window.TERM_DATA = {"meta":{"title":"名词手册","subjects":["生物化学","细胞生物学"],"count":1659,"updated":"2026-11-07","version":1},"groups":{"b":[{"id":"b01","name":"序论与水","part":"结构篇","count":28},{"id":"b02","name":"蛋白质化学","part":"结构篇","count":144},{"id":"b03","name":"酶学","part":"结构篇","count":30},{"id":"b04","name":"核酸化学","part":"结构篇","count":72},{"id":"b05","name":"糖与糖生物化学","part":"结构篇","count":43},{"id":"b06","name":"脂类和脂生物化学","part":"结构篇","count":37},{"id":"b07","name":"维生素与辅酶","part":"结构篇","count":34},{"id":"b08","name":"激素","part":"结构篇","count":36},{"id":"b09","name":"生物膜与运输","part":"结构篇","count":22},{"id":"b10","name":"代谢总论与生物氧化","part":"代谢篇","count":62},{"id":"b11","name":"糖代谢","part":"代谢篇","count":61},{"id":"b12","name":"脂类代谢","part":"代谢篇","count":48},{"id":"b13","name":"氨基酸代谢","part":"代谢篇","count":41},{"id":"b14","name":"核苷酸代谢","part":"代谢篇","count":33},{"id":"b15","name":"物质代谢的调节","part":"代谢篇","count":15}],"c":[{"id":"c01","name":"细胞与细胞生物学","part":"细胞生物学","count":34},{"id":"c02","name":"细胞膜与物质运输","part":"细胞生物学","count":29},{"id":"c03","name":"细胞膜与表面","part":"细胞生物学","count":57},{"id":"c04","name":"内膜系统与膜泡运输","part":"细胞生物学","count":103},{"id":"c05","name":"核糖体与非编码 RNA","part":"细胞生物学","count":41},{"id":"c06","name":"细胞核与染色体","part":"细胞生物学","count":88},{"id":"c07","name":"细胞骨架","part":"细胞生物学","count":65},{"id":"c08","name":"细胞周期与分裂","part":"细胞生物学","count":99},{"id":"c09","name":"细胞通讯与信号转导","part":"细胞生物学","count":77},{"id":"c10","name":"细胞连接与细胞外基质","part":"细胞生物学","count":24},{"id":"c11","name":"细胞分化与基因调控","part":"细胞生物学","count":63},{"id":"c12","name":"能量代谢","part":"细胞生物学","count":52},{"id":"c13","name":"衰老与凋亡","part":"细胞生物学","count":41},{"id":"c14","name":"癌细胞","part":"细胞生物学","count":49},{"id":"c15","name":"免疫","part":"细胞生物学","count":76},{"id":"c16","name":"研究技术与方法","part":"细胞生物学","count":48},{"id":"c17","name":"细胞质","part":"细胞生物学","count":7}]},"terms":[{"id":"ec37ac88","s":"b","g":"b01","n":"科学","e":"science","d":"属于人类对自然的认知体系。科学的英文 science 源于拉丁文 scio，后来演变为 scientia，本意是对自然的认识，表示“知识”“学问”；日本科学启蒙大师福泽谕吉把 science 译为“科学”（分科之学），1893年康有为引进并使用“科学”二字。综合苗力田“科学是目的不是手段”之说与罗素“确切的知识体系”之说，给出的定义是：科学就是确切的、系统的、分门别类的、理论性的知识体系。其内涵包括科学知识结构、科学过程与方法和科学本质。","src":"第1讲 生物化学序论"},{"id":"62054ad5","s":"b","g":"b01","n":"生命","e":"life","d":"属于生命物质最基本的属性，以三条给出生命的定义：自我复制（self-replication）、自我装配（self-assemble）和自我调节（self-regulation）。在此基础上，生命物质还表现出五个主要特征：高度复杂的化学复杂性与显微组织；代谢，即从环境中提取、转化和利用营养物质与能量；通过与周围环境相互作用获取能量和原料以适应环境；自我复制与自我组装；进化与多样性。这些特征使生命体区别于黏土、沙子、岩石、海水等无生命物质。","src":"第1讲 生物化学序论"},{"id":"5d866724","s":"b","g":"b01","n":"代谢","e":"metabolism","d":"属于生命物质的基本特征之一，指生命体从环境中提取、转化和利用营养物质与能量的一整套过程。它与高度复杂的化学复杂性、适应环境、自我复制与组装、进化与多样性并列为生命的主要特征。细胞和生命体依靠源源不断的能量供应，抵抗以最低能量状态衰减的趋势；分子通过不断的化学反应被合成和分解，因此需要持续向系统输入物质和能量。生物体是开放体系，与环境交换物质和能量，并通过两条策略获得能量：氧化从环境取得的化学燃料，或吸收太阳光能。","src":"第1讲 生物化学序论"},{"id":"473059c4","s":"b","g":"b01","n":"宇宙大爆炸","e":"Big Bang","d":"属于关于宇宙起源的一种学说，是依据天文观测研究后得到的一种设想。大约150亿年前，宇宙所有的物质都高度密集在一点，有着极高的温度，因而发生了巨大的爆炸；大爆炸以后，物质开始向外大膨胀，形成了今天看到的宇宙。爆炸后几秒钟内产生了最简单的元素氢和氦；宇宙膨大冷却后，物质在重力作用下浓缩形成星球，一些星球爆炸时释放能量，使较简单的原子核融合为更复杂的元素，经过数十亿年才形成今天的地球及地球上的化学元素。","src":"第1讲 生物化学序论"},{"id":"95c01a76","s":"b","g":"b01","n":"生命必需元素","e":"essential element","d":"属于构成生物体的化学元素中为生命活动所必需的部分。天然条件下地球上可找到90多种元素，多数科学家认为生命必需元素共有28种，包括氢、硼、碳、氮、氧、氟、钠、镁、硅、磷、硫、氯、钾、钙、钒、铬、锰、铁、钴、镍、铜、锌、砷、硒、溴、钼、锡和碘；其中硼只是某些绿色植物和藻类生长的必需元素，哺乳动物并不需要，因此人体必需元素实际为27种。按体内含量高低，这28种元素又分为宏量元素和微量元素。","src":"第1讲 生物化学序论"},{"id":"d535741f","s":"b","g":"b01","n":"宏量元素","e":"macroelement","d":"属于生命必需元素中按体内含量划分的一类，又称常量元素。宏量元素指含量占生物体总质量0.01%以上的元素，如氧、碳、氢、氮、磷、硫、氯、钾、钠、钙和镁。这11种元素在人体中的含量均在0.03%~62.5%之间，共占人体总质量的99.95%，是构成机体、参与生命活动的主要元素。与之相对，含量占生物体总质量0.01%以下的元素称为微量元素，二者共同构成人体必需元素的完整划分。","src":"第1讲 生物化学序论"},{"id":"c292500a","s":"b","g":"b01","n":"微量元素","e":"trace element","d":"属于生命必需元素中按体内含量划分的一类。微量元素指占生物体总质量0.01%以下的元素，如铁、硅、锌、铜、硒、溴、锡、锰等，合计约占人体总质量的0.05%左右。它们在体内的含量虽小，但在生命活动过程中的作用十分重要，通常是某些蛋白质包括酶发挥功能所必需的。以血红蛋白为例说明：血红蛋白分子输送氧的能力，绝对依赖于只占总质量0.3%的四个铁离子。","src":"第1讲 生物化学序论"},{"id":"15b9ad0e","s":"b","g":"b01","n":"功能基团","e":"functional group","d":"属于决定生物分子化学特性的基团。绝大多数生物分子可以看成是碳氢化合物的衍生物，碳氢化合物的骨架非常稳定，氢原子可以被各类功能基团取代，生成不同的有机化合物家族，典型的有醇、胺、醛和酮、羧酸等。多数生物分子是多功能的，含有两个或更多个不同的功能基团，每一种基团都有其自身的特点和反应。化合物的“个性、性质”，如肾上腺素或乙酰辅酶A，就是由其功能基团的性质和它们在三维空间中的位置决定的。","src":"第1讲 生物化学序论"},{"id":"61ebd93f","s":"b","g":"b01","n":"生物分子","e":"biomolecule","d":"属于构成生命有机体的有机化合物。生物分子可以理解为原子之间的结合类型（结合的形式和强度）、分子三维结构和化学活性，其中三维结构在生物化学中特别重要。几乎所有生命有机体的有机化合物形成后都是生物活性物质，是在生物进化中为适应特定功能被选择下来的。生物学作用如酶与底物、抗体与抗原、激素与受体的作用都是高特异性的，这种特异性靠分子之间的立体互补和静电互补实现，维持三维结构的作用力中最重要的是非共价作用。","src":"第1讲 生物化学序论"},{"id":"6002d48b","s":"b","g":"b01","n":"单体","e":"monomer","d":"属于构成生物大分子的小分子有机化合物，又称组分、残基。大多数有机体系统的分子由碳原子与其他碳原子或氢、氧、氮原子共价连接而成；有机化合物的分子量低于500，如氨基酸、核苷酸和单糖，是被称为大分子如蛋白质、核酸及多糖的单体。一个单个的蛋白质分子可能含有1000或更多个氨基酸残基，脱氧核糖核酸可能有数百万个核苷酸组成。有限的单体通过特殊的亚基序列及大分子的空间排列，形成大分子特别的生物学功能。","src":"第1讲 生物化学序论"},{"id":"4a6c3545","s":"b","g":"b01","n":"恒稳态","e":"steady state","d":"属于描述生物体分子组成动态平衡的概念，被称为动力学上的恒稳态。一个生物体的化学组成在整个时间内几乎是恒定的，但一个细胞或生物体内的分子群却远远不是恒稳态：分子通过不断的化学反应被合成和分解，需要不断地向系统输入物质和能量。例如血液中的血红蛋白是上个月合成的，下个月将被降解并由新的分子取代；血液中血红蛋白和葡萄糖的数量几乎是一个恒量，因为合成或摄入的速度与降解的速度达到平衡，浓度上的恒定是动力学恒态的结果。","src":"第1讲 生物化学序论"},{"id":"7a3bbc27","s":"b","g":"b01","n":"光合作用","e":"photosynthesis","d":"属于细胞利用太阳光能制造有机物的过程。几乎所有生命有机体都直接或间接地从太阳光的辐射能量获得能量，这种光能发生于太阳中的热核聚变反应；光合作用细胞吸收光能，用于驱动水分子中的电子到二氧化碳，生成能量丰富的产物如蔗糖和淀粉，并释放分子氧到大气中去。非光合作用细胞和有机体则氧化光合作用产生的能量丰富的物质以获得能量，并传递电子到大气氧，生成水、二氧化碳及其他终产物，在环境中被再循环。","src":"第1讲 生物化学序论"},{"id":"12fcd057","s":"b","g":"b01","n":"生物化学","e":"biochemistry","d":"属于研究生命现象的化学学科，被称为“生命的化学”。其定义是：研究生物体（微生物、植物、动物及人体等）的化学组成，生命物质的结构、功能、分离纯化及分析方法，生命过程中的物质、能量变化及代谢网络和调节，遗传物质的信息传递及调控的一门科学。研究内容包括生物体的物质组成与结构功能、这些物质在体内的代谢变化及调节、分子水平的结构与生物功能及生命现象之间的关系、遗传物质的信息传递及调控。1877年霍佩-赛勒首次提出“Biochemie”。","src":"第1讲 生物化学序论"},{"id":"2cbe021a","s":"b","g":"b01","n":"静态生物化学","e":"static biochemistry","d":"属于生物化学的两大组成部分之一，与动态生物化学相对。静态生物化学研究生物体的化学组成与性质。其内容涵盖从无机物到有机物、从小分子到各种生物大分子的化学组成；大多数生物物质由30种小分子前体物质构成，有人将这30种前体物质称为生物化学的字母表，其中包括20种氨基酸、5种碱基、2种单糖以及脂肪酸、甘油和胆碱等。与静态生物化学并列的还有动态、机能和工程生物化学。","src":"第1讲 生物化学序论"},{"id":"a63e8668","s":"b","g":"b01","n":"动态生物化学","e":"dynamic biochemistry","d":"属于生物化学的两大组成部分之一，与静态生物化学相对。动态生物化学研究机体内所进行的化学变化，以代谢途径为中心，研究物质在细胞内的变化规律及其伴随发生的能量变化。同化和异化作用过程的化学反应可分为氧化还原反应、基团转移反应、水解反应、裂解反应、异构反应和合成反应六类。自20世纪60年代以来，现代生化研究正逐渐揭示生物体代谢调节机制的秘密，其成果已对微生物育种和食品、发酵、环境等方面产生巨大影响。","src":"第1讲 生物化学序论"},{"id":"d87d6d20","s":"b","g":"b01","n":"脂类","e":"lipid","d":"属于生物化学中按溶解性质归并的一类化合物。生物化学中的脂类化合物，是泛指生物合成并能被生物体利用的所有溶于有机溶剂的化合物。其成员复杂，远远超出了有机化学中酯类的范围，却又不能包括有机化学中所有的酯类化合物。这类化合物的归类服从以生物功能为主线的原则，与维生素因在体内调节代谢、维持生命而同归一类的情形相似。类脂质中的磷脂是组建生物膜双层脂质的基本物质。","src":"第1讲 生物化学序论"},{"id":"9576fd89","s":"b","g":"b01","n":"米勒-尤里模拟实验","e":"Miller-Urey experiment","d":"属于模拟原始地球条件下生命起源化学进化的实验。一种模拟在原始地球还原性大气中进行雷鸣闪电能产生有机物（特别是氨基酸）的实验，用以论证生命起源的化学进化过程，1953年由芝加哥大学研究生Miller在其导师Urey指导下完成，故名。装置是完全密闭的气体环路，将甲烷、氨、氢气和水的蒸汽按比例注入以再现原始大气，再用紫外线持续照射并对混合气体放电，几天后在装置内的水溶液中检测到多种形式的氨基酸。","src":"第2讲 生命之母——水"},{"id":"c5d7ab88","s":"b","g":"b01","n":"有机汤","e":"organic soup","d":"属于生命起源化学演化过程中的一种水溶液体系。原始地球环境中火山充当了缩聚反应的催化剂，火山活动频繁能在局部地区形成高温缺氧的环境，简单的氨基酸类小分子能与地壳表面的水体作用，形成含有机化合物的水溶液，即“有机汤”。“有机汤”因高温蒸发而逐渐干涸，有机分子浓度不断增加，最终氨基酸通过缩聚反应形成多肽等高聚物，进入海洋，成为生命起源所必需的有机大分子，水在其中起到关键作用。","src":"第2讲 生命之母——水"},{"id":"19d9a87d","s":"b","g":"b01","n":"水的密度","e":"water density","d":"属于水的重要物理特性。水的密度在4℃时最大：高于4℃时热胀冷缩，低于4℃时冷胀热缩。其原因在于液态水除含简单水分子外还含缔合分子；水温降到0℃结成冰时，几乎全部分子缔合在一起成为一个巨大的缔合分子，冰中每个氧原子有四个氢原子为近邻（两个共价键、两个氢键），这种排布形成一种敞开结构，冰的结构中有较大空隙，所以冰的密度反比同温度的水小。","src":"第2讲 生命之母——水"},{"id":"fa8ed9e9","s":"b","g":"b01","n":"缔合分子","e":"associated molecule","d":"属于液态水和固态水中由氢键结合而成的水分子聚集形式。液态水除含有简单的水分子外，同时还含有缔合分子，最典型的两种是(H2O)2和(H2O)3；水温降到0℃结成冰时，水几乎全部分子缔合在一起成为一个巨大的缔合分子。缔合使水的熔点、沸点比同族氢化物高得多，也使冰形成敞开结构而密度小于水，因此缔合是水在常温常压下成为液态并表现反常物理性质的结构基础。","src":"第2讲 生命之母——水"},{"id":"2896feb5","s":"b","g":"b01","n":"氢键","e":"hydrogen bond","d":"属于由氢原子参加成键的一种特殊的化学键。氢键指在氢原子与电负性很大的原子X以共价键相结合时，同另外一个具有孤对电子的原子Y形成的一个弱的键。其生成主要由于偶极子与偶极子之间的静电吸引，可视为以氢离子为桥梁，写作A—H…B，A、B是氧、氮或氟等电负性大且原子半径小的原子。形成条件有二：与电负性大且半径小的原子相连的氢，以及附近有电负性大、半径小的原子。氢键结合能为2~8 kcal，比分子间作用力稍强、比共价键和离子键弱。","src":"第2讲 生命之母——水"},{"id":"5ce20128","s":"b","g":"b01","n":"水分子的极性","e":"polarity of water molecule","d":"属于水分子中电荷分布不均的现象。一个水分子由二个氢原子和一个氧原子构成，氧原子通过分别与两个氢原子各形成一对共用电子对的方式结合成稳定的分子；由于共用电子对明显靠近氧原子一侧，导致氧原子附近形成负电荷中心，氢原子附近形成正电荷中心，这种现象称为水分子的极性。水的几乎所有化学性质都与水分子的极性密切相关。水分子的HOH键角为104度，故水是极性分子，极性又导致物质分布的有序化。","src":"第2讲 生命之母——水"},{"id":"9e62433b","s":"b","g":"b01","n":"偶极矩","e":"dipole moment","d":"属于衡量分子极性大小的物理量。它是电荷与距离之积的矢量：共价键中成键电子对在电负性较强的原子周围出现的概率较大，正负电荷中心不重合，各带正q、负q的电荷，两中心相距l，则μ＝q×l为偶极矩。其中l为正负电荷中心的距离而非两成键原子之间的距离，q为两原子所带的净电荷。偶极矩越大，电子对偏移越厉害，键的极性越大，极大者为离子键；偶极矩是矢量，有大小和方向，氯气正负电荷中心重合，偶极矩为零，键无极性。","src":"第2讲 生命之母——水"},{"id":"ce046fd3","s":"b","g":"b01","n":"分子极性","e":"molecular polarity","d":"属于分子整体电荷分布的性质，键的极性并不等同于分子的极性。分子极性是由分子内各键的偶极矩的矢量和决定的：矢量和为零是非极性分子，不为零是极性分子，因此极性键构成的分子不一定是极性分子。例如CO2中C＝O为极性键，但两键偶极矩大小相等、方向相反，加和为零，分子无极性。水则是有极性的，因为其HOH键角为104度。分子极性决定了水作为溶剂的特性以及物质分布的有序化。","src":"第2讲 生命之母——水"},{"id":"5f6601e6","s":"b","g":"b01","n":"热力学第二定律","e":"second law of thermodynamics","d":"属于热力学的基本定律之一。它的表述是“在能量上这个世界趋向无序化”，而不是物质的分布的无序化，即该定律指的是能量层面的自发趋向，并不等于物质在空间分布上必然趋于无序。水分子的极性导致物质分布的有序化，极性水分子与非极性油滴共存时体系仍能形成有序的分布，这种有序化正是细胞膜形成的基础；有了水和油，也就有了细胞，脂质体与纳米颗粒即由此而来。","src":"第2讲 生命之母——水"},{"id":"4a916ae0","s":"b","g":"b01","n":"渗透压","e":"osmotic pressure","d":"属于水溶液中因溶解溶质而产生的压力。Π＝ρ·RT/M，其中Π为渗透压，ρ＝W/V为浓度，M为分子量，R为气体常数，T为温度；由公式可见，渗透压与浓度和温度成正比，与分子量成反比。由此可见说明“蜗牛上撒盐会出水”的道理：溶质浓度改变使水在体系之间重新分布。此外还据此区分等渗溶液、高渗溶液与低渗溶液三种情形，可见渗透压是描述溶液浓度效应、判断水在生物体内外流动方向的重要参数。","src":"第2讲 生命之母——水"},{"id":"a5d169ca","s":"b","g":"b01","n":"亨德森-哈塞尔巴尔赫方程","e":"Henderson-Hasselbalch equation","d":"属于化学中关于酸碱平衡的一个方程。该方程使用pKa（即酸解离常数）描述pH值的变化，可以用来估算缓冲体系的pH，其形式为pH＝pK＋log[质子受体]/[质子供体]，对应HA⇌A⁻＋H⁺的解离平衡。方程把溶液的pH、解离基团的pK值与该基团质子化与去质子化形式的浓度比联系起来，因此可用于计算弱酸弱碱溶液在给定pH下的解离百分数，也是判断缓冲区域的依据。","src":"第2讲 生命之母——水"},{"id":"302f8019","s":"b","g":"b01","n":"pH","e":"","d":"属于表示水溶液酸碱度的标度。pH的“p”表示“取负对数”的意思，来自德语（power的第一个字母），即pH＝-log[H⁺]＝log{1/[H⁺]}；因此可以有pOH、pNa、pCa等，任何情况下p必须小写。pH一定是对水溶液而言，因为只有在水溶液中才能测定pH。pH对生化反应（酶促反应）影响极大，并给出正确写法，如“50 mM Tris-HCl，pH 8.0”“将溶液pH调至8.0”。","src":"第2讲 生命之母——水"},{"id":"2170bc1f","s":"b","g":"b02","n":"蛋白质","e":"protein","d":"属于生物大分子，即由多种（20种）氨基酸按照一定的顺序、通过肽键连接形成的一条或多条肽链组成的生物大分子。蛋白质是生命活动的重要物质基础，没有蛋白质就没有生命；它是最丰富的生物大分子，存在于所有的细胞及细胞的所有部分，Protein一词来自希腊文“Proteios”，指“first”或“foremost”，意即“头等重要”“第一位的”“最重要的”。从古细菌到高级生命体，蛋白质都由相同的20种氨基酸共价连接而成。","src":"第3讲 蛋白质化学1"},{"id":"c604aae6","s":"b","g":"b02","n":"单纯蛋白","e":"simple protein","d":"属于按组成或理化性质划分的一类蛋白质（英国Physiological Society，1907），指只含氨基酸的蛋白质。共有七种：白（清）蛋白溶于水、盐、酸、碱溶液，加热凝固，见于血清；球蛋白溶于盐、酸、碱溶液，加热凝固；谷蛋白溶于酸、碱溶液，不溶于水和稀盐，见于谷种；醇溶谷蛋白溶于70-90%酒精、酸、碱溶液；硬蛋白不溶，见于毛、发、爪、皮肤；组蛋白溶于水、酸溶液，见于细胞核；鱼精蛋白溶于水、酸溶液，见于精子。","src":"第3讲 蛋白质化学1"},{"id":"62473c86","s":"b","g":"b02","n":"复合蛋白","e":"conjugated protein","d":"属于按组成或理化性质划分的一类蛋白质，又称结合蛋白质，指含有氨基酸以外其他成分的蛋白质。共有六种：核蛋白含戊糖或脱氧戊糖，见于细胞核；磷蛋白含有以酯的形式存在的磷酸，见于动物细胞和体液；脂蛋白含脂质；色蛋白含带Fe、Cu等的有机色素；糖蛋白含糖及其衍生物；金属蛋白与金属结合，后四类见于动植物细胞。这六类均以所含的非氨基酸成分为特征，与只含氨基酸的单纯蛋白相对。","src":"第3讲 蛋白质化学1"},{"id":"d12f04cf","s":"b","g":"b02","n":"球状蛋白质","e":"globular protein","d":"属于按分子形状划分的一类蛋白质，指分子较为对称、呈球形或椭球形的蛋白质，其溶解度较好，能结晶。大多数蛋白质属于球状蛋白质，如血红蛋白、肌红蛋白、酶和抗体等。与之相对，纤维状蛋白质分子对称性差、能够聚集为纤维状或细丝状，主要起结构蛋白作用，大多不溶于水。球状蛋白质因溶解度高、能结晶，易于制备和研究，是酶、运输蛋白与抗体等功能蛋白的主要存在形式。","src":"第3讲 蛋白质化学1"},{"id":"32585718","s":"b","g":"b02","n":"蛋白质的互补作用","e":"protein complementation","d":"属于营养学上提高蛋白质利用率的一种作用。完全蛋白质含有人体所必需的各种氨基酸，不完全蛋白质则缺乏人体所必需的某种氨基酸，如植物蛋白质与人体的差异较大，大豆缺甲硫氨酸、小麦缺赖氨酸、玉米缺色氨酸。将不同来源的蛋白质混合食用，可以互相弥补所缺的必需氨基酸，从而提高蛋白质生理价值，这种作用称为蛋白质的互补作用，是食物搭配与膳食调配的依据。","src":"第3讲 蛋白质化学1"},{"id":"460891e4","s":"b","g":"b02","n":"蛋白质系数","e":"protein factor","d":"属于由含氮量换算蛋白质含量的换算系数。各种蛋白质的含氮量很接近，平均为16%；不同蛋白质其氨基酸构成比例及方式不同，故含氮量也不同，一般蛋白质含氮量为16%，即一份氮素相当于6.25份蛋白质，此数值6.25称为蛋白质系数。蛋白质含量＝N含量×6.25，每克样品中含氮克数×6.25×100即为100克样品中蛋白质含量。不同食品的系数有所不同，如花生为5.46、大米为5.95、大豆为5.71、小麦粉为5.70、牛乳为6.38。","src":"第3讲 蛋白质化学1"},{"id":"6a931b1c","s":"b","g":"b02","n":"一级氨基酸","e":"primary amino acid","d":"属于生命体中合成蛋白质的原材料。蛋白质用强酸、强碱处理后可以得到多种氨基酸，在动植物组织中可以分离得到26-30种（以上）不同的氨基酸；第一个氨基酸早在两个世纪前就已经被发现，最后一个氨基酸在1935年才发现；直到1965年才搞清楚，只有20种氨基酸才是生命体中合成蛋白质的原材料，称为一级氨基酸。后来又有报道称存在第21种硒代半胱氨酸和第22种吡咯赖氨酸。","src":"第3讲 蛋白质化学1"},{"id":"156209b6","s":"b","g":"b02","n":"氨基酸","e":"amino acid","d":"属于蛋白质的基本组成材料。氨基酸以同一碳原子连接氨基、羧基、氢原子和侧链R基为基本结构，该碳原子称α碳原子，是不对称碳原子、手性碳原子；二十种氨基酸除Gly外全是L-型。氨基酸为无色晶体，熔点较高（200～300℃），水中溶解度各不相同，取决于侧链；除Cys-Cys、Tyr外一般溶于水，稀酸、稀碱中溶解最好；除Pro溶于乙醇、乙醚外，绝大多数氨基酸不溶于有机溶剂。","src":"第3讲 蛋白质化学1"},{"id":"91b81072","s":"b","g":"b02","n":"二硫键","e":"disulfide bond","d":"属于蛋白质中由两个半胱氨酸的巯基氧化形成的共价键，对蛋白质高级结构的形成十分重要。Cys的巯基易氧化形成二硫键，相应的氧化还原反应可使蛋白质分子中二硫键形成或断裂；半胱氨酸（Cysteine）与胱氨酸（Cystine）即因二硫键而相互转变，二硫苏糖醇（DTT）也可以用来打开胱氨酸上的二硫键。二硫键属于侧链基团的反应，是稳定肽链空间结构的重要共价交联。","src":"第3讲 蛋白质化学1"},{"id":"25f69527","s":"b","g":"b02","n":"L-型氨基酸","e":"L-amino acid","d":"属于氨基酸的绝对构型。按原子排列次序法确定了L型和D型氨基酸，但现在L和D已经不代表氨基酸的旋光性，只代表氨基酸的绝对构型；为正确表示左旋和右旋，采用（＋）和（－）符号，（＋）代表右旋，（－）代表左旋。从右旋的D型甘油醛出发可以合成出左旋的D型乳酸，说明物质的旋光性与手性原子上的构型没有确定的关系。“黄氏”判断法是：将H原子靠近自己，观察CAR的走向，逆时针为L型，顺时针为D型。","src":"第3讲 蛋白质化学1"},{"id":"ca206228","s":"b","g":"b02","n":"硒半胱氨酸","e":"selenocysteine","d":"属于第21个基本氨基酸（E.coli），密码子为UGA。硒代半胱氨酸由UGA无义密码子编码，有特殊的tRNA-Ser与其识别，Ser结合入肽链后立即修饰（硒代）为硒代半胱氨酸；其结构与半胱氨酸类似，只是其中的硫原子被硒取代。它存在于谷胱甘肽过氧化酶、甲状腺素5'-脱碘酶等酶分子中，包含硒半胱氨酸残基的蛋白都称为硒蛋白。UGA通常用作终止密码子，若mRNA中有硒半胱氨酸插入序列（SECIS），UGA就用作硒半胱氨酸的编码。","src":"第3讲 蛋白质化学1"},{"id":"1134e8e0","s":"b","g":"b02","n":"吡咯赖氨酸","e":"pyrrolysine","d":"属于目前已知的第22种参与蛋白质生物合成的氨基酸，在产甲烷菌的甲胺甲基转移酶中发现。它与标准氨基酸不同的是由终止密码子UAG的有义编码形成；与之对应，产甲烷菌中含有特异的吡咯赖氨酰-tRNA合成酶（PylRS）和吡咯赖氨酸tRNA（tRNAPyl），tRNAPyl具有不同于经典tRNA的特殊结构。产甲烷菌通过直接途径和间接途径生成吡咯赖氨酰-tRNA，还可能通过mRNA上的特殊结构控制UAG编码成为终止密码子或者吡咯赖氨酸。","src":"第3讲 蛋白质化学1"},{"id":"23cc5930","s":"b","g":"b02","n":"两性电解质","e":"ampholyte","d":"属于同一分子上既能带正电荷又能带负电荷的电解质。同一个氨基酸分子上可以同时解离携带正电荷和负电荷，被称为两性电解质。水溶液中，氨基酸的氨基和羧基在不同pH条件下表现出不同的解离状态；这种同时带有正、负电荷的离子称为两性离子，也称两极离子。氨基酸、多肽（蛋白质）、核苷酸、核酸等都属两性电解质，其解离状态随环境pH而改变，因而具有特征的滴定曲线和等电点。","src":"第3讲 蛋白质化学1"},{"id":"bfbf844f","s":"b","g":"b02","n":"范斯莱克定氮法","e":"Van Slyke method","d":"属于氨基酸α-氨基的化学反应所建立的一种定量方法。氨基酸与亚硝酸反应，标准条件下测定生成氮气的体积，可计算氨基酸的量，用于氨基酸定量和蛋白质水解程度的测定。使用时须注意：生成的N2只有一半来自氨基酸。该反应是范斯莱克法定量测定氨基酸的基本反应，与茚三酮反应、甲醛反应同属α-氨基参与的反应，可用于氨基酸定量及蛋白质水解程度的判断。","src":"第3讲 蛋白质化学1"},{"id":"cc9ec310","s":"b","g":"b02","n":"Sanger反应","e":"Sanger reaction","d":"属于鉴定多肽N-端氨基酸的重要方法，又称2,4-二硝基氟苯（DNFB、FDNB）法。2,4-二硝基氟苯在碱性（pH 8-9）条件下能够与肽链N-端的游离氨基作用，生成二硝基苯衍生物（DNP-氨基酸）；在酸性条件下水解，得到黄色DNP-氨基酸，该产物能够用乙醚抽提分离；不同的DNP-氨基酸可以用色谱法进行鉴定。由于只标记N端，该法可用于确定肽链的N-端残基，是蛋白质一级结构测定的经典手段之一。","src":"第3讲 蛋白质化学1"},{"id":"42e748ad","s":"b","g":"b02","n":"Edman降解法","e":"Edman degradation","d":"属于鉴定多肽N-端氨基酸并进行氨基酸顺序分析的重要方法，即异硫氰酸苯酯（PITC）法，实际上也是一种N-端分析法。此法的特点是能够不断重复循环，将肽链N-端氨基酸残基逐一进行标记和解离，生成PTH-氨基酸后经鉴定即可确定该位置的残基，从而逐个读出肽链的序列。由于可以循环操作，它比只标记末端的Sanger法更适于测定较长肽段的顺序，是蛋白质序列分析的基础方法。","src":"第3讲 蛋白质化学1"},{"id":"d614d575","s":"b","g":"b02","n":"丹磺酰氯法","e":"DNS-Cl method","d":"属于鉴定多肽N-端氨基酸的重要方法。在碱性条件下，丹磺酰氯（二甲氨基萘磺酰氯，DNS-Cl）可以与N-端氨基酸的游离氨基作用，得到丹磺酰-氨基酸（DNS-AA）。此方法的优点是丹磺酰-氨基酸有很强的荧光性质，检测灵敏度可以达到10⁻⁹ mol，因而适合微量样品的N-端分析。它与Sanger法、Edman法同属N-端测定方法，常用于蛋白质或多肽末端残基的鉴定。","src":"第3讲 蛋白质化学1"},{"id":"5df08b50","s":"b","g":"b02","n":"西佛碱","e":"Schiff base","d":"属于含碳氮双键的一类化合物，也称西弗碱或席夫碱。西佛碱是氮原子与碳原子以双键连结形成的一类化合物。氨基酸的主要化学反应分为氨基、羧基和侧链三类，生成西佛碱列在α-氨基参与的反应之中，与酰化、烃基化、脱氨基等反应并列；其用途是作为多种酶促反应的中间过程，说明氨基在酶催化中可作为亲核基团形成共价中间物。","src":"第3讲 蛋白质化学1"},{"id":"72ea35d2","s":"b","g":"b02","n":"Strecker降解","e":"Strecker degradation","d":"属于α-氨基酸的降解反应。α-氨基酸与α-二羰基化合物反应时，α-氨基酸氧化脱羧生成比原氨基酸少一个碳原子的醛，氨基与二羰基化合物结合并缩合成吡嗪；此外还可降解生成较小分子的双乙酰、乙酸、丙酮醛等。1862年Strecker发现四氧嘧啶能将Ala分解为乙醛和CO2，此反应称Strecker降解。不同α-氨基酸与还原糖加热能按Strecker降解生成各种特殊醛类，不仅与褐变有关，还与香气的产生有关。","src":"第3讲 蛋白质化学1"},{"id":"cec9a08c","s":"b","g":"b02","n":"兴奋性氨基酸","e":"excitatory amino acid","d":"属于中枢神经系统中的一类神经递质，即指具有2个羧基和1个氨基的酸性游离氨基酸，包括L-Asp、L-Glu及其人工合成的类似物，如红藻氨酸、N-甲基-D-天冬氨酸等。它们在中枢神经系统是兴奋性神经递质，可能起长程增强和兴奋性毒素的作用，尤其谷氨酸是中枢神经系统含量最高、分布最广、作用最强的兴奋性神经递质。在发育早期阶段呈神经营养作用，发育后期则为促毒性作用，过量的兴奋性氨基酸具有神经毒性。","src":"第3讲 蛋白质化学1"},{"id":"7ed263e4","s":"b","g":"b02","n":"抑制性氨基酸","e":"inhibitory amino acid","d":"属于中枢神经系统中抑制神经兴奋的一类氨基酸，即甘氨酸和γ-氨基丁酸（GABA）。大脑的正常功能依赖于兴奋性和抑制性之间的稳态平衡；在海马中γ-氨基丁酸系统是最主要的抑制性系统，包含了相位性和紧张性两种抑制作用，在神经元和神经网络的正常功能中发挥重要作用。此外，有证据显示牛磺酸也可能是脑内一种重要的抑制性神经递质或调质。","src":"第3讲 蛋白质化学1"},{"id":"347a3dd7","s":"b","g":"b02","n":"色谱法","e":"chromatography","d":"属于一种分离技术，由俄国植物学家Tsweett创立。原理是：使混合物（物理性质不同）中各组分在两相间进行不同的分配，一相是不动的（固定相），另一是流动的（流动相），后者带动混合物流过固定相，在同一推动力下，不同组分在固定相中滞留的时间不同，依次从固定相中流出，故又称色层法、层析法。按流动相分为气相色谱和液相色谱；按固定相分为柱色谱、纸色谱和薄层色谱；按层析性质分为吸附色谱、分配色谱、离子交换色谱和排阻色谱。","src":"第3讲 蛋白质化学1"},{"id":"4e3eabbf","s":"b","g":"b02","n":"分配层析","e":"partition chromatography","d":"属于根据物质在两种不相混合的相（溶剂）间分配差异来分离物质的方法，相当于一种连续液-液萃取法。在一定温度和压力下，物质同时溶解于两种互相接触但不相混合的溶剂中，其中一种溶剂吸附在支持物上作为固定相，另一种溶剂是可以流动的流动相；物质在两相中的浓度比值是一个常数，即分配系数。1941年Martin与Synge提出分配层析，其支持剂是纤维素、淀粉、硅胶等亲水性不溶性物质；分离的先决条件是各成分的分配系数有差异。","src":"第3讲 蛋白质化学1"},{"id":"d37dbc2f","s":"b","g":"b02","n":"分配系数","e":"partition coefficient","d":"属于描述溶质在两相间分配行为的参数。分配定律是：当一种溶质在两种一定的互不相溶的溶剂中分配时，在一定的温度下达到平衡后，溶质在两相中的浓度比值为一常数，即分配系数（Kd），Kd＝CA/CB（1891，Nernst），其中CA为在A相（动相）中的浓度，CB为在B相（静相）中的浓度。此外还定义了有效分配系数Keff＝某一物质在A相中的总量/某一物质在B相中的总量；对液-液层析系统，Keff＝Kd×Rv，Rv为两相体积比。","src":"第3讲 蛋白质化学1"},{"id":"647006e8","s":"b","g":"b02","n":"滤纸层析","e":"filter-paper chromatography","d":"属于分配层析的一种，以滤纸纤维素上吸附的水为固定相、展层用的溶剂为流动相，层析使混合氨基酸在两相中不断被分配，从而分配在滤纸的不同位置。滤纸层析是分离及鉴定简单氨基酸混合物的常用技术，可用于蛋白质氨基酸组成的定性鉴定及定量测定；还可以通过双向层析，利用不同的展层剂系统使在两向系统中不同Rf值的氨基酸分开，是测定蛋白质氨基酸组成的经典手段。","src":"第3讲 蛋白质化学1"},{"id":"d282bf0b","s":"b","g":"b02","n":"离子交换层析","e":"ion-exchange chromatography","d":"属于利用离子交换树脂作为柱层析支持物、将带有不同电荷及电量的物质进行分离的方法。离子交换树脂可分为阳离子交换树脂（如羧甲基纤维素等）和阴离子交换树脂（如二乙基氨基乙基纤维素等）；阳离子交换层析中，带正电荷多的物质与树脂结合较强，带正电荷少的结合较弱。用不同浓度的阳离子洗脱液如NaCl溶液进行梯度洗脱，通过Na⁺的离子交换作用可将带有不同正电荷的物质分离，带电荷量少、亲和力小的先被洗脱。","src":"第3讲 蛋白质化学1"},{"id":"ac2b4ad5","s":"b","g":"b02","n":"肽键","e":"peptide bond","d":"属于一个氨基酸的α-羧基与另一个氨基酸的α-氨基脱水缩合形成的酰胺键，是肽及蛋白质中最主要的共价键。1902年Hofmeister和Fischer提出肽键是蛋白质分子中氨基酸间的主要连接方式，即肽键理论。肽键的特点是氮原子上的孤对电子与羰基具有明显的共轭作用，组成肽键的6个原子处于同一平面；肽键中的C-N键具有部分双键性质，不能自由旋转，多数情况下以反式结构存在，一般C=N双键的键长为0.128 nm。","src":"第4讲 蛋白质化学2"},{"id":"77b52dbb","s":"b","g":"b02","n":"肽","e":"peptide","d":"属于氨基酸的多聚物，分子量大小差异极大，可以是2或3个到成千上万个氨基酸残基连接而成。两个氨基酸残基之间通过共价的肽键（酰胺键）连接形成一个二肽，三个氨基酸残基连接成三肽，有限数量的数十个氨基酸残基连接成寡肽，多个氨基酸残基则连接成多肽，蛋白质可以是数百到成千上万个氨基酸残基连接而成；多肽与蛋白质常被混用，但一般将分子量在10000以下的称为肽或多肽。","src":"第4讲 蛋白质化学2"},{"id":"e9366340","s":"b","g":"b02","n":"残基","e":"residue","d":"属于肽链中氨基酸的存在形式。氨基酸连接成肽链后，由于氨基酸之间通过一个氨基酸的氨基与另一个氨基酸的羧基缩合脱水，肽链上的一个氨基酸单位被称为残基。估算方法：用蛋白质的分子量除以110即为组成氨基酸的数目；20种氨基酸的平均分子量为138，考虑不同氨基酸出现的比例后平均为128，形成肽键时失去一分子水（18），故蛋白质分子中氨基酸残基的平均分子量为128-18＝110。","src":"第4讲 蛋白质化学2"},{"id":"250b8476","s":"b","g":"b02","n":"N端与C端","e":"N-terminus and C-terminus","d":"属于肽链两端的名称。氨基酸连接成肽链后，带有游离α-氨基的一端被称为氨基（末）端或N端，带有游离α-羧基的一端被称为羧基（末）端或C端。肽链上留下N端可解离的氨基、C端可解离的羧基以及侧链上能够解离的R基团，中间氨基酸的α-氨基和α-羧基由于形成肽键而不再对整个肽链的解离有贡献，因此肽也有特征滴定曲线及特征pI。N端、C端的测定是一级结构分析的步骤之一。","src":"第4讲 蛋白质化学2"},{"id":"3c002be5","s":"b","g":"b02","n":"催产素","e":"oxytocin","d":"属于一种小肽激素，为9肽，由垂体后叶制造，能刺激子宫收缩。一些脊椎动物的激素是小肽，它们发挥作用的浓度极低；催产素能引发分娩时的子宫收缩，刺激乳汁分泌，还能减少肾上腺酮等压力激素水平，降低血压。牛催产素的结构，说明自然存在的肽从2个到数千个氨基酸残基，肽的大小与其功能之间并不能作出相关性结论。催产素是自然存在的活性小肽，分子虽小却能在极低浓度下引起显著的生理效应。","src":"第4讲 蛋白质化学2"},{"id":"e2af04c1","s":"b","g":"b02","n":"鹅膏蕈碱 α-amanitin","e":"","d":"属于毒蘑菇鬼笔鹅蕈（Amanita phalloides）的真菌毒素，为双环的8肽，对动物有致死作用。它与许多抗生素一样属于极毒的毒蘑菇毒素，能与真核生物RNA聚合酶Ⅱ作用抑制转录；进一步说明它能抑制真核RNA聚合酶Ⅱ与RNA聚合酶Ⅲ的转录。这一作用说明，即使是分子很小的肽，也能在极低浓度下表现出重要的生物学作用，肽的大小与其功能之间并无简单的对应关系。","src":"第4讲 蛋白质化学2"},{"id":"1332709c","s":"b","g":"b02","n":"脑啡肽","e":"enkephalin","d":"属于神经递质的一种，即能改变神经元对经典神经递质的反应、起修饰经典神经递质作用的物质，又称神经调质，又被称为“脑内吗啡”。两种脑啡肽的序列：Met-脑啡肽为Tyr-Gly-Gly-Phe-Met，Leu-脑啡肽为Tyr-Gly-Gly-Phe-Leu，二者仅C端残基不同。它们与催产素、加压素等同属自然存在的活性小肽，说明肽的大小与其功能之间不能作出相关性结论。","src":"第4讲 蛋白质化学2"},{"id":"3375908e","s":"b","g":"b02","n":"加压素","e":"vasopressin","d":"属于一种小肽激素，又名抗利尿激素。加压素可调节细胞的进水量，增加肾中水的重吸收，并刺激血管收缩而增加血压；它与催产素同为脊椎动物的小肽激素，了牛加压素和牛催产素的结构。作为自然存在的活性肽之一，加压素在极低浓度下即可发挥作用；其作用集中于调节细胞的进水量、促进肾中水的重吸收与刺激血管收缩三个方面，可见小肽即可承担重要的激素功能。","src":"第4讲 蛋白质化学2"},{"id":"c67365a9","s":"b","g":"b02","n":"亚基","e":"subunit","d":"属于多亚基蛋白质中独立的多肽链。一些蛋白质只含有一条简单的多肽链，而另一些蛋白质成为多亚基蛋白质，含有两条或更多条非共价结合的多肽链；这些独立的多肽链可以是同一多肽链，也可以是不同的多肽链。如血红蛋白为四条非共价结合的多肽链，两条一致的α链和两条相同的β链。胰岛素的两条多肽链通过二硫键共价连接，这种情况下单条多肽链不是亚基，不构成多亚基结构（四级结构）。","src":"第4讲 蛋白质化学2"},{"id":"19feedf8","s":"b","g":"b02","n":"原体","e":"protomer","d":"属于多亚基蛋白质装配过程中的结构单位。有时不同的亚基形成小的寡聚体，并以此进一步装配，这种小的寡聚体被称为原体，原体再装配成更大的聚集体。如血红蛋白可称为四条多肽亚基的四聚体或者αβ原体的二聚体；天冬氨酸氨甲酰磷酸转移酶由6个调节亚基（R）和6个催化亚基（C）组成，装配时先由1个C亚基和1个R亚基组成一个原体CR，再由6个原体装配成一个有活性的酶。","src":"第4讲 蛋白质化学2"},{"id":"1faae07d","s":"b","g":"b02","n":"一级结构","e":"primary structure","d":"属于蛋白质结构的第一层次。1952年丹麦人Linderstrom-Lang最早提出蛋白质的结构可以分成四个层次，其中一级结构指氨基酸序列；1969年正式将一级结构定义为氨基酸序列和二硫键的位置。研究蛋白质的一级结构，就是要将氨基酸的排列顺序搞清楚。20世纪40年代起许多人从事一级结构研究，Sanger第一个将一个蛋白质（胰岛素）的所有氨基酸排列顺序通过高度的实验技巧加以确定，成为序列分析的典范。","src":"第4讲 蛋白质化学2"},{"id":"d693dde7","s":"b","g":"b02","n":"超二级结构","e":"supersecondary structure","d":"属于蛋白质结构中介于二级结构与三级结构之间的一个层次。Linderstrom-Lang于1952年提出蛋白质结构可分为一级、二级、三级、四级四个层次，介于二级结构和三级结构之间还存在超二级结构和结构域这两个层次；超二级结构即二级结构的组合，结构域则是在空间上相对独立的三维结构的实体。两个层次使α螺旋、β折叠等二级结构单元得以组合成较为稳定的局部实体，再进一步排布成三级结构。","src":"第4讲 蛋白质化学2"},{"id":"007b8004","s":"b","g":"b02","n":"二面角","e":"dihedral angle","d":"属于描述多肽主链构象的参数。两个肽键平面之间以一个Cα为中心，该α-碳原子可以作为一个旋转点形成二面角；绕Cα-N键轴旋转的二面角（C-N-Cα-C）称为φ，绕Cα-C键轴旋转的二面角（N-Cα-C-N）称为ψ，原则上φ和ψ可以取-180°~+180°之间的任一值。这样多肽链主链的各种可能构象都可用φ和ψ这两个二面角或扭角来描述，二面角的变化决定着多肽主链在三维空间的排布方式，是形成不同蛋白质构象的基础。","src":"第4讲 蛋白质化学2"},{"id":"ed059c7b","s":"b","g":"b02","n":"胰岛素","e":"insulin","d":"属于最小的蛋白质之一，由A链（21个氨基酸）和B链（30个氨基酸）组成，是胰腺β细胞分泌的一种激素，通过分泌和作用可以降低血糖。它是历史上第一个被确定氨基酸序列的肽（蛋白质），Sanger于1943—1953年确定了牛胰岛素的一级结构并于1958年获诺贝尔化学奖；1921年Banting和Best从胰腺中抽提出有活性的胰岛素，1980年Paul Berg在大肠杆菌中表达了人胰岛素，胰岛素因此成为第一个生化药物。","src":"第4讲 蛋白质化学2"},{"id":"431426d3","s":"b","g":"b02","n":"氨基酸分析仪","e":"amino acid analyzer","d":"属于进行氨基酸分离、衍生和检测的自动化分析系统，广泛用于制药、食品、饲料、农业、育种、医学研究、临床诊断和地质考察等领域。原理是：阳离子交换分离、柱后茚三酮衍生、可见光光度法测定。它使氨基酸组成分析实现自动化，是测定蛋白质氨基酸组成、进而计算每种氨基酸个数的基础设备，与Edman降解法、质谱法等共同构成蛋白质一级结构分析的技术体系。","src":"第4讲 蛋白质化学2"},{"id":"825afe3e","s":"b","g":"b02","n":"蛋白质的酸水解","e":"acid hydrolysis of protein","d":"属于蛋白质完全水解的常用方法。常用6 mol/L HCl或4 mol/L H2SO4在105-110℃条件下进行水解，反应时间约20小时。其优点是不容易引起水解产物的消旋化；缺点是Trp被沸酸完全破坏，含有羟基的氨基酸如Ser或Thr有一小部分被分解，Asn和Gln侧链的酰胺基被水解成了羧基。完全水解时每一种类型的蛋白质产生一种特征性的氨基酸比例或混合物，故酸水解是测定蛋白质氨基酸组成的前处理步骤。","src":"第4讲 蛋白质化学2"},{"id":"26f730ae","s":"b","g":"b02","n":"蛋白质的碱水解","e":"alkaline hydrolysis of protein","d":"属于蛋白质水解的一种方法。碱水解一般用5 mol/L NaOH煮沸10-20小时；由于水解过程中许多氨基酸都受到不同程度的破坏，产率不高，部分水解产物还会发生消旋化。该法的优点是Trp在水解中不受破坏。与酸水解相比，碱水解可使色氨酸免遭破坏，但氨基酸破坏较多且易消旋，因此在测定氨基酸组成时须根据待测氨基酸的种类选择水解方法。蛋白质的酶法水解则不会破坏氨基酸，也不会发生消旋化，产物为较小的肽段。","src":"第4讲 蛋白质化学2"},{"id":"965ed913","s":"b","g":"b02","n":"胰蛋白酶","e":"trypsin","d":"属于蛋白质肽链断裂所用的蛋白水解酶（内切酶）之一。胰蛋白酶专一性较强，水解速度快，其水解位点为Lys（K）和Arg（R）的C端羧基形成的肽键；当R2为Pro时水解受抑制。在蛋白质一级结构测定中，胰蛋白酶常被用来将多肽链断裂成若干肽段，供后续分离和序列分析；此外，内切酶中另有胰凝乳蛋白酶、胃蛋白酶、嗜热菌蛋白酶，外切酶则有羧肽酶和氨肽酶。","src":"第4讲 蛋白质化学2"},{"id":"ffd4a1ef","s":"b","g":"b02","n":"胃蛋白酶","e":"pepsin","d":"属于蛋白质肽链断裂所用的蛋白水解酶之一。胃蛋白酶在pH 2的条件下作用，对Phe（F）、Trp（W）、Tyr（Y）、Leu（L）及其他疏水性氨基酸的水解速度较快，R1为Pro时受抑制；其水解位点是芳香族氨基酸的N端氨基形成的肽键。在测定二硫键位置时选用胃蛋白酶，是因为其专一性较低、切点多、生成的含二硫键肽段较小便于分离，且酸性pH有利于防止二硫键发生交换。","src":"第4讲 蛋白质化学2"},{"id":"9dc8045e","s":"b","g":"b02","n":"胰凝乳蛋白酶","e":"chymotrypsin","d":"属于蛋白质肽链断裂所用的蛋白水解酶之一，又称糜蛋白酶。其水解位点是芳香族氨基酸的C端羧基形成的肽键，R1为Phe（F）、Trp（W）、Tyr（Y）等疏水性氨基酸，Leu、Met和His稍慢，作用pH为8-9。它与胰蛋白酶、胃蛋白酶、嗜热菌蛋白酶同属内切酶，专一性各有不同，在蛋白质一级结构测定中可根据需要选择，以获得长度和组成合适的肽段。","src":"第4讲 蛋白质化学2"},{"id":"a2101509","s":"b","g":"b02","n":"溴化氰裂解","e":"cyanogen bromide cleavage","d":"属于肽键专一性水解的化学法。化学法中用溴化氰（BrCN）断裂Met的C端肽键，生成高丝氨酸内酯；另有羟胺（NH2OH）较专一地断裂Asn-Gly之间的肽键，Asn-Leu及Asn-Ala键也能部分断裂，以及NTCB（2-硝基-5-硫氰苯甲酸）专一裂解Cys、产率大于90%。与酶法相比，化学断裂法位点明确，在蛋白质序列测定中常与酶解交替使用，以获得两套互相重叠的肽段。","src":"第4讲 蛋白质化学2"},{"id":"d403f4e6","s":"b","g":"b02","n":"对角线电泳","e":"diagonal electrophoresis","d":"属于确定蛋白质中二硫键位置的方法。一般用胃蛋白酶水解加对角线电泳法：将水解肽段点样在滤纸上，pH 6.5条件进行第一向电泳，肽段按大小及电荷不同被分离；然后将滤纸暴露在过甲酸蒸气中使二硫键断裂，含二硫键的肽段被氧化成一对含半胱氨磺酸的肽段；再将滤纸旋转90度，在与第一向完全相同的条件下进行第二向电泳。大多数肽段迁移率未变而位于对角线上，含半胱氨磺酸的成对肽段则偏离对角线，据此确定二硫键位置。","src":"第4讲 蛋白质化学2"},{"id":"d203eda2","s":"b","g":"b02","n":"质谱法","e":"mass spectrometry","d":"属于蛋白质序列测定的其他方法之一。质谱法可以在几分钟内测定短肽（20-30个氨基酸）的序列；其思路是经Edman循环后观察分子量的变化，或分离纯化蛋白质、酶切部分水解后分离短肽，再对短肽进行测序。此外，DNA快速测定方法的发展、遗传密码分析和基因分离技术可以从编码基因的核苷酸序列推测蛋白质的多肽序列，质谱法则在基因未获得时提供直接的序列信息。","src":"第4讲 蛋白质化学2"},{"id":"8d61c18c","s":"b","g":"b02","n":"固相肽合成","e":"solid-phase peptide synthesis","d":"属于肽的化学合成方法，1962年由R. Bruce Merrifield发明，给肽的化学合成带来了重要突破。该方法将氨基酸的一端固定在不溶性的聚合物（树脂）上，肽在这种支持物上合成，其合成方向与细胞内蛋白质的合成方向相反；试剂包括9-芴甲氧羰基、聚苯乙烯、二环己基碳化二亚胺。肽产品有从组织中分离纯化、基因工程生产和直接化学合成三种获得方式，固相合成即直接化学合成的主要形式。","src":"第4讲 蛋白质化学2"},{"id":"73628882","s":"b","g":"b02","n":"第二遗传密码","e":"Second genetic code","d":"又称折叠密码（folding code），属于关于一级结构决定空间结构规律的假说性概念。遗传信息从基因转变为有生物活性的功能蛋白质是通过两套密码介导的：一种是遗传密码，将核苷酸序列转变为多肽链的氨基酸顺序；另一种就是折叠密码即第二遗传密码，该密码决定存在于氨基酸顺序中的一维信息向蛋白质特定三维结构的转变。破译该密码的途径是蛋白质结构预测，即根据一级序列预测由Anfinsen原理决定的特定空间结构。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"d47ea44a","s":"b","g":"b02","n":"Chou-Fasman方法","e":"Chou-Fasman method","d":"属于预测蛋白质二级结构的经验方法，1970年由Peter Y. Chou和Gerald D. Fasman提出。该方法基于每个氨基酸在α-螺旋中的相对频率、测试表和通过X射线晶体学已知的蛋白质结构，用这些频率和概率参数判断某一氨基酸序列形成螺旋、折叠链或转角的概率。其确定正确二级结构的准确性约50%～60%，明显低于现代机器学习技术；并指出Glu、Met、Ala、Leu是α-螺旋最强的生成者，Gly、Pro是最强的破坏者。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"ce7edbda","s":"b","g":"b02","n":"天然蛋白质","e":"native protein","d":"属于蛋白质的一种存在状态，指处于功能及折叠状态构象的蛋白质。生理条件下蛋白质通常只呈现一个或几个主要构象状态，在特定条件下存在的构象是热力学上最稳定的构象，具有最低的自由能，处于功能及折叠状态构象的蛋白质即称为天然蛋白质。天然蛋白质是稳定的，生理条件下拆开折叠蛋白质为非折叠状态所需要的能量为20～65 kJ/mol，这一概念是讨论蛋白质变性与复性的基础。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"cee88cf6","s":"b","g":"b02","n":"疏水相互作用","e":"hydrophobic interaction","d":"属于维持蛋白质构象的非共价作用力，指蛋白质中的疏水基团彼此靠近、聚集以避开水的现象。其本质是水分子之间的相互作用比水与其他非极性分子的作用更强烈，非极性侧链避开水而聚集被压迫到蛋白质分子内部，大多数极性侧链则在蛋白质表面维持与水的接触。疏水相互作用在维持蛋白质构象（三级结构）中起主要作用，也是使蛋白质多肽链进行折叠的主要驱动力；尿素与盐酸胍可通过增溶疏水残基降低疏水相互作用。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"7d77895a","s":"b","g":"b02","n":"范德华力","e":"van der Waals force","d":"属于维持蛋白质构象的弱相互作用力。广义范德华力包括定向效应、诱导效应和分散效应，并包括吸引力和斥力两种相互作用，只有当两个非键合原子之间处于一定距离时才能达到最大。单个范德华力在4～30 kJ/mol量级，相对较弱，但由于其相互作用数量大并且具有加和性，因此是不可忽视的作用力，主要作用是稳定蛋白质中紧密堆积的基团和原子，在蛋白质中它与氢键、疏水作用等共同维持天然构象。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"559b958e","s":"b","g":"b02","n":"离子键","e":"ionic bond","d":"属于维持蛋白质构象的非共价作用力，指带有相反电荷的侧链之间的离子相互作用。离子化的侧链一般都出现在球蛋白表面，与水分子形成水化层，对球蛋白整体稳定性的贡献最小；荷电的侧链也可出现在蛋白质内部，一般与其他基团形成强氢键。离子键可稳定α-螺旋及三、四级结构，酸、碱可将其破坏；带电相反基团间形成的离子对即盐桥，也是稳定天然构象的贡献；它是维持蛋白质空间构象的作用力之一。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"d45712b6","s":"b","g":"b02","n":"X-射线晶体学","e":"X-ray crystallography","d":"属于利用X射线研究晶体中原子排列的学科，更准确地说，是利用电子对X射线的散射作用，获得晶体中电子密度的分布情况，再从中分析获得原子的位置信息即晶体结构。X射线波长范围为0.001～10 nm，与成键原子之间的距离（1～2 Å）可比；由于没有X射线透镜能聚焦X射线且单个分子衍射太弱，需借助含大量方位相同分子的晶体把衍射信号放大。该法至今仍是研究蛋白质高级结构的主要方法。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"31ea5fc4","s":"b","g":"b02","n":"核磁共振波谱学","e":"NMR spectroscopy","d":"属于在原子分辨水平测定蛋白质三维结构的方法之一。1985年Kurt以生物大分子中的质子为测量对象，连续测定所有相邻两个质子之间的距离和方位，数据经计算机处理形成生物大分子的三维结构图，奠定了NMR作为蛋白质结构研究方法重要手段的地位；现在NMR已成为生物大分子溶液三维结构研究的主要手段，可在近似生理环境下测定。缺点是只能测定MW 30000以下的蛋白质，且图谱分析极为费时。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"e29b232b","s":"b","g":"b02","n":"三维电镜重构","e":"3D electron microscopy reconstitution","d":"属于在原子分辨水平测定蛋白质三维结构的方法之一。其步骤为：利用快速冷冻技术对样品冷冻固定，利用冷冻电镜和低剂量成像技术作电子成像，用高灵敏底片记录，经高分辨率扫描仪数字化，再对数字化图像作二维图像分析——选点、分类、校正和平均，最后完成三维重构计算。已有数百种蛋白质由此获得结构。优势是可直接获得形貌信息、适于难结晶的膜蛋白与大分子复合体、适于捕捉动态结构变化。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"1b3a6587","s":"b","g":"b02","n":"肽键平面","e":"peptide bond plane","d":"属于肽链盘曲折叠的基本单位。肽键是一个刚性的平面结构，六个原子（-Cα—CO—NH—Cα-）基本上同处于一个平面，这就是肽键平面；肽链中能够旋转的只有α碳原子所形成的单键，此单键的旋转决定两个肽键平面的位置关系。由于共振，肽键的C=N键具有部分双键性质而不能自由旋转，肽链上重复出现的肽键平面即称为肽单位或肽基；肽键的C及N周围三个键角之和均为360°，相邻氨基酸残基的α-碳原子被3个共价键隔开。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"a36f8a90","s":"b","g":"b02","n":"二级结构","e":"secondary structure","d":"属于蛋白质结构层次之一，指多肽链中主链原子的局部空间排布即构象，不涉及侧链部分的构象。二级结构以一级结构为基础，多为短距离效应，主要化学键是氢键；Pauling等人对简单肽及氨基酸的酰胺作了X射线衍射分析，于1951年预测了蛋白质的二级结构。其类型包括α-螺旋、β-折叠、β-转角、无规则卷曲以及角蛋白、胶原的三股螺旋等；它与超二级结构、结构域、三级结构和四级结构共同构成蛋白质结构的层次。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"8f88b2f6","s":"b","g":"b02","n":"拉马钱德兰图","e":"Ramachandran plot","d":"属于以φ角和ψ角为坐标轴绘制的构象图。印度生物物理学家G. N. Ramachandran第一个计算出sterically allowed region，该图阐述蛋白质或肽立体结构中肽键内α碳原子与羰基碳原子间键的旋转度ψ对α碳原子与氮原子间键的旋转度φ所绘制，主要用来指明蛋白质或肽类允许和不允许的构象，不考虑能量问题。空间上可允许的区块以蓝色与黄色等高线显示，α-螺旋的数据多落在第三象限黄区，β-结构集中在第二象限黄区。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"256cae3d","s":"b","g":"b02","n":"α-螺旋 α-helix","e":"","d":"属于蛋白质中最常见、含量最丰富的二级结构，1950年由Pauling和Corey提出。多肽链主链围绕中心轴右手盘绕，每圈含3.6个氨基酸残基，螺距0.54 nm，每个残基绕轴旋转100°、沿轴上升0.15 nm，螺旋直径0.5 nm，残基的φ=-57°、ψ=-48°，R侧链伸向外侧。相邻螺圈间形成链内氢键，由肽键N-H的氢与其后面（N端）第4个氨基酸残基的C=O形成，氢键取向与中心轴几乎平行。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"93afb2a6","s":"b","g":"b02","n":"3.6₁₃螺旋","e":"3.6₁₃ helix","d":"即α-螺旋的规范表示，其中n=3。α-螺旋中第n个氨基酸的N-H与第n-4个氨基酸的C=O形成氢键，氢键封闭的环内主链上共包括13（3×3+4）个原子，故常用3.6₁₃-螺旋代表α-螺旋；其中3.6表示每圈螺旋含3.6个氨基酸残基（非整数螺旋），下角13表示氢键封闭的环内含13个主链原子。3₁₀-螺旋（n=2）与π螺旋（n=4）等其他螺旋形式。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"81ca4c04","s":"b","g":"b02","n":"3₁₀螺旋","e":"3₁₀ helix","d":"属于每圈含3个氨基酸残基的整数螺旋，n=2。其氢键所封闭的环内含10（3×2+4）个原子；当成对二面角取φ=-49°、ψ=-26°时形成该构象，每个肽基的C=O与其前面第2个肽基的N-H形成氢键构成10元环，每残基高度0.2 nm，螺距0.6 nm，螺旋直径约0.4 nm，比3.6₁₃-螺旋细长。它只存在于β-转角中，β转角相当于半圈3₁₀螺旋，Ⅲ型β-转角即第一与第三残基间的一小段3₁₀-螺旋。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"8b120fc4","s":"b","g":"b02","n":"π螺旋 π-helix","e":"","d":"也称4.4₁₆-螺旋，属于Pauling预测的三种螺旋之一，其中n=4。其残基高度0.12 nm，螺距0.52 nm，螺旋直径约0.6 nm，多为右手螺旋；肽链骨架上n位氨基酸残基的-C=O与n+5位残基的-NH之间形成氢键，氢键环有16个原子，每圈有4.4个氨基酸残基，每个残基环绕螺旋轴87°，二面角一般在（-55°，-70°）左右。π螺旋不稳定，在蛋白质中极少存在，仅在膜蛋白中可见。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"7aed2e2a","s":"b","g":"b02","n":"β-构象 β-conformation","e":"","d":"也称β-折叠、β-结构、β-折叠片，属于蛋白质中第二种最常见的二级结构。两条或多条几乎完全伸展的多肽链侧向聚集，相邻肽链主链上的-NH和C=O之间形成有规则的氢键，氢键与肽链长轴接近垂直；肽链平面之间折叠成锯齿状，相邻肽键平面呈110°角，R侧链伸出在锯齿上方或下方。平行β-片层残基间距0.65 nm，反平行0.7 nm，二面角为（-119°，+113°），计算中通常取每残基延伸0.36 nm。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"82db66ce","s":"b","g":"b02","n":"β-转角 β-turn","e":"","d":"又称回折、β-弯曲或发夹结构，属于球状蛋白质中的一种二级结构。它出现在肽链180°回折处，有三种类型（其中两种为主要），每个类型都有4个氨基酸残基，弯曲处第一个残基的C=O与第四个残基的NH之间形成一个4→1氢键，产生不很稳定的环形结构，连接α-螺旋或β-构象。Gly及Pro常出现在转角处；I型出现几率是II型的2倍多，II型总有Gly作为第三个残基。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"e4f09f39","s":"b","g":"b02","n":"β-凸起 β-bulge","e":"","d":"属于一种小片的非重复结构，能单独存在，但大多数作为反平行β-折叠片中的不规则情况存在。β-凸起可认为是β-折叠股中额外插入的一个残基，它使原来连续的氢键结构被打破，从而使肽链产生弯曲凸起，结果是在两个正常氢键之间凸起折叠股上是两个残基，而另一侧正常股上是一个残基。约5%的β-凸起出现在平行β-折叠中，它也能改变肽链走向，但没有β-转角那样明显；这类结构在β-折叠股中只涉及少数残基，属局部的规则性破坏。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"8c1cac55","s":"b","g":"b02","n":"无规则卷曲","e":"random coil","d":"也称卷曲，属于二级结构类型之一，泛指那些不能被归入明确二级结构如折叠片或螺旋的多肽区段。这些区段大多数既不是卷曲也不是完全无规则，存在少数柔性的无序片段；它们像其他二级结构那样是明确而稳定的结构，否则蛋白质不可能形成三维空间上每维都具周期性结构的晶体。它们受侧链相互作用影响很大，经常构成酶活性部位和其他特异功能部位，如EF手结构的中央环；其英文名为random coil，又称coil。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"b40ba829","s":"b","g":"b02","n":"EF手形结构","e":"EF-hand","d":"属于钙结合蛋白中结合Ca²⁺的特殊结构。与Ca²⁺结合的环状结构恰好位于两个α-螺旋之间，两个螺旋恰似伸开的拇指（F螺旋）和食指（E螺旋），故名。不同的EF手形蛋白具有2～8个不等的EF结构域，小清蛋白有3个EF结构，钙调素有4个EF区；小清蛋白pI 4.0～5.5、Mr 9～12 kD。EF手形模型很好地说明了钙结合蛋白的立体结构以及与Ca²⁺结合的特性。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"9c974b94","s":"b","g":"b02","n":"纤维状蛋白质","e":"fibrous protein","d":"属于动物体的基本支架和外保护成分，广泛分布于脊椎和无脊椎动物，占脊椎动物体内蛋白质总量的一半甚至更多。其分子是有规则的线性结构，与多肽链有规则的二级结构有关，而有规则的二级结构是其氨基酸顺序规则性的反映；纤维状蛋白质的基本结构单位是简单的重复的二级结构，为所存在的结构提供强度和/或弹性。所有纤维状蛋白质不溶于水，与其分子内部及表面含高浓度疏水性氨基酸残基有关。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"7b96e0ea","s":"b","g":"b02","n":"角蛋白","e":"keratin","d":"属于具有结缔和保护功能的纤维状结构蛋白，包括皮肤及其衍生物发、毛、鳞、羽、甲、蹄、角、爪、丝等。α-角蛋白中两股（或三股）右手α-螺旋向左缠绕拧成直径2 nm的原纤维，再排列成“9+2”电缆式结构、直径8 nm的微纤维，数百根微纤维结合成直径200 nm的大纤维；α-角蛋白几乎都呈α-螺旋，含大量半胱氨酸，每4个螺旋就有一个二硫键交联，保证纤维结构的稳定和强大刚性。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"ef67aada","s":"b","g":"b02","n":"胶原蛋白","e":"collagen","d":"也称胶原，属于动物骨、腱、软骨、皮肤的结构蛋白，有四种以上类型。胶原肽链富含Gly和Pro，Gly达总残基的1/3、Pro接近1/4，并含Hypro和Hylys，不含Trp和Cys，序列以Gly-Pro-Hypro三联交替排列；三条左手螺旋肽链拧成右手超螺旋，螺距8.6 nm，每股每圈30个残基，单股螺距0.95 nm、每圈3.3个残基、每残基沿轴0.29 nm。稳定三螺旋靠螺旋间范德华力、氢键和链间共价交联。","src":"第5讲 蛋白质化学3：二级结构"},{"id":"3c48e265","s":"b","g":"b02","n":"αα超二级结构 αα supersecondary structure","e":"","d":"属于超二级结构的基本形式之一，是由两股右手α-螺旋彼此缠绕而成的左手超螺旋，重复距离约140 Å。由于形成超螺旋，每圈螺旋为3.5个氨基酸残基（不是3.6），沿轴有一定的倾斜，重复距离从5.4缩短到5.1 Å；螺旋之间的相互作用由侧链装配控制，非极性侧链朝向超螺旋内部避开与水接触，稳定性主要由非极性侧链间的范德华力维持。它是α-角蛋白、肌球蛋白、原肌球蛋白和纤维蛋白原中的超二级结构。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"34fb7131","s":"b","g":"b02","n":"Rossmann折叠","e":"Rossmann fold","d":"属于βαβ型超二级结构中最常见的一种组合，即βαβαβ。最简单的βαβ组合由二段平行的β-链和一段连接链组成，连接链或是α-螺旋链或是无规则卷曲；而最常见的βαβ组合由三段平行的β-链和二段α-螺旋链构成，即Rossmann折叠。以磷酸丙糖异构酶（鸡肌肉）等为例说明β折叠在蛋白质中的不同形式，并指出理论上四条β折叠有12种组合，但实际出现的有限。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"6c07fbad","s":"b","g":"b02","n":"β-曲折 β-meander","e":"","d":"属于βββ组合的一种超二级结构，指相邻的3条或更多条反平行β-链通过紧凑的β-转角连接而成的结构。β-曲折与回形拓扑结构并列为βββ组合的两种超二级结构，并分别以红素氧还蛋白和人的前清蛋白为例图示其结构。这种由短β-转角把相邻反平行β-链连成一片的组合，属于拥有β-折叠片的蛋白质中常见的规则结构，多数情况下只有非极性残基侧链参与维持；其英文名为β-meander，又称β-曲折结构。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"c9f58995","s":"b","g":"b02","n":"回形拓扑结构","e":"Greek key topology","d":"又称希腊钥匙拓扑结构，属于反平行β-折叠片中常出现的一种超二级结构。这种结构直接用希腊陶瓷花瓶上的一种常见图案命名，故称“Greek key”拓扑结构；它有两种可能的回旋方向，实际上只存在一种，其基础还没有确定。以前清蛋白（人）为例展示该结构，并配以带希腊钥匙图案的双耳酒罐等图案说明其命名由来；它属于βββ组合，由反平行β-链与转角连接而成的片层组合。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"70cbcce3","s":"b","g":"b02","n":"结构域","e":"domain","d":"也称辖区或基元，属于蛋白质三级结构的局部折叠区，空间上相对独立，是进化过程中不同基因融合的结果。结构域是在二级结构或超二级结构基础上形成的三级结构局部折叠区，一条多肽链在这个域范围内来回折叠，相邻的域常被一个或两个多肽片段连接；通常由50～300个氨基酸残基组成，在三维空间可以明显区分和相对独立，并具有一定的生物学功能，如结合小分子。免疫球蛋白的12个结构域即其例。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"34014509","s":"b","g":"b02","n":"模体","e":"motif","d":"又称基序，属于结构域的亚单位，即二级结构有规律的组合，如螺旋-环-螺旋、β-折叠的组合、α-螺旋组合等。模体通常由2～3个二级结构单位组成，一般为α螺旋、β折叠和环（loop）；亮氨酸拉链、锌指结构都是典型的模体，它们执行一定的功能，既是结构单位又是功能单位，可直接作为结构域和三级结构的建筑块，某些蛋白质因子与DNA大沟结合的部位靠的就是特异的模体。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"16e4056a","s":"b","g":"b02","n":"三级结构","e":"tertiary structure","d":"属于蛋白质结构层次之一，指蛋白质的多肽链在各种二级结构的基础上再进一步盘曲或折叠形成的具有一定规律的三维空间结构，主要研究方法是X光衍射、核磁共振法及三维电镜重构。也有认为三级结构是指主链折叠盘曲形成构象的基础上，分子中各个侧链所形成的构象，侧链构象主要是形成微区即结构域；对球状蛋白质而言形成疏水区和亲水区，亲水区多在表面，疏水区多在内部并常形成“洞穴”或“口袋”，某些辅基镶嵌其中成为活性部位。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"5a4c325c","s":"b","g":"b02","n":"X-射线","e":"X-ray","d":"属于一种波长很短的电磁辐射，波长约为(20～0.06)×10⁻⁸ cm。伦琴射线具有很强的穿透本领，能透过许多对可见光不透明的物质，如墨纸、木料等；这种肉眼看不见的射线可以使很多固体材料发生可见的荧光，使照相底片感光以及空气电离，波长越短的X射线能量越大，称为硬X射线，波长长的能量较低，称为软X射线。X射线衍射即利用其与晶体中电子的作用研究物质结构。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"88be8a55","s":"b","g":"b02","n":"衍射","e":"diffraction","d":"属于X射线与晶体作用产生的现象，指原子在晶体中的周期性排列使得X射线散射在一些特定方向加强，而在其他方向减弱的现象。其产生原因是晶体中原子周期排列，散射波之间存在固定的位相关系并在空间产生干涉，其实质是大量原子散射波互相干涉的结果；散射是衍射的基础，而衍射则是晶体对X射线散射的一种特殊表现形式，并非X射线与物质相互作用的新现象；非晶体只在射线传播方向形成一个斑点，晶体则在中心斑点外围还有规律分布的其它斑点。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"0fdcaeaa","s":"b","g":"b02","n":"四级结构","e":"quaternary structure","d":"属于蛋白质结构层次的最高层次，指蛋白质分子中亚基的立体排布、亚基间的相互作用与接触部位的布局。单条多肽链组成的蛋白质分子没有四级结构；一般一条多肽链形成一个亚基，亚基可相同或不同，亚基单独存在无活性；维系四级结构的是氢键、盐键、范氏引力、疏水键等次级键。血红蛋白即四个亚基（两个α、两个β）占据四面体的四个角，每个亚基一个血红素辅基；α1β1界面间存在强相互作用，即使用尿素处理，得到的仍是完整的αβ二聚体。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"ca2d7c7e","s":"b","g":"b02","n":"别构效应","e":"allosteric effect","d":"又称变构效应，属于蛋白质构象改变导致功能改变的效应。当血红蛋白的一个α亚基与氧分子结合以后，可引起其他亚基的构象发生改变，对氧的亲和力增加，从而导致整个分子的氧结合力迅速增高，使血红蛋白的氧饱和曲线呈“S”形；这种由于蛋白质分子构象改变而导致蛋白质分子功能发生改变的现象称为别构效应。它是四级结构与功能关系的重要体现，别构蛋白一般都是寡聚蛋白质分子。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"9dae3874","s":"b","g":"b02","n":"折叠","e":"folding","d":"属于蛋白质形成立体结构的过程，指蛋白质从伸展的多肽链形成其特定立体结构的过程。维持其特定立体结构的作用力为氢键、疏水作用、范德华力、离子键和配位键；多数蛋白质被合成以后自己就能形成自由能最低的立体结构，蛋白质的天然立体结构一般是自由能最低的状态；有些蛋白质被合成后自己不能独立形成自由能最低的立体结构，需要分子伴侣使用ATP的能量帮助其完成折叠；该过程在细胞内可自发进行，也可由分子伴侣协助。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"a0402511","s":"b","g":"b02","n":"分子伴侣","e":"molecular chaperone","d":"属于协助新生肽折叠的一类蛋白质。有些蛋白质被合成以后自己不能独立形成自由能最低的立体结构，而需要一类蛋白质来催化，这类蛋白质称为分子伴侣；它们普遍存在于真核生物和原核生物中，一般使用ATP的能量帮助其他蛋白质形成自由能最低的立体结构，但不改变自己。此外，分子伴侣可识别肽链的非天然构象，促进各功能域和整体蛋白质的正确折叠；它不改变自己，只帮助其他蛋白质折叠。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"f80eef71","s":"b","g":"b02","n":"朊病毒","e":"prion","d":"也称传染性蛋白粒子、朊粒，属于一种不同于细菌、病毒或类病毒、在分类上尚未定论的病原因子。其本质为由正常宿主细胞基因编码的、构象异常的蛋白质，称为朊蛋白（PrP），目前尚未检出任何核酸成分，是人和动物传染性海绵状脑病（TSEs）的病原体。PrP^C三维结构具有42%的α-螺旋、3%的β折叠，对蛋白酶K敏感；PrP^SC的α-螺旋占30%、β折叠高达43%，对蛋白酶K有抗性。","src":"第6讲 蛋白质化学4：高级结构"},{"id":"33c846ac","s":"b","g":"b02","n":"分子病","e":"molecular disease","d":"属于蛋白质一级结构改变所致疾病的概念。蛋白质一级结构中参与功能活性部位的残基或处于特定构象关键部位的残基，即使整个分子中发生一个残基的异常，其结构和功能也会受到明显的影响；一些重要功能的蛋白质氨基酸序列改变可能引起疾病，人类很多分子病已查明是某种蛋白质缺乏或异常，这些缺损的蛋白质可能仅仅有一个氨基酸残基的异常。镰刀状红细胞性贫血病即574个残基中一个残基变异所致。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"772f4fbc","s":"b","g":"b02","n":"折叠酶","e":"foldase","d":"属于帮助细胞内新生肽链折叠的一类酶，催化与蛋白质折叠直接有关的反应。除一级结构、溶液环境外，大多数蛋白质的正确折叠还需要其他生物分子的帮助，这些参与新生肽折叠的分子一类是分子伴侣，另一类是折叠酶；折叠酶包括蛋白质二硫键异构酶（PDI）和肽酰（基）脯氨酰顺反异构酶（PPI），二者分别催化二硫键的形成、还原或重排以及肽基脯氨酰的顺反旋转体互变；折叠酶催化的是与蛋白质折叠直接有关的化学反应。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"b7329ff6","s":"b","g":"b02","n":"蛋白质二硫键异构酶","e":"protein disulfide isomerase","d":"属于折叠酶的一种，缩写PDI。它催化巯基与二硫键的交换反应，从而催化蛋白质二硫键的形成、还原（断裂）或重排（异构化）。它与肽酰脯氨酰顺反异构酶同属催化与蛋白质折叠直接有关反应的折叠酶，参与新生肽链在细胞内折叠为具有生物学功能的蛋白质的过程，是研究蛋白质折叠的重要对象；它与肽酰脯氨酰顺反异构酶同列为折叠酶，二者都催化与蛋白质折叠直接有关的反应。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"b0997fc7","s":"b","g":"b02","n":"肽酰脯氨酰顺反异构酶","e":"peptidyl prolyl cis/trans isomerase","d":"属于折叠酶的一种，缩写PPI。它在细胞中的基本作用是通过非共价键方式稳定扭曲的酰胺过渡态，而催化肽基脯氨酰的顺式与反式旋转体的相互转变。由于脯氨酸亚胺氮形成的肽键中有一部分为顺式构型，该酶所催化的顺反异构对含脯氨酸肽段的正确折叠具有重要意义。它与蛋白质二硫键异构酶并列为催化蛋白质折叠直接相关反应的折叠酶，二者所催化的反应都直接与新生肽链的折叠有关。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"fc2c563a","s":"b","g":"b02","n":"同源蛋白质","e":"homologous protein","d":"属于不同物种中行使相同或相似功能，或具有明显序列同源性的蛋白质。以细胞色素C为例指出，细胞色素C是真核细胞线粒体内的一种含Fe的蛋白质，在生物氧化中起传递电子的作用；通过数百种生物细胞色素C一级结构的研究表明，亲源关系越近，氨基酸顺序的同源性（相似性）越大；尽管不同生物间亲源关系差别很大，但与细胞色素C功能密切相关的氨基酸顺序却有共同之处，即保守顺序不变。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"6628ef44","s":"b","g":"b02","n":"T态与R态","e":"T state and R state","d":"属于血红蛋白的两种主要构象。T态（tense，紧张态）因更多的离子对作用而更为稳定，是去氧血红蛋白的主要构象，多数离子对存在于α1β2（及α2β1）界面间，其构象紧密、氧亲和力低；R态（relaxed，松弛态）构象松弛、氧亲和力高。氧可与两种状态结合，但对R态的亲和力更大；氧与T态的一个亚基结合引起构象改变为R态，αβ亚基对相互滑动和旋转，使β亚基间的口袋变窄。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"6ae01e00","s":"b","g":"b02","n":"别构蛋白","e":"allosteric protein","d":"属于具有别构部位的蛋白质。蛋白质分子中不止有一个配基的结合部位（活性部位），还有其他的配基结合部位（别构部位），这样的蛋白质即别构蛋白，别构蛋白都有别构效应；除活性部位外还有别构部位，有时活性部位和别构部位分属不同的亚基（活性亚基和调节亚基），活性部位之间以及活性部位与调节部位之间通过蛋白质构象的变化而相互作用。别构蛋白一般都是寡聚蛋白质分子；别构部位结合调节物后通过构象变化影响活性部位。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"943bdb8b","s":"b","g":"b02","n":"协同效应","e":"cooperative effect","d":"属于别构蛋白配基结合的特征。一种配基的结合促进后续配基的结合，称为正协同效应，表现为S型配体结合曲线；一种配基的结合抑制后续配基的结合，称为负协同效应；促进活性部位与配基结合的别构效应物为正效应物，抑制结合的为负效应物。血红蛋白的氧结合曲线呈S形，可看成反映低亲和与高亲和状态转变的杂合曲线，使其在肺和组织之间对氧浓度微小差异更为敏感；血红蛋白的氧结合即表现为正协同效应。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"cc71d3a5","s":"b","g":"b02","n":"氧亲和力","e":"oxygen affinity","d":"属于描述血红蛋白与氧结合性质的参数，指血红蛋白对于氧的结合牢固程度。在一定氧分压下，氧亲和力越高即氧结合越牢固；相反，氧亲和力越低，组织就能得到更多的氧供应。血红蛋白的氧亲和力受H⁺、CO₂等因素影响：肺部血液质子浓度低（pH 7.6）时亲和力高，保证高氧结合；组织血液质子浓度高（pH 7.2）时亲和力低，保证氧的释放；实验测定时使用pH 7.4；BPG也能降低Hb对氧的亲和力。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"d0849c49","s":"b","g":"b02","n":"波尔效应","e":"Bohr effect","d":"属于血红蛋白与O₂、H⁺和CO₂结合相互关系的经典效应，1904年由C. Bohr发现。高浓度的H⁺和CO₂可降低血红蛋白的氧亲和力，促使氧合血红蛋白分子释放O₂，而高浓度的O₂促使去氧血红蛋白分子释放H⁺和CO₂，血红蛋白对O₂、H⁺和CO₂结合的这种相互关系即波尔效应。其生理意义是：血液流经代谢旺盛组织时pH较低、CO₂较高，Hb释放O₂；流经肺时O₂升高，有利于Hb结合O₂并释放H⁺与CO₂。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"1887d315","s":"b","g":"b02","n":"主要组织相容性复合体","e":"major histocompatibility complex","d":"简称MHC，属于由一群紧密连锁的基因群组成的复合体。它定位于动物或人某对染色体的特定区域，呈高度多态性，其编码的分子表达于不同细胞表面，参与抗原递呈，制约细胞间相互识别及诱导免疫应答。早期从组织器官移植实验中发现，引起排斥反应的抗原称移植抗原或组织相容性抗原，此等抗原存在于细胞表面，无器官特异性，不同个体间抗原特异性互不相同，同卵双生及纯系动物个体间则完全一致。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"9851f6d1","s":"b","g":"b02","n":"人类白细胞抗原","e":"human leucocyte antigen","d":"简称HLA，属于人类MHC（HLA基因或HLA复合体）编码的分子，表达于白细胞上。HLA Ⅰ类分子顶部α1和α2区组成的抗原肽结合区呈沟槽状，α1和α2区各含4股β折叠片和1个α螺旋，β片层组成槽底、两侧由α螺旋组成；沟槽大小2.5 nm×1.0 nm×1.1 nm，可容纳8～12个氨基酸残基组成的短肽，沟槽内氨基酸变化大是Ⅰ类抗原多态性的基础；β2m无同种特异性，与α3功能区连接，有助于Ⅰ类抗原的表达和稳定性。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"70552553","s":"b","g":"b02","n":"组蛋白","e":"histones","d":"属于与DNA非特异性结合的碱性蛋白，带正电荷，含Arg、Lys。真核细胞中共有5种，分为两类：一类是高度保守的核心组蛋白，包括H2A、H2B、H3、H4四种；另一类是可变的连接组蛋白即H1。核心组蛋白高度保守，特别是H4，牛和豌豆H4的102个氨基酸中仅有2个不同；H1不仅具有属特异性，还有组织特异性，所以H1是多样性的。4种核心组蛋白通过C端疏水氨基酸相互结合。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"3609312f","s":"b","g":"b02","n":"核小体","e":"nucleosome","d":"属于染色质的基本结构单位。每个核小体单位包括约200 bp的DNA、1个组蛋白核心和1个H1；由H2A、H2B、H3、H4各两分子形成八聚体构成盘状核心颗粒，H3、H4形成四聚体位于颗粒中央，H2A、H2B二聚体分别位于两侧；DNA以左手螺旋缠绕在核心颗粒表面，每圈80 bp，共1.75圈约146 bp，两端被H1锁合，H1结合20 bp DNA；相邻核心颗粒之间为典型长度60 bp的连接DNA。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"2a01b273","s":"b","g":"b02","n":"非组蛋白","e":"non-histone proteins","d":"属于与染色体上特异DNA序列结合的蛋白质，又称序列特异性DNA结合蛋白。非组蛋白包括多种参与核酸代谢和修饰的酶类、核质蛋白、骨架蛋白、基因表达和染色体结构调节蛋白等；其特性为含较多Asp和Glu、属酸性蛋白质，整个细胞周期都进行合成（不像组蛋白只在S期合成并与DNA复制同步），能识别特异的DNA序列，识别信息存在于DNA本身、位点在大沟部分，靠氢键和离子键结合，并具有多样性和异质性。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"7fdd23f8","s":"b","g":"b02","n":"凝胶阻滞实验","e":"gel retardation assay","d":"又称电泳迁移率变动实验（EMSA），属于体外研究DNA与蛋白质相互作用的特殊凝胶电泳技术。凝胶电泳中裸露的DNA朝正电极移动的距离与其分子量的对数成反比；如果DNA分子与某种蛋白质结合，由于分子量增大，其在凝胶中的迁移作用便受到阻滞，在特定电压和时间内朝正电极移动的距离相应缩短。加入超量竞争DNA时阻滞条带消失，该法可用于研究序列特异性DNA结合蛋白。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"7c4794f1","s":"b","g":"b02","n":"螺旋-转角-螺旋","e":"helix-turn-helix","d":"简称HTH，属于序列特异性DNA结合蛋白的结构模式之一。蛋白质形成对称的同型二聚体，每个单位由20个氨基酸的小肽组成，两个α螺旋相互连接成β转角；羧基端的α螺旋负责识别DNA大沟的特异碱基信息，另一个螺旋与磷酸戊糖链骨架接触。HTH最初发现于λ噬菌体的阻遏蛋白中，现发现在很多原核及真核DNA结合蛋白中存在，由两个较短的α螺旋与其间含Gly残基的绞链组成。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"17921a51","s":"b","g":"b02","n":"锌指结构","e":"zinc finger","d":"属于序列特异性DNA结合蛋白的一种结构模式，也是典型的模体。每个锌指单位是一个DNA结合结构域，由30个左右氨基酸残基组成，其中一对Cys和/或一对His与Zn²⁺形成配位键，锌指的C端形成α螺旋负责与DNA结合；锌指区域由4个Cys或2个Cys及2个His组成，保守序列为Cys-N2-4-Cys-N12-14-His-N3-His；锌指蛋白有2～13个手指，各由23个氨基酸组成，指部伸入DNA大沟接触5个核苷酸。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"09a94078","s":"b","g":"b02","n":"亮氨酸拉链","e":"leucine zipper","d":"属于序列特异性DNA结合蛋白的一种结构模式。蛋白质肽链的羧基端约35个氨基酸残基有形成α螺旋的特点，每两圈（7个氨基酸残基）有一个Leu残基，α螺旋一侧的Leu排成一列，两个α螺旋间靠Leu间的疏水作用力形成一条拉链状结构；该结构具有35个氨基酸残基、其中有4个亮氨酸，二聚体另一端的肽段富含碱性氨基酸，借其正电荷与DNA双螺旋链上带负电荷的磷酸基团结合。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"a0d52236","s":"b","g":"b02","n":"蛋白质组","e":"proteome","d":"属于对应于基因组的所有蛋白质构成的整体，不是局限于一个或几个蛋白质。蛋白质组是澳大利亚学者Williams和Wilkins于1994年首先提出；同一基因组在不同细胞、不同组织中的表达情况各不相同，在空间和时间上是动态变化着的整体。通俗表述：一个细胞或一个基因组所表达的全部蛋白质。1996年澳大利亚建立了世界上第一个蛋白质组研究中心，1997年召开了第一次国际蛋白质组学会议。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"ea013a76","s":"b","g":"b02","n":"蛋白质组学","e":"proteomics","d":"属于应用各种技术手段来研究蛋白质组的一门新兴科学。其目的是从整体的角度分析细胞内动态变化的蛋白质组成成份、表达水平与修饰状态，了解蛋白质之间的相互作用与联系，揭示蛋白质功能与细胞生命活动规律。重要技术包括双向（凝胶）电泳（2-DE）、以质谱为代表的蛋白质鉴定技术、多维色谱技术（LC/LC-MS/MS）、肽质量指纹图（PMF）和数据库搜寻以及生物信息学分析。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"4cf63f31","s":"b","g":"b02","n":"质谱分析法","e":"mass spectrometry","d":"属于通过对被测样品离子的质荷比的测定来进行分析的一种分析方法。被分析的样品首先要离子化，然后利用不同离子在电场或磁场中运动行为的不同，把离子按质荷比（m/z）分开而得到质谱，通过样品的质谱和相关信息可得到样品的定性和定量结果。质谱是分子离子及碎片离子的质量与其相对强度的谱，谱图与分子结构有关；它是唯一可以给出分子量、确定分子式的方法，灵敏度可达10⁻¹⁸ mol/L。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"e82e324a","s":"b","g":"b02","n":"基质辅助激光解吸电离","e":"matrix-assisted laser desorption ionization","d":"简称MALDI，属于质谱的离子化方法之一。MALDI可使热敏感或不挥发的化合物由固相直接得到离子：待测物质的溶液与基质的溶液混合后蒸发，使分析物与基质成为晶体或半晶体，用一定波长的脉冲式激光照射时，基质分子能有效地吸收激光的能量，使基质分子和样品分子进入气相并得到电离；适用于肽类、核酸类等生物大分子，可得到分子离子峰而无明显碎片峰，特别适合于飞行时间质谱仪。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"37d0142d","s":"b","g":"b02","n":"蛋白质芯片","e":"protein chip","d":"属于生物芯片的一种，也称蛋白质微点阵。生物芯片是指包被在固相载体上的高密度DNA、抗原、抗体、细胞或组织的微点阵，包括DNA芯片、抗原芯片、抗体芯片、细胞芯片、组织芯片等；蛋白质芯片的基本原理是将高度密集排列的蛋白质分子作为探针点阵固定在固相支持物上，当与待测蛋白样品反应时可捕获样品中的靶蛋白，再经检测系统对靶蛋白进行定性和定量分析，依据抗原-抗体反应、配体-受体反应等原理。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"79c4e574","s":"b","g":"b02","n":"酵母双杂交技术","e":"yeast two-hybrid system","d":"属于利用酵母遗传学方法分析蛋白质之间相互作用的技术，由Fields等1989年提出，基于对酵母转录因子GAL4的研究。GAL4包括两个彼此分离但功能必需的结构域：N端1～174位残基区段的DNA结合域（DNA-BD）和C端768～881位区段的转录激活域（AD）；DNA-BD识别上游激活序列UAS并与之结合，AD通过与转录机构其他成分结合启动下游基因转录；二者单独不能激活转录，空间上充分接近时则呈现完整的GAL4活性。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"eed5be06","s":"b","g":"b02","n":"噬菌体展示","e":"phage display","d":"属于将外源肽或蛋白质的基因与噬菌体特定蛋白质的基因在其表面进行融合表达的新技术。将编码多肽的外源DNA片段与噬菌体表面蛋白的编码基因融合后，以融合蛋白的形式呈现在噬菌体表面，被展示的多肽或蛋白可保持相对的空间结构和生物活性；导入了各种各样外源基因的一群噬菌体就构成展示各种外源肽的噬菌体展示库，用一个蛋白质去筛查展示库时，就会选择性地与有相互作用的某个外源肽结合，从而分离出特定的噬菌体。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"ffaf44da","s":"b","g":"b02","n":"表面等离子共振","e":"surface plasmon resonance","d":"简称SPR，属于一种光学现象，可被用来实时跟踪在天然状态下生物分子间的相互作用，对生物分子无任何损伤且不需任何标记物。当入射光以临界角入射到两种不同透明介质界面时，可引起金属自由电子的共振，电子吸收光能量使反射光在一定角度内大大减弱，其中使反射光完全消失的入射光角度称为共振角；共振角随金属表面折射率变化，而折射率变化又与结合在金属表面的生物分子质量成正比。","src":"第7讲 蛋白质化学5：结构与功能及研究方法"},{"id":"1889a515","s":"b","g":"b02","n":"透析","e":"dialysis","d":"属于利用半透膜分离大分子与小分子的方法，即用半透膜（透析袋）将大分子蛋白质分离出来。蛋白质分子量大、扩散速度慢、不易透过半透膜，将混有小分子杂质的蛋白质溶液置于透析袋内、浮于流动水或适宜缓冲液中，小分子杂质易从袋中透出而保留了较纯的蛋白质；小于MWCO的分子在浓度差产生的扩散压作用下渗过透析膜，速度与浓度梯度、膜面积及温度成正比。常用于除盐、除有机溶剂和浓缩样品。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"f05bd1f0","s":"b","g":"b02","n":"半透膜","e":"semipermeable membrane","d":"属于只允许一些分子或离子扩散进出的薄膜，是对不同粒子的通过具有选择性的薄膜，例如细胞膜、膀胱膜、羊皮纸以及人工制的胶棉薄膜等，不同类型的半透膜孔径不同。半透膜在化学中只允许溶液通过，胶体和悬浊液均不能通过；反渗透设备所用半透膜只允许水分子透过而不允许溶质通过，用高压泵使原水压力超过渗透压即可获得纯净水。它是透析和超滤技术的基础；透析即利用半透膜将大分子蛋白质与小分子杂质分开。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"5e87750e","s":"b","g":"b02","n":"沉降系数","e":"sedimentation coefficient","d":"属于描述蛋白质在离心场中沉降行为的参数。蛋白质大分子在溶液中离心时可发生沉降，沉降速度与向心加速度之比值即为蛋白质的沉降系数S，即s=v/ω²r，其中ω为离心转子的角速度、r为到旋转中心的距离、v为沉降速度；其数值以每单位重力的沉降时间表示，10⁻¹³这个因子叫做沉降单位S（斯维德贝里单位），1S=10⁻¹³秒。大多数蛋白质和核酸的沉降系数在4S和40S之间，核糖体及其亚基在30S和80S之间，多核糖体在100S以上。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"5e50fffa","s":"b","g":"b02","n":"等电点","e":"isoelectric point","d":"属于蛋白质的重要理化参数。蛋白质由氨基酸组成，分子中除两端游离氨基和羧基外，侧链上还有一些解离基团，如Glu、Asp的γ和β-羧基、Lys的ε-氨基、Arg的胍基和His的咪唑基；蛋白质颗粒所带电荷既取决于其酸性与碱性氨基酸的含量，又受所处溶液pH影响。当处于某一pH时蛋白质兼性离子的净电荷为0，此时溶液的pH值即蛋白质的等电点（pI）；pH大于pI时带负电荷向阳极移动，pH小于pI时带正电荷向阴极移动。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"94df4e69","s":"b","g":"b02","n":"蛋白质变性","e":"denaturation","d":"属于蛋白质空间结构被破坏而生物学活性丧失的作用。天然蛋白质的严密结构在某些物理或化学因素作用下，其特定空间结构被破坏，从而导致理化性质改变和生物学活性的丧失，如酶失去催化活力、激素丧失活性，即蛋白质的变性作用；一般认为变性的本质是次级键、二硫键的破坏，并不涉及一级结构的变化。变性后多肽链松弛伸展、粘度增大，疏水基团暴露使溶解度下降，易被酶水解，紫外吸收可能增加。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"ce1a788d","s":"b","g":"b02","n":"复性","e":"renaturation","d":"属于变性的可逆变化。变性并非完全是不可逆的变化，当变性程度较轻时，去除变性因素，有的蛋白质仍能恢复或部分恢复其原来的构象及功能，变性的可逆变化称为复性。例如核糖核酸酶的四对二硫键及其氢键在β-巯基乙醇和8 M尿素作用下发生变性失活，经透析去除尿素与β-巯基乙醇并对空气缓慢氧化使巯基氧化成二硫键后，酶又可恢复原来的构象，酶活性几乎全部恢复；变性严重时则不能恢复，称不可逆性变性。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"9d937e3e","s":"b","g":"b02","n":"盐析","e":"salting out","d":"属于利用溶解度差别沉淀蛋白质的方法。在蛋白质溶液中加入大量的中性盐以破坏蛋白质胶体的稳定性而使其析出即盐析，常用的中性盐有硫酸铵、硫酸钠、氯化钠等；各种蛋白质盐析时所需的盐浓度及pH不同，故可用于对混合蛋白质组分的分离。例如用半饱和的硫酸铵沉淀出血清中的球蛋白，饱和硫酸铵可使白蛋白、球蛋白都沉淀；盐析沉淀的蛋白质经透析除盐仍保持活性，调节pH至等电点后盐析效果更好。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"0ec58da4","s":"b","g":"b02","n":"蛋白质沉淀","e":"protein precipitation","d":"属于蛋白质分子凝聚从溶液中析出的现象。蛋白质所形成的亲水胶体颗粒具有两种稳定因素，即颗粒表面的水化层和电荷，若无外加条件不致互相凝集；除掉这两个稳定因素（如调节pH至pI和加入脱水剂），蛋白质便容易凝集析出。若仅调pH至pI，同性电荷的排斥消失但水化膜仍起保护作用，一般不致凝聚，此时再加入脱水剂除去水化膜即可沉淀；变性蛋白质一般易于沉淀，但也可不变性而使蛋白质沉淀。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"b07cdaca","s":"b","g":"b02","n":"不可逆沉淀","e":"irreversible precipitation","d":"属于沉淀蛋白质的一种类型，指沉淀出来的蛋白质分子其内部结构发生了较大的改变，蛋白质已失去了原来的生物活性，即使沉淀因素消失，沉淀也不重新溶解。在蛋白质溶液中加入丙酮、乙醇等水溶性有机溶剂，因其与水的亲和力大于蛋白质，破坏了蛋白质胶体外层的水化膜并可逐步进入蛋白质内部而有利于沉淀；此种作用在短时间及低温时沉淀是可逆的，但作用时间长或温度较高时则是不可逆沉淀。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"d4ac5b21","s":"b","g":"b02","n":"加热凝固","e":"coagulation","d":"属于使蛋白质凝固而沉淀的方法。将接近于等电点附近的蛋白质溶液加热，可使蛋白质发生凝固而沉淀；加热首先使蛋白质变性，有规则的肽链结构被打开呈松散状不规则的结构，分子的不对称性增加，疏水基团暴露，进而凝聚成凝胶状的蛋白块，如煮熟的鸡蛋，蛋黄和蛋清都凝固。变性、沉淀、凝固关系密切：变性蛋白质只在等电点附近才沉淀，沉淀的变性蛋白质也不一定凝固；变性、沉淀与凝固是三个相关而不同的概念。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"426773af","s":"b","g":"b02","n":"蛋白质紫外吸收","e":"ultraviolet absorption","d":"属于蛋白质的理化性质之一，可用于蛋白质的定性和定量测定。蛋白质在280 nm处有吸收，波长范围为200～400 nm，引起紫外吸收的因素主要是色氨酸（Trp）和酪氨酸（Tyr）的共轭双键，Phe在紫外光区也有光吸收。通常以浓度1 mg蛋白质/ml溶液的A280为1.0进行估算，可按蛋白质浓度(mg/ml)=1.45A280−0.74A260计算；肽键在200～250 nm也有强吸收，可用0.144(A215−A225)测定。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"ba624a24","s":"b","g":"b02","n":"双缩脲反应","e":"biuret reaction","d":"属于蛋白质的常用颜色反应之一，也可用于蛋白质的定量测定。蛋白质在碱性溶液中与硫酸铜作用呈现紫红色即双缩脲反应；凡分子中含有两个以上-CO-NH-键的化合物都呈此反应，蛋白质分子中氨基酸以肽键相连，因此所有蛋白质都能与双缩脲试剂发生反应。定量时蛋白质与Cu²⁺形成紫红色络合物，颜色深浅与蛋白质浓度成正比，而与蛋白质的分子量及氨基酸成分无关，可在540～560 nm比色测定。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"eb4aee7f","s":"b","g":"b02","n":"茚三酮反应","e":"ninhydrin reaction","d":"属于蛋白质的颜色反应之一。α-氨基酸与水合茚三酮（苯丙环三酮戊烃）作用时，产生蓝（紫）色反应；由于蛋白质是由许多α-氨基酸组成的，所以也呈此颜色反应。该反应是氨基酸定性与定量分析的经典显色反应，在蛋白质化学中常用于检测蛋白质水解产物中的氨基酸。其与双缩脲反应、米伦反应、黄蛋白反应等并列为蛋白质常用的颜色反应，可用于蛋白质的定性鉴定；凡含α-氨基的氨基酸均呈此反应，蛋白质由α-氨基酸组成，故亦然。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"6e18191b","s":"b","g":"b02","n":"凯氏定氮法","e":"Kjeldahl method","d":"属于蛋白质定量测定方法，1833年由Kjeldahl提出，现已发展为常量、微量、自动定氮仪法、半微量法及改良凯氏法。蛋白质的含氮量一般为15%～17%，通常取值16%，测出总氮后乘以6.25即为蛋白质含量；原理是样品与浓硫酸和催化剂一同加热消化，使蛋白质分解，有机氮转化为氨并与硫酸结合成硫酸铵，加碱蒸馏使氨蒸出，整个过程分为消化、蒸馏、吸收与滴定，根据标准酸消耗量计算蛋白质含量。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"b478c306","s":"b","g":"b02","n":"Folin-酚法","e":"Folin-phenol method","d":"又称改良Lowry法，属于蛋白质定量测定方法。该法包括两步反应：第一步是在碱性条件下蛋白质与铜作用生成蛋白质-铜络合物；第二步是此络合物将磷钼酸-磷钨酸试剂（Folin-酚试剂）还原，产生深蓝色（磷钼蓝和磷钨蓝混合物），颜色深浅与蛋白质含量成正比。此法操作简便，灵敏度比双缩脲法高100倍，定量范围为5～100 μg蛋白质；显色由酪氨酸、色氨酸和半胱氨酸引起，样品含酚类、柠檬酸和巯基化合物均有干扰。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"e5d13b4c","s":"b","g":"b02","n":"BCA法","e":"bicinchoninic acid assay","d":"属于蛋白质定量测定方法。碱性溶液中蛋白质将二价铜（Cu²⁺）还原成一价铜（Cu⁺），后者与测定试剂中的BCA（bicinchoninic acid，双辛丹宁）生成一个在562 nm处具有最大光吸收的紫色复合物，复合物的光吸收强度与蛋白质浓度成正比。此法测定范围100～1200 μg蛋白质/ml，操作简单，灵敏度虽与Folin-酚法相似，但试剂十分稳定，显色后1 h内读A562值无变化，抗试剂干扰能力强。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"d2bf8769","s":"b","g":"b02","n":"考马斯亮蓝法","e":"Coomassie brilliant blue method","d":"又称Bradford法，1976年由Bradford建立，属于蛋白质定量测定方法。该法根据蛋白质与考马斯亮蓝（CBB）结合的原理设计，是目前灵敏度最高的蛋白质测定法；CBB G-250染料在酸性溶液中与蛋白质结合，使染料最大吸收峰的位置由465 nm变为595 nm，溶液颜色由棕黑色变为蓝色，染料主要与蛋白质中的碱性氨基酸（特别是精氨酸）和芳香族氨基酸残基相结合。优点是灵敏度高、快速简便、干扰物质少。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"7c73116b","s":"b","g":"b02","n":"超速离心","e":"ultracentrifugation","d":"属于利用离心力场分离蛋白质并测定其分子量的方法。不同蛋白质的密度与形态各不相同，在离心力场中沉降的速度也不同，从而将其分离；蛋白质在离心场中的行为用沉降系数（S）表示，大体上S与蛋白质分子量成正比关系。S还与蛋白质的密度和形状相关：分子量相同时，紧密颗粒的摩擦系数小、沉降快，疏松颗粒的摩擦系数大、沉降慢。应用包括蛋白质的分离纯化和分子量测定；超速离心机的转速为每分钟6～8万转。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"605ed0be","s":"b","g":"b02","n":"分子排阻层析","e":"size-exclusion chromatography","d":"也称凝胶过滤、分子筛层析或凝胶渗透层析，属于根据蛋白质分子大小进行分离的层析方法。柱料是具有特定孔径大小的交联聚合物；较大分子的蛋白质不能进入柱料微孔内部，流经柱的直接路径短，因而比较小分子蛋白质移动速度快而先被洗脱出来；较小分子的蛋白质进入微孔内部，因相对较长的流经距离而移动得慢而后被洗脱。测分子量时标准蛋白质的分子形状应与待测蛋白质相同，lgM=K1−K2Ve。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"491ee225","s":"b","g":"b02","n":"亲和层析","e":"affinity chromatography","d":"属于根据蛋白质分子的结合特性分离蛋白质的层析方法。滞留在柱料上的蛋白质是能特异性与柱料表面交联的配体结合的蛋白质，非结合的蛋白质在平衡过程中被洗掉，结合到柱上的目的蛋白质用含有游离配体的溶液洗脱下来。它需要有共价交联在层析填料上的生物配体，交联的配体必须与目标分子间有特异性的亲和结合，且结合必须可逆，被竞争洗脱后保持生物活性；如镍柱纯化带His-Tag的蛋白质。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"31e4fefb","s":"b","g":"b02","n":"疏水相互作用层析","e":"hydrophobic interaction chromatography","d":"简称HIC，属于利用蛋白质表面疏水性差异分离蛋白质的层析技术。从作用机制说它属于吸附层析，利用固定相载体上偶联的疏水性配基与流动相中的一些疏水性分子发生可逆性结合而进行分离；“疏水作用”一词1959年由Kauzmann首次在《蛋白质化学进展》中提出，七十年代后该技术日趋成熟。同时，到目前为止还没有被广泛接受的关于疏水相互作用层析机制的理论。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"fc79aecf","s":"b","g":"b02","n":"高效液相色谱","e":"high performance liquid chromatography","d":"简称HPLC，属于提高层析效果的分离技术。HPLC利用高压泵加快蛋白质分子沿柱流动的速度，提高层析效果，缩短层析时间，消除扩散影响，提高分辨率；其层析系统由高压泵、层析柱与检测器等组成，实验室用层析柱直径0.5～5 cm，工业用层析柱直径5～100 cm，填充物的多孔化可以减少层析压。以灌注层析示意说明其在蛋白质分离纯化中的应用；这种以高压提高流速的方式使分离在短时间内完成。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"d8b59949","s":"b","g":"b02","n":"电泳","e":"electrophoresis","d":"属于利用带电蛋白质在电场中受电场力作用发生迁移的特性分离和鉴定蛋白质的技术。电泳通常不用于大规模的蛋白质纯化，因为有更简单的方法可用，并且电泳会不可逆地导致蛋白质结构和功能的改变，但在蛋白质及核酸的分析方法上特别有用：蛋白质经电泳分离后可以显色，可很快估测不同蛋白质在混合物中的数量或纯度，还可测定等电点及大概的分子量；蛋白质电泳通常在交联的多聚物凝胶上进行，凝胶起分子筛的作用。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"63c4b769","s":"b","g":"b02","n":"电泳迁移率","e":"electrophoretic mobility","d":"属于描述带电颗粒在电场中迁移快慢的参数，用μ表示。电泳中驱动大分子运动的力是电势梯度E（场强），分子的电泳迁移率等于粒子的电压与电场场强的比值，还等于分子的净电荷Z与摩擦系数f的比值，即μ=V/E=Z/f，其中摩擦系数部分反映蛋白质分子的形状。因此蛋白质在电场中的电泳迁移是大小和形状共同作用的结果，也是凝胶电泳分离蛋白质的依据；凝胶的分子筛作用能减缓电荷/质量比相近蛋白质的迁移。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"28baea74","s":"b","g":"b02","n":"SDS-聚丙烯酰胺凝胶电泳","e":"SDS-polyacrylamide gel electrophoresis","d":"简称SDS-PAGE，属于在加入变性剂SDS条件下的聚丙烯酰胺凝胶电泳。蛋白质与SDS结合，经热变性和二硫键的还原，形成所带负电荷相对一致的非折叠衍生物，电泳时泳动速度主要由分子量决定；1个SDS分子平均结合2个氨基酸残基，使蛋白质带净负电荷并具有几乎相同的电荷/质量比，复合物形状近似雪茄烟状的长椭圆棒。可用于测定蛋白质分子量，测定结果只是亚基或单条肽链的分子量。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"492c36c4","s":"b","g":"b02","n":"凝胶浓度与交联度","e":"gel concentration and cross-linking degree","d":"属于描述聚丙烯酰胺凝胶孔径的两个参数。100 ml凝胶溶液中含有的单体和交联剂总克数称为凝胶浓度，记号为T，T(%)=[Acr(g)+Bis(g)]/V(ml)×100%；凝胶溶液中交联剂占单体加交联剂总量的百分数为交联度，记号为C，C(%)=Bis/(Acr+Bis)×100%。凝胶浓度主要影响筛孔的大小，筛孔的平均直径和凝胶浓度的平方根成反比；交联度反映甲撑桥的密度，可决定筛孔的最大直径。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"b4253b4d","s":"b","g":"b02","n":"等电聚焦","e":"isoelectric focusing","d":"属于一种特殊的PAGE电泳法。在凝胶柱中加入两性电解质载体Ampholine，可使凝胶柱上产生pH梯度，施加电场后pH梯度的顺序是从阳极到阴极pH值逐渐增大；蛋白质为两性电解质，所带电荷的性质和数量随所处环境的pH而变化，带负电荷的蛋白质向阳极移动、带正电荷的向阴极移动，当泳动到某一部位其pH正好相当于该蛋白质的等电点时，净电荷为零不再移动，聚焦形成一条蛋白质区带。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"ab76acb2","s":"b","g":"b02","n":"双向电泳","e":"two-dimensional electrophoresis","d":"简称2-DE，属于先后结合等电聚焦和SDS-PAGE电泳的技术。双向电泳能使复杂蛋白质的混合物得到好的分辨，较其他单独使用的电泳分析方法灵敏度更高；能分开不同pI但分子量相同或相近的蛋白质，也能分开相近pI但不同分子量的蛋白质。第一向在圆筒形凝胶进行等电聚焦，再将凝胶平放到平板SDS-聚丙烯酰胺凝胶上，水平方向反映pI差距，垂直方向反映分子量差异。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"387a1cdf","s":"b","g":"b02","n":"银染","e":"silver staining","d":"属于蛋白质凝胶电泳后最常用和最灵敏的染色方法。银离子与蛋白质分子上的巯基或羧基结合，再被还原为银，可使蛋白质条带呈深棕至黑色；分为酸性和碱性两种方法，碱性方法非常敏感但需要较长的步骤，酸性方法快速但灵敏度较低。银染灵敏度高（2～5 ng），缺点包括可能造成很高的背景、费时费力（需要8～16 h）、费用昂贵、需要接触有毒的甲醛，且核酸、脂多糖等常会干扰结果。","src":"第8讲 蛋白质化学6：理化性质与分离分析"},{"id":"824fce4a","s":"b","g":"b03","n":"酶学","e":"Enzymology","d":"研究酶的性质、结构和作用原理、作用规律、生物学功能、酶工程学以及酶应用的科学。它以生物催化剂酶为研究对象，内容包括酶分子结构与功能的关系、酶的催化机制与调节机制、酶与生命活动的关系，以及酶的生产、制备和应用。酶学研究一般认为始于1897年Buchner兄弟发现酵母抽提物可发酵糖，生物化学的研究史多数是酶研究的历史；现代酶学则沿着酶分子生物学和酶工程两个方向发展。","src":"第9讲 酶学"},{"id":"5a2db333","s":"b","g":"b03","n":"酶","e":"Enzyme","d":"由生物活细胞制造的、能在体内外起相同催化作用的一类具有活性中心和特殊构象的生物大分子，其化学本质主要是蛋白质。所有的酶都是由生物体产生的，几乎所有的生物包括病毒都能编码和合成酶；细胞中大部分球蛋白为酶。酶的催化效率比非催化反应高10⁸~10²⁰倍，比其他催化反应高10⁷~10¹³倍，并具有易失活、活性受调节和高度专一性等自身特点。酶具有一般催化剂的特点：加快反应速度、反应前后无变化、不改变反应的平衡点。","src":"第9讲 酶学"},{"id":"47056329","s":"b","g":"b03","n":"活化能","e":"Activation energy","d":"在一定温度下1 mol底物全部进入活化态所需要的自由能，单位为J/mol。反应物中能量高于初态的那部分能量即活化能，分子获得这部分能量后进入过渡态（活化态），从而打破或形成化学键生成产物；处于活化态的分子为活化分子，这种分子愈多反应速度就愈快。酶与其他催化剂一样能降低反应活化能，如过氧化氢分解的活化能在无催化剂时为75.24 kJ/mol，胶态钯催化为48.9，过氧化氢酶催化仅8.36。","src":"第9讲 酶学"},{"id":"2311548c","s":"b","g":"b03","n":"核酶","e":"Ribozyme","d":"具有催化活性的RNA。1982年Cech首先发现四膜虫L19RNA既有RNase活性又有RNA聚合酶活性，随后研究表明它具备高度底物专一性、遵循米氏动力学、对竞争性抑制剂敏感等酶促催化特征；原核生物RNase P由RNA与蛋白质组成，起催化作用的都是RNA。核酶分剪切型与剪接型两类，典型结构含三个螺旋、13个保守碱基，剪切点为GUN。Cech与Altman因此获1989年诺贝尔化学奖。","src":"第9讲 酶学"},{"id":"233f1aa0","s":"b","g":"b03","n":"酶的专一性","e":"Substrate specificity","d":"又称底物专一性，指酶对底物选择的严格程度，是酶区别于一般催化剂的重要特点。其分为两类：结构专一性包括只作用于一个底物的绝对专一性和作用对象不止一种底物的相对专一性，后者又有族专一性或基团专一性、键专一性之分；立体异构专一性包括旋光异构专一性和几何异构专一性。专一性由活性中心决定，研究专一性底物的结构特点可确定活性中心的结构特点。旋光异构专一性即酶只作用于旋光异构体中的一种，如L-氨基酸氧化酶只催化L-氨基酸氧化。","src":"第9讲 酶学"},{"id":"256c6f6c","s":"b","g":"b03","n":"绝对专一性","e":"Absolute specificity","d":"结构专一性的一种，指有些酶对底物的要求非常严格，只作用于一个底物。以脲酶为例：脲酶只能催化尿素水解，而对尿素的各种衍生物（如尿素的甲基取代物或氯取代物）不起作用。与它相对的是相对专一性，即酶的作用对象不止一种底物，又可分为族专一性或基团专一性和键专一性。酶的专一性研究是判断和确定活性中心结构特点的途径之一。绝对专一性说明酶活性中心与底物结构之间存在严格的互补关系，使酶能从众多物质中只选择其中之一。","src":"第9讲 酶学"},{"id":"4501548e","s":"b","g":"b03","n":"全酶","e":"Holoenzyme","d":"由酶蛋白与辅助因子结合形成的完整复合物，即酶蛋白加辅助因子。结合酶由酶蛋白与辅助因子组成，其中酶蛋白决定催化反应的特异性，即选择酶所催化的底物；辅助因子决定反应的类型，起递电子、递氢或转移某些基团的作用。辅助因子可为辅基、辅酶或金属离子，许多辅酶是B族维生素的衍生物。只有二者结合成全酶才能表现催化活性。以“全酶＝酶蛋白＋辅助因子”的组成式说明结合酶的分子组成，不含辅助因子的则称单纯酶。","src":"第9讲 酶学"},{"id":"99f13b60","s":"b","g":"b03","n":"辅助因子","e":"Cofactor","d":"包括金属离子和小分子有机化合物，本身无催化作用，除稳定酶的构象外，一般在酶促反应中运输转移电子、原子或某些功能基团。按其与酶蛋白结合的牢固程度分为两类：与酶蛋白结合松弛、可通过透析或超滤除去者称辅酶；以共价形式与酶蛋白牢固结合、不能通过透析或超滤除去者称辅基，金属离子也可归入辅基。有些蛋白质也具有这种作用，被称为蛋白辅酶。辅助因子与酶蛋白的结合方式决定它属于辅酶还是辅基，也决定能否用透析、超滤等方法将其除去。","src":"第9讲 酶学"},{"id":"1d904654","s":"b","g":"b03","n":"辅酶","e":"Coenzyme","d":"与酶蛋白结合松弛的辅助因子，可以通过透析或超滤等物理方法除去，多为有机小分子，常为B族维生素的衍生物。它与辅基同属酶的辅助因子，本身无催化作用，在酶促反应中运输转移电子、原子或某些功能基团。辅酶与辅基的区别仅在于与酶蛋白结合的牢固程度；在结合酶中酶蛋白决定催化反应的特异性，辅助因子决定反应的类型。辅酶被除去后酶蛋白即失去催化活性，说明辅酶是全酶发挥催化作用不可缺少的部分。","src":"第9讲 酶学"},{"id":"dad2ebe1","s":"b","g":"b03","n":"辅基","e":"Prosthetic group","d":"以共价形式与酶蛋白牢固结合、不能通过透析或超滤除去的辅助因子，与结合松弛的辅酶相区别，金属离子也可归入辅基。它与辅酶同属酶的辅助因子，本身无催化作用，主要作用是稳定酶的构象并在酶促反应中运输转移电子、原子或某些功能基团。在结合酶中，辅助因子决定反应的类型，酶蛋白决定催化反应的特异性，二者结合成全酶。辅基不能通过透析或超滤除去，只有破坏其与酶蛋白之间的共价结合才能将二者分开；辅基与辅酶的区别只在于与酶蛋白结合的牢固程度。","src":"第9讲 酶学"},{"id":"34bef36c","s":"b","g":"b03","n":"寡聚酶","e":"Oligomeric enzyme","d":"根据酶蛋白分子特点划分的一类酶，分子量为35000至几百万，由几个甚至几十个亚基组成。其亚基一般无活性，可以相同也可以不同，亚基间以非共价键结合，容易分开，如3-磷酸甘油醛脱氢酶。与它并列的还有只有一条多肽链的单体酶，以及由几种酶彼此嵌合形成复合体、有利于一系列反应连续进行的多酶体系；多功能酶则是多种催化功能集于一条多肽链的酶。许多寡聚酶属于别构酶，其亚基间的协同作用使反应速度对底物浓度呈S形曲线。","src":"第9讲 酶学"},{"id":"c752cbfa","s":"b","g":"b03","n":"多酶体系","e":"Multienzyme system","d":"由几种酶彼此嵌合形成的复合体，有利于一系列反应的连续进行，分子量一般在几百万。它是按酶蛋白分子特点划分的三类酶之一，与单体酶、寡聚酶并列：单体酶只有一条多肽链，很少，一般是催化水解反应的酶，如胰蛋白酶；寡聚酶由几个甚至几十个亚基组成，亚基间非共价结合、容易分开。此外，有人将多种催化功能集于一条多肽链的酶称为多功能酶或串联酶。多酶体系说明酶在细胞中并非孤立存在，而是以复合体形式组织起来完成一系列连续反应。","src":"第9讲 酶学"},{"id":"d7a3228a","s":"b","g":"b03","n":"酶活力","e":"Enzyme activity","d":"也称酶活性，指酶催化反应的能力。酶活力大小就是指在一定条件下所催化的某一化学反应速度的快慢，酶催化的反应速度越快，酶活力越高。酶的定量并非对蛋白质进行定量，而是对它的催化能力进行定量，所以酶的定量就是测定酶的活力，也即测定酶促反应的速度。酶活力不能通过称重或体积表示，常用国际单位、催量或自定义单位表示。测定酶活力的方法有连续法或终点法、动力法、紫外可见分光光度法、荧光分光光度法、酶偶联法、电化学法和旋光法等。","src":"第9讲 酶学"},{"id":"3aea4347","s":"b","g":"b03","n":"国际单位","e":"International Unit, IU","d":"由酶学委员会1976年规定的酶活力单位。在标准条件（25℃、最适pH、最适底物浓度）下，酶每分钟催化1 μmol底物转化为产物，这样速度所代表的酶的量被定义为1个国际单位，即1 U相当于1 μmol/min。与它并列的还有1979年规定的催量（Katal），指最适条件下酶每秒钟催化1 mol底物转化的酶量；此外还有各实验室自定义的活力单位。国际单位与催量都用于表示酶的量，前者以每分钟转化μmol底物计，后者以每秒转化mol底物计。","src":"第9讲 酶学"},{"id":"99ad708c","s":"b","g":"b03","n":"比活力","e":"Specific activity","d":"指每毫克酶蛋白所含的酶活力单位数，一般用U/mg蛋白质表示，是酶制剂纯度的常用指标。比活力越大，表示酶越纯。在酶的分离纯化中，可用纯化倍数（每次比活力/第一次比活力）和产率或回收率（每次总活力/第一次总活力×100%）评价纯化效果，因此纯化过程必须每步测定酶活，以指导分离纯化正确进行；测定比活力须同时测定酶活与蛋白含量。比活力越高，说明单位重量蛋白中目标酶所占的比例越大，故可作为纯度指标。","src":"第9讲 酶学"},{"id":"d530c422","s":"b","g":"b03","n":"米氏方程","e":"Michaelis-Menten equation","d":"通过米氏常数Km定量描述反应初速度v0、最大反应速度Vmax和底物浓度[S]之间关系的方程，即v0＝Vmax[S]/(Km＋[S])，是单底物-酶反应的速度方程。其推导以中间络合物学说为基础：酶与底物先形成ES复合物再转化为产物，并假设ES的形成速度与分解速度相等即稳态。表现为v0对[S]双曲线依赖的酶被认为遵循米氏动力学，主要例外是变构酶。米氏方程并不决定于其最初提出的两步反应机制，多数遵循米氏动力学的酶反应机制更为复杂。","src":"第9讲 酶学"},{"id":"31e45b4e","s":"b","g":"b03","n":"米氏常数","e":"Km Michaelis constant","d":"米氏方程中的常数，Km＝(k2＋k3)/k1，由酶反应性质及温度、pH、离子浓度等反应条件决定，对特定的酶与底物是一个特征常数。当v0＝1/2Vmax时Km＝[S]，即Km是反应速度达最大反应速度一半时的底物浓度，单位为浓度单位。1/Km可近似表示酶对底物的亲和力，Km最小的底物为最适底物即天然底物；Km还可用于鉴定酶、判断抑制类型和计算底物浓度。Km值越小，底物与酶的亲和力越强；催化正逆反应的酶其正逆两向Km不同，可据此判断反应方向。","src":"第9讲 酶学"},{"id":"95eae5f4","s":"b","g":"b03","n":"转换数（催化常数）kcat Turnover number, kcat","e":"","d":"指当酶被底物饱和时每秒钟每个酶分子转换底物的分子数，又称催化常数，是一级速度常数，单位为1/s或s⁻¹。Vmax＝kcat[E]，kcat越大表示催化效率越高；若反应中有一步限速，kcat即该限速步骤的速度常数，通常是形成产物那一步的常数；若几步都部分限速则称为转换数。kcat和Km均可通过实验测定。kcat与Km一样是可通过实验测定的动力学参数，不同酶的kcat差别很大。","src":"第9讲 酶学"},{"id":"e89bb1b5","s":"b","g":"b03","n":"特异性常数","e":"kcat/Km Specificity constant","d":"即kcat与Km的比值，是E＋S→E＋P的表观二级速度常数，单位为L/(mol·s)。当[S]≪Km时，v0＝(kcat/Km)[E0][S]。比较不同酶或同一种酶催化不同底物的催化效率，最好的方法是比较kcat/Km；E与S在溶液中扩散到一起的速率决定其上限，即扩散控制极限10⁸~10⁹ M⁻¹s⁻¹。kcat与Km单独表示都不足以评价动力学效率，因为不同酶的kcat可能相同、Km对细胞内底物浓度也可能相近。","src":"第9讲 酶学"},{"id":"f4ced515","s":"b","g":"b03","n":"双倒数作图法","e":"Lineweaver-Burk plot","d":"又称Lineweaver-Burk作图或双倒数作图。将米氏方程两边取倒数转变为Lineweaver-Burk方程，以1/v0对1/[S]作图得到一条直线：直线斜率为Km/Vmax，纵轴截距为1/Vmax，横轴截距为-1/Km，因此由截距即可求出Km和Vmax。也指出其缺点：点分布不均匀而集中于1/v轴，低[S]时v本身误差大，化成倒数后误差被显著放大。此外还有Eadie-Hofstee、Hanes-Woolf等作图法。","src":"第9讲 酶学"},{"id":"02ab89ce","s":"b","g":"b03","n":"竞争性抑制","e":"Competitive inhibition","d":"可逆抑制的一种，抑制剂竞争结合底物与酶的活性位点，占据活性位点阻止底物与酶结合，通常是底物的类似物，与酶结合形成EI复合物但不被催化。此时米氏方程为v0＝Vmax[S]/(αKm＋[S])，α＝1＋[I]/Ki；Vmax不变而表观Km增大(1＋[I]/Ki)倍，双倒数作图中纵轴截距相同、斜率增大。标志是抑制可在底物浓度足够高时被克服，如5-氟尿嘧啶、6-巯基嘌呤。","src":"第9讲 酶学"},{"id":"68b9bde3","s":"b","g":"b03","n":"反竞争性抑制","e":"Uncompetitive inhibition","d":"可逆抑制的一种。抑制剂与酶结合的位点不是底物的活性位点，只与ES复合物可逆结合，生成不能分解成产物的EIS，而不能与自由酶结合。此时米氏方程为v0＝Vmax[S]/(Km＋α′[S])，α′＝1＋[I]/Ki′；高[S]时v0接近Vmax/α′，表观Vmax降低，表观Km也降低。与竞争性抑制相反，其Ki值为∞，EIS只能解离成ES＋I，不能解离成EI＋S。双倒数作图中纵轴截距增大、横轴截距负值增大，是判断这种抑制类型的依据。","src":"第9讲 酶学"},{"id":"1663fdfe","s":"b","g":"b03","n":"激活剂","e":"Activator","d":"凡能使酶由无活性变为有活性或使酶活性增加的物质。举例：金属离子如Mg²⁺、K⁺、Mn²⁺，阴离子如Cl⁻，有机物如胆汁酸盐。按是否为酶发挥催化作用所必需，可分为必需激活剂和非必需激活剂，如Mg²⁺对己糖激酶是必需激活剂，Cl⁻对淀粉酶是非必需激活剂。激活剂与底物浓度、酶浓度、温度、pH、抑制剂并列为影响酶促反应速度的因素。必需激活剂是酶发挥催化作用所不可缺少的，非必需激活剂则只起促进或提高活性的作用。","src":"第9讲 酶学"},{"id":"73d29975","s":"b","g":"b03","n":"酶的活性中心","e":"Active center","d":"酶分子上由必需基团构成的与酶催化活性有关的特定区域。最初把酶分子中与底物接触或非常接近底物的部分称为活性部位，而直接与酶催化有关的部位称为活性中心。活性中心内的必需基团分为结合基团与催化基团，前者与底物结合，后者参与催化，中心之外还有活性中心外必需基团。可用专一性底物、竞争性抑制剂、侧链基团化学修饰法和X射线晶体衍射法确定。活性中心通常只由少数几个氨基酸残基构成，它们在空间上彼此靠近而形成一个特定区域。","src":"第9讲 酶学"},{"id":"43db7c80","s":"b","g":"b03","n":"诱导契合学说","e":"Induced-fit hypothesis","d":"Koshland于1958年提出的酶与底物结合学说。其要点是：酶表面并没有一种与底物互补的固定形状，而只是由于底物的诱导才形成互补形状；当底物与酶接触时，可诱导酶分子构象变化，使活性中心各种基团处于与底物互补契合的正确空间位置，有利于催化。它与Fischer的锁-钥模式相对，后者能解释专一性却无法说明酶为何能稳定过渡态；此外还有群体移动模式。群体移动模式认为酶在溶液中同时存在适合与不适合底物结合的两种构象，二者保持动态平衡。","src":"第9讲 酶学"},{"id":"874faf94","s":"b","g":"b03","n":"同工酶","e":"Isoenzyme","d":"催化同一种化学反应，但酶蛋白本身的分子结构有所不同的一组酶。同工酶存在于生物的同一种属或同一个个体的不同组织中，甚至同一组织或同一细胞中；这类酶由两个或两个以上的亚基组成。以乳酸脱氢酶为例，LDH有5种同工酶（H4、H3M、H2M2、HM3、M4）。同工酶对个体发育、细胞分化、代谢调节有重要作用，分析已用于优势杂交组合预测和临床诊断。同工酶谱在不同组织中有差异，如人体心、肝和骨骼肌的LDH同工酶谱各不相同。","src":"第9讲 酶学"},{"id":"462551d1","s":"b","g":"b03","n":"固定化酶","e":"Immobilized enzyme","d":"借助物理或化学方法将酶固定于水不溶性或水溶性载体而制备成的一种酶制剂形式，固定化方法主要包括吸附法、共价偶联法、交联法和包埋法。1953年最早报道固定化酶，1969年固定化氨基酸酰化酶正式用于工业生产，1971年Nelson和Griffin正式提出immobilized enzyme的概念。酶固定化后活力可缓慢释放，稳定性比天然态高，可重复多次使用。固定化酶可在酶反应器中连续使用，是酶工程研究与应用的重要内容。","src":"第9讲 酶学"},{"id":"1085ee54","s":"b","g":"b03","n":"酶原","e":"Zymogen","d":"酶的无活性的前体。以胰蛋白酶原的激活过程为例：酶原经肠激酶或胰蛋白酶作用，切去游离的六肽后成为有活性的胰蛋白酶，这一过程与二硫键、静电吸引力或氢键维持的构象有关。酶原形式的意义在于使酶在特定的环境和条件下才发挥作用，并可避免细胞自身消化；酶原与酶原的激活属于酶含量调节的内容。胰蛋白酶原可被肠激酶激活，也可被胰蛋白酶自身激活，切去游离的六肽后生成有活性的胰蛋白酶；酶原激活使消化酶只在需要时才表现活性。","src":"第9讲 酶学"},{"id":"47338bb2","s":"b","g":"b03","n":"酶原的激活","e":"Zymogen activation","d":"由无活性的酶原转变为有活性的酶的过程。以胰蛋白酶原为例：在肠激酶或胰蛋白酶作用下，酶原分子被切除一段游离的六肽，构象随之改变而表现活性。酶原激活的意义在于使酶能在特定的环境和条件下发挥作用，并避免细胞自身消化；它与酶的变构调节、共价修饰调节同属酶活性的调节方式，是酶含量调节的重要内容。激活通过切除游离的六肽完成，其本质是切除一段肽链的有限水解；被切下的肽段不再参与酶分子的组成，酶由此获得有活性的构象。","src":"第9讲 酶学"},{"id":"4e897bba","s":"b","g":"b03","n":"变构调节","e":"Allosteric regulation","d":"体内一些代谢物可与某些酶分子活性中心外的部位可逆结合，使酶构象改变从而改变酶的活性，这类酶一般都是寡聚酶。1963年Monod首次提出，别构酶一般为多亚基酶，别构调节剂（效应物）与活性中心以外的调节部位或亚基结合，引起调节亚基构象改变，进而引起别构酶构象改变而调节酶活性。变构酶的动力学偏离米氏方程，v对[S]多呈S形曲线，如Asp-氨甲酰磷酸转移酶。别构调节剂与调节亚基结合后，通过亚基间的构象传递改变催化亚基的活性。","src":"第9讲 酶学"},{"id":"750e9789","s":"b","g":"b04","n":"B型DNA双螺旋","e":"B-form DNA double helix","d":"Watson和Crick于1953年提出的DNA二级结构模型，B型是细胞中最常见的构象。其特点为：两条反向平行的多核苷酸链构成右手双螺旋，主链位于螺旋外侧、碱基位于内侧；A与T、G与C互补配对形成氢键，分别为2个和3个；螺距3.4 nm，直径2 nm，相邻碱基对平面距离0.34 nm，相差36度，10个核苷酸一圈；稳定因素为氢键和碱基堆积力。两条反平行的多核苷酸链绕同一中心轴相缠绕，一条为5′→3′方向，另一条为3′→5′方向。","src":"第10讲 核酸化学1"},{"id":"5799d904","s":"b","g":"b04","n":"基因组","e":"Genome","d":"泛指一个生命体、病毒或细胞器所含有的全部遗传物质；对真核生物而言指一套染色体（单倍体）DNA，即物种全部遗传信息的总和。人类基因组包含约30亿个碱基对，其中大约只有5万个基因转录成mRNA分子。1986年Mckusick创造了Genomics这一名词，即指从基因组水平研究基因生物学；基因组DNA在原核生物中呈环状双链，在真核生物中多为线形并与蛋白质结合。","src":"第10讲 核酸化学1"},{"id":"9d046846","s":"b","g":"b04","n":"基因组学","e":"Genomics","d":"发展和应用DNA制图、测序新技术以及计算机程序，分析生命体（包括人类）全部基因组的结构及功能的学科。它以整个基因组为研究对象，而不是以单个基因为研究对象；研究手段为分子生物学技术（大规模测序、基因表达分析及功能研究）、计算机技术和信息网络技术；研究方法包括基因组作图（遗传图谱、物理图谱、转录图谱）、核苷酸序列分析、基因定位和基因功能分析。该名词由Mckusick于1986年创造。","src":"第10讲 核酸化学1"},{"id":"967003d7","s":"b","g":"b04","n":"转录组","e":"Transcriptome","d":"一个活细胞所能转录出来的全部RNA的总和，是研究细胞表型和功能的一个重要手段。与基因组不同，转录组的定义中包含时间和空间的限定：同一细胞在不同生长时期及生长环境下，其基因表达情况不完全相同。人类基因组约30亿个碱基对中只有约5万个基因转录成mRNA，转录后的mRNA能翻译生成蛋白质的只占整个转录组的40%左右。转录组研究是研究细胞表型和功能的重要手段，也是转录组学的研究对象。","src":"第10讲 核酸化学1"},{"id":"93a5d2d0","s":"b","g":"b04","n":"转录组学","e":"Transcriptomics","d":"一门在整体水平上研究细胞中基因转录的情况及转录调控规律的学科。它以转录组即一个活细胞所能转录出的全部RNA为研究对象，通过测序技术揭示不同生长时期、不同生长环境下基因表达的差异，已是目前最常用的手段。同一种组织表达几乎相同的一套基因以区别于其他组织，如脑组织或心肌组织分别只表达全部基因中不同的30%，显示组织特异性。转录组学与基因组学不同，它不以单个基因为研究对象，而在整体水平上考察全部转录产物。","src":"第10讲 核酸化学1"},{"id":"81e62e67","s":"b","g":"b04","n":"核酸的一级结构","e":"Primary structure of nucleic acid","d":"指组成核酸的核苷酸的组成、连接方式和顺序。一分子核苷酸的3′-位羟基与另一分子核苷酸的5′-位磷酸基通过脱水形成3′,5′-磷酸二酯键，将两分子核苷酸连接起来。DNA的一级结构指DNA分子中脱氧核糖核苷酸的排列顺序及连接方式，RNA的一级结构指RNA分子中核糖核苷酸的排列顺序及连接方式；序列可按pA-C-G-T-AOH等形式表示。一级结构是核酸结构与功能研究的基础，遗传信息即贮存于核苷酸的排列顺序之中。","src":"第10讲 核酸化学1"},{"id":"283605fe","s":"b","g":"b04","n":"核酸","e":"Nucleic acid","d":"由多个核苷酸单位通过3′,5′-磷酸二酯键连接起来形成的不含侧链的长链状化合物，是生物体内的高分子化合物，包括脱氧核糖核酸（DNA）和核糖核酸（RNA）两大类。核酸的元素组成为C、H、O、N、P，与蛋白质比较有两个特点：一般不含元素S；P含量较多并且恒定，约占9~10%（通常取9.5%），故可用定磷法进行定量测定。核酸经水解可得到很多核苷酸，核苷酸又可水解为核苷和磷酸，核苷再水解为戊糖和含氮碱基。","src":"第10讲 核酸化学1"},{"id":"f44bc8de","s":"b","g":"b04","n":"5′-端与3′-端","e":"5′-end and 3′-end","d":"核酸是有方向性的长链状化合物，多核苷酸链的两端分别称为5′-端与3′-端：5′-端是核酸末端的核糖基带有5′-磷酸的一端，3′-端是核酸末端的核糖基3′位为羟基的一端。核酸一级结构的表示方法即按此方向书写，如5′-AGTCCATG-3′。方向性是核酸一级结构的基本特征，也是序列书写与碱基互补配对的结构基础。这种方向性使核酸的合成、复制与转录具有固定的方向，书写序列时5′端置于左侧。","src":"第10讲 核酸化学1"},{"id":"235fcbf3","s":"b","g":"b04","n":"mRNA（信使RNA）Messenger RNA","e":"","d":"细胞质中的一类RNA，约占细胞总RNA的5%，是蛋白质合成的直接模板。mRNA的设想由Jacob和Monod于1961年提出并证实，他们推测存在一种与DNA序列互补、能将它所编码的遗传信息带到蛋白质合成场所并翻译产生蛋白质的RNA；Brenner、Jacob等人用同位素标记方法证实这是一种新的RNA分子，并命名为信使RNA。真核生物mRNA 5′端有帽子结构、3′端多聚A尾，原核生物mRNA则无帽无尾，且多为多顺反子。","src":"第10讲 核酸化学1"},{"id":"9a7c9d20","s":"b","g":"b04","n":"tRNA（转运RNA）Transfer RNA","e":"","d":"细胞质中的一类稳定小分子RNA，约占细胞总RNA的15%，功能是活化与转运氨基酸。1957年Hoagland发现这类不与核糖体结合的稳定小分子RNA；Crick预言存在一种分子转换器，有20种、每种氨基酸一个，且每种氨基酸必有对应的酶催化其与转换器结合；1963年Ehrenstein等证明Hoagland发现的分子即tRNA，1965年Holley测出酵母Ala-tRNA序列。","src":"第10讲 核酸化学1"},{"id":"7e01a370","s":"b","g":"b04","n":"rRNA（核糖体RNA）Ribosomal RNA","e":"","d":"细胞质中含量最多的RNA，约占细胞总RNA的80%，充当装配机，提供蛋白质合成的场所。rRNA存在于核糖体中，Watson等发现rRNA的G≠C、A≠U，推断其为单链分子；原核生物有16S、5S、23S三种rRNA，真核生物有18S、5S、5.8S、28S；原核生物50S大亚基由5S及23S rRNA与蛋白质组成，30S小亚基由16S rRNA与蛋白质组成。","src":"第10讲 核酸化学1"},{"id":"00cda964","s":"b","g":"b04","n":"基因","e":"Gene","d":"DNA分子中的功能片段，决定遗传特性，具有特定的碱基序列。1909年Johannsen第一次用\"基因\"这个词代表遗传学的最基本单位即遗传因子；Morgan通过果蝇实验把一个特定基因与一条特定染色体联系起来，证明基因在染色体上，并于1926年创立基因学说。据此说明基因是DNA上的功能单位，为认识DNA是遗传物质提供了概念基础。基因组是一个生命体全部遗传物质的总和，基因则是其中决定遗传特性的功能片段。","src":"第10讲 核酸化学1"},{"id":"c549e48c","s":"b","g":"b04","n":"核苷","e":"Nucleoside","d":"由碱基与戊糖以糖苷键连接形成的化合物，即核苷＝碱基＋戊糖。嘌呤环上的N-9或嘧啶环上的N-1与糖的C1′以N-C糖苷键相连，形成β构型；核苷还可再进一步水解，产生戊糖和含氮碱基。核苷分为核糖核苷与脱氧核糖核苷两类，名称与缩写如腺苷（Ado）、鸟苷（Guo）、胞苷（Cyd）、尿苷（Urd）、胸苷（Thd）。假尿苷是例外，它以C-C糖苷键连接。核苷中碱基与戊糖环大致垂直，二者可呈顺式（syn）或反式（anti）两种构象。","src":"第10讲 核酸化学1"},{"id":"bc44a915","s":"b","g":"b04","n":"假尿苷","e":"Pseudouridine, ψ","d":"一种修饰核苷，其碱基与糖环之间以C-C糖苷键（β1′,C5）连接，而不是通常的N-C糖苷键。它属于tRNA中的稀有碱基即修饰碱基，是所列tRNA中常见的修饰成分之一。tRNA碱基的修饰有83种，每个tRNA约含有10~15个稀有碱基，如ψ、甲基化的嘌呤和嘧啶核苷、二氢尿苷、4-硫尿苷、3-甲基胞苷、7-甲基鸟苷和辫苷等。tRNA中四种碱基均可被修饰，修饰产物还包括次黄苷（肌苷）、喹啉核苷等。","src":"第10讲 核酸化学1"},{"id":"f11c4eb9","s":"b","g":"b04","n":"核苷酸","e":"Nucleotide","d":"由核苷与磷酸连接形成的化合物，即核苷酸＝核苷＋磷酸，连接方式为磷酸酯键。糖环上所有游离羟基（核糖的C-2′、C-3′、C-5′及脱氧核糖的C-3′、C-5′）均能与磷酸发生酯化结合；生物体内多数核苷酸是5′-核苷酸，即糖环上的C-5′与磷酸酯化。核苷酸是核酸的基本单位，如腺苷酸（5′-磷酸腺苷）与脱氧胞苷酸（5′-磷酸胞苷）。核苷5′-多磷酸如AMP、ADP、ATP，相应的脱氧核苷酸则为dAMP、dADP、dATP等。","src":"第10讲 核酸化学1"},{"id":"f199213b","s":"b","g":"b04","n":"核酸的紫外吸收（A260）Ultraviolet absorption at 260 nm","e":"","d":"核酸中碱基含有共轭双键，最大吸收峰在260 nm左右；由于共振作用，所有核苷酸的碱基都吸收紫外光，核酸在260 nm附近有强大光吸收。核酸溶液的紫外吸收以摩尔磷的吸光度表示，摩尔磷即相当于摩尔核苷酸。OD260＝1.0相当于50 μg/ml双链DNA、40 μg/ml单链DNA或RNA、20 μg/ml寡核苷酸；OD260/OD280可判断纯度，纯DNA为1.8、纯RNA为2.0。","src":"第10讲 核酸化学1"},{"id":"992ba881","s":"b","g":"b04","n":"稀有碱基（修饰碱基）Rare base","e":"","d":"与氨基酸一样，碱基在细胞中也受到各种各样的修饰，其产物称为稀有碱基或修饰碱基，常扮演信号传导信使分子、营养因子、辅酶等角色，并对核酸结构的稳定性起重要作用。DNA中的稀有碱基如5-甲基胞嘧啶（动物和高等植物DNA）、N6-甲基腺嘌呤（细菌DNA）、5-羟甲基胞嘧啶（噬菌体感染的细菌DNA）；tRNA中四种碱基均可被修饰，如二氢尿苷、4-硫尿苷、7-甲基鸟苷等。","src":"第10讲 核酸化学1"},{"id":"3367d7e6","s":"b","g":"b04","n":"胰核糖核酸酶","e":"Pancreatic ribonuclease (RNase A)","d":"一种核酸水解酶，属于内切核酸酶，以β方式水解磷酸二酯键，产物为以3′-嘧啶核苷酸结尾的寡核苷酸。核酸水解酶按作用方式分为内切核酸酶与外切核酸酶两类，前者在链内部切断，后者逐个水解核苷酸，并区分了以α方式和β方式作用的两种磷酸二酯酶。胰核糖核酸酶是说明内切酶作用方式与产物的典型例子。水解后磷酸基保留在产物的3′端，故产物以3′-嘧啶核苷酸结尾；该酶只水解RNA而不水解DNA。","src":"第10讲 核酸化学1"},{"id":"4ae3eb20","s":"b","g":"b04","n":"Chargaff法则","e":"Chargaff's rule","d":"Chargaff与Hotchkiss于1950年用纸层析法分析DNA组成成分后总结的规律：DNA分子中[A]＝[T]、[G]＝[C]、[A＋G]＝[C＋T]。DNA的碱基组成有物种差异，物种亲缘关系越远差异越大；同一物种不同组织器官中DNA碱基组成相同，且不因年龄、环境及营养而改变。该法则与X射线衍射结果一起成为提出DNA双螺旋结构的主要依据。该法则从碱基组成上预示了A与T、G与C之间的配对关系。","src":"第10讲 核酸化学1"},{"id":"6be6c0d8","s":"b","g":"b04","n":"碱基互补原则","e":"Complementary base pairing","d":"两条链间A与T或G与C配对形成氢键的规律，是B型DNA双螺旋的结构特点之一：A与T之间形成两个氢键，G与C之间形成三个氢键。碱基配对时碱基一般以酮式存在而非烯醇式，碱基中的氢原子一般不移动，中性pH下参与氢键的-NH2基均不带电荷，这是杂环电子共轭与氢键共同作用的结果。碱基间的氢键还有Hoogsteen配对等形式。碱基互补使两条链的序列彼此决定，从而保证遗传信息能够准确地传递。","src":"第10讲 核酸化学1"},{"id":"4f1e6721","s":"b","g":"b04","n":"碱基堆积力","e":"Base stacking force","d":"稳定双螺旋结构的作用力之一，即疏水作用，它是稳定双螺旋结构的主要因素。碱基处于双螺旋内部的疏水环境中，可免受水溶性活性小分子的攻击；碱基堆积力与碱基配对的氢键共同稳定双螺旋，GC含量越多越稳定。稳定双螺旋的因素列为碱基堆积力、碱基配对氢键以及磷酸基负电荷与阳离子间形成的离子键。碱基平面与螺旋轴近乎垂直、戊糖平面与螺旋轴平行，这种排列使碱基得以层层堆积，相邻碱基对平面间距保持0.34 nm。","src":"第10讲 核酸化学1"},{"id":"6a64be20","s":"b","g":"b04","n":"大沟和小沟","e":"Major and minor groove","d":"大沟和小沟分别指双螺旋表面凹下去的较大沟槽和较小沟槽。小沟位于双螺旋的互补链之间，而大沟位于相毗邻的双股之间；这是由于连接于两条主链糖基上的配对碱基并非直接相对，从而使主链间沿螺旋形成空隙不等的沟槽。大沟和小沟内碱基对中的N和O原子朝向分子表面，因此沟槽是双螺旋与蛋白质等配体相互作用的部位。由于碱基对中N、O原子的朝向不同，大沟与小沟所暴露的碱基边缘信息也不同，可与蛋白质发生特异性相互作用。","src":"第10讲 核酸化学1"},{"id":"25965860","s":"b","g":"b04","n":"A-DNA","e":"","d":"A型DNA双螺旋，在75%相对湿度下形成，与溶液中DNA-RNA杂交分子的构象相似，推测转录时发生B→A转变。其碱基平面倾斜20°，螺距和每一圈碱基对数目都有变化，为11个碱基对/螺旋，各上升0.26 nm。DNA钠盐结晶结构已发现A、B、C三型，A和C型在低相对湿度条件下形成，它们的螺距都比B型短。A、B、C三型的差别主要在于螺距、每圈碱基对数和碱基倾斜角不同；Z型则为左手螺旋，与A型不同。","src":"第10讲 核酸化学1"},{"id":"53a63e2a","s":"b","g":"b04","n":"Z-DNA","e":"","d":"左手双螺旋DNA，因磷酸基在多核苷酸骨架上的分布呈Z字形而得名，由Wang和Rich于1979年在研究人工合成CGCGCG单晶的X射线衍射图谱时发现。其主链呈锯齿型左向盘绕，直径约1.8 nm，螺距4.5 nm，每一圈含12个bp，只有小沟而没有大沟，重复单位是二核苷酸而非单核苷酸；多在GC重复或碱基甲基化修饰处发现，B与Z的相互转换可能与基因调控有关。Z型DNA的轴心线位于碱基对之外，其重复单位是二核苷酸而不是单核苷酸。","src":"第10讲 核酸化学1"},{"id":"9b192306","s":"b","g":"b04","n":"DNA的三级结构","e":"Tertiary structure of DNA","d":"指在一、二级结构基础上的多聚核苷酸链上的卷曲。三级结构包括链的扭结和超螺旋，或者是单链形成的环，或是环状DNA中的连环体。超螺旋是DNA三级结构的一种普遍形式，生物体的DNA绝大多数以超螺旋形式存在；真核生物染色体DNA虽多为线形，但与蛋白质结合后两个结合点之间的DNA形成环结构，同样具有超螺旋。DNA的大小因物种而异：噬菌体T2 DNA长约50 μm，大肠杆菌DNA长约1 mm，人生殖细胞DNA长约1 m。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"f73ccb03","s":"b","g":"b04","n":"共价闭合环状DNA Covalently closed circular DNA, cccDNA","e":"","d":"两条链均不发生断裂、首尾共价相连的环状双链DNA。原核生物的基因组DNA（即染色体）、质粒DNA、一些病毒DNA以及线粒体和叶绿体DNA呈环状双链；自1965年Vinograd等发现多瘤病毒环形DNA的超螺旋以来，已知绝大多数原核生物的DNA都是cccDNA分子。它在电泳中按超螺旋、开环、线形分为Ⅰ、Ⅱ、Ⅲ型，迁移率分别为最快、最慢与中等。cccDNA是超螺旋形成的前提，连接数、盘绕数与超盘绕数等拓扑参数即针对它而言。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"4cd16547","s":"b","g":"b04","n":"超螺旋","e":"Supercoil","d":"指双螺旋环状分子再度螺旋化而形成的结构。形成超螺旋的基础是DNA双螺旋的扭曲；超螺旋DNA具有更为致密的结构，可将很长的DNA分子压缩在较小的体积内，密度较大，离心场中较线形或开环DNA移动快，凝胶电泳时泳动也较快。超螺旋可采取两种拓扑学上相当的形式：双螺旋绕圆柱体旋转，或双螺旋相互盘绕，二者可以相互转变。超螺旋水平在活体中并不均匀，特定区域超螺旋的增加有助于DNA的结构转化。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"6c5b9473","s":"b","g":"b04","n":"正超螺旋与负超螺旋","e":"Positive and negative supercoiling","d":"超螺旋的两种方向。以右旋缠绕的细绳为例：向紧缠方向捻转后将两端连接，产生一个左旋超螺旋以解除胁变，称正超螺旋；向松缠方向捻转后连接，则产生右旋超螺旋，称负超螺旋。双螺旋DNA的松开导致负超螺旋，拧紧则导致正超螺旋；天然DNA都呈负超螺旋，仅在体外可得正超螺旋，嗜热微生物是唯一含正超螺旋DNA的生物。负超螺旋含有自由能，可为打开双链提供能量，具有局部解旋倾向，使复制和转录顺利进行。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"4bf70c32","s":"b","g":"b04","n":"拓扑学","e":"Topology","d":"专门研究物体变形后仍然保留下来的结构特性的学科。在核酸化学中，环状DNA的拓扑性质用连接数等参数描述：不发生链断裂时连接数为常数，拓扑异构体之间的转变通过拓扑异构酶实现。用L＝T＋W表述DNA结构的上述变化，L为连接数、T为盘绕数、W为超盘绕数，其中L在不发生链断裂时是常数，T和W是可变的。拓扑学关注的不是分子的具体形状，而是变形后仍然保留的性质，如连接数；活体中DNA各种构象的互变正是由超螺旋程度的改变介导的。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"32a009d6","s":"b","g":"b04","n":"DNA连接数","e":"Linking number, L","d":"DNA的一股链绕另一股链盘绕的次数，代表环型双螺旋DNA分子的拓扑特性；在不发生链的断裂时它是一常数。以长260 bp、周期数25的B-DNA为例，连成环时L为25；先拧松2周再连接，则得到L为23的解链环形DNA或具有2个超螺旋周的DNA。在右手双螺旋中L规定为正；超螺旋密度约为-0.05，相当于每200 bp存在1个负超螺旋。若DNA一条链发生断裂，连接数即可改变，这是拓扑异构酶改变DNA拓扑结构的基础。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"2412209a","s":"b","g":"b04","n":"Maxam-Gilbert化学降解法","e":"Maxam-Gilbert chemical degradation method","d":"1977年Maxam和Gilbert发明的DNA测序方法。其步骤为：先将DNA末端用放射性同位素³²P标记；在多组互相独立的化学反应中分别进行特定碱基的化学修饰（硫酸二甲酯作用于G、甲酸作用于G＋A、肼/NaCl作用于C、肼作用于C＋T）；在修饰碱基位置用哌啶断开DNA链；聚丙烯酰胺凝胶电泳按长短分开；再经放射自显影读出核苷酸序列。它与Sanger法原理不同，但都产生一系列长度各异的片段群，再经电泳和放射自显影读出序列。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"0bc050b8","s":"b","g":"b04","n":"拓扑异构酶","e":"Topoisomerase","d":"催化DNA拓扑异构体之间转变的酶，反应本质是先切断DNA的磷酸二酯键，改变DNA的链环数后再连接，兼有DNA内切酶和DNA连接酶的功能。其分为拓扑异构酶Ⅰ和拓扑异构酶Ⅱ：拓扑异构酶Ⅰ切开双链中的一条，未被切的互补链通过缺口穿过后连上缺口；拓扑异构酶Ⅱ结合于DNA并产生双链断裂。促旋酶即旋转酶，是拓扑异构酶的一种。以细菌质粒DNA的松弛型、超螺旋、部分解链等状态说明拓扑异构酶的作用，促旋酶即其中之一。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"a0e818d2","s":"b","g":"b04","n":"三股螺旋DNA Triple-stranded DNA, tsDNA","e":"","d":"由三条链形成的螺旋结构，1957年由Felesnfeld及Davis首先发现。三条链均为同型嘌呤或同型嘧啶，有两种基本类型：Pu-Pu-Py型在碱性介质中稳定，Py-Pu-Py型在偏酸性介质中稳定。通常是一条同型寡核苷酸与寡嘧啶-寡嘌呤双螺旋的大沟结合，第三股与寡嘌呤同向平行并按Hoogsteen配对。它常出现在复制、转录、重组的起始位点或调节位点。H-DNA即由寡嘧啶或寡嘌呤构成镜像重复时形成的三股螺旋，是三链DNA的特例。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"f68eddd4","s":"b","g":"b04","n":"H-DNA（铰链DNA）Hinged DNA","e":"","d":"当DNA的一段寡嘧啶（寡嘌呤）构成镜像重复时可以形成的三股螺旋，称为铰链DNA。它属于三链DNA的一种特殊形式，第三股链以Hoogsteen配对与双螺旋的大沟结合，如T-A:T、C-G:C⁺。DNA三股螺旋结构常出现在复制、转录、重组的起始位点或调节位点（如启动子区），第三股链的存在可能使调控蛋白或RNA聚合酶难以结合该区段，从而阻遏遗传信息的表达。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"6f7ae2b6","s":"b","g":"b04","n":"端粒","e":"Telomere","d":"线状染色体末端的一段特殊区域。由于一般参与复制DNA的酶无法作用于染色体的3′端，端粒的主要功能是使细胞能利用端粒酶来复制端粒；如果端粒消失，复制过程将使染色体长度缩小。端粒能保护染色体末端不被外切酶破坏，并阻止细胞中的DNA修复系统将其视为需修正的损毁位置。人类细胞端粒由重复数千次的TTAGGG序列组成，与细胞衰老、死亡、癌变有关。端粒的特殊序列使其在体外能以四链形态存在，端粒酶则以自身RNA为模板延长端粒。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"955cdfcf","s":"b","g":"b04","n":"G-四联体","e":"G-quadruplex","d":"由富含鸟嘌呤的端粒重复序列形成的特殊结构：四个鸟嘌呤构成一个平面，并重叠于其他平面之上，产生稳定的G-四联体；碱基与位于四个碱基中心的金属离子螯合物之间通过氢键结合以稳定结构，如每四个碱基一组、共三层重叠的单股DNA环状物中心可见三个螯合的钾离子。TTAGGG及其二聚、四聚序列在体外均能形成四链，无金属离子时以平行四链为主。四联体的形成使染色体末端较为稳定，起到特化的端帽作用。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"18ae42d4","s":"b","g":"b04","n":"定糖法","e":"Colorimetric sugar determination","d":"利用戊糖与特定试剂的显色反应测定核酸含量的方法。RNA的测定：RNA分子中的核糖经浓硫酸或浓盐酸脱水生成糠醛，糠醛与3,5-二羟甲苯（苔黑酚或地衣酚）反应生成绿色化合物，可在670~680 nm比色测定。DNA的测定：DNA中的脱氧核糖在冰醋酸或浓硫酸存在下与二苯胺反应生成蓝色化合物，可在595~620 nm比色测定。它与紫外吸收法、定磷法同属核酸的定量方法。由于RNA含核糖而DNA含脱氧核糖，该法可分别测定二者。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"4733f522","s":"b","g":"b04","n":"定磷法","e":"Phosphorus determination","d":"利用核酸含磷量恒定来测定核酸含量的方法。纯的核酸含磷量在9.5%左右，1 g磷相当于10.5 g核酸，因此测定核酸中磷的含量即可计算核酸的含量。测定时先用强酸将核酸中的磷消化成无机磷酸，后者与定磷试剂中的钼酸反应生成磷钼酸，再经还原作用生成蓝色复合物钼蓝，最后在650~660 nm比色测定。定磷法适用于RNA和DNA，因为二者都含有磷酸，且纯核酸的含磷量恒定，生成的钼蓝颜色深浅与磷量相关。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"b4d0d515","s":"b","g":"b04","n":"凝胶电泳","e":"Gel electrophoresis","d":"当前核酸研究中最常用的分离分析方法，包括琼脂糖凝胶电泳和聚丙烯酰胺凝胶电泳：前者常用于DNA的分离分析，后者用于RNA及DNA的分离分析。不同形状的DNA分子在琼脂糖中迁移率不同，超螺旋DNA最快，开环与松弛闭合环最慢，线形DNA居中；溴乙锭能插入DNA碱基对间，在紫外线下发橘红色荧光，荧光强度与DNA含量成正比。凝胶电泳也用于检测DNA三级结构。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"8b8a5297","s":"b","g":"b04","n":"Sanger双脱氧链终止法","e":"Dideoxy chain-termination method","d":"Sanger于1977年建立的DNA测序方法。原理是利用DNA聚合酶的聚合反应，在反应体系中引入一定比例的2,3-双脱氧核苷三磷酸（ddNTP）作为终止剂：ddNTP可以掺入新生链，但其核糖3′碳上连接的是氢原子而不是羟基，不能与下一个核苷酸聚合延伸，链合成在此终止。四组反应经变性聚丙烯酰胺凝胶电泳和放射自显影读出序列。四组反应使用相同的模板、引物和四种dNTP，仅各加入一种ddNTP，故产生四组长度各异的片段。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"2d0ed04a","s":"b","g":"b04","n":"SNP 单核苷酸多态性","e":"Single nucleotide polymorphism","d":"指不同个体的基因组上单个核苷酸的变异，包括替换、缺失和插入；一般来说，SNP是指变异频率大于1%的单核苷酸变异。人与人之间平均1000个碱基对就有一个碱基呈多态性，因此共在约300万个碱基上可能存在差异。SNP在基因组中分布相当广泛，可作为新的遗传标记，人体许多表型差异、对药物或疾病的易感性都可能与之有关。新一代测序技术利用高通量、低成本的优势对较多的个体测序，很容易得到大量的SNP位点。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"89be0d21","s":"b","g":"b04","n":"限制性内切酶","e":"Restriction endonuclease","d":"一类可从微生物中分离、能切断双链DNA的酶。双链DNA可被上千种限制性内切酶切断，又可被连接酶再连接起来；切断过程不需要能量，而连接过程需要2个分子的ATP，这是分子克隆和重组DNA技术的基础。大部分限制性内切酶识别的碱基序列为6个碱基的回文序列，它们在微生物细胞内起着防御外来DNA入侵的作用。1970年Arber发现了第一个DNA限制性内切酶。限制性内切酶的发现推动了基因工程的建立，1972年Berg建立了DNA重组技术。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"2d39b147","s":"b","g":"b04","n":"DNA变性","e":"DNA denaturation","d":"指DNA分子中的双螺旋结构解链为无规则线性结构的现象。其本质是维持双螺旋稳定的氢键断裂、碱基间的堆积力遭到破坏，不涉及一级结构的改变。凡能破坏双螺旋稳定性的因素，如加热、极端pH、有机试剂（甲醇、乙醇、尿素、甲酰胺）、低离子浓度等，均可引起变性。变性后OD260增高、粘度下降、比旋度下降、浮力密度增加、酸碱滴定曲线改变、生物活性丧失。变性后DNA的生物活性丧失，但一级结构并未改变，因此在一定条件下可以复性。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"9a9ea6b4","s":"b","g":"b04","n":"解链温度（Tm）Melting temperature, Tm","e":"","d":"在核酸加热变性过程中，紫外光吸收值达到最大值50%时的温度称为解链温度；由于这一现象与结晶融解相类似，又称融解温度。在Tm时，核酸分子内50%的双螺旋结构被破坏。特定核酸分子的Tm值与其G＋C所占总碱基数的百分比成正相关，经验公式为Tm＝69.3＋0.41(G＋C)%；一般DNA的Tm值在85~90℃之间，并受介质中离子强度的影响。不同来源DNA的变性曲线不同，Tm越高说明其G＋C含量越高。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"ab6a5e7a","s":"b","g":"b04","n":"增色效应","e":"Hyperchromic effect","d":"指DNA变性后其紫外吸收明显增加的效应。DNA分子中碱基间电子的相互作用使其具有吸收260 nm波长紫外光的特性；在双螺旋中碱基藏入螺旋内侧，变性时双螺旋解开，碱基外露，碱基中电子的相互作用更有利于紫外吸收，故产生增色效应，其实质是碱基暴露。完全变性后天然DNA紫外吸收值增加25~40%，RNA约增加1.1%，1 OD260相当于37 μg单链DNA。利用增色效应可以监测DNA的变性过程，并据此测定Tm值。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"43da56a9","s":"b","g":"b04","n":"DNA复性","e":"DNA renaturation","d":"指经加热变性的DNA在适当条件下，二条互补链全部或部分恢复到天然双螺旋结构的现象，它是变性的一种逆转过程。热变性DNA一般经缓慢冷却后即可复性。复性受温度和时间影响，比Tm低20~25℃左右的温度是最佳条件，降温必须缓慢；还受DNA浓度和序列复杂性的影响，浓度越高、序列越简单越易复性。复性过程是二级反应。复性时两条互补链通过碱基配对重新形成双螺旋，条件不当则难以恢复天然构象；它是变性的逆转过程，可用于分子杂交。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"63c73c43","s":"b","g":"b04","n":"退火","e":"Annealing","d":"热变性DNA一般经缓慢冷却后即可复性，这一过程称为退火。这一术语也用以描述杂交核酸分子的形成。退火要求温度比Tm低20~25℃左右且降温缓慢；若在超过Tm的温度下迅速冷却至低温（如4℃以下），复性几乎不可能，核酸实验中经常以此方式保持DNA的变性即单链状态。复性动力学可用C₀t1/2描述。在核酸实验中，迅速冷却至低温可使DNA保持单链状态，便于杂交或作为模板使用；PCR中的退火步骤即让引物与模板单链配对。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"254c99dd","s":"b","g":"b04","n":"Cot（C₀t）值","e":"Cot value","d":"衡量DNA复性速度的参数，C₀为变性DNA的原始浓度（以核苷酸对摩尔浓度表示），t为时间（秒）。复性过程是二级反应，复性一半时C₀t1/2＝1/K；当阳离子浓度、DNA片段长度一定时，可确定复杂度与C₀t1/2直接相关。片段越大复性越慢，浓度越大复性越快；通过C₀t1/2值可测原核生物基因组的大小，并可区分真核生物与原核生物基因组。Cot分析即以复性动力学为基础，用于研究基因组大小与重复序列。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"4d0692ae","s":"b","g":"b04","n":"分子杂交","e":"Hybridization","d":"不同来源的核酸分子变性后合并在一起进行复性，只要这些核酸分子的核苷酸序列含有可以形成碱基互补配对的片段，复性也会发生于不同来源的核酸链之间，形成杂化双链，这个过程称为杂交。杂交可以发生于DNA与DNA之间，也可以发生于RNA与RNA之间或DNA与RNA之间，是Southern、Northern印迹及原位杂交、荧光原位杂交（FISH）等技术的基础。杂化双链能否形成取决于两条链的序列互补程度，因此可用于检测特定序列。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"361e78c2","s":"b","g":"b04","n":"聚合酶链反应","e":"Polymerase chain reaction, PCR","d":"应用最广的分子生物学技术，需要模板DNA、引物、底物（dNTPs）、DNA聚合酶（Taq）和扩增缓冲液，通过变性（94℃）—退火—延伸（72℃）的热循环使DNA扩增。在DNA测序中只用了单链扩增技术，所产生的模板DNA并不指数上升，而只以热循环数为倍数。PCR是基因克隆、测序与临床诊断的基础技术。反应中引物决定扩增的起点与范围，Taq DNA聚合酶耐热，故在高温变性后仍能继续延伸。","src":"第11讲 核酸化学2：DNA的结构和特性"},{"id":"d68e6d96","s":"b","g":"b04","n":"G:U配对","e":"G:U base pair","d":"RNA中除Watson-Crick配对外，还存在G与U之间的非Watson-Crick配对，这种配对是RNA中额外的规则碱基配对方式，丰富了RNA自我互补的能力，使RNA能折叠形成多种茎环结构。据此RNA虽通常以单链形式存在，却可通过包括G:U配对在内的互补作用形成局部双螺旋，其双链部分符合Watson-Crick双螺旋模型，双链区常呈发夹、突起和环等形式。这些茎环结构包括发夹、突起和环，其双链区符合A型DNA双螺旋模型。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"85fa5c9a","s":"b","g":"b04","n":"RNA世界","e":"RNA world","d":"关于生命早期形式的设想。RNA分子一般为单链，容易形成自由能最小的独特二级结构；因2′羟基的存在，一些RNA具有自我切断、自我连接、切断其他核酸分子、连接其他核酸分子及肽基转移酶等酶学活性，第一个可以自我复制的分子被认为是RNA分子。RNA在细胞中同时扮演信息媒介（mRNA）和执行者（rRNA、tRNA、snRNA）两种角色，故有人称生命早期为RNA世界。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"210e629a","s":"b","g":"b04","n":"内含子","e":"Intron","d":"真核基因顺序中插入的不编码氨基酸的序列，又称intervening sequence。真核基因拥有令人吃惊的特点，顺序中插入了很多不编码氨基酸的\"废物\"，这些序列在转录后的mRNA成熟之前被除去。鸡卵清蛋白mRNA与其基因杂交所显示的环状结构，为内含子的存在提供了直观证据，其切除通过剪接完成。真核基因转录出的hnRNA须经剪接去除内含子，才能成为成熟的mRNA，该加工由snRNA组成的剪接体完成。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"ddd95ccc","s":"b","g":"b04","n":"向导RNA Guide RNA, gRNA","e":"","d":"引导RNA编辑的RNA分子，长度约60~80个核苷酸，由单独的基因转录，具有3′寡聚U尾巴，中间有一段与被编辑mRNA精确互补的序列，5′端是锚定序列，同非编辑的mRNA序列互补。编辑时形成一个编辑体，以gRNA内部的序列作为模板对转录物进行校正，同时产生编辑的mRNA；gRNA3′端的oligo(U)尾可作为被添加U的供体。RNA编辑多数为插入碱基，编辑后mRNA的序列与基因编码序列不同。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"81a119ce","s":"b","g":"b04","n":"端粒酶RNA Telomerase RNA","e":"","d":"染色体端粒的RNA序列。在具有端粒酶活性的细胞内，它的任务是作为反转录的模板，然后加在端粒的末端，以解决染色体因复制而变短的问题。这种酶在大多数细胞里是没有活性的，在某些肿瘤细胞、转化细胞、干细胞以及生殖细胞里活性较高；端粒由重复数千次的TTAGGG序列组成，其缩短与细胞衰老有关。端粒酶RNA作为反转录的模板反复延长端粒的3′端，以补偿复制造成的缩短；端粒由重复的TTAGGG序列构成。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"cc5be2ba","s":"b","g":"b04","n":"SRP RNA（信号识别颗粒RNA）Signal recognition particle RNA","e":"","d":"信号识别颗粒中的RNA组分，实际上与多个多肽结合在一起行使功能。这个核糖核蛋白主要负责终止mRNA的翻译，同时还能与内质网上的停泊蛋白结合，使结合了mRNA的核糖体定位在内质网上，参与蛋白质的转位。它与gRNA、端粒酶RNA、snRNA等并列为具有特定功能的细胞内小分子RNA。SRP与内质网停泊蛋白结合后，携带mRNA的核糖体被定位到内质网上，新生肽链得以转位；它列为胞内具有特定功能的小RNA之一。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"ae595b87","s":"b","g":"b04","n":"多顺反子","e":"Polycistron","d":"原核生物mRNA结构的特点之一，即一条mRNA分子携带多个基因（顺反子）的编码信息。原核生物mRNA的特点为：多顺反子；5′端无帽子结构，3′端无多聚A尾；一般没有修饰碱基；无转录后加工转运，转录与翻译可同时进行。这与真核生物mRNA有5′帽子、3′多聚A尾、分子中有编码区与非编码区、经历转录后加工转运形成对照。多顺反子结构使原核生物能用一条mRNA同时编码多条肽链，转录与翻译可同时进行。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"545f4804","s":"b","g":"b04","n":"顺反子","e":"Cistron","d":"基因功能的单位，是一段染色体，是一种多肽链的密码，一种结构基因。据此界定原核生物基因的结构单位，并据此把携带多个顺反子的mRNA称为多顺反子。顺反子概念把基因的功能单位与一条多肽链的编码单位对应起来，使原核生物一条mRNA可同时携带多个基因的信息，转录与翻译可同时进行。原核生物的一条mRNA可含有多个顺反子，每个顺反子编码一条多肽链；真核生物基因则因含内含子而需转录后加工。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"9ff196e7","s":"b","g":"b04","n":"3′-多聚A尾巴","e":"3′-Poly(A) tail","d":"大多数真核mRNA 3′端具有的多聚A尾巴，大约为200 bp。polyA尾巴不是由DNA编码的，而是转录后在核内加上去的，受polyA聚合酶催化，该酶能识别mRNA游离的3′-OH端并加上约200个A残基。大多数真核基因3′端有一个AATAA序列，是加polyA尾的信号，核酸酶在此信号下游10~15碱基外切断磷酸二酯键；该结构可能与mRNA转运、翻译效率及稳定性有关。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"40afd43b","s":"b","g":"b04","n":"5′帽子结构","e":"5′ Cap structure","d":"真核生物mRNA 5′端的修饰结构。RNA聚合酶Ⅱ开始转录不久、RNA链尚未超过20~30个核苷酸时，5′端即被加上一个7-甲基鸟苷（m7G）残基；该核苷酸以与正常3′-5′连接相反的取向加到转录物上，形成5′-5′三磷酸桥，反应由鸟苷酰转移酶催化，随后还可甲基化形成Cap0、Cap1和Cap2。帽子是翻译起始的必要结构，可保护mRNA免遭5′外切核酸酶攻击。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"7e3c19ee","s":"b","g":"b04","n":"snRNA（核内小分子RNA）Small nuclear RNA","e":"","d":"存在于细胞核中的小分子RNA，是真核生物转录后加工过程中RNA剪接体的主要成分，参与mRNA前体的加工。哺乳动物中snRNA长度约100~215个核苷酸，一直存在于细胞核中，与40种左右的核内蛋白质共同组成剪接体，在RNA转录后加工中起重要作用。snRNA包括U1、U2、U4、U5、U6等，胞质中的小分子RNA则称为scRNA。剪接体由snRNA与约40种核内蛋白质组成，负责识别内含子边界并完成剪接。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"ce641dee","s":"b","g":"b04","n":"16S rRNA","e":"","d":"原核生物核糖体小亚基（30S亚基）中的rRNA，30S亚基由16S rRNA与蛋白质组成。16S rRNA以其在进化上的特征性序列，已被广泛用于细菌分类和鉴定的分子指标：通过比较各类生物16S rRNA的基因序列，从序列差异计算进化距离，可绘出生物进化树；其分析原理是从微生物样本中获得16S rRNA序列信息，与数据库比较以确定其在进化树中的位置，从而鉴定样本中的微生物种类。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"3f3240be","s":"b","g":"b04","n":"tRNA的三叶草二级结构","e":"Cloverleaf structure of tRNA","d":"tRNA的二级结构形式，单股tRNA链通过自身折叠形成四个螺旋区和四个环的基本结构，类似一个三叶草。tRNA均为74~95个核苷酸的小分子，5′端总是磷酸化、5′末端往往是pG，3′端是CpCpAOH序列；四个环为二氢尿嘧啶环（8~12个碱基）、反密码子环（7个核苷酸）、TψC环（7个核苷酸）和额外环（3~18个碱基），三级结构呈倒L形。四个螺旋区中，3′端与5′端核苷酸配对形成氨基酸接受茎。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"cd3ab595","s":"b","g":"b04","n":"氨基酸接受臂","e":"Amino acid acceptor arm","d":"tRNA 3′端均为CCA-OH序列，氨基酸接在腺苷酸残基上，这一CCA-OH序列称为氨基酸接受臂；3′-端第5~11位核苷酸与5′-端第1~7位核苷酸形成的螺旋区称氨基酸接受茎。所有tRNA的3′端都具CCA-OH，该序列与氨基酸接受茎共同构成tRNA装载氨基酸的一端，是tRNA携带氨基酸并参与蛋白质合成的结构基础。氨基酸与3′端腺苷酸残基的3′-OH相连，形成氨酰-tRNA。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"491c50ee","s":"b","g":"b04","n":"反密码子","e":"Anticodon","d":"tRNA反密码子环中处于34、35、36位的3个碱基，该环由7个核苷酸组成。反密码子通过碱基配对识别mRNA上的密码子，从而在蛋白质合成中把核酸的碱基序列信息转换为氨基酸序列。1966年Crick在遗传密码破译工作结束时提出摆动学说，说明反密码子与密码子配对时第三位碱基的配对具有一定灵活性；tRNA三级结构呈倒L形，反密码子位于其一端。反密码子与密码子的配对遵循碱基互补原则，摆动学说解释了第三位碱基配对的灵活性。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"4d08d77f","s":"b","g":"b04","n":"二氢尿嘧啶环","e":"Dihydrouridine loop, D-loop","d":"tRNA四个环之一，由8~12个碱基组成，含有1~3个修饰碱基（D）。它与反密码子环、TψC环、额外环共同构成tRNA三叶草二级结构的四个环，并与四个螺旋区一起使tRNA折叠成三叶草形。tRNA碱基的修饰有83种，每个tRNA约含有10~15个稀有碱基，如ψ、甲基化的嘌呤和嘧啶核苷、二氢尿苷、胸腺嘧啶核苷和辫苷等；TψC环参与tRNA与核糖体表面的结合。D环中的二氢尿苷由尿苷还原生成，属于修饰碱基。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"c05cdf7a","s":"b","g":"b04","n":"RNA编辑","e":"RNA editing","d":"发生在mRNA水平上的RNA加工方式，多数为插入碱基。RNA的加工类型列为切割、修剪、剪接、编辑和修饰五种，编辑是其中之一。编辑过程可由向导RNA引导，形成编辑体，以gRNA内部的序列作为模板对转录物进行校正，从而改变mRNA的序列信息，产生与基因编码不同的蛋白质。RNA编辑是RNA水平上改变遗传信息的方式，使基因编码的蛋白质序列与DNA序列不完全一致，是RNA加工类型之一。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"d7f16ece","s":"b","g":"b04","n":"miRNA（微小RNA）MicroRNA","e":"","d":"一类内生的、长度约20~24个核苷酸的小RNA，由发夹结构的约70~90个碱基大小的单链RNA前体经Dicer酶加工后生成，在细胞内具有多种重要的调节作用。每个miRNA可以有多个靶基因，几个miRNA也可以调节同一个基因，这种复杂的调节网络体现了基因表达调控的精细性，可见miRNA在基因表达调控中具有重要地位。miRNA属于不产生蛋白质的小RNA，与siRNA、反义RNA一样通过与mRNA互补来调控基因表达。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"04b3f461","s":"b","g":"b04","n":"RNA干扰","e":"RNA interference, RNAi","d":"通过dsRNA介导特异性降解同源序列mRNA，从而特异抑制相应基因表达的现象。早期通过导入全长dsRNA，细胞内的长双链被RNA酶Ⅲ相关的核酸酶（Dicer）处理，产生短的（21~25个核苷酸）双链RNA片段，发挥基因沉默作用。这种短的双链RNA片段称为siRNA，它与eIF2c、Gemin3、Gemin4等蛋白结合形成沉默复合体（RISC），介导序列特异的RNA降解。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"2496362c","s":"b","g":"b04","n":"siRNA（小干扰RNA）Small interfering RNA","e":"","d":"RNA干扰过程中产生的短双链RNA片段，长21~25个核苷酸，由导入细胞的长双链RNA被Dicer酶处理生成，发挥基因沉默作用。siRNA通过与eIF2c、Gemin3、Gemin4等蛋白结合形成沉默复合体（RISC），介导序列特异的RNA降解，从而抑制相应基因的表达。它与miRNA、反义RNA同属不产生蛋白质、可调控基因表达的小RNA，在个体发育与细胞分化中起作用。siRNA的生成依赖Dicer酶，是RNA干扰的效应分子。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"63559b7d","s":"b","g":"b04","n":"反义RNA Antisense RNA, asRNA","e":"","d":"指与mRNA互补的RNA分子，能与mRNA分子特异性地互补结合，从而抑制该mRNA的加工与翻译，是原核细胞中基因表达调控的一种方式。按其作用机制可分三类：Ⅰ类直接作用于靶mRNA的SD序列和/或编码区，引起翻译的直接抑制或促其被RNA酶Ⅲ降解；Ⅱ类与SD序列上游非编码区结合，阻止核糖体结合；Ⅲ类直接抑制靶mRNA的转录。人工合成反义RNA的基因并导入细胞后转录出反义RNA，可抑制特定基因表达，提示肿瘤基因治疗的可能。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"d87f1ea8","s":"b","g":"b04","n":"CRISPR","e":"","d":"成簇的规律间隔的短回文重复序列，是最新出现的一种由RNA指导的Cas9核酸酶对靶向基因进行编辑的技术，即强大的基因组编辑技术，可对生物的DNA序列进行修剪、切断、替换或添加。其重复序列长度在24~48 bp，重复次数最高可达250次，被26~72 bp的间隔序列隔开；crRNA通过碱基配对与tracrRNA结合形成双链，二者复合体指导Cas9在靶定位点切断双链DNA。","src":"第12讲 核酸化学3：RNA的结构和特性"},{"id":"805eca6b","s":"b","g":"b05","n":"碳水化合物","e":"Carbohydrates","d":"糖类的总称，化学本质为多羟基醛、多羟基酮及其衍生物，或能水解为多羟基醛、多羟基酮及其衍生物的物质；主要元素为C、H、O，另有少量N、S、P。地球上每年光合作用可转化超过1000亿吨的CO2和H2O为纤维素等植物产物，其氧化是多数非光合细胞的中心产能途径。不溶性多糖是细菌与植物细胞壁以及动物结缔组织的结构及保护成分；其他多糖润滑骨骼关节，参加细胞间的识别与粘附；更复杂的多糖共价结合蛋白质和脂，形成糖复合物。","src":"第13讲 糖与糖生物化学1"},{"id":"d54cde92","s":"b","g":"b05","n":"单糖","e":"Monosaccharides","d":"不能再水解为其他糖的糖，是糖类中最简单的单位，化学本质为多羟基醛或多羟基酮。按碳原子数分为丙糖、丁糖、戊糖和己糖，按羰基类型又分为醛糖与酮糖：五碳醛糖有核糖、阿拉伯糖、木糖、来苏糖，六碳醛糖有阿洛糖、阿卓糖、古洛糖、艾杜糖、塔罗糖、葡萄糖、半乳糖、甘露糖，六碳酮糖有果糖。单糖都有不对称碳，故具旋光性，都有甜度，多羟基使其易溶于热水而不溶于乙醚、丙酮等有机溶剂。","src":"第13讲 糖与糖生物化学1"},{"id":"ed08c807","s":"b","g":"b05","n":"寡糖","e":"Oligosaccharides","d":"糖类中能水解为其他糖的一类，由2至十几个单糖通过糖苷键连接而成，一般易溶于水、具有甜味，其中最简单的是二糖。按聚合程度可分为二糖（蔗糖、麦芽糖、乳糖）、三糖（棉籽糖）以及其他寡糖（血型糖、活性糖等），最重要的二糖即蔗糖、麦芽糖和乳糖。寡糖既是独立存在的小分子糖，也是糖复合物中糖链的常见形式；其末端半缩醛羟基是否游离决定有无还原性与变旋现象，连接单糖的键为糖苷键，可被酸或相应的糖苷酶水解。","src":"第13讲 糖与糖生物化学1"},{"id":"2350a31b","s":"b","g":"b05","n":"同多糖","e":"Homoglycans","d":"多糖的一类，又称同聚糖，指水解后只生成同一种单糖的高分子聚合物，即由同一单糖残基聚合而成的多糖。常见的例子有淀粉、糖元、纤维素、几丁质、糖苷等，它们分别由葡萄糖或N-乙酰氨基葡萄糖残基构成，在链状或分支结构、遇碘显色、水解产物等方面各不相同。同多糖与水解产物不止一种单糖或单糖衍生物的杂多糖相对，二者共同构成多糖按水解产物的分类；同多糖多为贮能物质或结构物质。","src":"第13讲 糖与糖生物化学1"},{"id":"d09429b2","s":"b","g":"b05","n":"杂多糖","e":"Heteroglycans","d":"多糖的一类，又称杂聚糖，指水解产物不止一种单糖或单糖衍生物的多糖，与同多糖相对。常见的例子有透明质酸、肝素、硫酸软骨素、硫酸皮肤素等，它们由氨基己糖与己糖醛酸以及硫酸等脱水缩合而成，糖基交替排列成线性顺序，分子中的羧基及硫酸等阴离子可通过静电作用与蛋白质等大分子结合。杂多糖溶液粘性较大，分布很广，大多以蛋白多糖形式存在，并进一步与胶原蛋白结合构成结缔组织基质的重要成分。","src":"第13讲 糖与糖生物化学1"},{"id":"52727571","s":"b","g":"b05","n":"糖的衍生物","e":"Sugar Derivatives","d":"指糖的氧化产物、还原产物、氨基取代物及糖苷化合物等，由单糖的羟基、羰基经氧化、还原、取代或成苷后生成，如氨基葡萄糖、N-乙酰氨基葡萄糖、糖的硫酸酯等。糖醛酸类主要有四种，即D-葡萄糖醛酸、D-甘露糖醛酸、D-半乳糖醛酸及L-艾杜糖醛酸，另有唾液酸、胞壁酸、脱氧糖、甲基糖等。它们是糖复合物的重要组成部分：N-乙酰氨基葡萄糖参与构成几丁质与糖胺聚糖，唾液酸代表一类神经氨酸，广泛存在于细菌和动物组织中，是糖脂和糖蛋白的组成成分。","src":"第13讲 糖与糖生物化学1"},{"id":"1581668a","s":"b","g":"b05","n":"构型","e":"Configuration","d":"指一个分子由于其各原子特有的空间排列而使该分子具有特定的立体化学结构；当一种物质由一种构型转变为另一种构型时，要求有共价键的断裂或重新形成。单糖的构型以甘油醛为参照标准，甘油醛C2为手性碳，与其相连的-OH在右边的定为D型、在左边的定为L型，二者互为对映体，具对映体的结构又称手性结构。手性碳不止一个时特规定：离羰基最远的不对称碳上的-OH方向决定糖的构型，在右为D型、在左为L型。构型与旋光方向并不呈一致对应。","src":"第13讲 糖与糖生物化学1"},{"id":"1f40871d","s":"b","g":"b05","n":"差向异构体","e":"Epimers","d":"立体异构的一种，指两个分子仅有一个不对称碳原子的构型不同、其余部分结构完全相同，二者互为镜像非对映体。如葡萄糖与甘露糖的差别在C2上的-OH位置，葡萄糖与半乳糖的差别在C4上的-OH位置，两两之间除该不对称碳外结构完全一致。由于成脎反应只发生在C1和C2，仅在第二碳上构型不同而其他碳构型相同的差向异构体必然生成同一个脎，故D-葡萄糖、D-甘露糖与D-果糖生成相同的糖脎，此性质可用于研究糖的构型。","src":"第13讲 糖与糖生物化学1"},{"id":"97185c10","s":"b","g":"b05","n":"旋光性","e":"Optical Rotation","d":"指物质使平面偏振光发生偏转的能力。葡萄糖及绝大多数糖都有旋光性，因为糖分子中都含手性碳；旋光性和旋光度由糖分子中所有手性碳上羟基的方向所决定，以右旋（d或+）或左旋（l或-）表示。构型与旋光性是两个不同概念，二者不一定一致：D型糖不一定是右旋糖，L型糖也不一定是左旋糖。对葡萄糖而言D型正好右旋、L型正好左旋，即D-[+]-Glc与L-[-]-Glc，天然葡萄糖为右旋，属D型。一切糖类都有不对称碳，因此都具旋光性。","src":"第13讲 糖与糖生物化学1"},{"id":"5ef52d22","s":"b","g":"b05","n":"变旋现象","e":"Mutarotation","d":"醛糖的C1或酮糖的C2成环时产生α和β一对异构体（异头物），在水溶液中二者很快互相转变成为混合物，溶解过程中旋光度随之改变，这种现象即变旋现象，由α、β异头物自发互变所导致。新配制的葡萄糖[α]D20为+112°，平衡时为+52.7°，其中α型约占36.2%、β型约占63.8%，醛式直链比例极少，故葡萄糖对Schiff化反应不灵敏。糖苷因无半缩醛羟基，不呈现变旋现象，也无还原糖的反应。","src":"第13讲 糖与糖生物化学1"},{"id":"d6272651","s":"b","g":"b05","n":"构象","e":"Conformation","d":"指一个分子中不改变共价键结构、仅靠单键的旋转或扭曲而改变分子中基团在空间排布位置所产生的不同排列方式，与需断裂共价键才能互变的构型不同。根据X射线晶体分析，葡萄糖吡喃环与环己烷的椅式结构相似，β-葡萄糖的可能构象有2种椅式和6种船式，主要是A椅式。椅式构象中基团有直立键（axial）与平伏键（equatorial）之别，故同一种糖可因构象不同而稳定性不同。构象异构体之间可自由互变，无需断裂共价键。","src":"第13讲 糖与糖生物化学1"},{"id":"a2ed2319","s":"b","g":"b05","n":"高碘酸氧化","e":"Periodate Oxidation","d":"糖类结构测定的一种化学方法。高碘酸又称过碘酸，是碘(VII)的含氧酸，有HIO4和H5IO6两种形式。糖类用高碘酸氧化时碳链发生断裂：相邻两个碳原子都带有羟基，或一个带有羟基、另一个带有醛基，其碳-碳键都发生断裂，生成断裂碳的醛基或羧基化合物；反应常是定量的，每摩尔碳-碳键消耗1摩尔高碘酸，因此高碘酸可用于糖类结构的测定。1928年Malaprada发明该法，1932年Fleury和Lange把方法完善化并用于糖化学研究。","src":"第13讲 糖与糖生物化学1"},{"id":"27166870","s":"b","g":"b05","n":"还原糖","e":"Reducing Sugar","d":"凡对斐林试剂、土伦试剂及班尼迪特试剂呈阳性反应的糖称为还原糖，呈阴性反应的为非还原糖，判据是分子中有无游离的半缩醛羟基。斐林试剂为硫酸铜和碱性酒石酸钾钠，土伦试剂为硝酸银的氨水溶液，班尼迪特试剂由柠檬酸、硫酸铜、碳酸钠配制。葡萄糖含醛基，能被弱氧化剂（如碱性Cu2+）氧化生成葡萄糖酸，蓝色的Cu2+被还原为砖红色的Cu2O；正常人尿液用班氏试剂检测为阴性，血糖高于160-180 mg/dL时呈阳性，但该法特异性差。","src":"第13讲 糖与糖生物化学1"},{"id":"c85311bc","s":"b","g":"b05","n":"糖苷与糖苷键","e":"Glycoside & Glycosidic Bond","d":"单糖环状结构中的半缩醛羟基比其他羟基活泼，可与其他分子的-OH（或活性H原子）反应，缩去一分子水而成糖苷，又称甙或配糖体；由葡萄糖衍生的糖苷叫葡萄糖苷，失水时形成的键叫糖苷键。苷似醚但不是醚，比一般醚键易形成也易水解。糖苷从结构上看是缩醛，在碱性条件下稳定，可被温和的酸性条件水解生成糖和配基，而普通醚键在温和酸性下稳定，只有强HX作用才分解。糖苷无变旋现象，也无还原糖的反应；酶也能立体专一地促使糖苷水解。","src":"第13讲 糖与糖生物化学1"},{"id":"4e6bed27","s":"b","g":"b05","n":"脎（成脎反应） Osazone","e":"","d":"一分子含半缩醛羟基的糖与三分子苯肼反应，在糖的1,2-位形成二苯腙，产物称为脎，此反应即成脎反应（苯肼反应）。醛糖的醛基先与苯肼反应生成苯腙，过量的苯肼进一步与苯腙反应生成脎，每个脎分子中含2分子苯肼，第三个苯肼被转化为苯胺和氨。脎的溶解度小、易成结晶，不同糖脎晶体形状不同、熔点不同、形成速度也不同，且都是黄色晶体，可作为糖的定性鉴定；反应只涉及C1和C2，故可用于研究糖的构型。","src":"第13讲 糖与糖生物化学1"},{"id":"7b121b62","s":"b","g":"b05","n":"Molish反应","e":"Molish Reaction","d":"糖的显色反应和定性鉴定方法之一，又称α-萘酚反应。糖在浓硫酸或浓盐酸的作用下脱水形成糠醛及其衍生物，后者与α-萘酚作用形成紫红色复合物，在糖液和浓硫酸的液面间形成紫环，因此又称紫环反应。自由存在和结合存在的糖均呈阳性反应，所有的糖都呈Molish反应；此外各种糠醛衍生物、葡萄糖醛酸以及丙酮、甲酸和乳酸也呈颜色近似的阳性反应。阴性反应证明没有糖类物质存在，阳性反应只说明有糖存在的可能性，需通过其他定性试验进一步确定。","src":"第13讲 糖与糖生物化学1"},{"id":"574a4ed7","s":"b","g":"b05","n":"蒽酮反应","e":"Anthrone Reaction","d":"糖的显色反应之一，可用于定量测定样品中的总糖。糖经浓酸作用后生成的糠醛及其衍生物，与蒽酮（10-酮-9,10-二氢蒽）作用生成蓝绿色复合物，颜色的深浅与糖的含量相关，故可借此进行比色定量。该反应与Molish反应一样依赖糖在浓酸下脱水生成糠醛类物质，因此对各类糖均可显色、专一性不强，它测定的是样品中的总糖而不能区分糖的种类，故常用于糖类总量的测定，可用于糖类的定量分析。","src":"第13讲 糖与糖生物化学1"},{"id":"0560d4cd","s":"b","g":"b05","n":"Seliwanoff反应","e":"Seliwanoff Reaction","d":"鉴定酮糖的特殊显色反应。酮糖在酸的作用下较醛糖更易生成羟甲基糠醛，后者与间苯二酚作用生成鲜红色复合物，反应仅需20-30秒；醛糖在浓度较高时或长时间煮沸，才产生微弱的阳性反应，故可借此区分酮糖与醛糖。Seliwanoff试剂为0.5 g间苯二酚溶于1升盐酸（H2O与HCl体积比2:1）中，需临用前配制。该反应迅速、现象明显，是糖类定性鉴定的常用方法之一。该反应迅速、现象明显，常用于酮糖的鉴定。","src":"第13讲 糖与糖生物化学1"},{"id":"ccf12b1b","s":"b","g":"b05","n":"Barfoed试验","e":"Barfoed Test","d":"用于区别单糖和还原二糖的定性试验。在酸性溶液中，单糖和还原二糖的还原速度有明显差异，Barfoed试剂为弱酸性；单糖在Barfoed试剂作用下能将Cu2+还原成砖红色的氧化亚铜，时间约为3分钟，而还原二糖则需20分钟左右。因此该反应可用于区别单糖与还原二糖。当加热时间过长时，非还原性二糖经水解后也能呈现阳性反应，故须控制加热时间。该试验操作简便，是糖类分析的初步方法。","src":"第13讲 糖与糖生物化学1"},{"id":"de5534e0","s":"b","g":"b05","n":"棉子糖","e":"Raffinose","d":"一种三糖，又称蜜三糖、棉籽糖，分子式C18H32O16，存在于豆形果实、甘蓝、椰菜、芦笋等蔬菜和所有谷类等许多植物中，棉籽与桉树分泌物中尤多。其旋光度[α]t=105.2°，不能还原斐林试剂，与酸共热水解生成葡萄糖、果糖及半乳糖，结构为α-Gal[α(1→6)]-α-Glc[α,β(1→2)]-β-Fru。棉籽糖属低聚糖，是人体内双歧杆菌和乳杆菌等有益菌的增殖因子，不为人体吸收，热稳定性高，可用作食品原料及冷冻精液、活器官移植的稳定剂。","src":"第13讲 糖与糖生物化学1"},{"id":"8a76c4b4","s":"b","g":"b05","n":"蔗糖的转化","e":"Inversion of Sucrose","d":"蔗糖水解反应中伴随有旋光符号由+到-的变化，这种水解称为蔗糖的转化。蔗糖是常用食糖，甜度大、易结晶、溶于水，甘蔗和甜菜中含量丰富，分子式C12H22O11，由一分子α-D-葡萄糖和一分子β-D-果糖组成，既是葡萄糖苷又是果糖苷，结构为α-D-Glc基β-D-Fru[β-1,2]。因无异头形式、无半缩醛羟基，蔗糖不能还原Tollens和Fehling试剂、不能成脎、不变旋。蔗糖的转化即指这一旋光符号的变化，可据以判断蔗糖是否已被水解。","src":"第13讲 糖与糖生物化学1"},{"id":"218459d2","s":"b","g":"b05","n":"多糖","e":"Polysaccharides","d":"由多个单糖或单糖衍生物聚合而成，缩合时单糖分子以糖苷键相连，一般无甜味、无还原性，在酸或酶的作用下可水解为双糖、寡糖或多糖；重要的有淀粉、糖元、纤维素、几丁质、粘多糖等，可分为同多糖和杂多糖。功能包括能量作用、结构作用和生物活性作用：淀粉、糖元贮存能量，纤维素、几丁质构成支持结构，多糖还具有免疫调节、抗肿瘤、抗感染、抗凝血、降血糖、降血脂等活性。多糖广泛存在于细胞膜及细胞壁，已从自然界提取到好几百种。","src":"第14讲 糖与糖生物化学2"},{"id":"e55e1802","s":"b","g":"b05","n":"直链淀粉","e":"Amylose","d":"淀粉中能被热水处理25分钟所溶解的部分，又称可溶性淀粉，与不溶解的支链淀粉相对。直链淀粉平均由250-300个α-D-葡萄糖通过α-1,4糖苷键相连，链旋转卷曲成螺旋状，每6个葡萄糖残基盘旋一圈，遇碘呈（深）蓝色；其水解的双糖为麦芽糖，单糖为葡萄糖。淀粉遇碘显色与聚合度有关，在一定的聚合度范围内，随聚合度增加，包合物颜色由无色、橙色、淡红、紫色到蓝色，故直链淀粉呈蓝色。","src":"第14讲 糖与糖生物化学2"},{"id":"e3951ef8","s":"b","g":"b05","n":"支链淀粉","e":"Amylopectin","d":"淀粉中不能被热水处理25分钟溶解的部分。支链淀粉由2000-22000个葡萄糖残基组成，大约每24-30个葡萄糖残基就有一个α-1,6糖苷键形成的分支，遇碘呈紫（红）色；水解时只生成一种双糖，即（+）麦芽糖。它与直链淀粉共同构成淀粉，后者为α-1,4连接的螺旋链、遇碘呈蓝色。淀粉可经红色糊精、无色糊精逐步水解为麦芽糖和葡萄糖，糊精遇碘呈蓝色、紫色、橙色等。支链淀粉的分支多、分支短，故遇碘显紫红色。","src":"第14讲 糖与糖生物化学2"},{"id":"c386a926","s":"b","g":"b05","n":"糖元","e":"Glycogen","d":"又称动物淀粉，细菌细胞中也有存在，是动物组织内主要的贮藏多糖，肝脏、肌肉中含量多，分别称为肝糖元、肌糖元。结构与支链淀粉相似，但分支长度较短，一般由8-12个葡萄糖残基组成，分支多，分子量高达10^6-10^8。遇碘呈红褐色或棕红色，水解终产物是葡萄糖，对动物体血糖水平的调节重要。与甘油三酯相比，人体可能只贮存少于一天所需要能量的糖元，故糖元是短期快速的能量储备。","src":"第14讲 糖与糖生物化学2"},{"id":"f0ceaec0","s":"b","g":"b05","n":"纤维素","e":"Cellulose","d":"自然界中分布最广的糖，以纤维二糖为基本单位连接而成，纤维状、僵硬、不溶于水、不分支，约由10000-15000个β-D-葡萄糖残基以β(1-4)糖苷键连接而成。水解需要高温、高压和酸，人体消化酶不能水解纤维素，食草动物利用肠道寄生菌分泌的纤维素酶将其部分水解为葡萄糖。1838年法国科学家Payen从木材中提取分离出该物质，因是在破坏细胞组织后得到，遂以cell（细胞）与lose（破坏）组合命名为cellulose。","src":"第14讲 糖与糖生物化学2"},{"id":"109b2ef6","s":"b","g":"b05","n":"半纤维素","e":"Hemicellulose","d":"木材中除纤维素以外的其他糖，是由两种或两种以上单糖残基组成的不均一聚糖，大多带有短侧链。构成半纤维素的单糖主要有D-木糖、L-阿拉伯糖、D-半乳糖、D-甘露糖、D-葡萄糖和4-O-甲基-D-葡萄糖醛酸等。它与纤维素、木质素一起构成木材，针叶木中纤维素占50-55%、半纤维素占15-20%、木质素占25-30%。半纤维素并非均一的纤维素，而是杂聚糖，属于植物细胞壁的基质成分，是木材化学利用的重要对象。","src":"第14讲 糖与糖生物化学2"},{"id":"35ecdd3e","s":"b","g":"b05","n":"木质素","e":"Lignin","d":"一种复杂的、非结晶性的、三维网状酚类高分子聚合物，由苯丙烷结构单元组成，广泛存在于高等植物细胞中。木质素与纤维素、半纤维素等一起构成超分子体系，作为纤维素的粘合剂，以增强植物体的机械强度；它是仅次于纤维素的第二大可再生资源，全球每年可产生约6×10^14 t。木材是纤维素化学工业的主要原料，其主要成分即纤维素、半纤维素和木质素，针叶木中木质素约占25-30%。","src":"第14讲 糖与糖生物化学2"},{"id":"3c69d276","s":"b","g":"b05","n":"几丁质","e":"Chitin","d":"又称壳多糖，存在于节肢动物昆虫、甲壳类动物（虾、蟹）的外骨骼及真菌细胞壁，是地球上丰度仅次于纤维素的第二大类糖。由N-乙酰-D-葡萄糖胺以β(1→4)糖苷键缩合而成，分子线状不分支，即N-乙酰-D-葡萄糖胺的β-1,4同聚物。其降解产物N-乙酰葡萄糖胺和聚葡萄糖胺能刺激迷走神经，通过副交感神经的兴奋使毛细血管扩张；几丁质无毒、无味、可生物降解，可用于保健食品、手术缝合线、止血和伤口被覆材料、药物运送载体、食品增稠剂及化妆品等。","src":"第14讲 糖与糖生物化学2"},{"id":"9017d236","s":"b","g":"b05","n":"右旋糖酐","e":"Dextran","d":"又称葡聚糖，是利用微生物（蔗糖经肠膜状明串珠菌发酵）制造的高分子葡萄糖聚合物，由多个葡萄糖分子通过α-1,6、α-1,4、α-1,3糖苷键组合而成。分子量平均75000左右的为高分子右旋糖酐，是血浆代用品，能提高血浆胶体渗透压，将组织水分吸到血中维持血容量，用于出血性休克和创伤性休克；分子量20000-40000的为低分子量右旋糖酐，主要降低血液粘滞度、防止血栓形成，改善微循环并有利尿作用。","src":"第14讲 糖与糖生物化学2"},{"id":"40e60ceb","s":"b","g":"b05","n":"杂多糖（糖胺聚糖） Heteropolysaccharides","e":"","d":"由不止一种单糖或单糖衍生物组成的多糖，其他名称包括糖胺聚糖、粘多糖、酸性糖胺聚糖及氨基多糖等。由氨基己糖与己糖醛酸以及硫酸等脱水缩合而成，溶液粘性较大，分子中的羧基及硫酸等阴离子通过静电作用与蛋白质等大分子结合；分布很广，大多以蛋白多糖形式存在，并进一步与胶原蛋白结合构成结缔组织基质的重要成分，如透明质酸、硫酸软骨素、硫酸皮肤素等。已证实此类成分具有抗凝血、降血脂、抗病毒、抗肿瘤及抗辐射等多种药理活性。","src":"第14讲 糖与糖生物化学2"},{"id":"2c1fb993","s":"b","g":"b05","n":"透明质酸","e":"Hyaluronic Acid","d":"又名玻璃酸，一种大分子酸性粘多糖，1934年由Meyer和Palmer首先从牛眼玻璃体中分离。主要存在于结缔组织如眼球玻璃体、鸡冠、脐带、软骨等，细菌中也有存在。它是结构最简单的一种糖胺聚糖，有重复的二糖结构单位，D-葡萄糖醛酸与N-乙酰葡萄糖胺以β-1,3糖苷键相连，二糖单位间以β-1,4连接，链状无分支，分子量在100-1000万之间，不含硫酸取代基，生理pH下为多聚阴离子。主要在组织中吸着水，起润滑和保护作用。","src":"第14讲 糖与糖生物化学2"},{"id":"300a6cfa","s":"b","g":"b05","n":"硫酸软骨素","e":"Chondroitin Sulfate","d":"软骨的主要成分，广泛存在于结缔组织、筋腱、皮肤等。分子量一般低于10万（约250个重复二糖），个别可超过30万，有4-硫酸软骨素（硫酸软骨素A）和6-硫酸软骨素（硫酸软骨素C）两种；二糖单位为D-葡萄糖醛酸与N-乙酰半乳糖胺以β-1,3相连，糖链生成后由专一性酶在4位或6位进行硫酸化。硫酸软骨素与胶原纤维和弹力纤维一起存在，具有保水性，参与制造骨骼、促进肉芽形成使伤口提早痊愈，并保持关节滑顺，可用于防治冠心病等。","src":"第14讲 糖与糖生物化学2"},{"id":"09ba357c","s":"b","g":"b05","n":"硫酸皮肤素","e":"Dermatan Sulfate","d":"又称硫酸软骨素B，最初从猪皮中分离，存在于许多动物组织，如猪肠胃粘膜、脐带、肌腱等。其重复二糖单位为L-艾杜糖醛酸与N-乙酰半乳糖胺以α-1,3相连，与硫酸软骨素同属糖胺聚糖，但所含糖醛酸为L-艾杜糖醛酸而非D-葡萄糖醛酸。在结缔组织基质成分与组织机械性能的关系中，硫酸皮肤素见于肌腱、大血管等组织，与其抗张强度、延性等机械性能相关。它是结缔组织基质中的一类重要糖胺聚糖。","src":"第14讲 糖与糖生物化学2"},{"id":"3c6f40b2","s":"b","g":"b05","n":"肝素","e":"Heparin","d":"最早由肝脏和心脏中分离到，以肝脏中丰富，广泛存在于哺乳动物组织和体液中，猪肠粘膜是较好的材料来源。结构复杂，由D-葡萄糖胺与L-艾杜糖醛酸或D-葡萄糖醛酸组成二糖单位，同时C2上的-NH2和C6上的-OH可分别被硫酸酯化。常用作抗凝剂，防止血栓形成，输血时添加肝素作抗凝剂；其抗凝血作用包括增强抗凝血酶3与凝血酶的亲和力、加速凝血酶失活、抑制血小板粘附聚集、增强蛋白c活性，并有调血脂、抗炎、抗过敏作用。","src":"第14讲 糖与糖生物化学2"},{"id":"ab90be0c","s":"b","g":"b05","n":"结合糖（糖复合物） Glycoconjugates","e":"","d":"糖与非糖物质如脂类或蛋白共价结合形成的复合物，又称糖复合物或复合多糖，包括糖脂、糖蛋白、蛋白多糖等。糖脂和脂多糖是细胞膜上的组分，寡糖是亲水的头部基团，作为糖蛋白的特异识别位点；在细胞表面与各种识别事件相关，如鞘糖脂决定人类血型A、B、O。糖复合物上的糖链承担信息功能，参与细胞-细胞及细胞-胞外基质的相互作用，可作为细菌、病毒等病原体的受体，或作为激素等信息分子的受体。","src":"第14讲 糖与糖生物化学2"},{"id":"2b823346","s":"b","g":"b05","n":"脂多糖","e":"Lipopolysaccharides","d":"革兰氏阴性菌外膜显著的表面特征，是脊椎动物免疫体系针对细菌感染产生抗体的主要靶位，决定了细菌株系的血清型。种类多，革兰氏阴性菌细胞壁含有十分复杂的脂多糖，其分子结构一般包括三部分：外层专一性寡糖链—中心多糖链—脂质部分。一些细菌的脂多糖对人和其他动物有毒，是细菌内毒素的主要成分，当革兰氏阴性细菌崩裂时释出，是很强的发热原；内毒素作用于巨噬细胞等，使之产生IL-1、IL-6和TNFα等细胞因子，作用于下丘脑体温调节中枢而促使体温升高。","src":"第14讲 糖与糖生物化学2"},{"id":"ed76e490","s":"b","g":"b05","n":"糖蛋白","e":"Glycoproteins","d":"自然界中分布最广的一类复合糖，几乎所有的细胞都能合成，由短链寡糖与蛋白质共价连接而成。连接通过两种不同类型的糖苷键：一种是糖链上的半缩醛羟基与肽链上Thr、Ser、HyPro、HyLys的-OH形成O-糖苷键，另一种是与肽链上Asn的酰胺氮形成N-糖苷键。糖蛋白上共价连接的糖链通常是寡糖，分子量较小，一般占糖蛋白重量的1-70%，但永远达不到蛋白多糖中的99%；研究最多的是红细胞膜上的血型糖蛋白，含16个寡糖链，约占分子60%重量。","src":"第14讲 糖与糖生物化学2"},{"id":"2c22221a","s":"b","g":"b05","n":"蛋白聚糖","e":"Proteoglycans","d":"蛋白质与糖胺聚糖以共价键连成的大分子复合物，核心蛋白连在糖胺聚糖链上，是具有多聚阴离子的杂多糖，由氨基己糖和己糖醛酸交替排列成线性顺序，不同部位还有硫酸取代基。有三种不同的糖肽键连接：D-木糖与Ser的-OH形成O-糖肽键、N-乙酰葡萄糖胺与Asn形成N-糖肽键、N-乙酰半乳糖胺与Thr或Ser的-OH形成O-糖肽键。蛋白聚糖主要有维持或抑制细胞生长，以及在正常发育和病理条件下结合、贮存及向靶细胞释放生长因子和参与信号转导等作用。","src":"第14讲 糖与糖生物化学2"},{"id":"b64b2d1a","s":"b","g":"b05","n":"凝集素","e":"Lectins","d":"能与特定糖链结构结合的蛋白质，广泛存在于动物、植物、细菌和病毒中。凝集素可促进细胞与细胞之间的接触：一个细胞表面凝集素上的结合位点与另一细胞表面成列的糖类相互作用，从而实现识别与粘附。常见的凝集素包括伴刀豆球蛋白A、加纳籽凝集素4、麦胚凝集素、蓖麻毒素、半乳糖凝集素-1、多瘤病毒蛋白-1、流感病毒血凝素、肠毒素、霍乱毒素等，它们参与细胞表面寡糖的识别和粘附，是糖链信息功能得以实现的一类蛋白。","src":"第14讲 糖与糖生物化学2"},{"id":"c9cf7e53","s":"b","g":"b05","n":"糖生物学","e":"Glycobiology","d":"糖化学与糖生物学的交叉学科，主要研究糖链的结构和功能两个方面，内容包括糖化学、糖链生物合成、糖链在复杂生物系统中的功能和糖链操作技术。糖链在细胞内可修饰及调控蛋白质和脂类的结构与功能，在细胞外环境参与免疫应答、感染和癌症等过程中的细胞识别，但其作用机制还不完全清楚。1988年牛津大学Dwek在Annual Review of Biochemistry撰写了以“糖生物学”为题的综述，标志这一新分支学科的诞生。","src":"第14讲 糖与糖生物化学2"},{"id":"f37732c2","s":"b","g":"b05","n":"糖组学","e":"Glycomics","d":"在基因组学和蛋白质组学相继成为生物学重点研究领域后有望取得突破性进展的学科，研究聚糖的糖链结构及功能，涉及糖链结构与细胞发育、分化、进化、免疫反应、肿瘤转移、微生物感染等。糖链结构具有多样性、复杂性和微观不均一性，其一级结构不仅包括各糖基的排列顺序，还包括各糖基的环化形式、异头物构型、连接方式以及分支位点和分支糖链结构；6种单糖形成带分支的六糖有10^12种异构体，这种复杂性使糖链能携带巨大的生物信息。","src":"第14讲 糖与糖生物化学2"},{"id":"00714a31","s":"b","g":"b05","n":"糖工程学","e":"Glycoengineering","d":"随着糖生物学基础研究的发展，用于糖生物学研究的方法和基本技术，以及将基础研究成果进一步转化为生产技术等方面的研究倍受重视，由此兴起的学科即糖工程学。其内容与糖化学相关，包括对巨大糖类资源的开发利用，如由糖类生产燃料、由糖类制备化工原料以及粘合剂、食品添加剂等其他工业应用；还包括糖类的修饰和改造，以及研发糖类药物、营养品和保健品并用于疾病的预防和治疗，如糖类用作疫苗和免疫调节剂、酶抑制剂、药物导向及前生元等。","src":"第14讲 糖与糖生物化学2"},{"id":"421a9e39","s":"b","g":"b06","n":"生物脂类","e":"Biological Lipids","d":"一类范围很广的化合物，化学成分及结构差异极大，其定义的特点就是水不溶性（或脂溶性），因此多数脂类都易溶于乙醚、氯仿、己烷、苯等有机溶剂，而不溶于水。功能上，脂类可供给和储存能量，是生物膜的重要成分（约一半，包括磷脂、固醇、糖脂）；有些数量虽低，却作为酶的辅助因子、电子载体、光吸收色素、疏水稳定体、乳化剂、激素及胞间信息分子起关键作用；还有些脂类有防止机械损伤及防止热量散发的保护作用。","src":"第15讲 脂类和脂生物化学1"},{"id":"a4c4b5d6","s":"b","g":"b06","n":"单纯脂类","e":"Simple Lipids","d":"按化学结构及组成划分的一类脂，又称单纯脂质，分子中只含脂肪酸与醇形成的酯，不含磷酸、糖等其他成分，包括甘油三酯（脂肪、油）和蜡。甘油三酯由甘油与三分子脂肪酸酯化而成，是贮存能量的主要形式；蜡由长链脂肪酸与长链碳醇形成的酯构成，熔点较高、防水性强，多作为生物体的防水外被。单纯脂类与含磷酸或糖的复合脂类、以及异戊二烯类共同构成脂类的三大类，是脂类中最简单的形式。","src":"第15讲 脂类和脂生物化学1"},{"id":"5545ce0e","s":"b","g":"b06","n":"复合脂类","e":"Compound Lipids","d":"按化学结构及组成划分的一类脂，除脂肪酸和醇之外还含有磷酸、糖等其他成分，包括磷脂（甘油磷脂和鞘磷脂）和糖脂（脑苷脂和神经节苷脂）。甘油磷脂是磷脂酸的衍生物，以甘油为骨架，C1、C2上以酯键连两分子脂肪酸构成疏水的非极性尾，C3上的-OH连亲水的极性头；鞘磷脂则以鞘氨醇为骨架。复合脂类是生物膜的主要成分，与单纯脂类、异戊二烯类共同构成脂类的三大类。复合脂类因此不同于只含脂肪酸与醇的单纯脂类。","src":"第15讲 脂类和脂生物化学1"},{"id":"8df33723","s":"b","g":"b06","n":"异戊二烯类","e":"Isoprenes","d":"按化学结构及组成划分的一类脂，包括多萜类、固醇和类固醇类，由异戊二烯单体合成。此类化合物在生物体中数量很少，但常有特殊而重要的生物学活性，包括数千种类固醇及大量的类异戊二烯化合物，它们起着生物色素、酶的辅助因子、电子载体及传递细胞间信号等作用；固醇类还是生物膜的组成成分，以及胆汁酸、类固醇激素与维生素D等活性物质的前体，属活性脂而非贮能脂，多作为活性脂而非贮能脂。","src":"第15讲 脂类和脂生物化学1"},{"id":"be15a644","s":"b","g":"b06","n":"脂肪酸","e":"Fatty Acids","d":"碳链为4-36个碳的羧酸，一端为羧基（极性亲水头），另一端为碳氢链（非极性疏水尾），故是两性分子。碳链可为饱和的、不分支的，也可含有一个或多个双键，还可含有三碳的环或羟基。天然存在的脂肪酸多为顺式、双键非共轭（相互分开）、碳数为偶数。其中亚油酸、亚麻酸和花生四烯酸为人体必需脂肪酸。脂肪酸的熔点随碳链延长及饱和程度增加而升高，在水中溶解度则随链长增加而降低。故脂肪酸的熔点与溶解度都由碳链长度和双键数目决定。","src":"第15讲 脂类和脂生物化学1"},{"id":"c01516fa","s":"b","g":"b06","n":"必需脂肪酸","e":"Essential Fatty Acids","d":"人体自身不能合成、必须由食物提供的脂肪酸，包括亚油酸、亚麻酸和花生四烯酸。缺乏时影响机体代谢，表现为上皮细胞功能异常、湿疹样皮炎、皮肤角化不全、创伤愈合不良、对疾病抵抗力减弱、心肌收缩力降低、血小板聚集能力加强、生长停滞等。亚油酸和亚麻酸在体内可转化成具有重要生理作用的DHA（又名脑黄金），是婴儿脑部、视网膜发育所必需的营养素；亚油酸能降低血中胆固醇、防止动脉粥样硬化；花生四烯酸是体内合成前列腺素等的前体。","src":"第15讲 脂类和脂生物化学1"},{"id":"b3d7fe08","s":"b","g":"b06","n":"反式脂肪酸","e":"Trans Fatty Acid","d":"又称反式脂肪、逆态脂肪酸或转脂肪酸，是一种不饱和脂肪酸（单元不饱和或多元不饱和），化学结构包含一个或多个非共轭双键且构型为反式，定义中特别指明不包括含共轭双键的脂肪酸。它是油脂在“氢化”加工过程中的产物，精炼脱臭、部分氢化均可引入，也天然存在于反刍动物脂肪、乳及乳制品中，由瘤胃微生物氢化多不饱和脂肪酸而成，产物几乎全为反式18碳单烯酸。其危害包括增加心血管病、糖尿病危险、导致必需脂肪酸缺乏、抑制婴幼儿生长发育。","src":"第15讲 脂类和脂生物化学1"},{"id":"c5b5213f","s":"b","g":"b06","n":"甘油三酯","e":"Triacylglycerols","d":"脂肪酸与甘油形成的最简单的脂，也称三脂酰甘油、脂肪或中性脂肪，由甘油与三分子脂肪酸酯化而成。甘油与单个脂肪酸形成的酯称甘油单酯（单脂酰甘油），与2个脂肪酸形成的酯称甘油二酯（二脂酰甘油）；甘油酯中脂肪酸为同一种的称单纯甘油酯，两种或两种以上的称混合甘油酯，天然甘油酯多为混合甘油酯。甘油三酯因碳链长且还原度高，较糖贮藏的能量更多（二倍），其疏水性保证了运输中不必运送额外水化物的重量。","src":"第15讲 脂类和脂生物化学1"},{"id":"3e68c3c1","s":"b","g":"b06","n":"脂肪和油","e":"Fats and Oils","d":"天然甘油三酯的两种形态。形成甘油酯的脂肪酸种类很多，可以是饱和的或不饱和的；含不饱和脂肪酸较多的甘油酯在室温下为液体，被称为油，多见于植物体；含饱和脂肪酸较多的甘油酯在室温下为固体，被称为脂肪，多见于动物体。二者化学本质同为甘油三酯，差别只在脂肪酸组成，因而熔点、流动性不同。脂肪和油是食物中能量最集中的形式，也是人体脂肪细胞和植物种子中贮存能量的主要物质，人体脂肪组织约有15-20 kg甘油酯。","src":"第15讲 脂类和脂生物化学1"},{"id":"87374495","s":"b","g":"b06","n":"皂化值","e":"Saponification Value","d":"衡量甘油三酯中脂肪酸平均链长的参数。甘油三酯的酯键对酸、碱敏感，可被水解；脂肪在KOH或NaOH条件下加热，产生甘油和脂肪酸的钠或钾盐，这种盐被称为皂，该水解过程即皂化反应。水解1 g甘油三酯所需KOH的毫克数即为皂化值，从皂化值的数量可略知混合脂肪酸或混合脂肪的平均相对分子量，其关系为平均相对分子量=3×56×1000/皂化值。皂化值越小，说明脂肪酸的平均碳链越长。","src":"第15讲 脂类和脂生物化学1"},{"id":"22c1255c","s":"b","g":"b06","n":"酸败","e":"Racidity","d":"脂肪长期暴露于潮湿闷热的空气中，受到空气的作用，脂肪酸被氧化、断裂生成醛、酮及低分子量脂肪酸，产生难闻的恶臭味，这种现象称为酸败。酸败的本质是油脂中的不饱和脂肪酸被氧化降解，故贮存条件与酸败程度密切相关；为防止酸败，可在Ni的作用下使甘油酯中的不饱和双键与H2发生加成反应，油脂被饱和、由液态变为固态。酸败的程度可用酸值表示，酸值越高说明游离脂肪酸越多、酸败越严重。","src":"第15讲 脂类和脂生物化学1"},{"id":"71fac612","s":"b","g":"b06","n":"酸值","e":"Acid Value","d":"表示油脂酸败程度的参数，指中和1 g油脂中游离脂肪酸所消耗KOH的毫克数。脂肪长期暴露于潮湿闷热的空气中被氧化、断裂，生成醛、酮及低分子量脂肪酸，产生难闻恶臭即酸败，游离脂肪酸随之增多，故酸值越高表明酸败越严重。测定时以KOH滴定样品，按消耗的体积、浓度与56计算：酸值=ml KOH×N×56/样品重量，结果为每克油脂所耗KOH的毫克数，是评价油脂品质的重要指标。","src":"第15讲 脂类和脂生物化学1"},{"id":"14362987","s":"b","g":"b06","n":"碘值","e":"Iodine Number","d":"判断油脂中不饱和双键多少的参数，又称碘价、碘化值。油脂中不饱和双键与卤素发生加成反应生成卤代脂肪酸，称为卤化作用；100 g油脂所能吸收的碘的克数即为碘值。碘值越高，说明油脂中不饱和双键越多、不饱和程度越高，油脂的熔点越低。以棕榈油酸、油酸、亚油酸、亚麻酸、花生四烯酸为例，含双键数目不同的甘油三酯其碘值各不相同，故测定碘值即可判断油脂的不饱和程度，因而是油脂分析中的常规指标。","src":"第15讲 脂类和脂生物化学1"},{"id":"caba6296","s":"b","g":"b06","n":"乙酰化值","e":"Acetylation Number","d":"表示油脂中羟基含量的参数。油脂中含-OH的脂肪酸可与乙酸酐或其他酰化剂作用形成相应的酯，称为乙酰化作用；1 g乙酰化的油脂分解出的乙酸用KOH中和时所需KOH的毫克数即为乙酰化值。乙酰化值越高，说明油脂中含羟基的脂肪酸越多，故可用于判断油脂中羟基脂肪酸的含量。它与皂化值、酸值、碘值同属评价油脂组成与性质的化学指标，是油脂分析中的一项化学指标，也是评价油脂性质的重要指标。","src":"第15讲 脂类和脂生物化学1"},{"id":"22321f20","s":"b","g":"b06","n":"蜡","e":"Waxes","d":"由长链脂肪酸（14-16C）与长链碳醇（16-30C）形成的酯，是蜂蜡的主要成分。蜡的熔点为60-80℃，较甘油酯为高。因其防水性和坚硬度而有广泛应用：脊椎动物一些皮腺分泌的蜡质保护毛发和皮肤的柔顺、润滑及防水；鸟类尤其水鸟由口腺分泌蜡质而使羽毛不透水；一些热带植物被一层蜡质包裹以抵抗寄生物和水分的过分蒸腾。生物的蜡还有一定的药学、化妆品及其他工业用途，如用于洗涤剂、油膏及擦光剂。","src":"第15讲 脂类和脂生物化学1"},{"id":"8ea79592","s":"b","g":"b06","n":"磷脂酸","e":"Phosphatidic Acid","d":"甘油磷脂的母体结构。磷脂中2分子脂肪酸与甘油的C1及C2上的羟基以酯键相连，成为膜脂分子疏水的非极性的尾；亲水的极性的或带电的基团与C3上的-OH相连，成为极性的头。磷酸与甘油C3的-OH通过磷酸二酯键相连形成磷脂酸，甘油磷脂都是磷脂酸的衍生物，如磷脂酰胆碱、磷脂酰乙醇胺、磷脂酰肌醇、磷脂酰甘油等。甘油磷脂与鞘脂类、固醇类共同组成生物膜的膜脂，故其种类很多。","src":"第15讲 脂类和脂生物化学1"},{"id":"46d588c2","s":"b","g":"b06","n":"卵磷脂","e":"Lecithin","d":"即磷脂酰胆碱，动、植物中广泛存在，脑、心、精液、肾上腺、红细胞中丰富，卵黄中含量最高（8-10%）；希腊语Lekithos原义是egg yolk。其脂肪酸种类多样，含软脂酸、硬脂酸、油酸、亚油酸、亚麻酸、花生四烯酸等；溶于乙醚、氯仿、苯、热酒精，不溶于丙酮。卵磷脂是构成生物膜的主要成分，能以乳化方式协助脂肪等的运输，并参与控制脂肪代谢和抗脂肪肝，也是食物中卵磷脂与胆碱的来源。","src":"第15讲 脂类和脂生物化学1"},{"id":"e049e280","s":"b","g":"b06","n":"血小板活化因子","e":"Platelet Activating Factor","d":"一种重要的醚酯类激素，缩写PAF，化学本质为1-O-烷基-2-O-乙酰基-甘油-磷脂酰胆碱，是一种高活性的磷脂介质，来源于体内多种细胞。它具有广泛的生理学作用，尤其作为一种重要的炎性介质，能引起血管扩张和通透性增加、促进血小板聚集，并可激活炎症细胞释放5-羟色胺、组胺和前列腺素刺激因子，共同参与哮喘、过敏反应、急慢性炎性反应、败血性休克、关节炎、溃疡等疾病的炎症反应，并对肝、平滑肌、心脏、子宫及肺组织的收缩发挥作用。","src":"第15讲 脂类和脂生物化学1"},{"id":"e163aa27","s":"b","g":"b06","n":"鞘脂类","e":"Sphingolipids","d":"鞘氨醇的衍生物，是第二大类膜脂，有一个极性的头和两个疏水的尾，非甘油酯。由鞘氨醇（十八碳烯氨基二醇）与一分子长链脂肪酸及一分子极性头部组成，有时极性的头部为磷酸以酯键相连的基团。鞘氨醇分子的C1、C2、C3上分别带有-OH、-NH2、-OH，与甘油磷脂中甘油的三个羟基相似；脂肪酸与鞘氨醇的-NH2以酰胺键相连生成神经酰胺。鞘脂参与细胞表面的各种识别过程，如决定人类血型A、B、O，人类神经系统的膜上至少有15种神经节苷脂。","src":"第16讲 脂类和脂生物化学2"},{"id":"53fccbf4","s":"b","g":"b06","n":"鞘磷脂","e":"Sphingomyelins","d":"鞘脂的一种，极性头部含磷酸胆碱或磷酸乙醇胺，出现于细胞质膜和髓鞘。它由神经酰胺的C1羟基与磷酸胆碱相连而成，与甘油磷脂相比其骨架为鞘氨醇而非甘油，因含磷酸而属磷脂类。鞘磷脂是髓鞘的重要成分，其分解需鞘磷脂水解酶去除磷酸胆碱；先天性缺乏该酶时鞘脂沉积于患者的脾、肝、肺、骨髓及部分患者的脑中，即引起Niemann-Pick病。鞘磷脂与卵磷脂同属磷脂，但分属鞘脂与甘油磷脂。","src":"第16讲 脂类和脂生物化学2"},{"id":"748fa3a5","s":"b","g":"b06","n":"鞘糖脂（脑苷脂） Cerebrosides","e":"","d":"鞘脂的一类，极性头部有一个糖分子与神经酰胺C1的-OH相连，又称脑苷脂，如半乳糖脑苷脂、葡萄糖脑苷脂。其糖基以糖苷键连于神经酰胺，故属糖脂；糖脂和脂多糖是细胞膜上的组分，寡糖是亲水的头部基团，可作为糖蛋白的特异识别位点。在细胞表面，鞘糖脂与细胞的各种识别事件相关，如鞘糖脂决定人类血型A、B、O。若缺乏β-葡萄糖脑苷脂酶，葡萄糖脑苷脂不能分解而在组织中沉积，即引起高雪病。","src":"第16讲 脂类和脂生物化学2"},{"id":"dcb90b68","s":"b","g":"b06","n":"神经节苷脂","e":"Gangliosides","d":"最复杂的鞘脂类化合物，含几个糖单位组成的极性头部，属鞘糖脂的一种，其头部含唾液酸（N-乙酰神经氨酸）。人脑灰质中神经节苷脂超过6%，而大部分非神经动物组织中含量极少；人类神经系统的膜上至少有15种神经节苷脂，其作用还不清楚，但已知合成和降解受到严格调控，代谢紊乱可解释人类的几种遗传疾病。命名中G代表神经节苷脂，M（D、T）代表所含唾液酸的数目，1、2、3代表糖链的顺序。","src":"第16讲 脂类和脂生物化学2"},{"id":"9ce00384","s":"b","g":"b06","n":"Tay-Sachs病","e":"Tay-Sachs Disease","d":"又称家族性黑矇性痴呆，一种鞘脂沉积症。因缺失己糖胺裂解酶（氨基己糖苷酶A），神经节苷脂极性部分的D-GalNAc及D-Gal不能被水解，致使神经节苷脂（GM2）积累于脑和脾中，故为GM2神经节苷酯沉积病。患者逐渐神经紧张、眼瞎，一般3-4岁死亡，发病率约三十万分之一；东欧、德国、波兰与苏联境内的犹太人发病率高，约1/3600，28人中有一人带缺乏基因，双亲为携带者时小孩发病机会为1/4。","src":"第16讲 脂类和脂生物化学2"},{"id":"25d409d7","s":"b","g":"b06","n":"Niemann-Pick病","e":"Niemann-Pick Disease","d":"一种遗传性代谢紊乱疾病，属神经磷脂病（鞘脂沉积症），鞘脂沉积于患者脾、肝、肺、骨髓及部分患者的脑中，首发于婴儿，引起神经紧张和早死。病因是先天缺失鞘磷脂水解酶，不能由鞘脂水解去除磷酸胆碱。1914年德国儿科医生Albert Niemann描述了一个患脑和神经系统疾病不治的儿童，1920年代Luddwick Pick研究死后这类儿童的组织，找到了病因证据。该病与Tay-Sachs病、高雪病同属鞘脂沉积症。","src":"第16讲 脂类和脂生物化学2"},{"id":"4eb44a82","s":"b","g":"b06","n":"高雪病","e":"Gaucher's Disease","d":"一种代谢酶缺乏的遗传疾病，又名脑苷脂病或葡萄糖脑苷脂沉积病，是脑脂质沉积病中最常见的一种。患者缺乏β-葡萄糖脑苷脂酶，使葡萄糖脑苷脂不能分解为葡萄糖和N-脂酰鞘氨醇，葡萄糖脑苷脂在脾、肝、肺、骨髓及脑中大量沉积，引起组织疾病。有3种表型，该病在来自欧洲东部的德系犹太人中发病率高；它与Tay-Sachs病、Niemann-Pick病同属鞘脂降解障碍所致的沉积症。","src":"第16讲 脂类和脂生物化学2"},{"id":"3b3b1653","s":"b","g":"b06","n":"类固醇","e":"Steroids","d":"有四个固定环的碳氢环化合物，是多数真核生物细胞膜的结构脂质。由四个固定环组成类固醇的母核，四个环中三个为六碳环、一个为五碳环，这种母核为环戊烷多氢菲母核；整个环几乎是平面、僵硬的，C-C之间不能旋转。胆固醇是动物组织中最主要的类固醇；植物中有豆固醇，真菌中有麦角甾醇，细菌中极少含胆固醇。类固醇是生物膜的组成成分，又是胆汁酸、类固醇激素、维生素D等活性物质的前体。","src":"第16讲 脂类和脂生物化学2"},{"id":"893a66aa","s":"b","g":"b06","n":"胆固醇","e":"Cholesterol","d":"动物组织中最主要的类固醇，神经组织及肾上腺中丰富，占脑固体物质的17%；人体发现的胆石几乎全是胆固醇，肝、肾表面组织含量也相当多。胆固醇可从食物摄入或在体内合成，是细胞膜和细胞器的重要构成成分，也是体内合成维生素D和胆汁酸的原料；在体内可转变成各种肾上腺皮质激素，如皮质醇、醛固酮，还是性激素睾酮和雌二醇的前体。血液中胆固醇高可能引起动脉粥样硬化，可用胆固醇氧化酶法测定。","src":"第16讲 脂类和脂生物化学2"},{"id":"b17b8b0d","s":"b","g":"b06","n":"异戊二烯类化合物","e":"Isoprenoids","d":"由异戊二烯单体合成的一类脂，包括数千种类固醇及大量的类异戊二烯化合物，如维生素A、D、E、K。与贮藏脂及结构脂质相比，生物体中这类脂数量很少，但有特殊而重要的生物学活性，起着生物色素、酶的辅助因子、电子载体及传递细胞间信号等作用。维生素A、D、K、E是脂溶性维生素，属于异戊二烯类化合物，调节生物体的代谢作用和一些重要的生理生化功能，是脂溶性维生素的代表，与贮藏脂和结构脂相区别。","src":"第16讲 脂类和脂生物化学2"},{"id":"e8a38476","s":"b","g":"b06","n":"类固醇激素","e":"Steroid Hormones","d":"以类固醇为母核的一类激素，主要包括雄性激素、雌性激素、肾上腺皮质激素、可的松及醛甾酮，都含有完整的类固醇母核。其浓度低达10^-9 M，由某一特别组织产生，经血液传递到靶组织，与受体蛋白高特异结合，引起基因表达及代谢的改变，从而传递细胞间的信息。各类类固醇激素由胆固醇C17侧链氧化形成，故胆固醇是它们的前体；一些激素和几乎所有的性激素都是固醇。故类固醇激素的作用通过受体蛋白介导。","src":"第16讲 脂类和脂生物化学2"},{"id":"616cace1","s":"b","g":"b06","n":"前列腺素","e":"Prostaglandins","d":"存在于机体各组织中的一种内分泌素，是二十碳脂肪酸的衍生物，由一个五碳环和两条分别含7个和8个碳的碳链组成。花生四烯酸经氧化、环化等生成三个系列的二十碳酸类化合物，即前列腺素、凝血恶烷和白三烯。前列腺素分为九个型，用字母A、B、C、D、E、F、G、H、I表示，再按五碳环结构分成若干型、按双键数目分为Ⅰ、Ⅱ、Ⅲ三类。它可平衡机体内环境，通过调节cAMP合成对多种组织发生作用，如子宫平滑肌收缩、体温升高及炎症。","src":"第16讲 脂类和脂生物化学2"},{"id":"0d894403","s":"b","g":"b06","n":"凝血恶烷","e":"Thromboxane","d":"花生四烯酸经氧化、环化生成的三个系列二十碳酸类化合物之一，与前列腺素、白三烯同属类二十烷酸。其作用是促使血小板聚集，导致血栓形成，因而与血栓性疾病相关；而前列腺素中的PGI2可增加cAMP、抑制血小板聚集，二者比值影响血管与血液状态。阿司匹林通过乙酰化环加氧酶上关键的Ser残基而抑制该酶活性，布洛芬也抑制同一步骤，二者均属非甾体抗炎药，可减少前列腺素、凝血恶烷等的生成。","src":"第16讲 脂类和脂生物化学2"},{"id":"97cc552d","s":"b","g":"b06","n":"白三烯","e":"Leukotriene","d":"花生四烯酸经氧化、环化生成三个系列的二十碳酸类化合物，即前列腺素、凝血恶烷和白三烯，三者同属类二十烷酸。白三烯引起过敏的“慢反应”，与变态反应和发炎有关，能使肌肉收缩、引起肺气管缩小而发生哮喘。它是脂质作为细胞信号分子参与炎症与过敏反应的活性介质之一，其作用缓慢而持久，是炎症过程中不可忽视的脂质介质，是炎症过程中重要的脂质介质，其生成与前列腺素等类二十烷酸相关。","src":"第16讲 脂类和脂生物化学2"},{"id":"79deaa85","s":"b","g":"b06","n":"脂蛋白","e":"Lipoproteins","d":"血液中的脂质与蛋白质一起运输所构成的复合物。血浆中的甘油三酯和胆固醇都是疏水性物质，不能以游离的形式存在于血浆，必须与磷脂和蛋白质等一起组成复合物才能在血液中被转运；各类脂蛋白含有不同比率的胆固醇、甘油三酯、磷脂及蛋白质。包括乳糜微粒、极低密度脂蛋白、低密度脂蛋白及高密度脂蛋白，超速离心法还可分出中间密度脂蛋白（IDL）。其一般结构为单层双性脂类包裹非极性脂类核心，表面嵌有载脂蛋白。","src":"第16讲 脂类和脂生物化学2"},{"id":"101c55ac","s":"b","g":"b06","n":"低密度脂蛋白","e":"LDL","d":"血浆脂蛋白的一种，缩写LDL。血中60-70%的胆固醇由低密度脂蛋白携带，其作用是将胆固醇由肝脏带到周边组织；LDL-胆固醇过高可引起高胆固醇血症，是冠状动脉硬化和心脏疾病的危险因子，故被称为“坏”的胆固醇。LDL约含25%载脂蛋白和45%胆固醇，过量时促进胆固醇在动脉壁沉积。电泳分类中相当于β-脂蛋白，出现在β-球蛋白处，直径及含脂比例（70%）小于乳糜微粒和前β-脂蛋白。","src":"第16讲 脂类和脂生物化学2"},{"id":"9af31b29","s":"b","g":"b06","n":"高密度脂蛋白","e":"HDL","d":"血浆脂蛋白的一种，缩写HDL。血中20-30%的胆固醇由高密度脂蛋白运送，其作用是将周边组织的胆固醇带回肝脏代谢；HDL-胆固醇愈高，患冠状动脉心脏疾病的几率愈低，故被称为“好”的胆固醇。统计显示，HDL为25 mg/dL时男性冠心病发生率为18%，升至75 mg/dL时降为0%。电泳分类中相当于α-脂蛋白，出现在α1-球蛋白处，直径及含脂比例（67%）最小，比重最大。","src":"第16讲 脂类和脂生物化学2"},{"id":"2a8fce4b","s":"b","g":"b06","n":"载脂蛋白","e":"Apolipoprotein","d":"脂蛋白中与脂类结合的蛋白质，缩写apo，在肝脏和小肠粘膜细胞中合成。已发现十几种载脂蛋白，结构功能较清楚的有apoA、apoB、apoC、apoD与apoE五类，每类又分亚类，如apoB分B100和B48，apoC分CⅠ、CⅡ、CⅢ等。载脂蛋白含较多双性α-螺旋，一侧极性较高，可与水及磷脂或胆固醇极性区结合构成亲水面；另一侧极性较低，可与非极性脂类结合构成疏水核心区。其功能为稳定脂蛋白结构、运载脂类、激活酶及作为受体配体。","src":"第16讲 脂类和脂生物化学2"},{"id":"6465221c","s":"b","g":"b06","n":"高脂血症","e":"Hyperlipidemia","d":"血浆脂质水平超出正常范围的病理状态。血浆中的甘油三酯和胆固醇都是疏水性物质，不能以游离形式存在，必须与磷脂和蛋白质组成复合物才能在血液中被转运，临床所测定的TG和总胆固醇（TC）是血浆中所有脂蛋白中含有的甘油三酯和胆固醇的总和。一般把总胆固醇超过230 mg/dL（6.6 mM）、甘油三酯超过110 mg/dL（1.24 mM）诊断为高脂血症。其成因包括膳食与遗传因素，以及糖尿病和某些甲状腺、肝脏、肾脏疾病。","src":"第16讲 脂类和脂生物化学2"},{"id":"e89e0d71","s":"b","g":"b07","n":"维生素","e":"Vitamins","d":"维生素是一类有机化合物，天然食物中含量极少，对人体的生长、发育和健康是必需的，人体自身几乎不能合成，必须由饮食中摄取。它属于六大营养要素（糖、脂肪、蛋白质、盐类、维生素和水）之一，非供能，也非组成生物体的结构成分，而是为代谢过程所必需，多作为辅酶或辅基，或影响酶的活性、影响一些特殊的生理功能，从而影响正常生命活动和生长发育，严重缺乏时会引发疾病。维生素都是小分子有机化合物，化学结构上没有共同性，包括脂肪族、芳香族、脂肪环族及杂环等。","src":"第17讲 维生素与辅酶1"},{"id":"fbff68b9","s":"b","g":"b07","n":"脂溶性维生素","e":"Lipid(fat)-soluble vitamins","d":"脂溶性维生素是维生素按溶解性质划分出的一类，代表为维生素A、维生素D、维生素E和维生素K四种。维生素都是小分子有机化合物，化学结构上没有共同性，依据结构或功能无法分类，故习惯上只根据溶解性质划分，脂溶性维生素即与B族维生素、维生素C构成的水溶性维生素相对。四者的化学本质、活性形式、功能与缺乏症分别是：维生素A为具脂环的单元醇，维生素D为类固醇化合物，维生素E为生育酚，维生素K为萘醌衍生物。","src":"第17讲 维生素与辅酶1"},{"id":"f512d3a8","s":"b","g":"b07","n":"水溶性维生素","e":"Water-soluble vitamins","d":"水溶性维生素是维生素按溶解性质划分出的另一类，包括维生素B家族（B1、B2、烟酸及烟酰胺、B6、遍多酸、生物素、叶酸、B12等）和维生素C，与A、D、E、K四种脂溶性维生素相对。维生素结构上无共同性，只能按溶解性质划分。其中B1在体内以磷酸酯（TP）或焦磷酸酯（TPP）形式存在，B2则在体内转化为FMN和FAD，二者均以辅酶或辅基形式参与糖代谢的氧化脱羧与氧化还原反应，可见水溶性维生素多以辅酶形式发挥作用。","src":"第17讲 维生素与辅酶1"},{"id":"fedbf1d4","s":"b","g":"b07","n":"维生素A 视黄醇","e":"retinol","d":"维生素A的化学名称是视黄醇，是一个具脂环的单元醇，由四个异戊二烯单位组成，含五个共轭双键。它有A1和A2两种形式，前者主要存在于海水鱼肝脏内，后者存在于淡水鱼肝脏内，A1活性较A2为大。维生素A易被氧化，遇热或光更易氧化。其主要功能为维持上皮细胞正常结构和功能、组成视色素、促进粘多糖合成及骨的形成和生长等；缺乏症包括皮肤和各器官表皮角质化（蟾皮病）、眼角膜和结膜表皮细胞退变（干眼症、角膜软化症、夜盲症）。","src":"第17讲 维生素与辅酶1"},{"id":"fe1b7212","s":"b","g":"b07","n":"胡萝卜素","e":"Carotene（维生素A源）","d":"胡萝卜素是维生素A源，其结构与维生素A非常相似，1分子胡萝卜素可转化为2分子维生素A，因此可经体内转化提供维生素A活性。维生素A与癌的部分指出，维生素A源β-胡萝卜素是抗氧化剂，可以消除自由基，防止自由基过氧化作用带来的危害。此外，1920年发现人体可将胡萝卜素转化为维生素A；历史上1831年胡萝卜素作为维生素A前体被发现。由于胡萝卜素在体内可转变为视黄醇，故膳食中的胡萝卜素具有维生素A的营养作用。","src":"第17讲 维生素与辅酶1"},{"id":"59c89466","s":"b","g":"b07","n":"视紫红质","e":"rhodopsin","d":"视紫红质是视网膜杆状细胞中与暗适应有关的视色素。其组分包括11-顺式视黄醛与视蛋白（opsin），并标出全反式视黄醛与视蛋白，以及11-顺式视黄醇与全反式视黄醇之间由同分异构酶和醇脱氢酶催化的相互转变。维生素A的主要功能之一是组成视色素，缺乏时眼角膜和结膜表皮细胞退变，出现干眼症、角膜软化症和夜盲症，说明视紫红质的正常生成依赖维生素A的供应。","src":"第17讲 维生素与辅酶1"},{"id":"e3b88ce6","s":"b","g":"b07","n":"维生素D Vitamin D","e":"","d":"维生素D是类固醇化合物，具环戊烷多氢菲结构，包括D2和D3两种活性形式：D2为麦角钙化[甾]醇（ergocalciferol，calciferol），D3又称胆钙化[甾]醇（cholecalciferol），紫外线照射可使之转变为活化形式。主要作用为调节钙磷吸收及代谢，促进成骨，具抗佝偻病和抗软骨病作用。食物来源为鱼油、肝、蛋类等动物性食物。芬兰对1966年出生12000名儿童的追踪研究显示，服维生素D的孩子患糖尿病的机会减少80%。","src":"第17讲 维生素与辅酶1"},{"id":"3a91aa4e","s":"b","g":"b07","n":"维生素E 生育酚","e":"tocopherol","d":"维生素E的化学名称为生育酚，均为苯骈二氢吡喃的衍生物，天然存在的生育酚有8种以上，以α型最重要、活力最高。1922年Evans等发现受孕雌鼠有死胎并被吸收的现象，饲料中加入少量生菜、麦胚和干苜蓿后即可正常生殖，后提取纯化得维生素E并实现人工合成。维生素E为油状物，紫外及氧化剂可使其失活，无氧条件下耐热；因易氧化，可用于保护脂质和维生素A不被氧化，保护生物膜，对生育功能重要，临床用于防治流产及早产。","src":"第17讲 维生素与辅酶1"},{"id":"90958618","s":"b","g":"b07","n":"维生素K Vitamin K","e":"","d":"维生素K有K1和K2两种（K3和K4为人工合成），都是2-甲基-1,4萘醌的衍生物。丹麦科学家Dam于1929—1935年在实验鸡群中发现，命名为血凝维生素。其作用为凝血、抗出血不凝：加速血液凝固，促进肝脏合成凝血酶原及凝血因子，并参与体内氧化-还原反应（作为呼吸链的一部分参与电子传递和氧化磷酸化）。肝、鱼、肉、蔬菜中含量丰富，遇光易氧化。凝血过程有内源性与外源性两条触发途径，均需维生素K参与。","src":"第17讲 维生素与辅酶1"},{"id":"6644a592","s":"b","g":"b07","n":"双羟香豆素","e":"Dicumarol","d":"双羟香豆素是一种抗凝物质，其化学结构与维生素K相似，通过竞争性拮抗作用而达到抗凝效果，起效较慢但持续时间长，还能降低凝血酶诱导的血小板聚集反应。\"维生素K与凝血\"的图示中把它列为维生素K的拮抗物：维生素K为2-甲基-1,4萘醌的衍生物，有K1和K2两种，能促进肝脏合成凝血酶原及凝血因子、加速血液凝固；结构相似的双羟香豆素竞争性阻断这一过程，因而表现出抗凝作用。","src":"第17讲 维生素与辅酶1"},{"id":"e9c8c161","s":"b","g":"b07","n":"辅酶Q Coenzyme Q（泛醌）","e":"","d":"辅酶Q是一种辅酶，参与细胞线粒体呼吸链的组成，与细胞能量代谢密切相关，是细胞代谢的激活剂，对人体具有重要的生理功能，能提高机体的免疫力。对多种疾病如坏血病、十二指肠溃疡、充血性心脏病、病毒性肝炎等有较强的治疗作用，并具有抗肿瘤作用，可用于癌症的辅助治疗。以\"辅酶Q：泛醌\"为题给出其另一名称，并在电子传递链部分列出NADH氧化呼吸链与琥珀酸氧化呼吸链两条呼吸链。","src":"第17讲 维生素与辅酶1"},{"id":"e5b1d6c3","s":"b","g":"b07","n":"硫辛酸","e":"Thioctic acid / Lipoic acid","d":"硫辛酸是酵母和微生物等必需的生长因子，为含硫的八碳酸。对于动物它不能算是一个维生素，而是一个辅酶，通过氧化还原作用参与生物体的递氢和递乙酰基作用。以硫辛酸（酰胺）为辅酶的酶有硫辛酸转乙酰酶、二氢硫辛酸脱氢酶、丙酮酸脱氢酶、α-酮戊二酸脱氢酶，与糖代谢关系密切。硫辛酸与其还原型二氢硫辛酰胺构成一对氧化还原体，以“硫辛酸与氧化脱羧”一图说明二者的互变。","src":"第17讲 维生素与辅酶1"},{"id":"86b6c8a9","s":"b","g":"b07","n":"维生素B1 硫胺素","e":"Thiamine","d":"维生素B1又称硫胺素，由一个含硫的噻唑环和一个含氨基的嘧啶环组成，故得名，是最早发现的水溶性维生素。R. R. Williams等1936年测定其结构，1937年实现人工合成。体内以磷酸酯（TP）或焦磷酸酯（TPP）的形式存在。TPP是糖代谢中两个重要酶的辅酶，参与丙酮酸和α-酮戊二酸氧化脱羧及醛基转移反应，对维持正常糖代谢极其重要。植物中分布广，谷类、豆类的种皮及米糠中含量丰富，故精制谷物易致其缺乏。","src":"第17讲 维生素与辅酶1"},{"id":"01ce141f","s":"b","g":"b07","n":"硫胺素焦磷酸","e":"TPP（thiamine pyrophosphate）","d":"TPP是维生素B1在体内的焦磷酸酯形式，由硫胺素经磷酸化转变而来，\"Conversion of Thiamine to TPP\"及反应中的羟乙酰硫胺素焦磷酸中间物。称TPP是糖代谢中两个重要脱氢酶的辅酶，参与丙酮酸和α-酮戊二酸氧化脱羧及醛基转移反应，对维持正常糖代谢极其重要，还可催化乙酰乳酸生成等TPP依赖的反应。TPP缺乏时糖代谢受阻、丙酮酸积累，血、尿和脑中丙酮酸含量升高，出现脚气病等表现。","src":"第17讲 维生素与辅酶1"},{"id":"cee7e68f","s":"b","g":"b07","n":"脚气病","e":"beriberi","d":"脚气病是维生素B1（TPP）缺乏所致的疾病。TPP缺乏使糖代谢受阻、丙酮酸积累，病人血、尿和脑中丙酮酸含量升高，表现为多发性神经炎——脚气病，并伴厌食、神经性紊乱（特别是姿势），重症时体弱、心功能衰竭甚至死亡。1897年荷兰医生Eijkman证明米糠可治脚气病；1912年丰克从米糠中提取出能治疗脚气病的白色物质并命名Vitamine。因维生素B1在谷类、豆类的种皮及米糠中丰富，长期食用精制谷物易致缺乏。","src":"第17讲 维生素与辅酶1"},{"id":"b5b6d654","s":"b","g":"b07","n":"维生素B2 核黄素","e":"riboflavin","d":"维生素B2又称核黄素，为核[糖]醇和6,7-二甲基异咯嗪的缩合物，分子中1、10位N有两个活泼的共轭双键，易起氧化还原反应，反应中起递氢作用。缺乏时组织呼吸减弱、代谢降低，表现为口角炎、舌炎、皮脂溢出性皮炎和视觉模糊等，并与眼疾、皮肤异常、睾丸发育不全有关。它广泛存在于动植物中，米糠、酵母、肝、蛋黄中丰富。在体内转化为活性磷酸化代谢物FMN和FAD，作为氧化还原酶（黄素蛋白）的辅基。","src":"第17讲 维生素与辅酶1"},{"id":"4846c9e6","s":"b","g":"b07","n":"黄素单核苷酸","e":"FMN（flavin mononucleotide）","d":"FMN即核黄素磷酸，是维生素B2（核黄素）在体内转化生成的活性磷酸化代谢物之一。它与FAD同为氧化还原酶（黄素蛋白）的辅基，参与碳水化合物、蛋白质和脂肪的代谢，维持正常的视觉功能并促进生长，在呼吸链中作为递氢体。核黄素分子中1、10位N的两个活泼共轭双键易起氧化还原反应，故FMN可反复接受和传递氢。以FMN为辅基的酶有肾L-氨基酸氧化酶、酵母乳酸脱氢酶（LDH）等。","src":"第17讲 维生素与辅酶1"},{"id":"d99b4494","s":"b","g":"b07","n":"黄素腺嘌呤二核苷酸","e":"FAD（flavin adenine dinucleotide）","d":"FAD是维生素B2在体内转化生成的活性磷酸化代谢物之一，与FMN同为氧化还原酶（黄素蛋白）的辅基，参与碳水化合物、蛋白质和脂肪的代谢，维持正常视觉功能并促进生长，在呼吸链中作为递氢体。以FAD为辅基的酶很多，如琥珀酸脱氢酶、脂酰CoA脱氢酶、D-氨基酸氧化酶、L-葡萄糖氧化酶等；黄嘌呤氧化酶也是含FAD的黄素蛋白，同时还含Fe和Mo。核黄素1、10位N的共轭双键使其可反复进行氧化还原。","src":"第17讲 维生素与辅酶1"},{"id":"ec62c94f","s":"b","g":"b07","n":"烟酸（尼克酸）与烟酰胺","e":"Nicotinic acid / Nicotinamide","d":"烟酸又称维生素PP，或抗糙皮病（癞皮病）维生素，是含氮杂环吡啶化合物，体内主要以烟酰胺形式存在；游离酸与酰胺两种形式均有活性。烟酰胺是辅酶Ⅰ（CoI）和辅酶Ⅱ（CoII）的组成成分，二者为生物体脱氢酶类的辅酶，起携带和传递氢的作用。缺乏引起癞皮病、口腔炎、舌炎、腹痛、腹泻、痴呆、神经紊乱（3D症状）等，还可致生长迟缓、发育停滞、脂肪肝以及包括溃疡在内的胃肠紊乱（黑舌病）。食物来源以脏器肉最多。","src":"第18讲 维生素与辅酶2"},{"id":"04405d99","s":"b","g":"b07","n":"烟酰胺腺嘌呤二核苷酸磷酸","e":"NADP+（辅酶Ⅱ，CoII）","d":"NADP+即烟酰胺腺嘌呤二核苷酸磷酸（Nicotinamide Adenine Dinucleotide Phosphate），旧文献中称TPN或辅酶Ⅱ，与NAD+同属烟酰胺类辅酶，是生物体脱氢酶类的辅酶，起携带和传递氢的作用，其还原型为NADPH。NAD+与NADP+并列，说明二者均由烟酰胺参与构成，且都有对应的还原型并具有紫外吸收。烟酸在体内主要以烟酰胺形式存在，故烟酰胺是CoI和CoII的组成成分。","src":"第18讲 维生素与辅酶2"},{"id":"876d6a79","s":"b","g":"b07","n":"糙皮病（癞皮病）Pellagra","e":"","d":"糙皮病是烟酸（维生素PP）缺乏引起的疾病，故烟酸又称抗糙皮病维生素。早期表现为厌食、消化不良、肌无力、皮肤发红、皮肤粗糙；进展期出现典型的\"3D\"症状：皮炎（dermatitis）、腹泻（diarrhea）和痴呆（dementia），口腔炎、舌炎、腹痛、神经紊乱等。易诱发糙皮病的膳食有玉米粉、玉米淀粉、甘薯、大米、糖浆和猪油等。色氨酸可替代烟酸，60 mg色氨酸相当于1 mg烟酸，故以玉米为主食者易发病。","src":"第18讲 维生素与辅酶2"},{"id":"587127e2","s":"b","g":"b07","n":"色氨酸对烟酸的节省作用","e":"Sparing action of tryptophan","d":"色氨酸节省作用指膳食中存在的非必需营养成分降低机体对某种必需成分需要量的现象。数据是：色氨酸可以代替烟酸，60 mg色氨酸相当于1 mg烟酸；60 g蛋白质含600 mg色氨酸，即相当于10 mg烟酸。因此烟酸的需要量受膳食蛋白质中色氨酸含量的影响，以玉米为主食、烟酸与色氨酸均不足的膳食易诱发糙皮病。以\"Tryptophan can substitute for niacin\"表述这一替代关系。","src":"第18讲 维生素与辅酶2"},{"id":"3e7ccfea","s":"b","g":"b07","n":"维生素B6（吡哆醇）Vitamin B6","e":"","d":"维生素B6又称抗皮炎维生素，为吡啶衍生物；吡哆醇、吡哆醛和吡哆胺三者统称维生素B6，生物体内往往以磷酸酯形式发挥作用。它与氨基酸代谢密切相关，是氨基酸转氨酶、脱羧酶的辅酶，还参与氨基酸的消旋作用，并参与色氨酸转变为烟酸、亚油酸转变为花生四烯酸、鞘脂的生成。缺乏引起呕吐、中枢神经兴奋、惊厥、低色素性贫血，并导致体重下降、贫血及免疫功能削弱。植物中分布广，谷类外皮中尤为丰富。","src":"第18讲 维生素与辅酶2"},{"id":"edf9e06c","s":"b","g":"b07","n":"磷酸吡哆醛","e":"Pyridoxal phosphate（PLP）","d":"磷酸吡哆醛是维生素B6在体内的磷酸酯形式，即其发挥辅酶作用的主要形式。生化功能包括：氨基酸的脱羧作用、转氨酶反应、消旋作用，色氨酸转变为烟酸，亚油酸转变为花生四烯酸（前列腺素前体），以及鞘脂的生成。作为转氨酶与脱羧酶的辅酶，PLP参与氨基酸代谢的多个环节。肼苯哒嗪、异烟肼、环丝氨酸、青霉胺等维生素B6拮抗剂，它们可干扰PLP依赖的反应。吡哆醛、吡哆醇、吡哆胺统称维生素B6，三者均可形成磷酸酯。","src":"第18讲 维生素与辅酶2"},{"id":"abcb9fbb","s":"b","g":"b07","n":"生物素","e":"Biotin（维生素H）","d":"生物素是由噻吩环和尿素结合而成的双环化合物，侧链上有一戊酸，对一些微生物如酵母、细菌的生长有强烈的促进作用。它与细胞内的CO2固定或羧化作用有关，是很多需要ATP的羧化酶的辅基，起羧基的载体作用；其作用分两步：CO2先与生物素结合成N-羧基生物素，再把CO2转移给底物，激活生物素需要酶、CO2、ATP和Mg2+。依赖生物素的酶有丙酮酸羧化酶、乙酰CoA羧化酶等。动物缺乏时毛发脱落、皮肤发炎。","src":"第18讲 维生素与辅酶2"},{"id":"b6f61bb3","s":"b","g":"b07","n":"生物胞素","e":"Biocytin","d":"生物胞素是生物素与酶蛋白中赖氨酸残基结合形成的产物，即生物素酰赖氨酸。生物素与酶蛋白结合的Lys可以一起被洗下来，得到生物素酰Lys，即生物胞素；生物素的羧基与Lys的氨基以酰胺键结合。生物素借此共价连接于羧化酶上，作为羧基的载体参与CO2固定。这类需要ATP的羧化酶包括丙酮酸羧化酶（为糖异生合成草酰乙酸并补充三羧酸循环）和乙酰CoA羧化酶（脂肪酸合成），故生物胞素是生物素发挥辅基作用的结构基础。","src":"第18讲 维生素与辅酶2"},{"id":"8da57e0f","s":"b","g":"b07","n":"泛酸（遍多酸）Pantothenic acid","e":"","d":"泛酸又名遍多酸，意为\"到处都有\"，也有称维生素B3或B5。它由二羟基二甲基丁酸（泛解酸，pantoic acid）和β-丙氨酸通过酰胺键结合而成，是各种动植物、细菌、酵母和人类生长所必需，但植物和许多微生物能合成泛酸。纯品为黄色粘稠油状物（游离酸），耐湿热而不耐干热，对氧化还原剂稳定，在酸或碱中易水解。缺乏时导致肠胃炎症、皮肤角质化、蜕皮、脱毛等。几乎所有泛酸都用于构成辅酶A。","src":"第18讲 维生素与辅酶2"},{"id":"4d2dccf2","s":"b","g":"b07","n":"辅酶A Coenzyme A（CoA）","e":"","d":"辅酶A由等分子的泛酸、氨基乙硫醇、焦磷酸及3′-AMP组成，是泛酸在体内的主要存在形式（HS-CoA）。它主要起传递酰基的作用，是酰基转移酶的辅酶，携带乙酰基时称乙酰CoA。乙酰CoA是糖、脂、蛋白质（氨基酸）等进入三羧酸循环的必经之路，也是一些生物合成碳架的载体，可用于合成脂肪酸和脂类、生成酮体、合成固醇类化合物，在代谢中起重要作用。以\"乙酰CoA在代谢中的作用\"专页说明其枢纽地位。","src":"第18讲 维生素与辅酶2"},{"id":"1671d50a","s":"b","g":"b07","n":"叶酸","e":"Folic acid（蝶酰谷氨酸）","d":"叶酸为2-氨基-4-羟基-6-甲氨基蝶呤，又称蝶酰谷氨酸，由蝶酸（蝶啶与对氨基苯甲酸）和谷氨酸组成，去掉Glu会失去维生素作用。1935年在肝脏及酵母菌中发现可抗猴子贫血的物质称维生素M；1939年发现抗小鸡贫血的物质称维生素Bc；1940年一种可促进乳酸菌生长的物质被命名为叶酸或抗贫血维生素。缺乏时表现为生长不良及各种贫血症。植物绿叶中大量存在，在体内经还原酶作用还原为二氢及四氢叶酸。","src":"第18讲 维生素与辅酶2"},{"id":"41fcb87c","s":"b","g":"b07","n":"氨甲蝶呤","e":"Methotrexate（MTX）","d":"氨甲蝶呤又称amethopterin，是二氢叶酸还原酶（DHFR）的强抑制剂，该酶催化叶酸转变为四氢叶酸（THFA），而还原型叶酸是DNA合成所必需。THFA作为一碳单位（来自甲酸或甲醛）的接受体，参与嘌呤、胸腺嘧啶、胆碱等细胞成分的合成。MTX用于治疗儿童急性淋巴细胞白血病、绒毛膜瘤、骨肉瘤及头、颈、膀胱、睾丸癌，低剂量用于牛皮癣和风湿性关节炎。称二氢叶酸还原酶是重要的抗菌及化疗药物靶酶。","src":"第18讲 维生素与辅酶2"},{"id":"22a22246","s":"b","g":"b07","n":"四氢叶酸","e":"Tetrahydrofolic acid（THFA，FH4）","d":"四氢叶酸是叶酸在体内经还原酶作用生成的还原型产物，简称辅酶F。它作为一碳单位的载体，在各种生物合成反应中起转移和利用一碳单位（-CH3、-CH2-、-CH=、-CH=O、-CH=NH、-CH2OH）的作用，在嘌呤、嘧啶、核苷酸、丝氨酸、甲硫氨酸等的合成中起重要作用。叶酸与核酸合成有关，是骨髓巨红细胞和白细胞成熟和分裂所必需，临床用于治疗巨红细胞贫血和血小板减少等。5-甲酰THFA又称亚叶酸（leucovorin）。","src":"第18讲 维生素与辅酶2"},{"id":"a94ad1de","s":"b","g":"b07","n":"维生素B12（氰钴胺素）Cyanocobalamin","e":"","d":"维生素B12是1929年用猪肝治疗恶性贫血时分离得到的红色结晶化合物，1955年确定其化学结构为氰钴胺素，又称动物蛋白因子。分子中含Co和CN，Co以配位键与CN相连；一部分为与卟啉环相似的咕啉环，环中心为3价Co，另一部分为5,6-二甲基苯并咪唑核苷酸。它是一种抗恶性贫血因子，为红细胞正常成熟和生长所必需，通常以辅酶形式参与代谢，参与的酶促反应有两类：某些化合物的重排（变位反应）和某些化合物的甲基化。","src":"第18讲 维生素与辅酶2"},{"id":"c13b9d33","s":"b","g":"b07","n":"维生素C（抗坏血酸）Ascorbic acid","e":"","d":"维生素C因能防治坏血病又名抗坏血酸，可以脱氢参与生物体氧化还原反应，起递氢作用。它具抗毒作用，能保护巯基酶不被氧化，用于防治铅、汞、砷、苯等慢性中毒；参与脯氨酸和赖氨酸的羟基化，促进胶原蛋白和粘多糖的合成，促进骨骼正常生长和伤口愈合。它还是抗氧化剂，可清除超氧物等活性氧化剂，防止细胞蛋白和DNA损伤，并阻止亚硝胺生成。缺乏时患坏血病，出现瘀斑性出血、牙龈出血、伤口愈合变差等。","src":"第18讲 维生素与辅酶2"},{"id":"01067554","s":"b","g":"b07","n":"维生素缺乏症","e":"Vitamin deficiency","d":"维生素缺乏症指人体缺乏维生素所引起的一类特殊疾病。人体每日对维生素的需要量甚微，但缺乏则可引起这类疾病。其原因包括摄入不足、吸收障碍、机体需要增加以及长期应用药物或维生素拮抗剂；具体如作物歉收、食物贮存与烹调损失、偏食、慢性疾病、寄生虫、快速生长、妊娠、甲状腺机能亢进、药物治疗、多尿和哺乳等。不同维生素缺乏表现不同，如维生素B1缺乏致脚气病，烟酸缺乏致糙皮病，维生素C缺乏致坏血病。","src":"第18讲 维生素与辅酶2"},{"id":"4c909af9","s":"b","g":"b08","n":"激素","e":"Hormone","d":"激素亦称\"荷尔蒙\"，由特殊组织或腺体产生，直接分泌到体液（血液、淋巴液、脑脊液、肠液），运送到特定作用部位（靶），引起特殊激素效应的一群微量有机化合物，是生物体内的\"化学信使\"。Starling和Bayliss于1902年发现促胰液素后将这类物质命名为激素，希腊语horman意为\"奋起活动\"，对机体的代谢、生长、发育和繁殖等起重要调节作用。激素在血液中浓度极低，只对靶细胞的生理生化过程起加强或减弱作用，既不添加成分也不提供能量。","src":"第19讲 激素1"},{"id":"94fc12d7","s":"b","g":"b08","n":"促胰液素","e":"Secretin","d":"促胰液素是1902年Starling和Bayliss研究发现的第一个被命名为\"激素\"的物质。当食物进入小肠时，由于食物在肠壁摩擦，小肠粘膜分泌出一种数量极少的物质进入血液，流送到胰腺，胰腺接到此信息后立刻分泌胰液。这种物质提取后注入哺乳动物血液，动物即使不吃东西也会立刻分泌胰液。标注其为27肽（碱性肽）。正是这类\"数量极少但有生理作用、可激起生物体内器官反应\"的物质，被命名为激素（荷尔蒙）。","src":"第19讲 激素1"},{"id":"44dfa31d","s":"b","g":"b08","n":"褪黑激素（松果体素）Melatonin","e":"","d":"褪黑激素是松果体（松果腺）分泌的主要激素，化学本质为N-乙酰-5-甲氧基色胺，属色氨酸衍生物。其分泌受光照调节：黑暗刺激分泌，光照抑制分泌。它的生理作用涉及生殖系统的成熟及机体节律（生物节律）的调节。\"人体主要的内分泌腺及分泌的激素\"中列出松果体，指出其分泌褪黑激素并受黑暗与光线双重控制，是松果体作为神经内分泌器官发挥调节作用的物质基础。褪黑激素的发现使松果体被确认为人体主要的内分泌腺之一。","src":"第19讲 激素1"},{"id":"3d1a7c7d","s":"b","g":"b08","n":"靶器官、靶组织与靶细胞","e":"Target organ / tissue / cell","d":"被激素选择作用的器官、组织和细胞分别称为靶器官、靶组织和靶细胞。激素只作用于特定器官、组织和细胞，这一特性称为激素作用的特异性；其物质基础是靶细胞上存在能与该激素发生特异性结合的受体。肽类和蛋白质激素的受体存在于靶细胞膜上，而类固醇激素与甲状腺激素的受体则位于胞浆或细胞核内。有些激素特异性很强，如促甲状腺激素只作用于甲状腺；生长素、甲状腺激素等则几乎对全身组织细胞的代谢过程都发挥调节作用。","src":"第19讲 激素1"},{"id":"750f711d","s":"b","g":"b08","n":"胰高血糖素","e":"Glucagon","d":"胰高血糖素是胰岛α-细胞分泌的肽类激素，为29肽。它是低血糖的信号：较低的血糖浓度促发胰高血糖素分泌增加和胰岛素释放减少。其功能在许多方面与胰岛素相反，主要促使肝糖原分解及糖原异生，使血糖升高，并促使脂肪分解。它与肾上腺素相似，通过活化糖原磷酸化酶和钝化糖原合成酶刺激肝中糖原净降解；不同之处是它还抑制肝中由酵解引起的葡萄糖降解，并通过糖原异生刺激葡萄糖合成。","src":"第19讲 激素1"},{"id":"c1e63df3","s":"b","g":"b08","n":"生长激素抑制素（生长抑素）Somatostatin","e":"","d":"生长激素抑制素是一种由14（28）个氨基酸组成的肽，1973年由Brazeau等在羊下丘脑发现。这种多肽在全身各器官均有分布，以脑组织、胃肠和胰腺的含量较高。它可抑制腺垂体分泌生长激素，某些情况下抑制泌乳激素，也可减少某些胃肠道激素分泌，并直接或间接调节细胞因子链产生细胞保护作用。其异常会导致胃酸和胃蛋白酶分泌失常，在消化性溃疡发病机制中起一定作用。人工合成的制剂施它宁已用于消化道出血等。","src":"第19讲 激素1"},{"id":"86933dd2","s":"b","g":"b08","n":"儿茶酚胺","e":"Catecholamine","d":"儿茶酚胺是水溶性胺类激素，包括肾上腺素、去甲肾上腺素、多巴和多巴胺，它们是一类胺类化合物，是儿茶酚（酪氨酸）的衍生物，故统称儿茶酚胺。其生成顺序为酪氨酸→多巴→多巴胺→去甲肾上腺素→肾上腺素。肾上腺素由肾上腺髓质分泌，对心脏作用大，是强心剂（使心速加快），对糖代谢作用大、升高血糖；去甲肾上腺素对血管作用大，是加压剂（使血管收缩），对糖代谢的作用仅为肾上腺素的二十分之一。5-羟色胺则是色氨酸的衍生物。","src":"第19讲 激素1"},{"id":"59720367","s":"b","g":"b08","n":"甲状腺素（T4）Thyroxine","e":"","d":"甲状腺素即3,5,3′,5′-四碘甲腺原氨酸（T4），是甲状腺分泌的特征激素之一，化学本质为碘加氨基酸，自然状态下是L-型，为甲状腺球蛋白的组分之一；白色针状晶体，无臭无味，遇光变质，在235—236℃分解。其分泌受下丘脑TRH→垂体TSH的顺次调节。生理功能为促进分解代谢、促进生长发育、提高神经系统的兴奋性。分泌过多致甲亢（代谢加快、多食消瘦、心率呼吸加快、眼球突出），幼年分泌过少致呆小症，成年分泌过少致甲状腺肿大。","src":"第19讲 激素1"},{"id":"68eb1929","s":"b","g":"b08","n":"三碘甲腺原氨酸（T3）Triiodothyronine","e":"","d":"三碘甲腺原氨酸即3,5,3′-三碘甲腺原氨酸（T3），与甲状腺素（T4）同为甲状腺分泌的两个特征激素。下丘脑分泌的促甲状腺素释放激素（TRH）刺激垂体前叶释放促甲状腺素（TSH），TSH再顺次刺激甲状腺分泌T4和T3，二者共同刺激能量产生机制、促进代谢速度。甲状腺激素的化学本质是碘加氨基酸；合成所需的碘是活性碘，食物碘在肠道被还原为碘离子，再经甲状腺过氧化物酶（有过氧化氢存在）转化为活性碘。T4与T3的结构并列给出。","src":"第19讲 激素1"},{"id":"43afef5a","s":"b","g":"b08","n":"基础代谢率","e":"Basal metabolic rate（BMR）","d":"基础代谢率是个体在完全休息状态下氧的消耗速率，所谓完全休息状态指进食后12小时。BMR的测定对诊断甲状腺机能障碍是一种有用的手段：个体甲状腺机能亢进时，甲状腺素过分分泌，BMR提高；甲状腺机能减退时，甲状腺素分泌不足，BMR降低。由于甲状腺激素能刺激能量产生机制、促进代谢速度，故BMR成为反映甲状腺功能状态的实用指标，据此说明甲状腺激素对基础代谢的调节作用。","src":"第19讲 激素1"},{"id":"224bf2f9","s":"b","g":"b08","n":"二十烷类激素","e":"Eicosanoids","d":"二十烷类激素是花生四烯酸（二十碳四烯酸）的衍生物构成的激素，包括前列腺素、白三烯和凝血恶烷等。按化学本质分类时将其列为脂肪酸衍生物激素，与含氮激素、固醇类激素并列；按四分类法则列为肽类、胺类、类固醇激素之外的第四类\"二十碳酸类激素\"。这类激素在体内分布广、效应强，对生殖、心血管、呼吸、消化及神经系统均有作用，并对代谢过程发生影响，如引起炎症、发热及子宫平滑肌收缩等。","src":"第19讲 激素1"},{"id":"c8de3e55","s":"b","g":"b08","n":"糖皮质激素","e":"Glucocorticoid","d":"糖皮质激素是肾上腺皮质激素的一类，包括皮质酮、皮质醇（氢化可的松）和可的松。这类激素对糖代谢影响很大，而对水盐代谢影响很小，故称糖皮质激素。其主要功能是调节糖代谢，抑制糖的氧化，促使蛋白质（氨基酸）转化为糖，升高血糖；另外可减轻过敏反应、减轻炎症。它属固醇类（类固醇）激素，为脂溶性激素，通过进入核内调控基因表达而发挥作用，其受体位于胞浆或细胞核内。它与盐皮质激素同属肾上腺皮质激素，均由肾上腺皮质分泌。","src":"第19讲 激素1"},{"id":"dd6f0adc","s":"b","g":"b08","n":"盐皮质激素","e":"Mineralocorticoid","d":"盐皮质激素是肾上腺皮质激素的另一类，包括醛固酮、脱氧皮质醇、脱氧皮质酮和脱氢皮质酮，其中以醛固酮的生理效应最强。这类激素对水、盐代谢影响较大，对糖和蛋白质代谢影响较小。其主要生理功能是促使体内保留钠、排出钾（保钠排钾），调节水盐代谢。它与糖皮质激素同属固醇类激素，为脂溶性，可进入靶细胞与胞内或核内受体结合，调控特异基因的表达。二者对糖代谢与水盐代谢的影响正好相反。","src":"第19讲 激素1"},{"id":"8e4a304f","s":"b","g":"b08","n":"雄激素","e":"Male hormone / Androgen","d":"雄激素主要由睾丸的间质细胞分泌，但肾上腺皮质及卵巢也分泌少量。主要包括睾酮、雄酮和雄烯二酮，可看作雄烃的衍生物；三种激素中只有睾酮是睾丸分泌的，其生理功效最大，雄酮和雄烯二酮是睾酮的降解产物。生理功能为刺激男性性器官发育、促进精子生成及促进男性的第二性征，另外对全身代谢也有影响。雄激素属固醇类激素，由睾丸和卵巢合成，影响性的发育、性行为及其他各种生殖及非生殖功能。","src":"第19讲 激素1"},{"id":"4ca6a287","s":"b","g":"b08","n":"雌激素","e":"Estrogen","d":"雌激素主要由卵巢产生，但人类的胎盘、肾上腺皮质甚至睾丸也产生少量。卵泡激素包括雌二醇、雌三醇和雌酮，可看作雌烃的衍生物，其生理功能为促进女性器官发育、排卵；黄体激素主要为孕酮，生理功能为促进子宫和乳腺发育、抑制排卵、抑制动情，对全身代谢也有显著影响。雌激素与雄激素同属固醇类（类固醇）激素，为脂溶性激素，通过进入核内调控基因表达而发挥作用。卵泡激素与黄体激素并列为雌激素的两类。","src":"第19讲 激素1"},{"id":"4a251749","s":"b","g":"b08","n":"视黄酸","e":"Retinoic acid","d":"视黄酸又称维生素甲酸、维甲酸，是动物体内维生素A的代谢中间产物，属视黄酸激素。它具有广泛的生理学和药理学活性，在脊椎动物生长、发育和细胞分化尤其是胚胎发育过程中有重要作用，调节脊椎动物胚胎发生过程中多方面的形态形成。科学家发现它可以激活再生所必要的基因，是动物肢体再生过程中必不可缺的物质，在人体内由维生素A合成。2009年研究显示其作用机制可作为新型治疗乳腺癌的药物靶标。","src":"第19讲 激素1"},{"id":"ba4f5e5e","s":"b","g":"b08","n":"第二信使","e":"Second messenger","d":"第二信使是水溶性激素作用于靶细胞后产生的胞内信号分子。水溶性激素（肽类和胺类激素）不能通过细胞膜，其受体位于靶细胞膜的外表面；激素与膜上的特异受体结合后，受体产生变构作用，改变酶的构象，或引起胞内信号分子的形成，这种胞内信号分子即第二信使，如cAMP。它或调控特异的酶反应，或改变一个特异的或一套特异基因翻译形成蛋白质的速度。脂溶性激素则不同，其激素-受体复合物自身携带信使，直接调控基因表达。","src":"第19讲 激素1"},{"id":"fb932169","s":"b","g":"b08","n":"放射免疫测定","e":"Radioimmunoassay（RIA）","d":"放射免疫测定是Rosalyn Yalow和Solomon A. Berson发展起来的免疫测定方法，可在痕量水平定量和特异测定激素。由于激素浓度极低（10-6~10-12 M，而血糖为4×10-3 M），难以分离、鉴定及精确测定，此前的化学方法及整体动物或组织生物测定复杂而不灵敏、不精确、不准确。RIA使用限量的固相抗体和标记抗原，通过测定结合部分的放射性确定待测物含量；该法后来进一步发展为酶联免疫吸附测定（ELISA）。","src":"第19讲 激素1"},{"id":"d10ae03c","s":"b","g":"b08","n":"下丘脑调节激素（释放因子/释放抑制因子）Hypothalamic releasing factors","e":"","d":"下丘脑是脑组织的一个特化组织，是内分泌系统的协调中心，分泌一系列调控激素（释放因子），刺激垂体前叶分泌特定的激素并作用于下一级腺体，包括肾上腺皮质、甲状腺、卵巢、睾丸及胰腺。下丘脑调节激素均是多肽，至少分泌十种，化学本质都属肽类，且为分子量较小的多肽，分为释放因子（RF）与释放抑制因子（RIF），其作用通过名称即可知，如促甲状腺激素释放因子、生长激素释放抑制因子等。","src":"第20讲 激素2"},{"id":"3c79e5ab","s":"b","g":"b08","n":"加压素（抗利尿激素）Vasopressin / ADH","e":"","d":"加压素是垂体后叶激素之一，由较长的前体肽形成，Mr=1040，又名抗利尿激素（antidiuretic hormone，ADH）。它可增加肾中水的重吸收，并刺激血管收缩而增加血压。垂体激素表中列出抗利尿激素的主要生理作用为收缩血管、促进集尿管对水重吸收。它与催产素同属神经垂体激素，分子量相近（1040与1007），均为肽类激素，作用于平滑肌及肾小管而发挥调节水盐与血压的作用。","src":"第20讲 激素2"},{"id":"3c281ab3","s":"b","g":"b08","n":"促肾上腺皮质激素","e":"ACTH","d":"促肾上腺皮质激素是腺垂体分泌的六种促激素之一，Mr=4500，为肽类，刺激下一级分泌腺。它促使肾上腺皮质发育并刺激肾上腺皮质分泌激素（糖皮质激素等），在垂体激素表中其作用记为促进肾上腺皮质激素合成及释放。其分泌受下丘脑促肾上腺皮质激素释放因子调节，并受血中糖皮质激素水平的反馈控制。ACTH属含氮激素，通过靶细胞膜受体发挥作用，是下丘脑—垂体—肾上腺皮质轴的中枢环节。","src":"第20讲 激素2"},{"id":"6569b821","s":"b","g":"b08","n":"促甲状腺激素","e":"TSH（thyrotropin）","d":"促甲状腺激素是腺垂体分泌的促激素之一，Mr=28000，作用于甲状腺，促进甲状腺滤泡上皮细胞增生及甲状腺激素的合成和释放。其分泌受下丘脑促甲状腺激素释放激素（TRH）的刺激；血中过多的甲状腺素以及过高的体温又会抑制下丘脑与脑垂体分泌TRH和TSH，以免体温继续升高。据此说明下丘脑—垂体—甲状腺轴及其负反馈调节，该轴最终调节机体的代谢速率与产热。垂体激素表把其作用记为促进甲状腺激素合成及释放。","src":"第20讲 激素2"},{"id":"6de2dd19","s":"b","g":"b08","n":"促滤泡激素（卵泡刺激素）FSH","e":"","d":"促滤泡激素是腺垂体分泌的促激素之一，为糖蛋白，Mr=24000-35000，作用于性腺，刺激性器官发育及性激素分泌；在垂体激素表中其作用记为促进卵泡或精子生成。它与促黄体生成素同属垂体促性腺激素，二者协同调节性腺的发育与分泌功能。作为肽类（糖蛋白）激素，FSH属含氮激素，受体位于靶细胞膜上，经胞内第二信使传递信号而发挥效应。其分泌受下丘脑促卵泡激素释放因子调节，与LH协同作用。","src":"第20讲 激素2"},{"id":"25d162b4","s":"b","g":"b08","n":"促黄体（生成）激素","e":"LH","d":"促黄体生成素是腺垂体分泌的促激素之一，Mr=20500，作用于性腺：能刺激男性睾丸间质细胞分泌雄激素，刺激女性卵巢分泌雌激素。垂体激素表中将其主要生理作用记为促进排卵和黄体生成、刺激孕激素与雄激素分泌。它与促滤泡激素同属促性腺激素，共同调节性腺发育、配子生成和性激素分泌。LH为肽类激素，属含氮激素，通过靶细胞膜受体及胞内第二信使发挥作用。其分泌受下丘脑黄体生成素释放因子调节。","src":"第20讲 激素2"},{"id":"46caf7bb","s":"b","g":"b08","n":"生长激素","e":"GH（somatotropin）","d":"生长激素是腺垂体分泌的激素之一，也称促生长素，促进肝脏产生几种生长因子，促进骨和软骨生长以及RNA和蛋白质的合成；在垂体激素表中其作用记为促进机体生长。其分泌异常导致明显病症：GH过多在未成年时引起巨人症，成人后过多引起肢端肥大症；GH过少则引起侏儒症。生长激素没有特定的靶腺，作用比较广泛，几乎对全身组织细胞的代谢过程都发挥调节作用。其分泌异常与巨人症、肢端肥大症、侏儒症对应列出。","src":"第20讲 激素2"},{"id":"2d9e89ed","s":"b","g":"b08","n":"催乳素（催乳激素）Prolactin / LTH","e":"","d":"催乳素是腺垂体分泌的激素之一，Mr=27400，刺激乳腺分泌乳汁及黄体分泌孕酮；垂体激素表中记为刺激乳房发育及泌乳。其分泌受下丘脑催乳激素释放因子与催乳激素释放抑制因子的双重调控，属下丘脑—垂体轴调节的激素之一。催乳素为肽类激素，属含氮激素，其受体位于靶细胞膜上，经胞内信号分子传递信息而发挥作用。它与催产素共同参与哺乳活动，后者引起哺乳期间乳腺平滑肌收缩而排乳。","src":"第20讲 激素2"},{"id":"ed91aafa","s":"b","g":"b08","n":"瘦素","e":"Leptin","d":"瘦素是1994年发现的脂肪组织分泌的蛋白质激素，名称源自希腊语Leptos（thin，瘦），为166或167个氨基酸的小蛋白，去除21个氨基酸残基后为成熟肽，是ob（obese）基因的表达产物。与胰岛素、胰高血糖素及肾上腺素（几秒或几分钟）的调节作用不同，瘦素通过控制饮食和促进能量消耗控制哺乳动物体重（人：25-55岁）。脂肪组织反馈信号作用到脑中心，控制饮食行为和活动。缺乏瘦素引起肥胖。","src":"第20讲 激素2"},{"id":"4acdd32f","s":"b","g":"b08","n":"环腺苷酸","e":"cAMP（第二信使）","d":"cAMP是腺苷酸环化酶催化生成的环腺苷酸，是肾上腺素等激素作用于靶细胞后产生的胞内第二信使。Sutherland等揭示了肾上腺素激活糖原磷酸化酶的作用机理，确定cAMP是对胞外肾上腺素产生反应的胞内信使，整个过程是一种级联式放大作用，单分子激素可改变上万分子酶的催化活性。以cAMP为第二信使的激素有胰高血糖素、肾上腺素、促肾上腺皮质激素、甲状旁腺激素、促甲状腺激素、促滤泡激素、促黄体生成素等。","src":"第20讲 激素2"},{"id":"aa99e9ae","s":"b","g":"b08","n":"Gs蛋白（GTP结合蛋白）Gs protein","e":"","d":"Gs蛋白是介于激素受体与腺苷酸环化酶之间起穿梭作用的GTP结合蛋白。肾上腺素的作用机理涉及5种主要蛋白质：质膜上的激素受体、催化cAMP形成的腺苷酸环化酶、受体与环化酶间穿梭的Gs蛋白、依赖cAMP的蛋白激酶和环腺苷酸磷酸二酯酶。以cAMP为第二信使的激素通过Gs蛋白激活腺苷酸环化酶；另有一些激素通过抑制腺苷酸环化酶降低cAMP水平、抑制蛋白磷酸化而发挥作用，其穿梭蛋白是Gi。","src":"第20讲 激素2"},{"id":"80e1222f","s":"b","g":"b08","n":"胰岛素受体","e":"Insulin receptor","d":"胰岛素受体是一种酪氨酸特异性的蛋白激酶，其本身即为蛋白质激酶，能催化将ATP的磷酸基转移给胞内域的Tyr使之磷酸化。受体有两个α-链（亚基）盘曲于膜外，两个跨膜的β-亚基，羧基端在胞质面；α-亚基有胰岛素结合位点，β-亚基有酪氨酸激酶功能域。NIDDM的有些情况就是激酶域发生了突变，胰岛素与突变受体结合不产生效应。据此说明受体酪氨酸激酶在信号转导中的作用。","src":"第20讲 激素2"},{"id":"ab5cd6c3","s":"b","g":"b08","n":"环鸟苷酸","e":"cGMP（第二信使）","d":"cGMP是鸟苷酸环化酶催化GTP生成的环鸟苷酸，在一些细胞中也作为第二信使起作用，包括肠衬细胞、心脏、血管、脑、肾集合管。cGMP携带的信息依作用组织的不同而不同：在肾和肠中引起离子运输及吸水潴留的改变，在心脏平滑肌中是肌肉舒张的信号，在脑中可与发育成熟的成人功能及发育中的脑功能有关。NO即通过cGMP激活二级信号，cGMP再激活PKG，进而引起血管舒张等生物学效应。","src":"第20讲 激素2"},{"id":"6d4bf6ba","s":"b","g":"b08","n":"鸟苷酸环化酶","e":"Guanylate cyclase（GC）","d":"鸟苷酸环化酶是催化GTP生成cGMP的酶，分为可溶性（sGC）与膜结合型（mGC、rGC）两类，后者具有受体功能。cGMP的产生即通过鸟苷酸环化酶的酶促反应，其灭活则通过磷酸二酯酶水解。在内皮细胞中，NO扩散至邻近细胞后激活胞浆内可溶的鸟苷酸环化酶，催化GTP生成cGMP，cGMP再激活PKG，引起血管平滑肌舒张、血管扩张。cGMP的产生与灭活两条途径及可溶性与膜结合型两类酶。","src":"第20讲 激素2"},{"id":"5ba724c5","s":"b","g":"b08","n":"磷脂酰肌醇水解产生的两种第二信使（DAG与IP3）","e":"","d":"第三类信号受体通过G蛋白与质膜上特异的磷脂酶C相偶联，水解磷脂酰肌醇生成二脂酰甘油（DAG）和1,4,5-肌醇三磷酸（IP3）。二脂酰甘油通过激活膜结合的依赖Ca2+的酶——蛋白激酶C起作用，后者使特异靶蛋白磷酸化而改变它们的催化活性；蛋白激酶C有许多同工酶，但都有组织分布特性及对Ca2+和二脂酰甘油激活的敏感性。肌醇三磷酸则促使内质网释放Ca2+，使胞浆Ca2+浓度升高，进而激发细胞反应。","src":"第20讲 激素2"},{"id":"72d307a8","s":"b","g":"b08","n":"钙调蛋白","e":"Calmodulin（CaM）","d":"钙调蛋白是一种Ca2+结合蛋白，作为蛋白激酶的酶结合亚基发挥作用。Ca2+作为第二信使激发胞内反应的一种方法，是激活各种依赖Ca2+的酶，包括Ca2+/钙调蛋白依赖的蛋白激酶，该酶的调节亚基即钙调蛋白。在血管内皮细胞中，ACh作用于M受体后激活PLC生成IP3，内质网释放Ca2+使胞浆Ca2+浓度升高，借助钙调蛋白激活NOS生成NO。NO的活性也受Ca2+/CaM调节。","src":"第20讲 激素2"},{"id":"f62e7a93","s":"b","g":"b08","n":"一氧化氮","e":"Nitric oxide（NO）","d":"NO是一个不稳定的气态自由基，能作为细胞间的信息使者，有广泛的生理作用，包括血管舒张、抗血小板活性、调节神经传导和对疾病的免疫抵抗。NO是一种气体信号分子，可快速扩散透过细胞膜，作用于邻近细胞而发挥生理效应。很多细胞可以产生NO，如内皮细胞、神经细胞等。NO扩散至邻近细胞后激活胞浆内可溶的鸟苷酸环化酶，催化GTP生成cGMP，cGMP激活PKG，进而引起血管舒张等生物学效应；其活性受Ca2+/CaM调节。","src":"第20讲 激素2"},{"id":"58802fe3","s":"b","g":"b08","n":"神经肽Y Neuropeptide Y（NPY）","e":"","d":"NPY是代谢神经肽，由36个氨基酸组成，能促进食欲和减少热量生成。讨论瘦素作用阶层时指出，瘦素并不是控制摄食行为和体重的唯一激素：胰岛素分泌与脂肪组织大小及能量平衡（血糖水平）相关，胰岛素与下丘脑中的受体作用抑制摄食，同时对肌肉、肝脏和脂肪组织发出信号促进分解代谢。几种使食欲减退的神经肽被很好研究，如α-黑色素细胞刺激素（α-MSH），由前体阿黑皮素原生成。","src":"第20讲 激素2"},{"id":"8ea5e4e0","s":"b","g":"b09","n":"生物膜","e":"Biomembrane","d":"生物膜是以脂类（膜脂）、蛋白质（膜蛋白）、糖类（膜脂及膜蛋白的共价连接物）为主体形成的大分子复合物，组成上的差异与其功能密切相关。生物膜包括细胞（外）膜及细胞内膜（细胞器膜）。任何细胞都有膜状结构（厚4-7 nm）将细胞与环境隔开，这层膜就是细胞质膜，起着调节细胞和内环境相对稳定的作用；真核细胞的亚细胞结构也具有类似的膜系统。生物膜的形成对于物质、能量的贮存及细胞间的通讯起着中心作用。","src":"第21讲 生物膜和运输"},{"id":"bc53f891","s":"b","g":"b09","n":"细胞质膜","e":"Plasma membrane","d":"细胞质膜是包围在细胞外表、将细胞与环境隔开的膜状结构，厚约4—7 nm，起着调节细胞和内环境相对稳定的作用。它是生物膜的一部分，与细胞内膜（细胞器膜）相对。质膜对多数极性分子或带电分子不通透，允许非极性分子通透；膜上的泵可逆跨膜梯度转运特定的有机物和无机离子，质膜上的受体能感受胞外信号并转化为细胞内的分子事件。生物膜的基本功能之一是作为细胞独立空间的界限，并有选择性阻隔效果。","src":"第21讲 生物膜和运输"},{"id":"7fa98294","s":"b","g":"b09","n":"脂双层（磷脂双分子层）Lipid bilayer","e":"","d":"脂双层是生物膜的基本结构。无论是甘油磷脂还是鞘脂，都是两亲性分子，这一特征决定了它们在生物膜中的双分子层排列：磷脂分子疏水尾相对、极性头朝外，疏水的烃部分完全不与水相接触，极性头部与水接触。生物膜的厚度（电镜测定为5-8 nm）由3 nm的脂双层和蛋白的厚度决定，所有证据都支持生物膜由脂双层构成。脂双层本身是稳定的，但单个磷脂和固醇分子可在脂质平面内运动。磷脂在水中还可形成微团、单分子层和双层微囊等形式。","src":"第21讲 生物膜和运输"},{"id":"bb5efecd","s":"b","g":"b09","n":"贯穿性膜蛋白","e":"Integral membrane protein","d":"贯穿性膜蛋白是依与双层脂质之间立体结构位置划分的三类膜蛋白之一，主要以α-螺旋结构贯穿双层脂质，双层脂质区可含有20至30个氨基酸残基；可由氨基酸序列预测此种α-螺旋结构，例如钠钾泵。整合蛋白（内在蛋白、贯穿性蛋白）占膜蛋白的70-80%，部分或全部嵌入膜内，有的则全部跨膜分布，如受体、通道、离子泵、膜孔、运载体以及各种膜酶等。以外周蛋白与之对照：后者与膜结合松散、可逆，易释放且溶于水。","src":"第21讲 生物膜和运输"},{"id":"f6e20e06","s":"b","g":"b09","n":"附着性膜蛋白（外周蛋白）Peripheral membrane protein","e":"","d":"附着性膜蛋白又称外周蛋白，是膜蛋白的一类，蛋白质以非共价方式附着于膜脂或贯穿性膜蛋白上。许多外周蛋白通过与嵌入蛋白的亲水区域或膜脂的极性头部以静电作用或氢键结合到膜上，通过温度改变、破坏静电或氢键作用（如加入螯合剂、尿素、碳酸盐或改变pH）可被释放出来。它们可作为膜结合酶的调节因子、连接膜内蛋白与胞间结构的中介物，或控制一些膜蛋白的流动性。外周蛋白与膜的连接是可逆的，易于分离且溶于水。","src":"第21讲 生物膜和运输"},{"id":"97465b82","s":"b","g":"b09","n":"附脂性膜蛋白（锚定蛋白）Lipid-anchored protein","e":"","d":"附脂性膜蛋白又称锚定蛋白，是依与双层脂质立体结构位置划分的三类膜蛋白之一，蛋白质以共价键连于膜脂质的脂肪酸（fatty acid）或异戊二烯基（prenyl group）上。有些膜外周蛋白与膜脂有一个或多个共价结合位点，如长链脂肪酸或磷脂酰肌醇糖基化衍生物，连接的脂提供了一个疏水的锚以插入脂双分子层。糖基化磷脂酰肌醇（GPI）锚定蛋白质是真核生物细胞质膜上非常重要的一类膜蛋白。","src":"第21讲 生物膜和运输"},{"id":"8620a254","s":"b","g":"b09","n":"整合蛋白（内在蛋白）Integral protein","e":"","d":"整合蛋白又称内在蛋白，占膜蛋白的70-80%。它们部分或全部嵌入膜内，有的全部跨膜分布，如受体、通道、离子泵、膜孔、运载体以及各种膜酶等。整合蛋白靠疏水效应与膜脂结合，其分子上非极性基团的氨基酸侧链与脂双层疏水部分发生疏水相互作用，分布上埋于脂双层疏水区（水不溶性）、部分嵌在脂双层中或横跨全膜。它们与膜结合紧密，由膜上释放时要用去污剂、有机溶剂、变性剂等特别试剂。","src":"第21讲 生物膜和运输"},{"id":"7b713520","s":"b","g":"b09","n":"冰冻蚀刻","e":"Freeze-etching","d":"冰冻蚀刻是在冰冻断裂技术基础上发展起来的复型技术：将冰冻断裂样品的温度稍微升高，让样品中的冰在真空中升华，在表面上浮雕出细胞膜的超微结构；大量冰升华后，对浮雕表面进行铂-碳复型，并在腐蚀性溶液中除去生物材料，复型经重蒸水多次清洗后置于载网上进行电镜观察。冰冻断裂复型技术则先将样品在液氮中快速冷冻以防冰晶形成，真空下用冰刀横切，露出的两个面分别称P面和E面，可清楚观察到镶嵌蛋白。","src":"第21讲 生物膜和运输"},{"id":"f01a2251","s":"b","g":"b09","n":"三夹板模型（Danielli-Davson模型）","e":"","d":"三夹板模型是Danielli与Davson在脂双层基础上提出的生物膜分子结构模型，用以解释蛋白质定位的问题。其要点是：两层磷脂分子的脂肪酸烃链伸向膜中心，极性端面向膜两侧水相；蛋白质分子以单层覆盖两侧，形成蛋白质—脂质—蛋白质的\"三明治\"或\"三夹板\"结构。该模型突出了脂双层的核心地位并解释了蛋白质在膜两侧的位置；1972年Singer和Nicolson又提出了流动镶嵌模型。","src":"第21讲 生物膜和运输"},{"id":"2af6cb0b","s":"b","g":"b09","n":"流动镶嵌模型","e":"Fluid mosaic model","d":"流动镶嵌模型是1972年S. J. Singer和G. L. Nicolson提出的生物膜结构模型，认为膜是蛋白质镶嵌在粘滞的流体状脂质双层中所形成的。根据疏水相互作用，双分子层中的基质是脂质，蛋白质靠静电相互作用结合在脂质的极性头部（外周膜蛋白），或镶嵌在双分子层的疏水性区域（内在性膜蛋白），即膜的镶嵌特性。主要特征还包括：膜蛋白可侧向运动而不能翻滚；膜的不对称性保证膜功能的方向性；糖类多以糖蛋白、糖脂形式结合在细胞表面。","src":"第21讲 生物膜和运输"},{"id":"9aa30f2d","s":"b","g":"b09","n":"翻转运动","e":"Flip-flop","d":"翻转运动是磷脂分子在脂双层中发生的跨双分子层运动，即脂分子从双层的一侧翻转到另一侧，形象地称之为\"翻跟头\"。膜脂在不断地流动：脂双层结构本身稳定，但单个磷脂和固醇分子可在脂质平面内运动，横向运动很快，几秒内可环绕红细胞一周；双分子层的内部也是流动的，脂肪酸碳氢链可通过碳碳旋转不断运动；另一种运动就是跨双分子层运动即flip-flop。膜流动的程度依赖于膜脂的组成及温度。","src":"第21讲 生物膜和运输"},{"id":"fe5c0898","s":"b","g":"b09","n":"膜融合","e":"Membrane fusion","d":"膜融合是生物膜的一个明显特征，即一个膜可以与另一个膜融合而不失去其完整性，是许多生物过程的中心事件。外吞、内饮、细胞分裂、精卵细胞融合、膜包裹病毒进入宿主细胞等都涉及膜的重新形成，其最基本的行为就是两个膜片段的融合而不失去完整性。为了融合，两个膜必须首先相互靠近到分子距离（几个纳米），胞内钙离子浓度的增加是如胞吐等融合事件的信号。融合需要膜相互识别、表面靠近并相对、双层结构部分破坏，最终两个双分子层融合为一个连续的脂双分子层。","src":"第21讲 生物膜和运输"},{"id":"35355e55","s":"b","g":"b09","n":"膜联蛋白","e":"Annexin","d":"膜联蛋白是质膜下存在的一组蛋白，需要Ca2+，与脂双分子层的磷脂结合，体外可引起脂质体的融合，可交叉连接两个不同膜的脂质分子，使两个膜紧靠和稳定相对。它与融合蛋白共同参与膜融合过程：融合蛋白参与膜融合，引起特异识别和短暂、局部的脂双层结构变形，促使膜融合，可搭起膜融合的桥，引起融合区域脂双分子层的暂时恢复。受体调节的内吞或分泌还要求融合发生在合适的时间或对特异信号的反应。","src":"第21讲 生物膜和运输"},{"id":"6867bf48","s":"b","g":"b09","n":"被动转运","e":"Passive transport","d":"被动转运是物质从高浓度的一侧通过膜转运到低浓度的一侧，即沿着浓度梯度（膜两边的浓度差）的方向跨膜转运的过程。这类转运通过被转运物质本身的扩散作用进行，是一个不需要外加能量的自发过程；许多物质的被动转运过程需要特殊的蛋白载体帮助。被动转运是由膜蛋白促进的顺浓度梯度扩散；极性溶质或离子的过膜运输由膜上的蛋白降低活化能，对特异的物质提供过膜路径。简单扩散与协助扩散均属被动转运，区别在于是否需要膜蛋白协助。","src":"第21讲 生物膜和运输"},{"id":"54d725e0","s":"b","g":"b09","n":"主动转运","e":"Active transport","d":"主动转运是在外加能量驱动下进行的物质跨膜转运过程，即逆浓度梯度运输，引起物质的积累。主动转运直接或间接依赖于一些放能过程，非热力学自动发生，往往伴随光的吸收、氧化作用、ATP水解或其他顺浓度梯度的运输。其特点是逆浓度梯度、需能、都有载体蛋白。在初级主动运输中，物质的积累直接与放能反应（如ATP→ADP+Pi）相连接；次级主动运输则发生于由初级主动运输引起的逆浓度积累的顺浓度梯度运输。","src":"第21讲 生物膜和运输"},{"id":"b842d96d","s":"b","g":"b09","n":"渗透作用","e":"Osmosis","d":"渗透作用是在溶质浓度梯度、压力梯度、或者两者共同作用下，水分子通过差异性通透膜的移动。若袋内及袋外均装蒸馏水，溶质浓度内外相同，则无水浓度梯度，任何方向均无净移动。水是一种例外，可很快透过生物膜，其机制尚不清楚；膜两侧溶质浓度差异大时，渗透压的不平衡引起膜两侧水的流动，直至两侧的渗透压相等。据此说明水分子跨膜运动的驱动力来自渗透压差，而非需要载体的主动过程。","src":"第21讲 生物膜和运输"},{"id":"4215237a","s":"b","g":"b09","n":"简单扩散","e":"Simple diffusion","d":"简单扩散是被动转运的一种，其特点是顺浓度梯度（电化学梯度）方向扩散（由高到低）、不需能量、无膜蛋白协助。分子或离子朝浓度较低处自由运动称为扩散作用；物质扩散方向取决于其本身浓度梯度，与其他物质无关，每种物质的扩散是独立的；当没有浓度梯度时，任何方向之净移动为零。扩散作用为物质进出细胞的短距离运输方式。简单扩散因膜的选择性通透屏障而受限，极性分子或带电溶质需先解除水化膜的作用。","src":"第21讲 生物膜和运输"},{"id":"7fb0efd2","s":"b","g":"b09","n":"协助扩散","e":"Facilitated diffusion","d":"协助扩散是被动转运的一种，其特点是顺浓度梯度、不需能量、需特异膜蛋白。转运膜蛋白分两类：载体蛋白（亦称通透酶）和通道蛋白。载体蛋白的运输特点为：比自由扩散转运速率高；存在最大转运速率，一定限度内运输速率同物质浓度成正比，超过限度后浓度增加也不增加运输速率，因膜上载体蛋白的结合位点已饱和；有特异性，即与特定溶质分子相结合。红细胞葡萄糖渗透酶即通过促进扩散把血浆葡萄糖送入红细胞。","src":"第21讲 生物膜和运输"},{"id":"35d0df23","s":"b","g":"b09","n":"通透酶","e":"Permease","d":"通透酶是协助扩散中的载体蛋白，与特定溶质分子相结合，如葡萄糖的通透酶只与D-葡萄糖结合（亦可与D-半乳糖、D-甘露糖等结合），但不能和L-葡萄糖等L型异构体结合。通透酶与酶不同：被运输的物质不改变构型，而运输蛋白本身将发生构象的可逆变化。红细胞葡萄糖渗透酶有12个疏水区域（Mr=45000），可能跨膜12次，可使葡萄糖进入细胞内的速度大于没有时的50000倍。","src":"第21讲 生物膜和运输"},{"id":"daad3445","s":"b","g":"b09","n":"协同运输","e":"Cotransport","d":"协同运输是红细胞膜上氯化物和碳酸氢盐跨膜运输的方式。红细胞膜上存在另一种促进扩散系统——阴离子交换体，对于肌肉及肝脏中CO2回到肺的运输是必需的：CO2由血浆进入红细胞转化为HCO3-，HCO3-重新回到血浆被运输到肺组织；因HCO3-比CO2的溶解度大，这种变化增加了由组织到肺的CO2运输的血容量，在肺中HCO3-重回红细胞被转化为CO2缓慢呼出。氯化物-碳酸氢盐交换体又称阴离子交换蛋白，这一系统也称协同运输系统。","src":"第21讲 生物膜和运输"},{"id":"149e6768","s":"b","g":"b09","n":"钠钾泵","e":"Sodium-potassium pump","d":"钠钾泵是一种主动运输系统，有助于维持细胞内高浓度钾及低浓度钠。其结构为2大亚基2小亚基的四聚体，每一循环消耗一个ATP，运出3个Na+、运进2个K+，Mg2+和少量膜脂有助于其活性提高。其意义为：维持细胞的渗透压；造成膜电位，可提供肌肉和神经细胞传导电冲动；可提供糖、氨基酸等水溶性小分子间接主动运输的能源。Na+K+-ATPase是一种运输蛋白的典型形式，被称为P型ATPase，可以可逆磷酸化。","src":"第21讲 生物膜和运输"},{"id":"fc4b4f83","s":"b","g":"b09","n":"脂质体","e":"Liposome","d":"脂质体是人工将磷脂在水溶液中制成的一种脂双层包围的脂质微球体，即由磷脂形成的封闭的双分子层球形或椭圆形囊泡结构。由于脂质体在结构上与细胞相似，是研究细胞膜结构与功能的理想模型；作为运载工具，脂质体与生物体细胞相互作用（膜融合、吞噬等），可把一些物质运入细胞内，将特殊功能的生物大分子（酶、抗体、核酸、单个基因）及小分子药物定向导入特定的细胞，是重要的生物医学材料。","src":"第21讲 生物膜和运输"},{"id":"127eb4ac","s":"b","g":"b10","n":"新陈代谢（代谢）Metabolism","e":"","d":"是生物体内物质变化与能量转化的总称，指生物体活细胞内所有化学变化，也称为代谢。其分为分解代谢（异化作用）与合成代谢（同化作用）两种代谢作用，并说明每种代谢作用都包含物质代谢与能量代谢两个方面：前者是体内物质的合成与分解，涉及能量的储存、释放或转移，后者是物质代谢中能量的转换、储存和释放。代谢的速率和方向随生理状态改变：生长旺盛时合成代谢大于分解代谢，成年的生物两者相当，衰老或饥饿时合成代谢小于分解代谢，可见它是生命活动的基础。","src":"第1讲 代谢总论"},{"id":"df76c96c","s":"b","g":"b10","n":"分解代谢Catabolism","e":"","d":"属于新陈代谢的两种代谢作用之一，又称异化作用，指有机体分解物质、释放能量、提供还原力和生物合成中间产物的过程。分解代谢分解糖、脂和蛋白质等有机物，将其转化为更小、更简单的终产物，如乳酸、CO2和NH3等，释放的能量一部分被转化为ATP和还原型电子载体NADH、NADPH和FADH2，其余的作为热量散失。它既为机体提供可利用的能量与还原力，又为合成代谢供应前体物质，其速率在衰老或饥饿时高于合成代谢。","src":"第1讲 代谢总论"},{"id":"acd23b77","s":"b","g":"b10","n":"合成代谢Anabolism","e":"","d":"属于新陈代谢的两种代谢作用之一，又称同化作用，指有机体利用能量以小分子物质合成能量更高的（较）大分子物质并储存能量的过程。合成代谢以小或简单的前体物质合成更大、更复杂的分子，如脂、多糖、蛋白质和核酸等，合成代谢需要能量的输入，通常需要ATP和还原力（NADH、NADPH和FADH2）。它与分解代谢方向相反、相互联系，在生长旺盛的生物体中强于分解代谢，在成年生物中与分解代谢相当。","src":"第1讲 代谢总论"},{"id":"46ad1fa1","s":"b","g":"b10","n":"物质代谢Substance metabolism","e":"","d":"属于新陈代谢所包含的两个方面之一，指生物体内发生的物质的合成与分解作用，涉及能量的储存、释放或转移。每种代谢作用都包含物质代谢和能量代谢两个方面，二者是同一过程的不同侧面：物质代谢侧重物质本身的转变，能量代谢侧重伴随发生的能量转换。分解代谢中物质被分解、能量被释放，合成代谢中物质被合成、能量被储存，因此物质代谢的流向同时决定了能量的流向，是研究代谢的物质基础。","src":"第1讲 代谢总论"},{"id":"1d1cd66e","s":"b","g":"b10","n":"能量代谢Energy metabolism","e":"","d":"属于新陈代谢所包含的两个方面之一，指物质代谢中能量的转换、储存和释放。其与物质代谢并列，说明每种代谢作用都同时包含这两个方面。分解代谢释放的能量部分转化为ATP和还原型电子载体NADH、NADPH、FADH2，其余以热量散失；合成代谢则消耗ATP和还原力。此外，与物质循环相比能量只以一种方式流向生物圈，代谢中一部分自由能耗失并不可逆地转变为无用能（热和熵），生物不能再利用。","src":"第1讲 代谢总论"},{"id":"1a356204","s":"b","g":"b10","n":"自养生物Autotrophs","e":"","d":"按从环境中获得碳的化学形式划分的两大生物类型之一，指能自行制造有机营养物质的有机体，如绿色植物，能通过光合作用产生有机物质。自养生物利用空气中的CO2建造自己的有机生物分子，有些还分解水产生O2；植物利用铵或硝酸盐作为唯一氮源。在生物圈中自养生物与异养生物生活在一起，二者之间C、O2和H2O不断循环，太阳能是推动其循环的驱动力，因此自养生物是生物圈有机物质和能量的最初提供者。","src":"第1讲 代谢总论"},{"id":"d92b9230","s":"b","g":"b10","n":"异养生物Heterotrophs","e":"","d":"按从环境中获得碳的化学形式划分的两大生物类型之一，指不能自行制造有机营养物质、只能依赖现成的有机营养物质的生物，如所有动物，以及生活在腐生生物和寄生生物中的微生物。异养生物利用自养生物合成的有机物作为营养物质，呼吸O2并将CO2排放到大气中去，有些在氧化反应中消耗O2产生水。它们与自养生物共同维持生物圈中C、O2和H2O的循环，其所需的能量最终来自太阳能。","src":"第1讲 代谢总论"},{"id":"50be0d96","s":"b","g":"b10","n":"自由能Free Energy","e":"","d":"指一个反应体系中能够做功的那部分能量，符号为G。1878年Josiah Willard Gibbs结合热力学第一和第二定律提出了自由能公式ΔG=ΔH-TΔS，其中ΔH代表体系的热焓变化，ΔS代表熵的变化。自由能对生物体重要：不仅可用以判断生物体内的某一过程能否自发进行，而且生物体内能用于做功的能也正是体内生物化学反应释放出的自由能，因此它是衡量代谢反应能量变化的核心物理量。","src":"第1讲 代谢总论"},{"id":"93b8d0ca","s":"b","g":"b10","n":"自由能的变化ΔG","e":"","d":"指产物自由能与反应物自由能之差，与反应转变过程无关。对反应A+B→C+D，ΔG=(GC+GD)-(GA+GB)，且ΔG=ΔG0+RTln([C][D]/[A][B])，其中R为摩尔气体常数8.315 J/(mol·K)，T为热力学温度。由此判断反应方向：ΔG<0时释放自由能、反应自发进行；ΔG=0时只做体积功、不做有用功，反应可逆；ΔG>0时反应不能自发进行、需要提供能量，这一判据适用于生物体内的一切代谢反应。","src":"第1讲 代谢总论"},{"id":"86ad11d0","s":"b","g":"b10","n":"标准自由能的变化ΔG0与ΔG0′","e":"","d":"指在规定的标准条件下反应的标准自由能变化，用于比较不同反应释能的多少。条件是：ΔG0为298K、101.3kPa、反应物浓度1mol/L；生化反应中常用的ΔG0′除上述条件外还规定pH=7。它是自由能变化计算式ΔG=ΔG0+RTln([C][D]/[A][B])中的常数项，以此为基准比较磷酸化合物水解的释能，如ATP与ADP水解的ΔG0′均为-30.5 kJ/mol，AMP水解为-14.2 kJ/mol。","src":"第1讲 代谢总论"},{"id":"a09d4215","s":"b","g":"b10","n":"高能磷酸键","e":"","d":"生化中把磷酸化合物水解时释出的能量＞25 kJ/mol者所含的磷酸键称为高能磷酸键，常用∽P表示。以磷酸苷类为例说明：ATP水解为ADP和Pi、ADP水解为AMP和Pi的ΔG0′均为-30.5 kJ/mol，其中所含的即为高能磷酸键；而AMP水解为腺苷和Pi的ΔG0′为-14.2 kJ/mol，低于25 kJ/mol的界限。含有高能键的化合物称为高能化合物，高能磷酸键是体内能量转移和储存的通用形式。","src":"第1讲 代谢总论"},{"id":"e33bc2d3","s":"b","g":"b10","n":"高能化合物High energy compound","e":"","d":"指含有高能键的化合物。按高能键的类型列举其种类：磷酸酐类有ATP、ADP、UTP、CTP、PPi等，烯醇磷酸类有PEP，混合酐类有1,3-二磷酸甘油酸，磷酸胍类有磷酸肌酸，另有高能硫酯键如乙酰CoA、脂酰CoA等；以水解释能＞25 kJ/mol作为判别高能磷酸键的界限。这些化合物水解时释放较多自由能，是代谢中能量转移的供体与载体，其中ATP最为通用，磷酸肌酸则是肌肉及脑组织中的能量贮存形式。","src":"第1讲 代谢总论"},{"id":"499998fc","s":"b","g":"b10","n":"别构调节Allosteric regulation","e":"","d":"又称别位调节，属于分子水平代谢调节中酶分子活性调节的一种。指某些物质能与酶分子上的非催化部位特异结合，引起酶蛋白的分子构象发生改变，从而改变酶的活性。受这种调节作用的酶称为别构酶，能使酶发生变构效应的物质称为变构效应剂；变构后引起酶活性增强的效应剂称为激活变构剂或正效应物，反之称为抑制变构剂或负效应物。它使代谢物浓度的变化能即时影响酶活性，是代谢快速调节的重要机制。","src":"第1讲 代谢总论"},{"id":"9666d79c","s":"b","g":"b10","n":"别构酶Allosteric enzyme","e":"","d":"又称变构酶，指受别构调节作用、其活性可因非催化部位结合某些物质而改变的一类酶。某些物质与酶分子上的非催化部位特异结合后，引起酶蛋白分子构象改变，进而改变酶的活性，这类酶即别构酶；与之结合并引起变构效应的物质称为变构效应剂，其中使活性增强者称激活变构剂或正效应物，使活性降低者称抑制变构剂或负效应物。别构酶是代谢调节中感受效应物浓度并作出快速反应的元件。","src":"第1讲 代谢总论"},{"id":"2f1bb02b","s":"b","g":"b10","n":"变构效应剂Allosteric effector","e":"","d":"指能使酶发生变构效应、即与酶分子非催化部位特异结合并引起酶蛋白构象改变的物质。按作用结果将其分为两类：变构后引起酶活性增强的称为激活变构剂或正效应物，反之称为抑制变构剂或负效应物。效应物与酶非催化部位结合后引起的构象改变，可表现为酶活性的增强或减弱两种结果，因而它不必参与催化反应本身，就能把代谢物浓度的变化转化为酶活性的变化，是代谢反馈调节的中间环节，其结合部位与底物结合的催化部位不同。","src":"第1讲 代谢总论"},{"id":"fb018109","s":"b","g":"b10","n":"酶的酶促化学修饰Chemical modification","e":"","d":"属于分子水平酶活性调节的方式之一。指酶分子肽链上的某些基团在另一种酶的催化下发生可逆的共价修饰，从而引起酶活性改变的过程。修饰类型包括磷酸化和脱磷酸、乙酰化和去乙酰化、腺苷化和去腺苷化、甲基化和去甲基化以及-SH基与-S-S-基互变等，其中磷酸化和脱磷酸作用在物质代谢调节中最为常见。由于修饰可逆且由另一种酶催化，此类调节能使酶活性在两种状态间快速切换。","src":"第1讲 代谢总论"},{"id":"980e8b59","s":"b","g":"b10","n":"诱导剂Inducer","e":"","d":"属于酶含量调节中酶蛋白合成诱导与阻遏的一类作用物。酶的底物或产物、激素以及药物等都可以影响酶的合成，一般将加强酶合成的化合物称为诱导剂，减少酶合成的化合物称为阻遏剂。诱导剂和阻遏剂可在转录水平或翻译水平影响蛋白质的合成，以影响转录过程较为常见。例子表明，底物、产物、激素和药物都可作为这类影响酶合成的信号，机体据此改变酶的绝对含量来调节代谢，与酶活性的快速调节相配合。","src":"第1讲 代谢总论"},{"id":"3e751abf","s":"b","g":"b10","n":"阻遏剂Repressor","e":"","d":"属于酶含量调节中酶蛋白合成诱导与阻遏的一类作用物，指能减少酶合成的化合物，与加强酶合成的诱导剂相对应。酶的底物或产物、激素以及药物等都可以影响酶的合成，诱导剂和阻遏剂可在转录水平或翻译水平影响蛋白质的合成，以影响转录过程较为常见。它与诱导剂共同构成酶蛋白合成的诱导与阻遏调节，是酶含量调节的两个相反方向，可降低相应代谢通路的速率，从而在较长时间内改变代谢的流量与方向。","src":"第1讲 代谢总论"},{"id":"03031573","s":"b","g":"b10","n":"细胞内酶的分隔分布","e":"","d":"属于细胞水平的代谢调节方式。指酶在细胞内是分隔着分布的，代谢上有关的酶常常组成一个酶体系，分布在细胞的某一组分中：糖酵解酶系、糖原合成和分解酶系存在于胞液中，TCA酶系和脂肪酸β-氧化酶系在线粒体，核酸合成的酶系大部分集中在细胞核内。酶的隔离分布为代谢调节创造了有利条件，使某些调节因素可较为专一地影响某一细胞组分中酶的活性而不影响其他组分，从而保证整体反应的有序性。","src":"第1讲 代谢总论"},{"id":"7da1612a","s":"b","g":"b10","n":"生物氧化Biological Oxidation","e":"","d":"指糖类、脂类和蛋白质等在生物活细胞内进行的一系列的氧化分解作用，最终生成H2O和CO2，同时释放能量的过程，又称细胞呼吸或组织呼吸，相当于分解（异化）作用。1948年Eugene Kennedy和Albert Lehninger发现线粒体是真核生物生物氧化及氧化磷酸化的场所。与无机氧化（燃烧）相比，二者氧化的物质、释放的总能量和终产物都相同，但生物氧化要求温和条件、由酶催化逐步进行，能量逐步释放并以高能磷酸键形式贮存。","src":"第2讲 生物氧化 I"},{"id":"19f80950","s":"b","g":"b10","n":"线粒体嵴Cristae","e":"","d":"指线粒体内膜的褶皱或折叠，这些褶皱组织成层状结构（lamellae），称为嵴。线粒体内膜结构高度复杂，含有电子传递系统的全部复合物、ATP合成酶复合物和转运蛋白，而内膜的褶皱即嵴极大地增加了内膜的总表面积；较大的表面积使内膜能容纳比表面光滑时多得多的上述结构，从而为电子传递和氧化磷酸化提供充足的场所。同时说明外膜含孔（道）蛋白而通透性较高，内膜则仅对氧、二氧化碳和水自由透过。","src":"第2讲 生物氧化 I"},{"id":"f6d86c1c","s":"b","g":"b10","n":"脱羧作用Decarboxylation","e":"","d":"生物氧化中CO2的产生方式，指有机物在酶的作用下脱羧产生CO2的反应。按脱羧的性质将其分为直接脱羧和氧化脱羧，按脱羧的部位分为α-脱羧和β-脱羧，并举例：乙醇发酵中丙酮酸直接脱羧、草酰乙酸直接脱羧生成丙酮酸、丙酮酸氧化脱羧生成乙酰CoA、苹果酸氧化脱羧生成丙酮酸、TCA循环中α-酮戊二酸氧化脱羧生成琥珀酰CoA、异柠檬酸氧化脱羧生成α-酮戊二酸。它是生物氧化中有机物碳骨架的出路。","src":"第2讲 生物氧化 I"},{"id":"e7feae4d","s":"b","g":"b10","n":"脱氢Dehydrogenation","e":"","d":"生物氧化的方式之一，指底物脱下氢的反应，如RCH2OH-2H→RCHO。生物氧化的方式归为脱氢、加氧（氧化）和脱电子三种：脱氢是使代谢物上的氢活化、脱离，交给其他受氢体或传递体；加氧是氧原子直接参入有机分子；脱电子如Fe2+失去电子变为Fe3+。CH3CHO加水后脱氢生成CH3COOH并释出2H的例子。脱氢是生物氧化中最常见的方式，脱下的氢最终与O2结合生成H2O。","src":"第2讲 生物氧化 I"},{"id":"f0a21121","s":"b","g":"b10","n":"加氧（氧化）Oxidation","e":"","d":"生物氧化的方式之一，指氧原子直接加入底物的氧化反应，以RCHO+½O2→RCOOH为例。它与脱氢、脱电子并列为生物氧化的三种方式。与以氧为直接受氢体生成水的氧化不同，加氧反应中氧原子成为产物分子的一部分，催化此类反应的酶为加氧酶。加氧酶部分举例，儿茶酚经双氧合酶作用开环生成顺，顺-己二烯二酸，说明加氧方式可用于底物的羟化与开环转化，加氧酶催化的正是这类反应。","src":"第2讲 生物氧化 I"},{"id":"6b5d82a0","s":"b","g":"b10","n":"脱电子Deelectronation","e":"","d":"生物氧化的方式之一，指底物失去电子的氧化反应，以Fe2+-e→Fe3+为例，与脱氢、加氧并列为生物氧化的三种方式。这类反应中并无氢原子参加，只有电子的得失，因此不含氢的金属离子也能作为被氧化的底物。在呼吸链中，铁硫中心依靠铁原子的氧化还原、细胞色素依靠血红素铁的得失电子来传递电子，每次传递一个电子，最终把电子交给氧，体现了氧化还原反应的本质是电子转移，这类反应在呼吸链的金属载体上反复发生。","src":"第2讲 生物氧化 I"},{"id":"c06213c1","s":"b","g":"b10","n":"脱氢酶Dehydrogenase","e":"","d":"属于生物氧化的主要参与者，是使代谢物的氢活化、脱离，并将之传递给其他受氢体或传递体的酶，催化DH+R⇌D+RH。绝大多数脱氢酶需要NAD+（辅酶I）或NADP+（辅酶II）作为辅酶，也有以黄素核苷酸FMN或FAD作为辅基的。3-磷酸甘油醛脱氢、丙酮酸在NADH参与下还原为乳酸、琥珀酸脱氢生成延胡索酸等反应，并指出这类酶有的分布在胞质，有些分布在线粒体中，有些则两者兼有。","src":"第2讲 生物氧化 I"},{"id":"8a3acdcd","s":"b","g":"b10","n":"氧化酶Oxidase","e":"","d":"生物氧化中以氧直接为受氢体的氧化还原酶类，催化RH+O2→R+H2O或RH+O2→R+H2O2。其分为两种类型：一是金属蛋白，如含铜的抗坏血酸氧化酶，使L-抗坏血酸氧化为脱氢抗坏血酸并生成H2O；二是细胞色素氧化酶，催化4Cyt c-Fe2+ + O2→4Cyt c-Fe3+ + H2O，是呼吸链末端把电子交给氧的酶。氧化酶与加氧酶不同，后者催化氧原子直接参入有机分子。","src":"第2讲 生物氧化 I"},{"id":"80431742","s":"b","g":"b10","n":"加氧酶Oxygenase","e":"","d":"催化加氧反应的酶；与氧化酶不同，加氧酶催化氧原子直接参入有机分子。按供氢体与参入氧原子数分类：作用于一种氢供体的包括催化两个氧原子参入的双氧合酶（需铁离子或NADP作辅助因子，往往伴随开环）和催化一个氧原子参入的单氧合酶；作用于两种氢供体的也有相应两型，其中单氧合酶因反应伴随羟基形成又称羟化酶，因多含P-450又称P-450羟化体系。以邻氨基苯甲酸的双氧合和胆固醇7α-单氧合为例说明。","src":"第2讲 生物氧化 I"},{"id":"583e3b8b","s":"b","g":"b10","n":"传递体Carrier","e":"","d":"属于生物氧化的主要参与者之一，指生物氧化过程中起着中间传递氢或电子作用的物质，它们既不能使代谢物脱氢，也不能使氢活化。它与脱氢酶、氧化酶、加氧酶并列介绍：脱氢酶负责使底物上的氢活化、脱离，氧化酶以氧为直接受氢体，而传递体只在两者之间接力传递氢或电子，使电子按氧化还原电位由低到高逐级传递、能量逐步释放。呼吸链中的黄素蛋白、铁硫蛋白、辅酶Q和细胞色素都属于这类中间递体。","src":"第2讲 生物氧化 I"},{"id":"a189b7b3","s":"b","g":"b10","n":"过氧化物酶Peroxidase","e":"","d":"催化以H2O2等作为氧化剂的氧化还原反应的酶类，存在于过氧化物酶体中，负责H2O2和过氧化物的分解与转化。举例：以血红素为辅基的过氧化物酶和过氧化氢酶，后者催化2H2O2→2H2O+O2；以FAD为辅基的NAD(P)过氧化物酶，催化RH+H2O2→2H2O+R；谷胱甘肽过氧化物酶则以H2O2以外的过氧化物（如脂质过氧化物）为氧化剂，催化2GSH+ROOH→ROH+GSSG，保护细胞免受损伤。","src":"第2讲 生物氧化 I"},{"id":"ded400d2","s":"b","g":"b10","n":"超氧化物歧化酶Superoxide dismutase, SOD","e":"","d":"一种与阻断过氧化物生成有关的特殊氧化酶，是生物体的自由基清除剂，催化2O2-+2H+→H2O2+O2，它分为CuZn-SOD、Mn-SOD和Fe-SOD三种。氧自由基可聚集体表、心脏、血管、肝脏和脑细胞，使血管发生纤维性病变，导致动脉硬化、高血压、心肌梗塞，并引起记忆与智力障碍乃至老年性痴呆，是造成人类衰老和疾病的元凶，因此SOD清除超氧自由基意义重要。","src":"第2讲 生物氧化 I"},{"id":"c8b7c6cf","s":"b","g":"b10","n":"自由基Free radical","e":"","d":"一类非常活跃的化学物质，是含有不成对（奇数）电子的原子、原子团、分子和离子。其中最重要的是氧自由基，它可聚集体表、心脏、血管、肝脏和脑细胞，使血管发生纤维性病变，导致动脉管硬化、高血压、心肌梗塞，引起老年人神经官能不全、记忆与智力障碍以及抑郁症甚至老年性痴呆，是造成人类衰老和疾病的元凶；并分为无机氧自由基（超氧自由基、羟基自由基）与有机氧自由基（过氧、烷氧、多元不饱和脂肪酸、半醌自由基）。","src":"第2讲 生物氧化 I"},{"id":"1cd2a912","s":"b","g":"b10","n":"（中间）电子传递体Electron transfer","e":"","d":"指通过自身的还原和氧化，将脱氢酶和氧化酶连接起来组成呼吸链的一类物质，在生物氧化和氧化磷酸化过程中发挥重要作用。其主要包括黄素蛋白、铁硫蛋白、CoQ和细胞色素复合物。它们在呼吸链中按氧化还原电位由低到高排列，逐个接受并交出电子（其中有的兼传氢），使脱氢酶从底物上卸下的电子最终流向氧；它们既是呼吸链的结构组分，也决定了电子传递的顺序和方向，是呼吸链按顺序传递电子的结构基础。","src":"第2讲 生物氧化 I"},{"id":"8cc5bab3","s":"b","g":"b10","n":"呼吸链Respiratory Chain","e":"","d":"生物氧化体系要解决有机物脱氢及氢的去路问题，即解决有机物如何通过一系列特异性酶催化的反应脱氢、递氢和递电子，把氢交给氧生成水并产生ATP。整个氢的传递和电子的传递过程以及参与这一系列催化反应的酶、辅酶及其他中间递体一个接一个，组成链状反应体系，如同接力棒一样，这种形式的反应即呼吸链。人体最普遍最重要的是以NAD+或NADP+为辅酶的脱氢酶、黄素蛋白、辅酶Q及细胞色素复合物组成的两条呼吸链。","src":"第2讲 生物氧化 I"},{"id":"81ebf4bd","s":"b","g":"b10","n":"递氢体","e":"","d":"呼吸链中参与传递H的辅酶或辅基，与递电子体并列，二者共同构成呼吸链中除酶蛋白之外的中间递体。据此说明呼吸链的传递过程：底物脱下的氢先交给递氢体，再由递氢体传给下一载体，同时电子也随之一级级传递。呼吸链组成成分中，烟酰胺脱氢酶类、黄素酶类和辅酶Q都参与氢的传递，而铁硫中心与细胞色素只传电子，因此递氢体是氢进入呼吸链后的第一站；此外，递氢与递电子在链中相互衔接，使氢最终以水的形式交出。","src":"第2讲 生物氧化 I"},{"id":"8f80647c","s":"b","g":"b10","n":"递电子体","e":"","d":"呼吸链中参与传递电子的辅酶或辅基，与递氢体并列定义。呼吸链由一系列中间递体接力组成，其中只传递电子而不传递氢的成分即为递电子体。细胞色素类和铁硫中心是典型的递电子体：细胞色素以血红素中的铁原子得失电子，铁硫中心每次转移一个电子，它们使电子由NADH等供体经黄素酶、辅酶Q、细胞色素体系最终到达O2，并驱动质子泵出，可见递电子体主要承担链的后半段传递，其传递顺序由各载体的氧化还原电位决定。","src":"第2讲 生物氧化 I"},{"id":"9f6382ea","s":"b","g":"b10","n":"烟酰胺脱氢酶类Nicotinamide dehydrogenases","e":"","d":"又称吡啶脱氢酶类，是呼吸链的组成成分之一，指以NAD+及NADP+为辅酶、催化底物脱氢的一类酶。许多代谢中间物的脱氢都通过此类酶的作用，其辅酶有两种：NAD+（辅酶I）和NADP+（辅酶II），反应为还原型代谢物+NAD+→氧化型代谢物+NADH+H+。这类酶有些分布在胞质中，有些在线粒体中，有些则两者兼有；其还原型NADPH上的氢还可经吡啶核苷酸转氢酶转移到NAD+上形成NADH。","src":"第2讲 生物氧化 I"},{"id":"c2aa8a82","s":"b","g":"b10","n":"黄素酶类Flavoprotein","e":"","d":"又称黄素蛋白，指与黄素相关的脱氢酶，辅基中因含核黄素而得名，线粒体中可能与铁硫蛋白组成复合体。其种类多、酶蛋白不同，但辅基只有两种：FMN是NADH脱氢酶（FP1）的辅基，FAD是琥珀酸脱氢酶（FP2）的辅基；此类酶催化由NADH、琥珀酸、脂酰CoA或3-磷酸甘油分子上脱氢，生成FMNH2或FADH2，再把氢交给辅酶Q，其辅基FMN、FAD分别与FMNH2、FADH2互变而传递氢。","src":"第2讲 生物氧化 I"},{"id":"56ea0e3c","s":"b","g":"b10","n":"黄素单核苷酸FMN","e":"","d":"即黄素单核苷酸，是黄素酶类的辅基之一，为NADH脱氢酶（FP1）的辅基。反应NADH+H+ + E-FMN⇌NAD+ + E-FMNH2，说明FMN接受NADH的氢被还原为FMNH2，从而把底物脱下的氢引入呼吸链。FMN与FAD同列为黄素酶类的两种辅基，二者均含核黄素，因分子中含核黄素而呈黄色，是黄素酶传递氢所必需的辅基，在呼吸链中位于烟酰胺脱氢酶与辅酶Q之间。","src":"第2讲 生物氧化 I"},{"id":"e184d544","s":"b","g":"b10","n":"黄素腺嘌呤二核苷酸FAD","e":"","d":"即黄素腺嘌呤二核苷酸，是黄素酶类的辅基之一，为琥珀酸脱氢酶（FP2）的辅基。以琥珀酸+FAD⇌延胡索酸+FADH2为例说明其氧化还原，并指出此类酶催化由NADH、琥珀酸、脂酰CoA或3-磷酸甘油分子上脱氢，生成FMNH2或FADH2。FAD接受氢后被还原，再经铁硫中心把电子传给辅酶Q，故FAD是复合物Ⅱ及脂酰CoA脱氢酶等传递氢的必需辅基，其与FMN并列为黄素核苷酸。","src":"第2讲 生物氧化 I"},{"id":"c098e6cb","s":"b","g":"b10","n":"铁硫中心Iron-sulfur center","e":"","d":"指铁与无机硫原子和/或蛋白质Cys残基的硫原子相连形成的结构，最早由Helmut Beinert发现。最简单的铁硫中心是单个铁原子与4个Cys的-SH相连，更复杂的含有2个或4个铁原子，而Rieske铁硫蛋白则为1个铁原子与两个His残基相连。所有的铁硫蛋白参与一个电子的转移，其中的铁原子或被氧化、或被还原；线粒体中至少有8个铁硫蛋白参与电子传递，它们多与黄素蛋白结合发挥作用。","src":"第2讲 生物氧化 I"},{"id":"3bd8e4ec","s":"b","g":"b10","n":"辅酶QCoenzyme Q, CoQ","e":"","d":"又称泛醌，是脂溶性醌类化合物，有一个长的异戊二烯侧链，因广泛存在而得名，在呼吸链中是掺入线粒体内膜的电子载体。CoQ在呼吸链中接受黄素酶的氢，本身被还原为氢醌，再把电子传递给细胞色素体系而被氧化；接受1个电子变为自由基半醌，接受2个电子变为氢醌QH2。它不仅接受NADH脱氢酶的氢，还接受琥珀酸脱氢酶、脂酰CoA脱氢酶等脱下的氢，在电子传递链中处于中心地位，脂肪酸β-氧化产生的电子也经它进入呼吸链。","src":"第2讲 生物氧化 I"},{"id":"de51bd12","s":"b","g":"b10","n":"细胞色素Cytochromes","e":"","d":"含铁的电子传递体，铁原子处于卟啉结构中心，构成血红素，细胞色素类都以血红素作为辅基，使这类蛋白质呈现红色或褐色。细胞色素在呼吸链中将电子从辅酶Q传递到O2；D. Kailin根据吸收光谱将其分成a、b、c三类，线粒体的电子传递链至少含有5种不同的细胞色素：b、c1、c、a1、a3。它们依靠血红素铁的得失电子逐个传递电子，是呼吸链的末端电子载体，其中Cyt c是电子由复合物Ⅲ流向复合物Ⅳ的流动连接器。","src":"第2讲 生物氧化 I"},{"id":"4bb86956","s":"b","g":"b10","n":"复合物Ⅰ（NADH：泛醌氧化还原酶）Complex I","e":"","d":"呼吸链的电子载体复合物之一，也称NADH：泛醌氧化还原酶，催化电子由NADH转移到泛醌。它是一个大的酶复合物，由42条不同的多肽链组成，包括含FMN的黄素蛋白和至少6个铁硫中心，高分辨率电子显微镜显示为L形，一臂在膜内，另一臂伸展到基质中。它催化两个同时发生的偶联过程：NADH+H+ + Q→NAD+ + QH2，以及4个质子由基质转到内膜外，因此是由电子转移能驱动的质子泵。","src":"第3讲 生物氧化 II"},{"id":"19c0b4a9","s":"b","g":"b10","n":"复合物Ⅱ（琥珀酸脱氢酶）Complex II","e":"","d":"呼吸链的电子载体复合物之一，也称琥珀酸脱氢酶，催化电子由琥珀酸到泛醌。它是TCA循环中唯一一个线粒体内膜结合的酶，虽比复合物Ⅰ小而简单，但含有两类辅基和至少4种不同的蛋白质，其中1个蛋白质与FAD及有4个铁原子的Fe-S中心共价结合。电子由琥珀酸流向FAD，然后通过Fe-S中心到泛醌，反应为琥珀酸+Q→延胡索酸+QH2；脂酰CoA脱氢酶等的电子也流经Q但不经过复合物Ⅱ。","src":"第3讲 生物氧化 II"},{"id":"b7984746","s":"b","g":"b10","n":"复合物Ⅲ（Cyt bc1复合物）Complex III","e":"","d":"又称Cyt bc1复合物或泛醌：细胞色素c氧化还原酶，偶联催化电子由氢醌到Cyt c的转移和质子由膜内基质向膜外空间的运输。它是一个由相同单体组成的二聚体，每个单体含11个不同的亚基；功能核心有三部分：有两个血红素bH和bL的Cyt b、含2Fe-2S的铁硫蛋白和带血红素的Cyt c1。复合物有两个泛醌结合位点QN和QP，二者也是阻止氧化磷酸化的药物的作用位点。","src":"第3讲 生物氧化 II"},{"id":"fb84bc81","s":"b","g":"b10","n":"Q循环Q cycle","e":"","d":"根据复合物Ⅲ的结构和氧化还原反应研究提出的电子经该复合物流动的模型。在膜的N侧，2分子QH2被氧化为2Q，释放4个H+到内膜外空间；每个QH2提供1个电子经Fe-S中心给cyt c1，另1个电子经cyt b给Q分子，使其两步还原成QH2，还原反应还从基质中利用2个H+。转移的净效应是QH2被氧化成Q、2分子cyt c1被还原，从而实现电子由氢醌向Cyt c的传递并泵出质子。","src":"第3讲 生物氧化 II"},{"id":"fa33edb3","s":"b","g":"b10","n":"复合物Ⅳ（细胞色素氧化酶）Complex IV","e":"","d":"又称细胞色素氧化酶，是呼吸链的最后一步，把Cyt c的电子转移给O2并生成H2O。它是线粒体内膜上一个大的酶复合物，含13个亚基，Mr 204000，作用是电子传递和质子泵，其中三个亚基对功能至关重要。亚基Ⅱ有2个Cu离子（CuA）、2个细胞色素基团a1和a3以及另一个Cu离子（CuB）。电子传递为cyt c→CuA→a→a3→CuB→O2；每4个电子通过时消耗4个基质H+生成2H2O，每通过1个电子泵出1个H+。","src":"第3讲 生物氧化 II"},{"id":"e2a0d175","s":"b","g":"b10","n":"电子传递抑制剂","e":"","d":"指能阻断呼吸链某一部位电子传递的物质。利用专一性电子传递抑制剂选择性地阻断某个传递过程，再测定链中各组分的氧化-还原态情况，是研究电子传递顺序的有效而重要的方法。三类：鱼藤酮、安密妥、杀粉蝶菌素阻断电子由NADH向CoQ的传递；抗霉素A抑制b到c1的电子传递；氰化物、硫化氢、叠氮化物、CO等阻断电子由cyt aa3到氧的传递。这些抑制剂的作用位点不同，恰可用于确定各载体的先后次序。","src":"第3讲 生物氧化 II"},{"id":"adcfc88a","s":"b","g":"b10","n":"化学偶联假说Chemical coupling hypothesis","e":"","d":"关于氧化磷酸化作用机理的假说之一，认为电子传递和ATP生成的偶联是通过一系列连续的化学反应形成一个高能的共价中间物，该中间物被用于ATP的形成。该假说强调偶联的化学本质，即电子传递过程中先形成可转移的高能键，再由它把能量交给ADP以生成ATP。它与构象偶联假说、化学渗透假说并列介绍，三者分别从高能共价中间物、膜蛋白构象变化和跨内膜H+梯度解释电子传递如何驱动ATP的生成。","src":"第3讲 生物氧化 II"},{"id":"bb36aa77","s":"b","g":"b10","n":"构象偶联假说Conformational coupling hypothesis","e":"","d":"关于氧化磷酸化作用机理的假说之一，认为电子沿呼吸链传递使线粒体内膜蛋白组分发生了构象变化，而形成一种高能形式，进一步使F0F1-ATP酶高能化，用于ATP的生成。其与化学偶联假说、化学渗透假说并列列出，说明该假说把能量保存的环节归于蛋白质构象的改变而非高能共价中间物，也不涉及跨膜质子梯度；按化学偶联、构象偶联、化学渗透的顺序依次介绍这三种假说，三者构成偶联机制研究的主要线索。","src":"第3讲 生物氧化 II"},{"id":"92dd14a7","s":"b","g":"b10","n":"化学渗透假说Chemiosmotic hypothesis","e":"","d":"关于氧化磷酸化作用机理的假说，认为电子传递的结果是把H+从线粒体内膜基质泵到膜外空间，形成一个跨内膜的H+梯度，这种H+梯度的渗透能（质子推动力）用于驱动ATP的生成。由英国科学家P. Michell于1961年提出，获1978年诺贝尔化学奖。有三个实验事实支持这一假说：底物被氧化（琥珀酸生成延胡索酸）、O2被消耗、有ATP合成且依赖于可氧化底物和ADP与Pi。","src":"第3讲 生物氧化 II"},{"id":"c6afe0b9","s":"b","g":"b10","n":"ATP合成酶ATP synthase","e":"","d":"位于线粒体内膜的内表面，又称F1/F0-ATP合成酶。F1由5种亚基组成，为酶复合物的球状头部，也是活性中心，位于内膜基质表面；F0横贯内膜，含有质子通道，由4种亚基组成；茎部有寡霉素敏感蛋白（OSCP），有调节F0、F1的功能。它利用电子传递建立的质子推动力合成ATP，是氧化磷酸化的关键酶，其活性可被寡霉素抑制，从而使氧的利用和ATP的形成同时受阻。","src":"第3讲 生物氧化 II"},{"id":"943bc456","s":"b","g":"b10","n":"磷氧比P/O","e":"","d":"1940年由S. Ochoa提出，指代谢物脱下的氢经呼吸链氧化生成水时，一对电子（2H）经呼吸链传递到O2生成水所产生的ATP分子的数目，即消耗1个原子氧所产生ATP的数目，称为磷氧比。经典数值：2H经NADH氧化呼吸链被氧化为水时生成3ATP（P/O≈3），经琥珀酸氧化呼吸链氧化为水时生成2ATP（P/O≈2）；现在普遍认为分别为2.5ATP和1.5ATP。它反映氧化与磷酸化的偶联效率。","src":"第3讲 生物氧化 II"},{"id":"418b94d6","s":"b","g":"b10","n":"解偶联剂Uncoupler","e":"","d":"指能解除氧化磷酸化偶联作用的抑制剂，以2,4-二硝基苯酚（DNP）为例，其作用机理是破坏质子梯度。它被列为影响氧化磷酸化作用的抑制剂之一，与抑制氧的利用和ATP形成的寡霉素、与还原型Cyt氧化酶结合的CO、与氧化型Cyt氧化酶结合使酶失活的CN-等相区别。另外双香豆素、羰基氰对三氟甲氧基苯腙等具解偶联作用的物质，解偶联后产能转化为产热而不能合成ATP。","src":"第3讲 生物氧化 II"},{"id":"0a57d41e","s":"b","g":"b10","n":"解偶联蛋白Uncoupling proteins, UCPs","e":"","d":"是线粒体内膜上参与机体产热的重要转运蛋白质。UCPs被激活时形成质子通道，可引起线粒体内膜上的质子转运速度加快，使ATP合成依赖的线粒体内膜上的电化学梯度改变，氧化磷酸化被解偶联，不能合成ATP，产能转化为产热。UCPs被认为是参与能量代谢的重要靶蛋白；机体产热与能量平衡、代谢、体重调节密不可分，推测其可能与肥胖、胰岛素抵抗及糖尿病的发生发展相关，目前是肥胖药物研究的热门靶蛋白。","src":"第3讲 生物氧化 II"},{"id":"ff4a4de9","s":"b","g":"b10","n":"穿梭系统Shuttle System","e":"","d":"有些NADH是在胞液中产生的，而呼吸链位于线粒体的内膜上，线粒体内膜对NADH不能透过，必须通过一定的转运机制才能保证底物分子脱下的H可经呼吸链递氢和递电子被彻底氧化、释放能量，这种转运机制即为穿梭系统。经过穿梭系统把胞液中的NADH转变为线粒体内的NADH等，再经呼吸链被氧化。其包括磷酸甘油穿梭和苹果酸-草酰乙酸穿梭，后者存在于肝、心肌；两种穿梭最终都把胞液NADH的还原当量交给线粒体内的呼吸链。","src":"第3讲 生物氧化 II"},{"id":"e59bc830","s":"b","g":"b10","n":"腺苷酸转位酶Adenine nucleotide translocase","e":"","d":"线粒体内膜上的酶，可以把ADP和Pi转运到线粒体内，也能把合成的ATP从线粒体运到胞液。线粒体利用质子推动力合成ATP，但ADP和Pi必须转运到线粒体内，同时合成好的ATP也必须能运出线粒体在细胞质中水解供能，腺苷酸转位酶即承担这一任务，以反向转运体和同向转运体的图示说明其转运方向，从而保证氧化磷酸化持续进行，使胞质中ATP的水解供能与线粒体内ATP的合成相衔接。","src":"第3讲 生物氧化 II"},{"id":"07e01386","s":"b","g":"b10","n":"末端氧化酶Terminal oxidase","e":"","d":"指处于呼吸链末端、能将底物脱下的电子给O2并形成H2O2或H2O的酶类。除线粒体内膜上的细胞色素氧化酶和抗氰氧化酶（交替氧化酶）之外，还有存在于细胞质中的酚氧化酶、抗坏血酸氧化酶和乙醇酸氧化酶等。抗氰（交替）氧化酶系统、多酚氧化酶系统、抗坏血酸氧化酶系统、细胞色素P450系统等归为其他氧化酶体系，它们构成呼吸链的几条支路，使底物氧化不必经过完整的线粒体呼吸链。","src":"第3讲 生物氧化 II"},{"id":"63ebfb74","s":"b","g":"b10","n":"多酚氧化酶Polyphenol oxidase, PPO","e":"","d":"是植物体中（真菌、昆虫）广泛分布的、由核基因编码的质体铜金属酶，催化邻-苯二酚氧化成邻-苯二醌，也能作用于单酚单加氧酶的底物。PPO在植物抗病中起重要作用，有4个方面的间接证据：氧化生成的o-醌次级产物形成黑色素集结，形成可以阻碍感染的痂；o-醌与植物蛋白键合可降低亲核氨基酸的营养价值；o-醌类物质具有抑制细菌繁殖的作用；PPO的活性在不相容反应中增加。","src":"第3讲 生物氧化 II"},{"id":"e692374b","s":"b","g":"b10","n":"抗坏血酸氧化酶Ascorbic acid oxidase","e":"","d":"在酶催化下，分子态的氧可将抗坏血酸氧化成去氢抗坏血酸；该酶存在于细胞溶胶和细胞壁中，酶中含铜。它与其他氧化还原反应相偶联起末端氧化酶的作用，能催化抗坏血酸的氧化，具有抗衰老等作用，在植物体内的物质代谢中重要：丙酮酸、异柠檬酸、α-酮戊二酸、苹果酸、葡萄糖-6-磷酸等都可在脱氢酶作用下脱氢，把氢转移给辅酶，再经谷胱甘肽传给抗坏血酸，由其氧化脱氢，氢与氧结合生成水。","src":"第3讲 生物氧化 II"},{"id":"7959d7f1","s":"b","g":"b10","n":"过氧化物酶体氧化体系","e":"","d":"过氧化物酶体中含有较多的需氧脱氢酶，可催化L-氨基酸、D-氨基酸、黄嘌呤等的脱氢、加氧并生成H2O2，如RCH(NH2)COOH+O2+H2O→RCOCOOH+NH3+H2O2。该体系中的能量无利用，但生成的H2O2功能重要：在甲状腺中参与活性碘的生成，在中性粒细胞中可杀灭被吞噬的细菌，还参与一些生化反应。H2O2随后由过氧化氢酶和过氧化物酶处理、利用。","src":"第3讲 生物氧化 II"},{"id":"d5e5be3d","s":"b","g":"b11","n":"葡萄糖转运体（SGLT 与","e":"GLUT） Sodium-dependent glucose transporter / Facilitated glucose transporter","d":"介导葡萄糖跨膜转运的两大家族转运体蛋白。SGLT 即钠依赖性葡萄糖转运体，属主动转运，位于肠粘膜上皮细胞纹状缘，选择性将葡萄糖、半乳糖从肠腔粘膜表面转入细胞内再扩散入血；GLUT 为易化扩散的葡萄糖转运体。SGLT 家族已发现 6 种亚型，GLUT 家族已发现 12 种亚型，每种都有特异的组织分布和生化特性。葡萄糖是极性分子，只能以主动转运和易化扩散方式过膜；GLUT 除葡萄糖外还可转运去氢抗坏血酸、D-甘露醇、D-半乳糖和 D-果糖。","src":"第4讲 糖代谢 I"},{"id":"bb8c3c10","s":"b","g":"b11","n":"血糖","e":"Blood glucose","d":"指血液中的葡萄糖，是糖在体内的运输形式。来源有三：食物糖的消化吸收（主要来源）、其他糖在肝脏转变为葡萄糖（重要来源）、甘油与乳酸及氨基酸等非糖物质经糖异生转变而来。去路有四：各组织细胞内氧化分解、转变为肝糖原和肌糖原储备、转变为非糖物质或其他糖、过高时（160-180 mg/dL，8.89-10 mM）随尿排出。健康人血糖相当稳定，空腹时为 80-120 mg/dL【4.44-6.67 mM】，来路与去路维持动态平衡。","src":"第4讲 糖代谢 I"},{"id":"8c2d1bb7","s":"b","g":"b11","n":"肾糖阈","e":"Renal threshold for glucose","d":"肾脏所能保持的最高血糖浓度，为 160-180 mg/dL，是肾脏调节血糖的限度指标。正常情况下肾小管能重吸收肾小球滤液中的葡萄糖并回收到血液中，故尿中不出现葡萄糖；当血糖超过这一浓度，肾小管重吸收能力被超过，葡萄糖随尿排出，出现糖尿。据此说明肾脏是调节血糖的器官之一，与肝脏调节、神经系统调节（血糖低于 70-80 mg/dL 时经\"糖中枢\"反射性兴奋促使肝糖原分解）及激素调节共同维持血糖恒定。","src":"第4讲 糖代谢 I"},{"id":"c4e7f9f8","s":"b","g":"b11","n":"糖原合成酶","e":"Glycogen synthase","d":"糖原合成相关的三个酶之一，存在于肌肉和肝脏，催化糖原直链部分的合成，把活化的葡萄糖（UDPG，称活性葡萄糖）加到糖原分子的非还原末端上使糖链延长：UDPG+nG→(n+1)G+UDP。该酶只能促成 α-1,4-糖苷键，故产物为 α-1,4-糖苷键相连的直链多糖。酶有非（去）磷酸化 a 与磷酸化 b 两种形式，a 为活性形式，蛋白激酶催化其 Ser 残基磷酸化转为非活性或低活性 b，磷酸酯酶去磷酸化使 b 转回 a。","src":"第4讲 糖代谢 I"},{"id":"6dda5997","s":"b","g":"b11","n":"糖原分枝酶","e":"Branching enzyme（Glucosyl 4→6 transferase）","d":"催化糖原支链形成的酶，又称葡萄糖基 4→6 转移酶。糖原 α-1,6 糖苷键的分支点不是以逐个添加葡萄糖残基的方式合成，而是由分枝酶把一段糖原分子末端切下来转移到链上另一点形成分支。分枝酶将 5-8 个葡萄糖残基的寡糖直链转到另一糖原支链上，以 α-1.6-糖苷键相连生成分枝糖链，其非还原末端可继续由糖原合成酶延长。意义：多分支增加糖原水溶性利于贮存，分解时可从多个非还原末端同时开始，提高分解速度。","src":"第4讲 糖代谢 I"},{"id":"db47955c","s":"b","g":"b11","n":"糖原磷酸化酶","e":"Glycogen phosphorylase","d":"存在于肌肉和肝脏、主要功能为催化糖原降解生成 G-1-P 的酶。它从糖原非还原端断裂 α-1,4 糖苷键，分解进行到 α-1,6 分枝点两侧各余约 4 个葡萄糖残基，产物为极限糊精和 G-1-P。离体酶亦可催化合成反应：G-1-P+nG→(n+1)G+Pi。调节包括共价和变构调节，活性形式 a 为磷酸化的（两个亚基的 Ser14），去磷酸化变为非活性形式 b，AMP 是变构促进剂；它与糖原合成酶经磷酸化-去磷酸化相互调节。","src":"第4讲 糖代谢 I"},{"id":"2a9f22a1","s":"b","g":"b11","n":"UDPG（尿苷二磷酸葡萄糖） Uridine diphosphate glucose","e":"","d":"糖原合成中活泼葡萄糖基的供体，故又称活性葡萄糖。由 1-磷酸葡萄糖与 UTP 经 UDPG 焦磷酸化酶催化生成：G-1-P+UTP→UDPG+PPi，此反应被称为糖原合成的关键反应。糖原合成酶使 UDPG 上葡萄糖基 C1 与糖原分子非还原末端 C4 形成 α-1,4-糖苷键，使糖原增加一个葡萄糖单位。由于其生成过程消耗 UTP，故糖原合成是耗能过程；UDPG 也是半乳糖代谢中 UDPGal 再生的底物。","src":"第4讲 糖代谢 I"},{"id":"d116639d","s":"b","g":"b11","n":"糖原引物与糖原素","e":"Glycogenin","d":"糖原合成不能从头开始，糖原合成酶催化反应需要至少含 4 个葡萄糖残基的 α-1,4-多聚葡萄糖作为引物，在其非还原性末端与 UDPG 反应。体内存在一种特殊蛋白质即糖原素（glycogenin），可作为葡萄糖基的受体，从头开始合成第一个糖原分子的葡萄糖，催化此反应的酶是糖原起始合成酶（glycogen initiator synthase），先生成一寡糖链作为引物，再由糖原合成酶继续催化合成糖原。","src":"第4讲 糖代谢 I"},{"id":"17acd3db","s":"b","g":"b11","n":"糖原分解","e":"Glycogenolysis","d":"糖原降解为葡萄糖的过程。糖原磷酸化酶从非还原端断裂 α-1,4 糖苷键生成 G-1-P，至 α-1,6 分枝点两侧各余约 4 个葡萄糖残基，产物为极限糊精和 G-1-P；脱枝酶转移并水解 α-1,6 键生成葡萄糖，余下糖残基再由磷酸化酶继续水解。G-1-P 经磷酸葡萄糖变位酶转变为 G-6-P，在肝脏由葡萄糖-6-磷酸酶水解生成葡萄糖释放入血，肌肉缺乏该酶，故肌糖原主要供本身分解代谢。","src":"第4讲 糖代谢 I"},{"id":"3e12c348","s":"b","g":"b11","n":"脱枝酶","e":"Debranching enzyme","d":"又称去分枝酶，与寡葡聚糖[1,4→1,4]转移酶是同一个酶上的不同部分（两个活性位点）。作用时，极限糊精 α-1,6 分枝点两侧的葡萄糖残基先经转移酶转移到另一支链上，以 α-1,4 形式连接到分枝末端葡萄糖残基，再经脱枝酶水解 α-1,6 键生成葡萄糖；剩下的糖残基由磷酸化酶催化进一步水解。意义：与磷酸化酶配合使带分支的糖原彻底分解为 G-1-P 及葡萄糖，是糖原动员产生葡萄糖的必要环节。","src":"第4讲 糖代谢 I"},{"id":"93d6f315","s":"b","g":"b11","n":"糖酵解","e":"Glycolysis（EMP pathway）","d":"又称 Embden-Meyerhof-Parnas 途径、己糖二磷酸途径。指在无氧条件下，一分子葡萄糖通过一系列酶促反应生成 2 分子丙酮酸，并生成 ATP 和 NADH 的过程，是一切生物细胞中葡萄糖分解产生能量的共同代谢途径，也是第一个发现和研究得最清楚的生化代谢途径。可分三阶段：葡萄糖磷酸化生成己糖磷酸酯，消耗 2ATP，产物为 F-1,6-diP；醛缩酶在 C3-C4 间裂解为两分子三碳糖；三碳糖生成丙酮酸，反应 7 和 10 各生成 2ATP。","src":"第4讲 糖代谢 I"},{"id":"a72d3410","s":"b","g":"b11","n":"激酶","e":"Kinase","d":"一类从高能供体分子 ATP 转移 γ-磷酸基团到特定靶分子的酶，这一过程称为磷酸化。蛋白激酶作用于特定的蛋白质并改变其活性，在细胞信号传导及其复杂的生命活动中起广泛作用；其他不同的激酶作用于小分子物质（脂质、糖、氨基酸、核苷等），或为了传递信号，或为代谢中各种生化反应作准备。糖酵解中的己糖激酶、磷酸果糖激酶、磷酸甘油酸激酶、丙酮酸激酶均属此类，它们催化的磷酸化既消耗 ATP 也为底物水平磷酸化作准备。","src":"第4讲 糖代谢 I"},{"id":"91fde751","s":"b","g":"b11","n":"己糖激酶","e":"Hexokinase","d":"糖酵解第一个酶，需要 Mg2+ 或其他二价阳离子及 ATP，催化葡萄糖磷酸化生成 G-6-P，反应不可逆。它是酵解过程的第一个别构（调节）酶，肌肉中受产物 G-6-P 强烈别构抑制；肝脏中主要以葡萄糖激酶（glucokinase）形式存在，对葡萄糖有特异活性，不受 G-6-P 抑制。意义：使葡萄糖带上磷酸基团而得以在胞内继续代谢，是决定葡萄糖进入酵解速率的第一个环节，也是糖酵解调控的三个变构调节酶之一。","src":"第4讲 糖代谢 I"},{"id":"dd5a5794","s":"b","g":"b11","n":"磷酸果糖激酶-1 Phosphofructokinase-1（PFK-1）","e":"","d":"糖酵解途径的关键反应（committed step，key reaction，rate-limiting reaction）酶，需 Mg2+ 及 ATP，酵解进行的速度取决于该酶活性；两次磷酸化使葡萄糖转化为反应活性很高的 F-1,6-BP。该酶为 4 亚基寡聚酶，有 3 种同工酶：PFK-M（A，肌肉）、PFK-L（B，肝脏）和 PFK-P（C，血小板）。别构调节：ATP 对其有抑制效应，柠檬酸及脂肪酸加强抑制，AMP、ADP 及 Pi 可消除抑制。","src":"第4讲 糖代谢 I"},{"id":"e08c2bb6","s":"b","g":"b11","n":"3-磷酸甘油醛脱氢酶","e":"Glyceraldehyde-3-phosphate dehydrogenase（GAPDH）","d":"糖酵解中催化 3-磷酸甘油醛氧化磷酸化的脱氢酶，活性中心在酶的 Cys-SH 上。氧化型 NAD+ 与酶紧密结合，受氢还原后与酶脱离，磷酸攻击硫酯键生成 1,3-二磷酸甘油酸。只有 NAD+ 不断取代 NADH 才能保持酶的催化活力，否则酵解就要停止。碘乙（酰胺）酸与活性位点 -SH 共价结合使酶失活；砷酸（盐）与磷酸结构相似，可抑制酶的活性。意义：生成含高能磷酸键的 1,3-二磷酸甘油酸，为下一步底物水平磷酸化提供能量。","src":"第4讲 糖代谢 I"},{"id":"99f7c9b2","s":"b","g":"b11","n":"R-L 循环","e":"Rapoport-Luebering shunt","d":"红细胞糖酵解中 2,3-DPG 产生与转变的支路，1950 年发现。在红细胞代谢中产生两种效应：一是消耗能量，1,3-DPG 经 R-L 循环后其 1 位上的高能磷酸键未能转移给 ADP 生成 ATP，反而经两步反应消耗了 14 卡/摩尔的能量，故每分子葡萄糖经此循环不但没有 ATP 净生成，反而消耗能量；二是 2,3-DPG 调节 Hb 与 O2 的亲和力，通过调节自身含量确保不同状态下组织的供氧。意义：既调节酵解途径和能量代谢，又保证组织供氧。","src":"第4讲 糖代谢 I"},{"id":"6c63774a","s":"b","g":"b11","n":"2,3-二磷酸甘油酸","e":"2,3-Diphosphoglycerate（2,3-DPG）","d":"糖酵解中间产物。多数细胞中含量很少（痕量水平），但在红细胞中却是主要成分（约 5 mM），是哺乳类动物红细胞糖酵解途径的重要中间产物。由双磷酸甘油酸变位酶催化 1,3-BPG 的磷酸基从 C1 转移至 C2 而生成。它不仅是调节血红蛋白与氧结合和解离的重要因子，而且是红细胞代谢中重要的能量贮备物，其含量变化受许多代谢和血液因子调控，红细胞中它的生成与分解分别由 DPG 变位酶和 2,3-DPG 磷酸酶催化。","src":"第4讲 糖代谢 I"},{"id":"818d514e","s":"b","g":"b11","n":"烯醇化酶","e":"Enolase","d":"糖酵解中催化 2-磷酸甘油酸脱水生成磷酸烯醇式丙酮酸（PEP）的酶，EC 4.2.1.11，产生酵解途径的第二个磷酸基团转移能。有 Mg2+ 或 Mn2+ 存在时酶才有活性；F- 能与 Mg2+ 形成络合物并结合在酶分子上，从而抑制酶活性。意义：脱水反应使分子内部能量重新分布，生成含高能磷酸键的 PEP，为丙酮酸激酶催化 ADP 生成 ATP（底物水平磷酸化）提供磷酸基团供体，是酵解能量回收阶段的关键步骤。","src":"第4讲 糖代谢 I"},{"id":"80ff4a29","s":"b","g":"b11","n":"互变异构作用","e":"Tautomerization","d":"指一类特殊的同分异构现象，其特点是含有杂原子（如氮、氧或硫原子）的两个同分异构体，结构差异仅在于质子和相应双键的迁移，且这两个异构体共存于一个平衡体系中，以相当高的速率互相变换着。酮-烯醇互变异构是较普遍的现象，它可以被酸或碱所催化；此外还有氨式与亚氨式互变异构。糖酵解部分以此说明烯醇式丙酮酸一类烯醇式中间物的存在形式，是理解糖酵解后段反应中分子内能量重新分布的基础。","src":"第4讲 糖代谢 I"},{"id":"b73b206a","s":"b","g":"b11","n":"丙酮酸激酶","e":"Pyruvate kinase","d":"糖酵解第 10 步的酶，属别构调节酶，需要 Mg2+、K+，催化磷酸烯醇式丙酮酸+ADP→丙酮酸+ATP，反应有 ATP 生成，是酵解途径的重要调节酶。长链脂肪酸、乙酰 CoA、ATP、Ala 等均抑制酶活；F-1,6-BP 可活化此酶。它与己糖激酶、磷酸果糖激酶同为糖酵解的变构调节酶。意义：催化酵解第二个底物水平磷酸化位点，与磷酸甘油酸激酶一起使每分子葡萄糖净生成 2ATP。","src":"第4讲 糖代谢 I"},{"id":"5e3d0ba1","s":"b","g":"b11","n":"底物水平磷酸化","e":"Substrate-level phosphorylation","d":"指底物氧化、分子内基团重排等所释放的能量偶联 ATP 生成的方式，涉及可溶性的酶和代谢中间物，不涉及膜结合的酶、跨膜质子梯度和电子传递。以 EMP 的能量账目说明其地位：1,3-二磷酸甘油酸→2 分子 3-磷酸甘油酸生成 2ATP，2 分子磷酸烯醇式丙酮酸→2 分子丙酮酸生成 2ATP，而葡萄糖和 6-磷酸果糖的磷酸化各耗 1ATP。意义：无氧条件下机体取得能量的主要方式，两种发酵均净生成 2ATP 即由此而来。","src":"第5讲 糖代谢 II"},{"id":"bf43c099","s":"b","g":"b11","n":"乳酸发酵","e":"Lactic acid fermentation","d":"无氧条件下丙酮酸接受 NADH 的氢被还原为乳酸的过程，在肌肉等组织中发生，总反应为葡萄糖→2 乳酸。\"NADH 和 H+ 的命运\"中给出：无氧条件下通过乳酸发酵受氢，解决 NADH 的重氧化问题。意义：使胞质中有限的 NAD+ 得以再生，维持糖酵解持续进行；该过程净生成 2ATP，能量来自底物水平磷酸化，是机体相对缺氧时（环境、疾病、剧烈运动、局部缺血等）补充能量的一种有效方式。","src":"第5讲 糖代谢 II"},{"id":"eb673f5b","s":"b","g":"b11","n":"乙醇发酵","e":"Alcoholic fermentation","d":"无氧条件下丙酮酸先脱羧生成乙醛，乙醛再受氢生成乙醇的过程。无氧条件下丙酮酸转变为乙醛，进而生成乙醇，酵母等生物进行此反应，总反应为葡萄糖→2 乙醇+2CO2。参与反应的酶为丙酮酸脱羧酶和乙醇脱氢酶。意义：与乳酸发酵一样解决胞质中 NADH 的重氧化、再生 NAD+，使糖酵解在无氧条件下持续进行，同时净生成 2ATP；乳酸和乙醇都是最常见的微生物发酵产物之一。","src":"第5讲 糖代谢 II"},{"id":"1b4fc8f3","s":"b","g":"b11","n":"甘油发酵","e":"Glycerol fermentation","d":"糖酵解的利用途径之一，由磷酸二羟丙酮受氢生成 3-磷酸甘油，再脱磷酸生成甘油，反应为 DHAP+NADH+H+→3-磷酸甘油→甘油。利用酵母制造甘油可解决乙醛受氢的问题，两种方法：一是在培养基中添加 NaHSO3，与乙醛加成生成 CH3CH(OH)OSO2Na，使乙醛不能受氢；二是将发酵液调至碱性，使乙醛在碱性条件下发生歧化反应，生成乙酸钠和乙醇。意义：微生物发酵生产甘油。","src":"第5讲 糖代谢 II"},{"id":"15394ee9","s":"b","g":"b11","n":"果糖-1-磷酸醛缩酶（醛缩酶","e":"B） Fructose-1-phosphate aldolase","d":"肝脏中果糖代谢的关键酶，催化果糖-1-磷酸裂解为磷酸二羟丙酮和甘油醛；甘油醛再由甘油醛激酶催化、消耗 1ATP 生成 3-磷酸甘油醛进入 EMP。肝脏果糖代谢路线为：果糖激酶催化果糖生成 F-1-P，再由该酶裂解。肝中几乎不发生己糖激酶催化果糖磷酸化的反应，故肝脏果糖代谢主要依赖此路线。该酶缺乏时即导致遗传性果糖不耐受的临床综合征，患儿摄入果糖后才出现症状。","src":"第5讲 糖代谢 II"},{"id":"11a89291","s":"b","g":"b11","n":"遗传性果糖不耐受","e":"Hereditary fructose intolerance","d":"果糖-1-磷酸醛缩酶（醛缩酶 B）缺乏所致的临床综合征，遗传方式为常染色体隐性，发病率估计为活产婴儿 1/20,000。患儿摄入果糖后才出现症状，果糖-1-磷酸积聚引起低血糖、恶心、呕吐、腹部疼痛、出汗、震颤、头晕、嗜睡、惊厥和昏迷；长期摄入果糖可引起肝硬化、智力退化、近端肾小管酸中毒并伴尿中磷酸和葡萄糖丢失。诊断由与近期果糖摄入相关的症状提示并经 DNA 分析证实，治疗为低血糖时给葡萄糖、长期排除果糖、蔗糖和山梨醇。","src":"第5讲 糖代谢 II"},{"id":"90472a52","s":"b","g":"b11","n":"半乳糖激酶缺乏","e":"Galactokinase deficiency","d":"半乳糖代谢障碍的一种。正常时半乳糖由半乳糖激酶催化生成 1-磷酸半乳糖，再由鸟苷酰转移酶催化与 UDPG 反应生成 G-1-P 和 UDPGal，G-1-P 经变位酶变成 G-6-P 进入 EMP。该酶缺乏时患者因产生半乳糖醇而渗透性地损害晶状体纤维，导致白内障，特发性颅内高压（假性脑瘤）罕见；发病率为活产婴儿的 1/40,000。该病属糖代谢酶先天性缺陷所致的糖代谢紊乱，与转移酶缺乏所致典型半乳糖血症的机制不同。","src":"第5讲 糖代谢 II"},{"id":"87ef1f64","s":"b","g":"b11","n":"尿苷二磷酸半乳糖","e":"4-表异构酶缺乏 UDP-galactose 4-epimerase deficiency","d":"半乳糖代谢障碍的一种，有两种表现型：一种良性型和一种严重型。在日本，良性型的发病率是活产婴儿的 1/23,000；良性形式局限于红细胞和白细胞，不引起临床异常。严重型有时伴有听力丧失，其产生的综合征与典型半乳糖血症仍难以鉴别。其与半乳糖激酶缺乏、半乳糖 1-磷酸尿苷转移酶缺乏并列为半乳糖代谢障碍的三种酶缺陷。该酶的正常作用是把 UDPGal 转变为 UDPG 完成 UDPG 再生，从而使半乳糖经 UDPGal 途径进入糖代谢。","src":"第5讲 糖代谢 II"},{"id":"18e772a2","s":"b","g":"b11","n":"Warburg 效应","e":"Warburg effect","d":"指大多数肿瘤组织（实体瘤、细胞）对葡萄糖的吸收及糖酵解活性高于正常细胞 10 倍以上的现象，1930 年由 Warburg 提出。据此说明糖酵解的意义之一：某些组织在有氧时也通过糖酵解供能，包括成熟红细胞、白血病、视网膜、睾丸、肾髓质、神经和骨髓、皮肤及肿瘤细胞。肿瘤细胞所需的能量主要来自极高活性的糖酵解，肿瘤细胞的恶性程度越高，这种趋势越明显，故成为糖酵解抑制剂类抗肿瘤药物的靶点依据。","src":"第5讲 糖代谢 II"},{"id":"9cf73f01","s":"b","g":"b11","n":"低氧诱导因子","e":"Hypoxia inducible factor（HIF）","d":"对细胞环境中可利用氧减少（缺氧）作出应答的转录因子。肿瘤组织因快速生长、血管结构异常致供血减少，缺氧是普遍状态；缺氧微环境刺激 HIF 基因转录，HIF1 激活使葡萄糖转运体、糖酵解酶的表达增加并加速糖酵解，结果乳酸产生增多。此外 HIF1 也能激活丙酮酸脱氢酶激酶（PDKs），导致线粒体中的丙酮酸脱氢酶复合体失活，减少葡萄糖来源的丙酮酸进入三羧酸循环，使氧化磷酸化和氧消耗减少，促进肿瘤的有氧糖酵解。","src":"第5讲 糖代谢 II"},{"id":"3ecb461d","s":"b","g":"b11","n":"丙酮酸脱氢酶激酶","e":"Pyruvate dehydrogenase kinase（PDK）","d":"被 HIF1 激活的激酶，可使线粒体中的丙酮酸脱氢酶复合体失活，从而减少葡萄糖来源的丙酮酸进入三羧酸循环，使氧化磷酸化和氧消耗减少，使肿瘤细胞的糖酵解增加，并在低氧条件下节约氧，因此进一步促进肿瘤有氧糖酵解的发生。其列为缺氧微环境促进肿瘤糖酵解的调节环节，与葡萄糖转运体和糖酵解酶表达增加并列，共同构成 HIF1 激活后的代谢效应，也是肿瘤有氧糖酵解发生的机制之一。","src":"第5讲 糖代谢 II"},{"id":"43b3caff","s":"b","g":"b11","n":"糖的有氧氧化","e":"Aerobic oxidation of glucose","d":"葡萄糖（或糖原）在有氧条件下通过与糖酵解相同的途径分解为丙酮酸，进而彻底氧化成二氧化碳和水，并产生大量 ATP 的过程。反应部位为胞液和线粒体基质（真核生物）。生理意义：一般状况下异养生物（人）体大多数组织获取能量的主要方式，1 分子葡萄糖可生成 38 ATP；TCA 是三大类能量物质共同的分解代谢途径，不仅是糖、脂肪和氨基酸氧化供能的共同通路，也是它们互变的枢纽。38 个 ATP 贮存 1159.0 kJ/mol，能量利用率 40.4%。","src":"第6讲 糖代谢 III"},{"id":"42c8eb4f","s":"b","g":"b11","n":"丙酮酸脱氢酶复合体","e":"Pyruvate dehydrogenase complex（PDHC）","d":"催化丙酮酸氧化脱羧生成乙酰 CoA 的多酶体系，位于真核生物线粒体，是连接糖酵解与三羧酸循环的中心环节。由三种酶蛋白和六种辅助因子组成：丙酮酸脱氢酶（E1）、二氢硫辛酸（酰胺）转乙酰酶（E2）和二氢硫辛酸（酰胺）脱氢酶（E3）；辅助因子包括 TPP、硫辛酸、FAD、NAD+、HS-CoA 和 Mg2+，共催化 5 步反应。调节包括产物抑制（乙酰 CoA、NADH 分别抑制 E2 和 E3）、核苷酸反馈（GTP/ATP 抑制 E1，AMP 活化）及可逆磷酸化。","src":"第6讲 糖代谢 III"},{"id":"a51cb998","s":"b","g":"b11","n":"丙酮酸脱氢酶缺乏症","e":"Pyruvate dehydrogenase deficiency","d":"丙酮酸脱氢酶缺乏所致的疾病，使丙酮酸盐升高，从而提高乳酸水平。临床表现严重性不同，包括乳酸血症和中枢神经系统畸形，以及其他生后的变化，如大脑皮质、脑干以及基底神经节的囊性损害、共济失调和精神运动性迟缓。诊断可由皮肤成纤维细胞中酶分析和（或）DNA 测定明确。该病没有确切有效的治疗方法，但低碳水化合物或生酮饮食，以及饮食中补充硫胺素可能有益。属糖代谢酶先天性缺陷所致的疾病。","src":"第6讲 糖代谢 III"},{"id":"bc06a813","s":"b","g":"b11","n":"三羧酸循环","e":"Tricarboxylic acid cycle（TCA 循环）","d":"有氧条件下大多数生物共有的物质分解代谢途径，乙酰 CoA 经一系列（8 或 9 步反应）的氧化、脱羧，最终生成 CO2、还原电子和部分能量的过程。乙酰 CoA 与草酰乙酸缩合生成柠檬酸，再经一系列氧化、脱羧，循环后再生草酰乙酸，其中生成 2CO2、3[NADH+H+]、1GTP(ATP)、1FADH2。又称 Krebs 循环或柠檬酸循环；不仅是糖分解代谢的主要途径，也是脂肪、蛋白质分解代谢的最终途径，是三大类物质氧化供能的共同通路和互变枢纽。","src":"第6讲 糖代谢 III"},{"id":"5e3fc006","s":"b","g":"b11","n":"柠檬酸合酶","e":"Citrate synthase","d":"催化 TCA 第一步反应的酶，EC 2.3.3.1，位于线粒体基质，属转移酶。它催化乙酰 CoA 与草酰乙酸缩合，先生成柠檬酰 CoA，再水解为柠檬酸，为放能反应、不可逆，对 TCA 是一个限速步骤（rate-limiting step）。该酶是 TCA 的一个调节酶，活性受 ATP、NADH、琥珀酰 CoA 及长链脂酰 CoA 的抑制。酶由 437 个氨基酸残基组成，组织为两个主要亚基，每个亚基含 20 个 α-螺旋。","src":"第6讲 糖代谢 III"},{"id":"e80fdc41","s":"b","g":"b11","n":"顺乌头酸酶","e":"Aconitase","d":"又称乌头酸水合酶，EC 4.2.1.3，是 TCA 中催化柠檬酸经顺乌头酸异构化为异柠檬酸的酶，属含铁硫簇的酶。以氟柠檬酸致死机制说明其专一性：氟乙酰 CoA（氟乙酸、氟乙酸钠、氟乙酰胺）在酶的作用下与草酰乙酸生成氟柠檬酸，而顺乌头酸酶只识别柠檬酸，对氟柠檬酸没有作用，致使 TCA 中断，引起死亡毒性，是\"致死性合成\"的典型实例。据此说明含铁硫簇的酶对底物的严格识别，以及氟柠檬酸不能被继续代谢的原因。","src":"第6讲 糖代谢 III"},{"id":"e618b53f","s":"b","g":"b11","n":"致死性合成","e":"Lethal synthesis","d":"指与细胞正常代谢物结构相似的外来化合物参与代谢过程，生成高毒性的、可导致细胞死亡的毒作用的合成代谢，是一种特殊类型的化学损害。实例为：氟乙酰 CoA（氟乙酸、氟乙酸钠、氟乙酰胺）在酶的作用下与草酰乙酸生成氟柠檬酸，顺乌头酸酶只识别柠檬酸，对氟柠檬酸没有作用，致使 TCA 中断而死亡。在代谢研究的应用上，被广泛用于杀虫剂、灭鼠药及化疗药物的生产。含此类成分的毒鼠子属植物叶中微量即可侵害动物的神经系统和心脏，以至死亡。","src":"第6讲 糖代谢 III"},{"id":"ea8d3586","s":"b","g":"b11","n":"异柠檬酸脱氢酶","e":"Isocitrate dehydrogenase（IDH）","d":"催化 TCA 第一次氧化脱羧、产物为 α-酮戊二酸的酶。细胞内有两种异柠檬酸脱氢酶：线粒体中以 NAD+ 为氢受体者（EC1.1.1.41），为 Mg2+ 及 Mn2+ 所活化，是别构调节酶，正调控物是 ADP，缺乏 ADP 时没有活力，ATP 及 NADH 对酶有抑制作用；另一种以 NADP+ 为氢受体（EC1.1.1.42），在胞质及线粒体中都有存在。两者以不同辅酶参与 TCA 的氧化脱羧步骤。","src":"第6讲 糖代谢 III"},{"id":"bf90e012","s":"b","g":"b11","n":"α-酮戊二酸脱氢酶复合体 α-Ketoglutarate dehydrogenase complex","e":"","d":"催化 TCA 中 α-酮戊二酸氧化脱羧的酶复合体，其组成及作用与丙酮酸脱氢酶复合物相似，包括三个酶组分：α-酮戊二酸脱氢酶（E1'）、琥珀酰转移酶（E2'）和二氢硫辛酸脱氢酶（E3'），还有六种辅助因子 TPP、CoA、FAD、NAD+、硫辛酸（硫辛酰胺）及 Mg2+。它是调节酶，受产物 NADH 和琥珀酰 CoA 抑制，ATP、GTP 对酶有反馈抑制，不受可逆磷酸化的共价调节；AMP、ADP 与 Ca2+ 是酶的变构增活因子。","src":"第6讲 糖代谢 III"},{"id":"fcb945a8","s":"b","g":"b11","n":"琥珀酰","e":"CoA 合成酶 Succinyl-CoA synthetase（琥珀酸硫激酶）","d":"又称琥珀酸硫激酶，催化 TCA 中琥珀酰 CoA 转变为琥珀酸、同时产生 1 GTP(ATP) 的反应，是循环中唯一一次底物水平磷酸化。氧化释放的能量贮存于硫酯键中，该酶即利用琥珀酰 CoA 的硫酯键能量驱动 GDP 磷酸化。酶由 α-亚基和 β-亚基组成。意义：把 α-酮戊二酸氧化脱羧时保存于硫酯键的能量转换为 GTP(ATP)。以丁二酸单酰 CoA 为例说明氧化释放的能量贮存于硫酯键中，该键水解即驱动 GTP 生成。","src":"第6讲 糖代谢 III"},{"id":"f0a385d5","s":"b","g":"b11","n":"琥珀酸脱氢酶","e":"Succinate dehydrogenase","d":"催化琥珀酸脱氢生成延胡索酸的酶，氢受体是 FAD。它是真核生物 TCA 中唯一一个掺入线粒体内膜的酶（原核生物掺入质膜），直接与呼吸链相连。产物延胡索酸（反丁烯二酸），顺丁烯二酸（马来酸）不能参加代谢，对机体有毒；丙二酸是酶的竞争性抑制剂。意义：把 TCA 与呼吸链直接连接，使 FADH2 的电子不经中间载体直接进入呼吸链。 TCA 每轮四次脱氢中仅此一次以 FAD 为氢受体。","src":"第6讲 糖代谢 III"},{"id":"f8cf1b8d","s":"b","g":"b11","n":"两用代谢途径","e":"Amphibolic pathway","d":"既可用于代谢物分解又可用于合成的代谢途径，如三羧酸循环，亦称无定向代谢途径，即指把合成作用和分解作用合在一起的代谢途径。比指出：糖酵解系统主要是分解的（catabolism），氨基酸和卟啉系统则是合成（anabolism）；柠檬酸循环既有丙酮酸的分解作用，又为 α-酮戊二酸、草酰乙酸合成氨基酸或乙酰 CoA 合成脂肪酸提供原料，此类兼具两种作用的系统以希腊语 amphi 命名为 amphibolic 代谢系统。","src":"第6讲 糖代谢 III"},{"id":"9c888a2f","s":"b","g":"b11","n":"回补反应","e":"Anaplerotic reactions","d":"补充 TCA 循环中间产物的反应，五条途径：(1) 动物肝、肾线粒体中丙酮酸羧化酶催化丙酮酸+CO2+ATP+H2O→草酰乙酸；(2) 植物、细菌中 PEP 羧化酶催化 PEP+CO2→草酰乙酸；(3) 心脏、骨骼肌中 PEP 羧激酶催化 PEP+CO2+GDP↔草酰乙酸+GTP；(4) 苹果酸酶催化丙酮酸+CO2+NADPH→苹果酸；(5) Asp 和 Glu 转氨形成草酰乙酸和 α-酮戊二酸，Ile、Val、Thr 及 Met 形成琥珀酰 CoA。","src":"第6讲 糖代谢 III"},{"id":"1c0d885a","s":"b","g":"b11","n":"糖异生","e":"Gluconeogenesis","d":"人体肝脏、肾脏及肠上皮细胞中，甘油、乳酸和一些氨基酸等非糖物质转变为糖原或葡萄糖的过程。其中心点是能转变为丙酮酸的物质如何逆着酵解途径回到葡萄糖，即如何解决酵解途径中的三步不可逆反应（己糖激酶、磷酸果糖激酶、丙酮酸激酶催化的反应）；十步反应中有七步酶促反应是酵解过程的逆反应，另需丙酮酸羧化酶、PEP 羧激酶、果糖 1,6-二磷酸酶和葡萄糖 6-磷酸酶来逾越不可逆步骤。糖异生存在于动物、植物和微生物中。","src":"第7讲 糖代谢 IV"},{"id":"72a1a0ca","s":"b","g":"b11","n":"糖异生的前体","e":"Gluconeogenic precursors","d":"哺乳动物糖异生的原料物质，主要有乳酸、丙酮酸、甘油、大多数氨基酸及奇数碳脂肪酸。高等动物糖异生发生于肝脏（多数）和肾上腺皮质。此外，其在不同生物中的意义：植物种子萌发时，种子中贮存的甘油三酯和蛋白质通过糖异生转变为蔗糖运送到生长的植物，葡萄糖及其衍生物是植物细胞壁、核苷酸、辅酶及其他重要代谢物的合成前体；许多微生物可通过糖异生把乙酸、乳酸、丙酸等简单有机物转变为葡萄糖。","src":"第7讲 糖代谢 IV"},{"id":"bdba6775","s":"b","g":"b11","n":"无效循环","e":"Futile cycle（底物循环 substrate cycle）","d":"生物组织内由两个不同的酶催化两个相反的代谢途径，反应的一个方向需要高能化合物如 ATP 参与，而另一方向则自动进行，这样循环的结果只是 ATP 被水解了，而反应物并无变化，这种循环称为\"无效循环\"或\"底物循环\"。肝脏中有酵解和异生的完整酶系，可能存在 3 种无效循环。意义：产生热能、扩大代谢的调控，是糖酵解与糖异生相互调节的一种表现形式；糖异生调节部分专门讨论了这一循环。","src":"第7讲 糖代谢 IV"},{"id":"256facbe","s":"b","g":"b11","n":"乙醛酸循环","e":"Glyoxylate cycle","d":"微生物和植物中存在的代谢途径，因其具有两种酶即异柠檬酸裂解酶（isocitrate lyase）和苹果酸合成酶（malate synthetase），可使 TCA 循环中的异柠檬酸不经脱羧而被裂解为琥珀酸和乙醛酸，乙醛酸与另一分子乙酰 CoA 在苹果酸合成酶作用下缩合形成苹果酸。意义：连接糖与脂的相互转变；协同 TCA，造成 C4 的赢余，实现回补或生糖。正因存在此途径，微生物和植物可以在产乙酸或产生乙酰 CoA 的化合物中生长。","src":"第7讲 糖代谢 IV"},{"id":"d44dffb1","s":"b","g":"b11","n":"磷酸戊糖途径","e":"Pentose phosphate pathway（PPP）","d":"又称己糖单磷酸途径、戊糖（磷酸）支路、磷酸己糖支路/旁路、磷酸葡萄糖酸途径；由于此途径由 6-磷酸葡萄糖开始，故亦称己糖磷酸旁路（HMP）。发现依据是组织中添加酵解抑制剂后葡萄糖仍可被消耗，说明葡萄糖还有其他代谢支路。整个途径分两个阶段：氧化阶段，葡萄糖经脱氢、脱羧变为磷酸戊糖；非氧化阶段，戊糖经几种不同碳数的糖的转化，最终重新合成己糖，两个关键酶为转酮酶（TK）和转醛酶（TA）。","src":"第7讲 糖代谢 IV"},{"id":"71286f1d","s":"b","g":"b11","n":"6-磷酸葡萄糖脱氢酶","e":"Glucose-6-phosphate dehydrogenase","d":"磷酸戊糖途径氧化阶段的调节酶（regulatory enzyme），对 NADP+ 高度专一，对 NAD+ 的 Km 比对 NADP+ 大约 1000 倍。其活性主要由 NADPH/NADP+ 的比例来调节：NADP+ 为正调节（+），NADPH+H+ 为负调节（-）。它催化 6-磷酸葡萄糖脱氢生成 6-磷酸葡萄糖内酯，是氧化阶段的起始步骤。意义：控制 NADPH 的生成速率，从而与生物合成的还原力供应及红细胞还原性维持相适应。","src":"第7讲 糖代谢 IV"},{"id":"a751c0d2","s":"b","g":"b11","n":"糖醛酸途径","e":"Glucuronic acid pathway","d":"由 G-6-P 或 G-1-P 开始，经 UDP-葡萄糖醛酸（UDP-GlcUA）的代谢途径。主要步骤：G-6-P 转化为 UDPG，再由 NAD 连接的脱氢酶催化氧化为 UDP-GlcUA；UDP-GlcUA 与药物或异物作用，生成水溶性加成物由尿中排出；UDP-GlcUA 生成 UDP-艾杜糖醛酸；抗坏血酸的合成；GlcUA 经脱氢、脱羧等生成（磷酸）木酮糖与 PPP 相联。灵长类哺乳动物和部分鸟类缺乏此途径合成抗坏血酸的能力。","src":"第7讲 糖代谢 IV"},{"id":"fea81bcc","s":"b","g":"b11","n":"低血糖","e":"Hypoglycemia","d":"空腹血糖浓度＜3.89 mmol/L【70 mg/dL】。症状为头晕、心悸、出冷汗等，严重时引起脑昏迷。原因分两类：生理性低血糖见于妊娠期、哺乳期、饥饿及长期剧烈运动后；病理性低血糖见于胰岛细胞增生、严重肝病、对抗胰岛素的激素分泌不足、过量胰岛素治疗等。属糖代谢紊乱的常见表现。属糖代谢紊乱中由调节作用失调或代谢酶缺陷引起的一类表现，与高血糖、糖尿共同构成血糖浓度异常的三类情况。","src":"第7讲 糖代谢 IV"},{"id":"f226498b","s":"b","g":"b11","n":"高血糖","e":"Hyperglycemia","d":"空腹血糖浓度＞7.22 mmol/L（130 mg/dL）。原因分两类：生理性高血糖见于餐后、短时运动后、精神紧张时，注射葡萄糖或肾上腺素后；病理性高血糖见于糖尿病（Ⅰ型、Ⅱ型）、甲亢、垂体前叶嗜酸性细胞腺瘤、肾上腺皮质功能亢进症、嗜铬细胞瘤、垂体前叶嗜碱性细胞机能亢进等，是糖尿病的主要表现。糖代谢紊乱的两个主要原因为代谢酶的先天性缺陷和调节作用的失调，高血糖即其常见表现之一。","src":"第7讲 糖代谢 IV"},{"id":"0fc65f7d","s":"b","g":"b11","n":"糖尿","e":"Glucosuria","d":"血糖浓度＞8.89 mmol/L（160 mg/dL）时，葡萄糖随尿排出的现象，表述为\"糖尿：血糖浓度＞8.89 mmol/L\"。属血糖浓度异常的三类情况之一（低血糖、高血糖、糖尿）。糖尿病即以持续性高血糖和糖尿为特征，故糖尿是糖尿病的重要临床指标。低血糖、高血糖与糖尿并列为血糖浓度异常的三类情况，并分别给出诊断界值，血糖升高超过肾脏对葡萄糖的重吸收能力时滤液中的葡萄糖即随尿排出。","src":"第7讲 糖代谢 IV"},{"id":"08fd0466","s":"b","g":"b11","n":"糖尿病","e":"Diabetes mellitus","d":"以持续性高血糖和糖尿为特征的疾病。类型有胰岛素依赖型（Ⅰ型，IDDM）和非胰岛素依赖型（Ⅱ型，NIDDM）；病因为胰岛素缺乏和胰岛素抵抗（与感染、肥胖、体力活动减少、妊娠、遗传、环境因素有关）。胰岛素缺乏、胰岛素受体异常或胰岛素信号通路异常，不能对抗肾上腺素、胰高血糖素、肾上腺皮质激素等引起的血糖升高，产生高血糖和糖尿；病人代谢障碍、供能不足，出现多饮、多食、多尿及体重减少的\"三多一少\"症状，严重时伴酮血症及酸中毒。","src":"第7讲 糖代谢 IV"},{"id":"b2a9ec4c","s":"b","g":"b11","n":"酮体","e":"Ketone bodies","d":"糖尿病未得到控制时脂肪代谢紊乱，大量脂肪酸在肝内转变为酮体，包括乙酰乙酸、β-羟丁酸和丙酮。肝内生酮超过肝外利用能力时，酮体在血中积聚即\"酮血症\"；过多酮体随尿排出为\"酮尿症\"；部分丙酮呼出体外呈\"烂苹果味\"。乙酰乙酸和 β-羟丁酸为酸性物质，血中过多积聚时血液 pH 下降，即酮症酸中毒。糖尿病时脂肪动员加强、酮体生成过多超过肝外组织氧化能力，即出现上述变化，酮症酸中毒属糖尿病的急性并发症。","src":"第7讲 糖代谢 IV"},{"id":"040246e4","s":"b","g":"b11","n":"半乳糖血症","e":"Galactosemia","d":"患者先天缺乏半乳糖激酶（galactose kinase）或 UDPG-半乳糖磷酸尿苷酰转移酶（galactose 1-phosphate uridyl transferase），不能把半乳糖或 1-磷酸半乳糖转化为 UDPGal，半乳糖不能进入 EMP，血中半乳糖增多，引起半乳糖血，严重时导致半乳糖尿。患儿生长迟缓、喝奶后呕吐、腹泻、肝肿大、黄疸、智力迟钝，继续摄入半乳糖会中毒死亡。属糖代谢酶先天性缺陷所致的糖代谢紊乱。","src":"第7讲 糖代谢 IV"},{"id":"6d3891c4","s":"b","g":"b11","n":"蚕豆病（葡萄糖-6-磷酸脱氢酶缺乏症） Glucose-6-phosphate dehydrogenase deficiency","e":"","d":"葡萄糖-6-磷酸脱氢酶（G6PD）缺乏是一种临床表现为溶血性贫血的遗传性疾病，称 G6PD 缺乏症；尤其在吃蚕豆或服用伯氨喹啉类药物后出现血红蛋白尿、黄疸、贫血等急性溶血反应，又称蚕豆病，主要临床有新生儿黄疸、急性溶血性贫血。发病机制：红细胞中缺乏 G6PD 是对蚕豆或蚕豆花粉敏感的主要原因，蚕豆中含蚕豆嘧啶、蚕豆嘧啶核苷、多巴、多巴核苷等氧化作用物质，患者红细胞中 GSH 降低引发溶血。X 染色体不完全显性遗传，3 岁以下占 70%，男性占 90%。","src":"第7讲 糖代谢 IV"},{"id":"b8b488c8","s":"b","g":"b11","n":"己糖激酶缺乏","e":"Hexokinase deficiency","d":"红细胞中己糖激酶缺乏时，葡萄糖磷酸化受影响，糖进入 EMP 途径减少，EMP 途径的中间产物减少，2,3-二磷酸甘油酸缺少，Hb 对 O2 的亲和力异常高，组织获得 O2 的机会少，引起组织缺氧。同时说明红细胞中 2,3-DPG 的重要作用是调节血红蛋白的携带 O2 功能，其含量高是因为红细胞中存在 DPG 变位酶和 2,3-DPG 磷酸酶，后者活性较低使生成大于分解。己糖激酶缺乏属红细胞糖酵解酶缺陷所致的疾病。","src":"第7讲 糖代谢 IV"},{"id":"9b80b2bb","s":"b","g":"b11","n":"丙酮酸激酶缺乏","e":"Pyruvate kinase deficiency","d":"红细胞中丙酮酸激酶缺乏时，PEP 不能生成丙酮酸，EMP 产物浓度增高，2,3-DPG 增多，Hb 对 O2 的亲和力非常低；同时 ATP 减少，降低 Na+、K+-ATPase 活性，细胞无法维持正常离子浓度而肿胀、裂解，导致溶血性贫血。临床表现为遗传性非球形细胞溶血性贫血（HNHA）Ⅱ型。属红细胞糖酵解酶先天性缺陷所致的溶血性疾病，据此说明红细胞糖酵解中间产物与 ATP 供应对维持红细胞结构和功能的重要性。","src":"第7讲 糖代谢 IV"},{"id":"385496e8","s":"b","g":"b11","n":"糖原累积症","e":"Glycogen storage diseases（GSD）","d":"一类发生在肌肉和/或肝脏中，由影响糖原合成、糖原降解或者糖酵解（分解）的酶缺陷所引起的代谢性疾病，又称糖原贮积病或糖原病（glycogenosis and dextrinosis），分遗传性和获得性两类。按缺陷酶分为Ⅰ-Ⅷ型：Ⅰ型葡萄糖-6-磷酸酶缺陷（肝、肾），Ⅱ型溶酶体 α1→4 和 1→6 葡萄糖苷酶（脱支酶），Ⅲ型脱支酶缺失，Ⅳ型分支酶缺失，Ⅴ型肌磷酸化酶缺失，Ⅵ型肝磷酸化酶缺陷，Ⅶ型肌肉和红细胞磷酸果糖激酶缺陷，Ⅷ型肝脏磷酸化酶激酶缺陷。","src":"第7讲 糖代谢 IV"},{"id":"1ff639d7","s":"b","g":"b12","n":"血脂","e":"Blood lipids","d":"指血浆中的中性脂与类脂的总称，前者为甘油三酯和胆固醇，后者包括磷脂、糖脂、固醇和类固醇。标注其含量约为500 mg/dL，且波动范围较大。血脂的来源有三：食物中的脂类、体内合成的脂类以及脂库动员释放；去路包括氧化供能、进入脂库储存、构成生物膜和转变成其他物质。血脂在血浆中并非游离存在，而是与蛋白质结合成脂蛋白运输，其水平受膳食与代谢状态影响，是评价脂类代谢的常用指标。","src":"第8-9讲 脂类代谢 I"},{"id":"64ce27a3","s":"b","g":"b12","n":"脂蛋白脂肪酶","e":"Lipoprotein lipase","d":"指催化脂蛋白中甘油三酯水解的酶，在脂肪消化吸收过程中发挥作用。它的作用列为食物脂肪吸收过程的第6步：乳糜微粒经淋巴系统和血液进入组织后，其表面的载脂蛋白C-II激活脂蛋白脂肪酶，使乳糜微粒中的脂肪重新水解为游离脂肪酸和甘油；释出的脂肪酸进入细胞，或被氧化释放能量，或在肌细胞及脂肪组织中酯化储存。该酶因此是外源脂肪由血液转入组织的关键，其活性受载脂蛋白C-II调节。","src":"第8-9讲 脂类代谢 I"},{"id":"f3dd8e66","s":"b","g":"b12","n":"奥利司他","e":"Orlistat","d":"指一种用于治疗肥胖的药物，主要作用是作为脂肪酶抑制剂，阻止食物脂肪在人体肠道内被吸收，从而减少热量摄入。其处方药商品名为赛尼可（Xenical），由罗氏公司销售，非处方药商品名为Alli，在英国和美国销售；使用时须配合医生监督下的低热量膳食。此外，奥利司他最近被发现可抑制脂肪酸合成酶（FAS）的硫酯酶结构域，并展示过人脂肪酸合成酶被其抑制的结晶结构。","src":"第8-9讲 脂类代谢 I"},{"id":"d7b34742","s":"b","g":"b12","n":"脂肪动员","e":"Adipokinetic action","d":"指脂肪组织中的脂肪在一系列脂肪酶作用下水解为脂肪酸和甘油并释放入血液、供其他组织利用的过程。参与的酶包括甘油三酯脂肪酶（ATGL）、激素敏感脂肪酶（HSL）和单甘油酯脂肪酶（MGL）。激素敏感脂肪酶受多种激素调控：胰岛素下调其活性，肾上腺素与胰高血糖素上调其活性。动员出的脂肪酸由血清白蛋白非共价结合（约1∶10）运输至骨骼肌、心脏和肾上腺皮质，解离进入细胞氧化供能。","src":"第8-9讲 脂类代谢 I"},{"id":"f5a0b754","s":"b","g":"b12","n":"甘油激酶","e":"Glycerol kinase","d":"指催化甘油磷酸化生成3-磷酸甘油并消耗ATP的酶。脂肪细胞缺乏甘油激酶，不能利用甘油，故脂肪动员释出的甘油随血液回到肝脏再被利用：在肝中变为3-磷酸甘油后，可与活化的脂肪酸合成脂肪，也可生成磷酸二羟丙酮参与酵解氧化供能，或经糖异生转变为糖。甘油经此途径彻底氧化，按1 NADH计3 ATP、1 FADH2计2 ATP，净生成22或20个ATP。脂肪组织合成脂肪的甘油骨架只能来自磷酸二羟丙酮。","src":"第8-9讲 脂类代谢 I"},{"id":"b2f399a6","s":"b","g":"b12","n":"β-氧化 β-oxidation","e":"","d":"指脂肪酸从羧基端β位碳原子开始、每轮分解出一个二碳片段（乙酰CoA）的氧化方式，由Knoop于1904年用苯基标记喂养试验提出假说。每轮包括四步反复反应：脂酰CoA的α、β脱氢生成反式烯脂酰CoA，三种脂酰CoA脱氢酶均以FAD为辅基；烯脂酰CoA水化生成L(+)-β-羟脂酰CoA；再脱氢生成β-酮脂酰CoA，酶以NAD+为辅酶；最后由硫解酶催化硫解断链。脂肪酸只需活化一次，每轮产生1乙酰CoA、1 FADH2和1 NADH。","src":"第8-9讲 脂类代谢 I"},{"id":"f776df2c","s":"b","g":"b12","n":"脂酰CoA合成酶","e":"Acyl-CoA synthetase","d":"指催化脂肪酸活化生成脂酰CoA的酶，也称硫激酶，反应为脂肪酸与ATP、HS-CoA生成脂酰CoA、AMP和焦磷酸，需Mg2+，实际消耗ATP的两个高能磷酸键。细胞内有两类：内质网的酶活化12个碳原子以上的脂肪酸，线粒体的酶活化4~10个碳原子的脂肪酸，活化的酶位于线粒体膜外。活化后脂酰CoA水溶性增加，有利于反应进行，且β-氧化的酶对脂酰CoA有专一性，故活化是脂肪酸氧化的必要前提。","src":"第8-9讲 脂类代谢 I"},{"id":"5d3c4f10","s":"b","g":"b12","n":"肉碱转运","e":"Carnitine shuttle","d":"指长链脂肪酸进入线粒体基质进行β-氧化的特殊转运机制。中、短链脂肪酸（12C及以下）可直接穿过线粒体内膜，长链脂肪酸须经肉碱（L-carnitine）转运：脂酰CoA在肉碱-脂酰转移酶催化下生成脂酰肉碱，经肉碱/脂酰肉碱移位酶穿过内膜，再释放脂酰CoA。该体系包括肉碱转移酶I和II，14C及以上的脂酰CoA均需此转运；丙二酸单酰CoA抑制肉碱脂酰转移酶I，限制脂肪酸进入线粒体。","src":"第8-9讲 脂类代谢 I"},{"id":"e5c513e4","s":"b","g":"b12","n":"不饱和脂肪酸的氧化","e":"Oxidation of unsaturated fatty acids","d":"指不饱和脂肪酸进入线粒体后按β-氧化途径降解的过程，其途径基本上是饱和脂肪酸的β-氧化，同样需要活化和转运。由于天然不饱和脂肪酸都是顺式构型，β-氧化在遇到双键前仍为常规反应；遇到Δ3顺式烯脂酰CoA时，在异构酶作用下转变为Δ2反式烯脂酰CoA即可继续β-氧化；若生成D(-)-β-羟脂酰CoA，需差向异构生成L-型异构物；多不饱和脂肪酸彻底氧化还需差向异构酶参与。","src":"第8-9讲 脂类代谢 I"},{"id":"c1039d26","s":"b","g":"b12","n":"丙酸代谢","e":"Propionate metabolism","d":"指奇数碳脂肪酸经β-氧化生成丙酰CoA后的进一步代谢。奇数碳脂肪酸与偶数碳脂肪酸一样经多次β-氧化，最终除生成乙酰CoA外还产生1分子丙酰CoA；人体内奇数碳脂肪酸极少，但植物和海洋生物中常见，反刍动物瘤胃发酵及Val、Ile降解也产生丙酸。动物中丙酰CoA经丙酰CoA羧化酶、异构酶和甲基丙二酸单酰CoA变位酶催化转变为琥珀酰CoA进入TCA；植物和微生物中则经β-羟丙酸支路生成乙酰CoA。","src":"第8-9讲 脂类代谢 I"},{"id":"c61c9fb3","s":"b","g":"b12","n":"过氧化物酶体的脂肪酸氧化","e":"Peroxisomal fatty acid oxidation","d":"指过氧化物酶体以与线粒体相似但不完全相同的方式氧化脂肪酸的途径。其β-氧化第一步由黄素蛋白脱氢酶催化脱氢生成FADH2，电子直接传递给O2生成H2O2，后者被过氧化氢酶分解解毒。动物组织中约25%~50%的脂肪酸在此氧化。与主要氧化短链及中长链脂肪酸（C8~C20）的线粒体不同，过氧化物酶体主要氧化极长链脂肪酸（≥C22）、2-甲基支链脂肪酸如降植烷酸、胆汁酸代谢中间物及多不饱和脂肪酸等。","src":"第8-9讲 脂类代谢 I"},{"id":"59ce16d3","s":"b","g":"b12","n":"α-氧化 α-oxidation","e":"","d":"指在脂肪酸α-碳上进行的氧化，这种途径发生于某些因β-碳被封闭（如连有甲基）而无法进行β-氧化的脂肪酸。反应仅以游离脂肪酸为底物，直接涉及分子氧，产物既可是D-α-羟基脂肪酸，也可是少一个碳的脂肪酸或脂肪醇。植物中的脂肪酸过氧化物酶是含铁卟啉的蛋白质，铁卟啉为其活性中心，催化长链脂肪酸α-氧化脱羧，把α-碳氧化成醛基；哺乳动物中该途径发生在肝脏和脑的过氧化物酶体。","src":"第8-9讲 脂类代谢 I"},{"id":"9f09cf8e","s":"b","g":"b12","n":"Refsum综合征","e":"Refsum disease","d":"指一种由先天性代谢缺陷引起的肥大型多发性神经疾病，又称植烷酸贮积病，由挪威医生Refsum于1946年首先提出。植烷酸（由食物中的植醇转化而来）在体内大量堆积是其最主要特点：血清植烷酸占血清脂肪酸总量的7%~23%，正常人仅约0.01%，肝中堆积量约占脂肪酸总量的50%。健康人能将植醇吸收量的26.2%氧化分解，患者仅能氧化2.7%，其皮肤成纤维细胞氧化植烷酸的能力不到正常人的1%。","src":"第8-9讲 脂类代谢 I"},{"id":"06e76bb7","s":"b","g":"b12","n":"ω-氧化 ω-oxidation","e":"","d":"指脂肪酸在远离羰基碳的ω-碳上发生氧化、生成二元羧酸的途径，由Verkade于1932年发现：喂养一元羧酸后出现二元羧酸，十一碳羧酸变成十一碳、九碳、七碳的二元羧酸。该途径多发生于无脊椎动物肝脏和肾脏的内质网中，底物多为12或10碳的脂肪酸。第一步在ω-碳上引入羟基，氧来自分子氧，由混合功能加氧酶系统催化，涉及细胞色素P450和电子供体NADPH，还需醇脱氢酶和醛脱氢酶参与。","src":"第8-9讲 脂类代谢 I"},{"id":"12b9bd90","s":"b","g":"b12","n":"酮体的生成","e":"Ketogenesis","d":"指肝细胞中以乙酰CoA为原料合成酮体的三步酶促过程。两分子乙酰CoA在硫解酶催化下缩合成乙酰乙酰CoA；乙酰乙酰CoA与乙酰CoA在HMG-CoA合成酶催化下生成羟甲基戊二酰CoA（HMG-CoA）；HMG-CoA再由HMG-CoA裂解酶裂解生成乙酰乙酸，乙酰乙酸可还原为β-羟丁酸或脱羧生成丙酮。严重饥饿时TCA中间产物被糖异生消耗，乙酰CoA氧化减少，酮体生成增多。","src":"第8-9讲 脂类代谢 I"},{"id":"e8ac01b0","s":"b","g":"b12","n":"酮症酸中毒","e":"Ketoacidosis","d":"指酮体生成超过肝外组织氧化能力时出现的代谢紊乱。严重饥饿或未治疗的糖尿病人产生过量酮体：胰岛素不足时肝外组织不能充分利用葡萄糖，丙二酸单酰CoA不形成，不能抑制肉碱脂酰转移酶I，脂肪酸大量进入线粒体生成乙酰CoA，而草酰乙酸缺乏使乙酰CoA不能进入TCA。血中乙酰乙酸和β-羟丁酸增多使pH下降，引起酸中毒，极度酸中毒可致昏迷甚至死亡；血、尿酮体极高称酮症，二者合称酮症酸中毒。","src":"第8-9讲 脂类代谢 I"},{"id":"f018616a","s":"b","g":"b12","n":"脂肪酸的从头合成","e":"De novo synthesis","d":"指以乙酰CoA为原料在细胞质中全程合成脂肪酸的途径，又称全程合成，是脂肪酸合成的主要途径。合成在胞质（非线粒体系统）中进行，产物是长链脂肪酸，多为软脂酸，需要ACP、ATP、CO2、NADPH和Mn2+。合成中只有一个C2物以乙酰CoA形式作为引物，其余延伸的C2物均以丙二酸单酰CoA（三碳）形式参与。总反应消耗7分子ATP和14分子NADPH，生成1分子软脂酸。","src":"第8-9讲 脂类代谢 I"},{"id":"7bbda92c","s":"b","g":"b12","n":"柠檬酸-丙酮酸循环","e":"Citrate-pyruvate cycle","d":"指把线粒体内的乙酰CoA运往细胞质用于脂肪酸合成的转运机制。线粒体内膜对乙酰CoA不透过，乙酰CoA须先与草酰乙酸在柠檬酸合成酶催化下生成柠檬酸，柠檬酸被运送到胞质再裂解出乙酰CoA，供脂肪酸合成使用；其余碳架经丙酮酸等步骤返回线粒体，循环由此得名。非光合真核生物中，几乎所有用于脂肪酸合成的乙酰CoA都来自线粒体中丙酮酸的氧化及氨基酸碳架的分解，而脂肪酸氧化产生的乙酰CoA不作为原料。","src":"第8-9讲 脂类代谢 I"},{"id":"de09d239","s":"b","g":"b12","n":"乙酰CoA羧化酶","e":"Acetyl-CoA carboxylase","d":"指催化乙酰CoA和CO2形成丙二酸单酰CoA的酶，简写ACC，反应不可逆，需ATP和生物素。它是别构酶，也是脂肪酸合成的限速步骤。无活性的酶有三个结合位点：HCO3-结合位点、乙酰CoA结合位点及柠檬酸结合位点；柠檬酸及异柠檬酸是酶的正激活剂，无柠檬酸时酶无活力。该反应把二碳的乙酰CoA活化为三碳的丙二酸单酰CoA，为脂肪酸合酶提供延伸单位，其活性直接决定脂肪酸合成的速度。","src":"第8-9讲 脂类代谢 I"},{"id":"2ee7b293","s":"b","g":"b12","n":"脂肪酸合酶复合物","e":"Fatty acid synthase complex","d":"指催化脂肪酸生物合成的酶复合物，简写FAS。大肠杆菌的脂肪酸合酶由七个独立的多肽紧密协同为一个整体，包括一个ACP蛋白和六个酶：乙酰CoA-ACP转酰酶、丙二酸单酰CoA-ACP转移酶、β-酮脂酰-ACP合酶、β-酮脂酰-ACP还原酶、β-羟脂酰-ACP脱水酶和烯脂酰-ACP还原酶。ACP以硫酯键把脂酰基团连接在复合物上，代替脂酰CoA形式；动物体中该酶催化启动、装载、缩合、还原、脱水、还原、释放七步反应。","src":"第8-9讲 脂类代谢 I"},{"id":"b215d684","s":"b","g":"b12","n":"线粒体系统的延伸合成","e":"Mitochondrial elongation","d":"指在线粒体基质中延长脂肪酸碳链的合成方式，属于动物合成脂肪酸的两种方式之一（另一种为胞质中的全程合成）。该系统只能在C12、C14、C16的基础上逐步添加C2物，生成延长碳链的长链脂肪酸，需乙酰CoA、NADH和NADPH。反应基本上是β-氧化的逆过程，只有个别反应不同：脂酰CoA脱氢酶不参与逆反应，合成时由烯脂酰CoA还原酶催化，且需NADPH而不是FADH2。","src":"第8-9讲 脂类代谢 I"},{"id":"7a46b5e9","s":"b","g":"b12","n":"内质网系统的延伸合成","e":"Microsomal elongation","d":"指在内质网中延长脂肪酸碳链、尤其合成多烯不饱和脂肪酸的途径，与线粒体系统同属延伸合成。反应需NADPH和丙二酸单酰CoA，在脂肪酸的非甲基端添加C2物，其机理尚不清楚。内质网中还存在一种双功能加氧酶，催化双键的形成。脂肪酸合成分为三部分：全程合成在细胞质，延伸合成在内质网或线粒体，双键引入在内质网，三者共同完成从软脂酸到长链及不饱和脂肪酸的转变，构成完整的脂肪酸合成体系。","src":"第8-9讲 脂类代谢 I"},{"id":"fb7b5576","s":"b","g":"b12","n":"脂肪肝","e":"Fatty liver","d":"指肝脏脂肪含量超过正常标准上限的病理状态。肝脏是脂肪代谢最为活跃的场所，正常情况下健康成人肝中脂肪含量不超过肝脏总重量的4%~5%；一旦超过正常标准上限的5%，临床上即可诊断为脂肪肝。脂肪含量占肝脏重量5%~10%为轻度脂肪肝，10%~25%为中度，超过25%~50%为重度。主要成因包括肥胖少动、嗜酒豪饮、营养失调、合并糖尿病及乱服药物，治疗以饮食调治、锻炼和药物为主。","src":"第8-9讲 脂类代谢 I"},{"id":"5fc5534a","s":"b","g":"b12","n":"磷脂酶","e":"Phospholipases","d":"指参与甘油磷脂分解代谢的酶类，包括A（A1和A2）、B、C和D四大类，各自作用于磷脂分子中不同的酯键。A1广泛存在于动物细胞器和微粒体，专一水解磷脂分子C1上的酯键，产物为溶血性磷脂；A2大量存在于蛇毒、蝎毒和蜂毒，专一水解C2上的酯键，产物也是溶血性磷脂；B专一水解A2水解产物1-脂酰磷脂C1上的酯键；C主要存在于动物脑、蛇毒和微生物中，作用于磷脂酸C3位的磷酸酯键；D主要存在于高等植物，水解C3位第二个磷酸酯键。","src":"第9-10讲 脂类代谢 II"},{"id":"4684fc6f","s":"b","g":"b12","n":"溶血磷脂","e":"Lysophospholipid","d":"指甘油磷脂分子中甘油骨架上去掉任何一个酯键后形成的产物，属于磷脂分解代谢的中间物。由于失去一个脂酰基，它作为膜脂的功能被破坏，可导致细胞膜损坏即溶血，故称溶血甘油磷脂，催化其生成的酶称溶血磷脂酶。磷脂酶A1水解C1位酯键、磷脂酶A2水解C2位酯键、磷脂酶B水解溶血磷脂C1位酯键均可产生溶血磷脂。溶血磷脂是甘油磷脂酶解的首个产物，其进一步水解仍由溶血磷脂酶催化完成。","src":"第9-10讲 脂类代谢 II"},{"id":"7cc0cfa0","s":"b","g":"b12","n":"甘油磷脂的合成","e":"Glycerophospholipid synthesis","d":"指以脂酰CoA和L-甘油-3-磷酸为共同前体合成甘油磷脂的途径，它与甘油三酯的合成共用这两个前体及相同的几步反应。合成的起点可以是酵解产生的磷酸二羟丙酮，在肝脏和肾中还可由甘油经甘油激酶作用生成；另一前体脂酰CoA由脂肪酸经脂酰CoA合成酶催化生成。两个前体先合成磷脂酸，磷脂酸再转变为活化的中间物，与不同的极性头部供体连接，生成磷脂酰胆碱、磷脂酰乙醇胺等各类甘油磷脂。","src":"第9-10讲 脂类代谢 II"},{"id":"98500073","s":"b","g":"b12","n":"CDP-二脂酰甘油","e":"CDP-diacylglycerol","d":"指甘油磷脂合成中活化的中间物，由磷脂酸与CTP反应生成。在细菌的卵磷脂从头合成中，α-磷酸甘油先与2分子脂酰辅酶A合成磷脂酸，磷脂酸再与CTP生成CDP-二脂酰甘油；后者与L-丝氨酸生成磷脂酰丝氨酸，磷脂酰丝氨酸脱羧生成磷脂酰乙醇胺，再经N原子上的甲基化生成卵磷脂。它提供了甘油磷脂合成中极性头部对接所需的活化形式；哺乳动物合成卵磷脂时，CDP-乙醇胺和CDP-胆碱起类似的活化作用。","src":"第9-10讲 脂类代谢 II"},{"id":"d3db6b08","s":"b","g":"b12","n":"卵磷脂的从头合成","e":"De novo synthesis of lecithin","d":"指不依赖现成胆碱、从简单前体合成卵磷脂的途径，在细菌和哺乳动物中步骤不同。细菌中：α-磷酸甘油与2分子脂酰辅酶A合成磷脂酸；磷脂酸与CTP生成CDP-二脂酰甘油；与L-丝氨酸生成磷脂酰丝氨酸；脱羧生成磷脂酰乙醇胺；最后在N原子上甲基化生成卵磷脂。哺乳动物中：乙醇胺与ATP生成磷酸乙醇胺；与CTP生成CDP-乙醇胺；与甘油二酯生成磷脂酰乙醇胺；再甲基化生成卵磷脂。","src":"第9-10讲 脂类代谢 II"},{"id":"cff8a259","s":"b","g":"b12","n":"卵磷脂合成的补救途径","e":"Salvage pathway","d":"指以胆碱为起始物、由三步反应组成卵磷脂合成途径，是动物细胞中卵磷脂的主要合成途径。第一步，胆碱在激酶催化下与ATP生成磷酸胆碱；第二步，磷酸胆碱在转移酶催化下与CTP生成CDP-胆碱并释出焦磷酸；第三步，CDP-胆碱在转移酶催化下与甘油二酯生成卵磷脂并释出CMP。与从头合成相比，该途径直接利用食物或代谢产生的胆碱，不必经乙醇胺的逐步甲基化，是补充卵磷脂的重要方式。","src":"第9-10讲 脂类代谢 II"},{"id":"17f99e9b","s":"b","g":"b12","n":"缩醛磷脂","e":"Plasmalogen","d":"指醚脂的一种，醚脂包括缩醛磷脂和血小板激活因子两类。其合成需要长链脂肪醇，以醚键方式代替通常磷脂中脂肪酸的酯键连接；头部极性基团的合成方式与通常磷脂的合成一致，双键的引入机制则类似于脂肪酸脱饱和作用中的混合功能加氧酶的作用。过氧化物酶体是缩醛磷脂合成的主要场所。其头部合成方式与通常磷脂一致，可见它与普通甘油磷脂的差别主要在于疏水骨架以醚键代替酯键，它属于甘油磷脂中的醚脂类。","src":"第9-10讲 脂类代谢 II"},{"id":"99c92eb1","s":"b","g":"b12","n":"神经酰胺","e":"Ceramide","d":"指N-脂酰鞘氨醇，是鞘脂合成的中心中间物。其生成包括：由软脂酸（脂酰CoA）和丝氨酸合成十八碳胺即二氢鞘氨醇；二氢鞘氨醇进一步与脂酰CoA生成脂酰二氢鞘氨醇；二氢鞘氨醇的碳链部分脱饱和即生成神经酰胺。神经酰胺由卵磷脂分子获得磷酸胆碱而合成鞘磷脂，与活性糖连接则合成脑苷脂等鞘糖脂，二者分别构成鞘磷脂与鞘糖脂两大类。这两类鞘脂拥有相同的前体及部分相同的合成过程。","src":"第9-10讲 脂类代谢 II"},{"id":"494db744","s":"b","g":"b12","n":"泰-萨病","e":"Tay-Sachs disease","d":"指一种由第15号染色体上等位基因HEXA突变引起的常染色体隐性疾病，HEXA编码β-己糖胺酶A的α-亚基。正常情况下该酶催化降解GM2神经节苷脂，患者缺乏或只有少量这种酶，造成GM2神经节苷脂在神经中过量堆积，即GM2神经节苷酯沉积病，神经节苷脂积累于脑和脾。病情进展首先取决于GM2累积的速度和程度，其次取决于功能性β-己糖胺酶的水平。患者逐渐神经紧张、眼瞎，3~4岁死亡，发病率约三十万分之一。","src":"第9-10讲 脂类代谢 II"},{"id":"9f9e7fa1","s":"b","g":"b12","n":"尼曼-皮克病","e":"Niemann-Pick disease","d":"指一种遗传性代谢紊乱疾病，属于神经磷脂病。患者先天缺失鞘磷脂水解酶，不能由鞘脂水解去除磷酸胆碱，致使鞘脂沉积于患者的脾、肝、肺、骨髓及部分患者的脑中。本病首发于婴儿，引起神经紧张和早死。1914年德国儿科医生Albert Niemann描述了一例患脑和神经系统疾病不治的儿童，20世纪20年代Luddwick Pick研究这类儿童死后的组织，找到了病因证据；它与泰-萨病同属鞘脂代谢疾病。","src":"第9-10讲 脂类代谢 II"},{"id":"b35e8032","s":"b","g":"b12","n":"Sandhoff病","e":"Sandhoff's disease","d":"指一种与泰-萨病相似的GM2神经节苷脂积累病，但不影响犹太人。患者缺乏两种形式的己糖胺酶（氨基己糖苷酶），致使GM2神经节苷脂在体内积累；泰-萨病则缺乏β-己糖胺酶A的α-亚基，二者缺陷的酶不同。本病较为少见，主要影响发育中的儿童，表现为听力失常、早盲、精神与运动障碍、洋娃娃脸、樱桃红斑点、心脏变大，进而吞咽和呼吸困难、胸肺感染，一般3岁前死亡，为常染色体隐性遗传。","src":"第9-10讲 脂类代谢 II"},{"id":"2c2a317f","s":"b","g":"b12","n":"肠肝循环","e":"Enterohepatic circulation","d":"指经胆汁或部分经胆汁排入肠道的物质（如胆固醇、胆汁酸、胆红素、药物等），在肠道中又重新被吸收，经门静脉又返回肝脏的现象。它是胆固醇消化吸收的三大特点之一，另两个特点是吸收延迟和吸收有限。借助这一循环，排入肠道的胆固醇、胆汁酸、胆红素及部分药物被回收再利用。胆汁酸盐在肠道重吸收后返回肝脏，再随胆汁排入肠道，如此反复构成循环途径，从而减少胆固醇的丢失，维持体内胆固醇池的稳定。","src":"第9-10讲 脂类代谢 II"},{"id":"b25b381f","s":"b","g":"b12","n":"胆汁酸","e":"Bile acids","d":"指胆固醇的极性衍生物，在肝脏生成后分泌入胆囊，经胆管进入肠道，帮助脂肪及脂溶性维生素的消化与吸收。胆汁酸为两亲性分子，具有去污剂性质。胆汁酸盐简称胆盐，主要指胆汁酸的钠盐或钾盐，分两类：游离型包括胆酸、脱氧胆酸、鹅脱氧胆酸和石胆酸；结合型主要有甘氨胆酸、牛黄胆酸、甘氨鹅脱氧胆酸和牛黄鹅脱氧胆酸。胆盐能降低油水两相间的表面张力，促进脂类乳化，并防止胆结石生成。","src":"第9-10讲 脂类代谢 II"},{"id":"9e50e6dc","s":"b","g":"b12","n":"脂酰辅酶A-胆固醇脂酰转移酶","e":"ACAT","d":"指催化胆固醇与长链脂酰CoA连接形成胆固醇酯的酶，简写ACAT。它在胆固醇的吸收、运输和贮存过程中起重要作用，并为脂蛋白组装提供胆固醇酯。病理条件下，ACAT催化形成过多的胆固醇酯可引起动脉粥样硬化；抑制ACAT可降低血浆总胆固醇及低密度脂蛋白胆固醇水平，防止胆固醇酯化，减少胆固醇酯在动脉壁上积蓄，从而阻止动脉粥样硬化的形成，故其抑制剂可能成为新型降血脂药物。","src":"第9-10讲 脂类代谢 II"},{"id":"dca8c56b","s":"b","g":"b12","n":"胆固醇的生物合成","e":"Cholesterol biosynthesis","d":"指以乙酰CoA为原料合成胆固醇的途径，场所为肝脏（主要）的胞质和内质网。全过程分五步：乙酰CoA（C2）先合成甲羟戊酸（MVA，C6）；MVA转变为活化的异戊二烯单位（C5）；C5经C10、C15缩合为C30的鲨烯；鲨烯转变为羊毛甾醇，形成四个环的固醇核；最后由羊毛甾醇形成胆固醇。其中HMG-CoA转变为MVA由HMG-CoA还原酶催化，是限速步骤，受胞内胆固醇浓度及激素调节。","src":"第9-10讲 脂类代谢 II"},{"id":"1ebc50c9","s":"b","g":"b12","n":"HMG-CoA还原酶","e":"HMG-CoA reductase","d":"指催化胆固醇合成限速步骤、即HMG-CoA转变为甲羟戊酸（MVA）的酶。其活性受胞内胆固醇浓度和激素调节：受胆固醇衍生物及MVA的变构抑制；胰高血糖素和肾上腺素通过磷酸化使其失活，胰岛素促进去磷酸化而激活，即磷酸化失活、去磷酸化激活。胞内胆固醇浓度升高还激活ACAT促进胆固醇酯化储存，并使LDL受体减少，减缓向血液中吸收胆固醇。它也是他汀类降胆固醇药物的作用靶点。","src":"第9-10讲 脂类代谢 II"},{"id":"81694989","s":"b","g":"b12","n":"他汀类药物","e":"Statins","d":"指HMG-CoA还原酶抑制剂类降胆固醇药物，通过阻断胆固醇合成的关键步骤降低血浆胆固醇。第一个上市的是Merck公司1987年推出的洛伐他汀，此后辛伐他汀、普伐他汀、氟伐他汀、阿伐他汀、西立伐他汀、罗伐他汀等相继上市。此类药物作为饮食控制的补充，用于高胆固醇患者，可降低冠心病死亡、心肌梗死及中风的风险；1999年全球销售额超过100亿美元，是当时最畅销的药物类别之一。","src":"第9-10讲 脂类代谢 II"},{"id":"b2c19368","s":"b","g":"b12","n":"胆固醇结石","e":"Cholesterol stones","d":"指胆结石的一种，与色素性结石并列，属于胆固醇病理性积累的形式之一，另一种为动脉粥样硬化。胆结石的成分有胆固醇、胆色素、胆酸盐及蛋白胶质，据此分为色素性结石和胆固醇结石两类。胆道中胆固醇浓度很高，当胆囊黏膜重吸收胆囊中的水分和胆汁盐时，若吸收过程太过分，本不溶于水而溶于含胆汁盐水溶液中的胆固醇便从胆汁中结晶析出，形成结石；胆囊发炎时吸收更快，结石更易形成并逐渐增大。","src":"第9-10讲 脂类代谢 II"},{"id":"da58efaa","s":"b","g":"b12","n":"动脉粥样硬化","e":"Atherosclerosis","d":"指动脉内膜形成的胆固醇斑纹所造成的动脉病变。患者血液胆固醇或胆固醇与磷脂的比值升高，脂质向动脉内膜浸润并黏着于血管壁，形成动脉粥样斑。过去认为其原因是摄入胆固醇过高，即膳食假说；但生物体内90%以上的胆固醇是体内合成的内源性胆固醇，因此控制动脉粥样硬化应考虑胆固醇合成、分解及排泄速度等因素。ACAT催化形成过多胆固醇酯也会使胆固醇酯在动脉壁积蓄，促进粥样硬化。","src":"第9-10讲 脂类代谢 II"},{"id":"9daf9755","s":"b","g":"b12","n":"高胆固醇血症","e":"Hypercholesterolemia","d":"指血浆胆固醇水平超过正常范围的状态，美国约有6500万成人受累。它是冠心病（CHD）的独立危险因素，而冠心病是美国第一位致死原因。其判定标准为总胆固醇>200 mg/dL、低密度脂蛋白胆固醇（LDL）>130 mg/dL，或高密度脂蛋白胆固醇（HDL）<40 mg/dL。治疗包括运动与饮食控制、HMG-CoA还原酶抑制剂（他汀类），新的疗法有烟酸以及烟酸与他汀类合用。","src":"第9-10讲 脂类代谢 II"},{"id":"5270acef","s":"b","g":"b12","n":"乳糜微粒","e":"Chylomicron","d":"指血浆四种脂蛋白之一，简写CM。其电泳位置在原点，直径最大、比重最小，含脂比例最大达98%，蛋白质所占比例最低。它含有胆固醇、甘油三酯、磷脂和蛋白质，其中的甘油三酯来自食物脂肪在肠黏膜细胞的再合成，故主要运输外源甘油三酯。乳糜微粒中的载脂蛋白C-II激活脂蛋白脂肪酶，使脂肪水解为脂肪酸和甘油供组织利用，残余的残渣被肝脏摄取；电泳时它停留在原点，可与其他三类脂蛋白区分。","src":"第9-10讲 脂类代谢 II"},{"id":"c77f98c1","s":"b","g":"b12","n":"前β-脂蛋白","e":"Pre-β-lipoprotein","d":"指血浆四种脂蛋白之一，电泳出现在α2-球蛋白处，直径及含脂比例（90%）仅次于乳糜微粒，比重大于乳糜微粒，相当于极低密度脂蛋白（VLDL）。它含有胆固醇、甘油三酯、磷脂和蛋白质，各组分比例与乳糜微粒不同。由于含脂比例高、直径较大，其漂浮性质介于乳糜微粒与β-脂蛋白之间。以电泳位置、直径、含脂比例和比重四项指标区分四类脂蛋白，它是四类中直径和含脂比例居第二者。","src":"第9-10讲 脂类代谢 II"},{"id":"4d88f715","s":"b","g":"b12","n":"β-脂蛋白 β-lipoprotein","e":"","d":"指血浆四种脂蛋白之一，电泳出现在β-球蛋白处，直径及含脂比例（70%）小于乳糜微粒和前β-脂蛋白，相当于低密度脂蛋白（LDL）。LDL被称为坏胆固醇，负责把胆固醇运送到包括冠状动脉在内的组织，但过量时促进胆固醇在动脉壁的蓄积；其组成中载脂蛋白约占25%、胆固醇约占45%，载脂蛋白B-100是已知最大的单条多肽链之一，含4636个氨基酸残基，分子量513000。","src":"第9-10讲 脂类代谢 II"},{"id":"2614ce34","s":"b","g":"b12","n":"α-脂蛋白 α-lipoprotein","e":"","d":"指血浆四种脂蛋白之一，电泳出现在α1-球蛋白处，直径及含脂比例（67%）次于前三种脂蛋白，但比重最大，相当于高密度脂蛋白（HDL）。HDL被称为好胆固醇，其作用是把胆固醇运回肝脏。用HDL水平与冠心病发生率的数据说明其保护作用：HDL为25 mg/dL时男性发病率为18%，随HDL升高发病率下降，HDL达75 mg/dL时男性为0%，说明HDL对冠心病具有明显的保护作用。","src":"第9-10讲 脂类代谢 II"},{"id":"d7f1f76d","s":"b","g":"b12","n":"肥胖症","e":"Obesity","d":"指全身性脂肪堆积过多、导致体内一系列病理生理变化的疾病状态。其衡量标准为体重指数（BMI），即体重（kg）除以身高（m）的平方：24~26为轻度肥胖，26~28为中度肥胖，>28为重度肥胖。肥胖症常伴有高血糖、高血脂、高血压和高胰岛素血症。肥胖症放在脂类代谢紊乱部分讲述，上述伴随表现说明脂肪堆积过多与糖、脂代谢异常密切相关，是脂类代谢紊乱的重要表现之一。","src":"第9-10讲 脂类代谢 II"},{"id":"2aa9380b","s":"b","g":"b13","n":"氮素循环","e":"Nitrogen cycle","d":"指氮素在生物圈中循环、构成生物氮库的过程。空气是最重要的氮源，含有近4/5的氮气分子，但极少生物能转化氮气为可利用的氮素。循环第一步是固氮细菌固定（还原）空气氮生成氨；土壤细菌氧化氨生成亚硝酸盐和硝酸盐以获得能量，这一过程为硝化作用；植物和许多微生物经硝酸或亚硝酸还原酶吸收硝酸盐，氨被植物固定为氨基酸。有机体死亡后微生物分解其蛋白质把氨回放土壤；无氧时细菌把硝酸盐转变为N2，称反硝化作用。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"25c71349","s":"b","g":"b13","n":"氮平衡","e":"Nitrogen balance","d":"指反映人体蛋白质代谢概况的指标。蛋白质的平均含氮量为16%，食物中的含氮物绝大部分为蛋白质，因此测定食物中的含氮量以及尿与粪中的含氮量，可以反映人体蛋白质的代谢概况。氮的总平衡为摄入氮等于排出氮，收支平衡，反映正常成人的蛋白质代谢情况；氮的正平衡为摄入氮大于排出氮，反映儿童、孕妇及恢复期病人的代谢；氮的负平衡为摄入氮小于排出氮，反映饥饿或消耗性疾病患者，故氮平衡是评价蛋白质营养状况的常用指标。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"07e4564d","s":"b","g":"b13","n":"蛋白质的营养价值","e":"Protein nutritional value","d":"指评价食物蛋白质质量的指标，它取决于两个方面：一是必需氨基酸的种类和数量，二是必需氨基酸的比例。凡含有人体所需的全部必需氨基酸、且各氨基酸比例与人体需要相近的蛋白质，营养价值就高；缺乏某种必需氨基酸或比例不当者，营养价值低。由于人体不能合成必需氨基酸而必须由食物供给，评价蛋白质的营养价值实质上就是看其提供必需氨基酸的能力，因此蛋白质的营养价值由必需氨基酸决定。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"9b7ddd48","s":"b","g":"b13","n":"蛋白质的消化","e":"Digestion of proteins","d":"指食物蛋白从胃到小肠、由多种蛋白水解酶依次作用分解为氨基酸和小肽的过程。食物蛋白在胃中经胃蛋白酶作用分解为小肽，进入小肠后经胰蛋白酶、胰凝乳蛋白酶作用变为更短的肽，再经肠黏膜的二肽酶、氨肽酶及胰脏分泌的羧肽酶作用，经肠壁细胞进入肝脏，再由血液运至组织细胞。各酶作用位点不同：胰蛋白酶作用于Lys、Arg的羧基端，胰凝乳蛋白酶作用于Phe、Trp、Tyr的羧基端，弹性蛋白酶作用于各种脂肪族氨基酸形成的肽。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"47d33151","s":"b","g":"b13","n":"多肽的吸收","e":"Absorption of peptides","d":"指人体以多肽形式吸收蛋白质消化产物的机制。过去认为蛋白质经消化道酶促水解后主要以氨基酸的形式被吸收，近年的研究结果表明，人体吸收蛋白质的主要形式不是氨基酸而是多肽，这是人体吸收蛋白质机制的新认识。这一认识说明蛋白质在肠道的消化不必进行到游离氨基酸阶段，部分肽段可完整通过肠壁进入血液；当体内蛋白酶受抑制或缺失时，甚至少量蛋白质也可直接吸收进入血液，从而引起食物蛋白过敏。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"e7fc3bda","s":"b","g":"b13","n":"乳糜泻","e":"Celiac disease","d":"指一种因消化酶不能分解小麦面粉中的水不溶性蛋白而引起的疾病，该蛋白称麦角蛋白（醇溶朊或麸朊，gliadin）。先天免疫性障碍造成对小肠黏膜的炎症和萎缩，对肠衬细胞产生不利作用，引起体腔（腹腔）疾病，即麸质敏感性肠病。患者摄入麸质后诱发免疫性炎症，导致小肠绒毛萎缩，活检可见黏膜变平；同时体内形成针对麸质及其组分麦胶蛋白的抗体和自身抗体，故本病属免疫介导的肠道疾病，而非单纯的消化吸收不良。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"59acbadf","s":"b","g":"b13","n":"急性胰腺炎","e":"Acute pancreatitis","d":"指胰液分泌到肠内的分泌途径发生障碍所致的疾病。此时蛋白水解酶的酶原预先成熟、转变为催化的活性形式，这些活性水解酶在胰腺细胞内攻击自身组织，损伤器官。病情严重时可致命，死亡率为20%，有并发症者可达50%。正常情况下胰腺分泌的蛋白酶均以无活性酶原形式存在，胰液中还有胰蛋白酶抑制剂保护胰腺免受自身消化；酶原在腺内提前激活即破坏这一保护机制，故急性胰腺炎本质上是自身消化的结果。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"9955c64f","s":"b","g":"b13","n":"腐败作用","e":"Putrefaction","d":"指肠道细菌对未被消化的蛋白质及蛋白质的消化产物所起的作用。其一是胺类的生成：细菌蛋白酶把蛋白质分解为氨基酸，氨基酸再脱羧基生成胺类，如组氨酸生成组胺、赖氨酸生成尸胺、色氨酸生成色胺、酪氨酸生成酪胺、苯丙氨酸生成苯乙胺。其二是氨的生成，来源为未被吸收的氨基酸在肠菌作用下脱氨基，以及血中尿素渗入肠道被肠菌尿素酶水解。腐败作用还产生苯酚、吲哚、甲基吲哚、硫化氢等有害物质。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"7dfb11ce","s":"b","g":"b13","n":"脱氨基作用","e":"Deamination","d":"指氨基酸失去氨基的作用，包括氧化脱氨和非氧化脱氨两类：前者在动、植物中普遍存在，后者见于微生物中，不普遍。氨基酸的脱氨基作用由氨基酸氧化酶催化，总反应为2分子氨基酸与O2生成2分子α-酮酸和2分子NH3。动物的脱氨主要发生在肝脏中。生成的α-酮酸可进入TCA氧化供能，也可转变为糖或酮体；释出的氨进入氨的转运与尿素合成，故脱氨基作用是氨基酸分解代谢的中心环节。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"d2d66de2","s":"b","g":"b13","n":"L-谷氨酸脱氢酶","e":"L-Glutamate dehydrogenase","d":"指催化L-谷氨酸氧化脱氨的酶，反应为L-Glu+NAD(P)+⇌α-酮戊二酸+NH3+NAD(P)H+H+。该酶分布广、活力高，是氨基酸氧化脱氨的关键酶。味精生产所用发酵菌的L-谷氨酸脱氢酶活力非常高，可利用糖代谢的中间产物α-酮戊二酸发酵生产味精，所需NADPH来自异柠檬酸脱氢。GTP是该酶的变构抑制剂。它催化生成的α-酮戊二酸可接受其他氨基酸的氨基，故在联合脱氨中处于中心地位。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"6202b344","s":"b","g":"b13","n":"转氨基作用","e":"Transamination","d":"指转氨酶催化的反应：一个L-氨基酸的α-氨基转移到α-酮酸上，使之变成相应的α-氨基酸，而原来的氨基酸转变为相应的α-酮酸。转氨酶均以磷酸吡哆醛为辅基。Lys、Arg、Thr、Pro不能通过转氨酶转氨。重要的转氨酶有GPT（催化Glu与丙酮酸生成Ala与α-酮戊二酸）和GOT（催化Glu与草酰乙酸生成Asp与α-酮戊二酸）。转氨作用只转移氨基、不产生游离氨，是联合脱氨的组成步骤。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"02d6ea0d","s":"b","g":"b13","n":"联合脱氨作用","e":"United deamination","d":"指氨基酸脱氨通过转氨作用和L-谷氨酸脱氢酶催化的L-谷氨酸氧化脱氨作用联合完成的脱氨方式。氨基酸先在转氨酶作用下把氨基转移给α-酮戊二酸生成谷氨酸，谷氨酸再经L-谷氨酸脱氢酶氧化脱氨释出氨，同时再生α-酮戊二酸。这种方式弥补了L-氨基酸氧化酶分布少、活力低的缺陷，在体内广泛存在，但并不是所有组织细胞的主要脱氨方式；骨骼肌、心肌等组织则以嘌呤核苷酸循环进行联合脱氨。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"057deb73","s":"b","g":"b13","n":"嘌呤核苷酸循环","e":"Purine nucleotide cycle","d":"指一种通过嘌呤核苷酸的相互转变完成脱氨的方式：次黄嘌呤核苷一磷酸（IMP）与Asp形成腺苷酸代琥珀酸，再经裂合酶分解产生AMP和延胡索酸，AMP在腺苷酸脱氨酶作用下生成NH3和IMP，从而把氨基酸的氨基以氨的形式释出。该循环是骨骼肌、心肌、肝脏及脑中主要的脱氨方式。循环中生成的延胡索酸是TCA的中间产物，故该循环与三羧酸循环通过共同中间物相联系，其延胡索酸也是三羧酸循环的成分。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"90755c86","s":"b","g":"b13","n":"脱羧基作用","e":"Decarboxylation","d":"指氨基酸在脱羧酶催化下生成相应一级胺并放出CO2的反应，需要磷酸吡哆醛为辅基。脱羧酶作用专一性很高，一般一种氨基酸只有一种脱羧酶，且只对L-型氨基酸起作用，只有His脱羧酶不需要辅酶。例如组氨酸脱羧生成组胺（降血压、刺激胃酸分泌），酪氨酸脱羧生成酪胺（升高血压），谷氨酸脱羧生成γ-氨基丁酸（神经介质，强神经抑制性氨基酸，具镇静、催眠、抗惊厥、降血压作用），故脱羧产物多为有生理活性的胺类。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"634a2d65","s":"b","g":"b13","n":"谷氨酰胺合成酶","e":"Glutamine synthetase","d":"指催化NH3+Glu+ATP生成Gln、ADP和Pi的酶，多数动物细胞都含有。它把有毒的游离氨与谷氨酸结合生成无毒的谷氨酰胺，因而是氨转运的主要形式：谷氨酰胺随血液运送到肝脏或肾脏，再由谷氨酰胺酶催化其水解，释放NH4+。该酶与谷氨酰胺酶配合，完成氨从外周组织到肝、肾的运输。脑组织也以谷氨酸与氨生成谷氨酰胺的方式解除氨的毒性，故该反应是机体重要的解氨毒途径之一。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"2ec1e9c6","s":"b","g":"b13","n":"丙氨酸-葡萄糖循环","e":"Glucose-alanine cycle","d":"指肌肉把氨运送到肝脏的途径。肌肉中氨在谷氨酸脱氢酶作用下转变为谷氨酸，再在GPT作用下把氨基转移给丙酮酸生成丙氨酸；丙氨酸随血液运送到肝脏，在肝脏GPT作用下转回丙酮酸和谷氨酸，氨进入尿素合成。肌肉中的丙酮酸由糖酵解提供，肝脏中的丙酮酸可异生为葡萄糖，葡萄糖再随血液回到肌肉被利用，循环因此得名，其实质是肌肉与肝脏之间氨与碳架的交换，氨以丙氨酸的形式被运输而不以游离氨出现。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"e6bb751e","s":"b","g":"b13","n":"尿素循环","e":"Urea cycle","d":"指氨基酸代谢产生的氨在肝脏中代谢为尿素解毒的途径，又称鸟氨酸循环或Krebs-Henseleit循环，由Hans Krebs和Kurt Henseleit于1932年发现，其实现必须有精氨酸酶水解精氨酸为尿素。循环经五步反应：氨甲酰磷酸合成酶I（CPS-I）合成氨甲酰磷酸；鸟氨酸转氨甲酰酶（OTC）生成瓜氨酸；精氨琥珀酸合成酶生成精氨琥珀酸；精氨琥珀酸裂解酶生成精氨酸和延胡索酸；精氨酸酶水解精氨酸生成尿素并再生鸟氨酸。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"4ed55af8","s":"b","g":"b13","n":"氨甲酰磷酸合成酶I Carbamoyl phosphate synthetase I","e":"","d":"指尿素循环的第一个酶，简写CPS-I，催化CO2与氨合成氨甲酰磷酸，为循环的限速步骤。该酶被N-乙酰谷氨酸变构激活：N-乙酰谷氨酸合成酶缺陷时缺乏CPS-I的激活剂，可用N-乙酰谷氨酸的类似物氨甲酰谷氨酸治疗，以激活其活性。尿素循环的五个酶在饥饿动物和高蛋白质食物动物的肝脏中合成速率更高，尿素产生增多；缺乏蛋白质食物时循环活性低，尿素生成少，故CPS-I是尿素循环调节的关键酶。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"9b475ac5","s":"b","g":"b13","n":"血氨的来源与去路","e":"Sources and fate of blood ammonia","d":"指血氨的来源与去除途径。来源有三：氨基酸脱氨基作用产生的氨是血氨的主要来源，胺类的分解也可产生氨；肠道吸收的氨；肾小管上皮细胞分泌的氨，主要来自谷氨酰胺。去路有四：在肝内合成尿素是最主要的去路；合成非必需氨基酸及其他含氮化合物；合成谷氨酰胺；肾小管泌氨，分泌的NH3在酸性条件下生成NH4+随尿排出。氨清除不足或氨产生过多均可使血氨升高，据此可分析高血氨症的成因。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"3b2f806c","s":"b","g":"b13","n":"肝昏迷","e":"Hepatic coma","d":"指肝脏病变不能解除氨基酸代谢产生的氨的毒性所引起的昏迷。氨一般在脑中与谷氨酸形成谷氨酰胺而解毒，谷氨酸用于解毒须消耗TCA的中间产物α-酮戊二酸，导致TCA中间产物流失，阻滞TCA的进行，影响脑中能量代谢，造成昏迷。氨对脑组织的毒性还表现为干扰脑组织的能量代谢使ATP减少、使脑内神经递质改变（兴奋性递质谷氨酸、乙酰胆碱减少，抑制性递质γ-氨基丁酸、谷氨酰胺增多）以及抑制神经细胞膜上Na+、K+-ATP酶的活性。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"c9f1c9c8","s":"b","g":"b13","n":"生糖氨基酸","e":"Glycogenic amino acids","d":"指分解产物为糖代谢中间物的氨基酸。这些中间物除乙酰CoA外，包括丙酮酸、草酰乙酸、α-酮戊二酸、延胡索酸等，可经糖异生转变为糖，故称生糖氨基酸。人体20种氨基酸中有18种属于生糖氨基酸。氨基酸碳架的氧化产物还可进入TCA彻底氧化，人体10%~15%的能量可来自氨基酸的氧化分解，因此生糖氨基酸既参与糖异生，也为机体供能；把20种氨基酸分为生糖、生酮和生糖生酮三类。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"c61e59d0","s":"b","g":"b13","n":"生酮氨基酸","e":"Ketogenic amino acids","d":"指分解产物为乙酰CoA或乙酰乙酸的氨基酸，因其碳架可生成酮体而得名。属于此类的有亮氨酸、赖氨酸、苯丙氨酸、酪氨酸、色氨酸、异亮氨酸和苏氨酸。其中赖氨酸和亮氨酸是绝对生酮的氨基酸，即分解产物只生成酮体而不生成糖。生酮氨基酸的碳架不能净生成葡萄糖，在饥饿时可生成酮体供肝外组织利用，这些氨基酸分解生成的乙酰CoA不能异生为糖，故只生酮而不生糖，其性质与生糖氨基酸相对。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"68714950","s":"b","g":"b13","n":"生糖生酮氨基酸","e":"Glucogenic and ketogenic amino acids","d":"指分解产物既可生成糖代谢中间物、又可生成乙酰CoA或乙酰乙酸的氨基酸，包括异亮氨酸、苏氨酸、苯丙氨酸、酪氨酸和色氨酸。它们的碳架在分解时一部分转变为糖异生的前体，另一部分生成酮体，故兼具生糖和生酮两种性质。与它们相对，赖氨酸和亮氨酸为绝对生酮氨基酸；全部20种氨基酸中除这两种以外均可生糖，故生糖生酮氨基酸同时也是生糖氨基酸，既能作为糖异生前体，也能生成酮体。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"0fd52791","s":"b","g":"b13","n":"氨基酸碳架的氧化","e":"Oxidation of amino acid carbon skeletons","d":"指氨基酸脱去氨基后其碳架被氧化供能的途径。人体10%~15%的能量可来自于氨基酸的氧化分解。氨基酸的碳架以丙酮酸或乙酰CoA、α-酮戊二酸、琥珀酰CoA、延胡索酸、草酰乙酸等形式进入三羧酸循环，彻底氧化为H2O和CO2。这些中间物还可用于糖异生、生酮或生脂，因此氨基酸代谢与糖代谢、脂代谢通过TCA的中间产物相互联系，是三大物质代谢的交汇点之一，也是氨基酸能替代部分糖供能的原因。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"73cc5df3","s":"b","g":"b13","n":"一碳单位","e":"One carbon unit","d":"指一些氨基酸在代谢过程中产生的含一个碳原子的基团，这种基团参与生物合成反应，被称为一碳单位（C1单位或OCU）。一碳单位生成和转移的代谢称为一碳代谢。生物体的一碳单位有甲基（-CH3）、甲烯基（亚甲基，-CH2）、甲炔基（-CH=）、甲酰基（-CHO）、亚氨甲基（-CH=NH）等形式。它们由Gly、Ser、Thr、His、Trp等氨基酸的代谢产生，在体内参与多种生物合成反应。","src":"第11讲 蛋白质降解与氨基酸代谢 I"},{"id":"28fb36a6","s":"b","g":"b13","n":"谷氨酰胺酰胺基转移酶","e":"Glutamine amidotransferase","d":"指催化酰胺氨基转移的一类酶，是氨基酸和核苷酸生物合成中十余种反应所用生理氨基的主要来源。该酶都含有两个结构功能域：一个结合谷氨酰胺，另一个结合另一个底物即氨基受体；谷氨酰胺结合域含有一定的结构元素，包括一个活性必须的Cys。作用时谷氨酰胺的酰胺氮以氨的形式释放，氨基受体有两类，X代表一个激活基团，通常是由ATP过来的磷酸基团，可促进氨基替代R-OH的羟基基团。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"317e703f","s":"b","g":"b13","n":"必需氨基酸","e":"Essential amino acids","d":"指体内需要而又不能自身合成、必须由食物供给的氨基酸。共有八种：赖氨酸、色氨酸、苯丙氨酸、蛋氨酸、苏氨酸、亮氨酸、异亮氨酸及缬氨酸，其余12种氨基酸体内可以合成，称非必需氨基酸。以谐音句\"笨蛋来宿舍亮一亮鞋\"\"假设来写一两本书\"助记，并把Met、Trp、Lys、Val、Ile、Leu、Phe、Thr依次对应。哺乳动物只能以简单方式合成其中大约一半的氨基酸，其他必须由食物中摄取。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"e5c0102f","s":"b","g":"b13","n":"非必需氨基酸","e":"Non-essential amino acids","d":"指体内可以自身合成、不必由食物供给的氨基酸。20种氨基酸中除八种必需氨基酸以外的其余12种属此类，哺乳动物只能以简单的方式合成其中大约一半的氨基酸，即非必需氨基酸。就来源而言，所有氨基酸合成的碳架都来自EMP、TCA或PPP的中间产物，氨基（氮）通过谷氨酸或谷氨酰胺进入合成途径；不同生物合成20种氨基酸的能力差异极大，大多数细菌和植物可合成全部20种。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"9a6d51f0","s":"b","g":"b13","n":"氨基酸生物合成的分族","e":"Amino acid biosynthetic families","d":"指按合成碳架前体把氨基酸划分为若干家族的方式。六族：丙氨酸族以丙酮酸为前体，包括Ala、Val、Leu；丝氨酸族以甘油酸-3-磷酸为前体，包括Ser、Gly、Cys；谷氨酸族以α-酮戊二酸为前体，包括Glu、Gln、Pro、Arg；天冬氨酸族以草酰乙酸为前体，包括Asp、Asn、Lys、Thr、Ile、Met；组氨酸以磷酸核糖为前体；芳香氨基酸族以磷酸赤藓糖加PEP为前体，包括Phe、Tyr、Trp。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"f12d403e","s":"b","g":"b13","n":"分支酸","e":"Chorismate","d":"指Trp、Phe及Tyr合成的关键中间物，是细菌和植物中芳香族氨基酸合成途径的分支点。环境中并没有现成的芳香环，芳香环的形成是一条重要的生物学途径，涉及脂肪族前体的环化及双键添加：前4步由4-磷酸赤藓糖和PEP形成莽草酸，后者经3步反应转变为分支酸，再由分支酸分别走向三种芳香族氨基酸。苯环虽非常稳定，微生物和植物仍能从头构建，故分支酸被视为该族的枢纽。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"54a69d1a","s":"b","g":"b13","n":"槭糖尿病","e":"Maple syrup urine disease","d":"指一种遗传性疾病，由三个支链氨基酸分解代谢障碍所致。患者智力发育不全，尿中出现三个支链氨基酸及其相应的酮酸，尿液呈焦糖味，每22.5万人中约有一例发生。病因是先天缺乏α-酮酸脱羧酶（也叫dHE），该酶催化α-酮酸的氧化脱羧，而支链氨基酸生成酮酸后只有氧化脱羧这一条途径可走，故酮酸在体内累积并随尿排出，该反应需要TPP参加。其治疗困难，膳食上应低蛋白、尽量减少支链氨基酸摄入。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"208feed1","s":"b","g":"b13","n":"5-羟色胺","e":"5-Hydroxytryptamine","d":"指以Trp为前体生成的一种生物活性物质，属氨基酸来源的小分子信使，同时列出\"血清素\"\"血管收缩素\"两个名称。血清素是神经细胞之间相互通信的化学信号分子，有助于镇定情绪、解除焦虑。Trp合成5-羟色胺与合成吲哚乙酸并列展示，作为色氨酸的两条代谢去向；在\"氨基酸来源的生物活性物质\"一图中，5-羟色胺与组胺、多胺、GABA、牛磺酸等一同被列为氨基酸的代谢产物。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"9406802e","s":"b","g":"b13","n":"苯丙酮尿症","e":"Phenylketonuria","d":"指一种先天性氨基酸代谢缺陷病，因先天缺乏苯丙氨酸羟化酶（Phe hydroxylase）所致。患者血及尿中苯丙氨酸及苯丙酮酸浓度高，智力低下，多停留在儿童阶段，肤发颜色较浅，血中肾上腺素也低。正常情况下Phe羟化为Tyr，酶缺陷时Phe改走生成苯丙酮酸的道路并在体内堆积。其列为影响氨基酸代谢的人类遗传疾病之一，与黑尿症、白化病同属芳香族氨基酸代谢障碍。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"e34a34e6","s":"b","g":"b13","n":"黑尿症","e":"Alkaptonuria","d":"指一种先天性代谢疾病，属芳香族氨基酸分解代谢障碍，1902年由英国医生加罗德发现，是年代标注最早的氨基酸代谢病，标题括号中将其注为\"苯丙酮尿症\"。其病因是缺乏黑尿酸氧化酶：Phe、Tyr分解为乙酰乙酸的途径依次经过黑尿酸与马来酰乙酰乙酸，黑尿酸氧化酶负责使黑尿酸继续向下游转变，酶缺陷时该中间物不能顺利代谢。它与苯丙酮尿症、白化病并列，作为芳香族氨基酸代谢障碍所致人类遗传病的代表性实例。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"68797e78","s":"b","g":"b13","n":"白化病","e":"Albinism","d":"指因缺乏酪氨酸酶（Tyr 3-单氧酶，Tyrosinase）而使Tyr不能生成黑色素所致的疾病。Phe、Tyr代谢部分依次列出苯丙酮尿症、黑尿症与白化病三种酶缺陷病。Tyr合成黑色素、多巴的途径与白化病对照展示：酪氨酸经酪氨酸酶催化羟化为多巴，再经多巴醌等步骤生成黑色素，酶缺陷时该途径中断，黑色素不能形成。白化病与苯丙酮尿症、黑尿症并列，同列为芳香族氨基酸代谢异常引起的人类遗传疾病。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"8bb89068","s":"b","g":"b13","n":"酪氨酸酶家族","e":"Tyrosinase family","d":"指一系列酪氨酸酶基因家族成员，除酪氨酸酶外还包括酪氨酸酶相关蛋白TRP-1、TRP-2和Pmel 17。TRP-1又称DHICA氧化酶，有一个跨膜结构域，仅参与真黑色素生成，不参与黑色素的形成；TRP-2为多巴色素互变异构酶，同样有一个跨膜结构域，也仅参与真黑色素生成；Pmel 17/gp100是TRP家族一员，有一个跨膜结构，催化DHICA转变为黑色素。三者与酪氨酸酶共同参与黑色素的生成。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"653f0d84","s":"b","g":"b13","n":"酪氨酸酶","e":"Tyrosinase","d":"指催化黑色素生成限速反应的酶，是黑色素细胞的标记，基因位点位于11q14-21。它为67 kDa的糖蛋白，因糖基化方式不同有4个同工酶：T1和T2可溶，T3有90%的酪氨酸酶活性、不溶、与内质网和高尔基膜结合，T4与黑色素体结合。辅助因子为Cu2+，每个分子2个原子，底物之一为多巴。它催化至少3步反应：甲苯酚酶（单酚酶）活性羟化酪氨酸形成多巴，儿茶酚酶（二酚酶）活性氧化多巴形成多巴醌，以及5,6-二羟吲哚生成吲哚-5,6-醌。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"7aa8bc60","s":"b","g":"b13","n":"组胺","e":"Histamine","d":"指由His合成的一种生物活性物质，是一种强烈的血管舒张剂，能增加毛细血管的通透性，可引起血压下降和局部水肿。组胺的释放与过敏反应密切、症状相关；它还可刺激胃蛋白酶和胃酸分泌，常被用于胃分泌功能研究。以\"His合成组胺\"为题，说明组氨酸是组胺在体内的直接前体。在\"氨基酸来源的生物活性物质\"中，组胺与5-羟色胺、多胺、GABA、牛磺酸并列，其效应以扩张血管与促进胃液分泌为主。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"cae056d5","s":"b","g":"b13","n":"多胺","e":"Polyamines","d":"指鸟氨酸合成的一类含多个氨基的化合物，包括腐胺、亚精胺和精胺，三者均带多个氨基。多胺存在于精液和细胞核糖体中，是调节细胞生长的重要物质；多胺带有较多正电荷，能与DNA和RNA结合并稳定它们的结构。生长旺盛的组织如胚胎、再生肝和癌组织中含量较高，故可用血或尿中多胺含量作为临床肿瘤诊断的辅助指标。鸟氨酸合成多胺列为氨基酸生成生物活性物质的实例之一，与腐胺、亚精胺、精胺三种成分并列。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"87fa4647","s":"b","g":"b13","n":"GABA γ-氨基丁酸","e":"","d":"指由Glu合成的一种神经传导物质，即γ-氨基丁酸。GABA是一种使大脑细胞之间的信息传递达到最优化所必需的传导物质，具有抑制有害的大脑信号的作用；老年人语言能力、视力及身体灵活性下降等老年疾病，原因可能在于其大脑无法得到足够量的GABA。此外，给老猴子大脑施与微量GABA，可使其大脑功能恢复至年轻猴子的正常水平，提示其与抗衰老有关。\"Glu合成GABA\"列在Glu的代谢去向中。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"7016c49a","s":"b","g":"b13","n":"牛磺酸","e":"Taurine","d":"指Cys合成的氨基乙磺酸，又称牛胆碱或牛胆素，属非蛋白质氨基酸，以游离形式存在或与胆汁酸形成复合物。它主要分布在兴奋性较高的组织，如神经系统、肌肉组织、视网膜及淋巴细胞和血小板中；主要由食物供给，也可在体内合成，大量摄取未见任何副作用。其为婴幼儿生长发育所必需，对心血管系统有较强的保护作用，可促进脂肪乳化，对视网膜及神经系统有益；缺乏时可出现生长及发育迟缓、视网膜功能紊乱等。","src":"第12讲 蛋白质降解与氨基酸代谢 II"},{"id":"b558d728","s":"b","g":"b14","n":"核酸酶","e":"Nuclease","d":"指作用于核酸磷酸二酯键的水解酶，包括核糖核酸酶（RNase）和脱氧核糖核酸酶（DNase）。其中能水解核酸分子内磷酸二酯键的酶又称为核酸内切酶，从核酸的一端逐个水解下核苷酸的酶称为核酸外切酶。在食物核酸的消化中，核酸在小肠被胰核酸酶（含DNase、RNase）降解为嘌呤核苷酸、嘧啶核苷酸和寡核苷酸，肠黏膜释放的磷酸二酯酶协同胰核酸酶将其水解为单核苷酸，故核酸酶在功能上属磷酸二酯酶类。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"ef73d871","s":"b","g":"b14","n":"核苷磷酸化酶","e":"Nucleoside phosphorylase","d":"指催化核苷磷酸解的一类酶，反应为核苷加无机磷酸生成嘌呤碱或嘧啶碱与1-磷酸戊糖（Ns+Pi⇌Pu or Py+pentose-1-P）。该酶广泛存在，反应可逆。与之并列的是核苷水解酶，后者分布局限，只对核糖核苷起作用。核苷酸先由磷酸单酯酶（核苷酸酶）水解为核苷，再由核苷磷酸化酶或核苷水解酶进一步分解，释出碱基与戊糖，完成核苷酸的分解代谢，故该酶催化的是核苷酸分解的第二步。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"55cd20ff","s":"b","g":"b14","n":"核苷水解酶","e":"Nucleoside hydrolase","d":"指催化核苷水解的酶，反应为核苷加水生成嘌呤碱或嘧啶碱与戊糖（Ns+H2O⇌Pu or Py+pentose）。其分布局限，存在于植物和微生物中，只对核糖核苷起作用，对脱氧核糖核苷不作用。它与核苷磷酸化酶同属催化核苷水解的两类酶，区别在于前者直接水解、后者以磷酸解方式进行且广泛存在、反应可逆。核苷酸分解时，碱基与戊糖即由这两类酶释出，供机体重新利用或排出。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"715e1e0c","s":"b","g":"b14","n":"嘌呤碱的脱氨基作用","e":"Deamination of purine bases","d":"指嘌呤碱分解时首先脱去氨基的反应，可在嘌呤、核苷或核苷酸三个水平上进行。动物组织腺嘌呤脱氨酶含量极少，而腺嘌呤核苷脱氨酶及腺嘌呤核苷酸脱氨酶的活性较高，因此腺嘌呤的脱氨基作用主要在核苷或核苷酸水平上进行；鸟嘌呤脱氨酶分布广，其脱氨基作用主要在碱基水平进行。腺嘌呤、鸟嘌呤脱氨后分别生成次黄嘌呤和黄嘌呤，再进一步代谢生成尿酸，故脱氨是嘌呤碱分解代谢的第一步反应。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"c3ce511c","s":"b","g":"b14","n":"鸟嘌呤脱氨酶","e":"Guanine deaminase","d":"指催化鸟嘌呤脱氨分解的酶，催化鸟嘌呤生成黄嘌呤并释放氨。该酶分布较广，是鸟苷酸、鸟苷及鸟嘌呤主要的脱氨途径，即无论底物处在核苷酸、核苷还是碱基水平，鸟嘌呤的脱氨基最终都经由这一酶完成。与腺嘌呤主要靠核苷、核苷酸水平的脱氨酶不同，鸟嘌呤的脱氨主要在碱基水平进行，产物黄嘌呤随后在黄嘌呤氧化酶作用下氧化生成尿酸。鸟嘌呤脱氨与腺嘌呤在核苷、核苷酸水平的脱氨对照呈现，说明同一碱基的脱氨可在不同层次完成，而鸟嘌呤以碱基水平为主。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"a322485b","s":"b","g":"b14","n":"尿酸","e":"Uric acid","d":"指人和猿类及一些排尿酸的动物（鸟类、某些爬行类和昆虫）嘌呤代谢的终产物，分子量168。嘌呤核苷酸的分解代谢主要在肝脏、小肠及肾脏中进行，生理情况下嘌呤合成与分解相对平衡，尿酸生成与排泄也较恒定：正常男性平均149～416 μmol/L，女性平均89～357 μmol/L。体内核酸大量分解（白血病、恶性肿瘤等）或食入高嘌呤食物时血中尿酸升高，超过0.48 mM（8 mg/dL）时尿酸盐形成结晶。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"307af823","s":"b","g":"b14","n":"痛风","e":"Gout","d":"指嘌呤碱分解产生过多尿酸、尿酸盐结晶沉积于关节、软组织、软骨甚至肾脏等处所致的疾病。尿酸溶解性很差，易形成尿酸钠结晶，也可形成尿酸的尿路结石；沉积于男性关节腔的尿酸钠结晶被吞噬细胞吞噬后，通过氢键与溶酶体膜作用破坏溶酶体，释放的水解酶及蛋白因子使局部生成较多致炎物质，引起痛风性关节炎。诊断最简便而有价值的检查是血尿酸测定，男性大于416 μmol（7 mg/dL）、女性大于357 μmol（6 mg/dL）应考虑痛风。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"b93c82c1","s":"b","g":"b14","n":"黄嘌呤氧化酶","e":"Xanthine oxidase","d":"指催化次黄嘌呤和黄嘌呤氧化生成尿酸的酶。其为复合黄素酶，由两个相同的亚基组成，分子量260 000，每个亚基含一个FAD、一个钼原子和一个Fe4S4中心；进入尿酸的氧来自水。底物与酶结合后Mo(VI)被还原为Mo(IV)，电子经黄素、铁硫中心等传给O2，反应要求分子氧作为电子受体，与氢离子生成H2O2，Mo(IV)再氧化为Mo(VI)。该酶是别嘌呤醇等抗痛风药物的作用靶点。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"a708c768","s":"b","g":"b14","n":"别嘌呤醇","e":"Allopurinol","d":"指一种抗痛风药物，其作用机理有两条：一是竞争性抑制黄嘌呤氧化酶，阻止尿酸生成；二是与PRPP结合生成别嘌呤醇核苷酸，消耗PRPP，别嘌呤醇核苷酸反馈抑制嘌呤核苷酸的从头合成，从而抑制嘌呤核苷酸的合成。其结构与次黄嘌呤相似，在黄嘌呤氧化酶作用下氧化为别黄嘌呤，后者与酶中心的Mo(IV)牢固结合，使Mo(IV)不易转变成Mo(VI)，成为酶的灭活物。常用抗痛风药物还有秋水仙碱、丙磺舒、苯溴马隆等。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"27972bf8","s":"b","g":"b14","n":"自杀底物","e":"Suicide substrate","d":"指结构与天然底物相似、经酶催化后转变为能与酶牢固结合并使酶失活的物质，这种底物类似物称为自杀作用（底）物，这一作用称为自杀作用。以别嘌呤醇为例：它与次黄嘌呤结构相似，在黄嘌呤氧化酶作用下氧化为别黄嘌呤，后者与酶中心的Mo(IV)牢固结合，使Mo(IV)不易转变成Mo(VI)而成为酶的灭活物。别嘌呤醇还可与PRPP作用生成相应核苷酸，抑制PRPP-AT，使IMP合成减少。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"c7a71ccd","s":"b","g":"b14","n":"补救途径","e":"Salvage pathway","d":"指由现成的嘌呤碱、嘧啶碱、戊糖及磷酸在酶的作用下直接合成核苷酸的途径，与全程合成是两条完全不同的途径，其主要存在于脑、骨髓。就嘌呤核苷酸而言，利用现成的腺嘌呤、次黄嘌呤和鸟嘌呤，通过腺嘌呤磷酸核糖基转移酶（APRT）及次黄嘌呤-鸟嘌呤磷酸核糖基转移酶（HGPRT）实现AMP、IMP、GMP的补救合成。该途径的特点是不必从头构建嘌呤或嘧啶环；人体细胞大多为全程合成，但脑和骨髓中几乎只能通过补救途径合成。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"28e6dd73","s":"b","g":"b14","n":"全程合成","e":"De novo synthesis","d":"指由磷酸戊糖先和非嘌呤或嘧啶环结合，在未完成的环上添加必要的部分，然后闭合成环的核苷酸合成途径，又称从头合成，其主要在肝脏、小肠、胸腺进行。嘌呤核苷酸的全程合成以5-磷酸核糖、ATP、Gln、Asp、GTP、N5,N10-亚甲基四氢叶酸和CO2为原料，另需Mg2+、Mn2+、NAD+、THFA-CHO等辅助因子，先生成IMP，继而合成AMP和GMP。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"8582aeb6","s":"b","g":"b14","n":"羽田杀菌素","e":"Hadacidin","d":"指一种具有抗癌作用的抗菌素，为Asp的结构类似物，即N-羟-N-甲酰甘氨酸。它可强烈抑制腺苷琥珀酸合成酶的活性，阻止腺苷琥珀酸的合成，从而抑制AMP的合成；该酶催化IMP与Asp缩合生成腺苷琥珀酸，是AMP合成的关键步骤。羽田杀菌素具有抗癌活性，对腺苷琥珀酸合成酶也有作用，但没有用于临床，属嘌呤核苷酸合成途径中以Asp为原型设计的氨基酸类似物类抗代谢物，该途径的其余抗代谢物还有Gln类似物与叶酸类似物。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"1611040a","s":"b","g":"b14","n":"HGPRT","e":"","d":"指次黄嘌呤-鸟嘌呤磷酸核糖基转移酶，是嘌呤核苷酸补救合成的关键酶，与APRT共同利用现成的嘌呤碱合成核苷酸。HGPRT催化次黄嘌呤、鸟嘌呤与PRPP反应，分别生成IMP和GMP；APRT则催化腺嘌呤生成AMP。人体细胞大多为全程合成，但脑和骨髓中几乎只能通过补救途径合成，故脑与骨髓的核苷酸供应依赖该酶。HGPRT缺陷的男性儿童表现为自毁容貌综合症。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"71b5b9a5","s":"b","g":"b14","n":"莱-纳二氏综合症","e":"Lesch-Nyhan syndrome","d":"指因HGPRT缺陷所致的先天性遗传疾病，又称自毁容貌综合症，患者多为男性儿童。表现为一种强制性的自残行为，行为对立、侵略性强，自咬手指、脚趾、嘴唇等，并伴智力低下。其分子基础是HGPRT基因的点突变，使嘌呤核苷酸补救合成受阻。以HGPRT基因点突变示意其分子缺陷。该病是嘌呤核苷酸补救合成途径缺陷的典型代表，它与痛风并列，作为嘌呤核苷酸代谢异常的两类代表性病症。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"91ca63c5","s":"b","g":"b14","n":"抗代谢药物","e":"Antimetabolic agents","d":"指主要是一些嘌呤、氨基酸或叶酸等的类似物，采用竞争性抑制或\"以假乱真\"等方式抑制合成代谢中的酶，干扰和阻断核苷酸的合成，从而进一步阻止核酸以及蛋白质生物合成的一类药物。肿瘤细胞的核酸与蛋白质代谢旺盛，因此抗代谢物可用于肿瘤的化疗。按其靶位可分为抑制Gln转酰胺酶者（重氮丝氨酸、阿西维辛）、抑制胸苷酸合成酶和二氢叶酸还原酶者（氟尿嘧啶、甲氨蝶呤、氨基蝶呤）以及嘌呤或嘧啶核苷酸类似物。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"23b58bca","s":"b","g":"b14","n":"6-巯基嘌呤","e":"6-Mercaptopurine","d":"指一种嘌呤类似物类抗代谢药物，结构与次黄嘌呤相似。其在体内转变为6-MP核苷酸，即IMP的类似物，反馈抑制IMP从头合成中PRPP与5-磷酸核糖胺的形成；同时抑制从头合成中IMP向AMP和GMP的转变，并抑制补救合成中的HGPRT，故可用作抗癌药物。6-巯基嘌呤与8-氮杂鸟嘌呤、6-巯基鸟嘌呤同列为嘌呤类似物，说明其以竞争性抑制或\"以假乱真\"的方式干扰核苷酸合成。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"18ff0319","s":"b","g":"b14","n":"氮杂丝氨酸","e":"Azaserine","d":"指一种氨基酸类似物类抗代谢物，化学结构与Gln相似，可干扰谷氨酰胺转酰胺酶在嘌呤核苷酸合成中的作用，从而抑制嘌呤核苷酸的合成。其归入抑制有谷氨酰胺参与的反应、干扰全程合成的一类，并注明其又称重氮乙酰丝氨酸，与6-重氮-5-氧正亮氨酸同属Gln类似物。它由链丝菌属形成，属抗菌素类；此外，它可经呼吸道伤害人体，引起食欲降低、恶心、呕吐和腹泻，并伤害肝脏，是致癌物。","src":"第13讲 核酸降解与核苷酸代谢 I"},{"id":"3de2c667","s":"b","g":"b14","n":"氨甲酰磷酸合成酶II Carbamoyl phosphate synthetase II","e":"","d":"指在嘧啶核苷酸从头合成中催化氨甲酰磷酸生成的酶，反应为谷氨酰胺加水加CO2加2ATP生成氨甲酰磷酸、谷氨酸、2ADP和Pi，即以谷氨酰胺为氮供体。其与CPS-I对照列出，二者是两种不同的氨甲酰磷酸合成酶。生成的氨甲酰磷酸随后与Asp缩合为氨甲酰Asp，再经二氢乳清酸酶、二氢乳清酸脱氢酶催化形成乳清酸。动物细胞中嘧啶核苷酸合成主要受CPS-II调控，UTP抑制其活性，ATP和PRPP为激活剂。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"af18e388","s":"b","g":"b14","n":"乳清酸","e":"Orotic acid","d":"指嘧啶核苷酸从头合成中形成的第一个嘧啶环化合物：氨甲酰磷酸先与Asp缩合成氨甲酰Asp，再经二氢乳清酸酶环化、经二氢乳清酸脱氢酶脱氢而生成乳清酸。乳清酸随后经乳清酸磷酸核糖基转移酶接上PRPP生成乳清苷酸，再由乳清苷酸脱羧酶脱羧生成UMP，由此走向UTP和CTP。乳清酸的生成与\"乳清酸经乳清苷酸合成UMP\"分为嘧啶合成的两个阶段。尿中排出大量乳清酸是乳清酸尿症的主要表现。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"bb5d554d","s":"b","g":"b14","n":"天冬氨酸氨甲酰转移酶","e":"Aspartate transcarbamoylase","d":"指细菌嘧啶核苷酸合成调节中的关键酶，催化氨甲酰磷酸与天冬氨酸缩合生成氨甲酰Asp。细菌ATCase分子由6个催化亚基和6个调节亚基组成，催化亚基与底物分子结合，调节亚基与变构调节物CTP结合。整个酶分子有两种构象即活性形式和非活性形式：CTP未与调节亚基结合时酶活性最大；CTP积累并与调节亚基结合时，调节亚基构象改变并带动催化亚基构象改变，酶变为无活性形式，故CTP对其有反馈抑制作用。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"cccd7efb","s":"b","g":"b14","n":"乳清酸尿症","e":"Orotic aciduria","d":"指一种遗传性疾病，主要表现是尿中排出大量乳清酸、生长迟缓和重度贫血。病因是催化嘧啶核苷酸从头合成反应的乳清酸磷酸核糖基转移酶和乳清苷酸脱羧酶存在缺陷，使乳清酸不能转变为UMP而堆积排出。患儿尿中大量排出乳清酸是本病的标志性改变。临床用尿嘧啶或胞嘧啶治疗：尿嘧啶经磷酸化可生成UMP，抑制CPS-II活性，从而抑制嘧啶核苷酸的从头合成，减少乳清酸的生成。它是嘧啶核苷酸合成途径缺陷的代表性遗传病。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"23eb3575","s":"b","g":"b14","n":"嘧啶核苷酸的补救合成","e":"Salvage synthesis of pyrimidine nucleotides","d":"指利用现成的嘧啶碱合成嘧啶核苷酸的途径，与从头合成并列。两条路线：尿嘧啶在尿嘧啶磷酸化酶催化下与1-磷酸核糖反应生成尿苷，尿苷再由尿苷激酶催化、由ATP供能生成UMP；或尿嘧啶直接与PRPP反应，经UMP磷酸核糖基转移酶催化生成UMP并释放PPi。所生成的UMP可进一步转变为其他嘧啶核苷酸，是嘧啶核苷酸供应的补充方式。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"035a47df","s":"b","g":"b14","n":"核糖核苷酸还原酶","e":"Ribonucleotide reductase","d":"指催化核糖核苷酸还原为脱氧核糖核苷酸的酶，又称核糖核苷二磷酸还原酶。它使核糖分子还原为脱氧核糖，底物须先转化为二磷酸核苷酸水平，产物dNDP再经激酶作用形成dNTP。大肠杆菌和多数真核生物中为二聚体，由R1和R2亚基组成：R1含两种调节位点并提供两个活性必需的巯基，R2提供一个稳定的酪氨酸自由基，另有双核铁离子（Fe3+）辅助因子帮助产生并稳定该自由基。它是该转化过程的唯一酶，也是DNA合成和修复的关键酶。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"c4c7b88a","s":"b","g":"b14","n":"羟基脲","e":"Hydroxyurea","d":"指一种抗肿瘤药物，为Fe3+螯合剂及自由基清除剂，作用于核糖核苷酸还原酶。该酶的两个亚基都是二聚体，R1亚基每条肽链上都有核苷酸底物结合部位及效应物结合部位，R2亚基每条肽链含一个稳定的酪氨酰自由基参与催化，而该自由基的产生与Fe3+的存在关系密切。羟基脲通过螯合Fe3+，使R2亚基上的自由基不稳定，达到抑制还原酶活性的目的，干扰dNDP和dNTP的合成，进而抑制DNA合成。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"4a8b5588","s":"b","g":"b14","n":"胸苷酸的补救合成","e":"Salvage synthesis of dTMP","d":"指以现成的胸腺嘧啶为原料生成dTMP的途径，与全程合成并列。两步为：胸腺嘧啶与1-磷酸脱氧核糖在胸苷酸磷酸化酶催化下生成脱氧胸苷（dT）；dT再在dT激酶（TK）催化下由ATP供能生成dTMP和ADP。该途径与全程合成并列为dTMP生成的两条不同途径：前者以现成的胸腺嘧啶为起点，后者以dUMP为起点并经胸苷酸合成酶催化，故补救途径是胸腺嘧啶核苷酸供应的补充来源。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"0d7e383f","s":"b","g":"b14","n":"胸苷酸合成酶","e":"Thymidylate synthase","d":"指催化dUMP甲基化生成dTMP的酶，是胸苷酸全程合成的关键酶。全程合成途径以dUMP为原料，以N5,N10-亚甲基四氢叶酸为甲基供体，由胸苷酸合成酶催化生成dTMP。该酶与二氢叶酸还原酶并列为胸苷酸合成的两个关键酶，二者共同构成由dUMP合成dTMP的环节，也是设计抗肿瘤药物的靶位：氟尿嘧啶的活性形式F-dUMP可与之形成共价结合的三元复合物而使酶失活。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"1faddcf1","s":"b","g":"b14","n":"5-氟尿嘧啶","e":"5-Fluorouracil","d":"指一种重要的抗癌药物，在体内转变为5'-氟脱氧尿嘧啶核苷酸（F-dUMP），是dTMP的类似物，也是胸苷酸合成酶的自杀性抑制物。F-dUMP第六位C与胸苷酸合成酶的巯基结合，N5,N10-亚甲基FH4与F-dUMP的第五位C结合，形成一个共价结合的三元复合物，酶不能将F除去，干扰了尿嘧啶的甲基化，不能转变为dTMP，细胞不能合成DNA而死亡。临床可用于绒毛膜上皮癌、恶性葡萄胎、结肠癌、胃癌、乳腺癌、肝癌等。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"e8565d53","s":"b","g":"b14","n":"阿糖胞苷","e":"Cytarabine","d":"指一种嘧啶抗代谢药物，又称阿糖胞甙、阿糖胞嘧啶、胞嘧啶阿拉伯糖甙。它在细胞内先经脱氧胞苷酶催化磷酸化，转变为有活性的阿糖胞苷酸，进一步转化为二核苷酸和三核苷酸起作用：与dCTP竞争而抑制DNA聚合酶，干扰核苷酸掺入DNA；还能抑制核苷酸还原酶，阻止NDP转变为dNDP。不良反应为骨髓抑制、消化道反应，少数病人可有肝功能异常、发热和皮疹。生化机制分类中把它列为DNA多聚酶抑制剂。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"ac716745","s":"b","g":"b14","n":"环胞苷","e":"Ancitabine","d":"指一种抗肿瘤药物，又称环胞啶、环胞甙。它在体内被转化为阿糖胞苷，作用与阿糖胞苷相似，即通过转化为阿糖胞苷酸及其二、三核苷酸，与dCTP竞争而抑制DNA聚合酶，并抑制核苷酸还原酶、阻止NDP转变为dNDP。主要用于各类急性白血病，眼科用于治疗单纯疱疹病和毒性角膜炎。不良反应包括胃肠道反应、骨髓抑制（白细胞和血小板减少，严重时全血象抑制），少数病人有肝功能损害。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"85af7f38","s":"b","g":"b14","n":"核酸及核苷酸类药物","e":"Nucleic acid and nucleotide drugs","d":"指具有药用价值的核酸、核苷酸、核苷或者碱基，包括天然的、类似物、衍生物及其聚合物。其作用为影响生物的蛋白质合成和脂肪、糖类的代谢，或恢复正常代谢、干扰某些异常代谢；用途包括放射病、血小板减少症、白细胞减少症、急慢性肝炎、心血管疾病和肌肉萎缩、肿瘤、病毒病。其分为两类：一类具天然结构，多为生物体自身能够合成的物质，毒副作用小；另一类是自然结构碱基、核苷、核苷酸的结构类似物或聚合物。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"32300f38","s":"b","g":"b14","n":"烟酰胺腺嘌呤二核苷酸","e":"NAD","d":"指由一分子烟酰胺核苷酸（NMN）和一分子腺嘌呤核苷酸连接而成的辅酶核苷酸，NADP则是在NAD的腺苷酸核糖的2'-羟基上接了一个磷酸。由烟酸合成NAD经3步反应：烟酸与PRPP反应生成烟酸单核苷酸，进一步与ATP缩合生成脱酰胺-NAD，最后酰胺化生成NAD，Gln作为酰胺氮的供体；NADP由NAD经磷酸化转变合成，由NAD激酶催化。其与FMN、FAD、辅酶A同列为需经多步反应合成的辅酶核苷酸。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"60e388fb","s":"b","g":"b14","n":"黄素核苷酸","e":"FMN与FAD","d":"指核黄素转变生成的两类黄素核苷酸。FMN由6,7-二甲基异咯嗪核醇和磷酸组成，FAD由一分子FMN和一分子腺苷酸连接而成。合成上，核黄素在黄素激酶的作用下与ATP反应生成5'-磷酸核黄素，即异咯嗪单核苷酸（FMN）；FMN又在FAD焦磷酸化酶的作用下与ATP反应生成FAD。两个反应式：核黄素+ATP→FMN+ADP，FMN+ATP→FAD+PPi，并将其与NAD、辅酶A同列为辅酶核苷酸生物合成的实例。","src":"第14讲 核酸降解与核苷酸代谢 II"},{"id":"9b07283f","s":"b","g":"b15","n":"关键酶","e":"Key enzyme","d":"指代谢途径中催化反应速度最慢（rate-limiting）、其活性决定代谢途径总速度的酶，又称调节酶。其特点为：催化单向反应或非平衡反应，其活性决定反应的方向；通常处于代谢途径的起始处或分支处；其活性受底物和多种代谢物或效应剂的调节。它是对代谢进行调节的对象，调节方式分酶活性的调节（快速调节）和酶含量的调节（缓慢调节）两类。糖酵解的关键酶为己糖激酶、磷酸果糖激酶、丙酮酸激酶。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"325146bd","s":"b","g":"b15","n":"酶的分隔分布","e":"Compartmentation of enzymes","d":"指酶在细胞内分隔分布、一组代谢酶常常组成一个酶系分布在细胞某部分的格局。举例：糖酵解、糖原合成及分解、脂肪酸合成的酶系存在于胞液中，TCA和β-氧化酶系在线粒体，核酸合成的酶系大多集中在细胞核内。其意义在于为代谢调节创造条件，使某些调节因素可以较专一地影响某一细胞器中酶的活性而不影响其他部分，保证整体反应的有序性；代谢物或离子在各细胞器间的穿梭移动也可改变某些部分的代谢速度。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"320e96f9","s":"b","g":"b15","n":"别构调节","e":"Allosteric regulation","d":"指有些物质（效应物、别构调节物）能与酶分子上的非催化部位特异结合，引起酶分子构象改变，进而改变酶催化活性的调节方式，又称变构调节。受这种调节作用的酶为别构酶或变构酶；能使酶发生变构效应的物质称变构效应剂，变构后引起酶活性增强的为激活变构剂（正效应物），反之则为抑制变构剂（负效应物）。变构剂与调节亚基或部位间以非共价键结合。它是细胞水平代谢调节中酶分子结构调节的方式之一。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"4ab813d5","s":"b","g":"b15","n":"别构酶","e":"Allosteric enzyme","d":"指能受别构调节的酶，常常是由两个以上亚基组成的聚合体。有的亚基与作用物结合、起催化作用，称催化亚基；有的亚基与变构剂结合、发挥调节作用，称调节亚基，也可在同一亚基上既存在催化部位又存在调节部位。变构剂与调节亚基（或部位）间以非共价键结合，结合后改变酶的构象，从而使酶活性被抑制或激活。它与米氏酶不同，动力学不符合米曼氏方程式，反应速度与作用物浓度的关系曲线常呈S形。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"dc63afc9","s":"b","g":"b15","n":"变构效应剂","e":"Allosteric effector","d":"指能使酶发生变构效应的物质。按其效应分为两类：变构后引起酶活性增强的称激活变构剂或正效应物，引起酶活性减弱的称抑制变构剂或负效应物。以糖和脂肪代谢的别构酶为例：磷酸果糖激酶受AMP、ADP、FDP激活，受ATP、柠檬酸抑制；丙酮酸激酶受FDP激活，受ATP、乙酰CoA抑制；乙酰CoA羧化酶受异柠檬酸激活，受长链脂肪酸抑制。效应剂与酶的结合为非共价、可逆的结合。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"d1dc7505","s":"b","g":"b15","n":"酶的化学修饰调节","e":"Chemical modification","d":"指酶分子（肽链）某些氨基酸残基的侧链在另一些酶的催化下发生可逆的共价修饰、引起酶活性改变的过程，又称共价修饰调节。修饰方式包括磷酸化和去磷酸化、乙酰化和去乙酰化、腺苷化和去腺苷化、甲基化和去甲基化以及-SH基与-S-S-基互变等，其中磷酸化和去磷酸化在物质代谢调节中最为常见。其两个特点：被修饰的酶有活性与非活性两种互变形式；可产生连续激活现象，具有信号放大效应。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"90731a3b","s":"b","g":"b15","n":"蛋白质的磷酸化","e":"Protein phosphorylation","d":"指由蛋白质激酶催化的把ATP或GTP上γ位的磷酸基转移到底物蛋白质氨基酸残基上的过程，其逆转过程由蛋白质磷酸酶催化，称为蛋白质脱（去）磷酸化。已发现人体内有多达2000个左右的蛋白质激酶和1000个左右的蛋白质磷酸酶基因。以糖原磷酸化酶为例，无活性的磷酸化酶b（二聚体）在磷酸化酶b激酶催化下磷酸化成为高活性的磷酸化酶a（二聚体），再由磷酸化酶a磷酸酶逆转。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"81369bc1","s":"b","g":"b15","n":"诱导剂与阻遏剂","e":"Inducer and repressor","d":"指通过影响酶蛋白合成而调节酶含量的两类化合物。酶的底物或产物、激素以及药物等都可以影响酶的合成，一般将加强酶合成的化合物称为诱导剂，减少酶合成的化合物称为阻遏剂；诱导剂和阻遏剂可在转录水平或翻译水平影响蛋白质的合成。酶含量的调节与酶活性的调节相对，属缓慢调节。生物体通过调节酶的合成或降解速度来控制酶的绝对含量以调节代谢，除诱导和阻遏过程外，还必须同时控制酶降解的速度。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"421c2f8f","s":"b","g":"b15","n":"泛素","e":"Ubiquitin","d":"指由76个氨基酸残基组成的小分子多肽，可以以共价结合的方式与将被降解的蛋白质的Lys残基相连，蛋白质一旦接有泛素即称为发生泛素化。泛素化在ATP的参与下被三种酶依序催化，形成蛋白质-泛素复合结构，进入蛋白酶体后降解为肽段。该系统的三个组分为泛素激活酶E1、泛素结合酶E2和靶蛋白泛素连接酶E3；E1以Cys巯基与泛素C端Gly形成高能硫酯键。选择什么蛋白质被泛素化主要取决于E2和E3。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"4a50c6a5","s":"b","g":"b15","n":"泛素-蛋白酶体途径","e":"Ubiquitin-proteasome pathway","d":"指蛋白质经泛素化标记后被蛋白酶体降解为肽段的途径。其过程为：泛素在ATP参与下被E1、E2、E3三种酶依序催化，与靶蛋白的Lys残基形成异肽键，形成蛋白质-泛素复合结构，进入蛋白酶体降解为肽段。其中E1利用水解ATP的能量以其半胱氨酸残基的巯基与泛素C端的甘氨酸残基形成高能硫酯键，泛素随后转移到E2，靶蛋白与E3结合，E2把泛素转移到靶蛋白并与Lys的-NH2基团形成异肽键。该途径也参与内源性抗原在胞内的降解。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"a0e725fb","s":"b","g":"b15","n":"酶原激活","e":"Zymogen activation","d":"指在一定的条件下酶原水解去除一部分肽链、使酶的构象发生变化而形成有活性酶分子的过程。酶原从无活性状态转变成有活性状态的过程是不可逆的。例如胰蛋白酶原分子中某一个肽键被特殊的水解酶催化水解后，即转变成活性的胰蛋白酶，肽链缩短、构象改变。属于这种类型的酶有消化系统的酶（如胰蛋白酶、胰凝乳蛋白酶和胃蛋白酶等）以及凝血酶等。它与别构调节、共价修饰调节同属酶活性的调节方式。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"0cf18181","s":"b","g":"b15","n":"膜受体激素与胞内受体激素","e":"Membrane-receptor and intracellular-receptor hormones","d":"指按受体在细胞中部位不同而划分的两类激素。膜受体激素的作用路线为：激素结合膜受体后经第二信使调节代谢，产生细胞效应；胞内受体激素则进入细胞，结合细胞核或胞浆受体形成激素-受体复合物，作用于DNA的激素作用元件（HRE），调节相应基因转录，从而改变蛋白质或酶的合成。激素通过特异性受体发挥调节作用；对每一个细胞来说激素是外源性调控信号，对机体整体而言仍属内环境的一部分。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"96096b47","s":"b","g":"b15","n":"应激","e":"Stress","d":"指生物体接受到一些异常的刺激，如创伤、剧痛、缺氧、中毒、严重感染和剧烈情绪激动等时所作出的一系列反应的\"紧张状态\"。人体应激时交感神经兴奋，肾上腺素、肾上腺皮质激素分泌增加，血浆胰高血糖素和生长激素增多，胰岛素减少；代谢改变加强表现为血糖升高（糖原分解和糖异生）以保证脑和红细胞能量供应、脂肪动员成为肌肉的主要能源、蛋白质分解使肌肉输出氨基酸、尿素合成和排出增加，出现负氮平衡。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"54eb6874","s":"b","g":"b15","n":"短期饥饿","e":"Short-term starvation","d":"指机体在短期饥饿状态下的代谢改变。概括为四点：肌肉蛋白分解加强；糖异生增强；脂肪动员增强，酮体生成增加；组织对葡萄糖利用减少。四点合起来即以脂肪和酮体供能、以糖异生保糖。这些改变使机体在葡萄糖供应不足时转向以脂肪和酮体供能，同时由糖异生维持血糖水平。短期饥饿与饱食情况、长期饥饿并列，作为机体主要组织间代谢联系发生改变的代表性状态，说明各组织器官在代谢上互相紧密联系形成一个整体。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"ec4a1ce4","s":"b","g":"b15","n":"长期饥饿","e":"Long-term starvation","d":"指机体在长期饥饿状态下的代谢改变。酮体生成大量增多，脑利用酮体增加，占耗氧量的60%；肌肉以脂肪酸为主要能源，以使酮体优先供应脑；肌肉蛋白大量减少，糖异生以乳酸和丙酮酸为主要原料；肾脏糖异生明显增加，几乎与肝相等；因肌肉蛋白分解减少，负氮平衡有所改善。与短期饥饿相比，长期饥饿时酮体成为脑的重要燃料，糖异生的原料与场所也发生转移。这些改变体现饥饿时各组织器官之间在底物供应上的重新协调。","src":"第15讲 物质代谢的调节及代谢网络"},{"id":"e97d841a","s":"c","g":"c01","n":"三羧酸循环","e":"tricarboxylic acid cycle","d":"三羧酸循环（tricarboxylic acid cycle）又称柠檬酸循环、TCA循环或Krebs循环，是以发现者Hans Adolf Krebs命名的需氧代谢途径。有氧条件下丙酮酸氧化脱羧生成乙酰辅酶A进入循环，乙酰基被完全氧化为CO2，高能电子以NADH形式收集后交给膜上的电子传递链，经氧化磷酸化生成ATP。在多数细胞中它承担约三分之二的碳化合物氧化，是糖、脂、蛋白质代谢汇聚转化的枢纽，也是所有细胞共有的能量代谢途径之一。","src":"《第1章 细胞与细胞生物学》p40；《第7章细胞的能量代谢》p20；MBoC 7e 印刷 p88"},{"id":"86c29161","s":"c","g":"c01","n":"人类基因组计划","e":"HGP","d":"人类基因组计划（HGP）是投入30亿美元、2003年完成精细图、约含30亿个数据的基因组测序计划，其数据量相当于3000本每本1000页、每页1000字的「天书」。它被视为改变世界的科学计划，将改变哲学、伦理与法律观念，并对社会、经济产生重大影响。所谓「基因相关论」认为所有疾病都与人类基因组及病原基因组中有关基因的直接或间接相互作用有关；全基因组信息记录一个人生老病死的重要信息，是最重要的隐私，基因专利与基因资源商业化开采由此引发争议。","src":"《第1章 细胞与细胞生物学》p50"},{"id":"aadcf64c","s":"c","g":"c01","n":"人胚胎干细胞（hES细胞）","e":"","d":"人胚胎干细胞（human embryonic stem cell，hES细胞）指1998年由Thomson建立的人胚胎干细胞系，其建立开启了干细胞研究新的一页，并推动组织工程与修复医学的发展。它取自着床前胚胎的囊胚内细胞团，具有自我更新与多能性两大特征：可在体外长期增殖并保持未分化，在适宜条件下可分化为三个胚层的多种细胞。它既是研究人早期发育与疾病建模的材料，也被视为细胞替代治疗的种子细胞；因建系需破坏胚胎，其研究长期伴随伦理争议。","src":"网络补充：en.wikipedia.org（Embryonic stem cell）"},{"id":"257bcd32","s":"c","g":"c01","n":"人造细胞","e":"Artificial cells","d":"人造细胞（Artificial cells）是一类以生物膜或聚合物膜包裹生物活性物质、模仿活细胞一种或多种功能的工程化颗粒，脂质体、高分子囊泡、纳米微粒与微胶囊都可归入其中。微囊化可在膜内进行代谢、允许小分子交换而阻止大分子通过，其优点在于更接近体内状态、提高装载物的溶解度并降低免疫反应。它可用于药物递送、血液灌流与细胞封装，被视为将对医学与保健产生重大影响的新技术，然而仍有大量工作要做，完全自下而上构建的活细胞尚未实现。","src":"《第1章 细胞与细胞生物学》p60；网络补充：wikipedia（Artificial cell）"},{"id":"dd26844e","s":"c","g":"c01","n":"信号转导","e":"signal transduction","d":"信号转导（signal transduction）是细胞感知环境中的各种信号、把这种信号转导入细胞内并作出一定反应的过程。信号分子与膜受体或核受体结合后，经受体构象改变、酶活性变化、第二信使产生与蛋白磷酸化级联等环节逐级传递并放大，最终改变基因表达、代谢、运动或增殖状态。它是细胞通讯的核心，与细胞增殖、分化、衰老、凋亡并列为细胞重大生命活动；一氧化氮介导、细胞膜受体介导、细胞核受体介导以及细胞连接与黏附依赖的信号转导是其经典途径。","src":"《第1章 细胞与细胞生物学》p11；《第9章 2021细胞通讯和信号转导》p2"},{"id":"af0fdf5a","s":"c","g":"c01","n":"内膜系统","e":"","d":"内膜系统是真核细胞特有的结构，包括细胞核、内体、内质网、高尔基器、溶酶体及转运膜泡等由膜包被的区室；原核细胞除核糖体、蛋白酶体外没有其它细胞器，也没有恒定的内膜系统。它的意义在于把催化特定反应所需的各种酶聚集成大的多组分蛋白质复合物，并把不同代谢过程及所需蛋白质限定在不同的膜被区室内，使相互冲突的反应得以同时进行。各区室之间通过膜泡运输交换物质，形成动态而有序的功能网络。","src":"《第1章 细胞与细胞生物学》p44；《第5章细胞内膜系统（上）》p1"},{"id":"8dfe22dc","s":"c","g":"c01","n":"分子细胞生物学","e":"Molecular Cell Biology","d":"分子细胞生物学（Molecular Cell Biology）是20世纪80年代由于分子生物学的巨大进步而催生的学科。一个多世纪以来，细胞生物学不断从其它学科吸取精华而发展，分子生物学方法与概念的引入，使人们得以在分子水平解析细胞结构、细胞器发生与重大生命活动的机制，研究由描述走向机制阐明。它与生物化学、遗传学、发育生物学等交叉，成为现代细胞生物学的主流形态与《Molecular Biology of the Cell》等教科书的核心。","src":"《第1章 细胞与细胞生物学》p12"},{"id":"153fa611","s":"c","g":"c01","n":"分解代谢","e":"catabolism","d":"分解代谢（catabolism）是新陈代谢的一个方面。新陈代谢是生命活动的基本特征，包括物质代谢和与之相伴的能量代谢，分为合成代谢与分解代谢。分解代谢指细胞把食物分子等大分子降解为较小分子的过程，同时产生细胞可利用的能量形式以及细胞所需的小分子构件；释放的能量经活化载体分子转移，供合成代谢使用。糖酵解与三羧酸循环是典型的分解代谢途径，它们与生物氧化偶联的氧化磷酸化生成ATP。","src":"《第1章 细胞与细胞生物学》p38；MBoC 7e 印刷 p58"},{"id":"e5c47dfa","s":"c","g":"c01","n":"原核细胞","e":"","d":"原核细胞是没有成形细胞核的细胞，核物质集中在核区，无核膜、无核仁，DNA不与组蛋白结合；细胞质中除核糖体、蛋白酶体外没有其它细胞器，也没有恒定的内膜系统；以二分裂为主，属无丝分裂；核糖体为70S型，承担蛋白质合成；细胞膜负责能量代谢，没有专门的能量代谢细胞器；多数具有肽聚糖细胞壁。其基因以转录单位和操纵子为单位组织，在DNA、转录、翻译三个层次调控，并以转录水平调控为主。","src":"《第1章 细胞与细胞生物学》p34；《第1章 细胞与细胞生物学》p26"},{"id":"c86bc21c","s":"c","g":"c01","n":"原生质理论","e":"","d":"原生质理论是19世纪提出的理论。对细胞生物学150年历史的回顾表明，正是19世纪的原生质理论而不是细胞理论，驱动了细胞结构－功能的研究；「系统」观的起源可追溯至原生质体概念的诞生。当代细胞系统生物学正在产生规模空前的数据，对细胞结构功能的系统性认识不断更新，而这一系统观与原生质理论一脉相承，因此原生质理论与21世纪的系统细胞生物学理论具有不可忽视的相关性，其系统视角至今仍有启发。","src":"《第1章 细胞与细胞生物学》p21"},{"id":"76d891ae","s":"c","g":"c01","n":"合成代谢","e":"anabolism","d":"合成代谢（anabolism）是新陈代谢的一个方面，与分解代谢相对。新陈代谢包括物质代谢和与之相伴的能量代谢，是生命活动的基本特征。合成代谢指细胞利用分解代谢产生的小分子构件，并消耗分解代谢所释放的能量，合成构成细胞的各种大分子的过程，如光合作用中固定CO2合成有机物。分解代谢释放能量、合成代谢消耗能量，两者通过活化载体分子偶联；叶绿体的光合磷酸化与光合作用即典型的合成代谢。","src":"《第1章 细胞与细胞生物学》p38；MBoC 7e 印刷 p70"},{"id":"0a6ff68d","s":"c","g":"c01","n":"基因","e":"","d":"基因是DNA分子的一个区段，是遗传信息的结构与功能单位；基因组则是一个物种全部遗传信息的总和。原核细胞与真核细胞都含有携带遗传信息的DNA，1944年Avery的肺炎双球菌转化实验与1952年Hershey、Chase的噬菌体实验证明遗传物质是DNA而不是蛋白质。基因需在细胞内时间与空间上有序表达，其产物逐级装配成行使生命活动的基本结构体系与各种细胞器，并调节增殖、分化、衰老与凋亡等生命活动。","src":"《第1章 细胞与细胞生物学》p24"},{"id":"8785bd54","s":"c","g":"c01","n":"基因组","e":"","d":"基因组是一个物种全部遗传信息的总和。原核细胞与真核细胞都以DNA携带遗传信息，基因是DNA分子的一个区段。人类约有3－4万个基因，基因组信息在细胞内需在时间与空间上有序表达，其表达产物逐级装配成细胞结构体系与细胞器，并调控细胞重大生命活动。功能基因组研究是生命科学基本问题的重要切入点；基因组学与转录组学、蛋白质组学、代谢组学相互衔接，构成从基因到产物的组学层次。","src":"《第1章 细胞与细胞生物学》p24；《第1章 细胞与细胞生物学》p9"},{"id":"f783fe64","s":"c","g":"c01","n":"干细胞","e":"","d":"干细胞是具有自我更新能力、能分化产生多种类型成熟细胞的一类细胞，是组织再生与修复的基础；按发育潜能可分为全能、多能与单能干细胞，按来源可分为胚胎干细胞与成体干细胞。干细胞研究包括治疗性克隆、干细胞与组织再生、诱导性多能干细胞、干细胞的表观遗传调控以及肿瘤干细胞等方向。1998年人胚胎干细胞系的建立开启了干细胞研究新的一页；我国科学家曾把小鼠胚胎干细胞诱导为功能性精子样细胞并获得可育后代。","src":"《第1章 细胞与细胞生物学》p52；《第1章 细胞与细胞生物学》p59"},{"id":"eeac12e9","s":"c","g":"c01","n":"操纵子","e":"operon","d":"操纵子（operon）是原核细胞基因组织的功能单位，由功能相关的结构基因及其上游的启动子、操纵基因等调控序列组成，可转录出一条多顺反子mRNA。原核基因以转录单位和操纵子为单位，在DNA、转录和翻译三个层次进行调控，其中转录水平的调控最为主要。以大肠杆菌色氨酸操纵子为例，色氨酸浓度低时操纵子转录、产生一套合成酶，色氨酸充足时则被阻遏而关闭。操纵子学说的建立推动了现代分子生物学的发展。","src":"《第1章 细胞与细胞生物学》p26；MBoC 7e 印刷 p411"},{"id":"fa33e21d","s":"c","g":"c01","n":"新陈代谢","e":"metabolism","d":"新陈代谢（metabolism）是生命活动的基本特征，指细胞内发生的全部化学过程的总和，即分解代谢与合成代谢之和。它包括物质代谢和与之相伴的能量代谢：分解代谢把食物分子降解为小分子，释放能量并提供构件；合成代谢消耗能量、利用这些构件合成细胞所需的各种分子。所有细胞都具有新陈代谢，并共有糖酵解与三羧酸循环等能量代谢途径，通过与生物氧化偶联的氧化磷酸化生成ATP，是新陈代谢统一性的体现。","src":"《第1章 细胞与细胞生物学》p38；MBoC 7e Glossary（PDF p1464）"},{"id":"aebce5d9","s":"c","g":"c01","n":"治疗性克隆","e":"Therapeutic cloning","d":"治疗性克隆（Therapeutic cloning）与生殖性克隆相对，指产生人克隆胚胎、提供胚胎干细胞以生产用于治疗的组织和器官的技术路线。技术上多以体细胞核移植为基础，把患者体细胞核移入去核卵母细胞，使所得干细胞与患者免疫相容，从而避免移植排斥。克隆人的主要目的不是为克隆人本身的利益，而是用于研究、医疗或其它用途；但因需创建并破坏胚胎，治疗性克隆涉及是否符合伦理、是否合法的争论。","src":"《第1章 细胞与细胞生物学》p55"},{"id":"9e4227b9","s":"c","g":"c01","n":"现代细胞理论","e":"","d":"现代细胞理论是细胞学说的发展形态，包括8条要点：所有生物都由细胞组成；细胞是生物的基本结构与功能单位；所有细胞都由已存在的细胞分裂形成；所有细胞具有基本相同的化学组成；细胞含有遗传信息（DNA），分裂时遗传信息传递给子细胞；细胞内存在生命活动需要的能量代谢过程；单细胞生物由一个细胞组成，多细胞生物由许多细胞组成；生物体的活性依赖于所有组成细胞活性的综合。它在经典细胞理论之上补充了化学组成、遗传信息与能量代谢。","src":"《第1章 细胞与细胞生物学》p22"},{"id":"68cc5d1f","s":"c","g":"c01","n":"生殖性克隆","e":"Reproductive cloning","d":"生殖性克隆（Reproductive cloning）是以产生人婴儿为目的的克隆，与治疗性克隆相对。后者产生人克隆胚胎，提供胚胎干细胞以生产用于治疗的组织和器官；生殖性克隆则把克隆胚胎植入子宫、使之发育为个体，技术上多采用体细胞核移植，把供体细胞核移入去核卵母细胞，并需克服重编程不完全带来的发育异常。克隆人的主要目的不是为克隆人本身的利益而是用于研究、医疗或其它用途，因此其伦理与法律争议更大。","src":"《第1章 细胞与细胞生物学》p55"},{"id":"25d4d31f","s":"c","g":"c01","n":"电子细胞（虚拟细胞）","e":"","d":"电子细胞（虚拟细胞）被视为生命科学技术的重大突破。它以计算机模型再现活细胞内的分子互作网络，把基因表达、信号转导与代谢反应等过程表述为可计算的方程或算法，在计算机上模拟细胞在不同条件下的行为，从而对复杂体系进行研究，并可预测药物作用与毒性、指导实验设计以减少试错。其代表是E-Cell等数字细胞系统；预计它将成为医学、生物学、药学等多学科研究产业领域不可替代的工具，但模型完整性与可靠性仍需大量工作。","src":"《第1章 细胞与细胞生物学》p63；网络补充：wikipedia（Virtual cell）"},{"id":"dcea10bd","s":"c","g":"c01","n":"真核细胞","e":"","d":"真核细胞是具有成形的真正细胞核的细胞，有核膜、有核仁，DNA与组蛋白形成染色体；细胞质中除核糖体、蛋白酶体外还有各种细胞器，具有复杂而恒定的内膜系统；以有丝分裂和减数分裂方式分裂，遗传物质为二倍体，分别来自两个亲本，形成有性生殖；核糖体为80S型；具有特异的进行有氧呼吸的线粒体和进行光合作用的叶绿体；植物细胞和真菌有细胞壁，动物细胞无细胞壁；DNA复制为多复制子、多个复制起点。","src":"《第1章 细胞与细胞生物学》p34"},{"id":"4caf27c6","s":"c","g":"c01","n":"糖类","e":"saccharide","d":"糖类（saccharide）是多羟基醛（酮）及水解后能生成多羟基醛（酮）的一类化合物，包括单糖、二糖、寡糖和多糖。它不仅是细胞代谢的重要能源，也是核酸和糖蛋白等生物大分子的结构成分与细胞的结构成分；细胞中糖类和其他有机物约占1％～1.5％。糖链常以非重复序列与蛋白质或脂质相连，构成细胞表面分子，如决定血型的寡糖；糖原则是完全由葡萄糖亚基连成的多糖，是动物的储能多糖。","src":"《第1章 细胞与细胞生物学》p31；MBoC 7e 印刷 p101"},{"id":"99d9c14b","s":"c","g":"c01","n":"糖酵解","e":"glycolysis","d":"糖酵解（glycolysis）是细胞质中普遍存在的代谢途径，字面意为「糖的分解」，在此过程中糖被不完全降解并产生ATP。它是所有细胞共有的能量代谢途径之一，与三羧酸循环共同构成能量代谢的基础：在大多数动物和植物细胞中，糖酵解只是食物分子分解的前奏，生成的丙酮酸迅速进入线粒体，转化为CO2和乙酰辅酶A后彻底氧化；在许多厌氧生物中，它则是产生ATP的主要方式。癌细胞常表现有氧糖酵解。","src":"《第1章 细胞与细胞生物学》p40；MBoC 7e Glossary（PDF p1458）"},{"id":"e07160f7","s":"c","g":"c01","n":"细胞凋亡","e":"cell apoptosis","d":"细胞凋亡（cell apoptosis）一词最早于1972年提出。到1990年代，细胞凋亡研究获得里程碑式的重大进展，证明它是基因调控的主动过程，而非被动的损伤死亡。典型的细胞凋亡过程涉及一系列胱天蛋白酶（caspase）的水解、活化和信号传递：上游信号触发caspase级联，切割底物，引起染色质凝缩、细胞解体并被吞噬。它与细胞增殖、分化、衰老同属细胞重大生命活动，在个体发育与疾病发生中具有重要意义。","src":"《第12章 细胞衰老与细胞凋亡》p28"},{"id":"dffe2ce3","s":"c","g":"c01","n":"细胞学说","e":"Cell Theory","d":"细胞学说（Cell Theory）由Schleiden和Schwann于1838－1839年共同提出。Schleiden指出细胞是构成植物的基本单位；1839年Schwann发表《关于动植物的结构和生长一致性的显微研究》，指出动植物都是细胞的集合物。两人共同提出：一切植物动物都是由细胞组成的，细胞是一切动植物的基本单位，这就是著名的细胞学说。它确立了细胞作为生物体基本单位的地位，为此后细胞理论的扩展与现代细胞理论的提出奠定了基础。","src":"《第1章 细胞与细胞生物学》p18；《第1章 细胞与细胞生物学》p22"},{"id":"8e091f27","s":"c","g":"c01","n":"细胞生物学","e":"Cell Biology","d":"细胞生物学（Cell Biology）是研究细胞的生命活动规律及其整合功能、阐明生命活动基本规律的学科。它主张以动态、系统、结构与功能统一的观点认识细胞，研究内容包括细胞的形态结构与化学组成、细胞增殖、细胞分化、衰老与凋亡、信号转导以及各种重大生命活动之间的相互关系。一个多世纪以来它不断从其它学科吸取精华而发展；20世纪80年代分子生物学的巨大进步催生了分子细胞生物学，使其成为现代生命科学的核心学科之一。","src":"《第1章 细胞与细胞生物学》p6；《第1章 细胞与细胞生物学》p12"},{"id":"b4d5a6d5","s":"c","g":"c01","n":"细胞组学","e":"Cytomics","d":"细胞组学（Cytomics）是确定单细胞分子表型、从系统角度研究细胞结构及分子功能的科学。它在探索细胞生命活动时，从基因表达与蛋白质生成的时空动态变化入手，深入了解生命的本质。细胞组学与基因组学、转录组学、蛋白质组学、代谢组学相互衔接，构成从基因到蛋白质再到代谢物的组学层次；其目标是系统地研究并理解细胞的结构与行为，即细胞的所有大分子以及细胞在整个机体中的效应。","src":"《第1章 细胞与细胞生物学》p64；《第2章 技术》p81"},{"id":"234b095c","s":"c","g":"c01","n":"能量代谢","e":"energy metabolism","d":"能量代谢（energy metabolism）指细胞的物质代谢过程中都伴随的能量释放、转移和利用。原核与真核细胞进化层次差别很大，但所有细胞都具有共同的能量代谢途径——糖酵解及三羧酸循环，并且都通过与生物氧化相偶联的氧化磷酸化生成三磷酸腺苷（ATP）保存化学能。能量代谢是细胞统一性的重要体现，也是新陈代谢的组成部分；糖、脂、蛋白质的氧化分解最终都汇入这一途径，线粒体进行氧化磷酸化，叶绿体进行光合磷酸化。","src":"《第1章 细胞与细胞生物学》p40；《第1章 细胞与细胞生物学》p35"},{"id":"9da65dc5","s":"c","g":"c01","n":"脂质","e":"lipids","d":"脂质（lipids）是生物体中一大类不溶于水而溶于有机溶剂的有机化合物，是热量的来源和细胞膜、激素的原料，包括脂肪酸、中性脂肪、类固醇、磷脂、糖脂与类胡萝卜素等。生物膜的基本结构由脂质分子形成的双分子层构成，大多数动物细胞膜干重的一半都是脂质分子；脂质分子具有双亲性，既有极性亲水头部又有非极性疏水尾部，这一特征使其在水溶液中能自发形成双分子层。膜脂主要有磷脂、糖脂和胆固醇。","src":"《第1章 细胞与细胞生物学》p30；《第3章 细胞膜与表面（上）》p9"},{"id":"f15f2189","s":"c","g":"c01","n":"蛋白质","e":"protein","d":"蛋白质（protein）是生命的物质基础，没有蛋白质就没有生命。它是细胞的主要大分子组成成分，是由氨基酸通过肽键连接成的线性聚合物，氨基酸序列是特定的；细胞中蛋白质约占7％～14％。蛋白质折叠成最低能量的构象，α螺旋与β折叠是常见的折叠基元，并具有四级结构层次；结构域是构建更大蛋白质的模块单位，部分区域无规且结构动态可变。蛋白质承担催化、运输、信号与结构等多种功能。","src":"《第1章 细胞与细胞生物学》p28；MBoC 7e Glossary（PDF p1471）"},{"id":"71b95a8d","s":"c","g":"c01","n":"诱导多能干细胞","e":"induced pluripotent stem cell（iPS）","d":"诱导多能干细胞（induced pluripotent stem cell，iPS）指通过导入特定转录因子使已分化细胞重编程而获得的多能干细胞。研究中先确定了14种新的候选重组基因，再通过系统的排除过程，最终使用了4个基因——OCT3、SOX2、NANOG和LIN28，成功诱导出多能干细胞。iPS细胞具有与胚胎干细胞相似的多能性，却避免了使用胚胎的伦理问题，是干细胞研究的重要方向，也用于疾病建模与细胞治疗探索。","src":"《第1章 细胞与细胞生物学》p56"},{"id":"d1793f65","s":"c","g":"c01","n":"转录单位","e":"transcript unit","d":"转录单位（transcript unit）是原核细胞基因组织的单位，指从同一启动子开始、被转录成一条RNA分子的DNA区段。原核细胞的基因以转录单位和操纵子为单位进行组织，在DNA、转录和翻译三个不同层次接受调控，其中转录水平的调控是最主要的方式。一个转录单位可包含多个功能相关的基因，转录出多顺反子mRNA，使相关蛋白得以协同表达，这是原核基因表达调控经济高效的结构基础。","src":"《第1章 细胞与细胞生物学》p26"},{"id":"8d1f5651","s":"c","g":"c01","n":"遗传密码","e":"codon","d":"遗传密码（codon）是由3个相邻核苷酸组成的信使核糖核酸（mRNA）基本编码单位，也称密码子。共有64种密码子，其中61种为氨基酸密码子（包括起始密码子），另有3个终止密码子，由它们决定多肽链中氨基酸的种类和排列顺序的特异性，以及翻译的起始和终止。密码子与反密码子按碱基互补配对识别，第三位碱基的摇摆配对使一种tRNA可识别多个同义密码子，故20种氨基酸由61个密码子编码。","src":"《第1章 细胞与细胞生物学》p29；MBoC 7e Glossary（PDF p1450）"},{"id":"e7db6747","s":"c","g":"c16","n":"CRISPR基因编辑技术","e":"CRISPRs（clusters of regularly interspersed short palindromic Repeats）","d":"CRISPR基因编辑技术（CRISPRs）源于细菌抵抗外来病毒或质粒的DNA元件，即规律成簇间隔短回文重复。细菌把入侵DNA的短片段整合到CRISPR位点之间作为「记忆」，再次入侵时转录加工成crRNA，识别入侵者的互补序列，并引导Cas9内切酶在PAM序列邻近处切割双链DNA，造成双链断裂；断裂经非同源末端连接或同源重组修复，可产生插入缺失而实现基因敲除，或引入外源模板实现精确编辑，现已广泛用于基因敲除与编辑。","src":"网络补充：pmc.ncbi.nlm.nih.gov（CRISPR/Cas9 Immune System as a Tool for Genome Engineering）"},{"id":"996b3406","s":"c","g":"c16","n":"荧光原位杂交","e":"FISH（Fluorescent in situ Hybridization）","d":"荧光原位杂交（FISH）是用荧光素或生物素、地高辛等标记的核酸探针，与染色体或组织切片上的靶DNA按碱基互补原则杂交的技术。靶DNA与探针经变性—退火—复性形成杂交体，洗去未结合探针后，用荧光显微镜即可直接观察信号所在位置，从而显示特定基因或序列在染色体、细胞或组织中的分布与表达。它属非放射性原位杂交，标本可为分裂期染色体或间期核，具有安全、快速、可多色同时检测等优点，用于基因定位、表达分析与疾病诊断。","src":"网络补充：kepuchina.cn（FISH技术）"},{"id":"38c7dbb9","s":"c","g":"c16","n":"荧光漂白恢复","e":"FRAP（Fluorescence Recovery After Photobleaching）","d":"荧光漂白恢复（FRAP）用高能激光短时照射细胞内某一微区，使该区荧光分子不可逆淬灭而形成暗斑；随后非漂白区的荧光标记分子因扩散或结合交换运动进入漂白区，荧光逐渐恢复；该技术于上世纪70年代提出，最初用于测定膜分子的侧向扩散。以低强度光连续监测恢复曲线，可得扩散系数与可动分数：恢复快慢反映分子运动与结合动力学，恢复不完全说明存在不可动的结合群体。它广泛用于研究活细胞内蛋白质定位、膜流动性与分子动力学。","src":"《第2章 技术》p37；网络补充：pmc.ncbi.nlm.nih.gov（FRAP, FLIM, and FRET）"},{"id":"0a717e8c","s":"c","g":"c16","n":"荧光共振能量转移","e":"FRET（Fluorescence Resonance Energy Transfer）","d":"荧光共振能量转移（FRET）是检测活体中生物大分子纳米级距离及其变化的有力工具。当供体荧光分子的发射光谱与受体的吸收光谱重叠、且两者距离足够近时，供体以非辐射方式把能量转移给受体，自身荧光减弱而受体荧光增强，转移效率随距离的六次方衰减，对1～10nm尺度的距离变化尤为敏感。因此它可判断某一细胞中两个蛋白是否存在直接的相互作用，也可用于检测分子构象变化，是活细胞成像中常用的近距离「分子尺」。","src":"《第2章 技术》p35；网络补充：kepuchina.cn（荧光共振能量转移）"},{"id":"ee9e690f","s":"c","g":"c16","n":"绿色荧光蛋白","e":"GFP","d":"绿色荧光蛋白（GFP）是可用于研究活细胞中动态过程的蛋白。把GFP编码序列与目的蛋白基因融合并导入细胞，表达的融合蛋白带荧光，可在荧光显微镜下实时观察该蛋白在细胞内的定位与运动；把GFP置于感兴趣基因的启动子控制下，它又可作为报告分子监测基因表达。GFP及其衍生蛋白（蓝色、红色荧光蛋白等）已成为活细胞成像的基本工具，用于标记核孔复合体、追踪膜蛋白运输等过程。","src":"《第2章 技术》p18；MBoC 7e 印刷 p574"},{"id":"d3130fc5","s":"c","g":"c16","n":"HAT培养基","e":"","d":"HAT培养基是含次黄嘌呤（hypoxanthine，H）、氨基蝶呤（aminopterin，A）和胸腺嘧啶（thymine，T）的选择培养基。氨基蝶呤阻断核酸合成的主通道，细胞只能经旁路途径利用次黄嘌呤与胸腺嘧啶合成核苷酸；骨髓瘤细胞突变体缺乏胸腺嘧啶核苷激酶（TK）和次黄嘌呤鸟嘌呤磷酸核糖转移酶（HGPRT），在HAT中不能存活。小鼠脾B淋巴细胞与骨髓瘤细胞融合后，只有杂交瘤细胞能借旁路途径生长而被筛选出来。","src":"《第2章 技术》p68"},{"id":"e7926580","s":"c","g":"c16","n":"免疫印迹","e":"Immunoblot（Western-Blot）","d":"免疫印迹（Immunoblot，又称Western blot）先将蛋白质经SDS-聚丙烯酰胺凝胶电泳按分子量分离，再电转移至硝酸纤维素或PVDF膜上，用封闭液封闭非特异位点，然后以特异性一抗与靶蛋白结合，继以酶标或荧光标记的二抗检测，经显色或化学发光显示条带。条带位置指示分子量、强度反映抗原丰度，故可对复杂混合物中的特定蛋白作定性与半定量分析，广泛用于蛋白表达与修饰研究。","src":"网络补充：thermofisher.com（Overview of Western Blotting）"},{"id":"80037559","s":"c","g":"c16","n":"模式生物","e":"Model organisms","d":"模式生物（Model organisms）是细胞生物学研究中使用的代表性生物。大肠杆菌与操纵子学说的建立及现代分子生物学的发展相关；豌豆和果蝇与遗传学定律的发现相关；酵母和海胆与细胞周期调控机制的认识相关；线虫与细胞凋亡机制的揭示相关；小鼠与哺乳动物功能基因组学研究相关。芽殖酵母与裂殖酵母因易产生和识别细胞周期突变体而成为研究细胞周期的模式生物；这些生物便于遗传操作与观察，结论常可推广。","src":"《第2章 技术》p79；《第10章 细胞分裂与细胞周期(下)》p26"},{"id":"c41d44cf","s":"c","g":"c16","n":"Southern印迹","e":"Southern blot","d":"Southern印迹（Southern blot）是通过核酸杂交确定凝胶中特定DNA片段位置的技术。DNA经限制酶切割并在琼脂糖凝胶中电泳按大小分离后，变性并转移到尼龙膜或硝酸纤维素膜上，与标记的核酸探针杂交，洗去未结合探针，再经放射自显影或显色显示互补片段所在的条带。它可判断特定序列是否存在及其大小与拷贝数，是基因组分析、基因定位与重组DNA鉴定的经典方法，也是各种印迹技术的原型。","src":"《第2章 技术》p54"},{"id":"c6f02c5a","s":"c","g":"c16","n":"倒置显微镜","e":"","d":"倒置显微镜是物镜在下、照明系统在上、两者位置颠倒的显微镜。标本置于物镜上方的载物台上，光路自下而上经标本进入物镜，聚光器位于上方，因而适合观察培养皿、培养瓶中较厚的活细胞样本；它通常配有相差或DIC物镜，有的还装有荧光装置，可在不染色、不固定的条件下观察活细胞的形态与运动。它是细胞培养室与活细胞工作站的基本设备，也是显微操作与细胞融合实验的常用工具；由于工作距离较长，便于放置培养皿等器皿。","src":"《第2章 技术》p12"},{"id":"7b1fdb77","s":"c","g":"c16","n":"冷冻蚀刻","e":"Freeze-Etching Fracture","d":"冷冻蚀刻（Freeze-Etching Fracture）又称冷冻断裂蚀刻复型，是透射电镜的制样技术。样品经快速冷冻后在高真空中用冷刀断裂，断裂面沿阻力最小处延伸，遇到生物膜时通常沿脂双层疏水区劈开，从而暴露膜的内部断面；稍升温使断面上的冰升华（即蚀刻），再以铂－碳投影、喷碳加固形成复型膜，清除组织后即可电镜观察。膜面上所见的微粒是镶嵌的膜蛋白，故该技术特别适于研究膜的结构与功能。","src":"网络补充：kepuchina.cn（冷冻刻蚀技术）"},{"id":"f169d1ae","s":"c","g":"c16","n":"凝胶过滤层析","e":"Gel Filtration Chromatography","d":"凝胶过滤层析（Gel Filtration Chromatography）又称排阻层析、分子筛方法或分子排阻层析，是用交联的聚糖（如葡聚糖Sephadex或琼脂糖）装柱分离蛋白质的柱层析技术。凝胶颗粒内部有网状孔隙，小分子可进入孔隙而滞留，大分子被排阻在颗粒外随流动相先流出，故按分子大小分离：大分子先洗脱，小分子后洗脱。它条件温和、不易使蛋白变性，常用于蛋白质的分离纯化、分子量估算以及脱盐与缓冲液交换。","src":"《第2章 技术》p44"},{"id":"ac999b4a","s":"c","g":"c16","n":"分辨率","e":"","d":"分辨率是光学显微镜的基本参数，R＝0.61λ/N.A，其中λ为光波长，N.A为数值孔径。数值孔径越大、波长越短，可分辨的两点间距离越小，分辨率越高，因此可用短波长光与油浸物镜增大数值孔径来提高分辨率。分辨率决定显微镜能看清的最小结构，是评价显微镜性能的核心指标；受衍射极限限制，普通光学显微镜的分辨率约在0.2µm量级，超越它需借助共焦、超高分辨率荧光或电子显微技术。","src":"《第2章 技术》p4"},{"id":"cbec72e0","s":"c","g":"c16","n":"单克隆抗体技术","e":"Monoclonal antibody technology","d":"单克隆抗体技术（Monoclonal antibody technology）把小鼠脾B淋巴细胞与骨髓瘤细胞融合，经HAT培养基筛选杂交瘤细胞以制备单克隆抗体。B淋巴细胞能产生特异性抗体但不能在体外长期增殖，骨髓瘤细胞可无限增殖却缺乏TK与HGPRT；融合后只有杂交瘤细胞既能在HAT培养基中存活，又能持续分泌单一特异性抗体。经克隆化培养与筛选，可获得针对单一抗原决定簇的均一抗体，广泛用于检测、定位与治疗。","src":"《第2章 技术》p66；《第2章 技术》p68"},{"id":"3a6da3d1","s":"c","g":"c16","n":"原代培养细胞","e":"primary culture cell","d":"原代培养细胞（primary culture cell）指从机体取出组织或器官，经机械剪碎或酶消化分散成单个细胞后，直接接种到培养瓶或培养皿中进行首次培养所得的细胞。它们刚离开体内环境，生物学性状与体内细胞较为接近，但群体不均一、增殖能力有限，通常传至10代以内即衰老死亡。原代培养是建立细胞系与细胞株的起点，也是药物检测与毒性试验中较能反映在体状态的实验材料。","src":"《第2章 技术》p65；网络补充：bncc.org.cn（原代培养与传代培养）"},{"id":"fae716a4","s":"c","g":"c16","n":"原位杂交","e":"","d":"原位杂交是在保持细胞或组织形态完整的条件下，用标记的核酸探针与切片或细胞内的靶核酸杂交，以显示特定基因或RNA在细胞内的分布与表达的技术。标本经固定、透化与变性后与探针杂交，洗去未结合探针，再以放射自显影或荧光检测信号。它把分子杂交的特异性与形态学定位结合起来，可确定特定序列所在的细胞类型与亚细胞位置，是基因定位、表达分析与疾病诊断的常用手段，也是荧光原位杂交等技术的基础。","src":"《第2章 技术》p45；《第2章 技术》p20"},{"id":"6f5561a7","s":"c","g":"c16","n":"基因敲除小鼠","e":"Knockout Mice","d":"基因敲除小鼠（Knockout Mice）是由Capecchi于20世纪80年代末发展的技术制备的小鼠。实验分三步：构建重组体，即把含筛选标记的载体与靶基因同源序列重组；转基因敲除，将重组体导入胚胎干细胞，经同源重组替换靶基因后注入囊胚获得嵌合体；筛选，鉴定基因型并交配繁育出纯合个体。该技术使特定基因的功能在整体水平被消除，是研究基因功能与构建人类疾病模型的重要工具。","src":"《第2章 技术》p72"},{"id":"cfa701e1","s":"c","g":"c16","n":"基因芯片","e":"Gene Microarray","d":"基因芯片（Gene Microarray）又称DNA微阵列，是在玻璃、硅片或尼龙膜等固相支持物上按特定排列固定大量已知序列的核酸探针，与荧光标记的样品核酸杂交，通过检测各点荧光强度实现高通量平行分析的技术。其原理是碱基互补配对：样品与探针互补则形成杂交体，信号强度反映该序列的相对丰度。它可一次分析成千上万个基因，用于基因表达谱测定、突变与多态性检测、基因组作图以及疾病诊断。","src":"网络补充：kepuchina.cn（基因芯片）"},{"id":"84972d6f","s":"c","g":"c16","n":"密度梯度离心","e":"","d":"密度梯度离心是在离心管中预先形成密度梯度介质，使样品组分按密度或沉降速度分层而分离的离心技术，包括速度密度梯度离心与等密度梯度离心。前者主要用于分离密度相近而大小不等的细胞或细胞器，各组分按沉降系数不同在梯度中形成不同区带；后者使各组分沉降到与自身密度相等的介质位置而达到平衡。它分辨率高于差速离心，可用于分离细胞器、区分不同时期的细胞以及纯化大分子复合物与病毒颗粒。","src":"《第2章 技术》p40"},{"id":"27db96f7","s":"c","g":"c16","n":"差速离心","e":"","d":"差速离心是逐步提高离心力、把细胞匀浆中各组分依次沉淀分离的离心技术。在细胞匀浆物中，较大的组分如细胞核、线粒体在较低离心力下即可沉淀，较小的细胞组分则需要更大的离心力才能沉降；因此按1000g、20000g、80000g、150000g逐级离心并分别收集沉淀，可先后得到核、线粒体、微粒体与可溶性组分。该方法操作简便，是分离细胞器与生物大分子的经典起点，但分辨率有限，常需与密度梯度离心配合。","src":"《第2章 技术》p41"},{"id":"ca2ec859","s":"c","g":"c16","n":"干涉显微镜","e":"DIC","d":"干涉显微镜（DIC）即微分干涉相差显微镜，1952年由Nomarski发明，利用两组平面偏振光的干涉加强影像的明暗效果，能显示结构的三维立体投影。标本可略厚一点，因折射率差别更大，故影像的立体感更强；它不需染色即可观察活细胞，能清晰显示细胞轮廓、细胞核与细胞器的立体形态。它常作为倒置显微镜的物镜配置，用于培养细胞的观察，也适于观察较厚标本的内部结构，对厚标本的效果优于普通相差显微镜。","src":"《第2章 技术》p11；《第2章 技术》p12"},{"id":"bc377c81","s":"c","g":"c16","n":"扫描电子显微镜","e":"","d":"扫描电子显微镜于20世纪60年代问世，用来观察标本表面结构。其分辨力为6～10nm；由于人眼的分辨力为0.2mm，故有效放大倍率为0.2mm/10nm＝20000X。电子束在样品表面逐点扫描，激发二次电子等信号成像，样品需经固定、脱水、干燥与表面镀膜处理；制样时表面须导电，故非导电样品要喷镀金属薄层。它景深大、立体感强，适于观察细胞表面形态、微绒毛与纤毛等表面结构，常与透射电镜配合使用。","src":"《第2章 技术》p33"},{"id":"9106e0c3","s":"c","g":"c16","n":"数字细胞","e":"Digital cell（E-Cell）","d":"数字细胞（Digital cell，E-Cell）是活细胞的计算机模型，以计算方式反映细胞内分子的互作网络。E-Cell System是用于细胞模拟的软件系统，可对像生物细胞那样的复杂系统进行高通量、大规模分析；E-Cell Project是国际合作研究项目，旨在发展有关的理论、技术与软件平台，以获得完整的细胞模型。数字细胞把分散的实验数据整合为可计算、可预测的模型，用于检验人们对细胞行为的理解并指导实验设计。","src":"《第2章 技术》p83"},{"id":"7dffcc57","s":"c","g":"c16","n":"核体","e":"karyoplast","d":"核体（karyoplast）是细胞拆合技术中由细胞核及极少量胞质、外包质膜构成的球形结构，与胞质体相对应，也称小细胞。制备时用细胞松弛素B处理细胞并配合离心，使细胞核排出或与细胞质分离，从而同时得到核体与去核的胞质体。核体带有完整的基因组，可在培养中再生胞质部分并继续生长、分裂；将其与胞质体或完整细胞融合，可构建重组细胞与胞质杂种，用于研究核质关系与细胞质遗传。","src":"《第2章 技术》p66；网络补充：baike.baidu.com（细胞拆合）"},{"id":"d5dcd017","s":"c","g":"c16","n":"激光扫描共焦显微镜","e":"LCSM","d":"激光扫描共焦显微镜（LCSM）用激光作光源，光束经双色镜反射后由物镜汇聚到样品某一焦点，逐点、逐行、逐面快速扫描。焦点发出的荧光经透镜汇聚成像而被检测器检出，样品其它部位发出的荧光不聚焦于检测器，故不能检出，因此可排除焦外杂散光、实现光学切片。它能显示细胞样品的立体结构，分辨力约为普通光学显微镜的3倍，配合免疫荧光标记可对细胞内分子作精确的三维定位，其光学切片能力使厚样品的三维重建成为可能。","src":"《第2章 技术》p23；《第2章 技术》p24"},{"id":"137c06a8","s":"c","g":"c16","n":"相差显微镜","e":"","d":"相差显微镜把透过标本的可见光的光程差变成振幅差，从而提高各种结构间的对比度，使各种结构变得清晰可见。在构造上它有两处不同于普通光学显微镜：环形光阑位于光源与聚光器之间；物镜中加了涂有氟化镁的相位板，可将直射光或衍射光的相位推迟1/4λ。因此它无需染色即可观察活细胞，对透明度高、反差极低的标本效果尤为明显，特别适合观察培养细胞、染色体与细胞器的形态和运动，也用于观察活细胞的贴壁与分裂过程。","src":"《第2章 技术》p9"},{"id":"8d3f7b28","s":"c","g":"c16","n":"细胞杂交","e":"cell hybridization","d":"细胞杂交（cell hybridization）是细胞工程中把两个不同来源的细胞融合，形成含双亲遗传物质的杂种细胞，并对其遗传特性与表型进行分析的技术。它与细胞融合技术相配合，可用于研究基因表达的调控、染色体与表型的对应关系以及细胞质遗传；杂种细胞在传代中往往随机丢失部分染色体，据此可把某一表型定位到特定染色体。制备核体与胞质体后再融合，还可构建胞质杂种与重组细胞。","src":"《第2章 技术》p66"},{"id":"3f11b542","s":"c","g":"c16","n":"细胞株","e":"cell strain","d":"细胞株（cell strain）是通过选择法或克隆形成法，从原代培养物或细胞系中获得的、具有特殊性质或标志物的细胞群体。其特殊性质或标志须在整个培养期间始终存在；由单细胞增殖而来者高度均一，遗传与生化特性近乎一致。细胞株可经连续传代，广泛用于需要稳定、可比结果的实验；与之相对的细胞系只要求某一类细胞占绝大多数而不强调纯度。不能继续传代者称有限细胞株，可连续传代者称连续细胞株。","src":"《第2章 技术》p65；网络补充：bncc.org.cn（细胞培养术语）"},{"id":"449e80d4","s":"c","g":"c16","n":"细胞系","e":"cell line","d":"细胞系（cell line）是原代培养物经首次传代成功后所繁殖形成的、可继续传代培养的细胞群体。第一个细胞系是HeLa细胞，其供体于69年前去世，但癌细胞至今仍在不停分裂复制，已繁衍18000代，总质量达到惊人的5000万吨，1951年由盖伊医生建立。细胞系可分为有限细胞系与无限细胞系，后者多已发生异倍化、具无限增殖能力；细胞系是细胞生物学与医学研究中最常用的实验材料。","src":"《第2章 技术》p64；MBoC 7e 印刷 p478"},{"id":"c23fee74","s":"c","g":"c16","n":"细胞融合","e":"cell fusion","d":"细胞融合（cell fusion）是两个或多个细胞合并为一个细胞的过程，是细胞工程的基本技术。可用灭活的病毒、聚乙二醇等融合剂或电融合诱导，使相邻细胞的质膜合并、胞质连通，细胞核也可融合形成杂种细胞。小鼠脾B淋巴细胞与骨髓瘤细胞的融合是制备单克隆抗体的关键步骤，融合后需用HAT培养基筛选杂交瘤细胞。细胞融合还用于基因定位、制备胞质杂种以及研究膜蛋白的流动与分布。","src":"《第2章 技术》p66；《第2章 技术》p68"},{"id":"833627c8","s":"c","g":"c16","n":"继代培养细胞","e":"sub-culture cell","d":"继代培养细胞（sub-culture cell）是原代培养的细胞经胰蛋白酶消化、按比例稀释后，转移到新的培养基与培养器皿中继续培养所得的细胞。其目的是解除接触抑制以及营养枯竭、代谢产物积累造成的生长停滞，并通过连续数代培养扩大细胞数量。继代培养的细胞逐渐适应体外环境，生物学性状趋于稳定，是建立细胞系与细胞株的必经环节；传代次数过多则可能出现衰老或转化；传代比例与间隔需依细胞生长速度调整。","src":"《第2章 技术》p65；网络补充：bncc.org.cn（传代培养）"},{"id":"e03f6d96","s":"c","g":"c16","n":"胞质体","e":"cytoplast","d":"胞质体（cytoplast）是细胞拆合技术中去核后仍由质膜包被的细胞质部分。制备时先用细胞松弛素B处理细胞，再结合离心使细胞核与细胞质分开，去核的胞质部分即为胞质体。它保留内质网、线粒体、溶酶体、高尔基体及微丝微管等结构，具有贴壁、铺展、运动与胞饮等行为，可在体外存活一段时间。将其与核体或完整细胞融合，可构建重组细胞与胞质杂种，用于研究核质关系与细胞质遗传。","src":"《第2章 技术》p66；网络补充：baike.baidu.com（细胞拆合）"},{"id":"cdc25214","s":"c","g":"c16","n":"荧光显微镜","e":"Fluorescence Microscopy","d":"荧光显微镜（Fluorescence Microscopy）以短波光为光源，配有两个特殊的滤光片，照明方式通常为落射式。激发滤光片只让激发光通过，照射标本使荧光物质受激发射荧光；阻挡滤光片再滤去激发光而只让荧光进入物镜成像，因此可在暗背景上看到明亮的荧光结构。它用于观察能激发出荧光的结构，包括免疫荧光、原位杂交与GFP标记，广泛用于分子定位、基因定位与疾病诊断。","src":"《第2章 技术》p13；MBoC 7e 印刷 p571"},{"id":"8f020dc9","s":"c","g":"c16","n":"表面等离子共振","e":"surface plasmon resonance（SPR）","d":"表面等离子共振（surface plasmon resonance，SPR）是基于全反射的光学检测技术，可实时、无标记地跟踪分子间的相互作用。偏振光以特定角度经棱镜射到传感器表面的金膜上，激发膜内自由电子的集体振荡形成表面等离子波；当入射光与等离子波匹配时发生共振，反射光强度急剧下降，对应的入射角称共振角。共振角对膜表面折射率极为敏感，而折射率变化与结合分子的质量成正比，故可实时记录结合与解离的全过程。","src":"网络补充：baike.sogou.com（表面等离子共振）"},{"id":"8a790f3b","s":"c","g":"c16","n":"透射电子显微镜","e":"Transmission Electron Microscopy","d":"透射电子显微镜（Transmission Electron Microscopy）以电子束作光源、电磁场作透镜。电子束的波长与加速电压（通常50～120KV）的平方根成反比；仪器由电子照明系统、电磁透镜成像系统、真空系统、记录系统与电源系统五部分构成。其分辨力为0.2nm，放大倍数可达百万倍，用于观察小于0.2µm的超微结构。电子穿透力弱，标本须制成超薄切片并经重金属染色，所得图像为二维投影。","src":"《第2章 技术》p29；MBoC 7e 印刷 p600"},{"id":"4e72c032","s":"c","g":"c16","n":"间接免疫荧光标记技术","e":"Indirect immunofluorescence labeled technique","d":"间接免疫荧光标记技术（Indirect immunofluorescence labeled technique）利用荧光抗体（抗原－抗体偶联）研究细胞内特定蛋白的定位。先用未标记的特异性一抗与标本中的靶抗原结合，洗去游离一抗；再用带荧光素的二抗与一抗结合，形成抗原—一抗—荧光二抗复合物，在荧光显微镜下即可见靶蛋白所在位置的荧光信号。因一个一抗可结合多个标记二抗、信号被放大，该法比直接法更灵敏，广泛用于蛋白亚细胞定位与细胞骨架观察。","src":"《第2章 技术》p18"},{"id":"31d358cf","s":"c","g":"c16","n":"非细胞体系","e":"cell-free system","d":"非细胞体系（cell-free system）是用细胞匀浆提取物或纯化组分在试管中重建某一生物学过程的研究体系。细胞生物学家的重要目标是使每一种生物学过程都能在纯化的非细胞体系中重建，因为只有这样才能确定该过程所需的全部组分并控制其浓度，从而阐明精确的作用机制。DNA复制、转录、RNA剪接与蛋白质翻译等过程的分子细节多由非细胞体系研究揭示，它也被用于研究膜泡出芽与蛋白质运输。","src":"《第2章 技术》p65；MBoC 7e 印刷 p487"},{"id":"5902bdf9","s":"c","g":"c03","n":"ABC转运蛋白","e":"ABC-Class","d":"ABC转运蛋白（ABC-Class）是膜转运蛋白中的一个大家族，跨膜转运种类繁多的分子，包括无机离子、氨基酸、单糖、多糖、小肽甚至蛋白质。它有两个高度保守的ATP结合区（ATP-binding cassette），结合ATP可使该区域二聚化，水解ATP则使其解聚；胞内发生的这种结构变化传递到跨膜区，使蛋白构象循环变化，把底物结合位点交替朝向膜内和膜外，从而利用ATP的结合与水解跨膜运输底物，如金黄色葡萄球菌的多药抗性蛋白。","src":"《第3章 细胞膜与表面（上）》p71"},{"id":"1d8ac575","s":"c","g":"c03","n":"ABO血型抗原","e":"","d":"ABO血型抗原是红细胞质膜上的一类鞘糖脂，属ABO血型系统的血型抗原，也是结合脂质的常见糖分子。其抗原特异性取决于糖链末端糖基的组成：A抗原与B抗原的差别仅在末端糖基不同，O型则缺少该末端糖基，因此血型由个体所携带的糖基转移酶决定。它在细胞膜表面朝向胞外，是免疫系统识别自身与异己的标志之一；作为糖脂参与细胞识别的典型实例，在输血配型与器官移植中具有重要意义。","src":"《第3章 细胞膜与表面（上）》p27；网络补充：baike.baidu.com（ABO血型抗原）"},{"id":"af4fefe1","s":"c","g":"c03","n":"ATP驱动泵（转运ATP酶）","e":"","d":"ATP驱动泵（转运ATP酶）是利用ATP水解成ADP和磷酸所释放的能量跨膜主动运输物质的蛋白，在原核细胞和真核细胞中广泛存在。它与通道蛋白、载体蛋白同属膜转运蛋白，但能逆电化学梯度转运底物，故称泵。按结构与机制可分为P型、V型和F型三类：P型泵在泵循环中自我磷酸化，V型泵位于植物与酵母的液泡膜及动物细胞的内体、溶酶体膜，F型泵位于细菌质膜、线粒体内膜与叶绿体类囊体膜。","src":"《第3章 细胞膜与表面（上）》p67；《第3章 细胞膜与表面（上）》p68"},{"id":"498809d7","s":"c","g":"c03","n":"载体蛋白","e":"Carrier proteins","d":"载体蛋白（Carrier proteins）是介导分子和离子的易化扩散与主动运输的膜蛋白。与形成孔道、让小分子和离子自由通过的通道蛋白不同，载体蛋白须先与被转运物结合，经自身构象改变把底物从膜的一侧送到另一侧，故其转运具有饱和性与特异性，速率低于通道。细胞膜蛋白按功能还可分为通道蛋白、细胞识别蛋白、受体蛋白与酶蛋白；载体蛋白参与葡萄糖、氨基酸与离子的跨膜转运，是细胞维持内环境的重要手段。","src":"《第3章 细胞膜与表面（上）》p24"},{"id":"daf5500e","s":"c","g":"c03","n":"细胞识别蛋白","e":"Cell recognition proteins","d":"细胞识别蛋白（Cell recognition proteins）是细胞膜上能识别特定细胞、参与细胞间相互识别的膜蛋白。它们多暴露于质膜外表面，其糖链或结构可与另一细胞表面的互补分子结合，使细胞能够分辨同类与异类、自身与非自身，从而参与组织构建、免疫识别、精卵结合与病原体识别等过程。按膜蛋白的功能分类，细胞识别蛋白与通道蛋白、载体蛋白、受体蛋白和酶蛋白并列，体现了膜蛋白功能的高度多样性。","src":"《第3章 细胞膜与表面（上）》p24"},{"id":"b790d58b","s":"c","g":"c03","n":"酶蛋白","e":"Enzymatic proteins","d":"酶蛋白（Enzymatic proteins）是催化特定化学反应的膜蛋白。许多酶结合在质膜或细胞器膜上，其活性位点朝向细胞质或膜外空间，可催化水解、磷酸化与氧化还原等反应；有的酶蛋白本身就是受体，配体结合后其酶活性被激活，如受体酪氨酸激酶。按膜蛋白的功能分类，酶蛋白与通道蛋白、载体蛋白、细胞识别蛋白和受体蛋白并列，使膜不仅是分隔内外的屏障，也是代谢反应与信号处理的场所。","src":"《第3章 细胞膜与表面（上）》p24"},{"id":"520f17b2","s":"c","g":"c03","n":"F型泵（ATP合成酶）","e":"F-Class","d":"F型泵（F-Class）即ATP合成酶，是由不同亚基组成、形状像涡轮机的ATP泵，位于细菌质膜、线粒体内膜和叶绿体类囊体膜上。它利用质子跨膜的电化学梯度驱动ATP合成：质子顺梯度流经膜内部分，带动转子旋转，使催化亚基的构象循环改变，把ADP与磷酸合成ATP；在需要时它也可水解ATP、逆梯度泵出质子。它是氧化磷酸化与光合磷酸化中ATP生成的共同装置，在能量转换中处于核心地位。","src":"《第3章 细胞膜与表面（上）》p68；《第3章 细胞膜与表面（上）》p70"},{"id":"96623117","s":"c","g":"c03","n":"P型泵","e":"P-Class","d":"P型泵（P-Class）是在泵循环过程中会自我磷酸化的ATP泵，由多次跨膜蛋白构成，包括很多负责建立和维持跨膜钠离子、钾离子、质子和钙离子梯度的主动运输蛋白。典型代表是钠钾泵，也称钠钾ATP酶，它利用ATP水解的能量逆电化学梯度将钠离子运出细胞、将钾离子运进细胞；当离子浓度梯度增大到电化学梯度的能量高于ATP水解的化学能时，钠钾泵可反向作用，利用离子顺梯度扩散的能量合成ATP。","src":"《第3章 细胞膜与表面（上）》p69"},{"id":"995ae77c","s":"c","g":"c03","n":"受体蛋白","e":"Receptor proteins","d":"受体蛋白（Receptor proteins）是细胞膜上专司识别与结合特定信号分子的膜蛋白，其配体包括激素和细胞因子等。在膜蛋白的功能分类中，它与通道蛋白、载体蛋白、细胞识别蛋白和酶蛋白并列。受体通常（但并非总是）位于细胞表面，信号分子与之结合后使受体活化，进而启动一条或多条胞内信号通路，并由胞内信号蛋白传递，部分通路还产生第二信使。细胞外基质中也含有能结合信号分子的受体蛋白；肥大细胞表面与IgE结合的Fc受体即为一例。","src":"《第3章 细胞膜与表面（上）》p24、p53；MBoC 7e 印刷 p874"},{"id":"9ce50f11","s":"c","g":"c03","n":"V型泵","e":"V-Class","d":"V型泵（V-Class）是ATP驱动泵的一类，其结构与F型泵相似，依靠ATP水解所释放的能量把质子泵入细胞器内部，从而酸化其内腔。它主要分布在植物、酵母和其他真菌的液泡膜上，也存在于动物细胞的内体膜和溶酶体膜上；破骨细胞以及部分肾小管细胞的质膜上也有分布。溶酶体、突触囊泡和植物液泡之所以能维持腔内的酸性环境，正是依赖V型泵持续转运质子；由此建立的跨膜质子梯度又为细胞器内的物质降解、转运和储存提供驱动力。","src":"《第3章 细胞膜与表面（上）》p68、p70"},{"id":"6d8b85ad","s":"c","g":"c03","n":"β桶跨膜结构","e":"","d":"β桶跨膜结构是多次跨膜蛋白穿越脂双层的一种方式：把跨膜的β折叠围成一圈、排列成封闭的桶状，使肽键之间得以充分形成氢键，从而满足在疏水环境中的能量要求。以β折叠方式穿膜所需的氨基酸数目很少，十个或更少即可；桶中β折叠的条数可少至八条、多至二十二条。β桶蛋白的功能多种多样，但分布上主要局限于细菌、线粒体和叶绿体的外膜，是这些膜上孔道蛋白的常见骨架。β桶跨膜结构因而与跨膜α螺旋并列为膜蛋白穿越脂双层的两种基本方式。","src":"《第3章 细胞膜与表面（上）》p23"},{"id":"1be3fa69","s":"c","g":"c03","n":"去垢剂","e":"","d":"去垢剂是一类能破坏脂双层、溶解膜蛋白的试剂。由于膜蛋白的疏水区嵌在脂双层内部，直接分离十分困难，实验中常利用温和去垢剂把膜脂与膜蛋白一同增溶，再经纯化并在适当条件下重建，从而获得保持活性的功能膜蛋白。去垢剂的作用也有选择性：低温下脂筏区域因富含饱和脂肪酸链和胆固醇而结构致密，能抵抗非离子去垢剂的抽提，被称为抗去垢剂膜；用甲基-β-环糊精去除胆固醇后，这些蛋白就变得易于提取。","src":"《第3章 细胞膜与表面（上）》p16、p17、p32"},{"id":"9b233e3e","s":"c","g":"c03","n":"去极化","e":"depolarization","d":"去极化（depolarization）指质膜两侧的电位差向正值方向偏移、即膜内负电性减弱的过程，去极化细胞的膜电位表现为外正内负的程度降低。它通常由门控钠通道开放引起：钠离子顺电化学梯度流入细胞，带入的正电荷使膜进一步去极化，从而开放更多钠通道。在神经和骨骼肌细胞中，足够强度的去极化可触发动作电位；电压门控钾通道的开放则使膜电位回落，完成复极化。可见去极化是电信号产生与传播的起始环节。","src":"《第3章 细胞膜与表面（上）》p83、p84；MBoC 7e 印刷 p662"},{"id":"b9fe5486","s":"c","g":"c03","n":"周围膜蛋白（外周蛋白）","e":"","d":"周围膜蛋白又称外周蛋白，是一类不直接与脂双层作用、而是通过非共价相互作用结合在整合膜蛋白上的膜蛋白。它们可附着于整合膜蛋白朝向胞质或朝向胞外的一侧，也可与膜脂的极性头部以离子键、氢键结合，但并不插入脂双层的疏水核心。由于结合方式较为温和，用高盐或极端pH等处理即可把它们从膜上剥离而不破坏膜结构。周围膜蛋白常作为膜与细胞骨架、信号分子之间的连接环节，参与维持细胞形态和信号转导。","src":"网络补充：MBoC 7e 第10章 膜结构（外周膜蛋白）"},{"id":"556de025","s":"c","g":"c03","n":"复极化","e":"repolarization","d":"复极化（repolarization）指去极化之后膜电位向静息值回落、膜内重新变负的过程。在动作电位中，去极化由电压门控钠通道开放引起，而复极化依赖延迟开放的电压门控钾通道：这些通道同样响应膜去极化而开放，但动力学较慢，只在动作电位的下降相、钠通道已失活时才开放。通道开放后钾离子迅速外流，直到细胞的静息电位在一两毫秒内恢复。钠通道从失活状态恢复所需的时间，则决定了下一个动作电位最早何时能够出现。","src":"《第3章 细胞膜与表面（上）》p83、p84；MBoC 7e 印刷 p664"},{"id":"eadfb165","s":"c","g":"c03","n":"多药抗性蛋白","e":"","d":"多药抗性蛋白是ABC转运蛋白的一种。ABC转运蛋白是膜转运蛋白中的一个大家族，能跨膜转运无机离子、氨基酸、单糖、多糖、小肽甚至蛋白质等多种分子。它有两个高度保守的ATP结合区，结合ATP可使该区域二聚化，水解ATP又使其解聚；胞内发生的这种结构变化传递到跨膜区，使蛋白构象循环改变，把底物结合位点交替地朝向膜内和膜外。金黄色葡萄球菌中的多药抗性蛋白即展示了结合ATP后的构象，借此把多种药物泵出细胞。","src":"《第3章 细胞膜与表面（上）》p71"},{"id":"21e22d38","s":"c","g":"c03","n":"成斑与成帽（成帽效应）","e":"patching / capping","d":"成斑与成帽是膜蛋白在膜平面内自由侧向扩散的直观表现。用荧光标记的抗体与细胞表面抗原结合，使相邻的抗原分子交联；低温下膜蛋白仍均匀分布，温度升高后这些交联的膜蛋白聚集成局限的斑块，即所谓成斑；随后斑块在细胞的一端汇集形成帽状结构，即成帽。该过程依赖细胞骨架、尤其是微丝的活动。成斑与成帽不仅证明膜蛋白能在脂双层中侧向移动，也被用于研究膜受体聚集与信号启动之间的关系。","src":"网络补充：MBoC 7e 第10章 膜结构（成斑与成帽）"},{"id":"eb4122aa","s":"c","g":"c03","n":"抗去垢剂膜","e":"detergent-resistant membranes（DRMs）","d":"抗去垢剂膜（DRMs）指低温下能抵抗非离子去垢剂抽提的膜区域。这类区域富含具有较长饱和脂肪酸链的脂质，分子间作用力较强，结构致密，介于无序液体与液晶之间，故称有序液体。它像一个蛋白质停泊的平台，与膜的信号转导和蛋白质分选均有密切关系。其中的胆固醇起胶水般的作用，对含饱和脂肪酸链的鞘磷脂亲和力很高；用甲基-β-环糊精去除胆固醇后，这些抗去垢剂的蛋白就变得易于提取。","src":"《第3章 细胞膜与表面（上）》p32"},{"id":"d2b0cfc5","s":"c","g":"c03","n":"整合膜蛋白（整合蛋白）","e":"","d":"整合膜蛋白是膜蛋白的一大类，指通过脂质基团或疏水多肽链插入脂双层疏水中心的膜蛋白。它与不直接作用于脂双层、仅通过非共价相互作用结合在整合膜蛋白上的周围膜蛋白相对。整合膜蛋白的疏水段埋在脂双层内，与脂质的疏水尾部相互作用，亲水部分则伸向膜两侧的水相；其中穿越脂双层、向胞外和胞内伸展者称跨膜蛋白，可分为单次跨膜和多次跨膜两类。整合膜蛋白多承担运输、受体和酶等功能，须借助去垢剂才能从膜上分离。","src":"《第3章 细胞膜与表面（上）》p18、p20"},{"id":"6071ac0e","s":"c","g":"c03","n":"水通道","e":"","d":"水通道是允许水分子高效穿膜的通道蛋白。其选择性的结构基础在于孔道壁的化学性质：孔道壁一边是顺序排列的羰基氧，另一边是疏水性氨基酸；这样孔道仅能容许水分子互相形成氢键、成单列通过。孔道壁另一边的疏水性氨基酸无法与单独的离子形成氢键，水化的离子因无法补偿脱水造成的能量损失而难以进入。水通道因此只让水通过而排斥离子，在需要大量转运水的细胞中尤为丰富，可显著加快水的跨膜移动。","src":"《第3章 细胞膜与表面（上）》p80"},{"id":"42b2a4d2","s":"c","g":"c03","n":"流动镶嵌模型","e":"","d":"流动镶嵌模型是1972年由Singer和Nicolson提出的生物膜结构模型。其要点是：膜上脂质分子排成双层，构成生物膜的骨架；蛋白质分子以不同方式镶嵌或联结于脂双层上；膜的两侧结构不对称；膜脂和膜蛋白具有一定的流动性。此前关于膜结构的假说多达五十种，该模型因能同时解释膜的流动性、不对称性和膜蛋白的分布等特点而被广泛接受。后来的脂筏模型认为膜上特殊脂质能形成稍厚的微区，是对流动镶嵌模型的补充。","src":"《第3章 细胞膜与表面（上）》p30、p31"},{"id":"4c8af692","s":"c","g":"c03","n":"渗透","e":"osmosis","d":"渗透（osmosis）指水透过半透膜、从溶质浓度低的区域向溶质浓度高的区域流动的过程。从自由能角度看，水的渗透同样是从自由能高处向自由能低处移动；若考虑溶质浓度，水则从溶质浓度低处流向溶质浓度高处。由于所有生物膜对水都有一定通透性，细胞体积会因渗透梯度的存在而在数分钟内达到平衡。除直接扩散外，一些原核和真核细胞的质膜上还嵌有水通道，使水能更快速地跨膜移动。对于多数动物细胞而言，渗透在细胞体积的调节中只起次要作用。","src":"《第3章 细胞膜与表面（上）》p61；MBoC 7e 印刷 p652"},{"id":"69b99e73","s":"c","g":"c03","n":"甘油磷脂","e":"phosphoglyceride","d":"甘油磷脂（phosphoglyceride）是磷脂的一大类，与鞘磷脂并列，是生物膜脂质的重要组成。磷脂是膜上含量最丰富的脂质，其疏水尾部通常是两条含十四到二十四个碳原子的碳氢链，其中一条通常饱和，另一条通常含多个顺式双键，每个顺式双键使碳氢链产生弯折。碳氢链的长度与饱和程度影响磷脂分子的堆积方式，进而影响膜上分子的运动，即膜的流动性。甘油磷脂以甘油为骨架，是构成脂双层的主要磷脂类型。","src":"《第3章 细胞膜与表面（上）》p10；MBoC 7e Glossary（PDF p1457）"},{"id":"8ec63401","s":"c","g":"c03","n":"生物膜","e":"biomembrane","d":"生物膜是细胞膜与各种细胞内膜结构的统称。其基本结构是脂质分子形成的双分子层，大多数动物细胞膜的干重有一半是脂质；脂质分子具双亲性，既有极性的亲水头部，也有非极性的疏水尾部，这一特征使它们能自发形成双分子层。生物膜的脂质主要有磷脂、糖脂和胆固醇。生物膜的功能包括：界定细胞与细胞器的边界，为特定功能提供场所，调节物质运输，提供检测外界信号所需的受体，以及为细胞间接触、通讯和黏附提供机制。","src":"《第3章 细胞膜与表面（上）》p6、p9"},{"id":"fce89c71","s":"c","g":"c03","n":"电化学梯度","e":"electrochemical gradient","d":"电化学梯度（electrochemical gradient）由跨膜浓度梯度与电势能梯度共同构成。生物膜两侧大部分分子和离子的分布并不均匀，常存在跨膜的浓度差异；对于带电荷的离子或分子，由于膜电位的存在，膜两侧还存在电势能梯度。二者合起来即为电化学梯度，它是驱动分子和离子跨膜运输的一种能量。顺电化学梯度运输不需额外供能，称被动运输；逆着电化学梯度运输则需提供能量，称主动运输。","src":"《第3章 细胞膜与表面（上）》p57、p59；MBoC 7e Glossary（PDF p1454）"},{"id":"137e66f2","s":"c","g":"c03","n":"电压门控通道","e":"Voltage-Gated Ion Channels","d":"电压门控通道（Voltage-Gated Ion Channels）是一类开放与关闭受膜电位控制的离子通道。其跨膜α螺旋上富含特征性的带正电荷氨基酸，能感应跨膜电位的变化，是电压敏感的螺旋。通道关闭时该螺旋阻碍并封闭通道；膜发生去极化时膜电位升高，电压敏感螺旋在膜上朝胞外方向倾斜滑动，把构象变化传递给通道α螺旋，使其构象改变而开放通道。神经和肌肉细胞的动作电位即由电压门控钠通道开放引发，随后由电压门控钾通道完成复极化。","src":"《第3章 细胞膜与表面（上）》p82、p84；MBoC 7e 印刷 p675"},{"id":"5e02ef12","s":"c","g":"c03","n":"相变","e":"phase transition","d":"相变（phase transition）指在不同温度下膜脂所处状态的改变。生理条件下膜脂多呈拟液态；温度下降至某一点则变为晶态，一定温度下晶态又可熔解再变为液晶态，这一临界温度称相变温度。不同的膜脂因成分不同而各有其相变温度。相变会打破脂双层的均一性，使其分成性质不同的畴区。膜脂的相变受脂肪酸链长度与不饱和程度影响：链较短或含双键时相变温度降低，膜在较低温度下仍可保持流动性。","src":"《第3章 细胞膜与表面（上）》p41、p42；MBoC 7e 印刷 p611"},{"id":"56156470","s":"c","g":"c03","n":"相变温度","e":"transition temperature","d":"相变温度（transition temperature）是膜脂由拟液态转变为晶态、或晶态熔解为液晶态的临界温度。生理条件下膜脂多呈拟液态，温度下降至某一点则变为晶态。不同的膜脂因成分不同而各有其相变温度。脂肪酸链较短或含有双键时相变温度降低，因为较短的链减少了同一层或双层之间碳氢链的相互作用，顺式双键使碳氢链产生弯折而难以相互堆积。胆固醇在相变温度以上限制脂酰链末端的运动，在相变温度以下则增加脂酰链的运动，从而调节膜的流动性。","src":"《第3章 细胞膜与表面（上）》p41、p43"},{"id":"c015afac","s":"c","g":"c03","n":"短杆菌肽A","e":"Gramicidin A","d":"短杆菌肽A（Gramicidin A）是由微生物产生的一种脂溶性抗生素，属于形成通道的离子载体。它是由十五个氨基酸组成的线性肽，两个分子在一起即可形成跨膜的通道。该通道能有选择地让单价阳离子按电化学梯度通过膜，可运输的阳离子依次为氢离子、铵离子、钾离子、钠离子和锂离子；与可动离子载体不同，它并不显著提高运输速度。短杆菌肽A因此常被用作研究跨膜离子通道选择性的模型。","src":"《第3章 细胞膜与表面（上）》p90"},{"id":"33ba6869","s":"c","g":"c03","n":"磷脂","e":"","d":"磷脂是膜上含量最丰富的脂质，其疏水尾部通常是两条含十四到二十四个碳原子的碳氢链，其中一条通常饱和，另一条通常含多个顺式双键，每个顺式双键使碳氢链产生弯折。碳氢链的长度与饱和程度影响磷脂分子的堆积方式，进而影响膜上分子的运动，即膜的流动性。磷脂可分为甘油磷脂和鞘磷脂两类；哺乳动物膜中卵磷脂与鞘磷脂合计约占整个膜脂的一半，两者含量的比值对膜脂的流动性有明显影响。","src":"《第3章 细胞膜与表面（上）》p10、p44"},{"id":"963b48b7","s":"c","g":"c03","n":"离子载体","e":"Ionophores","d":"离子载体（Ionophores）是由微生物产生的脂溶性抗生素。它们能插入膜中，通过结合并运载离子或形成通道的方式提高膜对特定离子的通透性，可分为可动离子载体和形成通道的离子载体两类。缬氨霉素是十二个氨基酸组成的环状肽，属可动离子载体，插入脂质体后能特异性运输钾离子，使运输速率提高十万倍；短杆菌肽A则是十五个氨基酸的线性肽，两个分子共同形成跨膜通道。离子载体因此常被用于研究膜的通透性与电化学梯度。","src":"《第3章 细胞膜与表面（上）》p90"},{"id":"d4932ddd","s":"c","g":"c03","n":"离子通道","e":"","d":"离子通道是运输特定无机离子（如钠、钾、钙、氯等）的通道蛋白。它形成跨膜的亲水性孔道，开放时离子顺电化学梯度快速通过，一个开放的通道每秒可通过一亿个离子，比转运蛋白快十万倍；但它不能利用能量进行主动运输，只能进行被动运输。离子通道的孔径很小，只有大小合适、带特定电荷的离子才能通过，此即选择性通透；通道还具有门控特性，只在特定刺激下开放，持续刺激后多数会关闭而进入失活状态。","src":"《第3章 细胞膜与表面（上）》p76、p77、p85"},{"id":"e50ae394","s":"c","g":"c03","n":"简单扩散","e":"","d":"简单扩散是分子顺电化学梯度穿膜、不需要消耗额外能量的被动运输方式之一，与易化扩散同属被动运输。严格地说，扩散是物质从自由能高的一侧向自由能低的一侧流动；若考虑溶质浓度，则是由浓度高处向浓度低处移动。简单扩散不需膜蛋白协助，其扩散速率取决于跨膜的浓度梯度、膜两侧的电位差、分子的疏水性（脂水分配系数）以及分子的大小，因而脂溶性小分子较易穿过脂双层。水分子虽可直接经简单扩散穿膜，但其速度常不足以满足细胞的需要。","src":"《第3章 细胞膜与表面（上）》p59、p60"},{"id":"0daca5ad","s":"c","g":"c03","n":"糖基化磷脂酰肌醇（GPI）锚点","e":"GPI anchors","d":"糖基化磷脂酰肌醇锚点是膜蛋白结合在脂双层上的一种锚定方式。有些蛋白并不插入脂双层，也不通过脂肪酸链锚定，而是经转酰氨基酶的作用，在内质网中被切去疏水片段后接上一个预先形成的GPI锚点，靠这一糖脂结构附着在质膜外侧。许多质膜蛋白以这种方式修饰，由于只通过GPI锚点附着在膜外，它们可在磷脂酶被激活时以可溶形式从细胞上释放；GPI锚点还参与把部分质膜蛋白导向脂筏等特化区域。","src":"《第3章 细胞膜与表面（上）》p18、p19；MBoC 7e 印刷 p712"},{"id":"d35a4ff0","s":"c","g":"c03","n":"糖脂","e":"","d":"糖脂是含有糖的脂质分子。在所有的细胞膜表面都发现有糖脂，它广泛存在于脂双层的外层，通常占膜外层脂质分子的百分之五。糖脂的不对称分布是由于在高尔基器腔中给脂质分子添加糖基，当它们被转运到细胞膜上时，糖基就暴露在细胞表面。红细胞质膜上的鞘糖脂是ABO血型系统的血型抗原，说明糖脂的糖链参与细胞识别，是细胞表面重要的信息分子。糖脂的糖链朝向细胞外，与糖蛋白的糖链共同构成细胞表面的糖被。","src":"《第3章 细胞膜与表面（上）》p11、p27"},{"id":"d84e97f2","s":"c","g":"c03","n":"糖蛋白","e":"glycoprotein","d":"糖蛋白（glycoprotein）是带有一条或多条共价连接于氨基酸侧链的糖链或寡糖链的蛋白质。真核细胞表面富含碳水化合物的区域即糖被，其多糖层的碳氢链以寡糖形式共价结合在膜蛋白、脂质和分泌到胞外的蛋白上，形成糖蛋白；也以长多聚糖链的形式结合在膜蛋白上形成蛋白多糖。多数分泌蛋白以及暴露在质膜外表面的蛋白都是糖蛋白。糖链伸展在细胞外，参与细胞识别、黏附与保护，并使细胞之间保持距离。","src":"《第3章 细胞膜与表面（上）》p25；MBoC 7e Glossary（PDF p1458）"},{"id":"0d87979e","s":"c","g":"c03","n":"糖被（胞衣）","e":"glycocalyx / cell coat","d":"糖被又称胞衣，指真核细胞表面富含碳水化合物的区域。其多糖层的碳氢链以寡糖形式共价结合在膜蛋白、膜脂以及分泌到胞外的蛋白上，形成糖蛋白；也以长多聚糖链的形式共价结合于膜蛋白，形成蛋白多糖。糖被的功能之一是保护细胞免于机械或者化学的损伤，同时使细胞之间保持距离，防止不必要的蛋白相互作用。由于糖链伸展在细胞外表面，糖被还参与细胞识别、黏附以及细胞与环境的通讯。它与胞外基质中的糖蛋白一起，参与维持细胞间的连接以及细胞与环境的联系。","src":"《第3章 细胞膜与表面（上）》p25"},{"id":"6bfaa9a4","s":"c","g":"c03","n":"细胞膜（质膜）","e":"cell membrane / plasma membrane","d":"细胞膜又称质膜，是包被细胞的外围边界，由脂质与蛋白质通过非共价相互作用组装成的疏水性薄层结构。其骨架是磷脂、糖脂和胆固醇等双亲性脂质分子自发形成的双分子层，构成水溶性分子跨膜的屏障；蛋白质以不同方式镶嵌或联结于脂双层上，承担跨膜物质交换、能量转换和信号传递。细胞膜界定了细胞与环境的界限，维持细胞内环境的稳定，并为物质运输、信号识别和细胞间接触提供场所。细胞膜具有不对称性，膜脂与膜蛋白在两层中的分布不同，并保持一定的流动性。","src":"《第3章 细胞膜与表面（上）》p4、p6、p9"},{"id":"cf8fb959","s":"c","g":"c03","n":"细菌视紫红质","e":"bacteriorhodopsin","d":"细菌视紫红质（bacteriorhodopsin）是古噬盐菌紫膜上唯一的一种蛋白质，紫膜即其质膜上一段特化的膜区。该蛋白折叠成七个紧密排列的跨膜α螺旋，并结合一个吸收光的生色团——视黄醛；视黄醛是维生素A的乙醛化形式，与蛋白上的精氨酸侧链共价结合，并使膜呈紫色。吸收一个单光子后视黄醛改变形状，引起蛋白一系列构象变化，把一个质子从细胞内转移到细胞外；强光下每个分子每秒可泵出几百个质子，由此建立的质子梯度可被F型ATP泵用于合成ATP。","src":"《第3章 细胞膜与表面（上）》p74；MBoC 7e 印刷 p626"},{"id":"7aae9ef2","s":"c","g":"c03","n":"缬氨霉素","e":"Valinomycin","d":"缬氨霉素（Valinomycin）是由微生物产生的一种脂溶性抗生素，属于离子载体。其分子为仅由十二个氨基酸组成的环状肽，是一种可动离子载体：它结合钾离子后在脂双层中穿梭，把离子从膜的一侧运到另一侧。将缬氨霉素插入脂质体后，它能特异性地运输钾离子，使钾离子的运输速率提高十万倍。正因为对钾离子高度专一并能显著提高膜的通透性，缬氨霉素常被用作研究膜电位与钾离子梯度的工具。","src":"《第3章 细胞膜与表面（上）》p90"},{"id":"93f6ee7b","s":"c","g":"c03","n":"胆固醇","e":"","d":"胆固醇是动物细胞质膜上含量特别多的一类脂质，其分子具有一个结构固定的环，环上连着一个极性羟基和一条短的非极性碳氢链。它可固定周围磷脂分子起始部分碳氢链上少数亚甲基的运动，降低脂双层该区域的可变形性，从而减弱对小水溶性分子的可通透性，增强脂双层的通透屏障性质。在相变温度以上，胆固醇限制磷脂脂酰链末端的运动；在相变温度以下，它又能增加脂酰链的运动，防止碳氢链聚合与结晶态的形成。","src":"《第3章 细胞膜与表面（上）》p12、p43"},{"id":"b7b90fdb","s":"c","g":"c03","n":"脂筏（脂筏模型）","e":"","d":"脂筏是生物膜上一些特殊脂质聚集形成的微区，大小约七十纳米，比周围膜稍厚，因能带着大量膜蛋白像筏子一样漂浮、集中完成复杂功能而得名。脂筏富含胆固醇与鞘磷脂，胆固醇像胶水一样对含饱和脂肪酸链的鞘磷脂亲和力高，使该区域结构致密，介于无序液体与液晶之间，故在低温下能抵抗非离子去垢剂的抽提。脂筏被视为蛋白质停泊的平台，与信号转导和蛋白质分选密切相关；小的脂筏可聚集扩大，使受体与配体相遇。","src":"《第3章 细胞膜与表面（上）》p31、p32"},{"id":"e2afdcdf","s":"c","g":"c03","n":"膜的流动性","e":"","d":"膜的流动性指脂双层中的脂质处于不断运动的状态，使膜表现为二维流体。脂质分子能在同一层内快速侧向扩散，也可发生弯折运动、绕自身长轴快速旋转；极少数情况下可从一层翻转到另一层，胆固醇则是能较快翻转的例外。膜的流动性受组分与温度的影响，并取决于磷脂碳氢链的长度与不饱和程度。流动性是膜行使功能的必要条件，它使膜上分子能快速扩散，并参与细胞运动、生长、分裂和分泌等过程。","src":"《第3章 细胞膜与表面（上）》p38、p41"},{"id":"3e77a497","s":"c","g":"c03","n":"膜脂的不对称性","e":"","d":"膜脂的不对称性指脂双层两个单层的脂质成分存在明显差异。以人红细胞膜为例，几乎所有头部基团含胆碱的磷脂分子，即卵磷脂和鞘磷脂，都位于靠外的单层；而含末端氨基的磷脂，即磷脂酰乙醇胺和磷脂酰丝氨酸，位于内层。由于带负电荷的磷脂酰丝氨酸位于内层，两层之间呈现明显的电荷差异。这种不对称分布由脂质的合成与转运过程维持，在把胞外信号转换为胞内信号以及区分活细胞与死细胞时具有作用。","src":"《第3章 细胞膜与表面（上）》p33"},{"id":"a53803ee","s":"c","g":"c03","n":"膜蛋白","e":"","d":"膜蛋白是能够与膜上脂双层直接或者间接结合的蛋白质的统称，膜的特定功能主要由膜蛋白完成。按结合方式可分为整合膜蛋白与周围膜蛋白：前者通过脂质基团或疏水多肽链插入脂双层的疏水中心，后者不直接与脂双层作用，而通过非共价相互作用结合在整合膜蛋白上。穿越脂双层、向胞外和胞内伸展的称跨膜蛋白，其跨膜段多由非极性残基组成并形成α螺旋。膜蛋白承担物质运输、信号接收、细胞识别和酶催化等功能。","src":"《第3章 细胞膜与表面（上）》p20、p21"},{"id":"2686caa4","s":"c","g":"c03","n":"膜蛋白的不对称性","e":"","d":"膜蛋白的不对称性包括分布的不对称和方向的不对称。膜蛋白在脂双层上呈不对称分布，并具有确定的方向性，其亲水区朝向膜哪一侧由合成与转运过程决定；许多膜蛋白还在膜外侧被糖基化。此外，许多细胞能在连续的脂双层膜上把膜蛋白限制在特定区域，而在该区域内这些蛋白仍可自由扩散。对上皮细胞而言，这种不对称分布是必需的，它使细胞顶端面与基底面得以执行不同的功能。膜蛋白一旦插入脂双层便难以翻转，其不对称性因而得以长期维持。","src":"《第3章 细胞膜与表面（上）》p36"},{"id":"ebef659d","s":"c","g":"c03","n":"蛋白多糖","e":"proteoglycan","d":"蛋白多糖（proteoglycan）是由一条或多条糖胺聚糖链共价连接在核心蛋白上形成的分子。细胞表面的多糖层除以寡糖形式形成糖蛋白外，也以长多聚糖链的形式共价结合在膜蛋白上形成蛋白多糖。它与糖蛋白的区别在于糖链的性质、数量与排列：蛋白多糖至少有一条糖链是糖胺聚糖，糖链长而不分支，可占分子质量的绝大部分。蛋白多糖是胞外基质的组成部分，也是一种整合膜蛋白，参与基质构建与细胞间相互作用。","src":"《第3章 细胞膜与表面（上）》p25；MBoC 7e 印刷 p1131"},{"id":"828a6fc2","s":"c","g":"c03","n":"视黄醛","e":"retinal","d":"视黄醛（retinal）是细菌视紫红质中吸收光的生色团，是维生素A的乙醛化形式。它与视紫红质蛋白上的一个精氨酸侧链共价结合，使紫膜呈现紫色。当视黄醛被一个单光子激活时，它改变形状，并引起蛋白内部一系列的构象变化，最终使一个质子从细胞内转移到细胞外。脊椎动物光感受细胞中的视紫红蛋白也含视黄醛类生色团，吸收光子后同样发生构象改变并触发下游信号，可见视黄醛是光信号转变为蛋白构象变化的共同起点。","src":"《第3章 细胞膜与表面（上）》p74；MBoC 7e 印刷 p154"},{"id":"307e4e9f","s":"c","g":"c03","n":"超极化","e":"Hyperpolarization","d":"超极化（Hyperpolarization）指质膜两侧的电位差向更负的数值偏移，即膜内负电性进一步增强的过程，方向与去极化相反。视觉信号转导中可见其典型表现：光激活盘膜上的视紫红质后，胞质内环鸟苷酸浓度下降，质膜上的阳离子通道关闭，膜电位变得更负，于是光引起超极化，进而抑制突触信号的传递。超极化使细胞的兴奋性降低，是神经元整合抑制性输入、调节放电频率的重要方式。","src":"MBoC 7e Glossary（PDF p1459）；MBoC 7e 印刷 p906"},{"id":"39a0a37d","s":"c","g":"c03","n":"跨膜α螺旋","e":"","d":"跨膜α螺旋是大多数跨膜蛋白跨膜区的常见结构形式：多肽链在膜内盘绕成螺旋，使肽键之间形成最多的氢键，从而在疏水环境中保持稳定。含有二十至三十个氨基酸、疏水性较高的肽段即可按α螺旋的方式跨膜。跨膜α螺旋不仅仅把蛋白锚定在脂双层上，螺旋之间还可发生特异性的强相互作用，参与蛋白的折叠与功能。电压门控通道中带正电荷的跨膜螺旋还能感受膜电位变化，通过倾斜滑动把构象变化传给通道。","src":"《第3章 细胞膜与表面（上）》p22、p82"},{"id":"41bcc50c","s":"c","g":"c03","n":"跨膜蛋白","e":"","d":"跨膜蛋白是穿越脂双层、向胞外和胞内伸展的典型膜蛋白。它具有双亲性，同时含有疏水区和亲水区：疏水区穿过膜，在脂双层内与脂质的疏水尾部相互作用，亲水区则在膜的两边暴露于水溶液。其跨膜段主要由非极性残基组成，在疏水的跨膜区，极性的肽键趋向于相互形成氢键。按多肽链跨膜次数，可分为单次跨膜蛋白和多次跨膜蛋白；跨膜区多形成α螺旋，也有以β桶方式跨膜的。跨膜蛋白承担运输、受体和酶等功能。","src":"《第3章 细胞膜与表面（上）》p21"},{"id":"74575fd1","s":"c","g":"c03","n":"选择性通透","e":"","d":"选择性通透指离子通道只允许大小合适、带特定电荷的离子通过的特性。离子通道的孔径都很小，通道壁的化学性质决定了哪些离子能够通过，因此同一类通道对不同离子的通透能力差别很大，例如钾通道对钾离子的通透速率是钠离子的一万倍。这种高度选择性来自通道内部与离子相互作用的位点，使离子在脱水后能得到恰当的配位补偿。选择性通透是神经细胞产生电信号、细胞维持跨膜离子梯度的分子基础。","src":"《第3章 细胞膜与表面（上）》p77"},{"id":"e233d84c","s":"c","g":"c03","n":"通道蛋白","e":"Channel proteins","d":"通道蛋白（Channel proteins）是一类形成跨膜亲水性孔道、让特定溶质顺浓度梯度快速穿膜的膜蛋白。与转运蛋白不同，通道蛋白与溶质分子的结合能力很弱，通道开放时允许特定的溶质分子通过，运输速率比转运蛋白高四到八个数量级；一个开放的离子通道每秒可通过一亿个离子。由于主要运输钠、钾、钙、氯等离子，它们也称离子通道。通道蛋白不能利用能量进行主动运输，只能进行顺浓度梯度的被动运输。","src":"《第3章 细胞膜与表面（上）》p24、p56、p76；MBoC 7e 印刷 p618"},{"id":"95dd2836","s":"c","g":"c03","n":"钠钾泵（钠钾ATP酶）","e":"","d":"钠钾泵是P型泵的一种，即钠钾ATP酶，利用ATP水解所释放的能量逆电化学梯度把钠离子运出细胞、把钾离子运进细胞。它每水解一分子ATP，便通过自身磷酸化与去磷酸化引起的构象循环完成一次转运，使钠钾两种离子按相反方向跨膜移动。由此建立的钠、钾离子梯度可维持细胞内高钾低钠的状态和膜电位，为营养物质的继发性主动转运、细胞体积调节提供驱动力；当离子梯度足够大时，它也可反向工作而合成ATP。","src":"网络补充：MBoC 7e 第11章 膜转运（钠钾泵）"},{"id":"bff402c2","s":"c","g":"c03","n":"门控特性","e":"","d":"门控特性指离子通道并非持续开放，而是需要响应特定刺激才开放的性质。通道除开放和关闭两种状态外，还存在失活状态：如果持续给予电化学刺激，大多数通道会关闭而进入不应期或失活状态，为刺激过后的重新开放作准备。门控使细胞能把外界刺激转换为通道开放概率的变化，从而精确控制离子的流动。按刺激类型，通道可分为电压门控通道和配体门控通道，前者感受膜电位变化，后者结合特定配体后开放。","src":"《第3章 细胞膜与表面（上）》p81"},{"id":"1294b929","s":"c","g":"c03","n":"静息电位","e":"Resting Potential（RP）","d":"静息电位（Resting Potential，RP）指细胞未受刺激时存在于细胞膜内外两侧、外正内负的电位差。神经元的静息电位约为负六十毫伏，即膜内为负。它的形成基础是钾离子外流，推动钾离子外流的动力是膜内外的钾离子浓度差；静息状态下非门控钾通道部分开放，使膜对钾离子的通透性较高。由于膜很薄，这一电位差在膜上形成极强的电场，可影响膜蛋白中带电荷的基团和极性键的状态，进而影响通道的开关。","src":"《第3章 细胞膜与表面（上）》p82、p84"},{"id":"4f9f7892","s":"c","g":"c03","n":"鞘磷脂","e":"sphingolipid","d":"鞘磷脂是磷脂的一大类，与甘油磷脂并列，是生物膜脂质的重要成分。其脂肪酸链的饱和程度高，相变温度也高，因此鞘磷脂含量高的膜流动性较小；哺乳动物膜中卵磷脂与鞘磷脂合计约占整个膜脂的一半。鞘磷脂主要位于脂双层的外层，且大部分参与形成脂筏；脂筏中的胆固醇对含饱和脂肪酸链的鞘磷脂亲和力很高，而对不饱和脂肪酸链的亲和力低。此外，红细胞质膜上的鞘糖脂还是ABO血型系统的血型抗原。","src":"《第3章 细胞膜与表面（上）》p10、p32、p44；MBoC 7e 印刷 p605"},{"id":"d9e3af6b","s":"c","g":"c05","n":"A位点","e":"A site","d":"A位点又称氨基酸位点，是核糖体上接受氨酰-tRNA的部位，主要分布在大亚基上。在肽链延伸过程中，携带下一个氨基酸的氨酰-tRNA通过其反密码子与mRNA上处于A位点的密码子配对而进入A位点，此时P位点与A位点各结合一个相邻的tRNA。随后P位点上肽链的羧基端从tRNA上释放，转移到A位点氨基酸的游离氨基上，形成新的肽键。A位点是延伸循环的第一步；E位点被占据时，A位点与氨酰-tRNA的亲和力会下降。","src":"《第4章 核糖体》p29、p41；MBoC 7e 印刷 p368"},{"id":"e408f474","s":"c","g":"c05","n":"E位点","e":"E site（exit site）","d":"E位点即退出位点，是脱氨酰-tRNA离开A位点之后、完全从核糖体释放之前的中间停靠点，只是一个暂时的停留处。当E位点被占据时，A位点与氨酰-tRNA的亲和力降低，可防止另一个氨酰-tRNA过早结合；直到核糖体准备就绪、E位点空出，才会接受下一个氨酰-tRNA。E位点与A位点、P位点共同构成核糖体的功能活性位点，保证tRNA按顺序进入、参与肽键形成并退出，使延伸循环有序进行。","src":"《第4章 核糖体》p31"},{"id":"932513e9","s":"c","g":"c05","n":"P位点","e":"P site","d":"P位点又称肽酰基位点，主要分布在大亚基上，是与延伸中的肽酰-tRNA结合的部位，也是释放tRNA的部位。肽链延伸时，P位点上的tRNA共价连接着已合成肽链的羧基端，A位点则接受携带下一个氨基酸的氨酰-tRNA；两个位点位置相邻，使两个tRNA的反密码子能与mRNA上相邻的密码子配对，从而维持正确的阅读框。随后肽链转移到A位点氨基酸上形成肽键，再经转位使核糖体沿mRNA向前移动。","src":"《第4章 核糖体》p30；MBoC 7e 印刷 p368"},{"id":"2699399c","s":"c","g":"c05","n":"SD序列","e":"SD sequence","d":"SD序列是原核mRNA 5′端一段富含嘌呤的短核苷酸序列。在原核生物核糖体中，与mRNA的结合位点位于16S rRNA的3′端；mRNA上这段与16S rRNA 3′端序列互补的序列即为SD序列，一般位于起始密码AUG上游五至十个碱基处。通过这种碱基互补配对，mRNA得以在小亚基上正确定位，翻译起始得以进行。真核生物没有SD序列，其mRNA与核糖体小亚基的结合主要依赖5′端甲基化帽子结构的识别。","src":"《第4章 核糖体》p32"},{"id":"ec55b7b9","s":"c","g":"c05","n":"rRNA（核糖体RNA）","e":"ribosomal RNA","d":"rRNA即核糖体RNA，是核糖体的主要组成成分，占细胞总RNA的绝大部分。核糖体无膜结构，由核糖体蛋白和rRNA构成：原核生物rRNA约占三分之二，真核约占五分之三；原核大亚基含23S与5S rRNA，小亚基含16S rRNA，真核大亚基含28S、5.8S与5S rRNA，小亚基含18S rRNA。rRNA虽为单链，但内部可形成双链区，并具有肽酰转移酶活性，能催化肽键形成，因此蛋白质合成的功能主要依靠rRNA完成。","src":"《第4章 核糖体》p18、p61；MBoC 7e Glossary（PDF p1473）"},{"id":"4f8946b1","s":"c","g":"c05","n":"内部核糖体进入位点","e":"internal ribosome entry site（IRES）","d":"内部核糖体进入位点是mRNA上的一段特殊序列与结构，能使核糖体不依赖5′端帽子结构而直接结合到mRNA内部并起始翻译。真核生物mRNA通常依靠5′端甲基化帽子被识别而与核糖体小亚基结合，内部核糖体进入位点则提供了另一种起始方式，因此常被用于在同一mRNA上翻译两个基因产物；某些病毒RNA以及应激状态下的细胞mRNA也利用这种方式起始翻译，使蛋白质合成不完全依赖于帽子结构。","src":"网络补充：MBoC 7e 第6章 翻译起始（IRES）"},{"id":"d303abea","s":"c","g":"c05","n":"多聚核糖体","e":"polyribosomes / polysome","d":"多聚核糖体是多个甚至几十个核糖体串连在同一条mRNA分子上、高效进行肽链合成时形成的核糖体与mRNA聚合体。核糖体在细胞内并不是单个独立地执行功能，而是以这种具有特殊功能与形态结构的聚合体存在。其生物学意义在于：无论多肽的分子量大小或mRNA的长短如何，单位时间内所合成的多肽分子数目都大体相等；以多聚核糖体的形式合成多肽，对mRNA的利用及其浓度的调控更为经济和有效。","src":"《第4章 核糖体》p55"},{"id":"38f0fa0a","s":"c","g":"c05","n":"核糖体蛋白","e":"ribosomal protein","d":"核糖体蛋白是核糖体的蛋白质成分。核糖体无膜结构，由rRNA与核糖体蛋白构成，真核生物rRNA约占五分之三、蛋白约占五分之二，原核生物rRNA约占三分之二、蛋白约占三分之一。核糖体蛋白种类繁多：原核大亚基三十一种、小亚基二十一种，真核大亚基四十九种、小亚基三十三种。它们对核糖体的合成与稳定起辅助作用，并可能对核糖体的功能起微调作用；去除部分核糖体蛋白并不能完全阻止蛋白质的合成。","src":"《第4章 核糖体》p18、p33；MBoC 7e 印刷 p354"},{"id":"6b56f244","s":"c","g":"c05","n":"氨酰tRNA","e":"aminoacyl-tRNA","d":"氨酰-tRNA是氨基酸与对应tRNA结合形成的产物。氨基酸本身不识别密码子，不能直接反应生成肽链，也不能直接到达核糖体，需借助tRNA转运。在胞质中，特异性的氨酰-tRNA合成酶催化氨基酸的羧基与其对应tRNA 3′端的羟基反应，生成含高能酯键的氨酰-tRNA，反应消耗ATP。该反应具有高度专一性，每一种氨基酸都有专一的氨酰-tRNA，从而保证氨基酸按密码子所决定的位置准确掺入肽链。","src":"《第4章 核糖体》p35；MBoC 7e 印刷 p362"},{"id":"0464516f","s":"c","g":"c05","n":"沉降系数","e":"sedimentation coefficient（s）","d":"沉降系数是描述颗粒在离心场中沉降行为的物理量，单位以斯维德伯格s表示，数值越大表示颗粒沉降越快。它是核糖体分类的重要依据：原核生物核糖体为70S，由50S大亚基与30S小亚基组成；真核生物核糖体为80S，由60S与40S亚基组成；线粒体核糖体为55S，由35S与25S亚基组成。沉降系数并不等于各组分之和，因为颗粒的形状与密度同样影响沉降行为，例如大肠杆菌小亚基装配中颗粒可由21S变为26S。","src":"《第4章 核糖体》p15、p17、p26"},{"id":"44641d18","s":"c","g":"c05","n":"游离核糖体","e":"free ribosome","d":"游离核糖体是游离于细胞质基质中、未附着于任何膜结构上的核糖体。它与附着在内质网膜上的膜结合核糖体在结构和功能上完全相同，两者的差别只在于当时正在合成的蛋白质种类：膜结合核糖体合成正在跨内质网膜转运的蛋白，游离核糖体则合成由核基因组编码的其余蛋白质。若mRNA编码带内质网信号序列的蛋白，多聚核糖体便在信号序列引导下附着到内质网膜上，因此两类核糖体可随所合成的mRNA而相互转换。","src":"《第4章 核糖体》p17；MBoC 7e 印刷 p704"},{"id":"8f893944","s":"c","g":"c05","n":"终止密码子","e":"","d":"终止密码子指UAA、UAG和UGA三个密码子。遗传密码共六十四个，其中六十一个为氨基酸密码子（含起始密码子），三个为终止密码子。终止密码子不编码氨基酸，当核糖体到达其中任何一个时，由于没有与之相匹配的反密码子，蛋白质的延伸被终止，多肽链从tRNA中脱离出来。终止密码子因此规定了多肽链合成的终点，与起始密码子共同界定翻译的阅读框，保证肽链长度和氨基酸序列的准确性。","src":"《第4章 核糖体》p43；《第1章 细胞与细胞生物学》p29"},{"id":"a03b6517","s":"c","g":"c05","n":"翻译后修饰","e":"PTM","d":"翻译后修饰指新生肽链加工过程中氨基酸残基发生的化学修饰。常见类型包括磷酸化、乙酰化、甲基化、糖基化、羟基化、硫酸化、二硫键形成、泛素化和酪氨酸硝化等，各自承担特定功能：糖基化与分泌蛋白及细胞识别有关，羟基化影响蛋白质稳定性及其与配体的相互作用，硫酸化调节蛋白质之间以及受体与配体的结合，二硫键形成分子内或分子间交联以稳定蛋白质，泛素化则作为蛋白质降解的信号。这些修饰可显著扩展蛋白质结构与功能的多样性。","src":"《第4章 核糖体》p45、p46"},{"id":"2ba5c438","s":"c","g":"c05","n":"lncRNA","e":"lncRNA","d":"lncRNA即长链非编码RNA，指不编码蛋白质且转录本超过二百个核苷酸的RNA分子。它和mRNA类似，主要由RNA聚合酶II转录，可发生可变剪接，部分具有poly(A)尾巴，分布于细胞核和细胞质。其调控方式包括转录干扰、转录激活和转录后调控：可抑制RNA聚合酶II活性、招募染色质重塑复合物或促进启动子甲基化；也可与编码基因的转录本形成互补双链而干扰剪接，或作为小RNA的前体、结合特定蛋白调节其活性。","src":"《第4章 核糖体》p93、p95、p96；MBoC 7e 印刷 p470"},{"id":"8d06c339","s":"c","g":"c05","n":"miRNA","e":"miRNA","d":"miRNA是由基因组自身转录并加工而成的小RNA。其加工途径为：初级转录本pri-miRNA先被加工为pre-miRNA，再经Dicer切割形成成熟miRNA，加工时剪切一个侧臂、其余部分降解。miRNA与Argonaute家族蛋白结合形成复合物，作用于靶基因mRNA的3′-UTR；一个miRNA可调节若干具有共同功能域的不同基因，一个基因上也可有多个作用位点。配对完全时导致靶mRNA降解，配对不完全时则抑制翻译，从而负调控基因表达。","src":"《第4章 核糖体》p81、p87；MBoC 7e 印刷 p464","x":1},{"id":"beb03022","s":"c","g":"c05","n":"piwiRNA","e":"piwiRNA","d":"piRNA是一类与Piwi蛋白结合的小RNA，由内源产生，其前体为较大的RNA前体，可被加工成大量piRNA。它作用于转座子RNA的任何部位，一个基因上可有多个作用位点，并与Piwi、ago3、Aubergine等蛋白形成复合物。其效应包括在转录水平由Piwi介导、在转录后由ago3与Aub切割，从而抑制转座子活性。piRNA主要存在于生殖细胞中，对维持生殖细胞基因组的稳定、抵抗转座子侵袭以及配子发生具有重要作用。","src":"《第4章 核糖体》p87"},{"id":"b8adafe3","s":"c","g":"c05","n":"siRNA","e":"siRNA","d":"siRNA即小干扰RNA，源于外源病毒入侵或内源RNA产生的小分子双链RNA，长度一般为二十一至二十五核苷酸，能在细胞之间短暂转移。其双链前体经Dicer对称地切割两侧臂而成熟，随后与Argonaute等复合物组分结合，其中一条链被切割丢弃，剩余单链引导复合物回到病毒或转座子产生的互补RNA上。由于配对通常完全，Argonaute可切割这些RNA使其迅速降解；每次切割后复合物重新释放，故一个siRNA分子能催化性地破坏许多互补RNA。","src":"《第4章 核糖体》p80、p87；MBoC 7e 印刷 p465","x":1},{"id":"ffde118a","s":"c","g":"c05","n":"snRNA","e":"snRNA","d":"snRNA即小核RNA，是参与细胞核内pre-mRNA加工的小分子RNA，长度约一百至三百核苷酸。它与多种蛋白因子结合形成snRNP，构成剪接体；组成核内剪接体的snRNA命名为U1、U2、U4、U5和U6，参与多步RNA-RNA与RNA-蛋白相互作用。剪接过程中，U1与U2 snRNA先与pre-mRNA的剪接位点和分支点碱基配对，随后U4、U5、U6参与活性位点的形成，切除内含子并把外显子连接起来。","src":"《第4章 核糖体》p61；《第11章 细胞分化与基因表达调控》p109；MBoC 7e 印刷 p344"},{"id":"815b79e2","s":"c","g":"c05","n":"snoRNA","e":"snoRNA","d":"snoRNA即小核仁RNA，是一类富集于核仁的小分子RNA，长度约六十至三百核苷酸，绝大部分来源于内含子。它与蛋白结合形成snoRNP，通过与被修饰位点两侧序列碱基配对，确定前体rRNA上需要修饰的位点；snoRNP中既含向导序列，也含催化修饰的酶，可指导rRNA的甲基化与假尿苷化等修饰。因此snoRNA参与rRNA的加工与修饰，是核糖体亚基正确成熟所必需的，其作用体现了RNA对RNA加工的调控。","src":"《第4章 核糖体》p61；MBoC 7e 印刷 p353"},{"id":"649a1a4d","s":"c","g":"c05","n":"多聚核糖体","e":"polysome","d":"多聚核糖体是由多个核糖体结合在同一条mRNA上形成的胞质复合体，相邻核糖体间隔可近至约八十个核苷酸。mRNA的5′端在翻译起始后即空出，可再被新的核糖体结合，同一条mRNA上因而能同时容纳多个核糖体；典型人类细胞中约三分之一的mRNA完全没有核糖体，其余每条mRNA上有十至二十个核糖体。这种多次起始使细胞在单位时间内合成的蛋白量远多于逐个完成的方式，也使mRNA得到经济有效的利用。","src":"《第4章 核糖体》p55；MBoC 7e 印刷 p375","x":1},{"id":"fc67ca18","s":"c","g":"c05","n":"核糖体","e":"ribosome","d":"核糖体是由rRNA与核糖体蛋白组成的、无膜结构的细胞器，能依据mRNA提供的信息催化蛋白质合成。按生物类型可分为原核与真核核糖体：原核为70S，由50S与30S亚基组成；真核为80S，由60S与40S亚基组成；线粒体核糖体为55S。核糖体具有A位点、P位点、E位点和mRNA结合位点等功能活性位点；其存在形式还受镁离子浓度影响，镁离子浓度过低时，核糖体以大、小亚基分离的形式存在。","src":"《第4章 核糖体》p17、p25；MBoC 7e Glossary（PDF p1473）"},{"id":"545f26db","s":"c","g":"c05","n":"核酶","e":"ribozyme","d":"核酶是具催化功能的RNA，又称酶性RNA；具催化功能的DNA称脱氧核酶，两者统称核酶。与蛋白质酶相比，核酶的催化效率较低，被认为是一种较为原始的催化酶。其作用机制包括剪切型与剪接型：剪切型核酶把自身或异体RNA切除一段特异的核苷酸序列，特点是只剪不接，通过磷酸二酯键的断裂破坏RNA链；第一类和第二类内含子则可进行自我剪接。核酶的发现突破了酶是蛋白质的传统观念，补充和发展了中心法则。","src":"《第4章 核糖体》p63、p73；MBoC 7e 印刷 p390"},{"id":"50495803","s":"c","g":"c05","n":"RISC（RNA诱导沉默复合体）","e":"","d":"RISC即RNA诱导沉默复合体，是由多个蛋白质分子与siRNA或miRNA组装而成的复合物。其核心成分是Argonaute家族蛋白，小RNA的双链被载入后，其中一条链被切割丢弃，剩余的单链作为向导，把复合物带到与之互补的靶RNA上。配对完全时，Argonaute切割靶RNA使其迅速降解；配对不完全时则阻遏翻译。复合物每次切割后即释放，可以循环使用，因此少量小RNA便能催化性地沉默大量靶mRNA。","src":"《第4章 核糖体》p82、p87；MBoC 7e 印刷 p465"},{"id":"370cd1fe","s":"c","g":"c05","n":"RNA世界假说","e":"","d":"RNA世界假说是在发现RNA兼具催化功能和自我复制功能之后提出的一种假说。该假说认为，在生物进化过程中最早出现的生物大分子是RNA，而不是DNA和蛋白质，即在进化的某个阶段存在一个以RNA为主导的“RNA世界”。由于RNA既能像DNA那样携带遗传信息，又能像蛋白质那样催化反应，它可以同时承担今日由核酸与酶分工完成的两项任务，从而为遗传信息载体与催化剂的分离演化提供了可能。","src":"《第4章 核糖体》p76"},{"id":"0730cab9","s":"c","g":"c05","n":"RNA干扰","e":"RNA interference（RNAi）","d":"RNA干扰指一种由双链RNA诱发的基因沉默现象，其机制是通过阻碍特定基因的翻译或转录来抑制基因表达。当细胞中导入与内源性mRNA编码区同源的双链RNA时，该mRNA发生降解，导致基因表达沉默。siRNA和miRNA介导的基因沉默现象均可称为RNAi。由于具有高度的序列特异性，RNAi已广泛应用于基因功能研究与疾病治疗探索，成为重要的反向遗传学工具，也是研究非编码RNA调控网络的基础。","src":"《第4章 核糖体》p88"},{"id":"3657f215","s":"c","g":"c05","n":"ceRNA（竞争性内源RNA）","e":"competing endogenous RNA","d":"ceRNA即竞争性内源RNA，是一类能通过竞争性结合miRNA来调节基因表达的RNA。它借助miRNA应答元件与miRNA结合，从而影响miRNA所致的基因沉默，揭示了一条由RNA到miRNA的调节通路。这一假说说明mRNA与miRNA之间的关系可以是双向的，一种RNA的水平能够影响另一种RNA的水平，由此形成相互竞争的调控网络，使非编码RNA与编码RNA共同参与基因表达的精细调节。","src":"《第4章 核糖体》p96、p99"},{"id":"9844cd78","s":"c","g":"c05","n":"eRNA（增强子RNA）","e":"enhancer RNAs","d":"eRNA即增强子RNA，是从转录增强子上转录产生的非编码RNA。增强子是真核细胞中远距离调控基因转录的顺式元件，其转录本即为eRNA。在lncRNA激活基因表达的机制中，eRNA被认为创造了一个自由的染色质环境，并可能介导调控复合物与核心转录起始位点的相互作用，从而锁定稳定的转录起始过程，实现增强子依赖的转录激活。eRNA的发现提示增强子不只是被动的调控元件，其转录产物本身也参与基因表达调控。","src":"《第4章 核糖体》p95、p100"},{"id":"e2b0c10b","s":"c","g":"c05","n":"mRNA","e":"Messenger RNA","d":"mRNA即信使RNA，是编码蛋白质的RNA分子，其核苷酸序列规定了蛋白质的氨基酸序列。在真核生物中，mRNA由RNA聚合酶以DNA为模板转录出前体，再经加工形成；随后在核糖体上被翻译为蛋白质，这一过程由核糖体催化。mRNA的长度变化很大。原核mRNA依靠SD序列与16S rRNA互补而结合核糖体，真核mRNA则主要依赖5′端甲基化帽子结构被识别，部分还可通过内部核糖体进入位点起始翻译。","src":"《第4章 核糖体》p61；MBoC 7e Glossary（PDF p1464）"},{"id":"8571d28b","s":"c","g":"c05","n":"piRNA","e":"piRNA（Piwi-interacting RNA）","d":"piRNA是生殖细胞中的一类小RNA，由内源产生，其前体为较大的RNA前体，可被加工成大量piRNA。它作用于转座子RNA的任何部位，一个基因上可有多个作用位点，并与Piwi、ago3、Aubergine等蛋白形成复合物，通过转录水平由Piwi介导、转录后由ago3与Aub切割的方式抑制转座子活性。因此piRNA的主要功能是维持转座子的沉默、抵抗转座子对基因组的侵袭，并在配子发生过程中发挥作用。","src":"《第4章 核糖体》p87"},{"id":"d2902245","s":"c","g":"c05","n":"scaRNA","e":"Small Cajal body-associated RNA","d":"小卡哈尔体RNA（Small Cajal body-associated RNA，scaRNA）是在卡哈尔体（Cajal小体）中发现的一类非编码小RNA，长度约200～300个核苷酸。它的主要作用是修饰小核RNA（snRNA），其作用方式与小核仁RNA指导rRNA的加工和修饰相似。由于snRNA是剪接体的核心组分，scaRNA对snRNA的修饰间接影响剪接体的装配与pre-mRNA的剪接效率。","src":"《第4章 核糖体》p61"},{"id":"e58ceec5","s":"c","g":"c05","n":"snRNA","e":"Small nuclear RNA","d":"小核RNA（Small nuclear RNA，snRNA）是长约100～300个核苷酸的核内小RNA，在细胞核的RNA加工中起作用。它并不单独行动，而是与多种蛋白因子结合成小核核糖核蛋白颗粒（snRNP）；组成细胞核剪接体的snRNA被命名为U1、U2、U4、U5和U6，通过一系列RNA-RNA与RNA-蛋白相互作用参与剪接。剪接早期，pre-mRNA与U1、U2 snRNA发生碱基配对，识别剪接位点，最终切除内含子序列。","src":"《第4章 核糖体》p61；《第11章 细胞分化与基因表达调控》p109"},{"id":"b7980589","s":"c","g":"c05","n":"snoRNA","e":"Small nucleolar RNA","d":"小核仁RNA（Small nucleolar RNA，snoRNA）是存在于核仁中的一类小RNA，长度约60～300个核苷酸，细胞内浓度很高，绝大部分来源于内含子。它的功能是指导前体rRNA的加工与修饰，包括对rRNA特定位点进行甲基化等修饰，是核糖体亚基正确成熟的必要条件。作为非编码RNA的重要成员，snoRNA与作用于snRNA的scaRNA分工相似，共同保证核内RNA前体的加工质量。","src":"《第4章 核糖体》p61；MBoC 7e Glossary（PDF p1475）"},{"id":"6a3bf7da","s":"c","g":"c05","n":"tRNA","e":"Transfer RNA","d":"转运RNA（Transfer RNA，tRNA）是长约70～90个核苷酸的小RNA，在蛋白质合成中作为mRNA与氨基酸之间的桥梁。氨基酸本身不识别密码、不直接反应生成肽链，需借助tRNA转运：氨酰-tRNA合成酶催化氨基酸的羧基与其对应tRNA的3′端羟基反应，生成含高能酯键的氨酰tRNA。核糖体上A位点接受氨酰tRNA，P位点结合延伸中的肽酰tRNA，E位点是脱氨酰tRNA离开时的暂时停靠点。","src":"《第4章 核糖体》p61、p35；MBoC 7e Glossary（PDF p1478）"},{"id":"3568421d","s":"c","g":"c05","n":"小RNA（miRNA）","e":"microRNA","d":"微RNA（microRNA，miRNA）是长度20～24个核苷酸的单链小RNA，作为一种负调控因子作用于其靶标mRNA，能在转录或翻译水平上调控基因表达，可通过降解mRNA或阻断翻译发挥作用。不同物种中已报道大量小RNA。mRNA与miRNA之间的关系可以是双向的，一种mRNA的水平能够影响另一种mRNA的水平和活性，这一现象被称为竞争性内源RNA（ceRNA）机制。","src":"《第4章 核糖体》p61、p78、p99"},{"id":"21b11dcb","s":"c","g":"c05","n":"核酶","e":"ribozyme（Rz）","d":"核酶（ribozyme，Rz）是具有催化功能的RNA，又称酶性RNA；具有催化功能的DNA则称脱氧核酶，两者统称核酶（nucleozyme）。与蛋白质酶相比，核酶的催化效率较低，是一种较为原始的催化酶。按分子大小可分为大分子核酶和小分子核酶两类。剪切型核酶将自身RNA或异体RNA切除一段特异的核苷酸序列，特点是只剪不接，都通过可逆的磷酸二酯断裂反应破坏RNA链。核酶的发现突破了酶是蛋白质的经典观念。","src":"《第4章 核糖体》p63、p65、p73"},{"id":"20ecbf3e","s":"c","g":"c05","n":"环状RNA（circRNA）","e":"Circular RNA","d":"环状RNA（Circular RNA，circRNA）是一大类具有闭合环状结构的特殊非编码RNA，大部分不编码蛋白质。其特征包括半衰期长、具有组织表达特异性、大多存在于细胞质中且序列高度保守。它的形成与反向剪接有关：3′剪接位点与下游的5′剪接位点相连，使正常的连接顺序被颠倒，通常释放出一段以共价闭合环状形式存在的单个外显子序列。这类RNA被输出到细胞核外，但很少被翻译成蛋白质。","src":"《第4章 核糖体》p104；MBoC 7e 印刷 p449"},{"id":"43a9cc57","s":"c","g":"c05","n":"脱氧核酶","e":"deoxyribozyme（DRz）","d":"脱氧核酶（deoxyribozyme，DRz）是具有催化功能的DNA，又称酶性DNA，与核酶（Rz）一起统称核酶（nucleozyme）。DRz通常是利用体外分子生化技术获得的一种单链DNA片段，具有高效催化活性和结构识别能力；迄今已发现的DRz有几十种，但在自然界中还没有找到具类似催化活性的DRz。它的发现与核酶一起，突破了酶是蛋白质的经典观念，是人类对酶化学本质认识的飞跃，补充和发展了中心法则。","src":"《第4章 核糖体》p63、p65"},{"id":"33c0b23f","s":"c","g":"c05","n":"自我剪切/自我剪接","e":"self-cleavage / self-splicing","d":"自我剪切和自我剪接（self-cleavage / self-splicing）指核酶的剪切和剪接作用都不需要其他酶即蛋白质参与，而由RNA自身完成。剪切型核酶把自身RNA或异体RNA切除一段特异的核苷酸序列，其特点是只剪不接，并通过同样可逆的磷酸二酯键断裂反应破坏RNA链。典型例子是四膜虫26S rRNA前体可进行自剪切。这一现象说明RNA既携带遗传信息又具有催化功能，是RNA世界假说的重要依据。","src":"《第4章 核糖体》p64、p70、p73"},{"id":"e6477690","s":"c","g":"c05","n":"锤头型核酶","e":"hammerhead ribozyme","d":"锤头型核酶（hammerhead ribozyme）是植物病毒中的一种小分子核酶，催化时形成一种类似锤头的特殊二级结构。它自身含有一个双链螺旋的柄结构，即柄Ⅱ，同时通过与靶RNA配对形成柄Ⅰ和柄Ⅲ，切割位点位于靶RNA柄Ⅰ与柄Ⅱ的配对区之间。这种结构与配对方式使核酶能够特异识别并切割靶RNA，是研究RNA催化机制、核酶结构与靶RNA识别方式的经典模型；其切割属剪切型核酶反应，只剪不接。","src":"《第4章 核糖体》p74、p75"},{"id":"e11c1e8c","s":"c","g":"c05","n":"长链非编码RNA（lncRNA）","e":"long noncoding RNA","d":"长链非编码RNA（long noncoding RNA，lncRNA）是不编码蛋白、转录本超过200个核苷酸的RNA分子。它与mRNA类似，主要由RNA聚合酶Ⅱ转录，有可变剪接，有些具有poly(A)尾巴、有些没有，定位在细胞核和细胞质中。其功能包括调控蛋白质的表达，作用可发生在转录、转录后和翻译水平，还能帮助蛋白质复合物的组装并调节蛋白质的活性。一般认为lncRNA可充当支架，把蛋白质和核酸组织在一起，从而加速细胞内多种反应。","src":"《第4章 核糖体》p93；MBoC 7e Glossary（PDF p1462）"},{"id":"2bb111a6","s":"c","g":"c05","n":"非编码RNA","e":"non-coding RNA","d":"非编码RNA（non-coding RNA）是不编码蛋白质的RNA，可作为酶性、结构性和调控性组分参与细胞内多种过程。基因组的绝大部分转录产物都是非编码RNA，物种间最主要的差别也在于非编码RNA。人类基因组除约2万个蛋白编码基因外，还含有数千个编码非编码RNA的基因，其中许多功能仍不清楚。按大小和功能可分为rRNA、tRNA、snRNA、snoRNA、scaRNA、miRNA、siRNA、piRNA以及lncRNA等。","src":"《第4章 核糖体》p60、p61、p93；MBoC 7e Glossary（PDF p1466）"},{"id":"19e22118","s":"c","g":"c17","n":"包涵物","e":"","d":"包涵物是细胞质中没有代谢活性、具有特定形态的结构，用于贮存能源物质和分泌颗粒，如糖原颗粒、脂滴和分泌颗粒。它是细胞质的组成成分之一，与细胞质基质、细胞器、细胞骨架并列。包涵物的种类和数量随细胞类型而异：胰腺外分泌腺细胞内可见大量胰酶原分泌颗粒，肝细胞内可见大量糖原颗粒，分泌类固醇激素的细胞内则出现脂滴。它们不参与中间代谢反应，而是作为贮备物质或待分泌物质暂时存放于细胞质中。","src":"《第4章 核糖体》p7"},{"id":"3c6b4ea8","s":"c","g":"c17","n":"无膜凝聚体（生物分子凝聚体）","e":"membrane-less compartments / biomolecular condensates","d":"无膜凝聚体（membrane-less compartments，biomolecular condensates）是细胞内蛋白质、核酸等生物大分子通过相分离形成的各类无膜结构。其形成依赖多价结合，分子作用力包括静电相互作用、疏水相互作用、π-π相互作用和π-阳离子相互作用等，多种弱作用叠加使大分子在局部富集，形成与周围稀相并存的浓相。由于没有脂双层边界，这类结构可以动态组装和解聚，使相关反应在特定时空内高效进行。","src":"《第4章 核糖体》p8、p9"},{"id":"d9bd97a7","s":"c","g":"c17","n":"相分离","e":"liquid/liquid phase separation","d":"相分离（liquid/liquid phase separation）指混合溶液打破其稳定而均匀的单相状态，通过重新排列形成浓相和稀相或者多相的过程，也称相变。在细胞内，蛋白质、核酸等生物大分子正是通过相分离形成各类无膜凝聚体结构。目前已知介导多价结合的分子作用力有很多种，包括静电相互作用、疏水相互作用、π-π相互作用和π-阳离子相互作用等。这一机制解释了无膜区室的形成，使细胞能在不依赖膜的情况下把特定组分与反应组织起来。","src":"《第4章 核糖体》p8"},{"id":"17be84d1","s":"c","g":"c17","n":"细胞质","e":"cytoplasm","d":"细胞质（cytoplasm）又称胞浆，是细胞质膜包围的、除核区以外的一切半透明、胶状、颗粒状物质的总称，由细胞质基质、细胞器、细胞骨架和包涵物组成。细胞质基质中主要含有与细胞内各种中间代谢反应相关的数以千计的酶类，以及维持细胞形态和物质运输有关的细胞质骨架结构。细胞质骨架是细胞质基质结构体系的组织者，为基质中的各种成分和细胞器提供锚定位点，保证细胞内各种复杂代谢反应高效而有序地进行。","src":"《第4章 核糖体》p3；MBoC 7e Glossary（PDF p1452）"},{"id":"40d7c132","s":"c","g":"c17","n":"细胞质基质","e":"","d":"细胞质基质是细胞质中除细胞器、细胞骨架和包涵物以外的胶状部分，又称胞质溶胶。其化学组成包括小分子（水、无机离子）、中等分子（脂类、糖类、氨基酸、核苷酸及其衍生物）和大分子（多糖、蛋白质、脂蛋白、RNA）。它并不是简单的酶溶液，其中的酶类和骨架结构呈区域性分布，细胞质骨架为各种成分和细胞器提供锚定位点，从而保证中间代谢反应高效有序地进行；基质还参与蛋白质寿命的控制。","src":"《第4章 核糖体》p3、p5"},{"id":"e4a2ce7f","s":"c","g":"c17","n":"细胞质遗传","e":"","d":"细胞质遗传是指由细胞质内的遗传因子所决定的遗传现象，其物质基础是叶绿体和线粒体中所含的DNA。胞质遗传因子与核基因相互独立，其传递不遵循核基因的分离规律，表现为非孟德尔式遗传；有多种表现形式，并以母系遗传为主。由于叶绿体和线粒体各自携带基因组，子代的某些性状取决于卵细胞所提供的细胞质，因而与核基因控制的性状在传递方式上明显不同。其遗传物质随细胞质中的细胞器一起分配，因此表现出与核基因不同的传递规律。","src":"《第4章 核糖体》p13"},{"id":"b965cdcf","s":"c","g":"c17","n":"细胞质骨架","e":"","d":"细胞质骨架是由微管、微丝和中间丝组成的高度动态结构体系，在不同细胞之间差异很大。它是细胞质基质结构体系的组织者，为基质中的各种成分和细胞器提供锚定位点，从而维持细胞的特定形状和内部布局，并参与细胞运动。其中中间纤维为细胞质提供机械强度，还参与细胞连接以及核膜的组装与去组装，从而保证各种复杂代谢反应高效有序地进行。不同细胞中三种组分的比例与分布不同，使骨架呈现明显的细胞类型差异。","src":"《第4章 核糖体》p3、p6；《第6章 细胞骨架》p143"},{"id":"443c9420","s":"c","g":"c10","n":"免疫球蛋白超家族","e":"IgSF","d":"免疫球蛋白超家族（IgSF）是细胞黏着分子的一大类，其成员含有一个或多个胞外Ig样结构域，即抗体分子的特征性结构域。ICAM（细胞间细胞黏附分子）与VCAM（血管细胞黏附分子）是该家族成员，它们是内皮细胞表面被白细胞整联蛋白识别的主要蛋白，介导异嗜性结合；该家族许多成员介导不依赖Ca2+的细胞-细胞黏附，并在免疫系统之外具有多种与免疫防御无关的功能。抗体、TCR、BCR与MHC等分子也属于这一家族。","src":"《思维导图》p1；MBoC 7e 印刷 p1125、p1126","x":1},{"id":"91024dd7","s":"c","g":"c10","n":"化学突触","e":"chemical synapse","d":"化学突触（chemical synapse）是动物神经细胞间的通讯连接方式，由突触前膜即突触前细胞、突触间隙和突触后膜即突触后细胞组成；与电突触相比，其结构中有突触泡和线粒体的汇聚，而电突触没有。其传递机制是间接的：动作电位到达突触前部位时，膜去极化打开聚集在突触前膜的电压门控Ca2+通道，Ca2+内流触发储存在膜内的小信号分子即神经递质释放到间隙中，再作用于突触后膜。","src":"《第9章 2021细胞通讯和信号转导》p99；MBoC 7e 印刷 p669"},{"id":"601cda38","s":"c","g":"c10","n":"半桥粒","e":"hemidesmosome","d":"半桥粒（hemidesmosome）是上皮细胞与基底膜之间的锚定连接，属于细胞与细胞外基质之间的连接。它像点焊一样把上皮细胞固定在基底膜上，在胞外侧把层粘连蛋白与胞内的角蛋白丝连接起来。其分子组成中，特化的α6β4整联蛋白跨膜存在，胞内通过plectin和BP230等接头蛋白与角蛋白丝相连，胞外则与基底膜中的层粘连蛋白结合，从而把细胞外基质与细胞骨架连成一体。","src":"MBoC 7e 印刷 p1148"},{"id":"373cf2e4","s":"c","g":"c10","n":"层粘连蛋白","e":"laminin (LN)","d":"层粘连蛋白（laminin，LN）是存在于基底膜中的细胞外基质纤维状蛋白，在基底膜中形成片层状网络。它是细胞与基质黏附的重要配体：跨膜的α6β4整联蛋白在胞外与层粘连蛋白结合，在胞内通过plectin、BP230等接头蛋白与角蛋白丝相连，由此把上皮细胞锚定在基底膜上。层粘连蛋白与纤粘连蛋白同属细胞外基质中的黏着蛋白，与胶原蛋白、弹性蛋白、蛋白聚糖和糖胺聚糖共同构成细胞外基质。","src":"MBoC 7e Glossary（PDF p1462）；MBoC 7e 印刷 p1148","x":1},{"id":"a2d53630","s":"c","g":"c10","n":"弹性蛋白","e":"elastin","d":"弹性蛋白（elastin）是细胞外基质中形成可伸展纤维即弹性纤维的蛋白质，赋予结缔组织弹性。其多肽链主要由两类短片段交替构成：一类是疏水片段，决定分子的弹性；另一类富含丙氨酸和赖氨酸，形成α螺旋并与相邻分子交联，每个片段由独立的外显子编码。弹性纤维中弹性蛋白分子的构象目前仍有不确定性，但其部分肽链如同普通橡胶的聚合物链，采取松散的“无规卷曲”构象，使纤维具有橡胶样性质。","src":"MBoC 7e 印刷 p1137；MBoC 7e Glossary（PDF p1454）"},{"id":"f3cc67bb","s":"c","g":"c10","n":"整联蛋白","e":"integrin","d":"整联蛋白（integrin）又称整合素，是跨质膜的异二聚体蛋白，其胞外段具有多种细胞外基质组分的结合位点，可结合胶原、蛋白聚糖和纤连蛋白，胞外段还能传导信号。细胞与细胞外基质的相互作用主要通过整联蛋白家族的各个成员实现，这种结合不仅介导细胞与基质的黏附，也介导信号转导途径：胞外结构域与配体作用可产生多种信号，如增加胞质Ca2+水平、刺激磷脂酰肌醇第二信使合成、使胞内蛋白酪氨酸残基磷酸化。","src":"《第9章 2021细胞通讯和信号转导》p101；MBoC 7e Glossary（PDF p1461）","x":1},{"id":"5ec2c8ca","s":"c","g":"c10","n":"桥粒","e":"desmosome","d":"桥粒（desmosome）是通常形成于两个上皮细胞之间的胞间锚定连接。其特征是两相邻细胞膜的胞质面各有一致密的桥板，由多种胞内接头蛋白混合组成，中间纤维束附着于桥板表面；跨膜的非经典钙黏蛋白即桥粒芯蛋白和桥粒胶蛋白与桥板结合，并通过其胞外结构域相互作用，把相邻的膜连在一起。中间纤维结合蛋白BPAG1为桥板蛋白，参与使中间纤维与桥粒相连；它与连接肌动蛋白丝的粘着带同属胞间锚定连接。","src":"MBoC 7e 印刷 p1117；《第6章 细胞骨架》p141","x":1},{"id":"b7392131","s":"c","g":"c10","n":"粘着带","e":"adherens junction","d":"粘着带（adherens junction）是胞间锚定连接的一种，其质膜胞质面与肌动蛋白丝即微丝相连，典型例子是连接相邻上皮细胞的黏着带，以及培养成纤维细胞下表面的黏着斑。其胞外结合由钙黏蛋白的同嗜性结合介导，胞内的catenin把经典钙黏蛋白与肌动蛋白骨架连接起来。当大量钙黏蛋白在新生粘着带处排列后，Rac受到抑制、Rho被激活，促进线性收缩性肌动蛋白丝束的组装，使连接处产生张力。","src":"MBoC 7e Glossary（PDF p1444）；MBoC 7e 印刷 p1113"},{"id":"81efd8f9","s":"c","g":"c10","n":"粘着斑","e":"focal adhesion","d":"粘着斑（focal adhesion）是整联蛋白簇集并引起胞质面蛋白快速酪氨酸磷酸化的位点，这一磷酸化由酪氨酸激酶Src完成。整联蛋白与胞外配体结合后，通过talin、paxillin等胞内接头蛋白把黏着斑激酶（FAK）招募到整联蛋白β亚基，聚集的FAK分子相互磷酸化，FAK因而成为整联蛋白介导反应中的效应子。由此可启动从细胞表面到细胞核（经Grb2、Sos、Ras、MAPK）以及到胞质核糖体的信号通路，引起信号级联放大。","src":"《第9章 2021细胞通讯和信号转导》p103；MBoC 7e 印刷 p1152","x":1},{"id":"6343d5c7","s":"c","g":"c10","n":"糖胺聚糖","e":"glycosaminoglycan","d":"糖胺聚糖（glycosaminoglycan，GAG）又称粘多糖，是细胞外基质中由重复二糖单位构成的无分支多糖长链，能占据很大空间并形成水化凝胶。每个重复二糖中的两个糖之一必定是氨基糖，即N-乙酰葡糖胺或N-乙酰半乳糖胺，多数情况下被硫酸化；另一个糖通常是糖醛酸。由于糖上带有硫酸基或羧基，GAG高度带负电。它们主要以共价方式连接到核心蛋白上而构成蛋白聚糖，例子包括硫酸软骨素、透明质酸和肝素。","src":"MBoC 7e Glossary（PDF p1458）；MBoC 7e 印刷 p1129"},{"id":"b43f441f","s":"c","g":"c10","n":"紧密连接","e":"tight junction","d":"紧密连接（tight junction）又称封闭连接，把相邻上皮细胞密封在一起，阻止大多数溶解的分子从上皮层的一侧穿到另一侧。除封闭作用外，它还起栅栏作用，阻止顶面或基底外侧的膜蛋白扩散到错误区域，从而维持上皮细胞的极性。其封闭功能可用低分子量示踪物验证：加在一侧的示踪物一般不能越过紧密连接。但这种封闭并非绝对，所有紧密连接对大分子都不通透，对离子和小分子的通透性则各不相同。","src":"MBoC 7e Glossary（PDF p1477）；MBoC 7e 印刷 p1118"},{"id":"b1744758","s":"c","g":"c10","n":"纤粘连蛋白","e":"fibronectin (FN)","d":"纤粘连蛋白（fibronectin，FN）是细胞外基质中的黏着蛋白，参与细胞与基质的黏附，并在胚胎发育过程中引导迁移细胞的移动。细胞表面的整联蛋白是纤粘连蛋白的受体，二者的结合把细胞固定在基质上，同时经整联蛋白向细胞内传递信号。它与层粘连蛋白同属基质中的黏着蛋白，与胶原蛋白、弹性蛋白、蛋白聚糖和糖胺聚糖一起组成细胞外基质，在组织构建与创伤修复中发挥作用。并影响细胞外基质的组装。","src":"MBoC 7e Glossary（PDF p1456）；《思维导图》p1","x":1},{"id":"c5f0fe6a","s":"c","g":"c10","n":"细胞外基质","e":"extracellular matrix","d":"细胞外基质（extracellular matrix）是由细胞产生并定向排列在细胞外的复杂网络，由糖胺聚糖即粘多糖如透明质酸、结构蛋白如胶原蛋白和弹性蛋白、黏着蛋白如层粘连蛋白和纤粘连蛋白组成，还包括蛋白聚糖。它由所在组织中的细胞合成并定向，不仅为细胞提供机械支撑，还通过整联蛋白等受体影响细胞的黏附、迁移、增殖与分化，并控制细胞骨架的取向和行为，是组织构建与功能维持的基础。","src":"《细胞生物学历年考题整理》p9；MBoC 7e 印刷 p1127","x":1},{"id":"758d4c7d","s":"c","g":"c10","n":"细胞连接","e":"cell junction","d":"细胞连接（cell junction）是细胞之间以及细胞与细胞外基质之间形成的特化连接结构，通常分为封闭连接即紧密连接、锚定连接即桥粒与粘着带、半桥粒与粘着斑，以及通讯连接即间隙连接、化学突触和胞间连丝三类。细胞连接与细胞外基质共同构成多细胞结构的组织装置，对细胞的取向、行为、功能与动态变化都至关重要：与相邻细胞和基质的连接控制细胞骨架的取向和行为，使细胞能够感知并响应环境力学特征的变化，该装置的缺陷是大量疾病的基础。","src":"MBoC 7e 印刷 p1105；《第9章 2021细胞通讯和信号转导》p98"},{"id":"6b968901","s":"c","g":"c10","n":"细胞黏着分子","e":"CAMs","d":"细胞黏着分子（CAMs）是介导细胞与细胞、细胞与细胞外基质黏附的膜蛋白，主要包括钙黏素蛋白家族、选择蛋白家族、免疫球蛋白家族、整联蛋白家族和黏蛋白家族。各家族特性不同：选择蛋白与钙黏蛋白、整联蛋白的黏附功能需要Ca2+，免疫球蛋白超家族成员则不需要；整联蛋白的主要功能是介导细胞与基质的黏附，只有少数在特殊情况下介导细胞与细胞的黏附。它们共同参与细胞识别与组织构建。","src":"《思维导图》p1；MBoC 7e 印刷 p1125、p1126"},{"id":"caf97f53","s":"c","g":"c10","n":"胞间连丝","e":"plasmodesma","d":"胞间连丝（plasmodesma）是植物细胞间唯一的胞间连接类型，相当于动物细胞的间隙连接，可直接连接相邻细胞的细胞质。其通道周围是相邻两个细胞质膜的延续和连接，中央有一个由压扁的内质网形成的圆筒体。由于植物细胞壁厚达0.1 μm以上，需要与间隙连接很不相同的结构才能跨越，胞间连丝正是贯穿细胞壁的细小胞质通道；除少数特化情况外，高等植物每个细胞都通过它与相邻细胞相连。","src":"MBoC 7e Glossary（PDF p1469）；MBoC 7e 印刷 p1124；《第9章 2021细胞通讯和信号转导》p100","x":1},{"id":"a80b29fe","s":"c","g":"c10","n":"胶原蛋白","e":"collagen","d":"胶原蛋白（collagen）是动物细胞外基质的主要蛋白质，富含甘氨酸和脯氨酸，赋予组织抗张强度。其分子由三条链相互缠绕形成长的规则三股螺旋，这种结构是胶原承受拉力的基础；许多胶原分子再侧并侧、端对端地结合，形成长的重叠排列，从而生成极其坚韧的胶原原纤维。胶原蛋白有多种类型：Ⅰ型最常见，存在于皮肤、腱和骨；Ⅱ型存在于软骨；Ⅳ型存在于基底膜。细胞外的这类蛋白常通过共价交联稳定其结构。","src":"MBoC 7e Glossary（PDF p1450）；MBoC 7e 印刷 p133","x":1},{"id":"9735165c","s":"c","g":"c10","n":"选择蛋白","e":"selectin","d":"选择蛋白（selectin）是细胞表面一类糖结合蛋白家族的成员，介导血液中短暂的、依赖Ca2+的细胞与细胞黏附，例如白细胞与血管壁内皮之间的黏附。淋巴细胞从血液迁出进入淋巴组织时，最初的黏附即由淋巴细胞表面的L-选择蛋白介导；随后在内皮细胞分泌的趋化因子刺激下，淋巴细胞迅速激活由整联蛋白介导的更强黏附系统。这种黏附只是暂时的，为后续稳定黏附创造了条件。选择蛋白因此主要承担捕获与选择的第一步。","src":"MBoC 7e Glossary（PDF p1474）；MBoC 7e 印刷 p1125；《第13章 免疫系统的细胞》p18"},{"id":"e68371d8","s":"c","g":"c10","n":"透明质酸","e":"hyaluronic acid","d":"透明质酸（hyaluronic acid，又称透明质酸盐）是糖胺聚糖中最简单的一种，由多达25000个二糖单位有规律地重复构成，在成体动物的所有组织和体液中含量不等，在早期胚胎中尤为丰富。它不是典型的GAG：不含硫酸化的糖，所有二糖单位都相同，链长极大，而且一般不与任何核心蛋白共价连接。由于链长极大且高度水化，它能占据很大的空间，在组织形态发生与修复中作为空间填充物发挥作用。","src":"MBoC 7e 印刷 p1129"},{"id":"d75d57a6","s":"c","g":"c10","n":"钙黏蛋白","e":"cadherin","d":"钙黏蛋白（cadherin）是跨膜黏附蛋白中钙黏蛋白超家族的成员，介导动物组织内同嗜性的、依赖Ca2+的细胞与细胞黏附。按定义，该超家族成员的胞外部分由若干拷贝的胞外钙黏蛋白结构域组成，同嗜性结合发生在最远离膜的N端：每个末端结构域形成一个球形凸起和邻近的口袋，相对两细胞膜上伸出的分子通过一个的凸起插入另一个的口袋而结合。Ca2+结合在每个铰链附近，阻止铰链弯曲，使整串结构域保持刚性。","src":"MBoC 7e Glossary（PDF p1448）；MBoC 7e 印刷 p1109","x":1},{"id":"0d0dc035","s":"c","g":"c10","n":"锚定连接","e":"anchoring junction","d":"锚定连接（anchoring junction）是把细胞与相邻细胞或与细胞外基质连接起来的细胞连接。按所连接的细胞骨架成分可分为两类：与中间纤维相连的，包括胞间的桥粒和细胞与基质间的半桥粒；与肌动蛋白即微丝相连的，包括胞间的粘着带和细胞与基质间的粘着斑。它通过跨膜黏附蛋白和胞内接头蛋白把细胞骨架与外侧结构连成整体，从而赋予组织机械强度，是上皮等组织维持结构完整的重要装置。","src":"MBoC 7e Glossary（PDF p1445）；《思维导图》p1"},{"id":"692b167f","s":"c","g":"c10","n":"间隙连接","e":"gap junction","d":"间隙连接（gap junction）是大多数动物组织中存在的通讯连接，由跨膜的通道蛋白构成，允许离子和小分子从一个细胞的细胞质流向相邻细胞的细胞质。脊椎动物中主要的间隙连接蛋白是连接蛋白，人类有21种亚型；无脊椎动物中则为innexin。其孔径约1.4 nm，可交换无机离子和其他小分子水溶性物质，但不允许蛋白质、核酸等大分子通过。经微电极向一个细胞注入电流，可因离子经间隙连接流动而在相邻细胞引起电学扰动，即电偶联。","src":"MBoC 7e Glossary（PDF p1457）；MBoC 7e 印刷 p1122","x":1},{"id":"d5c341f6","s":"c","g":"c10","n":"黏着斑激酶","e":"FAK","d":"黏着斑激酶（FAK）是一种胞质蛋白酪氨酸激酶，是整联蛋白介导反应中的效应子。当整联蛋白在细胞与基质的接触处簇集时，FAK通过talin、paxillin等胞内接头蛋白被招募到整联蛋白β亚基上，聚集的FAK分子在特定的酪氨酸上相互磷酸化。在培养细胞的黏着斑处，酪氨酸磷酸化往往十分显著，FAK正是这些位点上主要的酪氨酸磷酸化蛋白之一。它由此启动下游级联反应，使信号得以放大并传递到细胞核或核糖体。","src":"《第9章 2021细胞通讯和信号转导》p103；MBoC 7e 印刷 p1152","x":1},{"id":"ca589012","s":"c","g":"c10","n":"黏蛋白","e":"mucin","d":"黏蛋白（mucin）是黏液分泌物中的糖蛋白，也是细胞黏着分子家族之一。高尔基体对黏蛋白施加的O-连接糖基化在所有底物中最为沉重：通常先加上N-乙酰半乳糖胺，随后再添加数量不等的其他糖，从几个到十个以上。这类糖基化是逐个添加糖基的过程，与N-连接糖基化整体转移寡糖前体的方式不同。高尔基体同样对蛋白聚糖的核心蛋白进行O-连接糖基化，把糖胺聚糖链聚合到核心蛋白的丝氨酸上。","src":"《思维导图》p1；MBoC 7e 印刷 p773"},{"id":"790ee32d","s":"c","g":"c04","n":"ARF","e":"ARF (assembly reaction factor)","d":"ARF（assembly reaction factor）是一种小GTP结合蛋白，参与COPI被膜小泡的装配，其功能是调节外被蛋白与膜的结合。小GTP结合蛋白在膜泡运输中成对分工：ARF参与COPI小泡的装配，Sar1参与COPII小泡的装配，二者都通过GTP结合与水解的循环控制外被蛋白在膜上的组装。以Sar1为例，GDP释放后它立即结合GTP，暴露出两性螺旋插入脂双层胞质侧，进而招募外被蛋白亚基、起始出芽。","src":"《第5章细胞内膜系统（下）新》p62；MBoC 7e 印刷 p758"},{"id":"7962574c","s":"c","g":"c04","n":"COPII有被小泡","e":"COPII coated vesicle","d":"COPII有被小泡（COPII coated vesicle）是介导内质网到高尔基体运输的被膜小泡，其衣被由多亚基蛋白组成，包括Sec23/Sec24与Sec13/31等，装配由小GTP结合蛋白Sar1启动。COPII通过识别di-acidic分选信号如Asp-X-Glu来选择货物。生成的小泡可以融合成大泡，并以微管作为运输轨道。它与披网格蛋白小泡、COPI被膜小泡并列为运输小泡的三种主要类型，承担分泌途径中最早的一段正向运输。","src":"《第5章细胞内膜系统（下）新》p60、p35","x":1},{"id":"c026f1b8","s":"c","g":"c04","n":"COPII被膜小泡","e":"COPII coated vesicles","d":"COPII被膜小泡（COPII coated vesicles）是从内质网出芽、在分泌途径早期运输物质的被膜小泡，其衣被由多亚基蛋白组成，包括Sec23/Sec24和Sec13/31等。COPII的装配能识别di-acidic分选信号，例如Asp-X-Glu，从而把特定货物包装入小泡；小泡可以融合成大泡，并以微管作为运输轨道。其装配受小GTP结合蛋白Sar1调节，Sar1负责把外被蛋白招募并固定在膜上。","src":"《第5章细胞内膜系统（下）新》p60；MBoC 7e Glossary（PDF p1451）"},{"id":"0cf1e829","s":"c","g":"c04","n":"COPI有被小泡","e":"COPI coated vesicle","d":"COPI有被小泡（COPI coated vesicle）是介导高尔基体到内质网方向运输并回收内质网逃逸蛋白的被膜小泡，其装配由小GTP结合蛋白ARF参与，ARF负责调节外被蛋白与膜的结合。COPI外被为胞质溶胶蛋白，含7个亚基，结构类似网格蛋白；它识别KDEL受体胞质面的Lys-Lys-X-X序列，把带有回收信号的腔内蛋白包装起来送回内质网，因而在维持内质网驻留蛋白组成和膜区室身份上起关键作用。","src":"《第5章细胞内膜系统（下）新》p35、p60、p62","x":1},{"id":"e2584ee0","s":"c","g":"c04","n":"COPI被膜小泡","e":"COPI coated vesicles","d":"COPI被膜小泡（COPI coated vesicles）是从高尔基体各囊腔出芽、在分泌途径中运输物质的被膜小泡。其衣被由胞质溶胶蛋白组成，含7个亚基，结构类似网格蛋白；装配受小GTP结合蛋白ARF调节，ARF参与COPI小泡的装配并控制外被蛋白与膜的结合。COPI通过识别KDEL受体胞质面的Lys-Lys-X-X序列包装货物，介导回收性运输，如从高尔基体返回内质网，从而回收逃逸的内质网驻留蛋白。","src":"《第5章细胞内膜系统（下）新》p60、p62；MBoC 7e Glossary（PDF p1451）"},{"id":"d2114257","s":"c","g":"c04","n":"内质网相关蛋白降解","e":"ERAD (ER-associated protein degradation)","d":"内质网相关蛋白降解（ER-associated protein degradation，ERAD）是内质网蛋白质质控的策略之一。底物先被分子伴侣和凝集素按暴露的疏水区与糖基化状态识别，再经逆向转运通道从内质网拉回胞质；随后在E1激活酶、E2结合酶和E3连接酶催化的级联反应中被泛素化，聚泛素链被26S蛋白酶体识别并降解。AAA-ATP酶p97/VCP为底物从膜上抽出提供能量。","src":"网络补充：pmc.ncbi.nlm.nih.gov（ERAD 综述）"},{"id":"6701b216","s":"c","g":"c04","n":"ERGIC","e":"ERGIC","d":"ERGIC（ER-Golgi intermediate compartment，内质网-高尔基体中间区室）是位于内质网与高尔基体之间的膜性细胞器，又称小泡管簇，是目前内膜系统研究中很活跃的区域之一。从内质网出口位点出芽的COPII小泡脱去衣被后，彼此同型融合形成这一管泡状簇，货物在此分选，再由COPI小泡把内质网驻留蛋白逆向运回，正向货物则经囊腔成熟或沿微管运送进入顺面高尔基体网络。它同时是蛋白质质控的检查点。","src":"《第5章细胞内膜系统（下）新》p94；网络补充：en.wikipedia.org（ERGIC）","x":1},{"id":"743aa350","s":"c","g":"c04","n":"ESCRT复合体","e":"ESCRT complex","d":"ESCRT复合体（ESCRT complex）是参与膜内陷与出芽断裂的蛋白复合体，在把货物分选进入多囊体腔内小泡的过程中起核心作用。该过程还依赖一种脂激酶把磷脂酰肌醇磷酸化生成PI(3)P，PI(3)P为ESCRT复合体提供额外的停靠位点；ESCRT的停靠与小泡内陷既需要PI(3)P，也需要泛素化的货物蛋白与内体膜结合。ESCRT-Ⅲ在膜上形成大的多聚组装体使膜弯曲。ESCRT功能缺陷的细胞出现信号缺陷，活化的受体不能经内吞下调。","src":"MBoC 7e 印刷 p797","x":1},{"id":"02e1ff13","s":"c","g":"c04","n":"I-细胞病","e":"I-cell disease","d":"I细胞病（I-cell disease）是由单基因缺陷引起的隐性遗传病，只有两条缺陷基因拷贝的个体才发病，属于溶酶体贮积症。患者溶酶体所缺的各种水解酶都出现在血液中：由于在高尔基体中分选异常，这些酶被分泌到细胞外而不是运往溶酶体。缺陷已追溯到GlcNAc磷酸转移酶缺失或有缺陷，溶酶体酶在高尔基体cis面未被磷酸化，M6P受体便无法在TGN把它们分选进相应的运输小泡，水解酶于是被带到细胞表面。","src":"《第5章细胞内膜系统（上）》p116；MBoC 7e 印刷 p780","x":1},{"id":"70e42862","s":"c","g":"c04","n":"I细胞病","e":"inclusion cell disease (I-cell disease)","d":"I细胞病（inclusion cell disease，I-cell disease）又称黏脂病，因GlcNAc磷酸转移酶即N-乙酰葡萄糖苷酶缺陷，溶酶体酶不能获得M6P标记而分选障碍，属溶酶体贮积症。它同时揭示了溶酶体形成的非M6P途径：溶酶体膜中的糖蛋白如β-葡糖脑苷脂酶，以及作为溶酶体膜结合蛋白前体被合成的酸性磷酸酶，可依靠胞质结构域中的酪氨酸信号被分选到溶酶体，而不依赖M6P。","src":"《第5章细胞内膜系统（上）》p116、p117"},{"id":"7f5431e5","s":"c","g":"c04","n":"LC3-Ⅱ","e":"LC3-II","d":"LC3-Ⅱ是自噬相关蛋白LC3与脂质磷脂酰乙醇胺（PE）偶联后产生的形式，是细胞自噬相关通路中的关键环节。在自噬过程中，LC3由LC3-Ⅰ转换为脂化的LC3-Ⅱ并附着于自噬体膜，因此实验上常以LC3-Ⅱ/LC3-Ⅰ的转换以及荧光显微镜下LC3点状聚集物的形成作为检测自噬的指标。由于LC3本身也通过自噬被降解，检测时需结合自噬抑制物，尤其是溶酶体抑制剂，进行联合判断。","src":"《第5章细胞内膜系统（上）》p103；《第12章 细胞衰老与细胞凋亡》p93"},{"id":"8a8e6916","s":"c","g":"c04","n":"LDL","e":"LDL (low-density lipoprotein)","d":"LDL（low-density lipoprotein，低密度脂蛋白）是血液中运输胆固醇的球形脂蛋白。其核心含约1500个胆固醇酯，外面是约800个磷脂和500个未酯化的胆固醇分子，亲水头部朝外侧；最外层为载脂蛋白B-100，可与特定细胞表面受体结合。胆固醇来自食物或在肝脏中合成，以LDL的形式在血液中运输，再由细胞表面的LDL受体结合并内化，供细胞合成新膜等使用。","src":"《第5章细胞内膜系统（下）新》p26"},{"id":"c94201f5","s":"c","g":"c04","n":"LDL受体","e":"LDL receptor","d":"LDL受体（LDL receptor）是单次跨膜糖蛋白，按需要合成后掺入质膜，能结合并内化含胆固醇的LDL颗粒。LDL受体位于网格蛋白有被小窝中，小窝不断缢缩形成有被小泡，使结合的LDL被迅速内吞；小泡脱去网格蛋白外被后把内容物送入早期内体，内体的低pH使LDL与受体分离，LDL经晚期内体送往溶酶体，在那里胆固醇酯被水解为游离胆固醇供细胞利用，受体则可循环再用。","src":"《第5章细胞内膜系统（下）新》p26、p30；MBoC 7e 印刷 p792"},{"id":"93f2307c","s":"c","g":"c04","n":"M6P受体","e":"M6P receptor","d":"M6P受体（M6P receptor）是识别带甘露糖-6-磷酸即M6P标志的溶酶体水解酶的跨膜受体。M6P基团只加在这些可溶性溶酶体酶的N-连接寡糖上；TGN中的受体在腔内与水解酶结合，在胞质侧与装配中的网格蛋白外被的衔接蛋白结合，从而把水解酶包装进从TGN出芽的网格蛋白有被小泡。它在pH 6.5～6.7时结合M6P，pH 6时释放，故进入内体后货物解离，受体经retromer回收至TGN重复使用。","src":"《第5章细胞内膜系统（上）》p114；MBoC 7e 印刷 p778","x":1},{"id":"daea4eca","s":"c","g":"c04","n":"M6P受体蛋白","e":"M6P receptor protein","d":"M6P受体蛋白（M6P receptor protein）是溶酶体酶分选中的关键受体，在pH 6.5～7的条件下与M6P结合，在酸性条件即pH 6时脱落。它主要存在于高尔基体外侧网络，在某些细胞中也存在于细胞质膜上。受体在TGN腔内结合带M6P的溶酶体水解酶，在胞质侧通过衔接蛋白AP1进入网格蛋白有被小泡；到达内体后因pH降低而释放货物，自身则被回收至TGN再次使用。","src":"《第5章细胞内膜系统（上）》p114；《第5章细胞内膜系统（下）新》p49；MBoC 7e 印刷 p778"},{"id":"e71ce710","s":"c","g":"c04","n":"N-乙基马来酰亚胺敏感融合蛋白","e":"NSF (N-ethylmaleimide-sensitive fusion protein)","d":"NSF（N-ethylmaleimide-sensitive fusion protein，N-乙基马来酰亚胺敏感融合蛋白）是一种可溶性蛋白，为六聚体ATP酶。它与可溶性NSF附着蛋白SNAP一起介导不同小泡的融合，并能解开v-SNARE与t-SNARE形成的复合物，使SNARE蛋白得以循环使用。按SNARE假说，v-SNARE位于小泡膜、t-SNARE位于靶膜，二者配对形成复合物驱动膜融合，NSF则负责该复合物的解聚。","src":"《第5章细胞内膜系统（下）新》p79；MBoC 7e Glossary（PDF p1466）"},{"id":"f886e3f6","s":"c","g":"c04","n":"N-连接糖基化","e":"N-linked glycosylation","d":"N-连接糖基化（N-linked glycosylation）是把由14个糖即N-乙酰葡糖胺、甘露糖和葡萄糖组成的寡糖前体转移到蛋白质天冬酰胺残基的氨基上，识别序列为Asn-X-Ser/Thr，又称天冬酰胺连接糖基化。它起始于内质网，在高尔基体中进一步加工为高甘露糖寡糖或复合寡糖。N-连接糖基化从两方面促进蛋白质折叠：使折叠中间体更易溶、防止聚集；寡糖的顺序修饰形成糖码，标记折叠进程，供内质网中的分子伴侣与凝集素识别。","src":"《第5章细胞内膜系统（上）》p54、p74；MBoC 7e 印刷 p774"},{"id":"0a234c2a","s":"c","g":"c04","n":"O-连接的糖基化","e":"","d":"O-连接的糖基化是把糖链转移到多肽链的丝氨酸、苏氨酸或羟赖氨酸的羟基上的糖基化方式，这一反应发生在高尔基体中。与N-连接糖基化不同，它不以预先组装好的14糖寡糖前体整体转移，而是逐个添加糖基；高尔基体对黏蛋白和蛋白聚糖核心蛋白的O-连接糖基化最为显著。与此同时，N-连接的寡聚糖在高尔基体中也被进一步加工，二者共同决定成熟糖蛋白的糖链结构。O-连接糖基化不需要在别处预先合成寡糖前体。","src":"《第5章细胞内膜系统（上）》p75、p76"},{"id":"8a47e55d","s":"c","g":"c04","n":"O-连接糖基化","e":"O-linked glycosylation","d":"O-连接糖基化（O-linked glycosylation）是把一个或多个糖添加到蛋白质的羟基上，通常发生在高尔基体腔内，由糖基转移酶逐个把糖加到蛋白质上。一般先加上N-乙酰半乳糖胺，随后再添加数量不等的其他糖，从几个到十个以上。该修饰不需要预先组装好的寡糖前体。高尔基体对黏蛋白和蛋白聚糖核心蛋白的O-连接糖基化最为沉重，后者是把糖胺聚糖链聚合到核心蛋白的丝氨酸上，从而生成蛋白聚糖。","src":"MBoC 7e Glossary（PDF p1467）；MBoC 7e 印刷 p773"},{"id":"21eabe76","s":"c","g":"c04","n":"OGT","e":"O-GlcNAc transferase","d":"OGT（O-GlcNAc transferase，O-GlcNAc转移酶）是催化单个N-乙酰葡糖胺从UDP-GlcNAc转移到靶蛋白丝氨酸或苏氨酸残基上的酶，产物为β-连接的O-GlcNAc。该修饰可被O-GlcNAcase即OGA水解去除，构成动态可逆的循环。OGT含N端富含TPR重复的结构域，介导多聚化与蛋白质相互作用，C端为催化域；它富集于细胞核，胞质亦有分布，其活性随UDP-GlcNAc浓度变化，被视为代谢状态的感受器。","src":"网络补充：uniprot.org（OGT1_RAT）；pmc.ncbi.nlm.nih.gov","x":1},{"id":"89cdbc9d","s":"c","g":"c04","n":"Rab","e":"Rab","d":"Rab是一类与Ras蛋白相关的小GTP结合蛋白，属于单体GTP酶，已鉴定出30余种，各自在特定的膜泡运输过程中发挥作用。它在GTP结合状态下存在于质膜和细胞器膜上，在GDP结合状态下则为可溶性胞质蛋白。Rab可作用于运输的多个步骤，包括与SNARE相互作用、调节并促进v-SNARE与t-SNARE复合物的形成，从而赋予小泡停泊与融合的特异性，被称为膜泡运输的分子开关。","src":"《第5章细胞内膜系统（下）新》p82；MBoC 7e Glossary（PDF p1471）"},{"id":"86548c09","s":"c","g":"c04","n":"Rab蛋白","e":"Rab proteins","d":"Rab蛋白（Rab proteins）是与Ras蛋白相关的小GTP结合蛋白家族，已鉴定出30余种，分别承担特定的膜泡运输过程。它可作用于运输的多个步骤，包括与SNARE相互作用、调节并促进v-SNARE与t-SNARE复合物的形成。为确保运输有序，小泡必须准确识别正确的靶膜：所有运输小泡都展示标明其来源与货物类型的表面标记，靶膜则展示识别相应标记的互补受体，两类标记依次作用，Rab蛋白即参与赋予这种靶向特异性。","src":"《第5章细胞内膜系统（下）新》p82；MBoC 7e 印刷 p760"},{"id":"27c2336d","s":"c","g":"c04","n":"SNARE复合物","e":"SNARE complex","d":"SNARE复合物（SNARE complex）由定位于小泡膜的v-SNARE与定位于靶膜的t-SNARE配对形成。二者的配对高度专一，形成的反式SNARE复合物把两层膜锁在一起，为运输过程提供又一层特异性，确保小泡只与正确的靶膜融合。该复合物极其稳定，其组装在能量上有利，这份能量被用来把两膜面拉近，同时挤出界面上的水分子，从而启动脂双层融合；融合完成后由NSF催化复合物解离。","src":"《第5章细胞内膜系统（下）新》p79、p82；MBoC 7e 印刷 p763","x":1},{"id":"1233201a","s":"c","g":"c04","n":"SRP受体","e":"SRP receptor","d":"SRP受体（SRP receptor）是内质网膜上的组分，负责把信号识别颗粒即SRP引导到内质网膜，其作用已在体外实验中得到证明。SRP与SRP受体结合，把SRP-核糖体复合物带到内质网膜上尚未占用的蛋白质转位器；随后SRP结合在核糖体通道附近的部分移到另一位置，使转位器得以占据该位点，SRP与SRP受体随即释放，蛋白质合成恢复全速。与转位器紧密结合的核糖体把延伸中的多肽链转移过膜，即共翻译转运。","src":"《第5章细胞内膜系统（上）》p21、p27；MBoC 7e 印刷 p704","x":1},{"id":"46ccf9a1","s":"c","g":"c04","n":"Sar1","e":"Sar1","d":"Sar1是参与COPII被膜小泡装配的小GTP结合蛋白，功能是调节外被蛋白与膜的结合。由于胞质中GTP的浓度远高于GDP，Sar1在GDP释放后立即结合GTP；处于GTP结合状态时，它暴露出一个两性螺旋并插入内质网膜脂双层的胞质侧，紧密结合的Sar1随即招募外被蛋白的衔接亚基到内质网膜上，起始出芽。其他鸟苷酸交换因子与招募外被的GTP酶在其他膜上以类似方式工作。","src":"《第5章细胞内膜系统（下）新》p62；MBoC 7e 印刷 p758"},{"id":"31eb194d","s":"c","g":"c04","n":"钙联蛋白","e":"calnexin / calreticulin","d":"钙联蛋白（calnexin）与钙网蛋白（calreticulin）是内质网中参与N-连接糖基化蛋白质折叠质控的分子伴侣，前者位于膜上，后者为可溶形式。它们识别N-连接寡糖上的葡萄糖残基，为糖蛋白提供达到天然构象的机会；若折叠不成功，葡萄糖基转移酶可重新加上葡萄糖，使蛋白质重返这一折叠循环。葡萄糖基转移酶是判断蛋白质是否折叠正确的关键酶。反复折叠失败的蛋白质最终被移交ERAD途径降解。","src":"《第5章细胞内膜系统（上）》p54；网络补充：pmc.ncbi.nlm.nih.gov（ERAD 综述）"},{"id":"03360432","s":"c","g":"c04","n":"蛋白质二硫键异构酶","e":"protein disulfide isomerase (PDI)","d":"蛋白质二硫键异构酶（protein disulfide isomerase，PDI）是内质网中的驻留酶，催化游离巯基即SH基氧化形成二硫键即S-S键，也就是在半胱氨酸残基的侧链之间催化形成二硫键。它是蛋白质在内质网中加工与修饰的重要环节，与N-连接糖基化、经转酰氨基酶添加糖基磷脂酰肌醇锚并列。暴露在内质网腔或细胞外的蛋白质结构域中，几乎所有的半胱氨酸都形成二硫键，这类共价交联有助于稳定蛋白质结构。","src":"《第5章细胞内膜系统（上）》p47；MBoC 7e 印刷 p713"},{"id":"eb0bd67e","s":"c","g":"c04","n":"retromer","e":"retromer","d":"retromer是一种专门负责从内体到高尔基体外侧网络运输的外被蛋白复合物，包被从内体出芽的运输小泡。M6P受体在内体腔内因pH降至6而释放溶酶体水解酶后，被回收到这些由retromer包被的小泡中，随之返回TGN重复使用。因此retromer是实现受体循环利用的关键装置，与网格蛋白、COPI和COPII并列为几类典型的被膜小泡，其功能保证了溶酶体酶分选的持续进行。","src":"《第5章细胞内膜系统（下）新》p66；MBoC 7e 印刷 p752；《第5章细胞内膜系统（上）》p114","x":1},{"id":"75d39889","s":"c","g":"c04","n":"三联体骨架","e":"triskelion","d":"三联体骨架（triskelion）是网格蛋白的基本结构单元，呈三辐射状，由网格蛋白二聚体聚合形成。每条腿的末端向内弯折，使其N端结构域构成一个中间壳层；36个triskelion可组织成含12个五边形和6个六边形的网络。相互交织的腿形成外层的笼状结构，N端结构域从开口处伸出形成内层，并与衔接蛋白接触。这些单元能自组装成多面体笼，因此triskelion决定了网格蛋白笼的几何形状。","src":"《第5章细胞内膜系统（下）新》p42、p43、p44；MBoC 7e 印刷 p753"},{"id":"de8a9288","s":"c","g":"c04","n":"乙醛酸循环","e":"","d":"乙醛酸循环是植物细胞中过氧化物酶体的一种功能，发生在种子萌发过程中。过氧化物酶体降解种子内储存的脂肪酸，经氧化生成乙酰辅酶A，再通过乙醛酸循环转变为琥珀酸，琥珀酸可进一步异生为葡萄糖。这一途径把储存的脂肪酸转变成糖，为幼苗生长提供碳源。过氧化物酶体中常含两种酶：依赖黄素即FAD的氧化酶把底物氧化形成H2O2，过氧化氢酶则把H2O2分解为水和氧气。乙醛酸循环与光呼吸同为植物过氧化物酶体的重要功能。","src":"《第5章细胞内膜系统（上）》p124"},{"id":"9885ed41","s":"c","g":"c04","n":"信号假说","e":"signal hypothesis","d":"信号假说（signal hypothesis）由Blobel等于1975年正式提出，用以解释分泌蛋白在粗面内质网上合成的现象：合成始于游离核糖体；N端信号序列靠自由碰撞与内质网膜接触，然后插入内质网的膜；蛋白质以袢环形式穿过内质网膜。蛋白质最终的存在方式取决于信号：若信号序列被信号肽酶切除，则完全进入腔内；若存在停止转移信号，则成为膜蛋白。此后体外实验证实了SRP与SRP受体在这一过程中的作用。","src":"《第5章细胞内膜系统（上）》p16；MBoC 7e 印刷 p701"},{"id":"09589bc0","s":"c","g":"c04","n":"信号斑","e":"signal patch","d":"信号斑（signal patch）是溶酶体酶上形成的一种特殊空间结构，由几段信号肽聚集在一起构成的三维结构表面，即折叠后蛋白质表面上的一个斑块，可被磷酸转移酶识别。它是蛋白质分选信号的一种形式，与线性的信号肽不同，其识别依赖折叠后蛋白质表面的特定氨基酸排布。正是这一信号使溶酶体水解酶的寡糖获得M6P标记；由于多数水解酶含多个寡糖，可因此获得多个M6P基团，形成高亲和力信号。","src":"《第5章细胞内膜系统（上）》p109；MBoC 7e 印刷 p779","x":1},{"id":"a53d9a98","s":"c","g":"c04","n":"信号肽","e":"signal peptide","d":"信号肽（signal peptide）是引导肽链进入内质网腔的序列，又称开始转移序列，即start transfer sequence。其序列特征为15～35个氨基酸残基，其中含有4～12个疏水残基；位置可以是N端突出的一段肽，也可以位于肽链内部。需要进入内质网的跨膜蛋白、分泌蛋白、需要糖基化修饰的蛋白，以及需要严格空间分隔的酶，都依靠信号肽被引导到粗面内质网上合成与转运。","src":"《第5章细胞内膜系统（上）》p15","x":1},{"id":"c426f4e7","s":"c","g":"c04","n":"信号识别颗粒","e":"signal recognition particle (SRP)","d":"信号识别颗粒（signal recognition particle，SRP）是胞质中的核糖核蛋白颗粒，由6条多肽和一条约300个核苷酸的RNA组成。它含有三个功能域：翻译暂停结构域、信号肽识别结合位点、SRP受体蛋白结合位点。SRP结合部分合成的肽链上的内质网信号序列，使翻译暂停，并把该多肽连同所附着的核糖体引导到内质网膜；与SRP受体结合后，复合物被交给转位器，SRP随即释放，蛋白质合成恢复。","src":"《细胞生物学历年考题整理》p1；《第5章细胞内膜系统（上）》p27；MBoC 7e Glossary（PDF p1475）","x":1},{"id":"8e2f1163","s":"c","g":"c04","n":"光呼吸","e":"","d":"光呼吸是绿色植物叶肉细胞中过氧化物酶体的一种功能，指过氧化物酶体催化CO2固定反应副产物氧化的过程。过氧化物酶体中常含有两种酶：依赖黄素即FAD的氧化酶，作用是把底物氧化形成H2O2；过氧化氢酶，作用是把H2O2分解，形成水和氧气。因此过氧化物酶体既能处理氧化反应产生的H2O2，又能分解脂肪酸等高能分子向细胞直接提供热能，在植物中还参与乙醛酸循环。这些反应都在过氧化物酶体内完成。","src":"《第5章细胞内膜系统（上）》p124"},{"id":"0db2917a","s":"c","g":"c04","n":"光面内质网","e":"smooth ER (SER)","d":"光面内质网（smooth ER, SER）是内质网中不与核糖体结合的区域，多由小管与小囊构成。它不合成分泌蛋白，而为脂类合成转运的主要场所，并参与糖原分解与葡萄糖释放、Ca2+浓度调节及解毒。解毒依赖膜上丰富的氧化酶系统，如细胞色素P450与NADH细胞色素C还原酶，可把有害物质转化为易排出的产物。此类酶称混合功能氧化酶（mixed-function oxidase），每氧化一分子底物需消耗一分子氧，并把NADPH转变为NADP+。","src":"《第5章细胞内膜系统（上）》p41、p45；MBoC 7e Glossary PDF p1475"},{"id":"dccf028c","s":"c","g":"c04","n":"光面内质网","e":"SER","d":"光面内质网（SER）是内质网中不附着核糖体的部分，形态上多由小管与小囊构成不规则的网状结构，与粗面内质网同属连续的内膜系统。它的功能不涉及分泌蛋白合成，而集中在三个方面：一是糖原分解并释放游离葡萄糖，供细胞使用；二是脂类的合成与转运，包括合成类固醇激素、形成脂蛋白颗粒；三是调节胞内Ca2+浓度，兼具储存与释放钙离子的作用。此外，光面内质网富含氧化酶系统，能对药物等有害物质进行脱毒，是细胞解毒的重要场所。","src":"《第5章细胞内膜系统（上）》p12、p41、p45"},{"id":"812b54df","s":"c","g":"c04","n":"内体","e":"endosome","d":"内体（endosome）是质膜内陷并缢缩后形成的膜包围小泡，是内吞分子与新合成膜蛋白共同的分选场所。其膜上含有H+ ATPase，使腔内维持pH 5～6的酸性环境，内吞分子在此酸性条件下与受体分离。分离后的受体有三种去向：返回质膜再循环、被送往溶酶体降解，或经转胞吞作用运至细胞另一侧。内体的分选还依赖转运必需内体分选复合物（ESCRT），把待降解的膜蛋白分入向内凹陷的小泡，而需回收的蛋白则被排除。","src":"《第5章细胞内膜系统（下）新》p20、p32、p72；MBoC 7e 印刷 p750","x":1},{"id":"156e16c7","s":"c","g":"c04","n":"内质网","e":"endoplasmic reticulum","d":"内质网（endoplasmic reticulum）是由分支小管与扁平囊（潴泡）构成的网状迷宫，遍布细胞质，其膜与核外膜连续，共同围成一个连续的内腔即ER腔，该腔与内外核膜之间的间隙相通。它的膜通常超过动物细胞总膜量的一半，体积可占细胞总体积10%以上，是多数真核细胞中最大的细胞器。内质网外表面称胞质溶胶面，内表面称潴泡面，在脂类合成以及膜蛋白、分泌蛋白的合成中居中心地位，并有微粒体、肌质网等特殊类型。","src":"《第5章细胞内膜系统（上）》p13；MBoC 7e 印刷 p698"},{"id":"e3fe99ca","s":"c","g":"c04","n":"内部信号序列","e":"internal noncleavable signal sequences","d":"内部信号序列（internal noncleavable signal sequences）是位于肽链内部、不被信号肽酶切除的一类信号序列，见于单次跨膜蛋白的跨膜信号与膜蛋白定向过程。与位于N端、引导肽链进入内质网腔后可被切除的信号肽不同，它以疏水段形式兼作跨膜区，把肽链锚定在内质网膜上，并决定蛋白在膜上的取向。在跨膜信号系统中，它与起始转移信号、终止转移序列和可切割信号序列并列，共同决定单次跨膜蛋白插入内质网膜的方式。","src":"《第5章细胞内膜系统（上）》p29、p31"},{"id":"dcd2e3bd","s":"c","g":"c04","n":"分子伴侣调节的自噬","e":"chaperone-mediated autophagy (CMA)","d":"分子伴侣调节的自噬（chaperone-mediated autophagy, CMA）是细胞自噬的一种类型，与巨自噬、微自噬并列。它的特点是底物蛋白不经膜泡包裹，而由Hsp70类似的分子伴侣识别胞浆中带有KFERQ序列的底物蛋白，以非折叠状态直接运送至溶酶体，再递送入腔降解。由于依靠序列标签而非随机包裹，CMA对底物具有选择性，主要负责清除特定的可溶蛋白，与巨自噬清除大分子复合物和细胞器的分工不同。","src":"《第5章细胞内膜系统（上）》p99"},{"id":"7840f6e8","s":"c","g":"c04","n":"单体G蛋白","e":"monomeric GTP-binding protein","d":"单体G蛋白（monomeric GTP-binding protein）是一类小GTP酶，以结合状态决定活性：结合GTP时为活性状态，结合GDP时为非活性状态。在细胞内，其活化由鸟嘌呤核苷释放蛋白（GNRP，即鸟嘌呤核苷交换因子GEF）促进，使GDP解离而换上GTP；失活则由GTP酶激活蛋白（GAP）促进，加速GTP水解。与异三聚体大G蛋白不同，单体G蛋白转导许多类细胞表面受体发出的信号，并参与膜泡运输中的衣被装配。","src":"《第5章细胞内膜系统（下）新》p61；MBoC 7e 印刷 p880"},{"id":"5934863e","s":"c","g":"c04","n":"反面高尔基网络","e":"TGN","d":"反面高尔基网络（TGN）是高尔基体靠近分泌面一侧的网络结构，由相互连接的管状与囊状结构组成，是蛋白质与脂质离开高尔基体的出口。溶酶体水解酶在此被M6P受体识别，连同衔接蛋白与网格蛋白一起包装入运输小泡，送往内体；其他蛋白则被分装到不同小泡运往别处。TGN也是调节型分泌途径的分选位点，M6P受体等可经retromer被回收到TGN，从而反复参与新一批溶酶体酶的分选。","src":"《第5章细胞内膜系统（上）》p65、p67；MBoC 7e 印刷 p778","x":1},{"id":"64d81189","s":"c","g":"c04","n":"发动蛋白","e":"dynamin","d":"发动蛋白（dynamin）是一种胞质GTP酶，在网格蛋白有被小泡形成过程中结合于出芽的颈部。多个发动蛋白分子在颈部组装成螺旋，并招募其他蛋白，使相邻的脂双层不稳定；随后发动蛋白水解自身结合的GTP，引起构象改变，把已装配完成的小泡从质膜上切离，即完成掐断。在无细胞提取物中，网格蛋白有被小泡的掐断同样依赖发动蛋白的GTP水解，说明这一GTP酶活性是小泡断离的必要条件。","src":"《第5章细胞内膜系统（下）新》p55、p59；MBoC 7e 印刷 p757","x":1},{"id":"a8a27f18","s":"c","g":"c04","n":"受体介导的内吞","e":"receptor-mediated endocytosis","d":"受体介导的内吞（receptor-mediated endocytosis）是细胞经受体特异性地摄入胞外大分子的内吞方式。被转运分子先与互补的跨膜受体蛋白结合，受体－配体复合物在网格蛋白有被小窝处浓集，随后以网格蛋白有被小泡的形式进入细胞。典型内吞物包括LDL、转铁蛋白、胰岛素及多数蛋白激素和糖蛋白。进入内体后，酸性pH使配体与受体分离，受体可回膜再循环；LDL则被送入溶酶体，其胆固醇酯水解释放游离胆固醇。","src":"《第5章细胞内膜系统（下）新》p12、p28；MBoC 7e 印刷 p791","x":1},{"id":"c2da253a","s":"c","g":"c04","n":"可溶性NSF附着蛋白受体","e":"SNARE (soluble NSF attachment protein receptor)","d":"可溶性NSF附着蛋白受体（SNARE）是介导膜泡与靶膜融合的膜蛋白家族。位于运输小泡膜上的称v-SNARE，位于靶膜上的称t-SNARE，二者互补配对，使小泡与靶膜相互靠近并特异性地识别，是融合反应的核心。融合完成后，v-SNARE与t-SNARE形成的复合物十分稳定，需由NSF蛋白（可溶性NSF附着蛋白）催化解离，才能供下一轮融合使用。因此SNARE既决定融合的特异性，又需被循环利用。","src":"《第5章细胞内膜系统（下）新》p79、p80"},{"id":"4ae06abf","s":"c","g":"c04","n":"吞噬作用","e":"phagocytosis","d":"吞噬作用（phagocytosis）又称胞吃作用（cellular eating），是细胞以肌动蛋白介导的膜运动包裹细菌等大颗粒的内吞方式，主要见于巨噬细胞和中性粒细胞。颗粒被包入后形成吞噬体（phagosome），再与溶酶体融合为吞噬溶酶体（phagolysosome），由酸性水解酶将其消化。吞噬的启动依赖细胞表面受体识别补体成分、病原体表面的寡糖或凋亡细胞暴露的磷脂酰丝氨酸；过程中特定磷酸肌醇的生成与消耗按序引导吞噬体的内陷。","src":"《第5章细胞内膜系统（下）新》p13、p15；MBoC 7e 印刷 p804"},{"id":"fe778708","s":"c","g":"c04","n":"回收内体","e":"recycling endosome","d":"回收内体（recycling endosome）是由细径小管组成的膜网络，集中于微管组织中心附近，是受体再循环路径上的中间站。受体释放配体后，汇集于缺乏液相标记的膜区，经此中转返回细胞表面。回收内体还可作为特化质膜蛋白的胞内储存库：脂肪细胞与肌细胞在胞内储存大量葡萄糖转运蛋白，胰岛素与受体结合后触发信号通路，使这些转运蛋白快速插入质膜，从而大幅增加葡萄糖摄取。","src":"《第5章细胞内膜系统（下）新》p32、p33；MBoC 7e 印刷 p794"},{"id":"934a7959","s":"c","g":"c04","n":"外泌体","e":"exosome","d":"外泌体（exosome）是细胞释放的胞外囊泡的一种，与ectosome（ARMM）并列。它经内体途径产生：晚期内体的膜向内凹陷，形成腔内小泡，含这些腔内小泡的细胞器即多泡体，多泡体与质膜融合后把腔内小泡释放到细胞外，即成为外泌体。其货物经分选装入，ESCRT复合体参与这一过程。外泌体携带蛋白质等成分，是细胞间传递信息的载体，也是胞外囊泡研究与分离的主要对象之一。","src":"《第5章细胞内膜系统（下）新》p73、p74、p75"},{"id":"917d8a04","s":"c","g":"c04","n":"多泡体","e":"multivesicular bodies","d":"多泡体（multivesicular body）是内体成熟途径上的中间结构。随着内体成熟，其膜上的斑块向内凹陷并掐断，在腔内形成腔内小泡；因电镜下呈多泡外观，故称多泡体。多泡体携带待降解的内吞膜蛋白，例如已结合配体的EGF受体，这些蛋白选择性分配到内凹的膜上，从而完全暴露于日后降解它们的消化酶，而需回收的蛋白被排除在外。ESCRT复合体介导腔内小泡的形成，单个泛素分子则作为分选标记。","src":"《第5章细胞内膜系统（下）新》p67、p68；MBoC 7e 印刷 p796"},{"id":"6607f850","s":"c","g":"c04","n":"微粒体","e":"microsome","d":"微粒体（microsome）是细胞匀浆时内质网碎片化所形成的小囊泡，属特殊类型的内质网，可经离心纯化获得。其囊泡内腔相当于内质网腔，膜也保留了原来的取向，因此在体外实验中常被用来重建蛋白质跨膜转运：在无细胞体系中加入粗面内质网来源的微粒体，正在翻译的分泌蛋白可进入囊泡腔内并切成正确大小，而去除微粒体则不能。这一结果直接支持了信号假说，使微粒体成为研究信号肽与转位的重要工具。","src":"《第5章细胞内膜系统（上）》p13、p14、p21；MBoC 7e 印刷 p701"},{"id":"9d2c4f64","s":"c","g":"c04","n":"无被小泡","e":"uncoat vesicles","d":"无被小泡（uncoat vesicles）是网格蛋白有被小泡脱去外被后形成的运输小泡。其形成过程为：质膜上先出现网格蛋白小窝（clathrin-coated pit），进而出芽成为有被小泡（coat vesicles），随后外被去聚合而成为无被小泡。外被的去除由分子伴侣Hsp70催化，需要ATP供能；此外Ca2+也参与包被的形成与去被过程。脱去衣被后小泡才能与靶膜融合，因此去被是膜泡运输中不可省略的一步。","src":"《第5章细胞内膜系统（下）新》p46"},{"id":"7cdb1bcb","s":"c","g":"c04","n":"未折叠蛋白反应","e":"unfolded protein response (UPR)","d":"未折叠蛋白反应（unfolded protein response, UPR）是内质网中错误折叠蛋白积累所触发的细胞应答。激活后内质网发生扩张，并提高编码内质网分子伴侣与降解酶等基因的转录，以增强折叠能力、加快清除错误折叠蛋白。其信号涉及XBP1 mRNA的剪接、ATF6的胞质段进入核内作为转录因子，以及PERK激酶等通路。UPR与ERAD等机制共同构成蛋白质质控，使只有正确折叠的蛋白被运出内质网。","src":"《第5章细胞内膜系统（上）》p53、p56、p58；MBoC 7e Glossary PDF p1479"},{"id":"6040a76e","s":"c","g":"c04","n":"泛素","e":"ubiquitin","d":"泛素（ubiquitin）是存在于所有真核细胞中的小分子、高度保守的蛋白质，可共价连接到底物蛋白的赖氨酸残基上。其活化由E1（泛素激活酶）以ATP依赖的方式经硫酯键完成，再转移至E2（泛素结合酶），由E3（泛素连接酶）把泛素加到靶蛋白上；短泛素链可标记蛋白由蛋白酶体降解。细胞周期中SCF与APC即为多亚基泛素连接酶，分别主要在间期与有丝分裂期使底物泛素化降解。","src":"《第10章 细胞分裂与细胞周期(下)》p51、p53；MBoC 7e 印刷 p164","x":1},{"id":"b62d9c64","s":"c","g":"c04","n":"液泡","e":"plant cell vacuoles","d":"液泡（plant cell vacuoles）是植物细胞中由液泡膜包被的大型膜性细胞器，其功能与动物细胞的溶酶体相当，但更为多样，兼具储存、消化与代谢调节作用。液泡是代谢产物的储存场所：景天科等肉质植物白天气孔关闭、夜间开放，夜间由PEP羧化酶固定CO2形成草酰乙酸和苹果酸，苹果酸积累于液泡中；白天苹果酸脱羧生成CO2和丙酮酸，此即景天酸代谢（CAM）。可见液泡通过贮存与释放代谢物参与细胞代谢的时序调节。","src":"《第5章细胞内膜系统（上）》p92、p93；《第7章细胞的能量代谢》p104；MBoC 7e 印刷 p800"},{"id":"2642aa3a","s":"c","g":"c04","n":"混合功能氧化酶","e":"mixed-function oxidase","d":"混合功能氧化酶（mixed-function oxidase）是光面内质网上催化解毒反应的一类氧化酶，属其丰富的氧化酶系统，与细胞色素P450、NADH细胞色素C还原酶等共同作用，把许多有害物质转化为易于排出的物质。其特点在于每氧化一分子底物需消耗一分子氧，同时把NADPH转变成NADP+；所耗氧分子中的一个氧原子出现在水中，另一个出现在产物中。因一个氧原子进入产物、一个进入水，反应具有混合的功能，故得此名。","src":"《第5章细胞内膜系统（上）》p45"},{"id":"f14481e6","s":"c","g":"c04","n":"溶酶体","e":"lysosome","d":"溶酶体（lysosome）是由单层膜包被、含多种酸性水解酶的细胞器，典型溶酶体约含50种水解酶，均在最适酸性pH下起作用，酸性磷酸酶是其标志酶。其膜上嵌有质子泵以维持腔内低pH，并含多种载体蛋白向外转运水解产物；膜蛋白高度糖基化，膜中胆固醇有助于膜稳定。溶酶体具异质性，分初级、次级与残余体，功能包括细胞内消化（内吞、自噬、吞噬）、自溶作用、杀死外源异物、激素分泌调节以及形成精子顶体等。","src":"《第5章细胞内膜系统（上）》p89、p90；MBoC 7e 印刷 p798","x":1},{"id":"ab08ab46","s":"c","g":"c04","n":"溶酶体贮积症","e":"lysosomal storage disease","d":"溶酶体贮积症（lysosomal storage disease）是由溶酶体水解酶遗传缺陷引起的一类疾病。缺陷使未被消化的底物在溶酶体中积累，造成严重病理后果，最常累及神经系统。多数病例是编码某种溶酶体水解酶的结构基因突变，如Hurler病中降解某些糖胺聚糖链所需的酶缺陷或缺失；最严重的一型则源于GlcNAc磷酸转移酶缺陷，使酶无法获得M6P标记而不能正确定位。此外还包括糖原贮积症、矽肺病、类风湿关节炎等。","src":"《第5章细胞内膜系统（上）》p117；MBoC 7e 印刷 p779"},{"id":"5fef03ca","s":"c","g":"c04","n":"潴泡成熟模型","e":"cisternal maturation model","d":"潴泡成熟模型（cisternal maturation model）是关于高尔基体如何工作的一种假说。它预测每个潴泡都是短暂结构，通过先获得、随后失去特定的高尔基驻留蛋白，由早期潴泡逐渐成熟为晚期潴泡；在此观点下，分泌货物蛋白不需靠小泡逐级搬运，而是留在成熟的潴泡内随之前行，从而穿过高尔基体。这与稳定区室模型相对，后者认为潴泡长寿、货物靠小泡在潴泡间转运；两模型的分歧在于潴泡本身是否短暂、货物是否随潴泡前行。","src":"《第5章细胞内膜系统（上）》p79"},{"id":"9e6956c8","s":"c","g":"c04","n":"甘露糖-6-磷酸","e":"M6P","d":"甘露糖-6-磷酸（M6P）是溶酶体酶上的分选标志。溶酶体酶在粗面内质网经N-连接糖基化合成后，转运至高尔基体进一步加工，由N-乙酰葡萄糖胺磷酸转移酶与N-乙酰葡萄糖苷酶的作用加上M6P。M6P受体蛋白在pH 6.5～7时与M6P结合，在酸性条件（pH=6）下脱落，故主要存在于高尔基体外侧网络，某些细胞中亦见于质膜；这一依赖M6P的分选即为溶酶体生物发生的甘露糖-6-磷酸途径。","src":"《第5章细胞内膜系统（上）》p107、p114；MBoC 7e 印刷 p778","x":1},{"id":"ca6eadee","s":"c","g":"c04","n":"甘露糖-6-磷酸","e":"mannose 6-phosphate (M6P)","d":"甘露糖-6-磷酸（mannose 6-phosphate, M6P）是动物细胞溶酶体水解酶特有的标记。这类酶在粗面内质网合成并完成N-连接糖基化后，于高尔基体中被加上M6P基团，且只加在这些可溶性酶N-连接寡糖上。反面高尔基网络中的跨膜M6P受体识别M6P，在腔面结合水解酶，在胞质面结合正在装配的网格蛋白衣被的衔接蛋白，从而把水解酶包装进网格蛋白有被小泡，运往内体。","src":"《第5章细胞内膜系统（上）》p106、p107；MBoC 7e 印刷 p778"},{"id":"f8f3d258","s":"c","g":"c04","n":"磷酸肌醇","e":"phosphoinositides (PIP)","d":"磷酸肌醇（phosphoinositides, PIP）是含磷酸化肌醇衍生物的膜脂，在质膜中含量很少，却在真核细胞中用于标记不同的膜与膜结构域。PI与各种PIP之间的相互转化在细胞内高度区室化，因而不同细胞器膜上具有特征性的磷酸肌醇组成，可招募特定的胞质蛋白。在膜泡运输中，磷酸肌醇参与衣被的起始装配，帮助clathrin与adaptin定位；在吞噬作用中，特定磷酸肌醇的生成与消耗按序引导吞噬体形成。","src":"《第5章细胞内膜系统（下）新》p41、p52；MBoC 7e Glossary PDF p1469"},{"id":"55b2d5ef","s":"c","g":"c04","n":"稳定区室模型","e":"stable compartments model","d":"稳定区室模型（stable compartments model）是关于高尔基体组织的假说之一。它预测每个潴泡都是长寿结构，各自保留一套特征性的高尔基驻留蛋白，区室身份稳定不变；在此观点下，分泌货物蛋白由运输小泡从一个潴泡运送到下一个潴泡，逐级穿行高尔基体。该模型与潴泡成熟模型相对，后者认为潴泡本身短暂存在，靠获得和失去驻留蛋白由早期成熟为晚期，货物则留在潴泡内随之前行。","src":"《第5章细胞内膜系统（上）》p79"},{"id":"65fbbf4e","s":"c","g":"c04","n":"粗面内质网","e":"rough ER (RER)","d":"粗面内质网（rough ER, RER）是表面附着核糖体的内质网，因其糙面外观得名。核糖体附着于胞质面，使新合成的肽链能直接经转位因子进入ER腔，因而它是分泌蛋白、跨膜蛋白、需糖基化修饰的蛋白以及需严格空间分隔的酶进行合成与运输的场所。信号肽一般长15～35个氨基酸残基，含4～12个疏水残基，引导肽链进入内质网腔，又称开始转移序列；合成后还可进行N-连接糖基化等修饰。","src":"《第5章细胞内膜系统（上）》p15、p107；MBoC 7e Glossary PDF p1474"},{"id":"22950aa7","s":"c","g":"c04","n":"粗面内质网","e":"RER","d":"粗面内质网（RER）在形态上呈扁平囊状，膜外附着大量核糖体，与光面内质网相连而功能分工不同，二者共同构成连续的内膜系统。它负责合成四类蛋白：跨膜蛋白、分泌蛋白、需要糖基化修饰的蛋白，以及需要严格空间分隔的酶。核糖体附着于膜上，使合成的肽链在信号肽引导下边翻译边进入ER腔，随后进行N-连接糖基化等加工，再经高尔基体进一步修饰；溶酶体酶即在此完成糖基化后被运往高尔基体。","src":"《第5章细胞内膜系统（上）》p12、p15"},{"id":"b5fc21a5","s":"c","g":"c04","n":"糖基化","e":"glycosylation","d":"糖基化（glycosylation）是蛋白质的重要修饰，分N-连接与O-连接两类。N-连接糖基化发生在天冬酰胺上，序列特征为Asn-X-Ser/Thr，故又称天冬酰胺连接糖基化；O-连接糖基化则把糖链转移到多肽链丝氨酸、苏氨酸或羟赖氨酸的羟基上。在高尔基体中，糖基逐个加上，通常先加N-乙酰半乳糖胺。糖链的作用包括抵抗消化酶、作为转运信号以及帮助蛋白质折叠，也构成细胞表面的糖被。","src":"《第5章细胞内膜系统（上）》p51、p76；《第3章 细胞膜与表面（上）》p25；MBoC 7e 印刷 p773"},{"id":"6a451482","s":"c","g":"c04","n":"糖基磷脂酰肌醇（GPI锚）","e":"GPI: glycosylphosphatidylinositol","d":"糖基磷脂酰肌醇（GPI）锚是经转酰胺基酶（transamidase）添加到蛋白质上的一种糖脂锚，其成分即糖基化磷脂酰肌醇（glycosylphosphatidylinositol）。GPI锚以磷脂酰肌醇的脂肪酸链插入膜脂双层，把蛋白质锚定在膜上，使蛋白不跨越膜而附着于膜表面。与跨膜蛋白不同，GPI锚定蛋白没有胞质侧肽段，其释放可受磷脂酶调控；它们常富集于脂筏，细胞膜穴样内陷中即富含GPI锚定蛋白。","src":"《第5章细胞内膜系统（上）》p38、p47"},{"id":"9ceae515","s":"c","g":"c04","n":"糖基转移酶","e":"","d":"糖基转移酶是高尔基复合体的标志酶，常用于细胞化学工作中识别高尔基体。高尔基体中该酶的数量与细胞的分泌功能相关：分泌功能越旺盛的细胞，糖基转移酶越多。从膜组成看，高尔基体以蛋白质为主，蛋白质约占60%、脂类约占40%，与内质网（蛋白质20%、脂50%～60%）形成对比。糖基转移酶催化糖基从供体转移到受体，是高尔基体中寡糖链加工与O-连接糖基化的执行者；其数量之多也反映高尔基体以加工与分选为主要职能。","src":"《第5章细胞内膜系统（上）》p68"},{"id":"b90de87b","s":"c","g":"c04","n":"组成性胞吐途径","e":"constitutive exocytosis pathway","d":"组成性胞吐途径（constitutive exocytosis pathway）是细胞分泌的两条途径之一。其特点是运输小泡持续不断地形成，把蛋白质从高尔基体运送到细胞表面，无需胞外信号触发。该途径的功能是为质膜补充新合成的脂质与蛋白质，从而维持质膜组成并实现质膜的更新与生长。与之相对的调节型胞吐途径中，激素、黏液或消化酶先储存于分泌小泡，待胞外信号刺激才释放，见于特化的分泌细胞。","src":"《第5章细胞内膜系统（下）新》p6"},{"id":"27d4f7ae","s":"c","g":"c04","n":"细胞膜穴样内陷","e":"caveolae","d":"细胞膜穴样内陷（caveolae）是质膜上高密度分布的小凹陷，电镜下呈深陷的烧瓶状，其胞质面呈特征性的花椰菜纹理，且看不到胞质蛋白被膜。其膜属富含胆固醇、糖鞘脂与GPI锚定蛋白的脂筏，主要结构蛋白为caveolin，一种多次跨膜蛋白。与网格蛋白小泡不同，caveolae靠膜脂组成而非胞质衣被的装配来收集货物；它可从质膜掐断，把内容物送入内体样区室，或经转胞吞作用送到极化细胞对侧的质膜。","src":"《第5章细胞内膜系统（下）新》p17、p18；MBoC 7e 印刷 p790"},{"id":"75a4ba99","s":"c","g":"c04","n":"终止转移序列","e":"stop transfer sequence","d":"终止转移序列（stop transfer sequence）是跨膜信号系统中的一类序列，其作用是使肽链向ER腔内的转移停止，并把肽链锚定在膜上，本身构成跨膜区段。当肽链含有终止转移序列时，转位过程在该处中断，蛋白即成为跨膜蛋白而非完全进入腔内；因此该序列的有无，决定肽链是完全进入ER腔还是被锚定在膜上。它与起始转移信号、可切割信号序列、内部信号序列配合，可决定单次跨膜蛋白的插入方式与在膜上的取向。","src":"《第5章细胞内膜系统（上）》p16、p29"},{"id":"741fcec1","s":"c","g":"c04","n":"网格蛋白","e":"clathrin","d":"网格蛋白（clathrin）是网格蛋白有被小泡衣被的主要蛋白，构成衣被的外层。它由三条重链和三条轻链组成，形成三联体骨架（triskelion）；36个三联体可组装成由12个五边形和6个六边形构成的多面体网状外被，因而三联体决定了衣被的几何形状。其N端结构域向内突出形成内层，与衔接蛋白接触；衔接蛋白位于网格蛋白笼与膜之间，负责结合货物受体的胞质尾并招募网格蛋白。","src":"《第5章细胞内膜系统（下）新》p42、p46；MBoC 7e 印刷 p753","x":1},{"id":"17c259fd","s":"c","g":"c04","n":"网格蛋白小窝","e":"clathrin-coated pit","d":"网格蛋白小窝（clathrin-coated pit）是质膜上网格蛋白装配并使之向内凹陷的部位，进而掐断形成网格蛋白有被小泡。它是受体介导内吞的入口：受体在网格蛋白小窝中浓集，使细胞得以高效摄取特定的胞外分子。LDL受体须借胞内段与AP2衔接蛋白结合而定位于网格蛋白小窝，才能被内吞。若受体该结合位点突变，细胞表面受体数量正常却不能集中于小窝，LDL虽能结合也不被内化，直接证明网格蛋白小窝对胆固醇摄取的重要性。","src":"《第5章细胞内膜系统（下）新》p46；MBoC 7e 印刷 p792"},{"id":"dcb44f8b","s":"c","g":"c04","n":"网格蛋白有被小泡","e":"clathrin coated vesicle","d":"网格蛋白有被小泡（clathrin coated vesicle）是衣被含网格蛋白的运输小泡，其衣被成分还包括衔接蛋白adaptin（AP1、AP2、AP3等）、小G蛋白ARF以及发动蛋白dynamin，另有磷酸肌醇参与。ARF参与网格蛋白与adaptin的起始装配，dynamin的GTP水解则负责小泡的掐断。它介导质膜→内体、高尔基体→溶酶体以及高尔基体→植物液泡之间的运输。","src":"《第5章细胞内膜系统（下）新》p41、p56；《细胞生物学历年考题整理》p6","x":1},{"id":"de321f06","s":"c","g":"c04","n":"翻译后转位","e":"post-translational translocation","d":"翻译后转位（post-translational translocation）指蛋白质在细胞质核糖体上完成合成后，再以前体蛋白形式跨膜转运进入细胞器的方式，真核生物中蛋白进入线粒体即属此类。与共翻译转位不同，它不依赖正在翻译的核糖体与膜的偶联，而需分子伴侣帮助肽链解折叠、转运后再折叠，并消耗ATP。内质网也可采用翻译后转位，尾锚定蛋白（tail-anchored proteins）即以这种方式插入内质网膜。","src":"《第5章细胞内膜系统（上）》p37、p40；《第7章细胞的能量代谢》p118；MBoC 7e 印刷 p708"},{"id":"1ac9e022","s":"c","g":"c04","n":"胞吐","e":"exocytosis","d":"胞吐（exocytosis）是细胞把物质排出胞外的过程，包括小泡的出芽（budding）、运输、停靠（docking），以及与靶膜的最后融合。运输小泡上装配有衣被蛋白，如网格蛋白、COPII和COPI；只有正确折叠和组装的蛋白才被运输。运输过程中被转运的蛋白与脂质的方向不变，即原朝向腔面的一侧在融合后朝向细胞外。胞吐分组成性与调节性两条途径，前者持续进行，后者需信号触发。","src":"《第5章细胞内膜系统（下）新》p10；MBoC 7e Glossary PDF p1455","x":1},{"id":"0e7fa635","s":"c","g":"c04","n":"胞吞","e":"endocytosis","d":"胞吞（endocytosis）是真核细胞摄入液体及大、小分子的过程。质膜的一部分内陷并缢缩，形成膜包围的囊泡即内体（endosome），把胞外物质带入细胞。胞吞包括三种方式：吞噬作用，由肌动蛋白介导，包裹细菌等大颗粒；胞饮作用，几乎在所有细胞中持续发生；受体介导的内吞，内吞物如LDL、转铁蛋白、胰岛素及多数蛋白激素和糖蛋白。内体中的物质随后被分选，或回膜，或送溶酶体降解。","src":"《第5章细胞内膜系统（下）新》p12；MBoC 7e 印刷 p749","x":1},{"id":"38e8dbbf","s":"c","g":"c04","n":"胞外囊泡","e":"extracellular vesicles","d":"胞外囊泡（extracellular vesicles）是细胞分泌到胞外的膜性囊泡，主要包括外泌体（exosome）与ectosome（ARMM）。外泌体经内体－多泡体途径产生，由多泡体与质膜融合后释放腔内小泡形成；ectosome则自质膜出芽释放。二者在来源与生成机制上不同，是胞外囊泡分类的主要依据。研究时可按囊泡的物理性质用过滤、沉淀、差速离心、密度梯度离心以及大小排阻色谱法等进行分离。","src":"《第5章细胞内膜系统（下）新》p73、p78"},{"id":"ee28ac17","s":"c","g":"c04","n":"胞饮","e":"pinocytosis","d":"胞饮（pinocytosis）又称胞饮作用（cellular drinking），是细胞持续摄取胞外液体与其中可溶物质的内吞方式，几乎在所有细胞中不断发生。液相中的物质随液体一起被小囊泡包裹摄入，经内体转入细胞，可与膜结合分子一同运输。胞饮分为液相内吞（fluid-phase endocytosis）与吸附内吞（absorption endocytosis）两类。与吞噬作用不同，它不以肌动蛋白包裹大颗粒，也不以降解大颗粒为主要目的。","src":"《第5章细胞内膜系统（下）新》p12、p13；MBoC 7e Glossary PDF p1469"},{"id":"a41ab6cc","s":"c","g":"c04","n":"膜泡运输","e":"vesicular transport","d":"膜泡运输（vesicular transport）是蛋白质在细胞各区间转运的方式之一，通过膜包围的中间载体（运输小泡或细胞器碎片）把蛋白质从一个区室运至另一个区室。它承担内质网→高尔基体、高尔基体→溶酶体或细胞膜，以及返回内质网的运输。与跨膜运输由转位因子直接把蛋白送入另一区室、门控运输经核孔、吞噬靠膜包裹大颗粒不同，膜泡运输不直接穿膜，而借小泡的出芽与融合完成转移。","src":"《第5章细胞内膜系统（上）》p5；《第5章细胞内膜系统（下）新》p83；MBoC 7e 印刷 p694"},{"id":"a6916a9c","s":"c","g":"c04","n":"膜泡运输","e":"vesicle trafficking","d":"膜泡运输（vesicle trafficking）指通过运输小泡在细胞器之间转运蛋白质与脂质的过程。小泡的形成需要衔接蛋白（adaptor proteins）等衣被成分参与，把货物收集到出芽部位，并以GTP为主要能源完成衣被装配与膜的重塑；小泡与靶膜的融合则需要互补的蛋白对，如Rab蛋白与SNARE，以保证停靠与融合的专一性。通过这一系统，分泌途径与内吞途径得以在两个方向上流动并保持区室身份。","src":"《第5章细胞内膜系统（下）新》p4、p83"},{"id":"ae3cbf8c","s":"c","g":"c04","n":"自噬体","e":"autophagosome","d":"自噬体（autophagosome）是自噬过程中包裹待降解物的双层膜囊泡，又称初始自噬空泡（AVi）。其双层膜在电镜下常呈两条平行的膜双层，中间为电子透明的裂隙；腔内含形态完整的胞质和/或细胞器，与细胞其他部位的胞质相似。自噬体随后与溶酶体融合，形成自噬溶酶体，降解其所包裹的内容物，以实现细胞稳态与细胞器更新。选择性自噬中，受体蛋白识别货物并结合自噬体特有的ATG8。","src":"《第12章 细胞衰老与细胞凋亡》p89、p94；MBoC 7e Glossary PDF p1446"},{"id":"9760c695","s":"c","g":"c04","n":"自噬溶酶体","e":"autolysosome","d":"自噬溶酶体（autolysosome）是自噬体与溶酶体或晚期内体融合后形成的降解性区室。与具双层膜的自噬体不同，晚期降解性自噬空泡与自噬溶酶体通常只有一层限制膜，腔内含处于不同降解阶段的胞质物质和/或细胞器。自噬体包裹部分胞质与需降解的细胞器、蛋白质后与之融合，由酸性水解酶分解内容物，分解产物可供细胞重新利用，从而实现细胞稳态与细胞器的更新，因此自噬溶酶体是自噬降解的最终场所。","src":"《第12章 细胞衰老与细胞凋亡》p89、p94"},{"id":"fdf03c20","s":"c","g":"c04","n":"自溶作用","e":"autolysis","d":"自溶作用（autolysis）是溶酶体的生理功能之一，指细胞被自身水解酶消化的过程。当细胞遭遇休克、缺氧等损伤，或胞内pH下降时，溶酶体膜稳定性下降乃至破裂，其中的酸性水解酶释放到细胞质中，把细胞自身成分分解。它与吞噬作用、自噬作用、内吞作用并列，都是溶酶体参与的细胞内消化形式；溶酶体膜的稳定性因而对细胞存活十分重要，膜破裂即导致自溶。在胚胎发育、形态发生与受精等生理过程中，溶酶体也以类似方式参与组织的重塑。","src":"《第5章细胞内膜系统（上）》p94、p117"},{"id":"62da2f94","s":"c","g":"c04","n":"蛋白质质控","e":"protein quality control","d":"蛋白质质控（protein quality control）是细胞确保只有正确折叠或正确靶向其他细胞器的蛋白质才被运输的策略，主要包括ERAD（内质网相关蛋白降解）与UPR（未折叠蛋白反应）。ERAD把折叠失败的蛋白从内质网取出并送蛋白酶体降解，UPR则扩大内质网并提高分子伴侣与降解酶的转录。此外，许多内质网驻留蛋白含KDEL序列，KDEL受体经COPI小泡把它们回收到内质网；葡萄糖基转移酶是判断蛋白是否正确折叠的关键酶。","src":"《第5章细胞内膜系统（上）》p53"},{"id":"6e323d5c","s":"c","g":"c04","n":"蛋白酶体","e":"proteasome","d":"蛋白酶体（proteasome）是胞质中具有蛋白水解活性的大分子复合体，负责降解被泛素化或其他方式标记的蛋白质。其结构包括中央圆柱状的蛋白酶核心与两端的帽，帽中的AAA类去折叠酶环识别带多泛素链的靶蛋白，将其去折叠后送入核心腔内的活性位点逐步消化。细胞周期中SCF与APC等多亚基泛素连接酶把底物泛素化，再由蛋白酶体降解，从而实现蛋白质的选择性清除；除清除异常蛋白外，这一体系也通过降解周期调节因子参与细胞周期的推进。","src":"《第10章 细胞分裂与细胞周期(下)》p51；MBoC 7e 印刷 p385"},{"id":"1db1a27c","s":"c","g":"c04","n":"衔接蛋白","e":"adaptin (adaptor)","d":"衔接蛋白（adaptin）是网格蛋白有被小泡衣被的组成成分，位于网格蛋白笼与膜之间形成内层。其外表面即胞质侧结合网格蛋白分子，把网格蛋白骨架固定在小泡表面；其内表面识别整合膜蛋白胞质尾中的分选信号，从而把货物收集入小泡。衔接蛋白分多种：AP1识别M6P受体，AP2识别细胞质膜受体和M6P受体，并由α、β亚基参与；AP3等其他类型则参与另一些运输路线。衔接蛋白因而同时决定衣被在膜上的组装位置与所运货物的选择性。","src":"《第5章细胞内膜系统（下）新》p49；《细胞生物学历年考题整理》p6","x":1},{"id":"7b104a29","s":"c","g":"c04","n":"衣被小泡","e":"coated vesicle","d":"衣被小泡（coated vesicle）是胞质面带有蛋白笼状衣被的小型膜性细胞器，由膜上被膜区即有被小窝掐断而成。衣被可由网格蛋白构成，也可由其他蛋白构成，据此分为网格蛋白有被小泡、COPII被膜小泡、COPI被膜小泡与retromer等类型。衣被的作用是收集货物并使膜变形，不同衣被对应不同的运输路线与货物分选信号，如COPII负责内质网→高尔基体，COPI承担回收方向。","src":"《第5章细胞内膜系统（下）新》p35、p36；MBoC 7e Glossary PDF p1450"},{"id":"402694bc","s":"c","g":"c04","n":"被膜小泡","e":"coated vesicles","d":"被膜小泡（coated vesicles）是衣被由特定蛋白组成、承担不同运输路线的膜泡，主要有三种类型。披网格蛋白小泡（clathrin-coated vesicle）负责质膜→内体、高尔基体→溶酶体或植物液泡；COPII被膜小泡负责从内质网到高尔基体的正向运输；COPI被膜小泡则承担回收方向，如高尔基体→内质网。三者的衣被蛋白不同，因而在电镜下形态有别，其中网格蛋白衣被的结构更规则。","src":"《第5章细胞内膜系统（下）新》p35、p36、p41"},{"id":"dc87f785","s":"c","g":"c04","n":"调节性胞吐途径","e":"regulated exocytosis pathway","d":"调节性胞吐途径（regulated exocytosis pathway）是细胞分泌的两条途径之一。其特点是激素、黏液或消化酶等产物先储存于分泌小泡中，并不立即释放，只有当胞外信号刺激时才触发小泡与质膜融合，把内容物排出。该途径见于特化的分泌细胞，可使分泌在时间上受控、并可在需要时集中释放。与之相对的组成性胞吐途径则持续进行，为质膜补充新合成的脂质与蛋白质。","src":"《第5章细胞内膜系统（下）新》p6"},{"id":"23ff45af","s":"c","g":"c04","n":"起始转移信号","e":"start transfer signal","d":"起始转移信号（start transfer signal）是引导肽链插入内质网膜、启动跨膜转移的信号序列，属跨膜信号系统的一类。在单次跨膜蛋白中，它与终止转移序列、可切割信号序列、内部信号序列配合，共同决定蛋白的插入方式与膜上取向；其中疏水核心两侧正电荷氨基酸的分布是决定取向的因素。可切割的起始转移信号在肽链进入ER腔后被信号肽酶切除，不可切割者则兼作跨膜段保留在膜中。","src":"《第5章细胞内膜系统（上）》p29、p31"},{"id":"d2306030","s":"c","g":"c04","n":"跨膜运输","e":"transmembrane transport","d":"跨膜运输（transmembrane transport）是蛋白质进入细胞器的运输方式之一，指转位因子直接把特定蛋白从胞质送入拓扑上不同的空间，或送入脂双层成为整合膜蛋白；被转运的蛋白通常需解折叠才能穿过转位因子。蛋白质到内质网、线粒体、过氧化物酶体的运输均属此类，与经核孔的门控运输、经小泡的膜泡运输以及吞噬作用并列。就小分子而言，跨膜运输由转运蛋白和通道蛋白承担，是细胞维持离子浓度与代谢物供应的基础。","src":"《第3章 细胞膜与表面（上）》p56；MBoC 7e 印刷 p694、p637"},{"id":"01a983dd","s":"c","g":"c04","n":"转位因子","e":"translocon (Sec61)","d":"转位因子（translocon，Sec61复合体）是介导蛋白质跨内质网膜转移的膜通道复合体，Sec61α是其组分之一。在共翻译转位中，信号肽先被SRP识别、结合到SRP受体，使核糖体停靠到内质网膜并与转位因子结合，正在延伸的肽链随即穿通道进入ER腔；通道侧面可开启，使疏水段进入脂双层而形成跨膜蛋白。转位因子因而同时承担可溶蛋白向腔面的转运与膜蛋白在膜内的嵌入。","src":"《第5章细胞内膜系统（上）》p25、p26","x":1},{"id":"192cf7d6","s":"c","g":"c04","n":"转胞吞作用","e":"transcytosis","d":"转胞吞作用（transcytosis）是极性细胞把一处质膜内吞的物质经小泡跨细胞转运、再从另一处质膜以胞吐释放的过程。内吞物先进入早内体，经回收内体等中间站转运至对侧质膜结构域；在肠上皮等极性细胞中，抗体可借此由一侧转运至血液和乳汁，也是母体抗体传递给新生个体的途径之一。细胞膜穴样内陷也能介导转胞吞，把内容物送到极化细胞对侧的质膜，部分动物病毒亦经此进入细胞。","src":"《第5章细胞内膜系统（下）新》p18、p21；MBoC 7e 印刷 p794"},{"id":"92d50fb3","s":"c","g":"c04","n":"转运必需内体分选复合物","e":"ESCRT (endosomal sorting complexes required for transport)","d":"转运必需内体分选复合物（ESCRT）主要由ESCRT-0、ESCRT-I、ESCRT-II、ESCRT-III及其他辅助蛋白组分构成，在真核生物中高度保守。它执行膜剪切功能，参与内体分选、病毒出芽与胞质分裂，并调节信号通路转导、细胞极性、细胞自噬、外泌体形成与细胞质膜损伤修复等过程；多泡体腔内小泡的形成即由其介导。ESCRT组分异常与发育异常、肿瘤等一系列疾病密切相关。","src":"《第5章细胞内膜系统（下）新》p70、p72"},{"id":"359d1722","s":"c","g":"c04","n":"过氧化氢酶","e":"catalase","d":"过氧化氢酶（catalase）是定位于过氧化物酶体的酶，能高效地把H2O2分解为H2O和O2。过氧化物酶体常含两类酶：依赖黄素（FAD）的氧化酶把底物氧化并生成H2O2，过氧化氢酶随即将其分解，两者配合完成氧化反应而不使H2O2扩散为害。它还可利用H2O2对其他底物进行过氧化反应。过氧化氢酶与尿酸氧化酶同为微体的识别标志酶，在肝、肾细胞的解毒中起重要作用；由它分解H2O2，是过氧化物酶体处理这一有毒中间产物的主要方式。","src":"《第5章细胞内膜系统（上）》p120、p123、p124"},{"id":"470e15db","s":"c","g":"c04","n":"过氧化物酶体","e":"peroxisome","d":"过氧化物酶体（peroxisome）是由单层膜包被的小型细胞器，含一种或几种氧化酶，利用分子氧氧化各种底物并生成过氧化氢（H2O2），同时含分解H2O2的酶。其蛋白由核基因编码，在细胞质基质中合成后经PTS信号转运进入；PTS1为SKL，多在基质蛋白C端，PTS2位于某些基质蛋白N端，膜上有相应受体。过氧化物酶体经分裂形成子代并进一步装配成熟，其膜脂可能在内质网合成后转运而来。","src":"《第5章细胞内膜系统（上）》p121、p124、p125；MBoC 7e 印刷 p724"},{"id":"90293150","s":"c","g":"c04","n":"过氧化物酶体","e":"peroxisome（又称微体 microbody）","d":"过氧化物酶体（peroxisome）又称微体（microbody），是由单层膜围绕、内含一种或几种氧化酶类的异质性细胞器。它利用分子氧氧化底物，反应为RH2加O2生成R与H2O2，再由过氧化氢酶把H2O2分解为水和氧。与初级溶酶体形态大小相似，但过氧化物酶体pH约7、需要O2、含氧化酶类，且尿酸氧化酶等常形成晶格状结构，可作电镜识别特征；其标志酶为过氧化氢酶与尿酸氧化酶。","src":"《第5章细胞内膜系统（上）》p120、p123、p124"},{"id":"0fd7c0ce","s":"c","g":"c04","n":"过氧化物酶体靶向信号","e":"peroxisomal-targeting signal (PTS)","d":"过氧化物酶体靶向信号（peroxisomal-targeting signal, PTS）是引导蛋白质进入过氧化物酶体的分选信号，分两种：PTS1为SKL（Ser-Lys-Leu），多存在于基质蛋白的C端；PTS2为Arg/Lys-Leu/Ile-5X-His/Gln-Leu，存在于某些基质蛋白的N端。二者分别被相应的受体蛋白识别，受体与过氧化物酶体膜上的Pex14p结合后把货物转入；进入后N端信号被切除，而SKL则保留在蛋白上。","src":"《第5章细胞内膜系统（上）》p125、p126"},{"id":"07b1ddef","s":"c","g":"c04","n":"通道运输","e":"","d":"通道运输是借通道蛋白完成的跨膜运输方式。通道蛋白与溶质分子的结合能力很弱，它们形成狭窄的跨膜水溶性通道，在开放时允许特定溶质穿越膜，通常是一些小的无机离子，因而具有选择性而不需与被转运物形成紧密的酶－底物式复合物。与转运蛋白相比，通道蛋白的运输速率要高4到8个数量级。短杆菌肽A即一种形成通道的离子载体，由两个分子共同构成跨膜通道，可选择性地让单价阳离子按电化学梯度通过。","src":"《第3章 细胞膜与表面（上）》p56、p90"},{"id":"c676c3d1","s":"c","g":"c04","n":"酸性水解酶","e":"acid hydrolases","d":"酸性水解酶（acid hydrolases）是溶酶体中在酸性pH下活性最佳的水解酶，包括蛋白酶、核酸酶、糖苷酶、脂酶、磷脂酶、磷酸酶与硫酸酯酶等，典型溶酶体约含50种。它们的最适pH偏酸，与溶酶体腔内的酸性环境相适应；少量酶泄漏到细胞质基质中并不会引起细胞损伤，因为胞质的中性pH使其活性很低。酸性磷酸酶是溶酶体的标志酶，常用于细胞化学显示溶酶体。这些酶在粗面内质网合成后，经高尔基体分选包装进入溶酶体。","src":"《第5章细胞内膜系统（上）》p89、p123；MBoC 7e 印刷 p799"},{"id":"367cbb44","s":"c","g":"c04","n":"顺面高尔基网络","e":"CGN","d":"顺面高尔基网络（CGN）是高尔基体靠近内质网一侧的特殊区室，由从内质网运来的囊泡管簇融合而成，是高尔基体的入口面。它与反面高尔基网络（TGN）分别位于高尔基体的两面，均由相互连接的管状与囊状结构组成。蛋白质与脂质经CGN进入高尔基体，再由TGN输出，运往细胞表面或其他区室。两个网络都参与分选：进入CGN的蛋白既可继续前行，也可被返回内质网，这种返回由COPI小泡承担，可避免内质网驻留蛋白被误运至下游区室。","src":"《第5章细胞内膜系统（上）》p65；MBoC 7e 印刷 p770"},{"id":"d3200853","s":"c","g":"c04","n":"高尔基体","e":"Golgi apparatus","d":"高尔基体（Golgi apparatus）由意大利科学家Camillo Golgi于1898年发现，由4～8层扁平膜囊及其周围众多球形膜囊组成，分顺面（靠近粗面内质网，即内侧网络CGN）、中间潴泡与反面（外侧网络TGN）三个区域，对来自内质网的蛋白质和脂质进行修饰、分选与包装。它还参与膜的转化、把无活性的蛋白原水解为成熟多肽如胰岛素，参与溶酶体形成、植物细胞壁多糖合成以及细胞板形成。","src":"《第5章细胞内膜系统（上）》p65、p69；MBoC 7e Glossary PDF p1458"},{"id":"94b30dc5","s":"c","g":"c07","n":"9+2结构","e":"","d":"9+2结构是鞭毛和纤毛轴丝中微管的排列方式：外周为9个双联管，中央为2个单管，并含动力蛋白臂、辐条与中央鞘等附属结构。鞭毛与纤毛的弯曲源于相邻双联管之间的滑动，该滑动由动力蛋白水解ATP驱动，使微管相互推移；由于辐条与中央鞘的限制，滑动转为局部弯曲，表现为鞭毛的搏动。轴丝由基体发出，基体与中心体同源，9+2结构因而也是微管组织中心相关结构的特征；纤毛与鞭毛的摆动依赖轴丝中微管与动力蛋白的协同。","src":"《第6章 细胞骨架》p70、p119、p122、p124"},{"id":"b2eefcc3","s":"c","g":"c07","n":"Arp2/3","e":"Arp2/3","d":"Arp2/3是微丝的成核蛋白，以70度角结合到已存在的微丝上，在其侧壁组装新的微丝，从而产生Y形分支，使微丝呈网状分布。这种分支网络在运动细胞的片状伪足中大量存在，网状的微丝结构产生推力，推动细胞膜向前移动。与之相对，以formins为核心形成的是不分支的微丝，如张力纤维中微丝平行排列并附着到细胞膜上。Arp2/3的成核活性需要成核促进因子（NPF）参与，它由此成为分支微丝网络形成的核心因子，在细胞迁移与吞噬等过程中发挥作用。","src":"《第6章 细胞骨架》p25、p56；MBoC 7e 印刷 p966"},{"id":"74333189","s":"c","g":"c07","n":"Arp2/3 complex","e":"Arp2/3 complex","d":"Arp2/3复合体是含两个肌动蛋白相关蛋白（Arp2与Arp3）的蛋白复合体，能结合到已存在的微丝上，并由此成核、生长出新的微丝，形成分支结构。其介导的微丝成核需要成核促进因子（NPF）的活性，附着到微丝侧壁后进一步被激活，从而在膜附近生成分支状的微丝阵列，把单根微丝组织成树状网络。该复合体与成核促进因子共同作用，是细胞内分支状微丝网络形成的关键，也是片状伪足等突出结构形成的基础。","src":"《思维导图》p3；MBoC 7e 印刷 p966、Glossary PDF p1446"},{"id":"13b933aa","s":"c","g":"c07","n":"Ena/VASP","e":"Ena/VASP","d":"Ena/VASP是一类促进微丝延长的调节蛋白，以四聚体形式发挥作用。它结合于微丝的正端，竞争性阻止加帽蛋白如CapZ结合，即具有抗加帽活性，使正端保持游离而持续添加肌动蛋白单体；同时它可直接结合G-actin与profilin-actin复合物，把单体递送至正端，加快延长。Ena/VASP还借其EVH2结构域交联微丝，促使成束并抑制分支，参与丝状伪足与细胞前缘突出的形成。","src":"网络补充：ncbi.nlm.nih.gov（PMC1747414）"},{"id":"f1ac43de","s":"c","g":"c07","n":"Formins","e":"Formins","d":"Formins是一类微丝成核蛋白，以二聚体形式起作用。每个亚基都有肌动蛋白单体的结合位点，二聚体通过捕获两个单体来引发微丝聚合，成核出直而不分支的微丝；随着新微丝延长，formins二聚体持续结合在快速生长的正端，同时仍允许新的亚基在该端加入，故能持续延长微丝。由formins形成的微丝可被其他蛋白交联成平行束，如张力纤维，平行排列并附着到细胞膜上。因此formins既能成核又能持续延长微丝，与Arp2/3的分支成核方式形成对照。","src":"《第6章 细胞骨架》p25、p26；MBoC 7e 印刷 p967"},{"id":"c6f9b2fa","s":"c","g":"c07","n":"GTP帽","e":"GTP cap","d":"GTP帽（GTP cap）是微管正端由结合GTP的微管蛋白形成的帽子。微管蛋白装配到正端的速度可快于其结合核苷酸的水解速度，此时末端即保留一层带GTP的亚基，GTP帽有利于微管继续装配而维持生长。若在正端GTP水解速度大于装配速度，则失去GTP帽，微管转为解聚。由于带GDP的微管蛋白解聚远快于带GTP者，微管因此在生长与快速解聚之间交替，即动态不稳定性。这一解释即GTP帽模型。","src":"《第6章 细胞骨架》p81、p82；MBoC 7e 印刷 p961"},{"id":"3560dd57","s":"c","g":"c07","n":"Latrunculin B","e":"Latrunculin B","d":"Latrunculin B是作用于肌动蛋白的微丝特异性药物，其作用方式是结合肌动蛋白单体，阻止它们聚合成微丝，从而使微丝网络解聚。在肌动蛋白特异性药物中，它与鬼笔环肽、Jasplakinolide（结合并稳定微丝）、细胞松弛素（封住微丝正端）、Swinholide（切断微丝）的作用环节不同。实验中常用它处理细胞以破坏微丝、观察微丝依赖的过程，是研究细胞骨架功能的常用工具药。","src":"《思维导图》p3；《第6章 细胞骨架》p18"},{"id":"8e21cf55","s":"c","g":"c07","n":"Swinholide","e":"Swinholide","d":"Swinholide是切断微丝的肌动蛋白特异性药物。在微丝药物中，Phalloidin与Jasplakinolide结合并稳定微丝，细胞松弛素封住微丝正端，Latrunculin结合单体阻止其聚合，而Swinholide的作用是把已形成的微丝切断。这类药物多为真菌等来源的代谢产物，因作用于微丝装配的不同环节，常被用于处理细胞，以观察微丝解聚或切断后细胞形态与运动的变化。","src":"《第6章 细胞骨架》p18"},{"id":"468c28a6","s":"c","g":"c07","n":"Formin","e":"formin","d":"Formin是一类微丝成核蛋白，与Arp2/3形成网状分支微丝的方式相对：以formins为核心时，微丝不分支、平行排列，如张力纤维（stress fibers），并附着到细胞膜上。formin作为微丝结合蛋白，参与成核以促使微丝装配，并使微丝与细胞膜相连接。其成核产生的直微丝可被其他蛋白交联成平行束，在细胞形态维持与收缩装置中发挥作用；它与Arp2/3的分支网络共同构成微丝的两种基本排列方式。","src":"《第6章 细胞骨架》p25、p26；MBoC 7e Glossary PDF p1456"},{"id":"2ba5936a","s":"c","g":"c07","n":"septin","e":"septin","d":"Septin是一类细胞骨架蛋白，酵母中有7个基因、人类有13个，依序列关系分为四组。纯化的septin在试管中组装成对称的异源六聚体或异源八聚体，进而形成无极性的配对丝。GTP结合是septin多肽折叠所必需的，但GTP水解在其功能中的作用尚不清楚。septin结构在细胞内可装配与解聚，但动态性不如肌动蛋白丝与微管；动物细胞中septin参与细胞分裂、迁移、膜泡运输与细胞信号，如在初级纤毛基部形成环状扩散屏障。","src":"《思维导图》p3；MBoC 7e 印刷 p1012、p1013"},{"id":"7892f07f","s":"c","g":"c07","n":"γ-微管蛋白环","e":"gamma-tubulin ring","d":"γ-微管蛋白环（gamma-tubulin ring）是负责微管成核的蛋白质复合体，由γ-微管蛋白与辅助蛋白组装而成。两个γ-微管蛋白拷贝先与一对辅助蛋白结合，形成γ-微管蛋白小复合体，若干小复合体再聚合成环状的复合体，为微管蛋白二聚体的聚合提供成核位点。细胞中大部分此类复合体分布在细胞质中，一部分通过多种锚定蛋白固定在中心体上；用激光脉冲破坏中心体并不妨碍细胞内其他部位发生微管成核，说明中心体并非微管成核的绝对必要条件。","src":"《第6章 细胞骨架》p92、p93；MBoC 7e 印刷 p992"},{"id":"95ed9b92","s":"c","g":"c07","n":"丝状伪足","e":"filopodium","d":"丝状伪足（filopodium）是爬行中的动物细胞前缘伸出的细长、尖刺状突起，其核心是一束肌动蛋白丝。在细胞前缘，肌动蛋白丝以快速生长的正端朝向细胞边缘，由结合蛋白把纤维组织成紧密的平行束，从而把质膜顶出形成细长的突起；它与片状伪足的分支网络相互衔接，两者都是细胞前缘肌动蛋白聚合的产物。丝状伪足是细胞探索周围环境、感受导向信号并向前爬行的结构基础，也是细胞吞噬时摄取颗粒的装置之一。","src":"MBoC 7e 印刷 p972；《MBoC 7e》Glossary"},{"id":"32a979ad","s":"c","g":"c07","n":"中心体","e":"centrosome","d":"中心体（centrosome）是动物细胞主要的微管组织中心，由一对相互垂直排列的中心粒及周围物质构成。两个中心粒呈L形配置，每个中心粒由9组三联微管围成。中心体是间期微管的成核部位，也是有丝分裂时纺锤体的两极，负责纺锤丝微管的生长排列、染色体的捕捉和向两极的移动。它在一个细胞周期中只复制一次，复制发生在S期，并经历中心粒解放、成熟与中心体分离等步骤。此外，中心体并非微管成核的唯一场所，用激光破坏中心体并不妨碍细胞其他部位成核。","src":"《第6章 细胞骨架》p89、p90、p95；MBoC 7e 印刷 p992"},{"id":"9ab4e69b","s":"c","g":"c07","n":"中心粒","e":"centriole","d":"中心粒（centriole）是动物细胞中以微管为基础构成的细胞器，呈短圆柱状，由9组三联微管围成。两个中心粒互相垂直，嵌在中心体中央，构成中心体的核心。中心粒的复制以母中心粒依赖的方式进行，在细胞周期中只发生一次：先在母中心粒旁选定前中心粒的位置并形成前中心粒，再经过延长、成熟与解放等步骤，使一个中心粒转变为可复制的新中心粒。纤毛发生时，成熟的母中心粒迁移到质膜下作为基体；在多纤毛细胞中，中心粒还可由摇篮体大量扩增。","src":"《第6章 细胞骨架》p94、p99；MBoC 7e 印刷 p1054"},{"id":"31f55d1f","s":"c","g":"c07","n":"中间纤维","e":"intermediate filament","d":"中间纤维（intermediate filament）是细胞骨架的第三大类纤维，直径约10 nm，由多种中间纤维蛋白组成，呈柔软的绳状，为细胞提供机械张力。其分子中部有一段约310个氨基酸残基的α螺旋杆状区，高度保守；非螺旋的N端头部和C端尾部在各类分子中长度与序列差异很大。按组织来源和免疫原性可分为角蛋白、波形纤维蛋白、结蛋白、神经元纤维蛋白、胶质纤维酸性蛋白和核纤层蛋白等类型，其表达具有组织特异性；中间纤维无极性。","src":"《第6章 细胞骨架》p137、p138、p154；MBoC 7e 印刷 p1007","x":1},{"id":"4b14f297","s":"c","g":"c07","n":"中间纤维结合蛋白","e":"IFAP","d":"中间纤维结合蛋白（IFAP）是与中间纤维结合并调节其组装、分布及与其他结构连接的蛋白质，已知约有15种，功能多样。filaggrin使角蛋白纤维形成聚集物；plectin在中间纤维、微管和微丝之间形成横桥，把三套骨架系统连成整体；BPAG1为桥板蛋白，使中间纤维与桥粒连接；MAP2参与中间纤维与微管间的横桥；锚蛋白则参与中间纤维与膜的结合。通过这些蛋白，中间纤维得以与细胞膜、桥粒以及另外两类骨架纤维整合，共同维持细胞与组织的机械稳定性。","src":"《第6章 细胞骨架》p141"},{"id":"ac24ac7e","s":"c","g":"c07","n":"临界浓度","e":"critical concentration (Cc)","d":"临界浓度（critical concentration, Cc）是肌动蛋白单体或微管蛋白二聚体与相应纤维之间达到动态平衡时游离单体的浓度。当单体浓度高于Cc时，装配速率大于解聚速率，纤维净延长；低于Cc时则净解聚。正极和负极的临界浓度并不相等，负极的Cc大于正极的Cc。当游离单体浓度介于两端Cc之间时，正极持续装配而负极持续解聚。对肌动蛋白而言，Cc为一常数，约为0.1 μM，但掺入纤维的单体比例随反应中肌动蛋白总量而变。","src":"《第6章 细胞骨架》p13、p84；MBoC 7e 印刷 p959"},{"id":"99307099","s":"c","g":"c07","n":"二联体微管","e":"doublet microtubule","d":"二联体微管（doublet microtubule）是由两根微管并合而成的结构，见于鞭毛和纤毛的轴丝。A管完整，由13根原纤维围成；B管不完整，仅10根原纤维，与A管共用管壁。轴丝中9组二联体微管围成一圈，加上中央的一对单微管，构成鞭毛和纤毛特征性的9+2排列。二联体A管上附着动力蛋白臂，动力蛋白头部与相邻B管接触并水解ATP，使头部角度改变，引起相邻二联体相互滑动；滑动被连接蛋白约束后转变为轴丝弯曲，从而驱动纤毛和鞭毛摆动。","src":"《第6章 细胞骨架》p67、p119、p122","x":1},{"id":"334a8513","s":"c","g":"c07","n":"交联蛋白","e":"cross-linking proteins","d":"交联蛋白（cross-linking proteins）是一类能使肌动蛋白丝相互连接、从而决定微丝空间排列的微丝结合蛋白。此类蛋白通常为二聚体，具有两个相似的肌动蛋白丝结合位点，可分别与两根微丝结合：有的以双极方式把微丝连接成平行束，如α-actinin；有的使两根微丝以大角度相交，形成疏松的网络，如filamin。因而细胞内微丝究竟呈束状还是网状，取决于当地交联蛋白的种类与活性。细胞皮层中不同方向的微丝正是靠交联蛋白交联成三维网络。","src":"《第6章 细胞骨架》p23、p54；MBoC 7e 印刷 p969"},{"id":"1e4570eb","s":"c","g":"c07","n":"加帽蛋白","e":"capping protein","d":"加帽蛋白（capping protein）是结合在微丝末端、封闭该端的微丝结合蛋白，属微丝组装调节因子。它与纤维的一端结合后，阻止肌动蛋白单体在该端继续添加或脱落，从而限制纤维的延长与缩短；细胞内CapZ即结合于微丝末端起封端作用。在细菌利用肌动蛋白聚合推动自身运动的体外重建实验中，只需纯净的肌动蛋白、Arp2/3复合体、cofilin和加帽蛋白即可重现彗星尾式运动，说明加帽蛋白通过对纤维末端的时空调节参与细胞前缘的膜突进。","src":"《第6章 细胞骨架》p19、p22、p26；MBoC 7e 印刷 p971"},{"id":"a2280c62","s":"c","g":"c07","n":"动力学不稳定性","e":"dynamic instability","d":"动力学不稳定性（dynamic instability）指微管等蛋白纤维在生长与缩短两种状态之间突然、随机转换的特性。其分子基础在于微管蛋白二聚体所结合的GTP：正极持续添加GTP-微管蛋白时微管保持生长，当GTP水解快于亚基添加时，末端转变为GDP型，微管随即由生长转为迅速解聚。这种转换是突然而随机的，单位时间的转换概率取决于游离GTP-微管蛋白的浓度。同一根微管的末端可能生长一段时间后突然转为缩短，之后又可重新生长。","src":"《第6章 细胞骨架》p79；MBoC 7e 印刷 p989"},{"id":"fc20ec78","s":"c","g":"c07","n":"动力学不稳定性（动态不稳定性）","e":"","d":"动态不稳定性又称动力学不稳定性，指微管在装配与去装配两种状态之间交替变化的现象。用荧光标记的微管蛋白显微注射入细胞，先低温使细胞内原有微管解聚，再升温让其重新组装，可观察到荧光微管蛋白掺入新形成的微管，从而直接显示微管的装配与去装配过程。决定这一行为的主要因素是游离微管蛋白的浓度和微管正极的GTP帽：正极保持GTP帽时微管持续延长，GTP水解后帽子丢失，正极转为解聚。微管得以在细胞内快速搜索空间、重塑分布，并在有丝分裂时组装纺锤体。","src":"《第6章 细胞骨架》p79、p81"},{"id":"17597568","s":"c","g":"c07","n":"动力蛋白","e":"dynein","d":"动力蛋白（dynein）是沿微管向负极移动的马达蛋白。它由2至3条重链和多个中等链、轻链组成；重链头部具ATP酶活性，轻链则通过辅助蛋白与膜泡、染色体等货物结合。其工作循环为：头部与相邻B管接触促使ATP水解、产物释放并使头部角度改变，新的ATP结合使头部与B管脱离，ATP水解释放的能量使头部角度复原，随后头部又与B管上的另一位点结合。借此，动力蛋白把内质网膜泡、HIV病毒等由细胞边缘运向细胞中央，并参与鞭毛与纤毛轴丝二联体微管的滑动。","src":"《第6章 细胞骨架》p115、p116、p122；MBoC 7e 印刷 p1002","x":1},{"id":"95931ac8","s":"c","g":"c07","n":"原肌球蛋白","e":"tropomyosin","d":"原肌球蛋白（tropomyosin）是构成肌肉细丝的成分之一，由两条平行的多肽链缠绕成α螺旋，呈细长的杆状，卧于肌动蛋白丝双股螺旋的沟中。一个原肌球蛋白分子的长度大致相当于7个肌动蛋白分子。静息状态下，它与肌钙蛋白I-T复合体一起被牵拉，处于妨碍肌球蛋白头部结合的位置。当Ca2+升高、肌钙蛋白C结合Ca2+后，肌钙蛋白与原肌球蛋白的结合减弱，原肌球蛋白从提升位置降落到微丝的沟内，暴露出肌动蛋白上的结合位点，引起肌肉收缩。","src":"《第6章 细胞骨架》p37、p40、p48"},{"id":"9495fa09","s":"c","g":"c07","n":"基体","e":"basal body","d":"基体（basal body）是纤毛和鞭毛基部的微管组织中心结构，位于质膜下方。每个基体的核心是一个中心粒，其结构与动物细胞中心体中所含的中心粒相同，由9组融合的三联微管按车轮状排列而成。纤毛和鞭毛无论可动与否，都在间期由基体发出：中心粒迁移到质膜下，以其为模板使轴丝成核；由于纤毛内不发生蛋白质翻译，轴丝的建筑必须依靠鞭毛内运输不断输送材料。细胞内的微管因此呈现单管、双联管（鞭毛、纤毛）和三联管（中心粒、基体）三种形式。","src":"《第6章 细胞骨架》p67、p96；MBoC 7e 印刷 p1006"},{"id":"fbf00703","s":"c","g":"c07","n":"应力纤维","e":"stress fiber","d":"应力纤维（stress fiber）又称张力纤维，是培养细胞中由大量反向平行排列的微丝及其结合蛋白组成的收缩性纤维束。微丝以formins为核心成核、不分支地平行排列，并由交联蛋白成束，肌球蛋白II与之结合产生收缩力；纤维两端通过黏着斑与细胞外基质相连，使培养细胞铺展。Rho的激活可同时促进微丝与肌球蛋白II成束形成应力纤维，并促使integrin及其结合蛋白聚集形成黏着斑。应力纤维还在细胞形态发生、细胞分化和组织建成中发挥作用。","src":"《第6章 细胞骨架》p52；MBoC 7e 印刷 p1017"},{"id":"b198f3dd","s":"c","g":"c07","n":"微丝","e":"microfilament","d":"微丝（microfilament）是由肌动蛋白组成的细胞骨架纤维，直径约7 nm，由两条原纤维丝相互缠绕成双股螺旋，柔软，集中于细胞膜内侧。微丝有正、负两极；其组装可分为成核、延长和达到动态平衡三个阶段，Arp2/3复合体在成核促进因子作用下启动分支网络的形成，formins则介导不分支微丝的成核。有些微丝是永久性结构，如肌细胞中的细丝和小肠上皮细胞微绒毛中的微丝；有些是暂时性结构，如胞质分裂时的收缩环；通常为动态结构。","src":"《第6章 细胞骨架》p9、p16、p25"},{"id":"cc67fc89","s":"c","g":"c07","n":"微丝结合蛋白","e":"","d":"微丝结合蛋白是细胞内与肌动蛋白单体或微丝结合的蛋白质，已知有40多种。按作用可分为成核、与单体结合、末端封端、交联、截断以及连接细胞膜等几类，代表成员有Arp2/3、thymosin、profilin、CapZ、gelsolin、cofilin和formins。其中α-辅肌动蛋白横向连接微丝成束，纽蛋白介导微丝结合于细胞膜，绒毛蛋白在微绒毛发生中起关键作用，毛缘蛋白形成微丝束，肌球蛋白、原肌球蛋白和肌钙蛋白则与肌肉收缩有关。","src":"《第6章 细胞骨架》p19、p26"},{"id":"c57b54c7","s":"c","g":"c07","n":"微管","e":"microtubule","d":"微管（microtubule）是由α、β微管蛋白异二聚体装配成的中空圆柱状细胞骨架纤维，外径约26 nm，由13根原纤维围成。二聚体中α与β亚基头尾相接排列，使微管具有极性：α端为负极，β端为正极，正极装配速度快于负极。每个二聚体有2个GTP结合位点、二价阳离子结合位点，以及秋水仙素、长春花碱和紫杉醇各一个结合位点；α亚基上的GTP不能交换，β亚基上的GDP可与GTP交换。体内微管一端与微管组织中心相连，装配与去装配在时空上高度有序。","src":"《第6章 细胞骨架》p64、p66、p75、p77"},{"id":"02a517bf","s":"c","g":"c07","n":"微管组织中心","e":"MTOC","d":"微管组织中心（MTOC）是微管在生理状态以及实验处理解聚后重新装配的发生部位。多数微管以其一端固着于MTOC，常见的MTOC为基体或中心体；MTOC决定微管的极性，负极指向MTOC，正极背向MTOC。这种极性排布是细胞内定向运输的基础：背离MTOC的正极方向运输由驱动蛋白承担，朝向MTOC的负极方向运输由动力蛋白承担，两者分工完成物质的分区运输。有丝分裂时，MTOC还作为纺锤体的两极，发出星体微管、动粒微管和极间微管。","src":"《第6章 细胞骨架》p88、p118；MBoC 7e 印刷 p992"},{"id":"aa360e09","s":"c","g":"c07","n":"微管组织中心","e":"microtubule organizing center (MTOC)","d":"微管组织中心（microtubule organizing center, MTOC）是细胞内微管生长与装配的发源地。微管在生理状态以及实验处理解聚后，都在MTOC处重新装配；多数微管的一端固着于MTOC，因此MTOC决定微管的极性，负极指向MTOC，正极背向MTOC。微管本身是长、直、坚硬的中空圆柱体，直径约26 nm，正因一端被MTOC锚定，才能在细胞内形成有序的辐射状或平行状阵列。MTOC的组成与位置在不同细胞中差异很大。","src":"《第6章 细胞骨架》p5、p88；《MBoC 7e》Glossary"},{"id":"dd7eef7d","s":"c","g":"c07","n":"微管结合蛋白","e":"microtubule-associated protein","d":"微管结合蛋白（microtubule-associated protein）是能与微管结合并改变其性质的蛋白质的总称。其功能主要有：稳定微管的空间结构，促使微管蛋白与微管之间的平衡趋于装配，构成微管之间的连接，把微管与其他细胞结构相连，以及产生动力。由于微管蛋白C端短尾富含谷氨酸和天冬氨酸，微管表面带净负电荷，许多此类蛋白带正电荷，通过静电作用与微管结合。有些成员能保护微管免于解聚，另一些则介导微管与其他细胞组分的相互作用。","src":"《第6章 细胞骨架》p103；《MBoC 7e》Glossary；MBoC 7e 印刷 p995"},{"id":"a2bcf5a6","s":"c","g":"c07","n":"微管结合蛋白","e":"MAPs","d":"微管结合蛋白（MAPs）是细胞内与微管蛋白二聚体或微管结合的一大类蛋白质的统称。按功能可分为三类：控制新微管形成的成核因子、调节微管两端聚合与解聚速率的调节蛋白，以及把微管相互交联并使其相对移动的马达蛋白。此类蛋白通过稳定微管的空间结构、促使微管蛋白与微管的平衡趋于装配而发挥作用，其中MAP1存在于轴突和树突，MAP2存在于树突，MAP4广泛存在于各种细胞，τ蛋白存在于轴突。神经元中这类蛋白尤为丰富，是微管成束和维持轴突形态的分子基础。","src":"《第6章 细胞骨架》p103；MBoC 7e 印刷 p995、p1051"},{"id":"5a0d62cb","s":"c","g":"c07","n":"微管蛋白","e":"tubulin","d":"微管蛋白（tubulin）是微管的蛋白亚基，由α-微管蛋白和β-微管蛋白两个密切相关的球状蛋白以非共价键紧密结合成异二聚体。两种蛋白只以这种异二聚体形式存在，每个α或β单体各有1个GTP结合位点；α亚基上的GTP被物理封闭在二聚体界面，既不水解也不交换，β亚基上的GDP则能与GTP交换。此外二聚体还有二价阳离子结合位点，以及秋水仙素、长春花碱和紫杉醇各一个结合位点。二聚体头尾相接构成原纤维，13根原纤维围成微管；α端为负极，β端为正极。","src":"《第6章 细胞骨架》p64、p66；MBoC 7e 印刷 p987","x":1},{"id":"dc3b6115","s":"c","g":"c07","n":"微绒毛","e":"microvilli","d":"微绒毛（microvilli）是上皮细胞游离面伸出的指状突起，其轴心由成束的肌动蛋白丝支撑，属微丝参与形成的结构之一。小肠上皮细胞表面的微绒毛密集排列，使细胞游离面的表面积大为增加，从而提高营养物质吸收的效率。微绒毛中的微丝属于永久性结构，与肌细胞中的细丝一样长期存在；绒毛蛋白在微绒毛的发生中起关键作用，负责把微丝组织成束。微绒毛与细胞皮层、细胞伪足、应力纤维和收缩环一样，都是微丝在非肌细胞中执行特定功能的实例。","src":"《第6章 细胞骨架》p19、p33；MBoC 7e 印刷 p680"},{"id":"1b8da74c","s":"c","g":"c07","n":"微绒毛","e":"microvillus","d":"微绒毛（microvillus）是上皮细胞表面由微丝支撑的指状突起，小肠上皮细胞的微绒毛尤为典型，其功能是扩大细胞游离面的面积，使营养物质得以更有效地吸收。微绒毛轴心是一束同向平行排列的微丝，正极朝向突起顶端，微丝之间由交联蛋白成束；其中的微丝属永久性结构，与肌细胞中的细丝一样。在微绒毛的发生过程中，绒毛蛋白起关键作用。微绒毛因此与肌肉收缩、应力纤维、细胞皮层、细胞伪足和胞质分裂环并列，成为微丝在细胞中执行多种功能的例证之一。","src":"《第6章 细胞骨架》p16、p19、p21"},{"id":"4526bd45","s":"c","g":"c07","n":"成核","e":"nucleation","d":"成核（nucleation）是微丝组装的第一步，指游离肌动蛋白单体聚集形成稳定的核心、从而启动纤维延长的过程，也是整个组装反应的限速步骤。由于游离单体自发聚集成核十分困难，细胞内成核多由成核蛋白催化：Arp2/3复合体在成核促进因子的作用下被激活，并进一步结合到已有微丝的侧面而受到刺激，由此在膜附近生成分支的微丝阵列；formins则介导不分支微丝的成核。成核之后，单体在两端继续添加使纤维延长，直至与游离单体达到动态平衡。","src":"《第6章 细胞骨架》p26；MBoC 7e 印刷 p966","x":1},{"id":"dbbc6a12","s":"c","g":"c07","n":"拉春库林","e":"Latrunculin","d":"拉春库林（Latrunculin）是作用于肌动蛋白的药物，其作用方式是与肌动蛋白亚基结合，阻止亚基聚合成微丝。它与细胞松弛素、鬼笔环肽同属研究微丝动态与功能的工具药物：细胞松弛素为真菌产物，结合微丝正端而阻止聚合；鬼笔环肽来自白毒伞，沿微丝侧面紧密结合并使之稳定；拉春库林则把游离的肌动蛋白亚基结合住，使其不能掺入纤维，因而使微丝趋于解聚。这类能稳定或去稳定微丝的化合物，是研究纤维动态行为及其细胞功能的重要手段。","src":"《第6章 细胞骨架》p18；MBoC 7e 印刷 p963"},{"id":"f6cd0019","s":"c","g":"c07","n":"摇篮体","e":"deuterosome","d":"摇篮体（deuterosome）是脊椎动物多纤毛细胞中用于大量扩增中心粒的临时性结构，与母中心粒依赖的中心粒复制途径并存。在纤毛上皮细胞中，中心粒的扩增有两条途径：一条以母中心粒为核心逐个产生子中心粒，另一条依赖摇篮体在短时间内成批生成前中心粒。摇篮体由年轻的母中心粒产生，其本质尚不完全清楚，一种推测认为它由某些摇篮蛋白的旁系同源物构成，即与中心粒摇篮成分相似的蛋白组装而成。小鼠气管上皮细胞等是研究摇篮体组装与中心粒扩增的常用体系。","src":"《第6章 细胞骨架》p99、p100、p101"},{"id":"7f405cf3","s":"c","g":"c07","n":"核纤层（核纤层蛋白）","e":"lamin","d":"核纤层（lamin）即核纤层蛋白，属第Ⅴ类中间纤维蛋白，在核内膜内侧聚合成纤维网络，为核膜提供结构支架。它与中间纤维有许多共同点：均形成10 nm纤维，都能抵抗高盐和非离子去污剂的抽提，抗体反应相同，蛋白结构相似；免疫荧光可同时显示角蛋白与核纤层蛋白在细胞内的分布。核纤层的聚合状态受磷酸化调控：有丝分裂前期，核纤层蛋白被磷酸化，与核内膜蛋白及染色质的作用被破坏，核纤层解聚，核膜随之崩解；末期去磷酸化后，核纤层重新组装，核膜重建。","src":"《第6章 细胞骨架》p132、p138、p155；MBoC 7e 印刷 p744"},{"id":"ef083909","s":"c","g":"c07","n":"秋水仙素","e":"colchicine","d":"秋水仙素（colchicine）是结合微管蛋白亚基、阻止微管装配的特异性药物。它与长春花碱、诺考达唑、鬼臼毒素等一样，通过结合微管蛋白亚基并封住纤维两端而促使微管解聚；与之相反，紫杉醇结合并稳定微管，使微管蛋白的聚合净增加。由于微管的动态对有丝分裂纺锤体的正确功能至关重要，这类药物对分裂中的细胞有优先杀伤作用。秋水仙素处理可使细胞的有丝分裂装置无法形成，细胞被阻断在中期，因此常用于细胞周期同步化，把细胞收集在M期。","src":"《第6章 细胞骨架》p86、p87；《第10章 细胞分裂与细胞周期(下)》p13；MBoC 7e 印刷 p964"},{"id":"5ecd2b78","s":"c","g":"c07","n":"紫杉醇","e":"taxol","d":"紫杉醇（taxol）是结合微管并使之稳定的特异性药物，来源于红豆杉。与秋水仙素、长春花碱、诺考达唑等结合微管蛋白亚基、促使微管解聚的药物相反，紫杉醇沿微管结合并稳定之，使微管蛋白的聚合净增加。微管蛋白二聚体上除2个GTP结合位点和二价阳离子结合位点外，还有1个紫杉醇结合位点，即其作用靶点。由于微管动力学对纺锤体的正确功能至关重要，紫杉醇与微管解聚药物一样优先杀死分裂中的细胞，因而被用作抗肿瘤药物；它同时也是研究微管功能的有力工具。","src":"《第6章 细胞骨架》p64、p86、p87；MBoC 7e 印刷 p991","x":1},{"id":"3e56c0f2","s":"c","g":"c07","n":"纤毛","e":"cilia","d":"纤毛（cilia）是细胞表面以微管和动力蛋白为基础的毛状运动结构，其核心是一束微管构成的轴丝。轴丝中9组二联体微管围成一圈、中央为一对单微管，即9+2结构；二联体A管上的动力蛋白臂水解ATP使相邻二联体相互滑动，滑动受连接蛋白约束而转变为轴丝的弯曲摆动。纤毛比鞭毛短，通常每个细胞为数众多，通过摆动移动细胞外的液体、收集食物或推动细胞本身运动。可动纤毛与不动纤毛都由间期的基体发出；由于纤毛内没有蛋白质翻译，轴丝的建筑依赖鞭毛内运输。","src":"《第6章 细胞骨架》p67、p119；MBoC 7e 印刷 p1004"},{"id":"a1fc8b95","s":"c","g":"c07","n":"细胞松弛素","e":"cytochalasin","d":"细胞松弛素（cytochalasin）是一类真菌产生的代谢物，能抑制肌动蛋白聚合。其作用机制是与微丝的正端结合并封闭该端，使肌动蛋白单体无法继续添加，从而阻止纤维延长并使微丝趋于解聚。它与拉春库林（结合肌动蛋白亚基、阻止聚合）、鬼笔环肽（沿微丝侧面结合并稳定纤维）作用方式不同，三者常被并列用于比较微丝的稳定与去稳定效应。由于微丝参与细胞皮层、应力纤维、伪足运动和胞质分裂，细胞松弛素处理会引起细胞形态与运动能力的显著改变。","src":"《第6章 细胞骨架》p18；MBoC 7e 印刷 p963"},{"id":"883cfc45","s":"c","g":"c07","n":"细胞松弛素D","e":"Cytochalasin D","d":"细胞松弛素D（Cytochalasin D）是细胞松弛素类中常用的一种，作用是在微丝正端加帽，使肌动蛋白单体不能在该端继续添加，从而破坏微丝。它常被用来判断细胞过程是否依赖肌动蛋白：例如刚进入有丝分裂的细胞若用诺考达唑处理，微管被去稳定，核膜崩解、染色体凝缩但不形成纺锤体；若改用细胞松弛素D处理，则有丝分裂照常进行，但胞质分裂失败，形成双核细胞并进入G1期。两种结局的差异说明，微管为纺锤体所必需，而肌动蛋白丝为胞质分裂所必需。","src":"MBoC 7e 印刷 p1086；《第6章 细胞骨架》p18"},{"id":"2c3e8b5b","s":"c","g":"c07","n":"细胞皮层","e":"cell cortex","d":"细胞皮层（cell cortex）是紧贴质膜内侧、富含微丝的一层特化细胞质。该区域内，微丝结合蛋白把不同方向的微丝交联成三维网络，使局部细胞质呈凝胶状，因此皮层又称凝胶层。动物细胞皮层的肌动蛋白富集层负责细胞表面的各种运动。胞质分裂时，后期纺锤体中区发出信号，在细胞皮层诱导局部皱褶形成；这一过程的核心是centralspindlin复合体在纺锤体中区反平行微管上聚集，其组装受Aurora-B激酶的刺激，从而把分裂位置指定在皮层。","src":"《第6章 细胞骨架》p54；《MBoC 7e》Glossary；MBoC 7e 印刷 p1067"},{"id":"22f2881b","s":"c","g":"c07","n":"细胞骨架","e":"cytoskeleton","d":"细胞骨架（cytoskeleton）是真核细胞质中由蛋白纤维构成的系统，赋予细胞形状并使其能定向运动。广义的细胞骨架包括细胞质骨架、细胞核骨架和细胞膜骨架，其中细胞质骨架主要由微丝、微管和中间纤维三类组成：微丝直径约7 nm，由肌动蛋白构成双股螺旋，柔软；微管直径约26 nm，为微管蛋白构成的中空圆柱体；中间纤维直径约10 nm，由多种蛋白组成，呈绳状。细胞骨架参与物质运输、肌肉收缩、细胞形态的维持与改变、细胞分裂以及对外界刺激的反应。","src":"《第6章 细胞骨架》p3、p5、p6；《MBoC 7e》Glossary"},{"id":"d1b94e56","s":"c","g":"c07","n":"肌动蛋白","e":"actin","d":"肌动蛋白（actin）是微丝的单体，具ATP或ADP结合位点。单体头尾相接聚合成两条原纤丝，再相互缠绕成双股螺旋的肌动蛋白丝，即微丝。单体浓度高于临界浓度时微丝装配，低于临界浓度时解聚。肌动蛋白有多种异构体：α肌动蛋白分别为横纹肌、心肌、血管平滑肌和肠道平滑肌所特有，β和γ肌动蛋白则存在于所有肌肉细胞和非肌肉细胞中。以Arp2/3为核心可形成分支的微丝而呈网状分布，以formins为核心则形成不分支的微丝束，如张力纤维，附着到细胞膜上。","src":"《第6章 细胞骨架》p9、p13、p25"},{"id":"d83340c6","s":"c","g":"c07","n":"肌原纤维","e":"myofibril","d":"肌原纤维（myofibril）是肌细胞质中由肌动蛋白、肌球蛋白及其他蛋白组成的长而高度有序的纤维束，通过肌丝滑动机制收缩。肌原纤维由粗丝与细丝交替排列构成肌节。细丝由肌动蛋白、原肌球蛋白和肌钙蛋白（TnC、TnT、TnI）组成；粗丝由肌球蛋白构成，可分为HMM和LMM。肌原纤维周围包绕着肌质网，质膜内陷形成的横小管把动作电位传入细胞内部，信号经横小管传给肌质网，引起Ca2+释放，胞质Ca2+浓度升高即启动肌原纤维的收缩。","src":"《第6章 细胞骨架》p35、p37、p45；MBoC 7e 印刷 p981；《MBoC 7e》Glossary"},{"id":"88d988a2","s":"c","g":"c07","n":"肌球蛋白","e":"myosin","d":"肌球蛋白（myosin）是沿肌动蛋白丝移动的马达蛋白。以肌球蛋白II为例，它由2条重链和2条各两拷贝的轻链组成，两条重链的α螺旋尾部缠绕成卷曲螺旋介导二聚化，每条重链N端有一个球状头部，含产生力的结构，并具ATP酶活性、能与肌动蛋白结合。肌球蛋白II驱动肌肉收缩和胞质分裂，肌球蛋白I和V则参与骨架与膜的相互作用，如运输膜泡。用蛋白酶处理肌球蛋白可得到重酶解肌球蛋白和轻酶解肌球蛋白。其运动方向指向微丝正极。","src":"《第6章 细胞骨架》p29、p38；MBoC 7e 印刷 p976","x":1},{"id":"733b017d","s":"c","g":"c07","n":"肌球蛋白I","e":"myosin I","d":"肌球蛋白I（myosin I）是肌球蛋白超家族中结构较简单的一员，只含一个头部和一个较短的尾部，不形成二聚体，也不聚合成纤维。它的头部具有ATP酶活性，能沿肌动蛋白丝向正极移动；尾部则与膜泡等多种货物相连，因而能在微丝上运输膜性物质，参与细胞骨架与细胞膜的相互作用。与肌球蛋白II驱动肌肉收缩和胞质分裂不同，肌球蛋白I和肌球蛋白V主要参与骨架与膜的相互作用，如膜泡运输；这类运输与驱动蛋白、动力蛋白沿微管的运输相配合。","src":"《第6章 细胞骨架》p29、p32"},{"id":"b9f2bbd1","s":"c","g":"c07","n":"肌肉收缩的滑动机制","e":"","d":"肌肉收缩的滑动机制指Ca2+诱导肌球蛋白向肌动蛋白丝正极移动、使肌节缩短的过程。静息时原肌球蛋白封闭肌动蛋白上的肌球蛋白结合位点；Ca2+升高后肌钙蛋白C结合Ca2+，原肌球蛋白移位，位点暴露，肌球蛋白头部与之结合。随后头部摆动产生力：与ATP结合时头部与肌动蛋白分离，与ADP结合时重新结合，每水解1个ATP头部沿微丝移动约36 nm。由于粗丝两侧的肌球蛋白头部各朝向一组极性相反的细丝，两极同时向细丝正极行走，使肌节缩短而肌丝长度不变。","src":"《第6章 细胞骨架》p42；MBoC 7e 印刷 p980"},{"id":"c7f21e0f","s":"c","g":"c07","n":"肌节","e":"sarcomere","d":"肌节（sarcomere）是肌原纤维上由粗丝和细丝交替排列形成的结构单位，在显微镜下呈现明带与暗带相间的横纹。肌节以Z盘为界，中间为A区即暗带，A区中央为H区，H区两侧是粗细肌丝重叠的区域，两端的明带只含细丝。收缩时，粗丝两侧的肌球蛋白头部与极性相反的两组细丝结合，向各自的正极行走，使细丝向肌节中央滑入，肌节缩短，而粗丝与细丝本身的长度都不改变。由于许多肌节首尾相接排列成肌原纤维，肌节的微小缩短可在肌纤维水平累加，产生肌肉的整体收缩。","src":"《第6章 细胞骨架》p35、p36；MBoC 7e 印刷 p980"},{"id":"958810d0","s":"c","g":"c07","n":"肌节","e":"","d":"肌节是肌原纤维的结构单元，由粗丝和细丝按一定规律交替排列而成，是肌肉收缩的基本单位。一个肌节以两侧的Z盘为边界，内部依次为含细丝的明带、粗细肌丝重叠区、只含粗丝的H区，以及粗丝所在的A区即暗带。这种周期性的分子排列使肌原纤维在光镜下呈现明暗相间的横纹，也使无数肌球蛋白头部能同时作用于极性相反的两组细丝。收缩时各肌节的长度缩短而肌丝长度不变，众多肌节串联起来，就使整根肌纤维明显缩短，产生收缩力。","src":"《第6章 细胞骨架》p36"},{"id":"8b90272a","s":"c","g":"c07","n":"肌质网","e":"sarcoplasmic reticulum","d":"肌质网（sarcoplasmic reticulum）是肌细胞中特化的内质网，主要功能是储存和释放Ca2+。肌细胞质膜去极化时，动作电位沿质膜内陷形成的横小管迅速传入细胞深部，激活横小管膜上的Ca2+通道，触发肌质网膜上Ca2+释放通道开放，Ca2+涌入胞质，启动肌原纤维收缩。收缩完成后，胞质中的Ca2+又被肌质网膜上的Ca2+泵收回腔内，胞质Ca2+浓度下降，肌肉恢复舒张。这种释放与回收可使收缩对Ca2+变化作出极快反应。","src":"《第6章 细胞骨架》p45；MBoC 7e 印刷 p982"},{"id":"d7c45ae4","s":"c","g":"c07","n":"肌钙蛋白","e":"troponin","d":"肌钙蛋白（troponin）是肌肉细丝上的调节蛋白，由TnT、TnI和TnC三个多肽亚基组成。TnT与原肌球蛋白结合，TnC与Ca2+结合，TnI既能与肌动蛋白结合，也能与TnT结合，并抑制肌球蛋白ATPase的活性。静息肌肉中，TnI-TnT复合体把原肌球蛋白从正常的结合沟中拉出，置于妨碍肌球蛋白头部结合的位置；Ca2+升高后TnC结合Ca2+，这一抑制解除，原肌球蛋白落回沟内，暴露出肌动蛋白上的结合位点，引起收缩。","src":"《第6章 细胞骨架》p37、p48；MBoC 7e 印刷 p982"},{"id":"2569cae7","s":"c","g":"c07","n":"表皮水疱症","e":"","d":"表皮水疱症是一种由角蛋白基因突变引起的遗传性皮肤病，其分子基础在于角蛋白中间纤维装配的缺陷。患者的角蛋白K4和K14突变体具有缺陷的N端或C端，突变蛋白仍能与正常角蛋白形成异二聚体，但不能进一步装配成原纤丝即四聚体，因而表皮细胞中缺乏正常的角蛋白中间纤维。中间纤维本应为细胞提供机械张力，其缺失使表皮细胞之间的连接变得脆弱，皮肤在受到轻微机械摩擦后即发生离层和起泡。这一疾病从反面说明中间纤维对维持皮肤组织机械强度的必要性。","src":"《第6章 细胞骨架》p148"},{"id":"b528fe97","s":"c","g":"c07","n":"踏车行为","e":"treadmilling","d":"踏车行为（treadmilling）是指蛋白纤维在一端添加亚基、另一端丢失亚基，从而使纤维总长度保持不变的动态过程。其条件是游离单体浓度介于两端的临界浓度之间，即正极的临界浓度小于该浓度、而该浓度又小于负极的临界浓度：此时正极的装配快于负极，正极净装配而负极净解聚。微丝和微管都存在这一现象；由于两端临界浓度不同，纤维在稳态下仍持续消耗能量。对肌动蛋白而言，稳态踏车需要ATP水解持续供能，亚基在游离态与纤维态之间快速循环，而纤维长度不变。","src":"《第6章 细胞骨架》p14、p76；MBoC 7e 印刷 p963"},{"id":"d023f583","s":"c","g":"c07","n":"重酶解肌球蛋白","e":"HMM","d":"重酶解肌球蛋白（HMM）是肌球蛋白经胰蛋白酶处理后得到的片段，含S1头部和S2杆部。HMM的头部即HMM-S1，具有ATP酶活性，并能与肌动蛋白结合，是粗丝上伸出形成横桥、产生力的部分；S2杆部则把头部与粗丝的骨干相连。由于S1头部保留了ATP酶活性和与肌动蛋白结合的能力，纯化的S1头部常被固定在玻片上，与荧光鬼笔环肽标记的肌动蛋白丝及ATP一起使用，用来在体外直接观察单个肌球蛋白分子沿肌动蛋白丝移动。","src":"《第6章 细胞骨架》p37、p38、p39"},{"id":"d6956ced","s":"c","g":"c07","n":"长春花碱","e":"","d":"长春花碱是影响微管组装的特异性药物，其作用与秋水仙素相同，即阻止微管装配。它结合于微管蛋白二聚体上的长春花碱结合位点，使微管蛋白不能聚合成微管，并促使已形成的微管解聚。微管蛋白二聚体上除2个GTP结合位点、二价阳离子结合位点外，还各有1个秋水仙素、1个长春花碱和1个紫杉醇结合位点，这些位点正是各类微管药物的作用靶点。由于微管动态为纺锤体功能所必需，长春花碱处理可使细胞有丝分裂受阻，并激活纺锤体组装检验点，使细胞停滞于中期。","src":"《第6章 细胞骨架》p64、p86"},{"id":"8707bfe4","s":"c","g":"c07","n":"长春花碱","e":"vinblastine","d":"长春花碱（vinblastine）是结合微管蛋白亚基、阻止微管装配的特异性药物。微管解聚后，纺锤体无法正常组装。用秋水仙素或长春花碱处理细胞，可使细胞在有丝分裂期停滞数小时甚至数天，这一现象导致纺锤体组装检验点的发现：该检验点监测纺锤体微管的连接状态，确保所有染色体都正确双向取向于纺锤体之后，细胞才进入后期；药物处理激活该检验点，阻断了中期向后期的转变。因此长春花碱既是有丝分裂阻断剂，也是研究细胞周期检验点的重要工具。","src":"《第6章 细胞骨架》p64、p86、p87；MBoC 7e 印刷 p1062"},{"id":"9fb46fe4","s":"c","g":"c07","n":"鞭毛","e":"flagella","d":"鞭毛（flagella）是细胞表面以微管和动力蛋白为基础的长毛状运动结构，其核心是由微管构成的轴丝。轴丝为9+2结构，即9组二联体微管围成一圈、中央一对单微管；二联体A管上的动力蛋白臂水解ATP使相邻二联体相互滑动，滑动被连接蛋白约束后转变为轴丝的弯曲波，驱动鞭毛摆动。鞭毛见于精子和许多原生动物。与纤毛相比，鞭毛更长，通常每个细胞只有一根或少数几根，其作用主要是移动整个细胞而不是产生液流；两者都由间期的基体发出，基体核心是一个中心粒。","src":"《第6章 细胞骨架》p119；MBoC 7e 印刷 p1004"},{"id":"3575e67b","s":"c","g":"c07","n":"马达蛋白","e":"motor proteins","d":"马达蛋白（motor proteins）是能把化学能转变为机械运动、沿细胞骨架纤维定向移动并运输货物的蛋白质。各类马达蛋白的共同点是都能抓住货物与轨道并消耗ATP。微丝上的马达蛋白是肌球蛋白，微管上的马达蛋白是驱动蛋白和动力蛋白：肌球蛋白向微丝正极移动，驱动蛋白背离MTOC向微管正极移动，动力蛋白朝向MTOC向微管负极移动。马达蛋白产生的力负责肌肉收缩、细胞的爬行与游动，也驱动染色体向两极移动、细胞器沿轨道运输以及膜泡的定向转运。","src":"《第6章 细胞骨架》p106、p118；MBoC 7e 印刷 p167","x":1},{"id":"1e647103","s":"c","g":"c07","n":"驱动蛋白","e":"kinesin","d":"驱动蛋白（kinesin）是沿微管向正极移动的马达蛋白，即背离微管组织中心方向运输的分子马达。它为二聚体，两条重链的头部是相似的马达结构域，与ATP结合并在微管上移动，尾部结构域则各不相同，用于带动不同的物质；其特点是至少有一个头部始终结合在微管上，因而能沿微管长距离移动而不脱落。驱动蛋白与动力蛋白分工协作：驱动蛋白负责正极方向即由细胞中央向边缘的运输，动力蛋白负责负极方向即由边缘向中央的运输，共同完成细胞内物质的分区分布。","src":"《第6章 细胞骨架》p110、p112、p114；MBoC 7e 印刷 p1000","x":1},{"id":"13931361","s":"c","g":"c07","n":"鬼笔环肽","e":"phalloidin","d":"鬼笔环肽（phalloidin）是从白毒伞中分离的毒素，能沿肌动蛋白丝的侧面紧密结合，把纤维稳定住，从而抑制其解聚。它与细胞松弛素（结合微丝正端、阻止聚合）、拉春库林（结合肌动蛋白亚基、阻止聚合）作用相反，常与后两者并列作为研究微丝动态与功能的工具药物。由于鬼笔环肽能牢固而特异地结合微丝，其荧光衍生物被广泛用于标记和显示细胞内的肌动蛋白丝，例如在体外运动实验中用荧光鬼笔环肽标记肌动蛋白丝，观察其沿固定的肌球蛋白头部滑动。","src":"《第6章 细胞骨架》p18、p31；MBoC 7e 印刷 p963"},{"id":"3285a170","s":"c","g":"c12","n":"ATP合酶","e":"F0F1-ATP合酶 (ATP synthase)","d":"ATP合酶（F0F1-ATP合酶）是嵌于线粒体内膜的酶复合体，负责在质子动力势驱动下合成ATP。其F0基部由a、b2和c12组成，12个c亚基围成环形结构并构成质子通道；F1头部由α3β3γδε五种多肽组成，含ATP合成的催化位点。质子顺电化学梯度流经F0时，引起柄部在F1内旋转，使F1构象周期性变化，从而把电化学梯度中蕴藏的机械能转变为化学能，将ADP与Pi合成ATP。ATP合酶在嵴膜基质侧呈棒棒糖状突出，并沿嵴脊形成长排二聚体。","src":"《第7章细胞的能量代谢》p54、p56、p90"},{"id":"bf139355","s":"c","g":"c12","n":"C-4循环","e":"","d":"C-4循环是某些植物固定CO2的途径，其特点是碳的固定与光合产物的形成在不同部位和不同时间内完成。叶肉细胞兼具光系统I和光系统II，PEP羧化酶活性很高，能提高RuBP捕获CO2的能力：CO2先与磷酸烯醇式丙酮酸结合生成草酰乙酸，再转变成苹果酸或天冬氨酸等四碳酸，运到维管束鞘细胞。维管束鞘细胞没有堆积的类囊体，几乎没有PSII活性；四碳酸在此脱羧，释放出的CO2经卡尔文循环生成碳水化合物，脱羧产生的三碳酸则运回叶肉细胞再生PEP。","src":"《第7章细胞的能量代谢》p103"},{"id":"fe685c90","s":"c","g":"c12","n":"Hsp70","e":"HSP70","d":"Hsp70（HSP70）是一类分子伴侣，属hsp60和hsp70两大分子伴侣家族之一。在细胞质中维持前体蛋白的解析叠状态；人类共有13种hsp70蛋白，其中一组与核糖体结合，帮助新生成的多肽正确折叠。线粒体有自己的hsp70：前体蛋白进入基质后，线粒体hsp70一个接一个地结合在蛋白质线性分子上，像齿轮一样把蛋白质绞进基质，此过程消耗ATP；随后hsp70把蛋白质交给hsp60，完成折叠。内质网中则有特殊的hsp70即BiP协助折叠。","src":"《第7章细胞的能量代谢》p118、p119；MBoC 7e 印刷 p381"},{"id":"abf35fc1","s":"c","g":"c12","n":"NADH脱氢酶复合体","e":"complex I","d":"NADH脱氢酶复合体（complex I）是呼吸链中最大的呼吸酶复合体，催化NADH的电子传递至辅酶Q，同时将质子由线粒体基质转移至膜间隙。它接受来自NADH的电子，经黄素单核苷酸和八个铁硫簇传递给泛醌。该复合体含42个蛋白亚基、至少6个Fe-S中心和1个以FMN为辅基的黄素蛋白，并泵出4个H+。在嵴膜上，它与复合体III、IV串联，作为电子传递驱动的H+泵把质子泵出基质、酸化嵴间隙，从而建立质子动力势，供ATP合酶合成ATP。","src":"《第7章细胞的能量代谢》p22；MBoC 7e 印刷 p827"},{"id":"510ad5c6","s":"c","g":"c12","n":"OXA复合体","e":"","d":"OXA复合体是线粒体内膜上的蛋白质转运与插入装置，负责把线粒体自身合成的蛋白以及某些进入基质的蛋白插入到内膜上。线粒体蛋白的转运涉及多种复合体：TOM复合体负责前体蛋白通过外膜进入膜间隙；TIM复合体中TIM23把蛋白质转运到基质或安装在内膜上，TIM22把某些转运蛋白插入内膜；SAM复合物协助外膜蛋白正确折叠；OXA则承担内膜插入这一环节。线粒体有1000多种蛋白，自身只能合成十余种，因此OXA对呼吸链复合体的组装十分重要。","src":"《第7章细胞的能量代谢》p113、p116"},{"id":"476a8fa9","s":"c","g":"c12","n":"RuBP羧化酶","e":"","d":"RuBP羧化酶是叶绿体基质中参与碳同化的关键酶，即核酮糖-1,5-二磷酸羧化酶，占基质可溶性蛋白总量的60%。基质是内膜与类囊体之间的空间，除含碳同化相关的酶类外，还含叶绿体DNA、各类RNA、核糖体等蛋白质合成体系，以及淀粉粒、质体小球和植物铁蛋白等颗粒成分。卡尔文循环的第一步即由RuBP羧化酶催化核酮糖-1,5-二磷酸固定CO2，生成甘油酸-3-磷酸；在C-4植物中，维管束鞘细胞中四碳酸脱羧释放的CO2经卡尔文循环生成碳水化合物。","src":"《第7章细胞的能量代谢》p79、p101、p103"},{"id":"6cff69d5","s":"c","g":"c12","n":"解偶联剂","e":"uncoupling agents","d":"解偶联剂（uncoupling agents）是一类能同时消除跨膜质子梯度和ATP合成的试剂。化学渗透假说认为电子传递释能先转为H+梯度，再由H+经ATP合酶回流驱动ATP合成。支持该假说的证据包括：含复合体I、III或IV的膜泡可建立质子梯度；氧化磷酸化需要一个由膜围成的区室；质子梯度蕴含的能量足以驱动ATP合成；无电子传递时，人工质子梯度同样能驱动ATP合成。而解偶联剂同时消除质子梯度与ATP合成，正说明二者互为因果、密切偶联。","src":"《第7章细胞的能量代谢》p52"},{"id":"c42c4e0b","s":"c","g":"c12","n":"三羧酸循环","e":"TCA cycle（柠檬酸循环/Krebs循环）","d":"三羧酸循环（TCA cycle）又称柠檬酸循环或Krebs循环，因发现者Hans Adolf Krebs而得名。该循环在线粒体基质中进行，基质中含三羧酸循环酶系、线粒体基因表达酶系以及线粒体DNA、RNA和核糖体。有氧代谢在细胞内分区进行：丙酮酸进入线粒体后转变为乙酰辅酶A，再进入三羧酸循环；循环过程中产生的高能电子经电子传递链传递，为合成ATP提供动力。因此三羧酸循环既是糖、脂和氨基酸氧化的共同通路，也是把氧化释能转化为ATP的起点。","src":"《第7章细胞的能量代谢》p7、p12、p20"},{"id":"f53005f4","s":"c","g":"c12","n":"假环式电子传递","e":"","d":"假环式电子传递是光合电子传递的一条途径，其最终电子受体是氧。水中的电子经光系统II和光系统I传递，经质体醌、细胞色素b6/f、质体蓝素传给铁氧还蛋白后，不再交给NADP+，而是直接传递给氧，生成超氧阴离子自由基。该过程造成氧的消耗和过氧化氢的生成，形成的超氧自由基对植物体造成危害。它在强光、CO2不足、NADPH过剩的条件下发生；叶绿体光系统I受体端存在的氧化酶可通过米勒反应把电子由铁氧还蛋白传给氧，再经超氧化物歧化酶转变成过氧化氢。","src":"《第7章细胞的能量代谢》p97"},{"id":"7ff7d636","s":"c","g":"c12","n":"内共生起源假说","e":"","d":"内共生起源假说认为线粒体起源于被真核细胞吞入的细菌。1963年M. & S. Nass发现线粒体DNA，为此提供了依据。支持该假说的特征包括：线粒体具有环形DNA；含70S核糖体；其RNA聚合酶被溴化乙锭抑制而不被放线菌素D抑制；tRNA和氨酰基-tRNA合成酶不同于细胞质中的；其增殖方式也类似细菌。该假说的不足在于，难以解释共生体的遗传信息如何向宿主转移、细胞核如何进化，以及基因组中内含子的来源等问题。","src":"《第7章细胞的能量代谢》p125、p126"},{"id":"ee98d813","s":"c","g":"c12","n":"内膜转运酶","e":"TIM (translocase of inner membrane) complex","d":"内膜转运酶（TIM）复合体是线粒体内膜上的蛋白质转运装置，负责把前体蛋白送入基质或安装到内膜上。其中TIM23负责将蛋白质转运到基质，或将其安装在内膜上；TIM22负责把某些转运蛋白插入内膜。前体蛋白以未折叠形式存在，N端导肽先与外膜受体识别，在内外膜局部融合形成的接触点处，通过外膜TOM复合体后，以质子动力势为动力通过内膜的TIM复合体；进入基质后由线粒体hsp70协助完成转运，导肽随后被信号肽酶切除。转运既耗ATP，又依赖膜电位。","src":"《第7章细胞的能量代谢》p116、p118、p119"},{"id":"98e7985b","s":"c","g":"c12","n":"化学渗透假说","e":"chemiosmotic coupling hypothesis","d":"化学渗透假说（chemiosmotic coupling hypothesis）是解释氧化磷酸化偶联机制的学说。其内容是：电子传递链各组分在内膜中不对称分布，高能电子沿其传递时所释放的能量将H+从基质泵到膜间隙，形成H+电化学梯度；在这个梯度驱使下，H+穿过ATP合酶回到基质，同时合成ATP。该梯度所蕴含的能量称为质子动力势。支持它的证据包括：含复合体I、III或IV的膜泡能建立质子梯度；解偶联剂则同时消除梯度与ATP合成。","src":"《第7章细胞的能量代谢》p49、p51、p52"},{"id":"92cd0488","s":"c","g":"c12","n":"半自主性细胞器","e":"","d":"半自主性细胞器指线粒体和叶绿体，它们的基因组能编码少量蛋白质，但绝大部分蛋白质由核基因组编码，因而在遗传上只具有部分的自主性。线粒体有1000多种蛋白，自身合成的仅十余种，其余均由核基因编码、在细胞质核糖体上合成后以前体蛋白形式运入；叶绿体同样如此。这些由核编码的前体蛋白以未折叠形式存在，N端带有导肽即信号肽，完成运输后被信号肽酶切除成为成熟蛋白。正因依赖两套基因组的协同，线粒体和叶绿体的生物发生需要核与细胞器之间双向的物质与信息交流。","src":"《第7章细胞的能量代谢》p106、p113"},{"id":"39959ad3","s":"c","g":"c12","n":"卡尔文循环","e":"C3途径","d":"卡尔文循环即C3途径，是光合碳同化也就是暗反应的途径。其碳固定的第一步反应由核酮糖-1,5-二磷酸即RuBP固定CO2，生成甘油酸-3-磷酸；循环的总反应可写作6CO2+18ATP+12NADPH生成C6H12O6+12NADP+与18ADP和18Pi。该循环在叶绿体基质中进行，基质中的RuBP羧化酶占基质可溶性蛋白总量的60%。在C-4植物中，四碳酸在维管束鞘细胞脱羧释放的CO2正是进入卡尔文循环生成碳水化合物。","src":"《第7章细胞的能量代谢》p101、p102、p103"},{"id":"6c174d2c","s":"c","g":"c12","n":"基粒","e":"","d":"基粒是叶绿体中由扁平类囊体小囊堆叠而成的结构。类囊体是膜围成的扁平囊，主要成分是蛋白质和脂类，膜流动性高；堆叠成垛的称基粒类囊体，连接不同基粒而本身不堆叠的称基质类囊体。类囊体膜是光合链的场所，光系统、细胞色素b6/f复合体、ATP合酶以及天线复合物等均位于膜上，膜围成的内腔即类囊体腔。基粒的堆叠大大增加了膜的面积，使更多的光合色素与电子传递复合体得以排布；在叶绿体的显微结构中可见外膜、内膜、膜间隙、基质、基粒及类囊体腔等部分。","src":"《第7章细胞的能量代谢》p73、p74、p90"},{"id":"5104c8de","s":"c","g":"c12","n":"外膜转运酶","e":"TOM (translocase of outer membrane) complex","d":"外膜转运酶（TOM）复合体是线粒体外膜上的蛋白质转运装置，负责前体蛋白通过外膜。线粒体蛋白的转运涉及多种复合体：TOM负责通过外膜；内膜转运酶TIM复合体中，TIM23把蛋白质转运到基质或安装在内膜上，TIM22把某些转运蛋白插入内膜；OXA复合体负责把线粒体自身合成的蛋白和某些进入基质的蛋白插入内膜；SAM复合物协助外膜蛋白正确折叠。前体蛋白以未折叠形式与外膜受体识别，在内外膜接触点处穿过外膜，再以质子动力势为动力经TIM进入基质。","src":"《第7章细胞的能量代谢》p116、p118；《MBoC 7e》Glossary"},{"id":"22d91d1c","s":"c","g":"c12","n":"天线复合物","e":"LHC (light-harvesting complexes)","d":"天线复合物（LHC，light-harvesting complexes）是类囊体膜上捕捉光能的膜蛋白复合物。它由不同的膜蛋白复合物构成，内含大量叶绿素等色素分子；光照射叶绿素分子时，能量迅速从一个分子转移到另一个分子，这种传递方式称为共振能量转移。被激活的叶绿素分子把能量汇集到反应中心，反应中心最终产生高能电子，并迅速传递给类囊体膜上电子传递链的载体即醌。天线复合物因而扩大了光系统捕获光能的截面，使光能高效地汇集到反应中心。","src":"《第7章细胞的能量代谢》p77、p78"},{"id":"0593ad36","s":"c","g":"c12","n":"孔蛋白","e":"porin","d":"孔蛋白（porin）是线粒体外膜上的运输蛋白，构成的亲水通道允许分子量5 kD以下的物质通过。线粒体外膜含约50%的蛋白质和50%的脂类，因含孔蛋白而通透性较高；内膜含80%的蛋白质和20%的脂类，通透性很低，具有选择透性。外膜的高通透性使膜间隙的组成近似于细胞质，而内膜的高度不通透性则是维持质子梯度、进行氧化磷酸化的前提。叶绿体膜上也有由孔蛋白形成的通道：叶绿体前体蛋白的基质导向序列即引导其穿过膜上由孔蛋白形成的通道进入基质。","src":"《第7章细胞的能量代谢》p7、p11、p122"},{"id":"c8cec62c","s":"c","g":"c12","n":"导肽","e":"","d":"导肽又称信号肽，是线粒体前体蛋白N端的一段信号序列，引导蛋白质穿越线粒体膜进入基质。其结构特征为：含有丰富的带正电荷的碱性氨基酸，特别是精氨酸和赖氨酸，这有助于信号肽进入带负电荷的线粒体基质；几乎不含带负电荷的酸性氨基酸；可形成既亲水又疏水的α螺旋，有利于穿越线粒体的双层膜。导肽不仅含识别线粒体的信息，还具有牵引蛋白质通过线粒体膜运送的功能；它只起引导作用，并非蛋白质的永久结构，完成运输后被信号肽酶切除，成为成熟蛋白。","src":"《第7章细胞的能量代谢》p113、p115、p118"},{"id":"206179ba","s":"c","g":"c12","n":"嵴","e":"cristae","d":"嵴（cristae）是线粒体内膜向基质侧折叠形成的突起。内膜是氧化磷酸化电子传递链所在的场所，含与能量转换相关的蛋白，高度不通透；内膜向线粒体内室褶入形成嵴，使有限的线粒体体积内容纳更多的内膜，从而容纳更多的呼吸链复合体和ATP合酶。在电镜下，ATP合酶复合体像棒棒糖一样突出于嵴膜的基质侧，且并不随机分布，而是沿嵴脊形成长排二聚体；二聚体行列诱导或稳定了该处的高膜弯曲。嵴因此不仅扩大面积，还组织ATP合酶的排布以提高合成效率。","src":"《第7章细胞的能量代谢》p7、p11；MBoC 7e 印刷 p840"},{"id":"f50cb442","s":"c","g":"c12","n":"循环光合磷酸化","e":"","d":"循环光合磷酸化是光合磷酸化的一条途径，其电子传递只涉及光系统I。光系统I受光激发后放出的电子经质体醌、细胞色素b6/f复合体、质体蓝素和铁氧还蛋白传递，最终又回到光系统I，形成闭合回路。由于电子不传向NADP+，该途径不产生NADPH，也不涉及水的裂解，因而不产生O2；电子在回路中传递时释放的能量则用于建立H+梯度，驱动ATP合酶合成ATP。循环光合磷酸化因此只提供ATP而不提供还原力，与产生NADPH的非循环电子传递形成分工。","src":"《第7章细胞的能量代谢》p90、p93"},{"id":"ad62b8b4","s":"c","g":"c12","n":"心磷脂","e":"cardiolipin（双磷脂酰甘油/TPL）","d":"心磷脂（cardiolipin，双磷脂酰甘油/TPL）是线粒体内膜的主要脂类成分，约占内膜脂类的20%。线粒体的脂类占其干重的25%至30%，其中磷脂占3/4以上；外膜主要是卵磷脂，内膜则主要是心磷脂。内膜含80%的蛋白质和20%的脂类，脂类与蛋白质的比值约为0.3比1，而外膜为1比1，这种高蛋白、低脂的组成与内膜承担电子传递、氧化磷酸化和代谢物转运的功能相适应。心磷脂是内膜的特征性磷脂，与标志酶细胞色素氧化酶共存。","src":"《第7章细胞的能量代谢》p8、p10、p11"},{"id":"dbe91da3","s":"c","g":"c12","n":"景天酸代谢","e":"CAM","d":"景天酸代谢（CAM）是干旱地区景天科及其他肉质植物固定CO2的方式，其特点是气孔开闭与碳固定在时间上的分离。这类植物白天气孔关闭以减少水分散失，夜间气孔开放；夜间由PEP羧化酶固定CO2，生成草酰乙酸，进而形成苹果酸，积累在液泡中；白天苹果酸脱羧，释放出CO2和丙酮酸，CO2进入卡尔文循环生成碳水化合物。这种夜间固定、白天同化的时间分隔，使植物在白天高温干旱、气孔关闭的条件下仍能获得CO2，因而是对干旱环境的一种适应。","src":"《第7章细胞的能量代谢》p104"},{"id":"9eaf09cf","s":"c","g":"c12","n":"氧化还原电位","e":"","d":"氧化还原电位是衡量物质得失电子倾向的指标，电位越高氧化性越强，电位越低氧化性越弱。在电子传递链中，NADH脱氢酶复合物、细胞色素b-c1复合物、细胞色素c氧化酶复合物以及泛醌、细胞色素c等按氧化还原电位由低到高依次排列，其中NAD+/NADH最低，H2O/O2最高，FADH2也处于较低位置。高能电子因此沿电位递增方向逐级传递，每经过一个载体释放一部分能量，供复合物将质子泵出，电位差即电子定向传递的驱动力。","src":"《第7章 细胞的能量代谢》p29、p45"},{"id":"3faab296","s":"c","g":"c12","n":"泛醌","e":"ubiquinone（辅酶Q，CoQ）","d":"泛醌（ubiquinone），又称辅酶Q（CoQ），是电子传递链中的脂溶性醌类电子载体，可同时携带两个质子和两个电子。它溶于线粒体内膜的脂双层，不与蛋白质紧密结合，因而是呼吸链中唯一可移动的载体：既接受NADH脱氢酶复合物传来的电子，也接受琥珀酸脱氢酶复合物由FADH2传来的电子，再把电子交给细胞色素b-c1复合物。它在膜内每接受一个电子即从水相摄取一个质子，还原为泛醇，从而把电子传递与质子跨膜转移耦联起来。","src":"《第7章 细胞的能量代谢》p24、p34；MBoC 7e 印刷 p827"},{"id":"f7d78b56","s":"c","g":"c12","n":"琥珀酸脱氢酶复合物","e":"complex II","d":"琥珀酸脱氢酶复合物（complex II）是线粒体内膜上四个呼吸酶复合体之一，含FAD辅基和2个Fe-S中心。它催化FADH2的电子经FAD、Fe-S中心传递给泛醌（辅酶Q），但不能将质子由线粒体基质转移至膜间隙，即没有质子泵出。与之相比，NADH脱氢酶复合物含42个蛋白亚基、至少6个Fe-S中心和1个黄素蛋白，催化NADH氧化取得2个高能电子交给辅酶Q，并泵出4个H+。四者与泛醌、细胞色素c共同组成电子传递链。","src":"《第7章 细胞的能量代谢》p22、p35；MBoC 7e 印刷 p827"},{"id":"5dd2abc3","s":"c","g":"c12","n":"电化学质子梯度","e":"","d":"电化学质子梯度是线粒体内膜两侧由pH梯度与膜电位共同构成的跨膜H+梯度。电子传递链各复合物把质子由基质泵至膜间隙后，基质pH比膜间隙高约一个单位，质子浓度低约10倍，同时基质侧带负电、膜间隙侧带正电，两种成分叠加形成陡峭的电化学质子势。该梯度使H+具有强烈流回基质的趋势，其中蕴藏的能量即质子动力势，在氧化磷酸化过程中驱动ATP合成酶合成ATP，是化学渗透假说解释电子传递与ATP合成相偶联的核心。","src":"《第7章 细胞的能量代谢》p26、p28、p49"},{"id":"7b707229","s":"c","g":"c12","n":"电子传递链（呼吸链）","e":"electron transport chain / respiratory chain","d":"电子传递链（electron transport chain），又称呼吸链（respiratory chain），由线粒体内膜上的NADH脱氢酶复合物、细胞色素b-c1复合物、细胞色素c氧化酶复合物等呼吸酶复合物，以及泛醌、细胞色素c等可移动载体组成。电子沿氧化还原电位递增的方向逐级传递，高能电子释放的能量驱动三大复合物将H+从基质泵到膜间隙，形成跨内膜的H+电化学梯度。琥珀酸脱氢酶复合物催化的电子也经泛醌汇入此链。","src":"《第7章 细胞的能量代谢》p22、p25、p45"},{"id":"b95ecad7","s":"c","g":"c12","n":"类囊体","e":"thylakoid","d":"类囊体（thylakoid）是叶绿体内部由膜围成的扁平囊，主要成分是蛋白质和脂类，膜流动性高，是光合链进行的场所。多个扁平小囊堆叠形成基粒类囊体，连接各基粒而本身不堆叠者称基质类囊体。叶绿体由外被、类囊体和基质三部分组成，具有外膜、内膜、类囊体膜三种膜，以及膜间隙、基质和类囊体腔三种彼此分开的腔。捕光色素等前体蛋白进入类囊体需经基质导向序列与类囊体导向序列两步转运，并分别在基质和类囊体腔中被切除。","src":"《第7章 细胞的能量代谢》p70、p73、p122；MBoC 7e 印刷 p734"},{"id":"63ff09f0","s":"c","g":"c12","n":"线粒体清除","e":"","d":"线粒体清除是受损线粒体被选择性降解的过程，属线粒体质量控制体系的组成部分，也是快速降解完整线粒体的唯一手段。它与其余质控途径分工不同：动力学机制通过MFNs、OPA-1介导的融合与Drp1、Fis-1介导的分裂，使轻微受损的线粒体融合以利修复；生物发生机制通过增加线粒体数目与产能应对应激；囊泡相关降解途径在轻微受损时包裹氧化的线粒体蛋白和脂质，经内体分选系统送入溶酶体；蛋白酶监控途径与蛋白酶体体系则分别降解未折叠蛋白和外膜受损蛋白。","src":"《第7章 细胞的能量代谢》p65、p68"},{"id":"1ed92232","s":"c","g":"c12","n":"线粒体质量控制体系","e":"","d":"线粒体质量控制体系是细胞维持线粒体功能与数量的一整套机制，包括五方面。其一是线粒体动力学机制，融合相关蛋白MFNs和OPA-1使轻微受损的线粒体融合以促进修复，分裂相关蛋白Drp1和Fis-1参与分裂；其二是线粒体生物发生机制，通过增加线粒体数目及产能应对细胞内外应激；其三是线粒体清除机制，选择性降解受损线粒体；其四是线粒体囊泡相关降解途径，经内体分选系统把氧化蛋白和脂质送入溶酶体；其五是线粒体内蛋白酶监控途径及蛋白酶体降解体系。","src":"《第7章 细胞的能量代谢》p65"},{"id":"116a261f","s":"c","g":"c12","n":"细胞色素b-c1复合体","e":"complex III（cytochrome c reductase）","d":"细胞色素b-c1复合体（complex III），即细胞色素c还原酶，是线粒体内膜上四个呼吸酶复合体之一，包括1个细胞色素c1、1个细胞色素b和1个Fe-S蛋白。它催化电子从泛醇（UQH2）传给细胞色素c，同时将质子由线粒体基质泵至膜间隙，并泵出4个H+。在电子传递链中它位于泛醌之后、细胞色素c氧化酶之前，把复合物Ⅰ与复合物Ⅱ经泛醌汇集的电子继续向下游传递，并通过质子泵出为ATP合成积累电化学梯度。","src":"《第7章 细胞的能量代谢》p22、p35、p39"},{"id":"9d21c7f1","s":"c","g":"c12","n":"细胞色素c氧化酶复合体","e":"complex IV（cytochrome oxidase）","d":"细胞色素c氧化酶复合体（complex IV），又称细胞色素c氧化酶，是呼吸链的末端复合物，呈二聚体，每一单体含13个亚基，具有特定三维构象，含细胞色素a、细胞色素a3以及Cu和Fe。它催化电子从细胞色素c传给分子氧并形成水，在基质侧消耗质子，同时把质子转移至膜间隙。人类呼吸所吸收的氧气基本上都在此步骤消耗。作为电子传递链的终点，它使呼吸链得以持续运转；氰化物、叠氮化物与之紧密结合，因而具剧毒。","src":"《第7章 细胞的能量代谢》p22、p35、p47"},{"id":"1c59e6e5","s":"c","g":"c12","n":"质子动力势","e":"proton motive force","d":"质子动力势（proton motive force）是跨膜电化学质子梯度所施加、推动质子穿膜的力量，是该梯度蕴藏能量的表现形式。按化学渗透假说，电子传递链各组分在线粒体内膜不对称分布，高能电子沿链传递时释放的能量将H+从基质泵到膜间隙，形成H+电化学梯度；H+在此梯度驱使下穿过ATP合成酶回到基质并合成ATP，能量储存到ATP高能磷酸键，故质子动力势是ATP合成的动力。它还有物质转运和产热作用，如冬眠动物与新生儿棕色脂肪细胞线粒体产热。","src":"《第7章 细胞的能量代谢》p16、p51、p119；MBoC 7e Glossary（PDF p1471）"},{"id":"61d2be17","s":"c","g":"c12","n":"黄素单核苷酸","e":"FMN (flavin mononucleotide)","d":"黄素单核苷酸（FMN, flavin mononucleotide）是黄素蛋白（flavoprotein）的辅基。NADH脱氢酶复合物即复合体Ⅰ，由三部分组成，整体呈L形，其中一个臂突出于线粒体基质，该臂又由两部分组成，其中之一就是黄素蛋白，FMN正是这一黄素蛋白的辅基。复合体Ⅰ催化NADH氧化，从中取得2个高能电子并交给辅酶Q，同时泵出4个H+；作为辅基的FMN参与电子的接纳与传递，使NADH的电子得以进入呼吸链。","src":"《第7章 细胞的能量代谢》p35、p38；MBoC 7e 印刷 p1468"},{"id":"a2f86f91","s":"c","g":"c06","n":"30nm染色质纤维","e":"30-nm fiber","d":"30nm染色质纤维（30-nm fiber）是核小体串珠结构进一步包装的高级结构。以往学说认为，在组蛋白H1存在时，直径11 nm的核小体串珠结构螺旋盘绕，每6个核小体绕一圈，构成外径30 nm的中空管，即螺线管。冷冻电镜观察则显示其真实结构为以每四个核小体为单位的左手螺旋，呈Zigzag堆叠方式。铺展染色质电镜观察中，未经处理的天然染色质呈30 nm纤丝，经盐溶液处理后解聚为10 nm串珠状结构，是染色质在核内的基本包装形式之一。","src":"《第8章 细胞核与染色体》p53、p54；MBoC 7e 印刷 p251"},{"id":"33809bb6","s":"c","g":"c06","n":"Barr body","e":"Barr body","d":"Barr body是女性体细胞中因X染色体随机失活而凝集形成的性染色质体。雌性哺乳动物早期胚胎发育过程中，两条X染色体之一在不同细胞里随机失活，使组织形成由不同失活状态细胞构成的嵌合斑块；失活的X染色体高度凝集，在核内表现为可用染料显示的浓缩小体，即Barr body。它属于兼性异染色质，是X染色体随机失活在形态上的体现；由于不同细胞失活的X染色体来源不同，组织呈斑块状嵌合，玳瑁猫与三色猫的毛色斑块即由此而来。","src":"《第8章 细胞核与染色体》p83"},{"id":"b3e48efe","s":"c","g":"c06","n":"HMG框基序","e":"HMG-box motif","d":"HMG框基序（HMG-box motif）是高迁移率族蛋白（high-mobility group protein）的特征性结构基序，属非组蛋白的DNA结合结构模式之一。含HMG框结构的转录因子称构建因子（architectural factor），它通过弯折DNA，促进与邻近位点相结合的其他转录因子之间的相互作用，从而激活转录。可见其作用在于改变DNA的构象与空间排布，为多种转录调控蛋白在同一区域共同发挥作用提供结构基础。","src":"《第8章 细胞核与染色体》p42、p46"},{"id":"3e157d0d","s":"c","g":"c06","n":"KDEL序列","e":"KDEL sequence","d":"KDEL序列（KDEL sequence）是可溶性内质网驻留蛋白C端的回收信号，由Lys-Asp-Glu-Leu或类似序列组成，即内质网驻留信号。若用基因工程方法把该信号从BiP上移除，BiP便会被缓慢分泌；若把该信号转移到本来是分泌蛋白的分子上，该蛋白则会被高效回收到内质网并在那里积累。与可直接同COPI衣被结合的膜蛋白回收信号不同，可溶性驻留蛋白须先与KDEL受体结合，该受体是多次跨膜蛋白，再经COPI小泡的回收途径返回内质网。","src":"MBoC 7e 印刷 p768","x":1},{"id":"1daba2ec","s":"c","g":"c06","n":"MAR","e":"MAR","d":"MAR即核骨架结合序列，指在高盐洗脱时不能解离、与核骨架结合的DNA序列。其特点为富含AT、富含DNA解旋元件（DNA unwinding element）、富含反向重复序列（inverted repeats），并含有转录因子结合位点。核骨架组成中DNA仅占约0.8%，这部分DNA可能正是与核骨架直接结合的MAR，其与蛋白结合无序列特异性；少量RNA则可能起维持结构的作用。MAR与染色质的定位、复制和转录活动密切相关。","src":"《第8章 细胞核与染色体》p135、p136","x":1},{"id":"3bdb3a84","s":"c","g":"c06","n":"Ran","e":"Ran","d":"Ran是Ras超家族的单体GTP酶，存在于细胞质与细胞核中，是物质经核孔复合体主动转运所必需的。Ran在核内以Ran-GTP为主、在胞质中以Ran-GDP为主，该浓度差由定位不同的两种调节蛋白维持：核内的Ran-GEF即鸟苷酸交换因子，促使Ran释放GDP并结合GTP；胞质的Ran-GAP即GTPase激活蛋白，促使Ran水解GTP。转运蛋白与cargo的结合受Ran-GTP活性调节，Ran-GTP/GDP梯度因此决定核质转运的方向性。","src":"《第8章 细胞核与染色体》p21、p23；MBoC 7e Glossary（PDF p1472）","x":1},{"id":"d0e54426","s":"c","g":"c06","n":"Ran-GAP","e":"Ran-GAP","d":"Ran-GAP是Ran的GTPase激活蛋白（Ran GTPase activating protein），定位于胞质中。它促使Ran结合的GTP水解，使Ran转变为Ran-GDP，把胞质Ran维持在GDP状态。核内Ran-GEF与胞质Ran-GAP的分布共同造成核质间Ran-GTP/GDP浓度差：胞质主要含Ran-GDP，细胞核主要含Ran-GTP。该梯度是核质转运的驱动力，决定转运蛋白与cargo结合或解离，使核输入输出具单向性。","src":"《第8章 细胞核与染色体》p23"},{"id":"35bd90f4","s":"c","g":"c06","n":"Ran-GEF","e":"Ran-GEF","d":"Ran-GEF是Ran的鸟苷酸交换因子（Ran guanine nucleotide exchange factor），定位于核中。它促使Ran释放GDP并重新结合GTP，使核内Ran主要以Ran-GTP形式存在。核内Ran-GEF与胞质Ran-GAP的定向分布，共同维持核质间Ran-GTP/GDP浓度差：胞质主要为Ran-GDP，细胞核主要为Ran-GTP。该梯度是核质转运的驱动力，转运蛋白与cargo的结合受Ran-GTP调节。","src":"《第8章 细胞核与染色体》p23"},{"id":"49a34e50","s":"c","g":"c06","n":"Ran-GTP","e":"Ran-GTP","d":"Ran-GTP是单体GTP酶Ran结合GTP后的活性形式，在核中浓度高，胞质中主要为Ran-GDP。转运蛋白与cargo的结合受Ran-GTP活性调节：亲核蛋白的NLS与输入蛋白结合成复合物，经核孔复合体转移到核质面，在核内与Ran-GTP结合后复合物解离、释放亲核蛋白；空载输入蛋白与Ran-GTP返回胞质，Ran-GAP促其水解，生成的Ran-GDP失去亲和力，输入蛋白进入下一轮。核输出受体同样以结合Ran-GTP的方式运cargo。","src":"《第8章 细胞核与染色体》p21、p23、p28；MBoC 7e 印刷 p741"},{"id":"7e9d0f4d","s":"c","g":"c06","n":"Xist","e":"Xist","d":"Xist（X inactive specific transcript）是一种长链非编码RNA，长约20 000个核苷酸，负责使雌性哺乳动物两条X染色体中的一条失活。其转录产物促进X染色体失活，但不被输送至胞浆，而是与即将被它失活的X染色体的某个成分相连，在失活染色体表面形成“外套”（coating），介导基因沉默。因此Xist以RNA形式在核内覆盖靶染色体并使其沉默，而不是翻译成蛋白质发挥作用，是X染色体失活过程中的关键分子。","src":"《第8章 细胞核与染色体》p82；MBoC 7e Glossary（PDF p1480）"},{"id":"5dc7f19d","s":"c","g":"c06","n":"X染色体失活","e":"X-chromosome inactivation, XCI","d":"X染色体失活（X-chromosome inactivation, XCI）指雌性哺乳动物体细胞中两条X染色体之一随机失活、变为异染色质的现象。失活由非编码RNA Xist介导：Xist转录产物促进XCI，不输送至胞浆，而与即将被它失活的X染色体的某个成分相连，在失活染色体表面形成外套（coating）介导基因沉默。失活在不同细胞中随机发生，故早期胚胎发育后组织呈斑块状嵌合；失活的染色体高度凝集，形成Barr体，属兼性异染色质。","src":"《第8章 细胞核与染色体》p81、p82、p83"},{"id":"9d890412","s":"c","g":"c06","n":"YAC","e":"YAC","d":"YAC（yeast artificial chromosome）即酵母人工染色体，是依据真核染色体复制与稳定传递所需元件构建的人工染色体。其三种功能元件为自主复制DNA序列（ARS）、着丝粒DNA序列（CEN）和端粒DNA序列（TEL）：ARS使DNA能自主起始复制，CEN保证染色体在细胞分裂时被分配到子细胞，TEL保护染色体末端。把外源DNA与这三种元件组合，即可构成能在酵母细胞中复制并稳定传代的人工染色体，三者缺一不可。","src":"《第8章 细胞核与染色体》p87、p96"},{"id":"b48d7385","s":"c","g":"c06","n":"exportin","e":"exportin","d":"exportin即核输出受体，是介导物质由细胞核输出到细胞质的受体蛋白，与Ran-GTP结合后运送cargo。以XPO5为例，它介导蛋白质及其他cargo的核输出，能与GTP结合构象的Ran结合，并以不依赖Ran-GTP的方式结合核孔蛋白NUP214、NUP153。不同exportin运送不同底物，如XPO1运mRNA、XPO3运tRNA，XPO5还是miRNA生成的关键。含核输出信号（NES）的蛋白因子即通过此类受体出核。","src":"《第8章 细胞核与染色体》p26、p28","x":1},{"id":"8098fd36","s":"c","g":"c06","n":"importin","e":"importin","d":"importin即输入蛋白，是核定位信号的受体蛋白，由α和β两个亚基组成，存在于细胞质中。亲核蛋白在细胞质合成后需进入核内发挥功能，其NLS与importin在胞质内结合形成转运复合物，复合物与核孔复合体胞质侧纤维结合，从胞质面转移到核质面，在核内与Ran-GTP结合后解离，释放亲核蛋白；importin随后返回细胞质，进入下一轮转运。因此importin作为可循环使用的载体，实现亲核蛋白的主动、选择性入核。","src":"《第8章 细胞核与染色体》p14、p21","x":1},{"id":"66b450e3","s":"c","g":"c06","n":"rDNA","e":"","d":"rDNA是编码核糖体RNA的多拷贝串联重复序列，成簇分布在少数染色体的核仁组织区（NOR）上，位于染色体的次缢痕区，并构成核仁。利用一个rRNA基因作模板可同时转录100条rRNA分子；rRNA基因在染色质轴丝上呈串联重复排列，沿转录方向新生rRNA链逐渐增长，转录产物的游离端首先形成核糖核蛋白颗粒，体现了核仁活动的高效性。真核生物中5S rDNA不定位在NOR上，它以多个拷贝串联分布于常染色体，在核仁外由RNA聚合酶Ⅲ转录。","src":"《第8章 细胞核与染色体》p125、p127、p129"},{"id":"545065b0","s":"c","g":"c06","n":"亮氨酸拉链","e":"leucine zipper","d":"亮氨酸拉链（leucine zipper, ZIP）是非组蛋白的一种DNA结合结构模式。两个α螺旋间的Leu残基相互作用，使两条螺旋结合成短的卷曲螺旋，形成二聚化界面；拉链以外的区域两条α螺旋分开成Y状，以剪刀状构型与DNA结合，使侧链得以接触DNA大沟，该类蛋白因此以二聚体形式结合DNA。它与螺旋-转角-螺旋、锌指结构、螺旋-环-螺旋基序、HMG框基序同属非组蛋白的常见结构模式。","src":"《第8章 细胞核与染色体》p42、p45；MBoC 7e 印刷 p404"},{"id":"536956ef","s":"c","g":"c06","n":"亲核蛋白","e":"karyophilic protein","d":"亲核蛋白（karyophilic protein）是在细胞质中合成后进入细胞核发挥功能的一类蛋白。它在一个细胞周期中可能一次性被转运到核内行使功能，也可能需要反复穿梭于核质之间。亲核蛋白一般都含有特殊的氨基酸序列，即核定位序列（NLS）或核定位信号，该信号被输入蛋白识别，介导其穿过核孔复合体进入核内，在核内与输入蛋白分离后被释放。核质蛋白即是经核定位信号运送入核的典型例子。","src":"《第8章 细胞核与染色体》p14、p21"},{"id":"0f9e2642","s":"c","g":"c06","n":"修饰盒","e":"","d":"修饰盒指在特定组蛋白尾部的邻近残基上同时发生多个共价修饰的组合，如H3K9甲基化与H3S10磷酸化。组蛋白修饰并不是彼此独立发生的，同一尾部相邻位点的修饰可相互影响，形成功能上的组合单元。与修饰盒不同，反式组蛋白通路（trans-histone crosstalk）指不同组蛋白尾巴或核小体之间的共价修饰组合，如H2BK123单泛素化对H3K4和H3K79三甲基化至关重要，可使非活化染色质转变为结构开放的染色质，有利于转录活化。","src":"《第8章 细胞核与染色体》p73"},{"id":"886dee46","s":"c","g":"c06","n":"内层核膜","e":"inner nuclear membrane","d":"内层核膜（inner nuclear membrane）是构成核被膜的两层同心膜之一，表面光滑、无核糖体，内侧紧贴核纤层（nuclear lamina），并借助核纤层蛋白B受体（Lamin B receptor, LBR）等与核纤层连接。核被膜还包括外层核膜和核周间隙，内外膜平行，融合处形成核孔。内层核膜含特定蛋白，可作为染色质与核纤层的锚定位点；在分裂末期核膜重建时，富含LBR的膜泡参与形成双层膜，故内层核膜也是核膜组装的重要参与者。","src":"《第8章 细胞核与染色体》p3、p5；MBoC 7e Glossary（PDF p1461）"},{"id":"116889cf","s":"c","g":"c06","n":"冈崎片段","e":"","d":"冈崎片段（Okazaki fragment）是DNA复制中后随链不连续合成所产生的短DNA片段，真核生物中长约150–200个核苷酸，细菌中约1000–2000个核苷酸。由于DNA聚合酶只能沿5′→3′方向延伸，后随链模板方向与之相反，复制叉前进时只能分段合成：每一片段先由引物酶合成RNA引物，再由DNA聚合酶延伸，随后引物被切除、缺口被填补，最后由DNA连接酶把片段连接成完整的长链。前导链连续合成而后随链不连续合成，故称半不连续复制。","src":"网络补充：wikipedia.org（Okazaki fragments）；article.xuexi.cn（半不连续复制）"},{"id":"f9c61d68","s":"c","g":"c06","n":"动粒","e":"kinetochore","d":"动粒（kinetochore）是位于着丝粒外表面的盘状蛋白结构，由三层蛋白构成，可分为内板、中间间隙、外板和纤维冠，其中内板含与着丝粒异染色质结合的蛋白质。每条染色单体主缢痕处的两侧各有一个动粒，且朝向相反。有丝分裂中期动粒与纺锤体微管相连，是染色体的运动中心；其聚集和形成依赖于着丝粒处的特定DNA序列。动粒对染色体稳定性、姐妹染色单体配对、纺锤体附着、染色体移动及细胞周期检查点控制都是必需的。","src":"《第8章 细胞核与染色体》p94、p95；MBoC 7e 印刷 p1056","x":1},{"id":"10f00e5f","s":"c","g":"c06","n":"单倍体","e":"haploid","d":"单倍体（haploid）指性细胞所含的一套染色体数，用n表示；体细胞为二倍体（diploid），以2n表示，某些物种染色体成倍增加成为4n、6n、8n等，称为多倍体。染色体数目因物种而异，如人类2n=46、黑猩猩2n=48、果蝇2n=8、家蚕2n=56、小麦2n=42、水稻2n=24。减数分裂时若同源染色体不能正确分离，产生的单倍体细胞会出现某条染色体缺失或增多，如Chr.21不分离可导致唐氏综合征。","src":"《第8章 细胞核与染色体》p109；《第10章 细胞分裂与细胞周期（上）》p87"},{"id":"9cdd12fe","s":"c","g":"c06","n":"卫星DNA","e":"satellite DNA","d":"卫星DNA（satellite DNA）属高度重复序列，占人基因组的10%，重复单位为5–100 bp，呈串联重复排列，散在分布或位于着丝粒。它与小卫星DNA（重复单位10–25 bp，主要存在于近端粒处和着丝粒区）、微卫星DNA（重复单位2–4 bp，串联成簇长50–100 bp，又称STR）同属串联重复序列。人的着丝粒主要由短的重复序列即α卫星DNA构成，但同样的重复序列也见于非着丝粒位置，说明它不足以单独决定着丝粒的形成。","src":"《第8章 细胞核与染色体》p39；MBoC 7e 印刷 p214","x":1},{"id":"9f711f0c","s":"c","g":"c06","n":"反式组蛋白通路","e":"trans-histone crosstalk","d":"反式组蛋白通路（trans-histone crosstalk）指不同组蛋白尾巴之间或不同核小体之间的共价修饰组合，如H2BK123单泛素化与H3K4甲基化的关系。研究表明H2BK123单泛素化对H3K4和H3K79三甲基化至关重要，这类跨组蛋白、跨核小体的修饰组合可使非活化的染色质转变为结构开放的染色质，有利于转录活化。它说明组蛋白修饰并非独立发生：同一尾部邻近残基的多个修饰构成修饰盒，而不同组蛋白之间的修饰则通过反式通路相互协同。","src":"《第8章 细胞核与染色体》p73"},{"id":"c8d3d4cc","s":"c","g":"c06","n":"基因座控制区","e":"LCR","d":"基因座控制区（locus control region, LCR）是一类远距离顺式调控元件，能使其连接的基因在异位染色质位点以组织特异、拷贝数依赖的方式表达至生理水平。LCR通常由成簇的DNase I超敏位点组成，其核心为多个转录因子的结合位点，最先在人类β-珠蛋白基因座中发现，位于珠蛋白基因上游约6–22 kb，控制珠蛋白基因的发育阶段转换。LCR通过形成DNA环使远端元件接触启动子，营造开放染色质结构。","src":"网络补充：ncbi.nlm.nih.gov（PMC2811695，Locus control regions）；wikipedia.org（Locus control region）"},{"id":"e3db395b","s":"c","g":"c06","n":"复制起点","e":"replication origin","d":"复制起点（replication origin）是DNA分子上开始复制的位置。复制起始时，起始蛋白结合于复制起点并使富含AT的序列解链，随后解旋酶被装载并激活，引物酶装载并合成RNA引物，DNA聚合酶才能起始新链合成，于是从起点向两侧形成两个移动方向相反的复制叉。原核细胞一般只有一个复制起点，为单复制子，速度快；真核细胞为多复制子，有多个复制起点，速度较慢但可同时起始。","src":"《第8章 细胞核与染色体》p100；MBoC 7e 印刷 p274"},{"id":"a0aee58b","s":"c","g":"c06","n":"外层核膜","e":"outer nuclear membrane","d":"外层核膜（outer nuclear membrane）是构成核被膜的两层同心膜之一，包围内层核膜，并与内层核膜及内质网膜相连通，因此核周间隙也与内质网腔相通。其表面常附着进行蛋白质合成的核糖体，这些核糖体合成的蛋白可被转运到内外核膜之间的核周间隙。内外膜平行排列，融合处形成核孔，核孔处镶嵌核孔复合体，实现核质间的物质交换。外层核膜与内层核膜、核周间隙共同构成核被膜这一选择性屏障。","src":"《第8章 细胞核与染色体》p3；MBoC 7e 印刷 p736"},{"id":"46dae34b","s":"c","g":"c06","n":"多线染色体","e":"polytene chromosome","d":"多线染色体（polytene chromosome）是巨大染色体的一种，主要存在于双翅目昆虫幼虫唾腺细胞中。其体积巨大源于核内有丝分裂：DNA反复复制而细胞不分裂，多达1024条同源DNA并列成线。染色体上交替分布较致密的带（band）与较疏松的间带（interband），果蝇全套多线染色体约有3700条带和3700个间带。幼虫发育某阶段，某些带区疏松膨大形成膨突（puff）或巴氏环，用H3-UdR处理证明膨突是基因活跃转录的区域。","src":"《第8章 细胞核与染色体》p114、p116；MBoC 7e 印刷 p220","x":1},{"id":"dbb1647e","s":"c","g":"c06","n":"多线染色体","e":"Polytene chromosomes","d":"多线染色体（Polytene chromosomes）由核内有丝分裂形成，主要见于双翅目昆虫幼虫的唾腺细胞：DNA复制而细胞不分裂，核内多达1024条同源DNA并列成线性排列，使染色体体积巨大。它分成交替分布的致密带（band）和疏松间带（interband），带可按粗细与间隔识别并编号。幼虫发育某阶段，部分带区疏松膨大形成膨突（puff）或巴氏环（Balbiani ring），H3-UdR标记显示膨突被标记，说明此处是基因活跃转录区。","src":"《第8章 细胞核与染色体》p114、p115、p116；MBoC 7e 印刷 p220"},{"id":"73fc722c","s":"c","g":"c06","n":"小卫星DNA","e":"minisatellite DNA","d":"小卫星DNA（minisatellite DNA）属高度重复序列中的串联重复序列，重复单位为10–25 bp，呈串联重复排列，主要存在于染色体近端粒处和着丝粒区。与之并列的还有重复单位5–100 bp、散在分布或位于着丝粒的卫星DNA，以及重复单位2–4 bp、串联成簇长度50–100 bp的微卫星DNA（又称短串联重复序列STR）。高度重复序列占人基因组的10%，小卫星DNA与上述两类共同构成按重复单位长度区分的串联重复序列家族。","src":"《第8章 细胞核与染色体》p39"},{"id":"86a9546d","s":"c","g":"c06","n":"常染色质","e":"euchromatin","d":"常染色质（euchromatin）是间期染色体中染色弥散、着色较浅的区域，即“正常”染色质，与高度凝集的异染色质相对。常染色质一般具有转录活性，其纤维结构较为疏松，便于转录因子与顺式作用元件结合以及RNA聚合酶在模板上滑动。若染色体发生断裂重接，原本常染色的区域可转变为异染色质状态，且这种沉默状态能在细胞世代间稳定遗传，形成位置效应花斑，说明染色质的状态可在染色体上扩散并被继承。","src":"MBoC 7e Glossary（PDF p1455）；MBoC 7e 印刷 p205"},{"id":"9cb2adb8","s":"c","g":"c06","n":"异染色质","e":"heterochromatin","d":"异染色质（heterochromatin）是即使在间期也高度凝集、一般无转录活性的染色质。它分两类：组成型异染色质永久凝集于基因组的许多区域，兼性异染色质则可受调控以控制基因表达，如X染色体随机失活形成的Barr体即属后者。异染色质具有自我延续的重要性质，其状态可沿染色体扩散并在细胞世代间稳定遗传，位置效应花斑即由此产生。HP1与第9位赖氨酸三甲基化的组蛋白H3结合，是异染色质形成的模型基础。","src":"《第8章 细胞核与染色体》p77、p83；MBoC 7e Glossary（PDF p1458）","x":1},{"id":"be37f54d","s":"c","g":"c06","n":"微卫星DNA","e":"microsatellite DNA, STR","d":"微卫星DNA（microsatellite DNA）又称短串联重复序列（short tandem repeats, STR），属高度重复序列，重复单位仅2–4 bp，串联成簇，簇长50–100 bp，存在于基因组间隔序列和内含子等非编码区。同类中还有重复单位5–100 bp的卫星DNA和10–25 bp的小卫星DNA，后者主要在近端粒处和着丝粒区。三者按重复单位由长到短排列，共同构成高度重复序列中的串联重复部分，约占人基因组的10%。","src":"《第8章 细胞核与染色体》p39"},{"id":"a17356bc","s":"c","g":"c06","n":"早老症","e":"Hutchinson-Gilford progeria syndrome, HGPS","d":"早老症（Hutchinson-Gilford progeria syndrome, HGPS）属核纤层蛋白病，后者是主要影响肌肉组织的遗传性疾病。其分子基础是Lamin A第11外显子点突变，导致pre-Lamin A缺失50个氨基酸，Lamin A不能正常行使功能。患者细胞核结构、异染色质异常。Lamin A成熟需金属蛋白酶Zmpste24，敲除该基因的小鼠同样出现早衰；Lamin A突变的细胞还丧失DNA损伤后的修复能力。","src":"《第8章 细胞核与染色体》p35、p36"},{"id":"85a9c693","s":"c","g":"c06","n":"染色体","e":"chromosome","d":"染色体（chromosome）是由一条很长的DNA分子与相关蛋白组成的结构，携带生物体的部分或全部遗传信息，在细胞进行有丝分裂或减数分裂时凝集成光镜下可见的棒状结构。中期染色体具有典型形态：着丝粒（主缢痕）、次缢痕、随体和端粒。其DNA含三种功能元件，即自主复制DNA序列、着丝粒DNA序列和端粒DNA序列。染色体经物理、化学因素处理后分化染色，可显示特异的带纹，用于鉴定核型中的染色体及识别片段易位等变化。","src":"《第8章 细胞核与染色体》p86、p96、p112；MBoC 7e Glossary（PDF p1449）","x":1},{"id":"77c1be31","s":"c","g":"c06","n":"染色体DNA三种功能元件","e":"","d":"染色体DNA的三种功能元件指自主复制DNA序列（ARS）、着丝粒DNA序列（CEN）和端粒DNA序列（TEL）。ARS使染色体DNA能自主起始复制；CEN保证染色体在细胞分裂时被正确分配；TEL位于染色体两端，由高度重复的富含G的短串联重复序列组成，高度保守，与蛋白质形成核蛋白复合体，是真核生物所有染色体末端特有的结构，其重复序列由端粒酶合成后添加到末端。三者共同保证染色体成为独立的复制与传递单位。","src":"《第8章 细胞核与染色体》p87、p96"},{"id":"99468a21","s":"c","g":"c06","n":"染色体显带","e":"chromosome banding","d":"染色体显带（chromosome banding）是使染色体经物理、化学因素处理后进行分化染色，特别是用荧光染料染色，从而呈现特定深浅不同带纹（band）的方法。如G带即细胞中期染色体经胰酶、去垢剂等处理后用Giemsa染料染色所显示的带型。每条染色体的带型不同，从几条到上千条不等，是染色体的特异标志，主要用于鉴定一个核型中的任何一条染色体，以及识别染色体片段的易位等变化。它是核型分析的重要基础。","src":"《第8章 细胞核与染色体》p109、p112"},{"id":"5e8cdf5d","s":"c","g":"c06","n":"染色体显带技术","e":"","d":"染色体显带技术是使染色体经物理、化学因素处理后分化染色、呈现特定深浅不同带纹的方法。以G带为例，细胞中期染色体经胰酶、去垢剂等处理后用Giemsa染料染色，即显示特定的带型；也可用荧光染料染色使带纹更清晰。每条染色体带型不同，从几条到上千条不等，是染色体的特异标志。该技术主要用于鉴定一个核型中的任何一条染色体，以及检测染色体片段的易位等变化，是核型分析中识别单条染色体、判断结构异常的基本手段。","src":"《第8章 细胞核与染色体》p112"},{"id":"853fcfef","s":"c","g":"c06","n":"染色体骨架放射环模型","e":"","d":"染色体骨架放射环模型是解释染色体高级结构的模型，其要点有三：非组蛋白构成染色体骨架，并由骨架伸出无数DNA侧环；30 nm染色线折叠成环，沿染色体纵轴由中央向四周伸出，构成放射环；放射环结合在非组蛋白骨架上形成微带，微带沿纵轴构建成染色单体。其中30 nm染色线由核小体串珠在H1参与下螺旋盘绕而成，每6个核小体绕一圈，构成外径30 nm的中空管，故该模型把核小体、30 nm纤维与染色单体三个层次联系起来。","src":"《第8章 细胞核与染色体》p54、p58"},{"id":"5c9eb53c","s":"c","g":"c06","n":"染色质","e":"chromatin","d":"染色质（chromatin）是真核细胞核内由DNA、组蛋白和非组蛋白构成的复合物，即染色体赖以形成的物质。铺展染色质的电镜观察显示，未经处理的天然染色质为30 nm纤丝，经盐溶液处理后解聚呈10 nm串珠状结构，串珠即核小体。以核小体为结构单位的染色质如何与序列特异的转录因子结合并指导mRNA合成，取决于核小体在DNA上的排列疏密、核小体间的聚合与解聚，以及组蛋白的化学修饰；有转录活性的活性染色质对DNA酶I敏感，结构疏松。","src":"《第8章 细胞核与染色体》p48、p78；MBoC 7e Glossary（PDF p1449）"},{"id":"da67075e","s":"c","g":"c06","n":"染色质四级结构","e":"","d":"染色质四级结构是染色质逐级包装成染色单体的模型。第一级为核小体：含200 bp DNA、一个组蛋白八聚体与一分子H1，146 bp DNA盘绕八聚体1.75圈，相邻核小体以约60 bp连接DNA相连。第二级为30 nm纤维：H1存在时核小体串珠螺旋盘绕，每6个核小体绕一圈，形成外径30 nm的中空管即螺线管。更高级为30 nm染色线折叠成放射环并结合于非组蛋白骨架形成微带，微带沿纵轴构建染色单体。逐级包装使极长DNA得以容纳于核内。","src":"《第8章 细胞核与染色体》p52、p54、p58"},{"id":"07cc4b30","s":"c","g":"c06","n":"核仁","e":"nucleolus","d":"核仁（nucleolus）是见于细胞核内的圆球状结构，在蛋白质合成旺盛和分裂增殖较快的细胞中较大较多，反之很小或缺失，并在分裂前期消失、重现于分裂末期。其主要功能是转录rRNA和组装核糖体亚单位；核仁组织区（NOR）定位在核仁染色体的次缢痕部位，编码18S、28S和5.8S rRNA，核仁由此产生并与之紧密相连。此外核仁还是其他非编码RNA产生及RNA-蛋白复合物组装的场所，如U6 snRNP、端粒酶和信号识别颗粒的组装。","src":"《第8章 细胞核与染色体》p120、p121、p126；MBoC 7e 印刷 p355"},{"id":"f0276d88","s":"c","g":"c06","n":"核仁周期","e":"","d":"核仁周期指核仁随细胞周期运行而发生的动态变化，其发生依赖于rDNA的转录活性和细胞周期的运行。核仁在分裂前期消失，到分裂末期又重新出现于染色体周围，间期则维持其超微结构与功能。由于核仁由核仁组织区（NOR）产生并与之紧密相连，而NOR是rDNA成簇所在，rDNA转录活性的有无与高低直接影响核仁的形成、大小与解体，因此核仁的结构与数目在细胞周期中呈规律性的周期性变化。","src":"《第8章 细胞核与染色体》p120、p126、p131"},{"id":"f424391e","s":"c","g":"c06","n":"核仁组织区","e":"nucleolar organizer region","d":"核仁组织区（nucleolar organizer region, NOR）是参与核仁形成时的染色质区，定位在核仁染色体的次缢痕部位。核仁从核仁组织区部位产生，同时与该区紧密相连。在真核生物中，NOR编码18S、28S和5.8S rRNA，是rDNA成簇分布之处。中期染色体上可见次缢痕、随体、端粒与着丝粒（主缢痕）等形态特征，NOR即位于次缢痕处。需注意NOR是染色体上的染色质区域，与核仁这一核内结构不同。","src":"《第8章 细胞核与染色体》p86、p126","x":1},{"id":"b1d2d178","s":"c","g":"c06","n":"核仁组织区","e":"nucleolar organizing region, NOR","d":"核仁组织区（nucleolar organizing region, NOR）指参与形成核仁的染色质区，定位于染色体次缢痕部位，在真核生物中编码18S、28S和5.8S rRNA。核仁从核仁组织区产生，并始终与该区紧密相连，因此NOR是核仁形成的组织者。rDNA以多拷贝串联重复序列成簇分布在少数染色体的NOR上，构成核仁并位于次缢痕区。在中期染色体形态上，NOR与随体、端粒、着丝粒（主缢痕）并列，是识别特定染色体的形态标志之一。","src":"《第8章 细胞核与染色体》p86、p125、p126"},{"id":"0be76734","s":"c","g":"c06","n":"核内有丝分裂","e":"endomitosis","d":"核内有丝分裂（endomitosis）指DNA复制后核发生分裂而细胞质不分裂，或DNA复制而细胞不分裂，导致细胞多倍化、体积增大的过程。多线染色体的巨大体积即核内有丝分裂的结果：DNA反复复制而细胞不分裂，多达1024条同源DNA并列成线。在肝脏、心肌等组织中，DNA复制后核分裂而无胞质分裂，形成多核的多倍体细胞；哺乳动物胎盘滋养层细胞经八轮核内复制，产生对母胎间组织屏障形成至关重要的巨细胞。","src":"《第8章 细胞核与染色体》p114；MBoC 7e 印刷 p1272"},{"id":"a8e7aeec","s":"c","g":"c06","n":"核周间隙","e":"perinuclear space","d":"核周间隙（perinuclear space）是内层核膜与外层核膜之间的腔隙，与内质网腔相连通。外层核膜与内质网膜连续，其上的核糖体合成的蛋白质可被转运进入核周间隙；内外两层核膜平行排列，在融合处形成核孔，核孔处镶嵌核孔复合体，成为核质之间双向运输的通道。核周间隙与内层核膜、外层核膜共同构成核被膜，把核内与胞质分开，形成天然的选择性屏障；有丝分裂前期末核膜破裂时该腔隙随之消失，末期核膜重建时又重新形成。","src":"《第8章 细胞核与染色体》p3；MBoC 7e 印刷 p736"},{"id":"9f5bd8e9","s":"c","g":"c06","n":"核型","e":"karyotype","d":"核型（karyotype）是染色体组在有丝分裂中期的表型，包括染色体的数目、大小和形态特征等，是物种特异的。把细胞的全套染色体按大小、形状和数目排列展示，即得到该细胞的核型。在测量计算的基础上进行分组、排队、配对并作形态分析，称核型分析，对探讨人类遗传病机制、研究物种亲缘关系与进化、研究细胞癌变机理都有重要意义。显带技术可依据每条染色体特异的带型，为核型中单条染色体的识别提供标志。","src":"《第8章 细胞核与染色体》p110、p112；MBoC 7e Glossary（PDF p1461）"},{"id":"fe106527","s":"c","g":"c06","n":"核型分析","e":"","d":"核型分析是在对染色体进行测量计算的基础上，进行分组、排队、配对并进行形态分析的过程。它以核型即染色体组在有丝分裂中期的表型为对象，比较染色体的数目、大小与形态特征。核型分析对于探讨人类遗传病的机制、研究物种亲缘关系与进化、研究人细胞癌变机理等都有重要意义。结合染色体显带技术，可依据每条染色体特异的带型鉴定核型中的任何一条染色体，并识别染色体片段的易位等变化。","src":"《第8章 细胞核与染色体》p110、p111、p112"},{"id":"c1c78a0b","s":"c","g":"c06","n":"核基质","e":"nuclear matrix","d":"核基质（nuclear matrix）指细胞核内主要由非组蛋白构成的精密三维纤维网架结构，与染色质的定位、复制和转录活动有关。其形态与胞质骨架很相似，又与胞质骨架体系有一定联系；细胞核经核酸酶、高盐溶液处理后留下的纤维蛋白网架即核骨架，故核骨架与核基质为同一结构，1974年被发现。它由多种非组蛋白性纤维蛋白构成，含少量RNA（0.5%）、DNA（0.8%）、磷脂（1.6%）和糖类（0.9%），并与核纤层、中间纤维相连。","src":"《第8章 细胞核与染色体》p133、p134、p135"},{"id":"013edd74","s":"c","g":"c06","n":"核孔","e":"nuclear pore","d":"核孔（nuclear pore）是内核膜与外核膜平行排列、相互融合处形成的圆形或八角形孔道，孔处镶嵌核孔复合体（NPC）。核孔复合体由胞质环（外环）、核质环（内环）、辐和中央栓等组成，是核质交换的双向亲水通道。水溶性小分子可经此自由扩散，一般小于40 000道尔顿或直径约5 nm的分子能直接通过；而大多数生物大分子体积过大，需消耗能量、经信号识别与载体介导的主动运输双向穿核。","src":"《第8章 细胞核与染色体》p3、p6、p9；MBoC 7e 印刷 p350"},{"id":"2bdfc71b","s":"c","g":"c06","n":"核孔复合体","e":"nuclear pore complex (NPC)","d":"核孔复合体（nuclear pore complex, NPC）是形成核被膜上水性通道的大型多蛋白结构，允许特定分子在核与胞质之间移动。其结构包括胞质环（外环）、核质环（内环）、辐和中央栓（transporter）。作为核质交换的双向亲水通道，它使水溶性小分子自由扩散，而对大分子进行信号识别和载体介导的主动运输：含NLS或NES的蛋白质依赖Ran经NPC进出核，被动扩散一般限于40 kDa以下，NPC的有效孔径还可被调节。","src":"《第8章 细胞核与染色体》p6、p9、p13；MBoC 7e Glossary（PDF p1467）"},{"id":"e6b6df80","s":"c","g":"c06","n":"核孔复合体","e":"nuclear pore complex, NPC","d":"核孔复合体（nuclear pore complex, NPC）是镶嵌于核孔处的复合结构，由胞质环（外环）、核质环（内环）、辐和中央栓组成，其三维构型常以切面模型描述。它位于内外核膜融合形成的核孔处，是核质交换的双向亲水通道：既允许水溶性小分子自由扩散通过，又通过信号识别与载体介导的机制完成大分子的双向主动运输。NPC还参与核被膜的解体与组装，其特有的跨膜糖蛋白gp210可作为标记，Ran及其结合蛋白参与其在染色质表面的组装。","src":"《第8章 细胞核与染色体》p3、p5、p6、p9"},{"id":"6e84ae1d","s":"c","g":"c06","n":"核定位信号","e":"NLS","d":"核定位信号（NLS）是亲核蛋白所含的进核信号，本质为一段氨基酸序列，与importin结合后介导蛋白入核。其特点是无特异保守序列、富含碱性氨基酸即Lys和Arg；在SV40的NLS中突变一个氨基酸即丧失定位功能；移植到其他蛋白序列中往往能诱导该蛋白特异入核；通常为一段连续多肽，偶尔分为两段、间隔约10个氨基酸，且可位于肽链任何区段而非限于N或C端。含NLS的蛋白仍可能因NLS被磷酸化修饰或与胞质滞留因子结合而滞留于胞质。","src":"《第8章 细胞核与染色体》p18、p20；MBoC 7e 印刷 p738","x":1},{"id":"cef6113a","s":"c","g":"c06","n":"核定位信号","e":"nuclear localization sequence, NLS","d":"核定位信号（nuclear localization sequence, NLS）是亲核蛋白含有的特殊氨基酸序列，决定其被选择性转运入核。典型NLS由一段或两段富含带正电氨基酸Lys和Arg的短序列组成，不同蛋白的具体序列各异；它无特异保守序列，突变一个氨基酸即可丧失定位功能，移植到其他蛋白上往往能诱导后者特异入核，且可位于肽链任何区段。核质蛋白的NLS不连续，分为两部分，间隔约10个氨基酸，两部分都是NLS所必需。","src":"《第8章 细胞核与染色体》p14、p15、p18"},{"id":"8b1715c5","s":"c","g":"c06","n":"核小体","e":"nucleosome","d":"核小体（nucleosome）是染色质的基本结构单位，在电镜下呈串珠状。其结构要点为：一个核小体单位含200 bp DNA、一个组蛋白八聚体和一分子H1；组蛋白八聚体构成核小体的盘状核心结构；146 bp DNA盘绕八聚体1.75圈，H1在核心颗粒外锁住核小体DNA的进出端以稳定核小体；相邻核小体之间以连接DNA相连，典型长度约60 bp。核小体在DNA上的排列疏密由染色质重塑酶催化，其构型变化与组蛋白修饰直接影响染色质活性。","src":"《第8章 细胞核与染色体》p52、p65；MBoC 7e 印刷 p198"},{"id":"bfc7273b","s":"c","g":"c06","n":"核纤层","e":"nuclear lamina","d":"核纤层（nuclear lamina）是核膜内侧由A、B、C三种核纤层蛋白（lamin）相互交织形成的纤维网络结构，属V类中间纤维。它为核膜和染色质提供结构支架，保持细胞核的形态；在细胞分裂中通过周期性的磷酸化和去磷酸化而解聚和重建，参与核膜的组装与去组装；结构异常还会影响转录。核纤层与核膜、染色质、核孔复合体以及核骨架、穿过核被膜的中间纤维相连，形成贯穿核与质的连续网络结构。","src":"《第8章 细胞核与染色体》p29、p30、p34；MBoC 7e Glossary（PDF p1467）","x":1},{"id":"bfb66c48","s":"c","g":"c06","n":"核纤层蛋白B受体","e":"Lamin B receptor, LBR","d":"核纤层蛋白B受体（Lamin B receptor, LBR）是位于内层核膜上的蛋白，介导内核膜与核纤层之间的连接。内层核膜光滑、无核糖体，内贴核纤层，二者即借助LBR等蛋白相连。在核被膜解体后的重新组装中，富含LBR的膜泡与富含核孔复合体特有跨膜糖蛋白gp210的膜泡参与核膜形成：单层小泡先附着于染色质表面，排列并相互融合形成双层膜，Ran GTP酶及其结合蛋白参与膜泡在染色质表面的募集、融合和核孔复合物组装。","src":"《第8章 细胞核与染色体》p3、p5"},{"id":"0b513bb4","s":"c","g":"c06","n":"核纤层蛋白病","e":"laminopathies","d":"核纤层蛋白病（laminopathies）是主要由核纤层蛋白基因突变引起、主要影响肌肉组织的遗传性疾病，包括早老症（Hutchinson-Gilford progeria syndrome）。多数与A型核纤层蛋白的突变版本相关，表现为组织特异的疾病；骨骼与心脏异常可用核被膜削弱导致细胞损伤和死亡来解释，也有观点认为其源于致病性的、组织特异的基因表达改变。A型核纤层蛋白与多种核被膜蛋白一起，是控制转录、染色质组织和信号转导的蛋白质支架。","src":"《第8章 细胞核与染色体》p35；MBoC 7e 印刷 p1011"},{"id":"8876d572","s":"c","g":"c06","n":"核膜","e":"nuclear envelope","d":"核膜（nuclear envelope）是包围细胞核的双层膜结构，由外层核膜、内层核膜和核周间隙构成，内外膜平行，融合处形成核孔，核孔处镶嵌核孔复合体。外层核膜与内质网相通并常带核糖体，内层核膜光滑、内贴核纤层，核周间隙连着内质网腔。核膜是天然的选择性屏障，负责核质间的物质交换与信息交流。有丝分裂前期末双层核膜破裂，末期又围绕染色体重新形成；新核膜来自旧核膜，单层小泡膜也在染色质表面融合参与形成。","src":"《第8章 细胞核与染色体》p3、p5；MBoC 7e Glossary（PDF p1467）"},{"id":"9dd1349f","s":"c","g":"c06","n":"核质交换的双向性亲水通道","e":"","d":"核孔复合体的功能是作为核质交换的双向性亲水通道。水溶性小分子可自由扩散通过；大分子则经信号识别和载体介导的过程进行主动运输，该方式更有效，如每个核孔每分钟可运输100个组蛋白或3个核糖体亚基，能转运比被动扩散更大的分子颗粒（可达26 nm），并消耗GTP，NPC的有效孔径还可能被调节。因此核孔复合体既允许小分子快速交换，又保证蛋白质、RNA等大分子有选择地、双向地穿核。","src":"《第8章 细胞核与染色体》p9、p13；MBoC 7e 印刷 p350"},{"id":"62bcfd05","s":"c","g":"c06","n":"核质蛋白","e":"nucleoplasmin","d":"核质蛋白（nucleoplasmin）是存在于爪蟾卵母细胞核中的蛋白，因注射实验而被用于证明核定位信号的存在。它是一个大的五聚体蛋白，参与染色质装配：促进组蛋白与DNA的相互作用，同时避免DNA与组蛋白因强静电吸引而形成非特异的不可溶聚合物，本身并不参与核小体组成。实验中把完整蛋白、头部、尾部或带单一尾部的头部注入蛙卵母细胞的胞质或核内，除头部外各形式都能在核内积累，说明尾部含NLS，且入核是逆浓度梯度的主动运输。","src":"《第8章 细胞核与染色体》p15、p18；MBoC 7e 印刷 p747"},{"id":"45dc9bbd","s":"c","g":"c06","n":"核输出信号","e":"NES","d":"核输出信号（nuclear export signal, NES）是蛋白因子本身含有的出核信号。需要出核的蛋白质通过NES被相应的输出受体识别，经核孔复合体运出核外。RNA的出核同样依赖信号与蛋白因子：rRNA在核仁中合成、形成核糖体亚基后才被运出核外；5S rRNA与tRNA由蛋白介导出核；hnRNA需加帽、加尾、剪接并与多种RNA结合蛋白形成RNP复合体后才能出核。上述过程属信号识别与载体介导的双向主动运输，消耗GTP。","src":"《第8章 细胞核与染色体》p13、p26","x":1},{"id":"5db7a750","s":"c","g":"c06","n":"核输出信号","e":"nuclear export signal, NES","d":"核输出信号（nuclear export signal, NES）是蛋白因子本身所含有的出核信号，介导其经核孔复合体向核外运输。核孔复合体是核质交换的双向亲水通道，大分子的穿核是信号识别和载体介导的过程，消耗GTP，并可转运直径达26 nm的颗粒。含NES的蛋白被输出受体识别后出核；RNA的运出也依赖类似的信号与蛋白因子，如rRNA需在核仁中组装成核糖体亚基、hnRNA需加工为RNP复合体后才能出核。","src":"《第8章 细胞核与染色体》p13、p26"},{"id":"500b6f5a","s":"c","g":"c06","n":"核骨架","e":"nuclear skeleton","d":"核骨架（nuclear skeleton）即核基质，是细胞核经核酸酶、高盐溶液处理后留下的纤维蛋白网架，1974年被发现，形态类似细胞骨架。它与核纤层、中间纤维相互连接，形成贯穿核与质的独立结构系统。除维持核形态，核骨架是基因转录、加工的场所，具RNA聚合酶结合位点，基因只有结合在核骨架上才能转录，加入MAR序列可增强基因表达；它还参与染色体构建，30 nm染色质纤维结合于核骨架，分裂期进一步包装为染色体，并与病毒复制、加工和装配有关。","src":"《第8章 细胞核与染色体》p134、p135、p140"},{"id":"8404d3e4","s":"c","g":"c06","n":"次缢痕","e":"secondary constriction","d":"次缢痕（secondary constriction）是中期染色体上主缢痕以外的缢缩部位，核仁组织区（NOR）即位于此处。中期染色体具有着丝粒（主缢痕）、次缢痕、随体和端粒等形态特征，随体见于13、14、15、21、22号染色体。rDNA以多拷贝串联重复序列成簇分布在少数染色体的NOR上，构成核仁并位于次缢痕区，故次缢痕可作为识别含NOR染色体的形态标志。真核生物中5S rRNA基因不定位在NOR上。","src":"《第8章 细胞核与染色体》p86、p125、p126"},{"id":"0f6c9aa3","s":"c","g":"c06","n":"活性染色质","e":"active chromatin","d":"活性染色质（active chromatin）指在功能上具有转录活性的那部分染色质，只占基因总数的10%以下，其对DNA酶I敏感，是区别于非活性染色质的标志。转录发生时，其核小体构象发生改变，呈现疏松的染色质结构，核心组蛋白变形或解体，使DNA分子展开，从而便于转录因子与顺式作用元件结合，也便于RNA聚合酶在模板上滑动。在修饰特征上，活性染色质表现为H3的N端第4位Lys甲基化、第9和14位Lys的乙酰化以及第10位Ser的磷酸化。","src":"《第8章 细胞核与染色体》p78；《第8章 细胞核与染色体》p71"},{"id":"18ac1cba","s":"c","g":"c06","n":"活性染色质","e":"","d":"活性染色质指处于转录活跃状态的染色质，占基因总数不足10%，其最常用的检测特征是对DNA酶I消化敏感，红细胞中的血红蛋白基因、输卵管细胞中的卵白蛋白基因即属此类。由于核小体构象改变、核心组蛋白变形或解体，DNA得以展开，染色质呈疏松状态，转录因子易于结合顺式作用元件，RNA聚合酶也易于沿模板移动。与之相对，非活性染色质不具有转录活性，其H3第9位Lys是甲基化而不是乙酰化。","src":"《第8章 细胞核与染色体》p78；《普通班作业汇总》p4"},{"id":"7f2ecf74","s":"c","g":"c06","n":"灯刷染色体","e":"lampbrush chromosome","d":"灯刷染色体（lampbrush chromosome）是见于鱼类、两栖类和爬行类卵母细胞减数分裂双线期的一种巨大染色体，因形似灯刷而得名，而双线期正是卵黄合成与卵母细胞预存mRNA合成的旺盛时期。每条染色体由一条很长的DNA双螺旋与姐妹DNA双螺旋相连而成，大部分DNA位于两条染色单体的连接处，高度浓缩且无转录活性，起把染色单体组织到线性染色体轴上的作用；高度转录的区域则以巨大的染色质环从轴伸出，环长可达数万至数十万个核苷酸对。","src":"《第8章 细胞核与染色体》p117；MBoC 7e 印刷 p218","x":1},{"id":"fa41a5e3","s":"c","g":"c06","n":"着丝粒","e":"centromere","d":"着丝粒（centromere）是中期染色体上连接两条姐妹染色单体的缢缩部位，又称主缢痕，也是动粒装配、捕获纺锤体微管的位点。动粒位于着丝粒外表面，由内板、中间间隙、外板和纤维冠组成，有丝分裂中期与纺锤体微管相连，是染色体的运动中心。酿酒酵母着丝粒含CDE-I、CDE-II和CDE-III三种序列，CDE-III点突变即可使着丝粒完全失活。复杂生物的着丝粒多由alpha卫星DNA组成，但该序列也见于非着丝粒区，说明其形成更依赖蛋白装配。","src":"《第8章 细胞核与染色体》p92；《第8章 细胞核与染色体》p94；MBoC 7e 印刷 p214","x":1},{"id":"0883cafe","s":"c","g":"c06","n":"着丝粒DNA序列","e":"centromere DNA sequence, CEN","d":"着丝粒DNA序列（centromere DNA sequence，CEN）是染色体为完成复制、保持完整并均等分配所必需的三种功能元件之一。在酿酒酵母中，着丝粒区含CDE-I、CDE-II和CDE-III三种序列，其中CDE-I与CDE-II可能与着丝粒功能关系不大，而CDE-III的CCG发生点突变即可使着丝粒完全失活，因此它可能是与纺锤丝结合的识别位点。ARS、CEN与TEL组合即构成酵母人工染色体（YAC）的基础。","src":"《第8章 细胞核与染色体》p87；《第8章 细胞核与染色体》p92"},{"id":"9a3ec899","s":"c","g":"c06","n":"端粒","e":"telomere","d":"端粒（telomere）是真核生物线性染色体两端由高度重复、富含G的短串联重复序列与蛋白质共同形成的核蛋白复合体，序列高度保守，人的重复单位为TTAGGG。它可补偿DNA复制时5′末端在消除RNA引物后留下的空缺，抵消染色体随每轮复制而缩短的趋势；其重复序列并非由染色体DNA复制连续合成，而由端粒酶添加。端粒还须与意外断裂相区别，细胞用特殊核酸酶切去5′端，留下突出的单链3′端，以免端粒被当作断裂去修复而产生染色体融合。","src":"《第8章 细胞核与染色体》p96；《第8章 细胞核与染色体》p98；MBoC 7e 印刷 p282","x":1},{"id":"3ff59b4e","s":"c","g":"c06","n":"端粒DNA序列","e":"telomere DNA sequence, TEL","d":"端粒DNA序列（telomere DNA sequence，TEL）是染色体三种功能元件之一，与自主复制DNA序列、着丝粒DNA序列并列，为染色体能够复制、保持完整并均等分配所必需。它位于染色体两端，由高度重复、富含G的短串联重复序列组成，高度保守，并与蛋白质结合成核蛋白复合体。端粒的重复序列不是在染色体DNA复制时连续合成的，而是由端粒酶合成后添加到染色体末端，因而可补偿5′端消除RNA引物造成的空缺。","src":"《第8章 细胞核与染色体》p87；《第8章 细胞核与染色体》p96"},{"id":"c1ade733","s":"c","g":"c06","n":"端粒酶","e":"telomerase","d":"端粒酶（telomerase）是一种核糖核蛋白（RNP），由RNA和相关蛋白组成，存在于生殖细胞和部分干细胞中，具有反转录酶性质。它以自身携带的RNA为模板，逆转录合成端粒DNA并添加于染色体末端，从而维持端粒长度的稳定，补偿DNA复制时5′末端消除RNA引物后造成的空缺，因而被视为细胞分裂的计数器。在人细胞中，端粒酶只表达于性细胞，体细胞中几乎没有，故体细胞存在增殖极限；而在约90%的癌变细胞中端粒酶被激活，使端粒得以维持。","src":"《第8章 细胞核与染色体》p98；《第8章 细胞核与染色体》p99；MBoC 7e 印刷 p281","x":1},{"id":"90feeb9d","s":"c","g":"c06","n":"组蛋白","e":"histone","d":"组蛋白（histone）是真核生物染色体的基本结构蛋白，富含带正电荷的Arg和Lys等碱性氨基酸，属碱性蛋白质，能与DNA非特异性紧密结合。核小体组蛋白H2A、H2B、H3和H4帮助DNA卷曲，形成稳定的核小体结构，它们没有种属及组织特异性，在进化上十分保守；H1则在构成核小体时起连接作用，具有种属和组织特异性。每种核心组蛋白中都有五分之一以上的氨基酸为Lys或Arg，其正电荷可中和DNA骨架的负电荷。","src":"《第8章 细胞核与染色体》p40；MBoC 7e 印刷 p199","x":1},{"id":"9b9a40b2","s":"c","g":"c06","n":"组蛋白乙酰化","e":"histone acetylation","d":"组蛋白乙酰化（histone acetylation）是发生在组蛋白赖氨酸残基上的一种共价修饰，活跃转录的基因其组蛋白一般处于乙酰化状态。乙酰化降低了赖氨酸侧链的正电荷，使组蛋白与DNA之间的相互作用减弱，结构趋于开放；它还能抑制核小体的聚缩，调控核小体的可移动性，使RNA聚合酶II更容易接近DNA。该修饰由组蛋白乙酰转移酶催化，并由组蛋白去乙酰化酶逆转，两者共同决定某一染色质区域的乙酰化水平，从而参与基因转录的激活与关闭。","src":"《第8章 细胞核与染色体》p72；MBoC 7e 印刷 p421"},{"id":"5732ee7f","s":"c","g":"c06","n":"组蛋白密码","e":"histone code","d":"组蛋白密码（histone code）指组蛋白N端尾部多种共价修饰的组合所携带的调控信息。修饰方式包括乙酰化、磷酸化、甲基化、泛素化和SUMO化等，它们并非独立发生，而可在特定组蛋白尾部的邻近残基上形成修饰盒，或在不同组蛋白尾巴之间形成反式组蛋白通路，例如H2B第123位Lys单泛素化对H3第4位Lys甲基化至关重要。活性染色质常为H3第4位Lys甲基化、第9和14位Lys乙酰化，非活性染色质则为H3第9位Lys甲基化。","src":"《第8章 细胞核与染色体》p71；《第8章 细胞核与染色体》p73"},{"id":"b3ef06f2","s":"c","g":"c06","n":"细胞核","e":"nucleus","d":"细胞核（nucleus）是真核细胞储存遗传信息并进行基因转录的细胞器，其结构组成包括核被膜与核孔复合体、染色质、染色体、核仁和核基质。人细胞46条染色体的DNA若首尾相接长约2米，而容纳它们的核直径仅约6微米，相当于把40公里长的细线装进一个网球；这一包装由与DNA结合的专一性蛋白完成，它们把DNA折叠成有组织的螺旋与襻环，既避免缠结，又保持其可被酶接近。核被膜上的核孔复合体则介导亲核蛋白等大分子的核质交换。","src":"《第8章 细胞核与染色体》p2；MBoC 7e 印刷 p190"},{"id":"3b19918d","s":"c","g":"c06","n":"膨突","e":"puff, Balbiani ring","d":"膨突（puff）又称巴氏环（Balbiani ring），是多线染色体在幼虫发育某一阶段出现的形态学特征：某些带区疏松膨大，形成光镜下可见的膨突。多线染色体由大量染色质线平行排列而成，横向有带区（B）与间带（IB）之分，膨突即发生于特定带区。用H3-UdR处理细胞后发现膨突被标记，说明该处正在进行活跃的RNA合成，因此膨突是基因活跃转录的区域，可作为在光镜下直接观察基因活动与染色质结构变化的材料。","src":"《第8章 细胞核与染色体》p116"},{"id":"0a0f2c6b","s":"c","g":"c06","n":"自主复制DNA序列","e":"autonomously replicating sequence, ARS","d":"自主复制DNA序列（autonomously replicating sequence，ARS）是染色体DNA的三种功能元件之一，本质上是复制起始位点序列，确保染色体在细胞周期中能够自我复制。酵母的ARS元件是一段11~14 bp富含AT的共有序列及其上下游各200 bp左右的区域，其中含起始识别复合物（ORC）的结合部位，而ORC是一组结合在复制起点上的蛋白。它与CEN、TEL组合，即构成酵母人工染色体（YAC）的基础。","src":"《第8章 细胞核与染色体》p87；《第8章 细胞核与染色体》p89"},{"id":"c5533438","s":"c","g":"c06","n":"螺旋-转角-螺旋","e":"helix-turn-helix","d":"螺旋-转角-螺旋（helix-turn-helix）是非组蛋白中一种常见的DNA结合结构模式，与锌指结构、亮氨酸拉链、螺旋-环-螺旋基序和HMG框基序并列。其基本特征是由两段α螺旋通过一个转角相连，其中一段作为识别螺旋伸入DNA分子的主沟，识别特异碱基序列。含同源框的基因所编码的蛋白即形成这一结构：这类基因含高度保守的180 bp同源框，启动基因表达，在胚胎发育中对组织和器官的形成起重要调控作用，其突变可使某一器官在发育过程中异位生长。","src":"《第8章 细胞核与染色体》p42；《第8章 细胞核与染色体》p43；《第11章 细胞分化与基因表达调控》p43"},{"id":"5cdfb793","s":"c","g":"c06","n":"螺线管","e":"solenoid","d":"螺线管（solenoid）是30 nm染色质纤维的一种经典结构模型。以往的学说认为，在组蛋白H1存在的情况下，直径约11 nm的核小体串珠结构进一步螺旋盘绕，每6个核小体绕一圈，构成外径约30 nm的中空管，即螺线管。该模型中相邻核小体的组蛋白核心依次相互作用，核小体沿螺旋逐个上升，因而螺线管模型又被称为单向螺线管模型。它说明了10 nm纤维如何进一步压缩为30 nm纤维，是染色质高级结构组装的重要环节。","src":"《第8章 细胞核与染色体》p54；《第8章 细胞核与染色体》p55"},{"id":"eca5f25e","s":"c","g":"c06","n":"起始识别复合物","e":"origin recognition complex, ORC","d":"起始识别复合物（origin recognition complex，ORC）是一组结合在复制起点上的蛋白，其结合部位位于自主复制DNA序列（ARS）之内。在酿酒酵母中，ARS是一段11~14 bp富含AT的共有序列及其上下游各约200 bp的区域，ORC即结合于此，成为起点选择的平台。在细胞周期的G1期，ORC与Cdc6、Cdt1共同把Mcm解旋酶装载到起点上，完成复制前复合物的组装，为S期DNA复制的起始做好准备。","src":"《第8章 细胞核与染色体》p89；《第10章 细胞分裂与细胞周期(下)》p90"},{"id":"2436e4cf","s":"c","g":"c06","n":"锌指结构","e":"zinc finger","d":"锌指结构（zinc finger）是非组蛋白中一类重要的DNA结合结构模式，因外形似手指而得名。其基本单元由Cys和His残基与Zn2+配位结合，把一段氨基酸环固定成指状结构，多个指状单元可串联排列。锌指以β折叠和α螺旋伸入DNA分子的主沟，与特定碱基序列发生特异性接触，从而识别靶序列。它与螺旋-环-螺旋蛋白同属DNA识别蛋白的典型模式，广泛参与真核细胞基因表达的调控。","src":"《第8章 细胞核与染色体》p42；《第8章 细胞核与染色体》p44；MBoC 7e 印刷 p405"},{"id":"28971e29","s":"c","g":"c06","n":"随体","e":"satellite","d":"随体（satellite）是中期染色体上的一种形态结构，位于次缢痕的远端，呈小的球状或棒状突出。在人类染色体中，随体见于13、14、15、21和22号染色体，这些染色体的短臂末端先有次缢痕，次缢痕处即核仁组织区（NOR），其外侧所附的小体便是随体。随体经次缢痕与核仁组织区相连，与核仁的形成密切相关，并可作为识别上述近端着丝粒染色体的形态学标志，在核型分析中据此区分染色体。","src":"《第8章 细胞核与染色体》p86"},{"id":"9fe4fe48","s":"c","g":"c06","n":"非组蛋白","e":"non-histone protein","d":"非组蛋白（non-histone protein）是染色质中与组蛋白相对的一类蛋白，多为序列特异性（相对的）DNA结合蛋白，能识别特异的DNA序列。它们具有多样性和异质性，约占染色体蛋白的60%~70%，包括参与核酸代谢和修饰的酶类、核质蛋白、染色体骨架蛋白以及基因表达调控蛋白等；与只在S期合成的组蛋白不同，非组蛋白在整个细胞周期中都进行合成。其功能是帮助DNA折叠、协助DNA复制和调节基因表达，在骨架放射环模型中还构成染色体骨架。","src":"《第8章 细胞核与染色体》p41；《第8章 细胞核与染色体》p58"},{"id":"99e01a68","s":"c","g":"c06","n":"非组蛋白","e":"nonhistone","d":"非组蛋白（nonhistone）指染色体中除组蛋白以外的蛋白质，一般作为序列特异性DNA结合蛋白发挥作用。其特点为：种类繁多、异质性强，占染色体蛋白的60%~70%；在整个细胞周期中持续合成，而组蛋白仅于S期合成；能识别特异的DNA序列。按功能包括核酸代谢与修饰酶类、核质蛋白、染色体骨架蛋白和基因表达调控蛋白。它们帮助DNA折叠、协助DNA复制并调节基因表达，其结合DNA常借助螺旋-转角-螺旋、锌指、亮氨酸拉链和HMG框等模式。","src":"《第8章 细胞核与染色体》p41；《第8章 细胞核与染色体》p42"},{"id":"acb5c3ab","s":"c","g":"c06","n":"骨架放射环结构","e":"","d":"骨架放射环结构是解释染色体高级组装的一种模型，与四级结构模型并列。该模型认为，染色体中央有由非组蛋白构成的骨架，骨架向四周伸出无数DNA侧环：30 nm染色线先折叠成环，再沿染色体纵轴由中央向四周伸出，构成放射环；放射环结合在非组蛋白骨架上形成微带，微带再沿纵轴构建成染色单体。它把染色质纤维的局部折叠与染色体整体形态联系起来，说明DNA如何被有序压缩并有条理地组织进染色单体之中。","src":"《第8章 细胞核与染色体》p58"},{"id":"10c3ac54","s":"c","g":"c09","n":"GAP","e":"GAP","d":"GAP即GTPase促进蛋白（GTPase-accelerating protein），是G蛋白开关循环中的一类辅助蛋白。多数G蛋白自身具有水解GTP的能力，但这一能力较弱，与特异的GAP结合后可大大加快。GAP通过刺激G蛋白水解其结合的GTP，使G蛋白由活化状态转为GDP结合的失活状态，因此起关闭开关的作用。以Ras为例，其GTPase活性很弱，可在活化状态维持约30分钟，而GAP可使其GTP水解速率提高约105倍。","src":"《第9章 2021细胞通讯和信号转导》p20；《第9章 2021细胞通讯和信号转导》p78"},{"id":"d5cb437b","s":"c","g":"c09","n":"GDI","e":"GDI","d":"GDI即鸟苷酸解离抑制蛋白（guanine nucleotide-dissociation inhibitor），是G蛋白开关循环中的负向调节蛋白。它通过与G蛋白结合，抑制其上所结合GDP的释放，使G蛋白维持在GDP结合的非活化状态，从而阻止G蛋白被上游信号重新激活。GDI的作用与GEF正好相反：GEF促使GDP解离、让GTP结合而使G蛋白开启，GDI则把G蛋白保持在关闭构象，因而在Rab等G蛋白的循环中起调节作用。","src":"《第9章 2021细胞通讯和信号转导》p19；《第9章 2021细胞通讯和信号转导》p20；MBoC 7e 印刷 p761"},{"id":"694cd4b5","s":"c","g":"c09","n":"GEF","e":"GEF","d":"GEF即鸟苷酸交换因子（guanine nucleotide-exchange factor），是G蛋白开关循环中的正向调节蛋白。失活的G蛋白结合GDP，只有把GDP换为GTP才能转为活化状态；GEF的作用正是结合于失活状态的G蛋白，促使其所结合的GDP解离，让GTP取而代之，把G蛋白开启。在RTK-Ras通路中，接头蛋白GRB2把Sos招募到活化的受体处，Sos与Ras结合并催化GDP/GTP交换，使Ras由关闭转为开启。","src":"《第9章 2021细胞通讯和信号转导》p20；《第9章 2021细胞通讯和信号转导》p79"},{"id":"2a3af568","s":"c","g":"c09","n":"GRB2","e":"GRB2","d":"GRB2即生长因子受体结合蛋白2，是RTK-Ras通路中的接头蛋白。它含一个SH2结构域和两个SH3结构域，前者识别并结合活化受体酪氨酸激酶上特异的磷酸酪氨酸残基，后者与Sos结合。GRB2本身不具催化活性，其功能仅在于把其他蛋白连接成复合物：当配体结合RTK并把Grb2-Sos招募到质膜内侧后，Sos得以靠近Ras并催化其GDP/GTP交换，从而活化Ras。在整联蛋白经FAK传递的信号中，同样有Grb2→Sos→Ras这一环节。","src":"《第9章 2021细胞通讯和信号转导》p77；《第9章 2021细胞通讯和信号转导》p79"},{"id":"c1619e5a","s":"c","g":"c09","n":"GRK","e":"GRK","d":"GRK即G蛋白偶联受体激酶（GPCR kinase），是一类专门磷酸化G蛋白偶联受体的激酶，家族中包括参与视杆细胞光受体脱敏的视紫红质激酶。GPCR的C端富含Ser和Thr，正是GRK的作用位点；GRK在受体上磷酸化多个Ser和Thr，但只在配体结合、受体被激活之后才起作用，因为正是活化状态的受体对GRK发生变构激活。被GRK磷酸化的受体随即与抑制蛋白家族成员高亲和结合，从而阻断与G蛋白的偶联，实现受体脱敏。","src":"《第9章 2021细胞通讯和信号转导》p47；《第9章 2021细胞通讯和信号转导》p120；MBoC 7e 印刷 p910"},{"id":"7cf69815","s":"c","g":"c09","n":"IP3受体","e":"IP3 receptor","d":"IP3受体（IP3 receptor）是位于光面内质网膜上的大型跨膜Ca2+通道，在无IP3时处于关闭状态。IP3为水溶性分子，由质膜扩散至内质网并与之结合，引起构象改变，暴露出高亲和力的Ca2+结合位点；静息时胞质Ca2+浓度虽低，仍足以使部分受体结合Ca2+。IP3与Ca2+同时结合才能使通道开放，内质网储存的Ca2+释放入胞质，又可结合其他已结合IP3的受体，引起广泛的Ca2+释放乃至钙波；而局部过高的Ca2+最终使受体失活。","src":"《第9章 2021细胞通讯和信号转导》p65；MBoC 7e 印刷 p898"},{"id":"ade367ac","s":"c","g":"c09","n":"JAK-STAT信号通路","e":"Jak-STAT signaling pathway","d":"JAK-STAT信号通路（Jak-STAT signaling pathway）是细胞因子及某些激素激活的、从质膜直达细胞核以改变基因转录的快速通路。JAK是一类胞质酪氨酸激酶，包括Jak1、Jak2、Jak3和Tyk2，各自与特定的细胞因子受体结合；配体结合受体后，JAK被激活并磷酸化一组处于潜伏状态的基因调控蛋白STAT。STAT含SH2结构域，被磷酸化后离开受体、彼此结合成复合物并转入核内，结合靶基因的调控序列而刺激转录。","src":"《第9章 2021细胞通讯和信号转导》p87；《第9章 2021细胞通讯和信号转导》p88"},{"id":"ebbbe44f","s":"c","g":"c09","n":"MAPK信号转导途径","e":"Mitogen-activated protein kinase pathway","d":"MAPK信号转导途径（mitogen-activated protein kinase pathway）是由有丝分裂原激活的蛋白激酶构成的磷酸化级联，核心为MAPKKK→MAPKK→MAPK三级激酶依次磷酸化并激活。哺乳类已鉴定出多种MAPKKK、MAPKK和MAPK，众多组合使同一模块可介导增殖、分化、防御等反应。活化的Ras开启该途径，信号逐级下传；MAPK作为丝氨酸/苏氨酸激酶磷酸化靶蛋白，改变其活性或基因表达，引起细胞增殖。","src":"《第9章 2021细胞通讯和信号转导》p27；《第9章 2021细胞通讯和信号转导》p80"},{"id":"728a045b","s":"c","g":"c09","n":"Notch/Delta信号通路","e":"Notch/Delta signaling pathway","d":"Notch/Delta信号通路（Notch/Delta signaling pathway）是接触依赖性的细胞间通讯方式，在发育中决定细胞命运。相邻细胞的Delta与Notch结合后，信号细胞启动对Delta的内吞，把Notch胞外域展平，暴露出ADAM10的切割位点；切下的胞外域仍与Delta结合并随之内吞。残余的跨膜片段再被四蛋白的γ-secretase复合体在膜内切割，释放Notch胞内段，后者入核调控基因转录。","src":"《第9章 2021细胞通讯和信号转导》p7"},{"id":"abb22880","s":"c","g":"c09","n":"PKG","e":"PKG","d":"PKG即cGMP依赖性蛋白激酶（cGMP-dependent protein kinase）。cGMP与之结合后使其活化，活化的PKG使靶蛋白上的丝氨酸或苏氨酸残基磷酸化，从而激活靶蛋白，把信号继续向下游传递。在NO-cGMP通路中，一氧化氮激活鸟苷酸环化酶使GTP生成cGMP，cGMP再激活PKG，引起血管平滑肌舒张等反应。cGMP可被cGMP特异的磷酸二酯酶降解，故抑制该酶能提高cGMP水平，西地那非即属这类抑制剂。","src":"《第9章 2021细胞通讯和信号转导》p40"},{"id":"bd2cbc8b","s":"c","g":"c09","n":"RGS","e":"RGS","d":"RGS即G蛋白信号调节子（regulator of G protein-signaling），是异三聚体G蛋白通路的负向调节蛋白。Gα亚基具GTPase活性，能把结合的GTP水解为GDP而自行关闭，但通常需要另一蛋白参与才能加快，该蛋白可以是效应蛋白，也可以是特异的G蛋白信号调节子。RGS蛋白作为α亚基特异的GTPase促进蛋白，与活化态Gα结合并显著提高其水解GTP的速率，从而关闭G蛋白介导的信号。","src":"《第9章 2021细胞通讯和信号转导》p19；MBoC 7e 印刷 p894"},{"id":"533a7744","s":"c","g":"c09","n":"Ras蛋白","e":"Ras protein","d":"Ras蛋白（Ras protein）是小G蛋白家族成员，分布于质膜胞质一侧，属于分子开关蛋白，在信号由受体传向细胞核的过程中发挥重要作用。Ras自身GTPase活性很弱，可在GTP结合的活化状态维持约30分钟；GEF促其释放GDP而开启，GAP则使其水解GTP的速率提高约105倍而关闭。活化的Ras进一步激活MAPK磷酸化级联。约30%的人类肿瘤存在Ras基因突变，Ras-GAP基因NF1的突变则引起神经纤维瘤1型。","src":"《第9章 2021细胞通讯和信号转导》p77；《第9章 2021细胞通讯和信号转导》p78；《第9章 2021细胞通讯和信号转导》p80"},{"id":"7941638f","s":"c","g":"c09","n":"SH2结构域","e":"Src homology 2 domain","d":"SH2结构域（Src homology 2 domain）是蛋白质模式结合域的一种，约由100个氨基酸残基组成，本身不具酶活性，但能特异性结合围绕磷酸酪氨酸（p-Tyr）残基的氨基酸序列。这类模块与识别对象的亲和性较弱，因而有利于快速、反复地进行精细的组合式网络调控。在受体酪氨酸激酶信号中，活化受体胞内段自磷酸化产生的磷酸酪氨酸成为SH2结构域的停泊位点，含SH2的蛋白如接头蛋白GRB2、PI3K的p85调节亚基借此被招募到质膜。","src":"《第9章 2021细胞通讯和信号转导》p34；《第9章 2021细胞通讯和信号转导》p82"},{"id":"b2ab1bf2","s":"c","g":"c09","n":"SMAD","e":"SMAD","d":"SMAD是一类胞内基因调控蛋白，TGF-β超家族的信号即经受体丝氨酸/苏氨酸激酶与SMAD传递。这类受体主要结构特征为1个跨膜区和1个细胞内的丝氨酸/苏氨酸激酶结构域，配体结合后受体磷酸化自身，随即招募并激活胞质中的SMAD；被激活的SMAD与受体解离，再与其他SMAD结合成复合物，复合物迁移入核，刺激特定靶基因的转录。smads本身也属原癌基因之列，其异常与细胞生长失控有关。","src":"《第9章 2021细胞通讯和信号转导》p85；《第14章 癌细胞》p22"},{"id":"fb854a9c","s":"c","g":"c09","n":"Sos","e":"Sos","d":"Sos（son of sevenless）是Ras的鸟苷酸交换因子，即Ras-GEF，负责把Ras由关闭状态开启。它通过SH3结构域与接头蛋白GRB2结合，借助GRB2的SH2结构域停靠在活化受体的磷酸酪氨酸上，被招募到质膜内侧。Sos靠近膜上的Ras后与之结合，催化GDP/GTP交换，使Ras转为GTP结合的活化构象，进而激活下游MAPK级联。整联蛋白经FAK传递的信号同样沿FAK→Grb2→Sos→Ras的路线进行。","src":"《第9章 2021细胞通讯和信号转导》p77；《第9章 2021细胞通讯和信号转导》p79"},{"id":"dd9975e9","s":"c","g":"c09","n":"一氧化氮","e":"nitric oxide, NO","d":"一氧化氮（nitric oxide，NO）是一种较小的生物活性气体分子，可自由穿过细胞膜，直接作用于细胞内的靶分子，并以相对特异的方式控制多种细胞功能。在内皮细胞中，乙酰胆碱等刺激使NO生成，NO扩散至邻近的平滑肌细胞，激活鸟苷酸环化酶使GTP生成cGMP，cGMP再激活PKG，最终引起血管平滑肌舒张。硝酸甘油之所以能缓解心绞痛，正是因其在体内可释放NO，走的是同一条一氧化氮／环鸟苷酸途径。NO由精氨酸转变生成，同时产生瓜氨酸。","src":"《第9章 2021细胞通讯和信号转导》p36；《第9章 2021细胞通讯和信号转导》p38"},{"id":"536f0f0e","s":"c","g":"c09","n":"一氧化氮合酶","e":"nitric oxide synthase, NOS","d":"一氧化氮合酶（nitric oxide synthase，NOS）是以L-精氨酸为底物、依赖NADPH和氧生成NO的氧化还原酶，反应中精氨酸被氧化，同时释放等量的瓜氨酸。哺乳动物主要有三种同工酶：神经元型nNOS（NOS1）与内皮型eNOS（NOS3）在正常状态下表达、活性依赖Ca2+/钙调蛋白，分布于神经组织和血管内皮；诱导型iNOS（NOS2）在细胞受刺激后被诱导表达，见于巨噬细胞等免疫细胞，生成NO量较大，参与免疫防御。","src":"网络补充：baike.so.com/一氧化氮合酶"},{"id":"7025109c","s":"c","g":"c09","n":"三聚体G蛋白","e":"heterotrimeric G protein","d":"三聚体G蛋白（heterotrimeric G protein）又称大G蛋白，是G蛋白偶联受体与效应酶之间的转导分子，由Gα、Gβ和Gγ三种亚基组成。Gα亚基具有GTPase活性，结合GTP时为活化态、结合GDP时为失活态，因而作为分子开关；Gβ和Gγ以二聚体形式存在。Gα与Gβγ分别通过共价结合的脂分子锚定在质膜上。受体激活后促使Gα上的GDP被GTP置换，Gα与Gβγ解离，两者分别作用于腺苷酸环化酶、磷脂酶C等效应器。","src":"《第9章 2021细胞通讯和信号转导》p48"},{"id":"490dd31f","s":"c","g":"c09","n":"串话","e":"cross-talk","d":"串话（cross-talk）指不同细胞信号转导途径之间信号可以来回传递、相互影响的现象，是细胞信号转导的基本特点之一。两条主要信号通路的蛋白激酶不仅能磷酸化本通路的成员，还能磷酸化属于另一条通路的许多蛋白，因此一条通路的激活会改变另一条通路的活性状态。通过这种交叉磷酸化以及共享接头蛋白、第二信使等方式，原本各自独立的通路被连成网络，使细胞能对多种信号进行整合，产生协调而非孤立的反应。","src":"《第9章 2021细胞通讯和信号转导》p117；《第9章 2021细胞通讯和信号转导》p118；《第9章 2021细胞通讯和信号转导》p24"},{"id":"875ea0cf","s":"c","g":"c09","n":"信号分子","e":"","d":"信号分子是细胞所接受的、能引起细胞反应的信息载体，可分为物理信号与化学信号两类。物理信号包括光、热和电流；化学信号最为广泛，包括各类激素、神经递质及局部介质，其化学本质涵盖短肽、蛋白质、气体分子（如NO、CO）以及氨基酸、核苷酸、脂类和胆固醇衍生物。信号分子有三个共同特点：特异性，只能与特定的受体结合；高效性，几个分子即可引起明显的生物学效应，这有赖于细胞逐级放大的信号系统；可被灭活，完成信息传递后可被降解或修饰而失去活性。","src":"《第9章 2021细胞通讯和信号转导》p11；《第9章 2021细胞通讯和信号转导》p12"},{"id":"6a8c3a7a","s":"c","g":"c09","n":"兴奋性突触后电位","e":"EPSP","d":"兴奋性突触后电位（EPSP）是突触传递中突触后膜出现的一种去极化电位变化。离子通道偶联受体本身为4次或6次跨膜螺旋的通道蛋白，神经递质与之结合后通道开放，某些特定离子得以沿各自浓度梯度流入或流出，由此产生的净电流使突触后膜发生去极化，即兴奋性突触后电位；若同样的离子流使突触后膜出现超极化，则称为抑制性突触后电位（IPSP）。两者都是离子通道偶联受体把化学信号转换为电信号的直接结果。","src":"《第9章 2021细胞通讯和信号转导》p45"},{"id":"34aaf1ce","s":"c","g":"c09","n":"双信使系统","e":"","d":"双信使系统指G蛋白偶联受体激活磷脂酶C后，以1,4,5-三磷酸肌醇（IP3）和二酰基甘油（DAG）两种第二信使共同介导的信号通路。配体结合受体使G蛋白活化并激活磷脂酶C，后者水解质膜上的4,5-二磷酸磷脂酰肌醇，生成IP3和DAG。IP3为水溶性，扩散至内质网，作用于IP3受体这一Ca2+通道，使胞质Ca2+升高；DAG留在膜上，激活蛋白激酶C，使靶蛋白磷酸化。两条分支相互配合，把胞外信号转为胞内钙信号与磷酸化反应。","src":"《第9章 2021细胞通讯和信号转导》p63；《第9章 2021细胞通讯和信号转导》p65"},{"id":"e317d636","s":"c","g":"c09","n":"发散性","e":"divergence","d":"发散性（divergence）是细胞信号转导网络的一种基本特征，指同一配体的信号可以分途激活多种不同的效应器，从而产生多种效应。一种胞外信号分子与受体结合后，可同时开启多条下游通路：同一条G蛋白偶联受体通路既可经Gα调节腺苷酸环化酶，又可经磷脂酶C分支影响胞内Ca2+；受体酪氨酸激酶活化后也可分别经Ras-MAPK、PI3K等途径传递。发散使有限的信号分子能够协调地改变细胞的多项功能。","src":"《第9章 2021细胞通讯和信号转导》p116"},{"id":"8ddc13f8","s":"c","g":"c09","n":"受体","e":"receptor","d":"受体（receptor）是细胞膜上或细胞内能识别信号分子并与其特异性结合、进而引起细胞功能变化的生物大分子，通常为蛋白质。受体一般具有两个功能域：一是与配体结合的识别域，决定信号分子的特异性；二是产生效应的效应域，负责把结合事件转变为胞内反应。有的受体位于细胞表面，如离子通道偶联受体、G蛋白偶联受体和酶联受体；有的位于细胞内部，如核受体。配体结合后通过改变受体构象把信息导入细胞。","src":"《第9章 2021细胞通讯和信号转导》p13；《第9章 2021细胞通讯和信号转导》p43"},{"id":"64607a41","s":"c","g":"c09","n":"受体酪氨酸激酶","e":"receptor tyrosine kinase, RTK","d":"受体酪氨酸激酶（receptor tyrosine kinase，RTK）是最大的一类酶联受体，属跨膜蛋白。配体结合其胞外部分后，激活胞内的激酶活性域，对底物蛋白的酪氨酸残基进行磷酸化。受体通常以单体形式存在，配体结合促使其二聚化，两个单体相互交叉磷酸化而充分活化，磷酸化的酪氨酸随后成为含SH2结构域蛋白的停泊位点。按结构可分为多个亚族，如EGF受体（ErbB）家族、胰岛素受体家族、PDGF受体家族、FGF受体家族和Eph家族等。","src":"《第9章 2021细胞通讯和信号转导》p73；《第9章 2021细胞通讯和信号转导》p74"},{"id":"01278e51","s":"c","g":"c09","n":"受体酪氨酸蛋白磷酸酶","e":"receptor protein tyrosine phosphatase, PTP","d":"受体酪氨酸蛋白磷酸酶（receptor protein tyrosine phosphatase，PTP）是酶联受体的一类，其作用与蛋白酪氨酸激酶相反：它去除已发生磷酸化的酪氨酸残基上的磷酸根，使底物去磷酸化。由于酪氨酸磷酸化是许多信号通路的开关，PTP通过逆转激酶的作用而对信号起负向调节。PTP具有胞内的和膜上的两种形式，膜上形式即受体型，其胞外段可结合配体，胞内段催化去磷酸化，把胞外信号与胞内磷酸化水平联系起来。","src":"《第9章 2021细胞通讯和信号转导》p91"},{"id":"0cc0b426","s":"c","g":"c09","n":"失巢凋亡","e":"anoikis","d":"失巢凋亡（anoikis）是一种特殊的细胞程序性死亡，由细胞与细胞外基质或相邻细胞脱离接触而诱发。正常情况下，细胞外基质不仅提供机械支撑，还通过整联蛋白等受体向细胞传递信号，对细胞的迁移、分化、形态、凋亡和增殖均有影响；一旦上皮细胞脱离基质，来自基质的信号消失，细胞便启动程序性死亡，这是细胞外基质调控细胞凋亡的典型表现，与基质对迁移、分化、形态和增殖的调控同属一类细胞行为控制。","src":"《第9章 2021细胞通讯和信号转导》p104"},{"id":"067ddd52","s":"c","g":"c09","n":"抑制性突触后电位","e":"IPSP","d":"抑制性突触后电位（IPSP）是突触传递中突触后膜出现的一种超极化电位变化。离子通道偶联受体为4次或6次跨膜螺旋的通道蛋白，神经递质与之结合后通道开放，使某些特定离子沿各自浓度梯度流入或流出；由此产生的净电流若使突触后膜发生超极化，即称为抑制性突触后电位，与产生去极化的兴奋性突触后电位（EPSP）相对。两者均体现离子通道偶联受体把化学信号转换为电信号的功能，是突触后膜对递质作出兴奋或抑制反应的电位基础。","src":"《第9章 2021细胞通讯和信号转导》p45"},{"id":"068f6452","s":"c","g":"c09","n":"支架蛋白","e":"scaffold protein","d":"支架蛋白（scaffold protein）是一类具有多个结合位点、能把一组细胞内蛋白结合成复合物并常将其锚定在细胞特定位置的蛋白。在信号转导中，它可使相关激酶预先装配成等待激活的信号复合物。支架蛋白的结合对象包括多个其他蛋白和/或RNA分子，因而既把特定大分子连接在一起，又把它们定位到细胞内特定位置。其形态从刚性的支架（如SCF泛素连接酶中的cullin）到大型柔性支架不等，后者可在细胞内形成具有独特生化性质的区域。","src":"《第9章 2021细胞通讯和信号转导》p30；《第9章 2021细胞通讯和信号转导》p31；MBoC 7e 印刷 p171"},{"id":"f95627bf","s":"c","g":"c09","n":"收敛性","e":"convergence","d":"收敛性（convergence）是信号转导网络的另一种基本特征，指来自多种互不相关受体的信号可以汇聚，最终激活共同的效应器。不同受体被各自的配体激活后，其胞内段或底物上的酪氨酸被磷酸化，形成供接头蛋白SH2结构域停靠的磷酸酪氨酸位点；尽管上游受体种类各异，这些停泊位点却可招募同一套含SH2的接头蛋白与交换因子，使信号汇入共同通路。收敛使细胞能把性质不同的刺激整合为统一反应，与发散性共同构成信号网络的整合能力。","src":"《第9章 2021细胞通讯和信号转导》p115"},{"id":"fa3a9fd7","s":"c","g":"c09","n":"整联蛋白连接激酶","e":"ILK","d":"整联蛋白连接激酶（ILK）是整联蛋白介导的细胞外基质信号通路中的关键激酶。整联蛋白与细胞外基质结合后，ILK被激活，进而磷酸化并激活下游分子；同时它能结合肌动蛋白，引起细胞骨架组装，并激活相关的信号转导途径，使细胞产生相应反应。因此ILK把胞外基质的信号同细胞骨架及胞内信号联系起来。其活性受整联蛋白连接激酶相关磷酸酶（ILKAP）的负向调控，后者通过去磷酸化抑制ILK的活性。","src":"《第9章 2021细胞通讯和信号转导》p102"},{"id":"b94298ae","s":"c","g":"c09","n":"核受体共激活因子","e":"","d":"核受体共激活因子是一类与核受体结合、促进其转录活性的辅调节因子，与核受体辅抑制因子作用相反。其促进转录的方式主要有三：一是通过组蛋白乙酰化推进染色质结构的改变，使染色质松解而利于转录；二是作为桥梁因子，在结合于DNA的核受体位置募集调节因子；三是解除共抑制因子的作用，从而去掉对转录的抑制。共激活因子与辅抑制因子的相对作用，最终决定核受体对靶基因是激活还是抑制。","src":"《第9章 2021细胞通讯和信号转导》p95"},{"id":"b75967f9","s":"c","g":"c09","n":"核受体辅抑制因子","e":"","d":"核受体辅抑制因子是一类与核受体结合并抑制基因转录的辅调节因子。它本身并没有组蛋白去乙酰化活性，需要再招募其他的辅调节蛋白形成复合物，由复合物使核心组蛋白去乙酰化，从而使染色质结构收紧、抑制基因的转录。它与核受体共激活因子作用相反：后者通过组蛋白乙酰化松解染色质、作为桥梁因子募集调节因子并解除共抑制因子的作用来促进转录，而辅抑制因子则维持受体的抑制状态。两者的平衡决定靶基因的表达水平。","src":"《第9章 2021细胞通讯和信号转导》p95"},{"id":"c1c3e805","s":"c","g":"c09","n":"环鸟苷磷酸","e":"cGMP","d":"环鸟苷磷酸（cyclic GMP，cGMP）是细胞内重要的第二信使之一，由鸟苷酸环化酶催化GTP生成，并可被cGMP特异的磷酸二酯酶水解而降解。在一氧化氮／环鸟苷酸途径中，NO激活鸟苷酸环化酶，使胞内cGMP升高，cGMP再激活cGMP依赖性蛋白激酶G，使靶蛋白的丝氨酸或苏氨酸残基磷酸化而引起细胞反应，如血管平滑肌舒张。磷酸二酯酶水解cGMP，从而终结这一第二信使所传导的作用，胞内cGMP水平由生成与降解共同决定。","src":"《第9章 2021细胞通讯和信号转导》p38；《第9章 2021细胞通讯和信号转导》p39"},{"id":"bae1cb67","s":"c","g":"c09","n":"百日咳毒素","e":"","d":"百日咳毒素是一种能对G蛋白进行ADP-核糖基化修饰的细菌毒素。它催化Giα亚基的ADP-核糖基化，结果阻止了与Giα亚基结合的GDP释放，使Giα亚基被锁定在非活化状态，从而阻断了Gi对腺苷酸环化酶的抑制作用。抑制被解除后，气管上皮细胞内cAMP水平随之升高，促使液体、电解质和黏液分泌减少。这一作用环节也使百日咳毒素成为分析Gi蛋白在信号转导中功能的重要工具。","src":"《第9章 2021细胞通讯和信号转导》p54"},{"id":"528517c7","s":"c","g":"c09","n":"磷脂酶C","e":"phospholipase C, PLC","d":"磷脂酶C（phospholipase C，PLC）是G蛋白偶联受体介导的双信使通路中的效应酶。配体结合受体使G蛋白活化后，活化的Gα亚基激活磷脂酶C，后者水解质膜上的4,5-二磷酸磷脂酰肌醇，生成1,4,5-三磷酸肌醇（IP3）和二酰基甘油（DAG）两种第二信使。IP3为水溶性，扩散到光面内质网并作用于IP3受体，使胞质Ca2+升高；DAG留在膜内，激活蛋白激酶C。因此PLC处于该通路的分岔点，一次水解同时启动钙信号与磷酸化两条分支。","src":"《第9章 2021细胞通讯和信号转导》p63；《第9章 2021细胞通讯和信号转导》p65"},{"id":"6ed7fbfd","s":"c","g":"c09","n":"磷酸二酯酶","e":"phosphodiesterase, PDE","d":"磷酸二酯酶（phosphodiesterase，PDE）是一类能水解细胞内第二信使的酶，其底物为cAMP（环磷酸腺苷）或cGMP（环磷酸鸟苷）。它把cAMP或cGMP降解，从而终结这些第二信使所传导的作用，使信号在刺激减弱后迅速回落。例如cAMP磷酸二酯酶水解cAMP，与腺苷酸环化酶共同决定胞内cAMP的水平：前者负责降解，后者负责生成。PDE因此成为药物作用的重要靶点，西地那非即通过抑制cGMP特异的磷酸二酯酶而提高cGMP水平。","src":"《第9章 2021细胞通讯和信号转导》p39；《第9章 2021细胞通讯和信号转导》p58"},{"id":"79d9000f","s":"c","g":"c09","n":"离子通道偶联受体","e":"","d":"离子通道偶联受体又称配体门控型离子通道，是具有离子通道功能的细胞膜受体，其典型结构为4次或6次跨膜螺旋。它主要受神经递质等信号物质调节：递质与受体结合后，可使离子通道打开或关闭，从而改变膜的通透性，诱导细胞内的信号转导。通道开放后，某些特定离子沿各自浓度梯度流入或流出，离子流所携带的净电流或使突触后膜去极化，或使之超极化。因此这类受体是把化学信号转换为电信号的装置。","src":"《第9章 2021细胞通讯和信号转导》p44；《第9章 2021细胞通讯和信号转导》p45"},{"id":"57728f4f","s":"c","g":"c09","n":"突触","e":"synapse","d":"突触（synapse）是神经元之间或神经元与效应细胞之间传递信号的特化连接部位。化学突触由突触前膜、突触间隙和突触后膜三部分组成：动作电位到达突触前膜引起去极化，使聚集于前膜的电压门控Ca2+通道开放，Ca2+内流触发突触泡中的神经递质释放入狭窄的突触间隙，再作用于突触后膜上的受体。电突触同样有突触前膜、突触后膜及突触间隙，但没有突触泡和线粒体的汇聚，膜内侧胞质中也无突触泡聚集。","src":"《第9章 2021细胞通讯和信号转导》p99；MBoC 7e 印刷 p669"},{"id":"b2c2f2da","s":"c","g":"c09","n":"胞间连丝","e":"","d":"胞间连丝是植物细胞之间直接相连的通道，相当于植物细胞的缝隙连接，是植物组织中细胞通讯的结构基础。通道的周围是相邻两个细胞质膜的延续和连接，即两个细胞的质膜在通道处彼此连通，使细胞质得以直接相通；通道的中央有一个由压扁的内质网形成的圆筒体，纵向贯穿整个通道。质膜的延续部分与中央圆筒体之间留有可供物质通过的狭窄空间，因而胞间连丝既维持了相邻细胞在结构上的连续性，又为细胞间交换物质与信息提供了途径。","src":"《第9章 2021细胞通讯和信号转导》p100"},{"id":"238f0904","s":"c","g":"c09","n":"腺苷酸环化酶","e":"adenylyl cyclase, AC","d":"腺苷酸环化酶（adenylyl cyclase，AC）是G蛋白偶联受体通路中催化生成cAMP的效应酶，位于质膜上。它受G蛋白的双向调节：Gs型G蛋白活化后激活腺苷酸环化酶，使cAMP生成增多；Gi型G蛋白活化则抑制该酶，使cAMP减少。胞内cAMP升高后激活蛋白激酶A，进而磷酸化靶蛋白，并通过cAMP-PKA通路影响基因转录。cAMP可被cAMP磷酸二酯酶水解，故胞内cAMP含量由腺苷酸环化酶的生成作用与磷酸二酯酶的降解作用共同决定。","src":"《第9章 2021细胞通讯和信号转导》p50；《第9章 2021细胞通讯和信号转导》p57"},{"id":"770dd2b7","s":"c","g":"c09","n":"膜表面分子接触通讯","e":"juxtacrine signaling","d":"膜表面分子接触通讯（juxtacrine signaling）是通过细胞接触进行细胞间通讯的方式，属于细胞局部通讯的主要形式之一。它有两种形式：一是以细胞膜绑定的配体与另一个细胞的膜绑定受体之间的相互作用，此时信号分子并不释放到细胞外液中，而是随膜与膜的直接接触传递给相邻细胞；二是以旁分泌方式作用于邻近的异种细胞。由于信号只在接触处传递，这种通讯作用距离极短、定位精确，与内分泌的长距离激素信号共同构成细胞间信息交流的多种方式。","src":"《第9章 2021细胞通讯和信号转导》p97"},{"id":"13291a87","s":"c","g":"c09","n":"蛋白激酶","e":"protein kinase, PK","d":"蛋白激酶（protein kinase，PK）是把磷酸基团转移到其他蛋白质上的酶，与其作用相反的蛋白磷酸酶则去除磷酸基团。二者共同构成靶蛋白的磷酸化／去磷酸化分子开关：磷酸化往往改变靶蛋白的构象与活性，去磷酸化则使之复原，因而这类共价修饰通常对靶蛋白的活性具有调节作用。细胞信号转导中的许多环节都依赖这一机制，如蛋白激酶A、蛋白激酶C、蛋白激酶G以及MAPK级联中的激酶，通过依次磷酸化下游蛋白把信号逐级放大并传递。","src":"《第9章 2021细胞通讯和信号转导》p23"},{"id":"1443867a","s":"c","g":"c09","n":"蛋白激酶B","e":"PKB (Akt)","d":"蛋白激酶B（PKB，又称Akt）是反转录病毒癌基因v-akt的编码产物，属丝氨酸/苏氨酸蛋白激酶，是重要的信号转导分子。除中间的激酶结构域外，其N端还含有一个PH结构域，能紧密结合PI-3-P的3位磷酸基团，因而PI3K在质膜上生成的PI-3-P可作为它的锚定位点，把它募集到质膜并被PDK1、PDK2磷酸化而完全活化。活化后的PKB游离下来，磷酸化多种靶蛋白，包括重新激活凋亡抑制蛋白，从而抑制细胞凋亡。","src":"《第9章 2021细胞通讯和信号转导》p82；《第9章 2021细胞通讯和信号转导》p84"},{"id":"1081d133","s":"c","g":"c09","n":"蛋白质模式结合域","e":"modular binding domain","d":"蛋白质模式结合域（modular binding domain）是蛋白质中承担识别功能的结构模块，通常由40~120个氨基酸残基组成。它本身不具酶活性，却能识别其他蛋白质上的特定基序或特定修饰位点，如SH2结构域识别围绕磷酸酪氨酸的序列。这类模块与识别对象的亲和性较弱，因而有利于快速和反复地进行精细的组合式网络调控：同一蛋白可借不同的模块同时连接多个伙伴，信号通路也因此能够灵活组装与解离，而不必依赖高亲和而不可逆的结合。","src":"《第9章 2021细胞通讯和信号转导》p34"},{"id":"a15647d8","s":"c","g":"c09","n":"适应","e":"adaptation","d":"适应（adaptation）又称脱敏，指靶细胞在持续或反复受刺激后对信号分子敏感性下降的现象。其实现有五种方式：受体经内吞而被隔离；受体被送入溶酶体销毁而下调；受体被磷酸化后结合β-arrestin而失活；胞内信号蛋白发生改变而失活；下游反应中产生抑制性蛋白形成负反馈。适应使细胞对信号强度的变化而非信号的绝对量作出反应，因而能在很宽的信号水平范围内保持敏感性，视觉系统即利用适应在极大光强范围内清晰视物。","src":"《第9章 2021细胞通讯和信号转导》p119；MBoC 7e 印刷 p891"},{"id":"6edec9fa","s":"c","g":"c09","n":"酶联受体","e":"","d":"酶联受体是跨膜蛋白，既是受体又是酶，一旦被配体激活即具有酶活性并把信号放大，故又称催化受体。其胞内结构域常具有某种蛋白质激酶的活性，或者本身无激酶活性而与另一种蛋白激酶分子相连。按胞内段的性质可分为几类：受体酪氨酸激酶、受体蛋白丝氨酸/苏氨酸激酶、偶联蛋白质激酶的受体、鸟苷酸环化酶受体以及受体酪氨酸蛋白磷酸酶。它们与G蛋白偶联受体、离子通道偶联受体并列为细胞膜受体介导信号转导的途径。","src":"《第9章 2021细胞通讯和信号转导》p71；《第9章 2021细胞通讯和信号转导》p72"},{"id":"67875d77","s":"c","g":"c09","n":"钙调蛋白","e":"calmodulin, CaM","d":"钙调蛋白（calmodulin，CaM）是一种钙结合蛋白，通过Ca2+的结合与解离在两个状态间转换，起分子开关的作用：结合Ca2+后构象改变而被激活，进而影响其他蛋白质的活性，Ca2+解离则使其关闭。它是细胞内Ca2+信号的主要受体之一，当IP3引起胞质Ca2+升高时，Ca2+与钙调蛋白结合，把钙信号转交给下游靶蛋白，从而介导多种细胞反应。它与G蛋白超家族开关、蛋白激酶／蛋白磷酸酶开关同属重要的分子开关类型。","src":"《第9章 2021细胞通讯和信号转导》p18；《第9章 2021细胞通讯和信号转导》p65"},{"id":"830210f9","s":"c","g":"c09","n":"霍乱毒素","e":"","d":"霍乱毒素具有ADP-核糖转移酶活性，进入细胞后催化胞内NAD+中的ADP-核糖基共价结合在Gsα亚基上。这一修饰使Gsα亚基丧失GTPase活性，无法把结合的GTP水解为GDP，于是Gsα亚基被锁定在持续活化状态，不断地激活腺苷酸环化酶，使cAMP增加100倍以上。cAMP剧增导致细胞大量Na+和水分子持续外流，产生严重腹泻而脱水，这是霍乱剧烈水样泻的分子基础。","src":"《第9章 2021细胞通讯和信号转导》p53"},{"id":"cc602188","s":"c","g":"c09","n":"鸟苷酸环化酶受体","e":"Guanylate cyclase-coupled receptor","d":"鸟苷酸环化酶受体是酶联受体的一类，其受体分子本身即具鸟苷酸环化酶活性。配体结合后，其细胞内部分的一个鸟苷酸环化酶催化结构域被激活，催化GTP生成cGMP。cGMP作为第二信使激活cGMP依赖性的蛋白激酶G，后者进而使特定蛋白质的丝氨酸或苏氨酸残基磷酸化，引起细胞反应。与腺苷酸环化酶生成cAMP的通路相类似，该受体把胞外信号直接转变为环核苷酸水平的升高，是酶联受体中较为直接的一种信号转换方式。","src":"《第9章 2021细胞通讯和信号转导》p72；《第9章 2021细胞通讯和信号转导》p90"},{"id":"5d64316a","s":"c","g":"c08","n":"APC/C","e":"APC/C","d":"APC/C即后期促进复合体／周期体（anaphase-promoting complex/cyclosome），是泛素连接酶家族的多亚基复合体，活性自中期升高并持续至G1。其活性依赖与Cdc20或Cdh1结合，结合后构象改变而增强酶活性。APC/C催化securin和M期cyclin泛素化，使二者被蛋白酶体降解；securin的降解释放并激活separase，切断姐妹染色单体的连接，cyclin降解则使Cdk1失活，细胞得以退出M期。","src":"《第10章 细胞分裂与细胞周期(下)》p73；MBoC 7e 印刷 p1039","x":1},{"id":"3ef6cac5","s":"c","g":"c08","n":"ATM/ATR","e":"ATM/ATR","d":"ATM/ATR是与PI-3-K同源的激酶，作为DNA损伤信号的感受因子并激活下游通路。两条级联对应不同损伤类型：ATM-Chk2通路主要被DNA双链断裂激活，ATR-Chk1通路则主要被单链DNA激活，Chk2和Chk1是哺乳类细胞中DNA损伤信号感受因子的底物，均属Ser/Thr激酶。它们作用于G1/S、S期内部和G2/M三个检查点：G1/S时抑制DNA复制起始，S期内抑制晚复制起点的启动，G2/M时阻止细胞进入M期。","src":"《第10章 细胞分裂与细胞周期(下)》p58；《第10章 细胞分裂与细胞周期(下)》p62；《第10章 细胞分裂与细胞周期(下)》p69"},{"id":"9e59ba10","s":"c","g":"c08","n":"Aurora B","e":"Aurora B","d":"Aurora B是染色体乘客复合体（CPC）中的激酶，该复合体与内动粒相关联。它参与动粒与微管连接的稳定及错误连接的修正：微管牵拉动粒，黏连蛋白抵抗这一拉力，当两侧动粒都处于张力之下时，外动粒被拉离CPC，Aurora B不能磷酸化包括Ndc80在内的外动粒组分，连接得以稳定；若连接不正确，如两个姐妹动粒连向同一极或一个动粒连向两极，张力不足使Ndc80靠近Aurora B而被磷酸化，连接随之变得不稳定并被纠正。","src":"《第10章 细胞分裂与细胞周期(上)》p94；《第10章 细胞分裂与细胞周期(上)》p98"},{"id":"34c1a814","s":"c","g":"c08","n":"CAK","e":"CAK","d":"CAK即CDK激活激酶（Cdk-activating kinase），是使细胞周期蛋白依赖性激酶完全活化所必需的激酶。仅有cyclin结合并不能使Cdk充分活化：cyclin结合使T环移出活性中心，Cdk只获得部分活性；CAK再使Cdk的T环中一个苏氨酸残基（如Cdk2的Thr161）磷酸化，引起构象改变，使Cdk活性大大提高而完全活化。CAK的活性在整个细胞周期中保持恒定，因此这一修饰在各阶段持续发生。","src":"《第10章 细胞分裂与细胞周期(下)》p41；《第10章 细胞分裂与细胞周期(下)》p42；MBoC 7e 印刷 p1034"},{"id":"9251abc1","s":"c","g":"c08","n":"CKI","e":"CKI","d":"CKI即CDK激酶抑制因子（Cdk inhibitor protein），是对细胞周期起负调控作用的一组核蛋白。它们直接结合cyclin-CDK复合物，抑制其激酶活性，从而阻止细胞越过细胞周期检查点。按结构可分为两大家族：KIP/CIP家族，包括p21、p27和p57，主要抑制各类cyclin-CDK复合物；Ink4家族，包括p14至p19，作用于特定的CDK。CKI的表达可受p53调控，是细胞在DNA损伤等条件下中止周期的重要环节。","src":"《第10章 细胞分裂与细胞周期(下)》p44；《普通班作业汇总》p5","x":1},{"id":"597295e6","s":"c","g":"c08","n":"Cdc20","e":"Cdc20","d":"Cdc20是后期促进复合体／周期体（APC/C）的激活亚基之一，在中期向后期的转换中首先起作用。它与APC/C结合后，一方面引起构象改变而增强酶活性，另一方面提供酶与底物结合的主要位点，使APC/C得以在靶蛋白上装配多泛素链。APC-Cdc20在中期／后期转换时被激活，负责降解抑制后期的蛋白securin和M期cyclin，促使细胞由中期转入后期。纺锤体检查点蛋白Mad2能与Cdc20结合，抑制其对APC/C的激活。","src":"《第10章 细胞分裂与细胞周期(上)》p50；《第10章 细胞分裂与细胞周期(下)》p53；MBoC 7e 印刷 p1039","x":1},{"id":"1e3d387e","s":"c","g":"c08","n":"Cdc25","e":"Cdc25","d":"Cdc25是蛋白磷酸酶，负责去除周期蛋白依赖性激酶（Cdk）活性位点上方两个相邻位点的抑制性磷酸，从而提高Cdk活性。静息的M-Cdk虽已被CAK加上激活磷酸，却被Wee1的抑制性磷酸封闭；进入M期的关键事件正是Cdc25被激活、Wee1受抑制。Cdc25还能被其靶标M-Cdk激活，M-Cdk又抑制Wee1，构成正反馈，使少量Cdc25即可让大量CDK迅速活化。Cdc25不足时细胞不分裂，Wee1不足时细胞提早分裂，双突变个体正常分裂。","src":"《第10章 细胞分裂与细胞周期(下)》p43、p70；MBoC 7e 印刷 p1037","x":1},{"id":"50256934","s":"c","g":"c08","n":"Cdc6","e":"Cdc6","d":"Cdc6 是ATPase家族成员，能结合DNA双链，参与复制起始调控。它在细胞周期大部分时间含量很低，G1早期瞬时增加，为Mcm环复合体结合到DNA上所必需。晚M期与G1早期，Cdc6与Cdt1协作，在起点识别复合体（ORC）处把Mcm解旋酶装载到起点旁的DNA上，使起点获得复制执照。S期起始后，其他CDK阻止pre-RC再次形成，Cdc6的降解与失活是其中一环；待APC/C激活、CDK失活后Cdc6去磷酸化，pre-RC得以重置。","src":"《第10章 细胞分裂与细胞周期(下)》p65、p67；MBoC 7e 印刷 p1044"},{"id":"02895319","s":"c","g":"c08","n":"Cdt1","e":"Cdt1","d":"Cdt1 是与Cdc6协同的Mcm装载因子：G1早期CDK活性低时，Cdc6与Cdt1同ORC结合，把MCM复制解旋酶复合体装载到每个复制起点。Cdt1受geminin抑制——晚G1 APC/C-Cdh1关闭后geminin积累，抑制未与DNA结合的Cdt1；Cdt1与活跃复制叉上的蛋白结合还会促使CRL4-Cdt2将其泛素化降解。晚M期与G1早期APC/C-Cdh1降解geminin，使Cdt1恢复活性，pre-RC得以重置。","src":"《第10章 细胞分裂与细胞周期(下)》p66、p67、p90；MBoC 7e 印刷 p1045"},{"id":"314a0a49","s":"c","g":"c08","n":"Chk1/Chk2","e":"Chk1/Chk2","d":"Chk1/Chk2（Chk1/Chk2）是DNA损伤信号通路中的Ser/Thr激酶，也是ATM/ATR的底物与下游效应器。DNA受损时，损伤位点首先募集ATM或ATR（依损伤类型而定）并使其激活，随后募集并激活Chk1和Chk2，二者再磷酸化其他靶蛋白而导致细胞周期阻滞。主要靶标是p53：p53被磷酸化后稳定、积累，刺激p21基因转录，p21结合并抑制G1/S-Cdk与S-Cdk复合物，从而阻断细胞进入周期，使细胞停于G1期。","src":"《第10章 细胞分裂与细胞周期(下)》p58；MBoC 7e 印刷 p1081"},{"id":"16e13d41","s":"c","g":"c08","n":"DNA复制执照假说","e":"DNA replication-licensing theory","d":"DNA复制执照假说（DNA replication-licensing theory）认为，细胞中存在支持DNA复制的胞质因子，它们只出现在S期细胞中，当细胞由S期进入G2时即消失。据此，复制起点必须先在G1获得执照才能启动复制；一旦完成复制执照即失效，DNA不能在同一周期内再复制，G2期核须经M期进入下一个G1才能重新获得执照。该假说解释了每周期只复制一次的现象，其分子基础是G1期ORC、Cdc6、Cdt1装载Mcm形成pre-RC。","src":"《第10章 细胞分裂与细胞周期(下)》p64、p65"},{"id":"bdaf9bfd","s":"c","g":"c08","n":"E2F","e":"E2F","d":"E2F是一组基因调控蛋白，能结合多种基因启动子中的特定DNA序列，这些基因编码S期进入所需的蛋白，包括G1/S-周期蛋白、S-周期蛋白及DNA合成与染色体复制相关蛋白。无促有丝分裂刺激时，E2F与视网膜母细胞瘤蛋白（Rb）家族成员结合，其基因表达被抑制。促有丝分裂信号使G1-Cdk（cyclin D-Cdk4）活化并磷酸化Rb，释放E2F；E2F还提高自身及cyclinE、cyclinA基因的转录，进一步增加Rb磷酸化，形成正反馈。","src":"《第10章 细胞分裂与细胞周期(下)》p61；MBoC 7e 印刷 p1079"},{"id":"6c442417","s":"c","g":"c08","n":"G0期","e":"G0 phase","d":"G0期（G0 phase）是细胞脱离细胞周期后进入的静息状态。细胞在G1中行进时，依内部与外部条件可延迟G1、进入G0，或越过限制点继续周期。G0细胞不进行正常分裂，但接受适当的促分裂信号后可以重新进入周期，肝细胞、淋巴细胞即属此类；与之相对，肌细胞、红细胞、神经细胞等终末分化细胞已失去分裂能力。实验上常用血清饥饿法获得G0期细胞。G0细胞必须接收到适当的促有丝分裂信号才能重新进入周期，这是G1期检查点监控的内容之一。","src":"《第10章 细胞分裂与细胞周期(下)》p9、p14、p56","x":1},{"id":"a1b5edb3","s":"c","g":"c08","n":"G0期","e":"G0","d":"G0（G0）指细胞从真核细胞分裂周期中退出而进入的静息偏离状态，是分化细胞常见、有时是永久的状态。细胞在G1中推进时，依内外条件可延迟G1、转入G0，或越过限制点继续前进。进入G0的细胞不再正常分裂，只有接受适当的促有丝分裂信号才重新进入周期，肝细胞与淋巴细胞即能在刺激后恢复分裂；而终末分化的肌细胞、红细胞、神经细胞则不再分裂直至死亡。据此可把细胞分为连续分裂的周期细胞、G0细胞与终末分化细胞三类。","src":"《第10章 细胞分裂与细胞周期(下)》p9、p56；MBoC 7e Glossary（PDF p1456）"},{"id":"2fa323a7","s":"c","g":"c08","n":"G1/S检验点","e":"G1/S checkpoint","d":"G1/S检验点（G1/S checkpoint）监测G1/S转换，在DNA损伤时抑制DNA复制的起始，阻止细胞进入S期。ATM/ATR（与PI-3-K同源的损伤感受激酶）被激活后作用于Chk2/Chk1，二者是感受因子的底物与下游效应器Ser/Thr激酶；Chk2/Chk1使Cdc25A失活，Cdk2因不能去除抑制性磷酸而无法活化。同时p53积累并促进p21表达，p21抑制G1/S-Cdk与S-Cdk；Rb不能被磷酸化，E2F持续受抑。","src":"《第10章 细胞分裂与细胞周期(下)》p58；《第12章 细胞衰老与细胞凋亡》p80"},{"id":"f477e69b","s":"c","g":"c08","n":"G2/M检验点","e":"G2/M checkpoint","d":"G2/M检验点（G2/M checkpoint）是DNA损伤时阻止细胞进入M期的监控机制：当DNA发生损伤时该检验点被激活，使携带损伤的细胞不能启动有丝分裂，避免把错误遗传信息传给子细胞。其分子组成包括ATM/ATR、Chk2/Chk1、Cdc25A、Wee1以及p53与p21，最终作用于G2/M特异的cyclinA/B-Cdk1。Cdc25A被抑制使Cdk1的抑制性磷酸不能被去除，Wee1则继续维持其失活，细胞阻滞于G2。","src":"《第10章 细胞分裂与细胞周期(下)》p69"},{"id":"fa51bc08","s":"c","g":"c08","n":"Mad2","e":"Mad2","d":"Mad2 即Mitosis arrest deficient，是纺锤体装配检查点的关键蛋白，正常定位于前中期及排列错误的中期染色体的动粒上，即未与微管连接的动粒。它提供等待信号，延迟进入后期；未连接动粒像酶一样催化Mad2构象改变，Mad2再与其他蛋白形成多蛋白复合体，结合并抑制APC/C-Cdc20。Mad2也直接结合Cdc20而抑制APC。微管正确连接后抑制性复合体解体，抑制解除；Mad2突变细胞在染色体排列错误时不能停滞于中期。","src":"《第10章 细胞分裂与细胞周期(下)》p73、p74；《第10章 细胞分裂与细胞周期(上)》p49；MBoC 7e 印刷 p1062","x":1},{"id":"4b17f359","s":"c","g":"c08","n":"Mcm蛋白","e":"MCM (minichromosome maintenance protein complex)","d":"Mcm蛋白（MCM）以复合体形式参与DNA复制的起始与延伸，具解旋酶活性，形成环状结构环绕DNA。G1早期CDK活性低时，Cdc6与Cdt1两种装载因子与ORC结合，把MCM复制解旋酶复合体装载到每个复制起点；晚G1由DDK磷酸化MCM，S期CDK再磷酸化Sld2与Sld3，使DNA双链解开供DNA聚合酶作用。pre-RC启动后其他CDK阻止其再次形成，使每个起点每周期只启动一次，保证DNA只复制一次。","src":"《第10章 细胞分裂与细胞周期(下)》p65、p90"},{"id":"dfaefb7c","s":"c","g":"c08","n":"Ndc80复合物","e":"Ndc80 complex","d":"Ndc80复合物（Ndc80 complex）在动粒与微管正端之间形成关键而受调控的连接：复合物一端结合微管正端侧面，另一端经中介蛋白连到含CENP-A（组蛋白H3的特殊变体）的着丝粒核小体，使微管在保持连接的同时仍能聚合与解聚。其稳定性受张力调节：两动粒均处于张力下时，外动粒远离内动粒处的染色体乘客复合体（含Aurora B激酶），Ndc80不够靠近Aurora B而不能被磷酸化，连接稳定；无张力时Ndc80被磷酸化，连接失稳。","src":"《第10章 细胞分裂与细胞周期(上)》p94、p98；MBoC 7e 印刷 p1057"},{"id":"ce82bde5","s":"c","g":"c08","n":"Rb","e":"Rb","d":"Rb（Rb）即视网膜母细胞瘤基因的产物，是第一个被鉴定的抑癌基因产物，RB基因是视网膜母细胞瘤的易感基因。RB蛋白控制细胞周期进展，去磷酸化的RB具有抑制细胞增殖的活性，是其活性形式；p16INK4a能选择性抑制CDK4和CDK6，进而抑制pRb磷酸化，使非磷酸化的Rb得以与转录因子E2F结合。当Rb基因两份拷贝都缺失时，发育中视网膜的部分细胞过度增殖，说明Rb蛋白对该组织细胞分裂的抑制尤为重要。","src":"《第14章 癌细胞》p27；《第12章 细胞衰老与细胞凋亡》p23；MBoC 7e 印刷 p1079"},{"id":"b9460e87","s":"c","g":"c08","n":"Rb蛋白","e":"Rb protein","d":"Rb蛋白（Rb protein）是E2F的抑制蛋白，是哺乳动物G1期的刹车。生长因子刺激下，G1期细胞表达cyclin D并与CDK4/6结合，使Rb磷酸化；磷酸化的Rb释放转录因子E2F，后者促进cyclinE、cyclinA和CDK1等基因转录，使细胞由G1早期进入较迟阶段。释放的E2F还提高cyclinE、cyclinA转录，增加G1/S-Cdk与S-Cdk活性，使Rb进一步磷酸化。癌细胞中该调控常被破坏，导致增殖失控。","src":"《第10章 细胞分裂与细胞周期(下)》p61；《第12章 细胞衰老与细胞凋亡》p24；MBoC 7e 印刷 p1079"},{"id":"09479e71","s":"c","g":"c08","n":"SCF","e":"SCF","d":"SCF 是Skp1-cullin-F-box型多亚基泛素连接酶，由cullin支架、Skp1接头、Rbx1及众多F-box蛋白之一组成，F-box蛋白构成底物结合臂，决定底物特异性。它主要在间期有活性，把底物蛋白泛素化后交由蛋白酶体降解，如在晚G1降解S-Cdk的抑制蛋白而促进DNA复制；植物生长素途径中SCF-TIR1结合生长素后再结合AUX/IAA并使其降解。SCF与APC/C共同构成细胞周期中两类主要的泛素-蛋白酶体降解系统。","src":"《第10章 细胞分裂与细胞周期(下)》p51、p53；《第9章 2021细胞通讯和信号转导》p106；MBoC 7e 印刷 p165"},{"id":"62c8b1e2","s":"c","g":"c08","n":"S期检验点","e":"intra-S phase checkpoint","d":"S期检验点（intra-S phase checkpoint）在S期内发生DNA损伤时被激活，作用是抑制晚复制起始点的启动，使DNA复制速度减慢，同时激活DNA修复等机制。该通路由ATM/ATR感受损伤信号，经Chk2/Chk1传递，最终作用于Cdc25A与cyclinA-Cdk2，使Cdk2不能去除抑制性磷酸而维持失活，晚启动的起点因而不能启动。它与G1/S检验点、G2/M检验点共同组成DNA损伤检验点网络，只是作用时相不同。","src":"《第10章 细胞分裂与细胞周期(下)》p62；《第12章 细胞衰老与细胞凋亡》p80"},{"id":"c54cc76a","s":"c","g":"c08","n":"T-loop","e":"T-loop","d":"T-loop（T-loop）是CDK蛋白中封闭活性位点的一段区段。CDK在无cyclin结合的非活性状态下，活性位点被T-loop遮挡；cyclin结合使T-loop移出活性位点，Cdk2因而获得部分活性；随后CAK在T-loop中的一个苏氨酸残基上加磷酸，改变T-loop形状、提高酶与蛋白底物结合的能力，Cdk2才完全活化。T-loop的位移与磷酸化构成CDK激活的两步结构基础，使CDK活性受cyclin结合与CAK磷酸化的双重控制。","src":"《第10章 细胞分裂与细胞周期(下)》p41；MBoC 7e 印刷 p1034"},{"id":"205a51b0","s":"c","g":"c08","n":"Wee1","e":"Wee1","d":"Wee1（Wee1）是抑制Cdk活性的蛋白激酶，通过在Cdk活性位点上方两个相邻位点加抑制性磷酸而使Cdk失活，对M期进入的调控尤为重要。细胞接近有丝分裂时M-Cdk大量积累，虽已被CAK在激活位点磷酸化，却仍被Wee1的抑制性磷酸保持在失活状态，形成待发库存，直至Cdc25去除这些磷酸才骤然活化。Wee1表达不足时CDC2不被抑制，细胞提早分裂；Nurse分离的wee突变体在苏格兰方言中意为小，即细胞体积偏小。","src":"《第10章 细胞分裂与细胞周期(下)》p24、p43、p88；MBoC 7e 印刷 p1037"},{"id":"525c8e8f","s":"c","g":"c08","n":"geminin","e":"geminin","d":"geminin（geminin）是Cdt1的抑制蛋白，能阻止S期与M期形成启动DNA复制叉所需的蛋白-DNA复合物，确保染色体每周期只复制一次。晚G1时APC/C-Cdh1关闭，geminin积累，抑制未与DNA结合的Cdt1；Cdt1与活跃复制叉上的蛋白结合还会促使CRL4-Cdt2将其泛素化降解。相反，晚M期与G1早期APC/C-Cdh1触发geminin破坏，使Cdt1活化，pre-RC因而能够重置。","src":"《第10章 细胞分裂与细胞周期(下)》p66、p67；MBoC 7e 印刷 p1045"},{"id":"b4b82c7e","s":"c","g":"c08","n":"p21","e":"p21","d":"p21（p21）是CKI家族的抑制蛋白。DNA损伤时，磷酸化p53的激酶被激活，p53大量积累并刺激编码p21的基因转录；p21结合G1/S-Cdk与S-Cdk复合物并抑制其活性，从而阻断细胞进入周期，使细胞停滞于G1期。除抑制CDK外，p21还能抑制PCNA。它属KIP/CIP家族，该家族成员抑制所有G1期和S期的Cdk；与之并列的Ink4家族（p16等）则特异抑制cyclinD-Cdk类复合物。","src":"《第10章 细胞分裂与细胞周期(下)》p48、p92；《第12章 细胞衰老与细胞凋亡》p21；MBoC 7e 印刷 p1081","x":1},{"id":"ba637f9c","s":"c","g":"c08","n":"p53","e":"p53","d":"p53（p53）是由抑癌基因编码的转录调节蛋白，DNA损伤时被激活，阻止周期继续推进直至损伤修复，约半数人类癌症中该基因突变。未受损细胞中p53极不稳定、含量很低，主要因与Mdm2结合而被泛素化并经蛋白酶体降解；损伤后p53被磷酸化而稳定，刺激p21转录。p53还决定细胞命运：可诱导G1与G2期停滞，严重时诱导凋亡，如上调PUMA阻断p53与Bcl-xl互作、游离p53直接作用于Bax使线粒体外膜通透性增加。","src":"《第12章 细胞衰老与细胞凋亡》p54、p66、p100；MBoC 7e 印刷 p1081","x":1},{"id":"88c28731","s":"c","g":"c08","n":"preRC起始识别复合物","e":"preRC","d":"前复制复合物（preRC）是G1期在DNA复制起点上由ORC、Cdc6与Cdt1共同装载Mcm解旋酶形成的蛋白-DNA复合物。G1早期CDK活性低，Cdc6与Cdt1两种装载因子与ORC结合，把MCM解旋酶复合体装到每个起点，起点由此获得复制执照。S期起始后其他CDK阻止pre-RC再次形成；待APC/C激活、CDK失活、Cdc6去磷酸化、geminin降解而释放Cdt1后，pre-RC才在下一周期重新组装。","src":"《第10章 细胞分裂与细胞周期(下)》p65、p66、p67"},{"id":"3e841e4a","s":"c","g":"c08","n":"securin","e":"securin","d":"securin 是结合并抑制separase的蛋白，早期M期阻止separase切割连接姊妹染色单体的蛋白。中期到后期的转换由APC/C启动：当纺锤体检查点显示所有动粒均已连接微管、纺锤体正确组装与定向时，特异性因子Cdc20引导APC/C把securin与M期周期蛋白泛素化，送交蛋白酶体降解。securin被破坏后释放separase，后者切割cohesin的Scc1亚基，cohesin脱落，姊妹染色单体随之分离。","src":"《第10章 细胞分裂与细胞周期(上)》p51；MBoC 7e 印刷 p1061","x":1},{"id":"116878dd","s":"c","g":"c08","n":"separase","e":"separase","d":"separase（separase）是切割黏连蛋白的蛋白酶，其水解cohesin的Scc1亚基，使把姊妹染色单体连在一起的蛋白连接断开，cohesin随之脱落，姊妹染色单体分离并向两极移动。其活性受双重抑制：M期由CDK磷酸化抑制，同时被securin结合抑制；只有到中期-后期转换、APC/C降解securin之后，separase才被释放而发挥作用。退出M期还需磷酸酶逆转M-Cdk对多种蛋白的磷酸化，使纺锤体解聚、染色体去凝集。","src":"《第10章 细胞分裂与细胞周期(上)》p51、p97；MBoC 7e 印刷 p1061","x":1},{"id":"10ef16f9","s":"c","g":"c08","n":"中心粒","e":"centrioles","d":"中心粒（centrioles）是中心体的核心结构，每个中心体含两个互相垂直排列的中心粒。每个中心粒由9根三联微管组成，每一根三联微管又由数百个α、β和γ-微管蛋白亚基排列成环状复合物，整体呈九重对称的复杂超微结构，长度受到严格限定。间期较早时期的动物细胞一般只含一个中心体，常位于细胞核外靠近核膜一侧的特定位置。分裂细胞中中心粒每个细胞周期在原有中心粒旁复制一次，母中心粒还带有与特定中心体功能有关的附属结构。","src":"《第10章 细胞分裂与细胞周期(上)》p17、p18、p21；MBoC 7e 印刷 p1054"},{"id":"4df013e3","s":"c","g":"c08","n":"中心粒周物质","e":"PCM","d":"中心粒周物质（PCM）是包围在一对中心粒周围的无定形物质，含有负责微管成核（nucleation）与锚定（anchoring）的蛋白质。它与一对互相垂直排列的中心粒共同构成中心体，使中心体得以作为微管组织中心发挥作用，负责纺锤体的形成、纺锤丝微管的生长与排列、染色体的捕捉以及染色体向两极移动等重要事件。间期较早的动物细胞一般只含一个中心体，位于核外靠近核膜一侧的特定位置，其PCM即为胞质微管成核的主要场所。","src":"《第10章 细胞分裂与细胞周期(上)》p17、p25"},{"id":"4203953a","s":"c","g":"c08","n":"二价体（四分体）","e":"bivalent (tetrad)","d":"二价体（bivalent）又称四分体，是减数分裂前期粗线期同源染色体完全联会、缩短变粗后形成的结构。此时一对已复制的同源染色体紧密配对，每条各含两条姊妹染色单体，整个结构含四条染色单体，由联会复合体维持配对。到中期I，同源染色体间有两种连接：非姊妹染色单体之间的交叉，以及交叉处染色单体末端的粘连蛋白连接，二者与来自两极的拉力相拮抗，平衡时使配对的同源染色体排列在赤道面上；后期I同源染色体彼此分离，着丝点并不分开。","src":"《第10章 细胞分裂与细胞周期(上)》p75、p80、p82；MBoC 7e Glossary（PDF p1447）"},{"id":"81fbb4bc","s":"c","g":"c08","n":"二分裂","e":"","d":"二分裂是原核生物的细胞分裂方式，属于简单、直接的分裂：一个简单的环状DNA分子结合在一个蛋白核上，缠绕成花束状，在细胞内形成致密的类核区域，DNA形成50至100个环，环的两端固定在蛋白质核上；复制完成后细胞直接分裂，遗传物质均衡分配。与有丝分裂、减数分裂相比，二分裂不形成纺锤体，也无染色体的凝缩，过程最为简单。除细菌等原核细胞外，叶绿体也通过二分裂方式增殖，说明这种分裂机制在真核细胞的内共生细胞器中被保留。","src":"《第10章 细胞分裂与细胞周期(上)》p8、p9；《第7章细胞的能量代谢》p130"},{"id":"922daf16","s":"c","g":"c08","n":"交叉","e":"","d":"交叉是减数分裂前期双线期可见的结构，是非姊妹染色单体之间发生交换的位置。减数分裂前期依细线期、偶线期、粗线期、双线期、终变期顺序推进，交叉在双线期显现。到中期I，同源染色体之间维持两种连接：非姊妹染色单体之间的交叉，以及位于交叉处染色单体末端的粘连蛋白连接，这两种连接对来自纺锤体向两极的拉力形成拮抗；中期时拉力达到平衡，使配对的同源染色体排列到赤道面上。因此交叉既是交换的形态学标志，也参与中期I染色体的正确排列。","src":"《第10章 细胞分裂与细胞周期(上)》p74、p76、p80、p81"},{"id":"ed3aa4de","s":"c","g":"c08","n":"交叉互换","e":"crossing over","d":"交叉互换（crossing over）是减数分裂中同源重组的产物：母本与父本的同源染色体在减数分裂时紧密并列，二者之间发生的同源重组可产生染色体交叉互换与基因转换，形成同时含母本和父本遗传信息的杂种染色体。该过程始于Spo11与Mre11复合物催化的程序性双链断裂，再由RecA样蛋白催化链交换；随后可沿两条途径之一进行，一条经双Holliday连接体产生两条发生过互换的染色体，另一条则类似双链断裂修复反应，染色体被修复而未发生互换。","src":"MBoC 7e 印刷 p302、p303"},{"id":"62b05ac1","s":"c","g":"c08","n":"侧面捕捉","e":"lateral attachment","d":"侧面捕捉（lateral attachment）是动粒与微管最初的连接方式。纺锤体微管并非一开始就以端向方式结合动粒，显微观察表明多数初始连接是不稳定的侧面连接：动粒在外动粒动力蛋白协助下附着到经过微管的侧面，并沿微管滑动，染色体随之滑向微管的（+）末端，最终使动粒微管稳定下来；此后微管正端才被一个、再被另一个动粒以正确的端向方式捕获。侧面捕捉是前中期染色体被逐步纳入纺锤体的过渡步骤。","src":"《第10章 细胞分裂与细胞周期(上)》p37、p38；MBoC 7e 印刷 p1057"},{"id":"e2786f30","s":"c","g":"c08","n":"促有丝分裂因子","e":"mitogen","d":"促有丝分裂因子（mitogen）是一类刺激细胞分裂的胞外信号分子。这类调节细胞生长、分裂与存活的信号一般为可溶性分泌蛋白、结合于细胞表面的蛋白或胞外基质成分，按作用可分为三类：促有丝分裂因子刺激细胞分裂，主要通过触发一波G1/S-Cdk活性、解除细胞内原本阻断周期推进的负调控；生长因子促进蛋白质等大分子合成并抑制其降解，从而增加细胞质量；存活因子则通过抑制凋亡促进细胞存活。","src":"《第10章 细胞分裂与细胞周期(下)》p56；MBoC 7e 印刷 p1078"},{"id":"90421834","s":"c","g":"c08","n":"减数分裂","e":"meiosis","d":"减数分裂（meiosis）是配子形成的基础，DNA只复制一次而细胞连续分裂两次，染色体数目减半，产生单倍体配子。可分三型：配子型或终末型，见于多细胞动物和许多原生生物；合子型或起始型，见于某些原生生物、真菌和少数藻类，发生于受精之后；孢子型或中间型，见于所有高等植物和某些藻类，与配子形成和受精均无关。染色体减半的原因是同源染色体联会，每条同源染色体两条染色单体的着丝点在减数分裂I不分开、直到减数分裂II才分离，两次分裂间不复制DNA。","src":"《第10章 细胞分裂与细胞周期(上)》p69、p70、p84"},{"id":"9212949e","s":"c","g":"c08","n":"凝缩蛋白","e":"condensin","d":"凝缩蛋白（condensin）是介导染色质凝缩、形成中期染色体的蛋白复合物，属环状SMC蛋白复合体。活化的M-Cdk磷酸化condensin亚基，触发其在DNA上组装并引起染色体凝缩；condensin可利用ATP水解的能量促进DNA盘绕。它与拓扑异构酶II协同驱动染色体压缩并形成线性染色体轴，该轴富含condensin II与拓扑异构酶II；此过程与cohesin的让位相伴随，最终使每条染色体分成两条并列的姊妹染色单体。","src":"《第10章 细胞分裂与细胞周期(上)》p32、p33；MBoC 7e 印刷 p227","x":1},{"id":"f3f63a4c","s":"c","g":"c08","n":"分裂沟","e":"cleavage furrow","d":"分裂沟（cleavage furrow）是动物细胞胞质分裂时收缩环收缩使质膜内陷所形成的缢沟。环中的actin丝高度动态，排列在胞质分裂过程中不断改变；沟处不断插入新的膜以补偿胞质分裂带来的表面积增加。收缩完成后收缩环解聚，分裂沟处的质膜收窄，形成中体，中体作为两个子细胞之间的系绳保留下来，内含来自纺锤体中区反向平行微管的中央纺锤体残余。胞质分裂最后由abscission完成：中体两侧的膜被ESCRT-III聚合形成的丝缢断。","src":"MBoC 7e 印刷 p1065"},{"id":"2a7bd26d","s":"c","g":"c08","n":"分裂犁沟","e":"","d":"分裂犁沟是动物细胞有丝分裂后期质膜发生皱褶而形成的沟，其位置由有丝分裂器决定。犁沟发生在有丝分裂器长轴的垂直面上，沿犁沟在两组子染色体之间把细胞分割为二，是收缩环收缩在质膜上的形态表现。实验表明，犁沟出现初期若将细胞的有丝分裂器重置，原来的犁沟会消失，并在新的有丝分裂器位置重新形成犁沟，说明纺锤体的位置而非皮质本身决定了胞质分裂的分裂面，这也是胞质分裂与核分裂在空间上协调的机制。","src":"《第10章 细胞分裂与细胞周期(上)》p62、p63"},{"id":"d585162f","s":"c","g":"c08","n":"动粒微管","e":"kinetochore microtubule","d":"动粒微管（kinetochore microtubule）是纺锤体中连接纺锤体极与染色体动粒的微管，成束排列时称为K-fiber，负责在后期把已分离的姊妹染色单体拉向两极。其在早中期与染色体主缢痕部位的动粒复合体结合，捕捉染色体，并结合后朝相反方向拉动染色体，使染色体移向赤道板；其负端锚定于中心体，正端动态而不稳定，不断在快速伸长与收缩之间转换，从而在连接的同时容许微管聚合与解聚。","src":"《第10章 细胞分裂与细胞周期(上)》p28、p34；MBoC 7e 印刷 p1051","x":1},{"id":"7a46d478","s":"c","g":"c08","n":"卵子发生","e":"oogenesis","d":"卵子发生（oogenesis）是动物卵细胞形成的过程，分增殖期、生长期与成熟期。增殖期卵原细胞（2n）在胚胎时期增殖；生长期成为初级卵母细胞（2n），胚胎时期约有200万个，停留于粗线期与双线期；成熟期进行减数分裂，细胞数保留约40万个，第一次分裂产生一个次级卵母细胞（n）和一个第一极体（n），第二次分裂产生一个卵细胞（n）和三个第二极体（n）。最终不到500个能发育成熟，形成卵子。","src":"《第10章 细胞分裂与细胞周期(上)》p89、p91"},{"id":"c729d3ac","s":"c","g":"c08","n":"合子","e":"zygote","d":"合子（zygote）即受精卵，是由一个雄配子与一个雌配子融合形成的二倍体细胞。有性生殖中，父本与母本产生的单倍体配子（n）结合成合子，配子产生的基础是减数分裂；体细胞含两份染色体拷贝（2n），一份来自父本、一份来自母本，互为同源染色体。受精时，停滞于减数分裂II中期的卵完成第二次减数分裂，形成的单倍体卵核与单倍体精核融合成二倍体合子，随后进行最初的胚胎卵裂。","src":"《第10章 细胞分裂与细胞周期(上)》p69；《第10章 细胞分裂与细胞周期(下)》p17；MBoC 7e Glossary（PDF p1480）"},{"id":"091de97b","s":"c","g":"c08","n":"同源染色体","e":"homologous chromosome","d":"同源染色体（homologous chromosome）指二倍体细胞中某一染色体的母本拷贝与父本拷贝。体细胞含两份染色体拷贝（2n），一份来自父本、一份来自母本，二者互为同源染色体；父本来源与母本来源的染色单体互为同源染色单体，而由同一条染色体复制而来、由着丝点相连的两条染色单体则互为姊妹染色单体。减数分裂偶线期同源染色体逐步配对即联会，需要联会复合体；粗线期完全联会形成二价体或四分体；后期I同源染色体彼此分离，着丝点并不分开。","src":"《第10章 细胞分裂与细胞周期(上)》p69、p75、p82；MBoC 7e Glossary（PDF p1420）"},{"id":"6eb772b1","s":"c","g":"c08","n":"后期A","e":"anaphase A","d":"后期A（anaphase A）是染色体向两极移动的两种独立机制之一，指染色体在动粒处产生的力作用下向纺锤体极移动的阶段，可用微管去聚合假说解释，即动粒微管解聚使染色体向极移动。姊妹染色单体的分离启动后期A的染色体运动，其正常完成还依赖Cdk底物的去磷酸化，在多数细胞中这来自APC/C对cyclin的降解。不同细胞类型侧重的机制不同：胚胎细胞主要依靠微管流，酵母与脊椎动物体细胞则主要依靠动粒处产生的力。","src":"《第10章 细胞分裂与细胞周期(上)》p53、p54；MBoC 7e 印刷 p1063"},{"id":"d7859e20","s":"c","g":"c08","n":"后期B","e":"anaphase B","d":"后期B（anaphase B）是染色体向两极移动的第二种独立机制，表现为极点分离、纺锤体拉长。其一是极间微管滑动：极间微管（+）末端长度增加，由ATP供能发生微管聚合，微管亚基同时加到所有极间微管末端，使两极距离逐渐增加，重叠区的驱动蛋白沿反向平行的极性微管滑向（+）末端；其二是星体极向运动：锚定在质膜上的dynein沿星体微管滑行、向质膜方向移动，拉动两极分开。kinesin-5交联纺锤体中央的反向平行微管，把两极推开。","src":"《第10章 细胞分裂与细胞周期(上)》p53、p55、p56、p57；MBoC 7e 印刷 p1063"},{"id":"d7378692","s":"c","g":"c08","n":"周期蛋白","e":"cyclin","d":"周期蛋白（cyclin）是CDK的调节亚基，其浓度随细胞周期规律性地升高与降低，从而把CDK活性限制在适当阶段。不同cyclin都含约100个氨基酸的周期蛋白框，介导与CDK结合；有的含PEST序列介导蛋白更新，M期周期蛋白N端还有由9个氨基酸组成的破坏框，参与泛素介导的cyclinA与cyclinB降解。当中期MPF活性达到最高时，APC被激活，把泛素连到cyclinB上，cyclinB随之被蛋白酶体降解，M期后周期蛋白含量急速下降。","src":"《第10章 细胞分裂与细胞周期(下)》p40、p49、p91；MBoC 7e Glossary（PDF p1452）"},{"id":"e4a71dad","s":"c","g":"c08","n":"周期蛋白依赖性激酶","e":"cyclin-dependent kinase, Cdk","d":"周期蛋白依赖性激酶（cyclin-dependent kinase，Cdk）是Ser/Thr激酶，必须与特异cyclin以1:1非共价结合才有活性，通过磷酸化靶蛋白启动各阶段事件，是周期运行的引擎分子。以MPF为例，cyclin具结合域、为调节亚单位，CDK具激酶活性、为催化域。其活性还受磷酸化调控并被CKI抑制：KIP/CIP家族（p21、p27、p57）抑制G1和S期Cdk，Ink4家族（p16等）特异抑制cyclinD-Cdk。","src":"《第10章 细胞分裂与细胞周期(下)》p33、p36、p41"},{"id":"057a2e06","s":"c","g":"c08","n":"周期蛋白框","e":"Cyclin box","d":"周期蛋白框（Cyclin box）是各类cyclin共有的约100个氨基酸的保守同源序列，其功能是介导cyclin与Cdk结合形成活性复合物，对细胞周期的启动与时相转换进行关键性调控。不同来源的cyclin都含有这一同源序列，而周期蛋白盒与Cdk的结合正是CDK获得激酶活性的前提。除周期蛋白框外，有的cyclin还含PEST序列介导蛋白的更新，有的cyclin含破坏框，二者分别决定周期蛋白的周转与定时降解。","src":"《第10章 细胞分裂与细胞周期(下)》p36、p39"},{"id":"317582f6","s":"c","g":"c08","n":"四分体","e":"tetrad","d":"四分体（tetrad）是减数分裂前期粗线期同源染色体完全联会后形成的结构，由一对已复制的同源染色体紧密配对而成，共含四条染色单体，故又称二价体。此时染色体缩短变粗、核仁仍存在，配对由偶线期形成的联会复合体维持。四分体中非姊妹染色单体之间可形成交叉并发生交换，交叉与交叉处染色单体末端的粘连蛋白连接一起，与纺锤体两极的拉力相拮抗，使配对的同源染色体在中期I稳定排列于赤道面，为后期I同源染色体的分离作准备。","src":"《第10章 细胞分裂与细胞周期(上)》p75、p80；MBoC 7e Glossary（PDF p1447）"},{"id":"1b585085","s":"c","g":"c08","n":"复制衰老","e":"replicative senescence","d":"复制衰老（replicative senescence）指正常人体细胞体外培养时寿命有限的现象：正常人体细胞分裂25至50次后即进入复制衰老。其发生基础是培养细胞群体倍增的次数而非培养时间，倍增次数取决于供体种属、年龄与遗传背景。原因在于线性染色体的末端复制问题：子链5′端与母链3′端配对的RNA引物被切除后，子链5′端产生末端缺失，并随复制次数增加逐渐缩短，涉及端粒与端粒酶。HeLa等肿瘤细胞具遗传改变，可逃逸而永生化。","src":"《第10章 细胞分裂与细胞周期(下)》p11；《第12章 细胞衰老与细胞凋亡》p18"},{"id":"fa016d31","s":"c","g":"c08","n":"外推学说","e":"push","d":"外推学说（push）是解释染色体如何排列到赤道板的两种力学模型之一，与牵拉学说相对。该学说认为，星体的排斥力将染色体向外推，染色体距离中心体越近，星体对染色体的外推力越强；当来自两极的推力彼此平衡时，染色体即被稳定在赤道面上。实际上，中期赤道板的形成是推与拉两种力共同作用的结果：来自两极的微管最初长度不等，随着推力和拉力趋于平衡，染色体被驱动并稳定在中期盘上。","src":"《第10章 细胞分裂与细胞周期(上)》p45"},{"id":"59230f8e","s":"c","g":"c08","n":"姊妹染色单体","e":"sister chromatid","d":"姊妹染色单体（sister chromatid）指由同一条染色体复制而来、由着丝点相连的两条染色单体，属非同源染色单体。前期细胞核中，每条复制后的染色体都含一对沿长轴平行结合的姊妹染色单体，结合依赖cohesin；cohesin由Scc1、Scc3、Smc1和Smc3四个亚基组成，Smc1与Smc3为卷曲螺旋蛋白、一端具ATP和DNA结合域，可形成环状结构环绕染色单体。后期时，cohesin突然断开，各对姊妹染色单体分别移向两极。","src":"《第10章 细胞分裂与细胞周期(上)》p30、p48；MBoC 7e 印刷 p1047"},{"id":"74087d6c","s":"c","g":"c08","n":"成熟促进因子","e":"MPF","d":"成熟促进因子（MPF）是CDK与周期蛋白cyclin形成的二聚体蛋白，即M-Cdk。其中cyclin具结合域的功能、为调节亚单位，CDK具激酶活性、为催化域，典型代表为p34cdc2与cyclinB组成的复合物。海胆卵中存在一类在间期积累、在分裂期消失并随细胞周期重复的特殊蛋白质，被命名为cyclin，是诱导细胞进入M期所必需。用爪蟾卵体外成熟实验可检测MPF活性，其活性在爪蟾胚胎细胞周期中呈现振荡，是细胞周期控制系统的核心引擎分子。","src":"《第10章 细胞分裂与细胞周期(下)》p17、p19、p31、p33","x":1},{"id":"afc4c3ec","s":"c","g":"c08","n":"成膜体","e":"phragmoplast","d":"成膜体（phragmoplast）是高等植物细胞胞质分裂中引导细胞板组装的结构，由微管与肌动蛋白丝构成，形成于细胞预期的分裂面上，并衍生自有丝分裂纺锤体。植物细胞被半刚性的细胞壁包围，没有收缩环，也不具有星体微管，其细胞质是由内向外被新细胞壁分隔的：细胞板在后期晚期开始组装，由成膜体引导，马达蛋白把高尔基体来源的小膜泡运送到早期细胞板，融合形成新生细胞壁（初生壁）。","src":"《第10章 细胞分裂与细胞周期(上)》p65、p66；MBoC 7e 印刷 p1068"},{"id":"6269bddd","s":"c","g":"c08","n":"抑制性磷酸化","e":"inhibitory phosphorylation","d":"抑制性磷酸化（inhibitory phosphorylation）是调控Cdk活性的一种共价修饰：Wee1负责磷酸化Tyr15和Thr14，Cdc25负责这两个位点去磷酸化，CAK则使Thr161磷酸化。抑制性磷酸加在活性位点上方，封闭激酶活性位点，使cyclin-Cdk复合物失活；Cdc25去除这些磷酸后复合物即被激活。Cdc25不足时细胞不分裂，Wee1不足时细胞提早分裂，cdc25/wee1双突变个体则正常分裂。","src":"《第10章 细胞分裂与细胞周期(下)》p42、p43；MBoC 7e 印刷 p1034"},{"id":"78df0bb5","s":"c","g":"c08","n":"收缩环","e":"contractile ring","d":"收缩环（contractile ring）是动物细胞胞质分裂的特殊结构，由肌动蛋白actin与肌球蛋白II组成，二者在环中产生胞质分裂的动力，收缩时把两个子细胞掐开。间期细胞中，actin与myosin II在质膜下形成皮层网络，部分细胞还形成应力纤维；细胞进入有丝分裂时这些排列解体，actin重新组织、myosin II丝被释放，随后在赤道区组装成收缩环。环收缩同时质膜插入新膜补偿表面积，收缩完成后环解聚，两子细胞间狭窄的膜桥被切断。","src":"《第10章 细胞分裂与细胞周期(上)》p63；MBoC 7e 印刷 p1065"},{"id":"51699253","s":"c","g":"c08","n":"无丝分裂","e":"amitosis","d":"无丝分裂（amitosis）是不经过染色体有规律平均分配的一种直接分裂方式：核仁与核膜都不消失，不出现染色体的凝缩，也不形成纺锤体，遗传物质分配不均衡，分裂过程简单。1841年由Remak在鸡胚血细胞中发现，是最早被发现的一种细胞分裂方式，故又称Remak核分裂或直接核分裂。四膜虫的无丝分裂可作为典型示例。与有丝分裂、减数分裂相比，无丝分裂在染色体凝缩、纺锤体形成与遗传物质分配的均衡性上均明显不同。","src":"《第10章 细胞分裂与细胞周期(上)》p8、p12"},{"id":"aeddcd85","s":"c","g":"c08","n":"早熟染色体凝聚","e":"PCC (premature condensed chromosome)","d":"早熟染色体凝聚（PCC，premature condensed chromosome）是指M期细胞与间期细胞融合后，间期染色质被提前诱导凝集成染色体的现象。将M期HeLa细胞与G1、S、G2期细胞融合，即可观察到间期染色体提前凝聚，说明M期细胞中含有刺激细胞进入有丝分裂的因子。该因子即成熟促进因子MPF，为CDK与cyclin的二聚体，M期细胞富含MPF；细胞融合诱导早熟染色体凝聚因此成为细胞周期调控研究的经典证据。","src":"《细胞生物学历年考题整理》p5；《第10章 细胞分裂与细胞周期(下)》p17、p33","x":1},{"id":"aa92f422","s":"c","g":"c08","n":"星体","e":"aster","d":"星体（aster）是中心体以自身为中心向各个方向伸出放射状排列的微管所形成的一组星状结构，每个星体含一对几乎垂直排列的中心粒和一组放射状排列的纺锤体微管蛋白；微管负端锚定在中心体上，自由的正端动态而不稳定，不断发生快速伸长与收缩的转换。星体到达相对位置后，就在细胞核外形成有丝分裂纺锤体的两极。后期B中，锚定在质膜上的动力蛋白沿星体微管滑行、向质膜方向移动，驱动星体的极向运动，使两极进一步分开。","src":"《第10章 细胞分裂与细胞周期(上)》p26、p27、p57"},{"id":"a96624ae","s":"c","g":"c08","n":"星体微管","e":"astral microtubule","d":"星体微管（astral microtubule）是纺锤体微管的一种，指从星体放射而出、不与染色体动粒相连的微管。它起始于两极，并与细胞周质中的细胞骨架相结合，起到稳定星体位置的作用；后期B时，锚定在质膜上的动力蛋白沿星体微管滑行、向质膜方向移动，把两极拉向细胞皮层，参与纺锤体拉长与极点分离。并非所有细胞都有星体微管：高等植物细胞与许多脊椎动物卵母细胞没有中心体，因而也没有星体微管，说明中心体并非纺锤体组装的必需条件。","src":"《第10章 细胞分裂与细胞周期(上)》p28、p57、p66；MBoC 7e 印刷 p1051","x":1},{"id":"e47be2f8","s":"c","g":"c08","n":"有丝分裂","e":"mitosis","d":"有丝分裂（mitosis）是真核细胞最重要的分裂形式，前期、早中期、中期、后期、末期五个时期合称有丝分裂期，各期有严格的发生顺序，胞质分裂期则从后期启动、延续至末期。只有完成DNA复制与中心体复制的细胞才能进入有丝分裂期，其间核仁核膜消失与重现、纺锤体形成、染色质凝缩与去凝缩有序进行。分子上，M-Cdk等激酶磷酸化多种蛋白驱动纺锤体组装及其与姊妹染色单体的连接，APC/C降解securin与cyclin则启动染色单体分离与胞质分裂。","src":"《第10章 细胞分裂与细胞周期(上)》p13、p15、p16；MBoC 7e 印刷 p1047"},{"id":"b55b91c4","s":"c","g":"c08","n":"有丝分裂器","e":"mitotic apparatus","d":"有丝分裂器（mitotic apparatus）是纺锤体与和它结合的染色体的总称，其中纺锤体包括星体和三种纺锤丝，即星体、极间与动粒微管。极间微管的自由正端相向伸长、重叠，驱动蛋白等与之结合，连接位于两极的星体，构成纺锤体的基本构架；星体微管起始于两极并与细胞周质骨架结合以稳定星体位置；动粒微管则在早中期与染色体主缢痕处的动粒复合体结合，捕捉染色体。有丝分裂器决定胞质分裂的分裂面，染色体向两极的移动也由后期A、后期B两种机制完成。","src":"《第10章 细胞分裂与细胞周期(上)》p28、p53、p62"},{"id":"d52f626b","s":"c","g":"c08","n":"极间微管","e":"polar microtubule","d":"极间微管（polar microtubule）是纺锤体微管中数量最多的一类非动粒微管。它相对短而不稳定，密集分布于两极之间，被多种蛋白交联成动态、可调节的支架网络，为纺锤体提供结构稳定性；有些嵌入纺锤体极，许多则远离极，有时以负端附着于其他微管侧面，在赤道附近常与反向平行微管交联。后期B时，极间微管（+）末端长度增加，由ATP供能发生聚合，微管亚基同时加到所有极间微管末端，重叠区驱动蛋白沿反向平行微管滑向正端，使纺锤体拉长。","src":"《第10章 细胞分裂与细胞周期(上)》p28、p56；MBoC 7e 印刷 p1050","x":1},{"id":"cd373a3b","s":"c","g":"c08","n":"染色体不分离","e":"","d":"染色体不分离是减数分裂并非完美无缺的表现之一：同源染色体不能正确分离，使产生的单倍体细胞中，一些缺少某条染色体，另一些则多一条染色体，配子的染色体数目因而异常。典型例子是减数分裂时21号染色体不能正常分离，配子含有2个拷贝的21号染色体；这种不正常的配子与正常配子结合后，胚胎就带有3个21号染色体，即唐氏综合症。由此可见，减数分裂I同源染色体与减数分裂II姊妹染色单体的准确分离，是保证配子染色体数目正常的关键。","src":"《第10章 细胞分裂与细胞周期(上)》p87"},{"id":"5a3168db","s":"c","g":"c08","n":"染色体乘客复合物","e":"chromosomal passenger complex, CPC","d":"染色体乘客复合物（chromosomal passenger complex，CPC）是与动粒内层相连的蛋白复合物，含Aurora B激酶，参与动粒-微管连接的张力监视。当两个动粒都处于张力下时，外动粒被拉离内动粒处的CPC，Aurora B不能磷酸化外动粒成分，其中包括Ndc80复合物的微管结合位点，连接因而稳定；反之，缺乏张力时Aurora B可使这些成分磷酸化，使连接失稳并被纠正。CPC由此把张力转换为连接稳定性的信号。","src":"《第10章 细胞分裂与细胞周期(上)》p98"},{"id":"5db61ab8","s":"c","g":"c08","n":"染色粒","e":"chromomeres","d":"染色粒（chromomeres）是减数分裂前期细线期每条染色体上局部区域染色质纤维浓缩所形成的链珠状小区域。细线期染色体细长呈线状，核仁仍然存在，染色粒沿染色体长轴分布如串珠，染色体端粒与核膜相连。染色粒的出现反映了间期染色质在进入减数分裂时开始局部凝缩，是前期I早期染色体形态的重要标志；随后在偶线期，细线状的同源染色体逐步相互配对即联会，需要由蛋白质和DNA构成的联会复合体参与。","src":"《第10章 细胞分裂与细胞周期(上)》p75"},{"id":"54ddac06","s":"c","g":"c08","n":"检查点","e":"checkpoint","d":"检查点（checkpoint）是细胞周期某些关键时刻存在的一套调控机制，它调节各时相有序而适时地更迭，并使周期序列中后一个事件的开始依赖于前一个事件的完成，从而保证周期事件高度准确地完成；其监测作用在于保证基因和基因组的稳定性，而不是细胞分裂的基本条件。例如DNA复制检查点：羟基脲阻断DNA合成后，细胞被阻滞于S期；若同时加入咖啡因，检查点失效，细胞便带着未完成复制的DNA按正常日程进入M期。","src":"《第10章 细胞分裂与细胞周期(下)》p55、p63；MBoC 7e 印刷 p1062","x":1},{"id":"4e6fa471","s":"c","g":"c08","n":"泛素-蛋白酶体途径","e":"ubiquitin-proteasome system","d":"泛素-蛋白酶体途径（ubiquitin-proteasome system）是细胞周期中定时降解调控蛋白的主要机制。SCF与APC/C都是多亚基复合体，把底物泛素化后经蛋白酶体降解，从而把cyclin限制在相应周期阶段。SCF主要在间期有活性，APC主要在分裂期有活性；APC因含Cdc20或Cdh1亚基而识别不同底物，APC-Cdc20较早激活，降解securin与M-cyclin、促使中期转至后期，APC-Cdh1则促进M-G1转换。","src":"《第10章 细胞分裂与细胞周期(下)》p49、p51、p53"},{"id":"20527349","s":"c","g":"c08","n":"牵拉学说","e":"pull","d":"牵拉学说（pull）是解释染色体向赤道板运动的两种力学模型之一。该学说认为，染色体向赤道板方向运动是动粒微管牵拉的结果，动粒微管越长，拉力越大；当来自两极的动粒微管的拉力相等时，染色体即被稳定在赤道面上。与之并列的外推学说则强调星体排斥力的作用。实际上，正是推与拉两种力共同驱动染色体移向中期盘：两极来源的微管最初长度不等，随着两侧力量趋于平衡，染色体稳定排列在赤道面上。","src":"《第10章 细胞分裂与细胞周期(上)》p45"},{"id":"97330904","s":"c","g":"c08","n":"生殖细胞","e":"germ cell","d":"生殖细胞（germ cell）泛指生物体内能繁殖后代的细胞，包括原始生殖细胞和由其分裂得到的配子或孢子，可分无性生殖细胞与有性生殖细胞两类：前者经有丝分裂产生孢子或以减数分裂产生无性孢子，后者经减数分裂产生配子或以有丝分裂产生配子。有性生殖在特定的双倍体（2n）生殖细胞中发生减数分裂，产生单倍体（n）的配子，即精子或卵子；对动物而言这一过程称为精子发生或卵子发生，对异孢形植物则称为小孢子发生或大孢子发生。","src":"《第10章 细胞分裂与细胞周期(上)》p89；MBoC 7e Glossary（PDF p1457）"},{"id":"9b08c1f7","s":"c","g":"c08","n":"破坏框（降解盒）","e":"","d":"破坏框又称降解盒，是M期周期蛋白N端一段与其降解有关的特殊序列，由9个氨基酸组成，主要参与由泛素介导的cyclinA和cyclinB的降解。它的存在使M期周期蛋白能够被泛素-蛋白酶体系统识别并定时清除：当中期MPF活性达到最高时，后期促进因子APC被激活，APC负责把泛素连接到M期周期蛋白cyclinB上，cyclinB随之被蛋白酶体降解，因此M期之后周期蛋白含量急速下降，M-Cdk活性随之丧失。","src":"《第10章 细胞分裂与细胞周期(下)》p40"},{"id":"ed194165","s":"c","g":"c08","n":"类核","e":"nucleoid","d":"类核（nucleoid）是原核细胞内由基因组DNA与蛋白核共同形成的致密区域。一个简单的环状DNA分子结合在一个蛋白核上，缠绕成花束状，在细胞内形成这一致密区域；DNA形成50至100个环，环的两端固定在蛋白质核上，从而使较长的环状基因组被组织压缩在较小的空间内。类核是原核细胞区别于真核细胞成形细胞核的结构特征之一：原核细胞无核膜、无核仁，DNA不与组蛋白结合。二分裂时，环状DNA复制后细胞直接分裂，类核随遗传物质均衡分配到子细胞。","src":"《第10章 细胞分裂与细胞周期(上)》p9；《第1章 细胞与细胞生物学》p34"},{"id":"6bf49deb","s":"c","g":"c08","n":"精子发生","e":"spermatogenesis","d":"精子发生（spermatogenesis）是动物精子形成的过程，包括有丝分裂增殖与减数分裂两个阶段以及随后的成熟。精原细胞经有丝分裂分裂、分化成为A型与B型细胞，其中Ad型与Ap型作为保留的精原干细胞存在；B型细胞继续分裂分化形成初级精母细胞，后者经减数分裂产生精细胞，精细胞再经分裂、分化与成熟过程成为精子。对动物而言，由双倍体生殖细胞经减数分裂产生单倍体配子的过程即称为精子发生或卵子发生。","src":"《第10章 细胞分裂与细胞周期(上)》p89、p90"},{"id":"a7e8c2b8","s":"c","g":"c08","n":"纺锤体","e":"spindle","d":"纺锤体（spindle）是有丝分裂中由微管组装成的结构，包含动粒微管、极间微管和星体微管三种纺锤丝。动物细胞中，已复制的中心体作为微管组织中心，负责纺锤体的形成、纺锤丝微管的生长与排列、染色体的捕捉以及染色体向两极移动等重要事件；中心体移向相对位置后，在细胞核外形成纺锤体的两极。微管负端锚定在中心体上，自由的正端动态而不稳定，不断在快速伸长与收缩之间转换，这种动态性使纺锤体既能搜索并捕获染色体，又能在后期缩短或延长。","src":"《第10章 细胞分裂与细胞周期(上)》p25、p27、p94","x":1},{"id":"0b138cf2","s":"c","g":"c08","n":"纺锤体","e":"mitotic spindle","d":"有丝分裂纺锤体（mitotic spindle）是在真核细胞有丝分裂中形成的双极微管阵列及其结合分子，其作用是先把已复制的染色体排列到赤道面，再把姊妹染色单体分别分配到相反的两极。它由星体与三种纺锤丝即星体微管、极间微管和动粒微管组成，微管负端锚定在中心体上、正端动态伸缩，通过不断聚合与解聚搜索并捕获染色体动粒。M-Cdk等激酶磷酸化多种蛋白，驱动纺锤体组装及其与姊妹染色单体的连接。","src":"《第10章 细胞分裂与细胞周期(上)》p27、p28；MBoC 7e 印刷 p1047；MBoC 7e Glossary（PDF p1465）"},{"id":"f68108ab","s":"c","g":"c08","n":"纺锤体检查点","e":"spindle checkpoint","d":"纺锤体检查点（spindle checkpoint）监控动粒与微管的连接：动粒未连接微管时，Mad2与Bub1结合并抑制Cdc20，使APC/C不能泛素化securin，separase不被释放，后期延迟至所有染色体排列到赤道板。其信号链为APC/C-securin-separase-cohesin。检查点关闭后，APC/C泛素化securin与M期周期蛋白，separase释放并切割cohesin的Scc1亚基，姊妹染色单体分离。","src":"《第10章 细胞分裂与细胞周期(上)》p49、p51、p97","x":1},{"id":"93b127aa","s":"c","g":"c08","n":"纺锤体检查点","e":"spindle-attachment checkpoint","d":"纺锤体附着检查点（spindle-attachment checkpoint）动粒未与微管连接时，动粒上的Mad2与Bub1结合并抑制Cdc20，从而延迟后期启动，直至所有染色体排列在赤道板上。Mad2与Bub1位于前期与前中期的动粒上，可使动粒敏化、促使微管与动粒接触；染色体被捕捉后二者即消失。其效应途径是：securin作为后期抑制因子被降解后释放separase，separase再切割cohesin复合物，使姊妹染色单体得以分开。","src":"《第10章 细胞分裂与细胞周期(上)》p49；《第10章 细胞分裂与细胞周期(下)》p71"},{"id":"19fdbce7","s":"c","g":"c08","n":"细胞分裂","e":"cell division","d":"细胞分裂（cell division）是一个细胞通过核分裂和胞质分裂产生两个或者多个细胞的过程，目前仍是生物体产生新细胞的唯一来源。它既包括核的物质分配，也包括胞质的划分，二者在时间上相互配合：胞质分裂期从有丝分裂的后期启动，延续至末期。一次分裂结束到下一次分裂结束所经历的时间称为细胞周期，一般真核细胞周期为18至24小时，其中G1期变动最大；早期胚胎的细胞周期最短，没有G1和G2期。","src":"《第10章 细胞分裂与细胞周期(上)》p7；《第10章 细胞分裂与细胞周期(下)》p6"},{"id":"0967fbe4","s":"c","g":"c08","n":"细胞分裂周期基因","e":"cdc genes","d":"细胞分裂周期基因（cdc genes）是控制细胞分裂周期进程的一类基因，其温度敏感突变体在限制温度下会停滞于细胞周期的特定阶段，从而把周期过程分解为可研究的步骤。Hartwell以酿酒酵母为材料，系统鉴定并表征了cdc突变体（cell-division cycle mutants），并据此提出检查点概念；Nurse以裂殖酵母为材料研究cdk（周期蛋白依赖性蛋白激酶），Hunt则在海胆中鉴定cyclin（Cdk的调节因子）。","src":"《第10章 细胞分裂与细胞周期(下)》p21、p22、p28"},{"id":"deac1b53","s":"c","g":"c08","n":"细胞分裂间期","e":"interphase","d":"细胞分裂间期（interphase）是两次M期之间的时期，包括DNA合成前期（G1期）、DNA合成期（S期）和DNA合成后期（G2期）。间期细胞完成DNA复制、中心体复制和细胞体积增大等事件，只有完成了DNA和中心体复制的细胞才能够进入有丝分裂期。间期与分裂期共同构成细胞周期：M期包括有丝分裂与胞质分裂，间期的核心任务是准确复制染色体中的DNA，确保复制品分配到遗传物质相同的子细胞中；G1期还可延迟、进入G0或越过限制点。","src":"《第10章 细胞分裂与细胞周期(上)》p14、p15；《第10章 细胞分裂与细胞周期(下)》p2；MBoC 7e Glossary（PDF p1461）"},{"id":"0d10a4ed","s":"c","g":"c08","n":"细胞同步化","e":"synchronization","d":"细胞同步化（synchronization）是使不同时相的细胞群体停滞于周期同一时相的技术。天然同步化见于多数无脊椎动物和少数脊椎动物的早期胚胎，如早期果蝇胚胎中细胞核在细胞质内同步分裂。人工同步化分选择同步化与药物诱导同步化：前者利用M期细胞变圆易脱落的特点，将贴壁细胞按间隔振荡、收集脱落的M期细胞离心沉淀，同步化程度高且不受药物伤害，但数量少，也可用密度梯度离心按体积和质量差别分离；后者用TdR双阻断法把细胞阻断在G1/S交界处。","src":"《第10章 细胞分裂与细胞周期(下)》p10；《第10章 细胞分裂与细胞周期(下)》p12"},{"id":"43c4539a","s":"c","g":"c08","n":"细胞周期","e":"cell cycle","d":"细胞周期（cell cycle）是细胞复制其内含物后分裂为两个子细胞的有序事件序列，是所有生物繁殖的基本机制。单细胞生物一次分裂即产生一个完整新个体；多细胞生物需长而复杂的连续分裂才能形成有功能个体，成年体内也需分裂补充死亡细胞。过程上分为分裂期（M期）与间期，间期含G1、S、G2三期。其运行受CDK与周期蛋白构成的MPF等周期引擎分子调控，并受癌基因产物与Rb、p53等抑癌基因产物正负调节。","src":"《思维导图》p6；MBoC 7e 印刷 p1027"},{"id":"d4d52581","s":"c","g":"c08","n":"细胞周期时间","e":"cell cycle time","d":"细胞周期时间（cell cycle time）指细胞从一次分裂结束到下一次分裂结束所经历的时间。真核细胞一般TC为18～24小时，其中G1期约12～16小时、S期约6～8小时、G2期约3～4小时、M期小于1小时，G1期持续时间变化最大。不同细胞类型与发育阶段差别明显，最短的真核细胞周期见于早期胚胎，这类周期缺少G1和G2期，细胞在S期与M期之间快速交替，短时间内完成大量卵裂。测定周期时间与细胞同步化是研究各时相变化与调控的基础。","src":"《第10章 细胞分裂与细胞周期(下)》p6"},{"id":"7a307518","s":"c","g":"c08","n":"细胞周期蛋白依赖性激酶","e":"CDK","d":"周期蛋白依赖性激酶（CDK）是约300个氨基酸的小分子蛋白激酶，需与周期蛋白以1∶1比例非共价结合才能激活。不同cyclin只在其所促进的时相表达并激活不同CDK；cyclin水平主要经泛素-蛋白酶体系统降解而限定于相应时相。CDK活化还需CAK磷酸化Thr161、Cdc25去除抑制性磷酸化，Wee1的磷酸化则抑制其活性；M期CDK活化中Cdc25可被M-CDK激活形成正反馈。细胞内p21、p27、p16等CKI对CDK起负调控作用。","src":"《第10章 细胞分裂与细胞周期(下)》p36、p70；MBoC 7e 印刷 p1034","x":1},{"id":"74d7d451","s":"c","g":"c08","n":"细胞板","e":"cell plate","d":"细胞板（cell plate）是分裂的植物细胞中由高尔基体小泡融合形成的扁平膜性结构，是新生细胞壁的前体。植物细胞胞质分裂无星体微管，成膜体由有丝分裂纺锤体衍生，马达蛋白沿其微管把高尔基体小泡运向细胞中央；小泡富含合成新细胞壁所需的多糖和糖蛋白，融合成盘状早期细胞板，再靠不断融合向外扩展，直至抵达质膜与原细胞壁把细胞一分为二。随后纤维素微纤丝沉积于其基质，完成初生壁构建。组装始于后期末并由成膜体引导。","src":"《第10章 细胞分裂与细胞周期(上)》p65、p66；MBoC 7e 印刷 p1069"},{"id":"17804eaf","s":"c","g":"c08","n":"终末分化细胞","e":"terminally differentiated cells","d":"终末分化细胞（terminally differentiated cells）是高度特化、已丧失分裂能力直至死亡的细胞，如肌肉细胞、红细胞和神经细胞。按周期状态机体细胞分三类：持续分裂的干细胞、平时不分裂但受刺激后可再分裂的G0细胞和终末分化细胞。细胞分化可视为全能性逐渐丧失的过程，顺序为受精卵、胚胎干细胞、组织特异干细胞、终末分化细胞前体细胞，最终成为终末分化细胞；更新组织中干细胞分裂产生这类细胞，二者遗传相同而分化状态不同。","src":"《第10章 细胞分裂与细胞周期(下)》p9；MBoC 7e 印刷 p1170"},{"id":"24a4245e","s":"c","g":"c08","n":"联会","e":"synapsis","d":"联会（synapsis）是减数分裂前期同源染色体逐步相互配对的过程。它始于偶线期，细线状的同源染色体沿全长彼此靠近配对，成熟于粗线期，此时染色体完全联会、缩短变粗，配对的同源染色体含两条姐妹染色单体，称二价体或四分体；消失于双线期，联会复合体解聚，非姐妹染色单体间的交换点才以交叉形式显现。联会需由蛋白质和DNA构成的联会复合体，其形成与偶线期DNA即Zyg-DNA有关。联会使同源染色体准确配对并完成交换，是染色体数目减半的前提。","src":"《第10章 细胞分裂与细胞周期(上)》p75、p77；MBoC 7e 印刷 p1074","x":1},{"id":"161071aa","s":"c","g":"c08","n":"联会复合体","e":"synaptonemal complex, SC","d":"联会复合体（synaptonemal complex，SC）是减数分裂前期同源染色体联会时由蛋白质和DNA构成的精巧结构，主要作为支架使相互作用的染色单体完成交换。它发生于偶线期、成熟于粗线期、消失于双线期。电镜下SC呈梯子状：两侧为电子密度很高、约40 nm的侧生组分，中间是宽约100 nm的明亮中间区，中央为宽约30 nm的中央组分，粗线期可见侧生组分与中央组分构成的三元结构。SC形成与偶线期DNA即Zyg-DNA有关。","src":"《第10章 细胞分裂与细胞周期(上)》p79、p77"},{"id":"02240b11","s":"c","g":"c08","n":"肌生成抑制素","e":"myostatin","d":"肌生成抑制素（myostatin）是TGFβ家族成员，能特异性抑制成肌细胞的生长与增殖，而成肌细胞是融合形成骨骼肌巨大多核细胞的前体细胞。该信号由肌肉组织自身产生，随肌肉形成增多而水平升高，最终关闭肌肉生长，构成简单的器官大小反馈机制。其重要性可见于基因缺失的后果：Myostatin基因被删除后，突变小鼠的肌肉可比正常增大数倍；两种为获大肌肉而选育的牛及一种犬也带有该基因突变。可见它是抑制增殖的胞外信号分子。","src":"MBoC 7e 印刷 p1273"},{"id":"d2f476e4","s":"c","g":"c08","n":"胞质分裂","e":"cytokinesis","d":"胞质分裂（cytokinesis）是母细胞胞体一分为二、把细胞质分给两个子细胞的过程，与核分裂即mitosis相区别，属M期的一部分。它一般开始于后期，分裂面取向与所需时间取决于有丝分裂器。动物细胞由收缩环驱动，环中肌动蛋白与肌球蛋白Ⅱ产生分裂所需的力，在赤道处形成分裂沟并缢缩。植物细胞无星体微管，靠成膜体引导高尔基体小泡在赤道面融合形成细胞板，进而建成新细胞壁。部分细胞有丝分裂而无胞质分裂，形成多核细胞。","src":"《第10章 细胞分裂与细胞周期(上)》p61、p63；MBoC 7e 印刷 p1064"},{"id":"4783641a","s":"c","g":"c08","n":"胸腺嘧啶核苷双阻断法","e":"TdR double-block","d":"胸腺嘧啶核苷双阻断法（TdR double-block）是药物诱导细胞同步化的常用方法。其原理是用低毒或无毒的DNA合成抑制剂特异地抑制DNA合成，而不影响其他时期细胞继续运转，从而把细胞抑制在DNA合成期，即阻断在G1/S交界处。经两次阻断与释放，可使分散于各时相的细胞集中停留于G1/S交界处，洗去药物后同步进入S期，获得较高比例的同步化细胞。与秋水仙素抑制微管聚合使细胞停滞于中期一样，该法通过干扰周期运转实现同步化。","src":"《第10章 细胞分裂与细胞周期(下)》p13"},{"id":"cc9ee6f7","s":"c","g":"c08","n":"赤道板","e":"metaphase plate","d":"赤道板（metaphase plate）是与纺锤体两极等距、垂直于纺锤体轴的假想平面，中期染色体即排列于此。前中期核膜解体后，具自由正端的动粒微管随机试探并与动粒结合，捕获染色单体并不断将其移向赤道板；染色体被两极牵拉来回摆动，最终停在距两极等距处。其稳定有牵拉与外推两说：前者认为动粒微管越长拉力越大，两极拉力相等时染色体被稳定；后者认为星体排斥力把染色体外推，两极推力平衡时即稳定。脊椎动物细胞中染色体到达后仍轻微振荡，等待分离信号。","src":"《第10章 细胞分裂与细胞周期(上)》p43、p45；MBoC 7e 印刷 p1059"},{"id":"64bb0a2d","s":"c","g":"c08","n":"重组节","e":"recombination nodules","d":"重组节（recombination nodules）是联会复合体上相当于交换发生位点的结构，含酶装置，能促进在粗线期末完成的遗传重组。电镜下联会复合体呈梯子状：两侧为电子密度很高、约40 nm的侧生组分，中间是宽约100 nm的明亮中间区，中央为宽约30 nm的中央组分，横向排列着粗约7～10 nm的SC纤维。重组节分布于这一结构之上，与同源染色体非姐妹染色单体间的交换相对应，可作为形态学标志，把联会复合体的装配与遗传重组联系起来。","src":"《第10章 细胞分裂与细胞周期(上)》p79"},{"id":"a84c784e","s":"c","g":"c08","n":"限制点","e":"restriction point","d":"限制点（restriction point）是动物细胞G1期末的重要转换点，相当于裂殖酵母的Start点，属G1期检验点。细胞在G1期推进中依内部与外部条件作出选择：延迟G1、进入称G0的静息状态，或越过限制点进入S期；一旦越过即被决定进入S期，因此它把细胞对内外条件的判断同是否继续分裂联系起来。若DNA受损，细胞必须在此类检验点暂停以修复或走向凋亡。此外还有S期检验点，核查DNA是否只复制一次，共同保证周期有序进行。","src":"《第10章 细胞分裂与细胞周期(下)》p56；MBoC 7e Glossary（PDF p1473）"},{"id":"e81b412b","s":"c","g":"c08","n":"黏连蛋白","e":"cohesin","d":"黏连蛋白（cohesin）是连接已复制DNA分子、确保有丝分裂中染色体准确分离的蛋白复合物。G1期与染色体侧面结合；DNA复制时紧随复制叉之后被转变为能持住姐妹染色单体的黏连分子；G2期至前期之间，除着丝粒区外被去除。中期姐妹染色单体靠它相连，此时separase活性受CDK磷酸化与securin结合抑制；纺锤体检验点确认动粒正确连接微管后，Cdc20指导APC/C降解securin，separase被释放、切割黏连蛋白，启动后期分离。","src":"《第10章 细胞分裂与细胞周期(上)》p31、p51；MBoC 7e 印刷 p225","x":1},{"id":"54276aae","s":"c","g":"c11","n":"DNA甲基化","e":"DNA methylation","d":"DNA甲基化（DNA methylation）是在DNA上添加甲基的共价修饰，在脊椎动物中主要发生于胞嘧啶，且大多位于CG序列，生成5-甲基胞嘧啶，不影响碱基配对。植物和动物都借助CG序列中胞嘧啶的广泛甲基化使基因保持失活，因此它是重要的表观遗传调控方式。在脊椎动物细胞中，胞嘧啶甲基化为基因表达模式传给子代细胞提供机制，使不依赖DNA序列改变的细胞记忆得以在多次分裂后维持。长链非编码RNA也可通过促进启动子DNA甲基化实现转录干扰。","src":"《第4章 核糖体》p85、p95；MBoC 7e 印刷 p435"},{"id":"7b1f4adc","s":"c","g":"c11","n":"HMG框","e":"HMG box","d":"HMG框（HMG box）是高迁移率族蛋白中的一种DNA结合基序。含HMG框的转录因子属构建因子，即具有HMG框结构的转录因子，它们通过弯折DNA改变其空间走向，促进与邻近位点相结合的其他转录因子之间的相互作用，从而激活转录。这类因子往往不直接启动转录，而作为辅助成分把相距较远的调控蛋白在空间上聚拢，形成有活性的调控组合。因此HMG框的意义在于赋予转录因子改变DNA构型的能力，使启动子与增强子上多个因子的协同得以实现。","src":"《第8章 细胞核与染色体》p46","x":1},{"id":"65cc6c19","s":"c","g":"c11","n":"MyoD","e":"MyoD","d":"MyoD是在成肌细胞分化为骨骼肌细胞过程中的关键性调控蛋白。将MyoD转入体外培养的成纤维细胞中表达，可使细胞表现出骨骼肌细胞的特征，如合成大量肌动蛋白和肌球蛋白，在质膜上产生对神经信号敏感的受体蛋白和离子通道蛋白，并融合成肌细胞样的多核细胞。其原理是成纤维细胞已具备肌细胞特异性基因表达所需的其他必要调控蛋白，加入MyoD即形成启动肌细胞分化的特异调控蛋白组合。可见组合调控中单个关键调控蛋白的表达有时足以改变细胞类型。","src":"《第11章 细胞分化与基因表达调控》p44；MBoC 7e 印刷 p428"},{"id":"d36f224b","s":"c","g":"c11","n":"Polycomb复合物","e":"Polycomb complex","d":"Polycomb复合物（Polycomb complex）是Polycomb群蛋白形成的转录抑制复合物，主要通过组蛋白修饰介导沉默，分PRC1与PRC2。PRC2的EZH2经SET结构域催化组蛋白H3第27位赖氨酸三甲基化（H3K27me3），该修饰是基因抑制标志；PRC1中的CBX蛋白识别并结合H3K27me3而被招募到靶基因启动子，进而催化组蛋白H2A第119位赖氨酸单泛素化，使染色质压缩、RNA聚合酶Ⅱ停滞，基因被锁定于沉默状态。","src":"网络补充：nature.com（Roles of the Polycomb group proteins in stem cells and cancer）；pmc.ncbi.nlm.nih.gov"},{"id":"5b5fe7db","s":"c","g":"c11","n":"TATA框","e":"TATA box","d":"TATA框（TATA box）是许多真核基因启动子区的一段短DNA序列，主要由T和A组成，通常位于转录起始点上游约30个核苷酸处，是RNA聚合酶Ⅱ启动子最重要的起始信号之一。转录起始时RNA聚合酶并不直接识别启动子，而依赖通用转录因子；TFIID由TBP和TBP结合因子组成，其TBP识别并结合TATA框，结合后引起局部DNA变形，作为标识促进后续蛋白在启动子上集结，逐步组装前起始复合物。最简单的启动子即由TATA框与转录起始位点构成。","src":"《第11章 细胞分化与基因表达调控》p90、p92；MBoC 7e 印刷 p332"},{"id":"855ec842","s":"c","g":"c11","n":"hnRNA","e":"hnRNA","d":"hnRNA即异质性核RNA（heterogeneous nuclear RNA），是RNA聚合酶Ⅱ在核质中合成的转录产物，被视为mRNA的前体。三种RNA聚合酶分工明确：聚合酶Ⅰ在核仁中合成rRNA，聚合酶Ⅱ在核质中合成hnRNA-mRNA，聚合酶Ⅲ在核质中合成tRNA和snRNA。hnRNA须经加帽、加尾和剪接，并与多种RNA结合蛋白形成RNP后才能出核，mRNA的5′端先通过核孔复合体。可见hnRNA是走向成熟mRNA的中间形式。","src":"《第11章 细胞分化与基因表达调控》p89；《第8章 细胞核与染色体》p26"},{"id":"22475c68","s":"c","g":"c11","n":"永生化链假说","e":"immortal strand hypothesis","d":"永生化链假说（immortal strand hypothesis）由Cairns于1975年提出，认为成体干细胞在不对称分裂时不随机分配姐妹染色单体，而是选择性保留作为模板的旧DNA链，把新合成的链分给走向分化的子细胞。由于DNA复制可能引入错误，保留旧模板可使干细胞基因组中累积的复制错误降到最低。该假说常以脉冲-追踪标记实验检验：用氚标记胸腺嘧啶或BrdU标记DNA，若干细胞长期保留标记而成为标记滞留细胞，则提示模板链被选择性保留。","src":"网络补充：sciencedirect.com（The Immortal Strand Hypothesis: Segregation and Reconstruction）；nature.com"},{"id":"7f3c0840","s":"c","g":"c11","n":"mediator","e":"mediator","d":"中介体（mediator）是真核细胞中的大型蛋白复合物，通过不同结构域结合多种蛋白，对共同结合其上的RNA聚合酶Ⅱ与通用转录因子起调控作用，把激活因子接收的信号传递给转录起始装置。真核DNA包装成核小体并形成高级染色质结构，因此体内转录起始比在纯化DNA上更复杂，除激活因子外还需中介体与染色质修饰蛋白参与。用纯化蛋白和DNA得到的离体模型并不完整；在细胞中三者协同，才能使前起始复合物在启动子上有效装配并起始转录。","src":"MBoC 7e 印刷 p334；《普通班作业汇总》p6"},{"id":"dab66630","s":"c","g":"c11","n":"短暂扩充细胞","e":"transit amplifying cells","d":"短暂扩充细胞（transit amplifying cells）是已定向分化、在完成分化前经历有限次数较快分裂的细胞。许多组织的干细胞分裂十分稀少，它们产生短暂扩充细胞，由后者有限增殖以扩增细胞数量，再终末分化形成特化细胞，这是许多组织实现细胞更新的方式。肿瘤中也有类似组织形式：由少量能自我更新的肿瘤干细胞与大量由其衍生、分裂活跃但自我更新能力有限的短暂扩充细胞构成。因此致癌突变可经导致其过度增殖或抑制其终末分化与死亡而扰乱分化程序。","src":"《第11章 细胞分化与基因表达调控》p30；《第14章 癌细胞》p60；MBoC 7e 印刷 p1171"},{"id":"4dc311c0","s":"c","g":"c11","n":"上皮-间质转化","e":"EMT (Epithelial-Mesenchymal Transition)","d":"上皮-间质转化（EMT）是上皮细胞在正常发育及各种生理、病理条件刺激下，结构与功能向间质细胞转分化的现象，细胞由具紧密连接和极性的上皮表型，转变为无极性、活动力强并能产生细胞外基质的间质细胞。胚胎早期发育中，EMT存在于整个胚层分化发育进程，上皮样与间充质样细胞间的形态转变包括EMT与反向的MET，是决定胚胎发育成功的重要环节。EMT不仅是胚胎发育的基本过程，也是伤口愈合、器官纤维化及恶性上皮肿瘤发生的基础。","src":"《第11章 细胞分化与基因表达调控》p75"},{"id":"35d67c8e","s":"c","g":"c11","n":"亚全能干细胞（多潜能干细胞）","e":"pluripotent stem cells","d":"亚全能干细胞又称多潜能干细胞（pluripotent stem cells），指囊胚期内细胞群的细胞。胚泡腔内一侧聚集着一群形态不规则的细胞，称内细胞群；这些细胞具备分化成三个胚层所有细胞类型的能力，即可形成内胚层、中胚层和外胚层，但已失去发育成完整个体的能力，故称亚全能或多潜能干细胞。用显微操作分离内细胞群可制备胚胎干细胞。将Oct4、Sox2、c-Myc和Klf4四种转录因子基因引入小鼠成纤维细胞，可诱导其转化为诱导性多能干细胞。","src":"《第11章 细胞分化与基因表达调控》p22、p65"},{"id":"16cc6355","s":"c","g":"c11","n":"全能干细胞","e":"totipotential stem cell","d":"全能干细胞（totipotential stem cell）是最原始的干细胞，具有自我更新、高度增殖和多向分化发育成为组织细胞甚至形成完整个体的分化潜能。按分化潜能可把干细胞分为全能、亚全能（多潜能）、多能和单能干细胞，哺乳动物中只有受精卵是全能干细胞。随发育，细胞分化可视为全能性逐渐丧失的过程，顺序为受精卵、胚胎干细胞、组织特异干细胞、终末分化细胞前体细胞至终末分化细胞。细胞全能性则指细胞经分裂分化后在一定条件下发育成完整个体的潜能。","src":"《第11章 细胞分化与基因表达调控》p21、p22"},{"id":"9562a801","s":"c","g":"c11","n":"决定子（细胞命运决定子）","e":"","d":"决定子即细胞命运决定子，是影响卵裂细胞向不同方向分化的细胞质成分，源于受精卵细胞质的不均一性。由于卵裂后的细胞所携带的信息从一开始就不同，细胞质决定子的定位与不对称分裂可使细胞彼此产生差异，这种与分化相关的“决定”信息可上溯到受精卵。如果蝇的Prospero、Numb、Miranda等蛋白在分裂中不均等分配到两个子细胞，从而决定子细胞命运。因此决定子的不对称分配是非对称分裂的内在机制之一，与干细胞壁龛等外在机制共同调节干细胞更新与分化。","src":"《第11章 细胞分化与基因表达调控》p35"},{"id":"5df92196","s":"c","g":"c11","n":"分子杂交技术","e":"","d":"分子杂交技术是检测基因及其表达产物RNA的实验技术，常用于证明不同分化细胞中基因的差异表达。其策略是以已知序列的核酸探针与样品中的同源序列配对。检测细胞总DNA用Southern杂交，判断基因是否存在；检测总RNA用Northern杂交，判断基因是否转录。例如输卵管细胞、成红细胞和胰岛细胞中，卵清蛋白基因、β-珠蛋白基因和胰岛素基因在三者的总DNA中均存在，但对应mRNA只分别出现在相应细胞，说明差别在于表达而非基因丢失。","src":"《第11章 细胞分化与基因表达调控》p4"},{"id":"bef8d69e","s":"c","g":"c11","n":"剪接体","e":"spliceosome","d":"剪接体（spliceosome）是完成真核细胞前体mRNA剪接的大型RNA-蛋白复合体，由小分子核RNA（snRNA）及一系列相关蛋白因子组成，小RNA与蛋白因子结合后形成snRNP。组成核内剪接体的snRNA为U1、U2、U4、U5和U6。剪接体是复杂而动态的机器：离体可见少数组分先装配，随反应推进新组分进入而完成任务的组分被释放；许多研究者认为细胞内剪接体是全部组分预存的松散装配体，以协调的整体捕获、剪接并释放RNA。","src":"《第11章 细胞分化与基因表达调控》p109；MBoC 7e 印刷 p343"},{"id":"a8167c7b","s":"c","g":"c11","n":"化生","e":"metaplasia","d":"化生（metaplasia）是机体的一种组织由于细胞生活环境改变或理化因素刺激，在形态和机能上变为另一种组织的过程，属机体的一种适应现象，并且可逆。从细胞层面看，化生是某一组织类型的干细胞或祖细胞转变成了另一组织类型的祖细胞。化生在人类病理中常见，往往发生于长期受创伤、感染或异常激素刺激而不断再生的组织，如胃黏膜出现肠型杯状细胞的化生。化生需与转分化即一种分化细胞直接变成另一种分化细胞相区别，二者常被一起讨论。","src":"《第11章 细胞分化与基因表达调控》p72、p74"},{"id":"68bd4f68","s":"c","g":"c11","n":"单能干细胞","e":"monopotential stem cell","d":"单能干细胞（monopotential stem cell）又称定向干细胞，来自多能干细胞，具有向特定细胞系分化的能力，只能分化为一种类型的细胞，自我更新能力有限，故也称祖细胞。按分化潜能划分，干细胞依次为全能、亚全能（多潜能）、多能和单能干细胞，分化潜能逐级变窄。由定向干细胞最终形成特化细胞类型的过程称为终末分化。单能干细胞是分化链条中承上启下的环节：它已确定方向，经有限分裂产生前体细胞，再由其完成终末分化。","src":"《第11章 细胞分化与基因表达调控》p29"},{"id":"934c3089","s":"c","g":"c11","n":"去分化","e":"","d":"去分化是指分化细胞失去其特有结构、变成未分化细胞的过程。它与转分化相区别：转分化是一种类型的分化细胞转变成另一种类型分化细胞的现象，包括去分化与再分化两个过程，也可直接转分化而不经去分化。去分化意味着已特化的细胞在一定程度上撤除原有分化状态，是细胞可塑性的表现。在病理条件下，终末分化细胞以及肿瘤细胞的去分化都具有转化成肿瘤干细胞的能力，这与肿瘤干细胞和成体干细胞的相似性有关，故去分化也与肿瘤发生密切相关。","src":"《第11章 细胞分化与基因表达调控》p69；《第14章 癌细胞》p62"},{"id":"c0355674","s":"c","g":"c11","n":"反式作用因子","e":"trans-acting factor","d":"反式作用因子（trans-acting factor）是由某一基因表达产生的蛋白质因子，它通过与另一基因的特异顺式作用元件相互作用调节该基因表达，这种调节称反式调节。与之相对，顺式作用元件是可影响自身基因表达活性的DNA序列，包括启动子、增强子和沉默子（绝缘子），是真核基因转录的调节者。由于反式作用因子由基因编码、可扩散到核内并识别特定DNA序列，一个因子能调控多个靶基因；同一基因调控区又可集合多个因子结合位点，二者共同构成调控网络。","src":"《第11章 细胞分化与基因表达调控》p99"},{"id":"19051b29","s":"c","g":"c11","n":"可变剪接","e":"alternative splicing","d":"可变剪接（alternative splicing）是同一基因转录形成的初级RNA经不同的剪切和连接方式形成不同RNA的过程。常见方式包括外显子跳跃、内含子保留和剪切位点改变，结果是一个基因可转录产生多个不同的成熟mRNA，进而产生多个不同功能的蛋白质。当转录本多个位置都存在剪接可能时，一个基因可产生数十种蛋白质；极端的例子是单个果蝇基因理论上可产生多达38000种蛋白质。蛋白质复杂性可超过基因数目，不能把基因数目等同于生物体复杂程度。","src":"《第11章 细胞分化与基因表达调控》p114；MBoC 7e 印刷 p447"},{"id":"bd365d5d","s":"c","g":"c11","n":"可变剪接","e":"alternative RNA splicing","d":"可变剪接（alternative RNA splicing）指同一基因经不同剪接方式产生不同RNA的过程。真核基因的初级转录本含内含子与外显子，剪接体去除内含子时，若对两个或更多备选的5′与3′剪接位点配对无法明确区分，就会在不同单个转录本上作出不同选择，产生该基因编码蛋白的几种版本，这种组成型可变剪接发生在所有表达该基因的细胞中。当多个位置都存在剪接可能时，一个基因可产生数十种蛋白质。可变剪接在芽殖酵母中少见，在果蝇等生物中十分普遍。","src":"《第11章 细胞分化与基因表达调控》p114；MBoC 7e 印刷 p447"},{"id":"0486e629","s":"c","g":"c11","n":"同源异型基因","e":"homeotic gene","d":"同源异型基因（homeotic gene）常被称为主控调节基因，是参与发育模式与发育序列的基因。这类基因含高度保守的180 bp DNA序列，称同源框，可形成螺旋-转角-螺旋结构，启动基因表达。它们在胚胎发育中的表达水平对组织和器官形成有重要调控作用；若发生突变，就会在胚胎发育过程中导致某一器官异位生长。由于同源异型基因决定身体各部分的位置属性，其表达模式的改变足以改变器官的形态与位置，被视为发育调控层级上端的关键基因。","src":"《第11章 细胞分化与基因表达调控》p43"},{"id":"d9d520d3","s":"c","g":"c11","n":"启动子","e":"promoter","d":"启动子（promoter）一般位于结构基因5′端上游，是RNA聚合酶结合位点周围的一组转录控制组件，属顺式作用元件。它具有严格方向性，能指导RNA聚合酶与模板正确结合并启动转录。最简单的启动子由TATA框和转录起始位点构成，典型启动子常在TATA框上游还含GC框和/或CAAT框；有些基因的启动子不含TATA框，往往有多个转录起始位点，有时还富含GC。增强子常与启动子连环或重叠，有时二者过于接近而难以区分。不同启动子序列差异决定其强度。","src":"《第11章 细胞分化与基因表达调控》p89、p90、p94；MBoC 7e 印刷 p330"},{"id":"cca149ae","s":"c","g":"c11","n":"增强子","e":"enhancer","d":"增强子（enhancer）是增强基因转录的顺式作用元件。常与启动子连环或重叠，有时二者过于接近，难以在空间和功能上明确区分，故有“时空特异性启动子”之说。真核基因的顺式作用元件包括启动子、增强子和沉默子（绝缘子）：启动子位于基因5′端上游并具严格方向性，指导RNA聚合酶结合模板并起始转录，增强子则提高转录水平。增强子可在距基因较远的位置发挥作用，这与调控蛋白跨越很长DNA片段、使中间DNA成环有关，绝缘子则防止不同基因调控区相互干扰。","src":"《第11章 细胞分化与基因表达调控》p88、p94"},{"id":"f93d4fa8","s":"c","g":"c11","n":"多能干细胞","e":"multipotent stem cells","d":"多能干细胞（multipotent stem cells）是可分为不同类型细胞、但不能分化出足以构成完整个体的所有细胞的干细胞，如造血干细胞、神经干细胞、肠干细胞和间充质干细胞。它们属成体干细胞，维持组织细胞更新。按分化潜能可将干细胞分为全能、亚全能（多潜能）、多能和单能干细胞，潜能变窄。多能干细胞由亚全能干细胞衍生，又可产生单能干细胞即定向干细胞，后者只能分化为一种细胞且自我更新能力有限。小肠上皮多种细胞即由隐窝底部多能干细胞生成。","src":"《第11章 细胞分化与基因表达调控》p23；MBoC 7e 印刷 p1283"},{"id":"fbdfe235","s":"c","g":"c11","n":"奢侈基因","e":"","d":"奢侈基因又称组织特异性基因，是仅在特殊细胞中表达的基因，其产物为细胞或组织特异的蛋白质，赋予不同细胞类型各自的结构与功能特征。与之相对，管家基因在所有细胞类型中表达并为其所必需。早期认为管家基因数量较多，随着高通量技术的应用，发现大多数基因实为组织特异性基因，仅约3%为管家基因。因此细胞分化的分子基础不在基因的丢失或获得，而在不同细胞中奢侈基因的选择性表达，即组织特异性基因按特定组合被激活。","src":"《第11章 细胞分化与基因表达调控》p42"},{"id":"87d2aa0f","s":"c","g":"c11","n":"干细胞","e":"stem cells","d":"干细胞（stem cells）是功能还没有特化、能够自我复制和自我更新，并在一定条件下分化成多种细胞类型的多能性细胞。其关键特性是自我更新，即能经历多次细胞分裂周期而保持未分化状态；每次分裂产生的子细胞既可继续作为干细胞，也可走向终末分化。按分化潜能可分为全能、亚全能（多潜能）、多能和单能干细胞；按发育中出现的先后可分为胚胎干细胞与成体干细胞。细胞分化可视为全能性逐渐丧失的过程，而干细胞处于谱系起点，是组织更新与再生的细胞来源。","src":"《第11章 细胞分化与基因表达调控》p17、p21"},{"id":"44683577","s":"c","g":"c11","n":"干细胞壁龛","e":"stem cell niche","d":"干细胞壁龛（stem cell niche）是组织中干细胞所在的特殊微环境，它与干细胞相互作用以调节细胞命运，是能够维持自我更新干细胞的场所。胚胎发育中，多种壁龛因子作用于胚胎干细胞，改变其基因表达，诱导其增殖或分化以推动胎儿发育；在人体内，壁龛使成体干细胞维持在静息状态并长期保存。壁龛是干细胞更新与分化的外在调节机制，与非对称分裂中细胞质决定子的不对称分配这一内在机制相对应。组织损伤后，微环境可主动发出信号促进干细胞自我更新或分化。","src":"《第11章 细胞分化与基因表达调控》p33、p52"},{"id":"9c2e2a85","s":"c","g":"c11","n":"弯曲蛋白","e":"","d":"弯曲蛋白是一类能使DNA双螺旋弯曲成锐角、从而把相距较远的DNA区域拉到一起的蛋白，通过使结合其上的蛋白彼此靠近、相互调节而调控转录。这类蛋白属构建因子，本身常不直接激活或抑制转录，而改变DNA的空间构型，为其他调控蛋白的相互作用创造条件。含HMG框的转录因子即典型例子：它们通过弯折DNA，促进与邻近位点相结合的其他转录因子的相互作用而激活转录。因此在真核基因调控区，弯曲蛋白与激活因子、中介体及染色质重塑因子协同形成有活性的调控组合。","src":"《普通班作业汇总》p6；《第8章 细胞核与染色体》p46"},{"id":"fd223e38","s":"c","g":"c11","n":"染色质重塑","e":"chromatin remodeling","d":"染色质重塑（chromatin remodeling）是改变核小体排列位置与构型、从而调节DNA可及性的过程。染色质重塑复合体（如SWI/SNF）利用水解ATP所得的能量破坏组蛋白与DNA间的接触，形成接触部分破坏的活化中间态，使DNA与核小体结合变疏松，核小体随之滑动或重排。转录因子与重塑因子结合到启动子特定位点后，可引起特定核小体位置改变，使原本被遮蔽的调控序列暴露。重塑常与组蛋白修饰共同发生，使启动子去稳定化并组装转录起始复合物。","src":"《第8章 细胞核与染色体》p67、p68；MBoC 7e 印刷 p418","x":1},{"id":"9e19c622","s":"c","g":"c11","n":"染色质重塑","e":"","d":"染色质重塑是特定基因转录起始过程中的重要环节。特定基因的转录起始大致按染色质重塑、组蛋白修饰、转录激活因子富集、转录起始复合物组装、起始转录的顺序展开：先由重塑因子使DNA与核小体结合变疏松，再由组蛋白修饰改变染色质状态，随后激活因子在启动子上富集，最终装配转录起始复合物并起始转录。重塑因子与转录因子结合到启动子特定位点后，引起特定核小体位置的改变即滑动；该过程利用ATP水解产生的能量。不同启动子上各步骤细节并不相同。","src":"《第11章 细胞分化与基因表达调控》p101；《第8章 细胞核与染色体》p67、p68"},{"id":"b6a62fa1","s":"c","g":"c11","n":"沉默子","e":"silencer","d":"沉默子（silencer）是基因转录调控中的负性元件，与增强子作用相反。当特异的调节蛋白与沉默子结合后，基因转录即被抑制。有些沉默子在特定条件下也可起增强子的作用，这主要取决于细胞核内调节蛋白的性质，说明同一顺式元件的作用取决于与之结合的因子。真核基因的顺式作用元件包括启动子、增强子和沉默子（绝缘子），它们是真核基因转录的调节者，可影响自身基因的表达活性。沉默子与增强子、绝缘子共同作用，使不同基因的调控区互不干扰，实现精确调控。","src":"《第11章 细胞分化与基因表达调控》p88、p96"},{"id":"6427fb6f","s":"c","g":"c11","n":"管家基因","e":"housekeeping gene","d":"管家基因（housekeeping gene）是在所有细胞类型中都表达、为所有细胞所必需的基因，其编码产物是维持细胞基本生命活动所需的蛋白质，因此在几乎所有细胞中都表达。与之相对，奢侈基因即组织特异性基因仅在特殊细胞中表达。早期认为管家基因较多，随着高通量技术的应用，发现大多数基因实为组织特异性基因，仅约3%为管家基因。约60%的人类蛋白编码基因的启动子位于CG岛内，而几乎所有管家基因的启动子都包含在CG岛中。","src":"《第11章 细胞分化与基因表达调控》p42；MBoC 7e 印刷 p437"},{"id":"708ca0da","s":"c","g":"c11","n":"管家基因","e":"house-keeping genes","d":"管家基因（house-keeping genes）是指在所有细胞类型中都表达的基因，其产物为所有细胞所必需，是维持细胞基本生存代谢的必需基因。与之相对，组织特异性基因又称奢侈基因，仅在特殊细胞中表达，产生细胞或组织特异的蛋白。早期研究认为管家基因占比较大，随着高通量技术的应用，发现大多数基因实为组织特异性基因，仅约3%为管家基因。这说明细胞分化的分子基础主要不是基因的增减，而是组织特异性基因的选择性表达，管家基因则作为共同背景持续表达。","src":"《第11章 细胞分化与基因表达调控》p42"},{"id":"1c302332","s":"c","g":"c11","n":"组合调控","e":"","d":"组合调控是通过一种关键性调节蛋白对其他调节蛋白进行级联启动的细胞分化调控机制，是一种高效而经济的调控方式。借助于组合调控，一旦某种关键性基因调控蛋白与其他调控蛋白形成适当组合，不仅可将一种类型的细胞转化成另一种类型，而且遵循类似机制，甚至可以诱导整个器官的形成。因此组合信号是细胞分化调控的重要手段。细胞分化是渐进的过程，胚胎发育可看作一团细胞逐级区域化的过程，不同区域细胞中调控蛋白组合的差异决定了基因表达模式与细胞命运。","src":"《第11章 细胞分化与基因表达调控》p41、p45"},{"id":"e6b175d9","s":"c","g":"c11","n":"组织特异性基因（奢侈基因）","e":"luxury genes (tissue-specific genes)","d":"组织特异性基因又称奢侈基因（luxury genes，tissue-specific genes），是仅在特殊细胞中表达的基因，其产物为细胞或组织特异的蛋白质，决定不同类型细胞各自的结构与功能。与之相对，管家基因在所有细胞类型中表达并为所有细胞所必需。早期认为管家基因较多，随着高通量技术的应用，发现大多数基因为组织特异性基因，仅约3%为管家基因。因此细胞分化的关键在于奢侈基因的选择性表达：同一套基因组在不同细胞中按不同组合开启特定基因。","src":"《第11章 细胞分化与基因表达调控》p42"},{"id":"02ddd862","s":"c","g":"c11","n":"细胞全能性","e":"cell totipotency","d":"细胞全能性（cell totipotency）指细胞经分裂和分化后，在一定条件下具有发育成一个完整个体的潜能。它说明分化细胞仍具有个体的全部遗传信息，分化过程中遗传物质并未丢失或改变，差别在于基因的选择性表达。细胞全能性可由植物组织培养、动物克隆和干细胞研究证明：已分化的植物细胞可经组织培养形成完整植株，体细胞核移植可使去核卵发育成个体。随个体发育，细胞分化可看成全能性逐渐丧失的过程，发育潜能逐级变窄。","src":"《第11章 细胞分化与基因表达调控》p9"},{"id":"ecc10bdd","s":"c","g":"c11","n":"终末分化","e":"","d":"终末分化是指由定向干细胞最终形成特化细胞类型的过程。单能干细胞即定向干细胞来自多能干细胞，只能分化为一种类型的细胞且自我更新能力有限，故也称祖细胞；由它最终产生具有特定结构与功能的成熟细胞，即为终末分化。细胞分化可视为全能性逐渐丧失的过程，谱系为受精卵、胚胎干细胞、组织特异干细胞、终末分化细胞前体细胞，最后成为终末分化细胞。在更新组织中，干细胞分裂产生不再分裂的终末分化细胞；后者也可经去分化转化为肿瘤干细胞。","src":"《第11章 细胞分化与基因表达调控》p29、p32"},{"id":"3ae8f27b","s":"c","g":"c11","n":"绝缘子","e":"insulator","d":"绝缘子（insulator）是阻止远距离调控作用、防止不同基因调控区相互干扰的DNA序列，属真核基因的顺式作用元件之一。真核转录调控蛋白能够跨越很长的DNA片段发挥作用，中间DNA成环，因此需要机制把不同基因的调控区隔开；绝缘子即起这种屏障作用，使一个基因的增强子不能影响邻近基因。它与启动子、增强子和沉默子同为顺式作用元件，共同构成基因转录的调节者。许多编码重要发育调控蛋白的基因需被严格抑制，绝缘子有助于把调控限制在正确范围内。","src":"《第11章 细胞分化与基因表达调控》p97、p98；MBoC 7e 印刷 p422"},{"id":"62b2b044","s":"c","g":"c11","n":"胚胎干细胞","e":"embryonic stem cell","d":"胚胎干细胞（embryonic stem cell）是由囊胚期内细胞群经显微操作分离、在滋养层细胞上培养建系的多潜能干细胞。人胚胎发育5～6天至囊胚期时取出内细胞团，分散后培养在体外滋养层细胞（一般为经处理、不能继续分裂的小鼠成纤维细胞）上，随后传代培养建系。由于源自内细胞群，它具备分化成三个胚层所有细胞类型的能力，但失去发育成完整个体的能力，属亚全能或多潜能干细胞；体外可控诱导分化可形成机体各种组织，其维持涉及多条信号通路。","src":"《第11章 细胞分化与基因表达调控》p22、p60"},{"id":"243cf6a7","s":"c","g":"c11","n":"自我更新","e":"self-renewal","d":"自我更新（self-renewal）是干细胞经历多次细胞分裂周期仍保持未分化状态的能力。干细胞是功能尚未特化、能够自我复制和自我更新并在一定条件下分化成多种细胞类型的多能性细胞，自我更新正是其关键特性之一：干细胞每次分裂产生的子细胞，既可继续保持为干细胞，也可走向终末分化。这种在自我更新与分化间的选择，使干细胞群体得以长期维持并不断提供分化细胞。其调节包括非对称分裂的内在机制与干细胞壁龛等外在机制。","src":"《第11章 细胞分化与基因表达调控》p17、p18；MBoC 7e 印刷 p1291"},{"id":"6ea1d4ec","s":"c","g":"c11","n":"表观遗传","e":"epigenetics","d":"表观遗传（epigenetics）指不依赖DNA序列改变、却能在细胞分裂后传递给子代细胞的基因表达状态的改变，即叠加于DNA遗传之上的遗传形式，epi在希腊语中意为“在……之上”。其分子基础包括DNA甲基化（主要发生在CG序列中的胞嘧啶上）、组蛋白翻译后修饰如甲基化与去甲基化，以及染色质重塑，这些修饰决定染色质的开放或关闭状态，从而稳定地激活或沉默基因。表观遗传使表达模式随细胞分裂而继承，形成细胞记忆，是细胞分化与干细胞维持的重要基础。","src":"《思维导图》p7；MBoC 7e 印刷 p203"},{"id":"d77a0aa4","s":"c","g":"c11","n":"诱导性多能干细胞","e":"induced pluripotent stem cells (iPS)","d":"诱导性多能干细胞（induced pluripotent stem cells，iPS）是通过人工表达特定转录调控因子，使体细胞呈现类似胚胎干细胞多能性的细胞。将Oct4、Sox2、c-Myc和Klf4四种转录因子基因克隆入病毒载体，引入小鼠成纤维细胞，可诱导其发生转化；产生的iPS细胞在形态、基因和蛋白表达、表观遗传修饰状态以及分化能力等方面都与胚胎干细胞相似。由于可由体细胞直接诱导获得，它避免了使用胚胎的伦理问题。","src":"《第11章 细胞分化与基因表达调控》p65"},{"id":"a196ffc6","s":"c","g":"c11","n":"造血干细胞","e":"hematopoietic stem cells","d":"造血干细胞（hematopoietic stem cells）是位于骨髓、能产生几乎所有血细胞类型的干细胞，属多能干细胞。骨髓是一切免疫细胞的发源地，其中含两种干细胞：造血干细胞能产生循环系统中的三类血细胞，即白细胞、红细胞和血小板；另一种是间质干细胞。造血干细胞逐级分化为各种类型的血细胞，是血细胞持续更新的来源。作为成体干细胞，它依靠自我更新维持自身数量，并经短暂扩充细胞有限增殖后完成终末分化；移植后其重建能力随年龄而下降。","src":"《第11章 细胞分化与基因表达调控》p24；《第13章 免疫系统的细胞》p11"},{"id":"fc782469","s":"c","g":"c11","n":"间充质干细胞","e":"mesenchymal stem cell","d":"间充质干细胞（mesenchymal stem cell）是胚胎间充质中分化程度低的多能干细胞，间充质是主要见于两侧对称三胚层动物胚胎发育中的结缔组织。间充质细胞呈星状，细胞间以突起相互连接成网，核大、核仁明显、胞质弱嗜碱性。间充质干细胞在胚胎时期能分化成各种结缔组织细胞、内皮细胞和平滑肌细胞等，可分化为骨、软骨、肌肉、脂肪等多种组织，负责结构支持与结缔组织构成。成体结缔组织中仍保留少量未分化间质细胞，是组织修复与再生研究的重要来源。","src":"《第11章 细胞分化与基因表达调控》p26、p28"},{"id":"2c8427cf","s":"c","g":"c11","n":"非对称分裂","e":"asymmetric cell division","d":"非对称分裂（asymmetric cell division）是产生命运不同子细胞的分裂方式。其内在机制在于母细胞中某些重要分子在两个子细胞间的不均等分配，这种不对称继承使两个子细胞朝不同方向发育；例如细胞质决定子如Prospero、Numb、Miranda等蛋白在分裂时不对称分配，决定子细胞命运。非对称分裂也可由外在机制即干细胞壁龛引导，使干细胞分裂后仍留在壁龛中维持干性。因此它是干细胞既自我更新又产生分化细胞的重要方式。","src":"《第11章 细胞分化与基因表达调控》p33、p35；MBoC 7e 印刷 p1224"},{"id":"21b28a32","s":"c","g":"c11","n":"顺式作用因子","e":"cis-acting element","d":"顺式作用因子即顺式作用元件（cis-acting element），是可影响自身基因表达活性的DNA序列，是真核基因转录的调节者。它们包括启动子、增强子和沉默子（绝缘子）：启动子一般位于结构基因5′端上游，具严格方向性，指导RNA聚合酶与模板正确结合并启动转录；增强子增强转录，常与启动子连环或重叠；沉默子是负性元件，与特异调节蛋白结合后抑制转录。这些元件通过与反式作用因子即由其他基因编码的蛋白质因子相互作用而发挥作用。","src":"《第11章 细胞分化与基因表达调控》p88"},{"id":"0035ef50","s":"c","g":"c13","n":"Annexin V","e":"Annexin V","d":"Annexin V是一种用于检测细胞凋亡早期的探针蛋白。细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸（PS）迅速翻转到细胞膜外侧，使PS暴露于膜表面，这一变化可用PS与抗凝血剂Annexin V的相互作用检测。在Ca2+存在的情况下，Annexin V与PS有很高亲和力，能与之迅速结合，因此可用标记的Annexin V显示外翻的PS。由于PS外翻发生在细胞核破裂和DNA片段化之前，该检测可在核形态与DNA明显改变之前识别早期凋亡细胞。","src":"《第12章 细胞衰老与细胞凋亡》p35"},{"id":"527f61c2","s":"c","g":"c13","n":"Apaf1","e":"Apaf1","d":"Apaf1即凋亡蛋白酶激活因子1，是内源性凋亡途径的关键接头蛋白，其N端含CARD结构域。当损伤、DNA损伤或氧与营养缺乏等刺激使线粒体释放细胞色素c后，细胞色素c进入胞质并与Apaf1结合，使Apaf1结合脱氧ATP并寡聚化成长大的轮状七聚体；该七聚体把无活性的起始caspase-9单体招募到复合物中，形成更大的结构即凋亡复合体。caspase-9在凋亡复合体内通过二聚化被激活，随后切割并激活下游执行caspase，推动细胞凋亡。","src":"《第12章 细胞衰老与细胞凋亡》p62；MBoC 7e 印刷 p1095","x":1},{"id":"5ba127f8","s":"c","g":"c13","n":"BH3-only蛋白","e":"BH3-only proteins","d":"BH3-only蛋白是Bcl2家族中仅含BH3结构域的一类促凋亡蛋白。它们在凋亡刺激下产生或被激活，主要通过抑制抗凋亡蛋白促进凋亡：其BH3结构域可与抗凋亡的Bcl2蛋白结合，中和后者活性，也可直接与Bax和Bak结合，帮助触发二者的活化与聚集，从而在线粒体外膜上形成开口、引起细胞色素c释放。Bid被切割后形成tBid，连接内源性与外源性凋亡途径。三类Bcl2家族蛋白活性的平衡，很大程度上决定细胞经内源途径存活还是死亡。","src":"《第12章 细胞衰老与细胞凋亡》p50；MBoC 7e 印刷 p1096"},{"id":"c882c2ed","s":"c","g":"c13","n":"Bcl-2家族","e":"Bcl-2 family","d":"Bcl-2家族是调控线粒体途径细胞凋亡的关键调节因子家族，成员大多定位在线粒体外膜，或受信号刺激后转移到外膜，通过调控线粒体外膜通透性促进或抑制凋亡。成员具有Bcl-2同源结构域（BH），主要体现在BH1、BH2、BH3、BH4四个保守区域：BH4为抗凋亡蛋白所特有，BH3与促进凋亡有关，各成员可含数量与类型不同的1～4个BH结构域。抗凋亡成员阻止外膜通透化，促凋亡的Bax、Bak直接形成开口促使细胞色素c释放，三者的平衡决定细胞生死。","src":"《第12章 细胞衰老与细胞凋亡》p47、p64；MBoC 7e 印刷 p1104"},{"id":"03c7be99","s":"c","g":"c13","n":"DISC","e":"DISC","d":"死亡诱导信号复合物（DISC）是死亡受体介导的外源性凋亡途径中，由接头蛋白引导起始者caspase组装而成的凋亡信号激活复合物。死亡受体与配体结合后在膜上聚集，胞内段招募接头蛋白（如FADD），接头蛋白再通过蛋白相互作用把无活性的起始者caspase前体聚集到受体处，形成DISC。起始者caspase在DISC内通过二聚化被激活，切割并激活下游执行caspase，引发凋亡。因此DISC把胞外死亡信号在膜内侧转换为蛋白水解酶的级联活化。","src":"《细胞生物学历年考题整理》p5；《第12章 细胞衰老与细胞凋亡》p62；MBoC 7e 印刷 p1095","x":1},{"id":"8295e568","s":"c","g":"c13","n":"DNA梯状条带","e":"","d":"DNA梯状条带是凋亡细胞核DNA经琼脂糖凝胶电泳后呈现的阶梯状条带，是凋亡的生化检测指标之一。细胞凋亡时，核DNA在核小体连接处被切割断裂，由于核小体DNA长度约为200 bp，断裂产生的片段长度为200 bp及其整倍数，因而在凝胶上形成以约200 bp为间隔的梯状条带。这种有序的、以核小体为单位的断裂是凋亡区别于坏死的重要特征：坏死时DNA被随机降解，电泳呈连续弥散条带。故该检测可与形态学观察、PS外翻检测等配合判断凋亡。","src":"《第12章 细胞衰老与细胞凋亡》p36"},{"id":"e89e788c","s":"c","g":"c13","n":"DNA甲基化","e":"","d":"DNA甲基化是在DNA分子上添加甲基的共价修饰，在植物和动物中主要表现为CG序列中胞嘧啶的甲基化，生成5-甲基胞嘧啶，不改变碱基配对性质。广泛的胞嘧啶甲基化被用来使基因保持在失活状态，是重要的表观遗传调控方式；在脊椎动物细胞中，它还为基因表达模式传给子代细胞提供机制，使不依赖DNA序列改变的细胞记忆得以维持。在衰老研究中，DNA甲基化格局的改变是表观遗传改变的重要内容，与细胞复制性衰老及细胞早衰过程中基因表达程序的稳定性下降有关。","src":"《第12章 细胞衰老与细胞凋亡》p17；《第4章 核糖体》p95"},{"id":"89c001fc","s":"c","g":"c13","n":"Fas配体","e":"Fas ligand (CD95L)","d":"Fas配体（Fas ligand，CD95L）是激活细胞表面死亡受体Fas、从而触发外源性凋亡途径的配体。Fas即CD95，属死亡受体；FasL与之结合后使受体在膜上聚集，胞内段招募接头蛋白FADD，并由FADD引导起始者caspase前体组装成死亡诱导信号复合物（DISC），caspase在复合物内通过二聚化被激活，切割执行caspase，导致凋亡。细胞毒性T细胞即借这一配体-受体系统杀伤靶细胞，故它是免疫杀伤与免疫自稳的重要机制。","src":"《细胞生物学历年考题整理》p5；MBoC 7e Glossary（PDF p1456）","x":1},{"id":"d0752e5c","s":"c","g":"c13","n":"Hayflick界限","e":"Hayflick life span","d":"Hayflick界限指正常人体细胞在体外培养时增殖能力有一定界限、分裂潜能受限制的现象，又称复制衰老。经典证据来自对正常人成纤维细胞的培养观察：这类细胞在体外不能无限分裂，而是在经历大约50代后不可逆地进入生长停滞状态，且供体年龄越大，细胞可分裂次数越少，这否定了正常细胞具有永生性的旧观点。其分子基础与端粒随每次分裂而缩短有关：端粒缩短到临界长度即触发DNA损伤反应使细胞停止分裂，癌细胞则因端粒酶活性而逃避这一界限。","src":"网络补充：wikipedia.org（Hayflick limit）；kepuchina.cn"},{"id":"6428b1b0","s":"c","g":"c13","n":"LC3","e":"LC3","d":"LC3即微管相关蛋白1轻链3-β，是自噬的常用标志物。自噬过程中，LC3与脂质磷脂酰乙醇胺（PE）偶联，由LC3-I转变为脂质化的LC3-II，后者结合在自噬体膜上，因此其转换水平可反映自噬活性。检测最常用的方法是蛋白质印迹检测LC3-II/LC3-I的转换，以及荧光显微镜观察LC3点状聚集物的形成；由于LC3本身也通过自噬被降解，用印迹判断自噬通量时需结合自噬抑制物联合检测。自噬性细胞死亡检测的金标准则是电镜下看到自噬体等膜状结构。","src":"《第12章 细胞衰老与细胞凋亡》p93、p96；《第5章细胞内膜系统（上）》p103"},{"id":"8fe9d93d","s":"c","g":"c13","n":"衰老相关分泌表型","e":"SASP (senescence-associated secretory phenotype)","d":"衰老相关分泌表型（SASP）是衰老细胞表现出的分泌特征，即衰老细胞分泌多种因子，包括生长因子、蛋白酶和炎性因子等。这些分泌因子依其所处的生物环境，既可诱导自身衰老，也可促进细胞增殖，因而具有双向调节作用。SASP使衰老细胞不再只是被动地停止分裂，而能通过分泌活动影响自身与周围细胞，是衰老细胞与组织微环境相互作用的重要方式，也解释了衰老细胞在组织中所产生的复杂效应，被视为连接细胞衰老与组织功能改变的重要环节。","src":"《第12章 细胞衰老与细胞凋亡》p10"},{"id":"1dd93d87","s":"c","g":"c13","n":"Sir2","e":"Sir2 (silencing information regulator 2)","d":"Sir2即沉默信息调节因子2，是一种组蛋白去乙酰化酶，能沉默转录子并稳定DNA。它通过去除组蛋白赖氨酸残基上的乙酰基，使染色质处于较为关闭的状态，从而抑制该区域的基因转录，并有助于维持基因组的稳定性。在细胞复制性衰老以及细胞早衰过程中，Sir2的功能出现下调，提示其活性下降与衰老过程中染色质沉默能力减弱、基因表达程序紊乱有关。因此Sir2是研究染色质修饰、基因沉默与细胞衰老之间联系的重要分子。","src":"《第12章 细胞衰老与细胞凋亡》p17"},{"id":"cd5aa5a9","s":"c","g":"c13","n":"TUNEL","e":"TUNEL (TdT-mediated dUTP nick end labeling)","d":"TUNEL即末端脱氧核苷酸转移酶介导的dUTP缺口末端标记法。细胞凋亡时核DNA被切割断裂，产生大量DNA缺口，其断端带有3′-OH；TUNEL利用末端脱氧核苷酸转移酶把标记的dUTP连接到这些断裂缺口的3′-OH上，再通过标记信号在原位显示DNA断裂的细胞，从而在组织切片或细胞样本中识别凋亡细胞。由于它直接检测DNA断裂，属原位检测方法，可与DNA梯状条带电泳、PS外翻检测以及形态学观察等方法配合，共同判断细胞是否发生凋亡。","src":"《第12章 细胞衰老与细胞凋亡》p37"},{"id":"7d45e319","s":"c","g":"c13","n":"entosis","e":"entosis","d":"entosis即细胞侵入性死亡，是一种通过细胞侵入细胞（cell-in-cell invasion）而发生的非凋亡性细胞死亡过程。其特点是一个细胞主动进入另一个细胞内部，形成细胞套细胞的结构，随后内部细胞死亡，这一过程在形态与机制上均不同于典型凋亡，因此被归为非凋亡性细胞死亡方式。entosis的提出使人们对细胞死亡方式的认识不再局限于凋亡与坏死；已被熟知的途径还包括坏死性凋亡、自噬、铁死亡、细胞焦亡、非程序性坏死和免疫原性细胞死亡等。","src":"《第12章 细胞衰老与细胞凋亡》p103"},{"id":"e4a2ce91","s":"c","g":"c13","n":"ferroptosis","e":"ferroptosis","d":"ferroptosis即铁死亡，是一种以铁依赖的脂质过氧化累积为核心的程序性细胞死亡方式，在形态、生化与遗传特征上均区别于细胞凋亡、坏死性凋亡和自噬。其发生需要铁的参与：在二价铁或脂氧合酶作用下，细胞膜上的不饱和脂肪酸发生脂质过氧化，而谷胱甘肽过氧化物酶4等抗氧化体系功能受损时脂质过氧化物不能被及时清除，膜结构被破坏，最终导致细胞死亡。铁死亡与凋亡、坏死性凋亡、自噬、细胞焦亡、非程序性坏死等并列，是细胞死亡多样性的重要内容。","src":"网络补充：wikipedia.org（铁死亡）；ibp.cas.cn"},{"id":"dc84af69","s":"c","g":"c13","n":"necroptosis","e":"necroptosis","d":"necroptosis即坏死性凋亡，是细胞坏死的一种形式。传统坏死中细胞肿胀并破裂，内容物外溢到邻近细胞并引起炎症反应；而在另一些形式的细胞坏死中，细胞主动参与死亡过程，这类死亡依诱导应激的性质和所涉及的分子机制不同而被赋予专门名称，necroptosis与pyroptosis即属此类。因此坏死性凋亡的关键在于它虽在形态上表现为坏死，却由细胞内信号主动驱动、有特定分子机制，属程序性死亡，与被动发生的非程序性坏死相区别。","src":"《第12章 细胞衰老与细胞凋亡》p101；MBoC 7e 印刷 p1089"},{"id":"57b26708","s":"c","g":"c13","n":"p16/INK4a","e":"p16/INK4a","d":"p16/INK4a 是细胞周期蛋白依赖性激酶抑制因子，与细胞衰老密切相关，但并非介导细胞周期停滞的主要CKI，后者是p21。它构成p16INK4a/CDK4,6/Rb/E2F衰老信号途径：p16INK4a抑制CDK4/6，使pRb不能被磷酸化，非磷酸化的Rb与转录因子E2F结合，从而阻止细胞周期进程，细胞由此进入衰老状态。该途径与p19ARF/p53/p21Cip1途径并列，是细胞衰老的两条主要信号通路之一。","src":"《细胞生物学历年考题整理》p3；《第12章 细胞衰老与细胞凋亡》p23","x":1},{"id":"d06dc045","s":"c","g":"c13","n":"p16INK4a/Rb途径","e":"p16INK4a/Rb pathway","d":"p16INK4a/Rb途径（p16INK4a/Rb pathway）是细胞衰老的两条主要信号途径之一。其核心是：p16INK4a抑制细胞周期蛋白依赖性激酶CDK4/6，使Rb蛋白pRb不能被磷酸化；非磷酸化的pRb与转录因子E2F结合，阻止细胞周期进程，细胞由此退出增殖周期并进入衰老状态。与p19ARF/p53/p21Cip1途径经MDM2与p53发挥作用不同，该途径直接作用于CDK4/6-Rb-E2F环节，是衰老信号汇聚的重要通路。","src":"《第12章 细胞衰老与细胞凋亡》p23"},{"id":"0bbd6ab0","s":"c","g":"c13","n":"p19ARF/p53/p21Cip1途径","e":"p19ARF/p53/p21Cip1 pathway","d":"p19ARF/p53/p21Cip1途径（p19ARF/p53/p21Cip1 pathway）是细胞复制衰老的主要信号途径之一。细胞周期抑制因子p19ARF与MDM2结合并促进其降解，使p53得以稳定和激活；活化的p53促进细胞周期抑制因子p21Cip1表达，导致细胞周期中止，细胞进入不可逆的增殖停滞。该途径与p16INK4a/Rb/E2F途径并列，共同构成细胞衰老的经典通路。","src":"《第12章 细胞衰老与细胞凋亡》p21；《第12章 细胞衰老与细胞凋亡》p22"},{"id":"133ec777","s":"c","g":"c13","n":"细胞焦亡","e":"pyroptosis","d":"细胞焦亡（pyroptosis）是2018年细胞死亡命名委员会列出的细胞死亡途径之一，与细胞凋亡、坏死性凋亡、自噬、铁死亡、免疫原性细胞死亡及非程序性坏死等并列。它归属于细胞坏死的范畴，但与被动坏死不同，细胞主动参与死亡过程，并依诱导应激的性质和所涉分子机制而被单独命名。形态上细胞肿胀、破裂，内含物溢出到邻近细胞并引发炎症反应；这与凋亡时细胞膜保持完整、内含物不外漏、不引发炎症形成鲜明对照。","src":"《第12章 细胞衰老与细胞凋亡》p101；MBoC 7e 印刷 p1089"},{"id":"a5e304cd","s":"c","g":"c13","n":"tBID","e":"tBID","d":"tBID（truncated Bid）是caspase切割Bcl2家族促凋亡蛋白Bid后生成的截短片段。Bid被切割后，其翻译后N-豆蔻酰化是tBid靶向线粒体不可逆的一步，也是DISC与caspase-3介导凋亡之间线粒体放大环路的关键事件。tBid可结合并中和抗凋亡Bcl2蛋白的活性，也可直接作用于Bax和Bak，帮助触发它们的活化与聚合，促使线粒体外膜通透化。因此tBid把外源性与内源性凋亡途径连接起来。","src":"《第12章 细胞衰老与细胞凋亡》p68；《第12章 细胞衰老与细胞凋亡》p50","x":1},{"id":"a3448892","s":"c","g":"c13","n":"凋亡复合体","e":"apoptosome","d":"凋亡复合体（apoptosome）是内源性凋亡途径激活后由Apaf-1聚合形成的七聚体。Apaf-1（凋亡蛋白酶激活因子1）N端含CARD，与细胞色素c结合后结合dATP并寡聚成轮状七聚体，随后招募含CARD的caspase-9酶原进入复合物，形成更大的凋亡复合体；caspase-9在复合体内经二聚化被激活，再切割并激活下游执行者caspase-3和-7，引发凋亡。它与DISC同属使起始者caspase在大型复合物中被激活的装配平台。","src":"《第12章 细胞衰老与细胞凋亡》p65；MBoC 7e 印刷 p1095","x":1},{"id":"6fd2f9eb","s":"c","g":"c13","n":"凋亡小体","e":"apoptotic body","d":"凋亡小体（apoptotic body）是细胞凋亡过程中形成的单个圆形小体。凋亡起始时细胞表面特化结构如微绒毛消失、细胞间接触丧失，但细胞膜仍完整，线粒体大体完整，核糖体从内质网脱落，染色质固缩成沿核膜分布的新月形帽状结构；随后断裂的大小不等的DNA或染色质片段与细胞其他内含物一起被反折的细胞质膜包裹，在细胞表面形成许多泡状或芽状突起，根部绞窄后脱落，形成内含胞质、细胞器及核碎片的小体，最终被邻近细胞识别并吞噬消化。","src":"《第12章 细胞衰老与细胞凋亡》p31；《第12章 细胞衰老与细胞凋亡》p33","x":1},{"id":"75b9a461","s":"c","g":"c13","n":"凋亡抑制蛋白IAP家族","e":"inhibitor of apoptosis protein (IAP) family","d":"凋亡抑制蛋白IAP（inhibitor of apoptosis protein）家族是细胞内唯一的内源性半胱天冬酶抑制物，包括XIAP、Survivin、livin等，广泛存在于病毒、真核生物和哺乳动物中。其共同特征是氨基端带有BIR结构域，可直接结合caspases活性分子，阻抑其对底物的切割，为抑制凋亡所必需；其RING结构具E3连接酶作用，主要介导caspase-3、-7泛素化降解，对凋亡抑制并非必需。","src":"《第12章 细胞衰老与细胞凋亡》p51；《第12章 细胞衰老与细胞凋亡》p53"},{"id":"733e68ac","s":"c","g":"c13","n":"凋亡抑制蛋白家族","e":"IAP","d":"凋亡抑制蛋白家族（IAP）是抑制caspase的蛋白家族，为细胞内唯一的内源性半胱天冬酶抑制物，成员有XIAP、Survivin、livin等，广泛分布于病毒、真核生物与哺乳动物。其BIR结构域位于氨基端，可直接结合caspase活性分子，阻抑其对底物的切割。线粒体外膜通透化后，膜间隙释放的anti-IAPs进入胞质，中和这些原本阻断凋亡的抑制蛋白，解除抑制而使caspase得以活化。","src":"《第12章 细胞衰老与细胞凋亡》p51；《第12章 细胞衰老与细胞凋亡》p53；MBoC 7e 印刷 p1098"},{"id":"4768dd83","s":"c","g":"c13","n":"半胱天冬酶","e":"caspase","d":"半胱天冬酶（caspase）是一类活性中心含半胱氨酸、并在靶蛋白特定天冬氨酸之后切割底物的细胞内蛋白酶，名称即取自cysteine的c与aspartic acid的asp。它们切割众多但特异的细胞内蛋白，引发凋亡时的剧烈形态变化。按其作用分起始者（caspase-8、-9等）与执行者（caspase-3、-6、-7）：起始者含CARD、DD或串联的DED，借结构域间聚合被招募到DISC、凋亡复合体等上游复合物中活化，再激活下游执行者。","src":"《第12章 细胞衰老与细胞凋亡》p57；MBoC 7e 印刷 p1091","x":1},{"id":"7759119e","s":"c","g":"c13","n":"坏死","e":"cell necrosis","d":"细胞坏死（cell necrosis）是细胞受到急性强力损伤，如极端物理、化学因素或严重病理性刺激时所发生的死亡形式，属被动过程。坏死时Ca2+升高、ATP水平急降，出现线粒体外膜肿胀而密度增加、细胞骨架破坏、溶酶体酶释放、pH下降、核染色质呈絮状及DNA降解、蛋白质合成减慢，最后细胞膜和细胞器破裂，内含物释放到胞外，引起周围区域炎症反应。创伤或血供阻断时细胞肿胀破裂即属此类，坏死性凋亡与细胞焦亡则是细胞主动参与的特殊形式。","src":"《第12章 细胞衰老与细胞凋亡》p81；MBoC 7e 印刷 p1089"},{"id":"6028d66f","s":"c","g":"c13","n":"死亡受体","e":"death receptor (CD95)","d":"死亡受体（death receptor）是结合胞外配体后向细胞发出凋亡信号的跨膜受体蛋白。以CD95（又称Fas、APO-1）为代表，其配体为CD95L，二者结合后组装死亡诱导信号复合体（DISC），经接头蛋白FADD招募并激活caspase-8。FADD含C端死亡结构域（DD）与N端死亡效应结构域（DED），DD结合受体胞内段，DED与caspase-8酶原的DED作用。CD95/CD95L、TNFR1、TRAILR是三条主要途径。","src":"《第12章 细胞衰老与细胞凋亡》p56；《第12章 细胞衰老与细胞凋亡》p59；MBoC 7e Glossary（PDF p1452）","x":1},{"id":"07e5b64c","s":"c","g":"c13","n":"死亡受体途径（外源性途径）","e":"","d":"死亡受体途径又称外源性途径，由CD95/CD95L（Fas）、TNFR1、TRAILR等死亡受体介导，是caspase依赖性凋亡通路。配体与受体结合后，受体胞内段经接头蛋白（如含DD和DED的FADD）募集caspase-8、-10酶原，组装成死亡诱导信号复合体（DISC）；起始者caspase在DISC这种大型复合物中经二聚化被激活，再激活执行者caspase。其共同特点是起始者均在大复合物中被激活，接头蛋白负责把它们引导至适当位置。","src":"《第12章 细胞衰老与细胞凋亡》p56；《第12章 细胞衰老与细胞凋亡》p70"},{"id":"12e2d455","s":"c","g":"c13","n":"磷脂酰丝氨酸外翻","e":"phosphatidylserine externalization","d":"磷脂酰丝氨酸外翻（phosphatidylserine externalization）指凋亡时质膜内侧磷脂酰丝氨酸（PS）翻转至膜外侧的现象。健康细胞中PS由ATP依赖的转位酶维持在内侧，凋亡时该不对称性被迅速打破，PS暴露于细胞表面，且早于膜完整性丧失，成为供巨噬细胞识别吞噬的“eat-me”信号。荧光标记的Annexin V可高亲和结合外翻的PS，用于检测早期凋亡细胞；DNA断裂产生大量3′端是较晚事件，故为TUNEL检测的基础。","src":"《细胞生物学历年考题整理》p5；网络补充：pmc.ncbi.nlm.nih.gov（The Burial: Clearance and Consequences）","x":1},{"id":"ca79ed64","s":"c","g":"c13","n":"程序性细胞坏死","e":"programmed necrosis","d":"程序性细胞坏死（programmed necrosis）是形态上表现为坏死、却可被受体配体诱导并受基因和表观因素调控的细胞死亡。DNA损伤积累使PARP活化、NAD+大量减少，糖酵解受抑、ATP急降而致坏死，分裂旺盛的细胞更易发生。受体相互作用蛋白RIP1和RIP3是通路中重要的调节蛋白：RIP1是决定细胞生存与死亡的交叉点，RIP3是决定死亡方式（凋亡或坏死）的转换器。TNF与其受体结合即可导致凋亡或程序性坏死，病毒也编码基因抑制之。","src":"《第12章 细胞衰老与细胞凋亡》p85；《第12章 细胞衰老与细胞凋亡》p86"},{"id":"e02b7edf","s":"c","g":"c13","n":"端粒-p53-PGC途径","e":"","d":"端粒-p53-PGC途径是细胞衰老中连接端粒损伤与线粒体功能下降的信号通路。端粒损伤可激活p53基因的表达，p53进而抑制过氧化物酶体增殖物活化受体γ协同刺激因子（PGC）基因的表达；PGC是细胞代谢过程和线粒体功能的主要调控因子，其表达受抑导致线粒体数量减少和功能下降，细胞代谢受损，推动衰老表型出现。该途径说明端粒损伤除经p53/p21引起周期停滞外，还可沿代谢—线粒体轴影响细胞衰老。","src":"《第12章 细胞衰老与细胞凋亡》p25"},{"id":"2ac3803c","s":"c","g":"c13","n":"线粒体凋亡途径（内源性途径）","e":"intrinsic pathway","d":"线粒体凋亡途径又称内源性途径，由细胞内部应激或发育信号激活，依赖线粒体膜间隙蛋白释放入胞质。损伤、DNA损伤、缺氧或营养缺乏等上游信号改变线粒体外膜，使细胞色素c等可溶性蛋白扩散至胞质；细胞色素c与Apaf-1结合，促其寡聚成七聚体并招募caspase-9酶原形成凋亡复合体，caspase-9二聚化活化后切割执行者caspase。该途径受Bcl2家族蛋白间相互作用控制，是脊椎动物多数凋亡的途径，线粒体因而被称为细胞死亡信号的整合器。","src":"《第12章 细胞衰老与细胞凋亡》p62；MBoC 7e 印刷 p1095"},{"id":"e8caef61","s":"c","g":"c13","n":"细胞凋亡","e":"apoptosis","d":"细胞凋亡（apoptosis）是基因调控的主动的细胞死亡形式，即细胞内的“自杀”程序被激活，经caspase等蛋白水解酶介导而迅速死亡；该词于1972年提出，1990年代的里程碑式进展证明它是基因调控的主动过程。形态上细胞膜保持完整、内含物不外漏、不引发炎症，染色质高度凝聚，核小体间DNA断裂形成200bp倍数的片段，并形成凋亡小体被邻近细胞吞噬。途径分死亡受体（外源）与线粒体（内源）两类，经接收信号、活化、执行、清除四个阶段。","src":"《第12章 细胞衰老与细胞凋亡》p28；《第12章 细胞衰老与细胞凋亡》p30；MBoC 7e 印刷 p1090","x":1},{"id":"3c10cea2","s":"c","g":"c13","n":"细胞坏死","e":"necrosis","d":"细胞坏死（necrosis）是与凋亡相对的细胞死亡方式，由急性强力损伤如极端理化因素或严重病理性刺激引起。坏死时细胞膜与细胞器破裂、内含物释放到胞外并引发炎症，核染色质呈絮状、DNA降解，Ca2+升高、ATP急降、细胞骨架破坏、溶酶体酶释放；这与凋亡时细胞膜完整、染色质在核小体间断裂、不引起炎症形成鲜明对比。在讲授体系中，细胞死亡分为细胞衰老、细胞凋亡、细胞坏死与细胞自噬，坏死还包括PARP活化、ATP耗竭所致的程序性坏死。","src":"《第12章 细胞衰老与细胞凋亡》p81；《细胞生物学历年考题整理》p6","x":1},{"id":"13506e1e","s":"c","g":"c13","n":"细胞色素c","e":"cytochrome c","d":"细胞色素c（cytochrome c）是线粒体电子传递链中的可溶性组分，位于线粒体膜间隙，在内膜的细胞色素b-c1复合物与细胞色素c氧化酶复合物之间传递电子。它还有第二种功能：线粒体外膜通透性改变后，细胞色素c从膜间隙释放入胞质，与Apaf-1结合，促其寡聚并与caspase-9酶原组装成凋亡复合体，激活caspase-9，从而启动内源性凋亡。因此它既是能量代谢的电子载体，又是凋亡的启动信号。","src":"《第7章细胞的能量代谢》p24；《第12章 细胞衰老与细胞凋亡》p65；MBoC 7e Glossary（PDF p1452）","x":1},{"id":"a20b3e4a","s":"c","g":"c13","n":"细胞衰老","e":"senescence","d":"细胞衰老（senescence）指细胞不可逆地丧失增殖能力后所进入的一种相对稳定的状态，伴有一定的生物化学改变、结构异常和生理功能障碍。正常人体细胞在体外分裂潜能受限制的现象称复制衰老，即Hayflick界限，人成纤维细胞在标准培养下约经50次群体倍增后停止分裂且不再恢复。其分子基础包括DNA损伤、端粒缩短、应激、癌基因异常表达、microRNA和自噬等，主要途径为p19ARF/Mdm2/p53/p21与p16INK4a/Rb/E2F。","src":"《第12章 细胞衰老与细胞凋亡》p4；《第12章 细胞衰老与细胞凋亡》p5；MBoC 7e 印刷 p1082","x":1},{"id":"51dc04ec","s":"c","g":"c13","n":"细胞衰老","e":"","d":"细胞衰老是指细胞不可逆地丧失增殖能力后所进入的一种相对稳定的状态，伴有一定的生物化学改变、结构异常和生理功能障碍。衰老是细胞生命活动的客观规律，衰老的细胞趋向死亡；对单细胞生物而言细胞衰老即生物体衰老，对多细胞生物而言细胞衰老并不等于生物体衰老，但二者紧密相关。细胞衰老见于几乎所有生物，其机理在进化中高度保守，酵母、线虫、果蝇、小鼠、人类乃至植物中都存在参与衰老调节的同源基因，如Sir2。","src":"《第12章 细胞衰老与细胞凋亡》p4；《第12章 细胞衰老与细胞凋亡》p6"},{"id":"f6ea5a2b","s":"c","g":"c13","n":"自噬","e":"autophagy","d":"自噬（autophagy）是真核生物中高度保守的降解系统，参与调节细胞物质合成、降解与再利用的代谢平衡。膜包裹部分胞质和需降解的细胞器、蛋白质形成自噬体，再与溶酶体融合成自噬溶酶体，降解其内容物，以实现细胞稳态和细胞器更新。自噬分三型：巨自噬由多种自噬相关蛋白相互作用形成自噬体，把底物投递至溶酶体，是最主要的形式；微自噬经晚期内体或溶酶体膜内陷包裹清除；分子伴侣介导的自噬经Hsp70类分子伴侣把带KFERQ序列的底物送入溶酶体。","src":"《第5章细胞内膜系统（上）》p99；《第12章 细胞衰老与细胞凋亡》p89"},{"id":"466fd9e2","s":"c","g":"c13","n":"自噬性细胞死亡","e":"autophagic cell death","d":"自噬性细胞死亡（autophagic cell death）是以胞质中出现大量自噬泡为特征的细胞死亡形式。电镜下可见胞质中有大量包裹细胞浆和细胞器的空泡结构即自噬泡，胞质浓缩，质膜通透性改变。自噬泡与溶酶体融合，所包裹的待降解物质进入溶酶体，在各种酶作用下分解成氨基酸和核苷酸，并进入三羧酸循环，产生小分子和能量供细胞利用。检测金标准是电镜下看到膜状结构的自噬体，常用WB检测LC3-II/LC3-I转换及荧光显微镜观察LC3点状聚集。","src":"《第12章 细胞衰老与细胞凋亡》p90；《第12章 细胞衰老与细胞凋亡》p93"},{"id":"96c1d701","s":"c","g":"c13","n":"衰老相关β-半乳糖苷酶","e":"SA-Bgal","d":"衰老相关β-半乳糖苷酶（SA-β-gal）是应用最广泛的细胞衰老标志酶之一，属溶酶体β-半乳糖苷酶，由GLB1基因编码。正常细胞中该酶最适pH为4.0~4.5，而衰老细胞溶酶体数量与体积增加、酶活性升高，在pH 6.0的弱酸性条件下即表现出高活性。检测时以X-gal为底物，在pH 6.0下经该酶催化生成深蓝色不溶产物，用普通光学显微镜即可观察到，从而把衰老细胞与年轻、静止期细胞区分开；但破骨细胞、巨噬细胞等也可呈阳性，判断需谨慎。","src":"《第12章 细胞衰老与细胞凋亡》p7；《第12章 细胞衰老与细胞凋亡》p10；网络补充：pmc.ncbi.nlm.nih.gov（SA-β-GAL检测）"},{"id":"e94989b4","s":"c","g":"c15","n":"ADCC","e":"ADCC","d":"ADCC即抗体依赖性细胞介导的细胞毒作用（antibody-dependent cellular cytotoxicity），是抗体的免疫效应之一，与中和、超敏反应、免疫调理等并列。其过程为：IgG等抗体以抗原结合部位特异结合靶细胞表面抗原，Fc段被效应细胞表面的Fc受体识别，把效应细胞招募并激活到靶细胞上，释放杀伤介质将其杀死。中性粒细胞经Fc受体识别IgG包被的细菌并吞噬即属此类；嗜酸性粒细胞也借ADCC杀伤寄生虫、调节过敏性炎症。","src":"《第13章 免疫系统的细胞》p37；《第13章 免疫系统的细胞》p58"},{"id":"d68ec540","s":"c","g":"c15","n":"AID","e":"AID (activation-induced cytidine deaminase)","d":"AID（activation-induced cytidine deaminase，活化诱导的胞苷脱氨酶）是抗体类别转换的关键酶。它把免疫球蛋白重链基因DNA中的胞嘧啶残基脱氨基为尿嘧啶，引发一系列事件，导致恒定区基因被其他恒定区基因替代，即由表达IgM/IgD改而表达IgG、IgE或IgA，可变区与抗原结合特异性不变，AID首先作用于开关S区。抗体库的初级多样性由V(D)J连接（RAG）产生，次级多样性由类别转换重组（AID）产生。","src":"《第13章 免疫系统的细胞》p71"},{"id":"e9f5f411","s":"c","g":"c15","n":"B淋巴细胞","e":"B lymphocyte","d":"B淋巴细胞（B lymphocyte）是介导体液免疫的淋巴细胞，受抗原刺激后经一系列分化、增殖成为浆细胞，浆细胞产生抗体并进入体液，形成特异性免疫即体液免疫，也称抗体间接免疫。在效应器阶段，激活的Th细胞使特异的B细胞增殖并释放抗体，抗体结合于外源入侵物以防感染。B细胞表面有BCR、Fc受体、细胞因子受体、MHC分子和CD分化抗原等膜分子，成熟B细胞一般表达单体IgM和IgD；它属适应性免疫，需抗原刺激，有抗原特异性和免疫记忆性。","src":"《第13章 免疫系统的细胞》p57；《第13章 免疫系统的细胞》p76；《第13章 免疫系统的细胞》p5"},{"id":"388c6884","s":"c","g":"c15","n":"B细胞","e":"B cell (B lymphocyte)","d":"B细胞（B cell）即骨髓依赖性淋巴细胞（bone marrow dependent lymphocyte）。前B细胞在哺乳动物骨髓中再分化成熟为B细胞，故骨髓是其发育成熟的中枢免疫器官。受抗原刺激后，B细胞可增殖分化为浆细胞，合成和分泌免疫球蛋白，主要执行机体的体液免疫功能；此外B细胞还有呈递抗原等其他作用。作为适应性免疫的淋巴细胞，它需抗原刺激而活化，参与特异性、有免疫记忆的免疫应答，并分布于淋巴结、脾等次级淋巴器官。","src":"《第13章 免疫系统的细胞》p49"},{"id":"640ec894","s":"c","g":"c15","n":"B细胞抗原受体","e":"BCR","d":"B细胞抗原受体（BCR）是表达在B细胞表面的膜表面免疫球蛋白（mIg），可特异识别抗原。成熟B细胞一般表达单体IgM和IgD分子，构成初级抗体库；每个B细胞克隆的BCR具有单一的特异性。BCR与Fc受体、细胞因子受体、MHC分子及CD分子等共同组成B细胞膜主要表面分子，其中Fc受体有利于与免疫复合物结合。BCR识别抗原后，在辅助性T细胞经CD40与CD40配体等的协同下，使B细胞活化、增殖并分化为抗体分泌细胞或记忆细胞。","src":"《第13章 免疫系统的细胞》p70；《第13章 免疫系统的细胞》p76"},{"id":"ff056e06","s":"c","g":"c15","n":"CTLA-4","e":"CTLA-4","d":"CTLA-4（cytotoxic T lymphocyte-associated antigen-4，细胞毒性T淋巴细胞相关抗原-4）是T细胞上的受体，在激活初期调节T细胞功能，抑制B7介导的共刺激作用。它于1987年被发现，可阻止T细胞全力攻击入侵者；1996年研究显示抗CTLA-4抗体能使小鼠肿瘤消退。Anti-CTLA4抗体Ipilimumab是首个获美国FDA批准靶向免疫检查点的药物，用于治疗不可切除或转移性黑色素瘤。","src":"《第13章 免疫系统的细胞》p113；《第13章 免疫系统的细胞》p114"},{"id":"147f4702","s":"c","g":"c15","n":"HLA","e":"HLA (human leukocyte associated antigen)","d":"HLA（human leukocyte associated antigen，人类白细胞抗原）是人类主要组织相容性复合体编码的抗原，编码它的基因群称HLA复合体。HLA抗原高度多态，除同卵双生外个体间表型完全相同的可能性极小，是移植排斥反应的主要靶抗原。HLA分I类（HLA-A、B、C等，分布于各种有核细胞表面）与II类（DR、DP、DQ等，表达于B细胞、单核/巨噬细胞等），分别把内源、外源抗原呈递给CD8+、CD4+ T细胞。","src":"《第13章 免疫系统的细胞》p93；《第13章 免疫系统的细胞》p94"},{"id":"32d9ff4f","s":"c","g":"c15","n":"免疫球蛋白","e":"IgG, IgM, IgA, IgE, IgD","d":"免疫球蛋白按重链恒定区不同分为IgG、IgM、IgA、IgE和IgD五类。IgG可通过胎盘传递给新生儿，亲和力高，是血液和组织液的主要抗体；IgM在循环中为大的五聚体，以单体存在于B细胞表面，是初次应答产生的抗体，也是新生儿最先合成的Ig；IgA有单体和二聚体两种形式，分泌型IgA为二聚体，存在于眼泪等外分泌液中；IgE在循环中含量很低，寄生虫感染时大量增加，Fc区结合肥大细胞受体，与过敏有关；IgD是B细胞的抗原受体，记忆细胞中没有。","src":"《第13章 免疫系统的细胞》p75"},{"id":"8cb5fc75","s":"c","g":"c15","n":"MHC I类分子","e":"MHC class I","d":"MHC I类分子（MHC class I）即I类抗原，包括HLA-A、HLA-B和HLA-C等31个基因座，广泛分布于各种有核细胞表面，但神经细胞和成熟滋养层细胞不表达。其分子表面有一个较小的沟，可接纳12~20个氨基酸的肽链。几乎所有细胞都表达MHC I类分子，不断把胞内病毒蛋白、正常细胞碎片结合到MHC-I上，呈递给CD8+ T细胞，是向细胞毒T细胞展示病毒或肿瘤抗原的主要机制；肿瘤与病毒感染细胞常下调MHC I以逃避T细胞免疫。","src":"《第13章 免疫系统的细胞》p94；《第13章 免疫系统的细胞》p99"},{"id":"87ec563a","s":"c","g":"c15","n":"MHC II类分子","e":"MHC class II","d":"MHC II类分子（MHC class II）即II类抗原，包括HLA-DR、DP和DQ等近30个基因座，主要表达在某些免疫细胞表面，如B细胞、单核/巨噬细胞和树突状细胞，即专职抗原呈递细胞。其分子表面有一个较大的沟，可接纳较长的肽链。专职APC通过内吞摄取胞外蛋白（自身或外来），将其降解为肽段并结合到MHC-II分子上，再呈递给CD4+辅助T细胞，从而启动辅助性T细胞应答。只有少数几种抗原呈递细胞表达MHC II类分子。","src":"《第13章 免疫系统的细胞》p94；《第13章 免疫系统的细胞》p101"},{"id":"209df06b","s":"c","g":"c15","n":"NK细胞","e":"NK cell","d":"NK细胞（NK cell）即自然杀伤细胞，属固有免疫的淋巴细胞样白细胞，是机体抵抗肿瘤和病毒感染细胞的第一道防线之一。它监视宿主细胞表面MHC I类蛋白的水平，选择性杀伤MHC I类分子表达低下的细胞，即病毒感染细胞和某些癌细胞，并通过诱导凋亡将其杀死。其胞质颗粒含穿孔素、蛋白多糖、NK细胞毒因子和TNF等。NK细胞受I型干扰素增强活性，被活化巨噬细胞分泌的细胞因子招募至炎症部位，只杀细胞而不递呈抗原。","src":"《第13章 免疫系统的细胞》p32；《第13章 免疫系统的细胞》p34；MBoC 7e 印刷 p1361","x":1},{"id":"3668e0af","s":"c","g":"c15","n":"PD-1","e":"PD-1 (programmed death protein-1)","d":"PD-1（programmed death protein-1，程序性死亡蛋白-1）是T细胞表面的抑制性受体，与其配体PD-L1构成免疫检查点通路。在肿瘤微环境中，肿瘤细胞通过该通路抑制T细胞活化的免疫应答，逃避机体免疫系统的识别和攻击，这是免疫逃逸的重要机制。Anti-PD-1及其配体的抗体Anti-PD-L1能阻断该抑制性信号，有效治疗多种肿瘤，并能诱发持续的肿瘤缓解，与抗CTLA-4抗体同属靶向免疫检查点的干预疗法。","src":"《第13章 免疫系统的细胞》p114；《第13章 免疫系统的细胞》p112"},{"id":"b5f97476","s":"c","g":"c15","n":"PD-L1","e":"PD-L1","d":"PD-L1是PD-1（程序性死亡蛋白-1）的配体，二者构成肿瘤微环境中抑制T细胞活化的通路。肿瘤细胞借PD-L1与T细胞PD-1结合，传递抑制信号、抑制T细胞活性而实现免疫逃逸，故PD-L1成为癌细胞的重要靶标。Anti-PD-L1抗体可阻断该通路，有效治疗多种肿瘤并诱发持续缓解；PD-L1 t-haNK细胞则靶向PD-L1特异性杀伤癌细胞。以PD-L1为靶的疗法与anti-CTLA4、anti-PD-1同属癌症免疫疗法中的检查点阻断。","src":"《第13章 免疫系统的细胞》p114；《细胞生物学历年考题整理》p2","x":1},{"id":"6a000a0b","s":"c","g":"c15","n":"Toll样受体","e":"TLR","d":"Toll样受体（TLR）是先天性免疫系统中的单跨膜非催化性蛋白质，可识别微生物的保守结构即病原相关分子模式（PAMP）。TLR监视并识别各种PAMP，是机体抵抗感染性疾病的第一道屏障，其中TLR4不但识别外源病原体，还可识别内源性物质及降解物。TLRs表达于巨噬细胞和树突状细胞等多种细胞；树突状细胞TLR识别PAMP后活化而成熟，提供获得性免疫的共刺激信号，并诱导IL-1β、IL-6、TNF及趋化性细胞因子产生，调节Th1/Th2平衡。","src":"《第13章 免疫系统的细胞》p27；《第13章 免疫系统的细胞》p30"},{"id":"b7208dda","s":"c","g":"c15","n":"Toll样受体","e":"Toll-like receptor (TLR)","d":"Toll样受体（Toll-like receptor，TLR）是单跨膜非催化性蛋白质，可识别微生物高度保守的病原相关分子模式（PAMP）。PAMP是一类特定微生物病原体及其产物共有的、非特异性而高度保守的分子结构，可被免疫细胞识别。TLR如同天然免疫的“眼睛”，微生物突破皮肤、粘膜等屏障时识别它们并激活免疫应答，是抵抗感染性疾病的第一道屏障。TLR表达于巨噬细胞、树突状细胞，活化后诱导抗微生物防御，产生IL-1β、IL-6、TNF等。","src":"《第13章 免疫系统的细胞》p27；《第13章 免疫系统的细胞》p29"},{"id":"cde390ca","s":"c","g":"c15","n":"T淋巴细胞","e":"T lymphocyte","d":"T淋巴细胞（T lymphocyte）是介导细胞免疫应答的淋巴细胞，在胸腺中发育成熟并产生T细胞受体，以此特异性识别抗原，识别、粘附和消灭被感染、变异和“外源”的细胞，不产生B细胞那样的抗体。其表面标志为TCR与CD3，亚群包括CD4+辅助性T细胞、CD8+细胞毒性T细胞、调节性T细胞和记忆性T细胞。细胞毒T细胞与靶细胞形成免疫突触，释放穿孔素和颗粒酶杀伤靶细胞；辅助T细胞分泌共刺激细胞因子、表达共刺激蛋白，辅助B细胞并激活巨噬细胞。","src":"《第13章 免疫系统的细胞》p78；《第13章 免疫系统的细胞》p80；《第13章 免疫系统的细胞》p83"},{"id":"f7d0316a","s":"c","g":"c15","n":"T细胞","e":"T cell","d":"T细胞（T cell）是在胸腺中成熟的一类淋巴细胞。在胸腺中，T细胞产生细胞表面受体即T细胞受体，该受体可与抗原特异性结合；机体产生大量不同种类的T细胞，以识别、粘附和消灭被感染的、变异的和“外源”的细胞，且不产生B细胞类似的抗体。按功能可分为细胞毒性T细胞（CD8+）、辅助性T细胞和调节性T细胞：细胞毒T细胞识别表面呈递的抗原，能杀死任何呈递同一抗原的靶细胞并形成免疫突触；辅助T细胞刺激B细胞、激活巨噬细胞与细胞毒T细胞。","src":"《第13章 免疫系统的细胞》p78；《第13章 免疫系统的细胞》p80"},{"id":"c60aed9c","s":"c","g":"c15","n":"T细胞受体","e":"TCR","d":"T细胞受体（TCR）是T细胞表面的抗原识别受体，为α/β亚基组成的异源二聚体，每条链含一个可变（V）区和一个恒定（C）区，属免疫球蛋白样结构域。与抗体不同，TCR只有一个抗原结合部位，该部位由Vα和Vβ两个结构域的高变环共同形成。TCR与抗原-MHC复合物结合可引起T细胞激活，但其亲和力通常较低，需CD4、CD8等辅助受体及黏附分子增强细胞间结合强度，才能形成功能性相互作用。T细胞在胸腺中成熟时产生该受体。","src":"《第13章 免疫系统的细胞》p78；《第13章 免疫系统的细胞》p90"},{"id":"a0030595","s":"c","g":"c15","n":"V(D)J重组","e":"V(D)J recombination","d":"V(D)J重组（V(D)J recombination）是淋巴细胞分化时把基因片段拼接成功能性免疫球蛋白链或T细胞受体链基因的体细胞重组过程。它由RAG基因编码的核酸内切酶介导，重组信号序列在RAG介导的基因片段连接中起作用。这是抗体与T细胞受体多样性的来源，属仅见于脊椎动物的较晚进化创新，其机制可能源自更古老的剪切—粘贴型转座子。RAG基因缺陷的小鼠或人无法进行V(D)J重组，因而没有功能性B细胞或T细胞，对感染高度易感。","src":"《第13章 免疫系统的细胞》p68；MBoC 7e Glossary（PDF p1479）"},{"id":"7a4ebbc8","s":"c","g":"c15","n":"等位基因排斥","e":"allelic exclusion","d":"等位基因排斥（allelic exclusion）是发育中的B细胞只使用一条轻链位点和一条重链位点进行基因重排，从而产生仅有一种抗原结合位点的抗体的现象，结果是每个B细胞克隆只表达一种特异性的BCR，即单特异性。若重排后不能装配出VH与VL配对的抗体，细胞便无法制造抗体，通过凋亡而死亡。该机制保证B细胞克隆的单特异性，与克隆选择学说相合，是抗体应答具有高度特异性的基础之一。","src":"《第13章 免疫系统的细胞》p69"},{"id":"2345f8c6","s":"c","g":"c15","n":"克隆清除","e":"clonal deletion","d":"克隆清除（clonal deletion）是免疫耐受的机制之一，指可能与自身抗原反应的淋巴细胞在结合自身抗原后发生凋亡而被清除，从而使免疫系统通常不攻击自身抗原。与之并列的耐受机制还有受体编辑（改变抗原受体）、克隆失能或失活（结合自身抗原后功能上被灭活）和克隆抑制（调节性T细胞抑制其他自身反应性淋巴细胞的活性）。受体编辑与克隆清除主要在胸腺、骨髓等中枢淋巴器官对未成熟细胞起作用，构成中枢耐受。","src":"《第13章 免疫系统的细胞》p55；《第13章 免疫系统的细胞》p56"},{"id":"77a757fa","s":"c","g":"c15","n":"丢失自我识别","e":"missing-self recognition","d":"丢失自我识别（missing-self recognition）是NK细胞的一种识别机制。MHC I类分子是细胞向细胞毒T细胞展示病毒抗原或肿瘤抗原的主要机制，而病毒感染细胞和某些肿瘤细胞会长期下调MHC I类分子，以逃避T细胞介导的免疫；NK细胞正是针对这一适应进化出来的，它监视所有宿主细胞表面MHC I类蛋白的水平，选择性杀伤MHC I类分子表达低下的细胞，通过诱导凋亡将其杀死。因此NK细胞弥补了T细胞免疫的漏洞。","src":"《第13章 免疫系统的细胞》p34"},{"id":"c029c21e","s":"c","g":"c15","n":"单克隆","e":"monoclonal","d":"单克隆（monoclonal）指只有单一B细胞克隆被激活所产生的抗体应答，此时抗体由同一个B细胞克隆产生，因而具有单一的特异性。与之相对，当抗原刺激产生许多种抗体、每种抗体由不同的B细胞克隆产生时，这种应答称为多克隆。单克隆应答的原理被用于制备单克隆抗体：把单个抗体分泌B细胞与骨髓瘤细胞融合成杂交瘤，筛选出单个克隆，即可获得均一而特异的抗体，从而克服多克隆抗体异质性强、量有限的缺点。","src":"《第13章 免疫系统的细胞》p62；MBoC 7e 印刷 p479"},{"id":"fd7e536b","s":"c","g":"c15","n":"主要组织相容性复合体","e":"MHC","d":"主要组织相容性复合体（MHC）是编码能引起强而迅速排斥反应的主要组织相容性抗原的基因群，是一组紧密连锁的基因。控制机体免疫应答能力与调节功能的免疫应答基因（Ir基因）也存在于MHC内，因此MHC不仅与移植排斥反应有关，也广泛参与免疫应答的诱导与调节。人类的MHC即编码HLA的基因群，称HLA复合体。按其编码产物分I类和II类：I类广泛分布于各种有核细胞表面，II类主要表达于B细胞、单核/巨噬细胞等免疫细胞。","src":"《第13章 免疫系统的细胞》p93；《第13章 免疫系统的细胞》p94","x":1},{"id":"0cc2eb11","s":"c","g":"c15","n":"体液免疫","e":"humoral mediated immunity","d":"体液免疫（humoral mediated immunity）是B淋巴细胞受抗原刺激后，经一系列分化、增殖成为浆细胞，由浆细胞产生抗体，抗体进入体液而形成的特异性免疫，也称抗体间接免疫。在效应器阶段，激活的Th细胞使特异的B细胞增殖并释放抗体，这些抗体结合在外源入侵物质上以防止感染。抗体本身不直接杀伤病原，而是通过中和作用、免疫调理、ADCC、超敏反应等效应发挥作用，故称抗体间接免疫；B细胞主要执行机体的体液免疫功能。","src":"《第13章 免疫系统的细胞》p57；《第13章 免疫系统的细胞》p58"},{"id":"5b8a2801","s":"c","g":"c15","n":"克隆选择学说","e":"clonal selection theory","d":"克隆选择学说（clonal selection theory）认为动物首先随机产生巨大多样性的淋巴细胞，每个B细胞各制造一种不同的抗体，能与诱导其产生的那种抗原特异性反应。在克隆阶段，抗体并不离开B细胞，而是嵌在B细胞质膜上；抗原经巨噬细胞呈递后，当膜上抗体识别病原体表面抗原时，该B细胞便迅速分裂增殖，产生大量相同的子代细胞即一个克隆，部分分化为分泌抗体的效应细胞，部分成为记忆细胞。该学说解释了抗体应答的特异性与免疫记忆。","src":"《第13章 免疫系统的细胞》p51；《第13章 免疫系统的细胞》p52"},{"id":"3c2f9a2c","s":"c","g":"c15","n":"免疫器官","e":"","d":"免疫器官是淋巴细胞产生和定居的器官，分初级（中枢）淋巴器官与次级（周围）淋巴器官。初级淋巴器官包括骨髓和胸腺，是淋巴细胞发育成熟的场所；次级淋巴器官包括淋巴结、脾脏、粘膜相关淋巴组织（如派伊尔淋巴集结、阑尾）和皮肤淋巴系统等，是成熟淋巴细胞接触抗原并发生免疫应答的场所。胸腺是胚胎时期第一个出现的免疫器官，是T细胞发育和成熟的场所，其中的选择过程释放对机体有益的T细胞、除去会引起自身免疫反应的T细胞。","src":"《第13章 免疫系统的细胞》p9；《第13章 免疫系统的细胞》p12"},{"id":"afcb7cf9","s":"c","g":"c15","n":"免疫应答","e":"immune response","d":"免疫应答（immune response）是免疫系统对已通过机体被动防御系统的特殊抗原起作用的高效、长时反应。动物首次接触抗原发生初次免疫应答；再次接触同一抗原时潜伏期更短、应答更强更有效，即二次免疫应答，反映抗原特异性免疫记忆。固有免疫应答激活适应性免疫应答，淋巴细胞通常只有在固有免疫系统先被激活后才对外来抗原起反应。按介导细胞分：B细胞介导体液免疫应答，T细胞介导细胞免疫应答。","src":"《第13章 免疫系统的细胞》p53；《第13章 免疫系统的细胞》p7","x":1},{"id":"8b03acf4","s":"c","g":"c15","n":"免疫检查点","e":"","d":"免疫检查点指免疫系统中存在的一些抑制性信号通路，其作用是调节外周组织中免疫反应的持续性和强度以避免组织损伤，并参与维持对自身抗原的耐受。肿瘤细胞通过多种机制逃避机体免疫系统的识别和攻击，得以在体内生存和增殖，即肿瘤免疫逃逸，而利用免疫检查点的抑制性信号通路抑制T细胞活性是肿瘤免疫逃逸的重要机制。因此以CTLA-4、PD-1/PD-L1为靶的抗体可解除抑制、恢复T细胞的杀伤活性，成为肿瘤免疫治疗的重要方向。","src":"《第13章 免疫系统的细胞》p112"},{"id":"f69c6408","s":"c","g":"c15","n":"免疫突触","e":"immunological synapse","d":"免疫突触（immunological synapse）是T细胞与抗原呈递细胞或靶细胞间高度有序的接触界面，由TCR与APC上的抗原-MHC复合物结合、黏附蛋白与其配体结合构成。以细胞毒T细胞杀伤靶细胞为例：T细胞中心体定位于与靶细胞的接触点，含穿孔素和颗粒酶的分泌颗粒沿微管运至中心体，中心体再移向突触，经局部胞吐把内容物释放到靶细胞表面；穿孔素在高Ca2+下组装成跨膜通道，颗粒酶B进入靶细胞激活caspase-3、-7，引发凋亡。","src":"《第13章 免疫系统的细胞》p83；MBoC 7e 印刷 p1392","x":1},{"id":"985666b5","s":"c","g":"c15","n":"免疫系统","e":"","d":"免疫系统是保护机体免受外来生物影响的系统，包括先天性免疫与获得性免疫。先天性免疫是机体内持续抵抗病原体的固有机制，生来就有、始终存在，可遗传给后代、受基因控制而相对稳定，不是专对某一病原起作用，故又称非特异性免疫；获得性免疫是通过免疫应答对新的刺激产生反应的机制，需要抗原刺激、有延时、有抗原特异性并有免疫记忆性，由T、B淋巴细胞及抗体介导。两者协同：固有免疫先启动，并进一步激活适应性免疫。","src":"《第13章 免疫系统的细胞》p4；《第13章 免疫系统的细胞》p5"},{"id":"d35c80d7","s":"c","g":"c15","n":"免疫耐受","e":"immunological tolerance","d":"免疫耐受（immunological tolerance）是确保免疫系统不攻击自身抗原的机制，使机体区分自我与非我。其方式包括：自身反应性淋巴细胞通过受体编辑改变其抗原受体；克隆清除，即结合自身抗原后发生凋亡；克隆失能或失活，即结合自身抗原后功能上失活；以及克隆抑制，即调节性T细胞抑制其他可能自身反应性淋巴细胞的活性。受体编辑与克隆清除主要在中枢淋巴器官对未成熟细胞起作用，构成中枢耐受；克隆失能与克隆抑制主要在外周发挥，构成外周耐受。","src":"《第13章 免疫系统的细胞》p55；《第13章 免疫系统的细胞》p56"},{"id":"59041f0f","s":"c","g":"c15","n":"免疫记忆","e":"immunological memory","d":"免疫记忆（immunological memory）是适应性免疫系统在一次初次免疫应答后对许多抗原形成的长期特性，使再次遇到同一抗原时能引起更迅速、更强的二次免疫应答。以动物实验为例，用抗原A免疫一次，数日后可检出抗体或T细胞应答，应答迅速上升后逐渐下降，此为初次应答；再次接触抗原A时潜伏期更短、应答更强更有效，说明动物“记住”了首次接触。其细胞基础是记忆细胞，它们比初始细胞更快增殖，并产生效应细胞和更多记忆细胞。","src":"《第13章 免疫系统的细胞》p53；《第13章 免疫系统的细胞》p54"},{"id":"1db00ed8","s":"c","g":"c15","n":"单克隆抗体","e":"monoclonal antibody","d":"单克隆抗体（monoclonal antibody）是由杂交瘤细胞系分泌的抗体。杂交瘤由单个B细胞与单个肿瘤细胞融合而成，因此每个杂交瘤产生的抗体完全相同，可作为某一单一类型单克隆抗体的永久而稳定的来源。每种单克隆抗体只识别一种抗原位点，例如蛋白质表面五六个氨基酸侧链组成的特定簇；这种均一的特异性使其在许多用途上比常规抗血清更有用，并能针对复杂混合物中只占微小成分的分子制备抗体。","src":"《第2章 技术》p68；MBoC 7e 印刷 p479","x":1},{"id":"9eb020ad","s":"c","g":"c15","n":"单核细胞","e":"monocyte","d":"单核细胞（monocyte）是白细胞的一种，在骨髓中生成，核大，在血液中循环，离开血流进入组织后成熟为巨噬细胞，是巨噬细胞和树突状细胞的前体。与单核细胞相比，巨噬细胞体积大5~10倍，含更多更复杂的细胞器尤其是溶酶体，吞噬能力更强，产生更高水平的水解酶，杀灭被吞入微生物、激活T细胞及分泌炎症介质的能力也更强。单核细胞（包括巨噬细胞）与B细胞、树突状细胞同属抗原呈递细胞。","src":"《第13章 免疫系统的细胞》p21；《第13章 免疫系统的细胞》p23","x":1},{"id":"67e03222","s":"c","g":"c15","n":"单核细胞","e":"monocytes","d":"单核细胞（monocytes）是在血液中循环的吞噬细胞，由骨髓中的造血干细胞产生，到达器官组织后即成为巨噬细胞，分布到组织各部分形成单核细胞吞噬系统。单核细胞在血液中循环，巨噬细胞则存在于组织中；后者比单核细胞大5~10倍，含更多更复杂的细胞器尤其溶酶体，吞噬能力、产生水解酶的能力、杀灭被吞微生物和激活T细胞的能力以及分泌炎症介质的能力均增强。单核细胞是巨噬细胞和树突状细胞的共同前体。","src":"《第13章 免疫系统的细胞》p21；MBoC 7e 印刷 p1286"},{"id":"1d95042a","s":"c","g":"c15","n":"嗜中性粒细胞","e":"neutrophil","d":"嗜中性粒细胞（neutrophil）是血液中数量最大的白细胞，具高度运动性，能吞噬并消灭微生物尤其是细菌，是急性炎症应答中的主要细胞群。它寿命短，不存在于其他健康组织中，感染时被含甲酰甲硫氨酸的肽、活化巨噬细胞分泌的趋化因子及补体裂解片段迅速从血液招募到感染部位。炎症时肥大细胞释放组胺，与病原体来的化学物质一起吸引中性粒细胞；病原体被抗体包被后，中性粒细胞借Fc受体识别并内吞形成吞噬泡，溶酶体与之结合，病原体被蛋白酶消化。","src":"《第13章 免疫系统的细胞》p36；《第13章 免疫系统的细胞》p43"},{"id":"a985d0d9","s":"c","g":"c15","n":"嗜碱性粒细胞","e":"basophil","d":"嗜碱性粒细胞（basophil）是胞质中含有不同大小嗜碱性颗粒的白细胞，与肥大细胞共同介导超敏反应。当组织受到损伤或发生炎症、过敏反应时，它释放大量组胺，使血管壁通透性增加，导致局部组织水肿，这是机体的一种正常防御反应。在白细胞分类中它约占1%，主要与过敏反应有关；嗜酸性粒细胞约占2%，参与过敏反应与杀伤寄生虫；中性粒细胞约占60%，杀灭细菌；单核细胞约占4%，分化为巨噬细胞；淋巴细胞约占33%，指挥免疫系统。","src":"《第13章 免疫系统的细胞》p38；《第13章 免疫系统的细胞》p39"},{"id":"fd0da3f7","s":"c","g":"c15","n":"嗜酸性粒细胞","e":"eosinophil","d":"嗜酸性粒细胞（eosinophil）是具吞噬作用的粒细胞，可杀伤寄生虫、调节过敏性炎性反应，并参与创伤修复。当病原体过大（如蠕虫等大型寄生虫）而不能被成功吞噬时，一群巨噬细胞、中性粒细胞或嗜酸性粒细胞会聚集在入侵物周围，分泌防御素等损伤性物质并释放呼吸爆发的氧衍生毒性产物，这种集中攻击常足以摧毁病原体。在白细胞分类中它约占2%，与过敏反应和寄生虫杀伤有关；其脱颗粒与ADCC相关，并可通过释放TGF-α等因子促进胶原沉积乃至纤维化。","src":"《第13章 免疫系统的细胞》p37；《第13章 免疫系统的细胞》p39；MBoC 7e 印刷 p1358"},{"id":"b5be17d1","s":"c","g":"c15","n":"固有免疫系统","e":"innate immunity","d":"固有免疫系统（innate immunity）是生物在种系发展和进化过程中逐渐形成的天然防御机制，可遗传给后代、受基因控制并具有相对稳定性；它生来就有，不是某一个体所特有，也不是专对某一病原（抗原）起作用，因此又称非特异性免疫。其应答无需抗原刺激、无延时、无抗原特异性、无免疫记忆性，参与的细胞有巨噬细胞、树突状细胞、中性粒细胞、单核细胞、NK细胞以及嗜酸性粒细胞、嗜碱性粒细胞和肥大细胞，效应分子有细胞因子、补体和急性期蛋白。","src":"《第13章 免疫系统的细胞》p19；《第13章 免疫系统的细胞》p5"},{"id":"cf657f36","s":"c","g":"c15","n":"多克隆抗体","e":"polyclonal","d":"多克隆（polyclonal）指抗原刺激许多不同B细胞克隆、各自产生不同抗体所形成的抗体应答，即当抗原刺激产生许多种抗体、每种抗体由不同B细胞克隆产生时，称为多克隆应答；相比之下单克隆应答只有单一B细胞克隆被激活。用抗原免疫动物后从血清中分离的抗体即为多克隆抗体，它识别蛋白质上多种不同的抗原位点，是异质性混合物，特异性抗体只占血清抗体的一部分，且单只动物所能提供的抗体量有限。","src":"《第13章 免疫系统的细胞》p62；MBoC 7e 印刷 p479"},{"id":"3a79aef0","s":"c","g":"c15","n":"巨噬细胞","e":"macrophage","d":"巨噬细胞（macrophage）是由血液单核细胞分化而来、定居于大多数组织但能游走的吞噬细胞，在免疫应答中兼有清除与抗原呈递两种功能。它寿命长、常驻组织，是感染时最先反应的吞噬细胞，可吞噬入侵微生物；在数量上更重要的是清除衰老细胞和凋亡细胞，例如每人每天被巨噬细胞吞噬的衰老红细胞超过10^11个。此外它还有非特异性免疫防御、免疫自稳和抗肿瘤作用，并合成分泌细胞因子、集落刺激因子、生长因子、干扰素、TNF及补体成分等。","src":"《第13章 免疫系统的细胞》p21；《第13章 免疫系统的细胞》p24；MBoC 7e 印刷 p803","x":1},{"id":"10079404","s":"c","g":"c15","n":"巨噬细胞","e":"macrophages","d":"巨噬细胞（macrophages）由血液中的单核细胞分化而来，分配到组织各部分形成单核细胞吞噬系统；单核细胞在血液中循环，巨噬细胞则存在于组织。它比单核细胞大5~10倍，含更多更复杂的细胞器尤其溶酶体，吞噬能力、产生水解酶的能力、杀灭被吞微生物的能力、激活T细胞的能力及分泌炎症介质的能力都更强。其功能包括非特异性免疫防御、抗原呈递、免疫自稳和抗肿瘤，并分泌细胞因子、补体等生物活性物质；脾红髓中的巨噬细胞负责清除血液中的异物和衰老红细胞。","src":"《第13章 免疫系统的细胞》p21；《第13章 免疫系统的细胞》p15"},{"id":"3d328a8f","s":"c","g":"c15","n":"干扰素","e":"interferon (IFN)","d":"干扰素（interferon，IFN）是一类细胞因子，能保护未被感染的机体细胞免受病毒感染，是固有免疫的重要抗菌物质。它与补体并列：补体引起微生物溶解、促进吞噬并产生炎症反应以吸引白细胞到感染部位，而干扰素则作用于邻近未感染细胞，使其建立抗病毒状态。干扰素是巨噬细胞合成与分泌的生物活性物质之一，与集落刺激因子、生长因子、肿瘤坏死因子、补体成分等一同参与免疫调节，并属于影响和调控多种类型细胞增殖、分化、迁移、成熟和凋亡的活性因子。","src":"《第13章 免疫系统的细胞》p41；《第13章 免疫系统的细胞》p24"},{"id":"aca5fd94","s":"c","g":"c15","n":"抗体","e":"antibody (immunoglobulin)","d":"抗体（antibody）又称免疫球蛋白（immunoglobulin），是活化的B细胞即浆细胞受病原体或异物刺激后分泌的Y形蛋白，可牢固结合病原体或异物分子，使其失活或标记其被吞噬作用、补体引起的裂解所破坏。每个抗体分子由两条相同的重链和两条相同的轻链组成，具有两个相同的抗原结合位点；它位于B细胞表面或游离于血液中，通过特异性结合中和抗原。IgG抗体包被的细菌可经Fc受体被巨噬细胞或中性粒细胞吞噬。","src":"《第13章 免疫系统的细胞》p58；《第13章 免疫系统的细胞》p75；MBoC 7e Glossary（PDF p1445）"},{"id":"497633a4","s":"c","g":"c15","n":"抗体基因组","e":"","d":"抗体基因组指编码抗体分子的基因组织方式。抗体的轻链（L链）由C、V、J三个基因簇编码，重链（H链）由C、V、D、J四个基因簇编码；其中V编码可变区，D编码高变区，J编码连接V与C的结合区，C编码恒定区。这种分段的基因簇结构是V(D)J重组产生抗体多样性的基础：淋巴细胞分化时各基因片段经重组连接成完整的可变区，再与恒定区基因共同表达，使有限的基因片段组合出大量不同的抗体特异性。","src":"《第13章 免疫系统的细胞》p64"},{"id":"dbd34f8d","s":"c","g":"c15","n":"抗体类别转换","e":"class switch","d":"抗体类别转换（class switch）指B细胞在免疫应答中由分泌膜结合型IgM、IgD改为产生IgG、IgE或IgA的过程。其特点是可变区不变、重链恒定区发生变化，因而抗原结合特异性保留而效应功能改变；转换后的IgG、IgE、IgA称二级Ig类，只在抗原刺激后产生，主导二次应答。转换发生在生发中心，经DNA重排即类别转换重组完成，不同恒定区联系不同效应功能。AID是关键酶，把重链基因DNA中的胞嘧啶脱氨为尿嘧啶，先作用于开关S区。","src":"《第13章 免疫系统的细胞》p71；《第13章 免疫系统的细胞》p72"},{"id":"24fa4e9b","s":"c","g":"c15","n":"抗原决定簇","e":"","d":"抗原决定簇是抗原分子中能与抗体或与淋巴细胞表面受体结合的特定部分，亦即抗原表位。一个蛋白质抗原表面可带有多种不同的抗原决定簇，因而能刺激许多不同的B细胞克隆、各自产生针对不同位点的抗体，形成多克隆抗体应答；抗体的特异性即取决于所识别决定簇的差异。在抗原呈递中，抗原被降解为小肽后与MHC分子结合，CD8+ T细胞识别MHC I类分子上的抗原决定簇部位，CD4+ T细胞识别MHC II类分子上的抗原决定簇部位。","src":"《第13章 免疫系统的细胞》p62；《第13章 免疫系统的细胞》p99"},{"id":"ce6eec0d","s":"c","g":"c15","n":"抗原呈递","e":"antigen presentation","d":"抗原呈递（antigen presentation）指细胞在表面表达可被T细胞识别的抗原的过程。蛋白质抗原先降解为小分子肽：与MHC I类分子结合者成为细胞毒T细胞的靶标，与MHC II类分子结合者呈递给T辅助细胞。几乎所有细胞都表达MHC I类分子，不断把胞内病毒蛋白、细胞碎片结合到MHC-I上，供CD8+ T细胞核查；只有树突状细胞、巨噬细胞和B细胞等专职APC表达MHC II类分子，摄取胞外蛋白、降解为肽并呈递给CD4+ T细胞。","src":"《第13章 免疫系统的细胞》p91；《第13章 免疫系统的细胞》p101"},{"id":"64aad220","s":"c","g":"c15","n":"抗原呈递细胞","e":"APC","d":"抗原呈递细胞（APC）是能将抗原以T细胞能识别的方式递呈的细胞，包括B细胞、树突状细胞和单核细胞（包括巨噬细胞），它们具有不同的免疫激活能力。专职APC能内吞胞外蛋白（自身或外来），将其降解为肽段并结合到MHC II类分子上，供CD4+ T细胞识别；只有树突状细胞、巨噬细胞和B细胞等少数几种细胞表达MHC II类分子。树突状细胞表面同时富含MHC I和MHC II，是目前发现的功能最强大的抗原呈递细胞。","src":"《第13章 免疫系统的细胞》p48；《第13章 免疫系统的细胞》p101","x":1},{"id":"8d7e40a4","s":"c","g":"c15","n":"抗原表位","e":"epitope","d":"抗原表位（epitope）又称抗原决定簇，是抗原分子中能被高度特异的单克隆抗体所识别的特定部位。在蛋白质工程中，任何基因都可被改造，使其所编码的蛋白带上一段额外的氨基酸序列作为特异性识别标签，以便简化并加快后续的蛋白纯化；这种识别标签常就是抗原表位，可用相应单克隆抗体经亲和层析或免疫沉淀把目标蛋白纯化出来。另一些标签则专为纯化设计，如重复的组氨酸序列可结合镍、铜等金属离子。","src":"MBoC 7e 印刷 p486；《第13章 免疫系统的细胞》p62","x":1},{"id":"f5dea6f1","s":"c","g":"c15","n":"杂交瘤细胞","e":"hybridoma","d":"杂交瘤细胞（hybridoma）是由肿瘤细胞与另一种细胞融合而成的杂交细胞系。制备单克隆抗体时，把经免疫小鼠的单个抗体分泌B淋巴细胞与来源于转化B淋巴细胞系的骨髓瘤细胞融合，得到的杂交细胞既保有制造某种特定抗体的能力，又能在培养中无限增殖，从而大量制备均一的抗体。B淋巴细胞在培养中寿命有限，杂交瘤则可作为永久而稳定的抗体来源；操作上常用小鼠脾（B淋巴细胞）与骨髓瘤细胞融合，并用HAT培养基筛选。","src":"MBoC 7e 印刷 p479；《第2章 技术》p68","x":1},{"id":"36fc8517","s":"c","g":"c15","n":"树突状细胞","e":"dendritic cell","d":"树突状细胞（dendritic cell）是一类起源于骨髓、散在分布、发生迁移的白细胞，因表面有长短不一的细密突起而得名。它数量不足外周血单个核细胞的1%，但表面具有丰富的抗原呈递分子MHC I和MHC II，是目前发现的功能最强大的抗原呈递细胞。它摄取、加工处理抗原并呈递给T细胞，是激活初始T细胞所必需；捕获抗原后迁移入淋巴器官，TLR识别PAMP后成熟，提供共刺激信号，把固有免疫与适应性免疫连接起来。","src":"《第13章 免疫系统的细胞》p25；MBoC 7e 印刷 p1363","x":1},{"id":"63bf56e3","s":"c","g":"c15","n":"树突状细胞","e":"dendritic cells (DC)","d":"树突状细胞（dendritic cells，DC）是一类起源于骨髓、散在分布并具有迁移能力的白细胞，数量不足外周血单个核细胞的1%，表面却富含MHCⅠ和MHCⅡ类抗原递呈分子，并具有长短不一的细密突起。它是目前发现的功能最强大的抗原呈递细胞，能把捕获的抗原递呈给T、B细胞，从而启动免疫应答。淋巴结和脾脏等次级淋巴器官中均有分布，捕获抗原后可将抗原信息交给淋巴细胞，因而被视为连接固有免疫与适应性免疫系统的桥梁。","src":"《第13章 免疫系统的细胞》p25"},{"id":"36f805f1","s":"c","g":"c15","n":"浆细胞","e":"plasma cell","d":"浆细胞（plasma cell）是B淋巴细胞受抗原刺激后经一系列分化、增殖形成的效应B细胞，主要执行体液免疫。其最成熟形态的细胞内充满发达的粗面内质网，正忙于合成抗体，并大量分泌免疫球蛋白进入体液，抗体结合到外源入侵物上以阻止感染。与效应T细胞不同，效应T细胞几乎不含内质网、分泌的是细胞因子而非抗体；B细胞来源的抗体经血流广泛分布，而T细胞来源的细胞因子主要作用于局部。浆细胞由骨髓中的前B细胞分化成熟而来，是抗体介导免疫的效应细胞。","src":"《第13章 免疫系统的细胞》p49；MBoC 7e 印刷 p1366"},{"id":"00068246","s":"c","g":"c15","n":"淋巴结","e":"lymph node","d":"淋巴结（lymph node）是起淋巴液免疫过滤器功能的次级（周围）淋巴器官，主要由T细胞、B细胞、树突状细胞和巨噬细胞组成。绝大多数组织液都会流经淋巴结，其中的巨噬细胞与树突状细胞捕获抗原后把抗原递呈给T、B细胞，从而引起机体的免疫反应。淋巴结与脾脏、黏膜相关淋巴组织、皮肤淋巴系统同属次级淋巴器官。淋巴细胞经血液进入淋巴结时，通过归巢受体与毛细血管后微静脉内皮细胞弱黏附并滚动，再在趋化因子与整合素的作用下稳定黏附并进入淋巴结。","src":"《第13章 免疫系统的细胞》p16；MBoC 7e 印刷 p1369"},{"id":"559019d9","s":"c","g":"c15","n":"炎症反应","e":"","d":"炎症反应是固有免疫的重要防御机制之一。当细胞受到攻击时，肥大细胞释放组胺，组胺与来自病原体的化学物质共同作用，把具有抗体Fc受体的中性粒细胞吸引到受攻击部位；病原体被抗体包被后与中性粒细胞表面的Fc受体结合，经内吞形成吞噬泡，溶酶体与之融合，病原体被蛋白酶消化。补体也能产生炎症反应以吸引白细胞到感染部位。此外，凋亡过程中细胞膜保持完整、细胞内含物不外泄，因此不引发机体的炎症反应，这与细胞坏死形成对照。","src":"《第13章 免疫系统的细胞》p43；p41；《第12章 细胞衰老与细胞凋亡》p30"},{"id":"578990e5","s":"c","g":"c15","n":"病原相关分子模式","e":"PAMP (pathogen-associated molecular patterns)","d":"病原相关分子模式（PAMP，pathogen-associated molecular patterns）是一类或一群特定微生物病原体及其产物共有的、非特异性且高度保守的分子结构，可被免疫细胞识别。识别它们的受体是Toll样受体（TLR），TLR为单跨膜非催化性蛋白质，可识别微生物的保守结构，是机体抵抗感染性疾病的第一道屏障。TLR表达于巨噬细胞、树突状细胞等多种细胞，其中TLR4既能识别外源病原体，也能识别内源性物质及其降解物。","src":"《第13章 免疫系统的细胞》p27"},{"id":"33ba5bd5","s":"c","g":"c15","n":"白细胞分化抗原","e":"CD (cluster of differentiation)","d":"白细胞分化抗原（CD，cluster of differentiation）是血细胞在分化成熟为不同谱系、不同阶段及活化过程中出现或消失的细胞表面标记分子，多为膜糖蛋白，已发现超过350种。1982年第一届人类白细胞分化抗原国际会议确立CD命名法：用以单克隆抗体鉴定为主的聚类分析法，把不同实验室抗体识别的同一分化抗原归为一个分化群。常见者如T细胞的CD3、CD4、CD8，B细胞的CD19，NK细胞的CD56，单核／巨噬细胞的CD14。","src":"网络补充：baike.baidu.com《白细胞分化抗原》；pmc.ncbi.nlm.nih.gov CD命名"},{"id":"34eb8934","s":"c","g":"c15","n":"穿孔素","e":"perforin","d":"穿孔素（perforin）是细胞毒性T细胞分泌的成孔蛋白。Tc细胞识别被病毒、细菌或真菌感染的体细胞表面的抗原，在病毒复制之前把感染细胞杀死；杀伤时Tc细胞与靶细胞形成免疫突触，在突触处发生局部胞吐，把穿孔素与颗粒酶B等释放到靶细胞表面。胞外液中的高浓度Ca2+使穿孔素在靶细胞膜上组装成孔道，颗粒酶由此进入，激活caspase级联，使靶细胞凋亡。Tc细胞不能杀死游离的病毒颗粒，其激活需要相应的病毒抗原，白细胞介素可激活Tc细胞。","src":"《第13章 免疫系统的细胞》p81；MBoC 7e 印刷 p1392"},{"id":"9bf3fcd7","s":"c","g":"c15","n":"类别转换","e":"class-switch recombination","d":"类别转换（class-switch recombination）发生在抗体应答中：抗原激活B细胞后，膜上表达和分泌的免疫球蛋白类别从IgM转换为IgG、IgA、IgE等其他类别。转换时抗体的可变区不变，只有重链恒定区发生改变，因而抗原结合特异性不变而效应功能改变。在DNA水平上这是一种不可逆的改变，涉及IgH基因座中各恒定区基因上游的转换区。B细胞由产生IgM和IgD转为产生次级类别免疫球蛋白，是体液免疫应答走向成熟的重要标志。","src":"《第13章 免疫系统的细胞》p71；MBoC 7e Glossary（PDF p1450）"},{"id":"aa8c3161","s":"c","g":"c15","n":"粒细胞","e":"granulocytes","d":"粒细胞（granulocytes）是白细胞的一个类群，通称炎性细胞、多型核白细胞，在炎症和固有免疫中发挥清除微生物和死亡组织的作用，并受T细胞分泌的细胞因子刺激而活化。其细胞只有一个核，但核呈不规则的叶状。根据对染色剂的不同反应，外周血中的粒细胞可分为嗜中性、嗜酸性与嗜碱性三种类型。嗜碱性粒细胞和肥大细胞胞质中含不同大小的嗜碱性颗粒，介导超敏反应；被IgG抗体包被的细菌则可被中性粒细胞经Fc受体识别后吞噬。","src":"《第13章 免疫系统的细胞》p35；p38；p58"},{"id":"9f85b263","s":"c","g":"c15","n":"细胞免疫","e":"cellular mediated immunity","d":"细胞免疫（cellular mediated immunity）是以T细胞为主要细胞的适应性免疫。与B细胞不同，T细胞通过产生一类称为T细胞受体的蛋白质来识别特殊抗原，而且需要抗原经抗原呈递细胞处理后呈递才能被识别。在细胞免疫中，细胞毒性T细胞直接杀伤带有相应抗原的靶细胞，辅助T细胞则通过分泌细胞因子招募并激活其他免疫细胞。T细胞在胸腺中成熟，成熟后分布于淋巴结、脾脏等次级淋巴器官，并在血液与淋巴之间再循环。","src":"《第13章 免疫系统的细胞》p79；p97；p46"},{"id":"e2c09a7e","s":"c","g":"c15","n":"细胞因子","e":"cytokine","d":"细胞因子（cytokine）是细胞分泌的、在细胞间通讯中充当局部介质的胞外信号蛋白或多肽，能影响并调控多种细胞的增殖、分化、迁移、成熟和凋亡，包括干扰素、白细胞介素、集落刺激因子、肿瘤坏死因子等。巨噬细胞可合成与分泌集落刺激因子、生长因子、干扰素、肿瘤坏死因子及补体成分等生物活性物质。细胞因子既参与固有免疫也参与适应性免疫：TLR活化后可诱导产生IL-1β、IL-6和TNF以及趋化型细胞因子，调节Th1与Th2的平衡。","src":"《第13章 免疫系统的细胞》p24；p30；MBoC 7e Glossary（PDF p1452）"},{"id":"0191adcb","s":"c","g":"c15","n":"细胞因子","e":"cytokines","d":"细胞因子（cytokines）是细胞信号传导中重要的一类小分子蛋白，分子量约5～20 kDa，由巨噬细胞、Th细胞等多种细胞分泌，白细胞介素等淋巴因子即属此类，可刺激B细胞和T细胞分裂。它们既是固有免疫的效应分子（与补体、急性期蛋白并列），也参与适应性免疫。巨噬细胞分泌的集落刺激因子、生长因子、干扰素、肿瘤坏死因子均属细胞因子；TLR活化后诱导产生的IL-1β、IL-6、TNF及趋化型细胞因子可调节Th1与Th2的平衡。","src":"《第13章 免疫系统的细胞》p24；p5；p30"},{"id":"63cd9b75","s":"c","g":"c15","n":"细胞毒性T细胞（Tc）","e":"cytotoxic T cells (CD8+)","d":"细胞毒性T细胞（cytotoxic T cells，CD8+）是表达CD8、专司杀伤的T细胞。它能识别靶细胞表面呈递的抗原，并可杀伤任何呈递相同抗原的靶细胞，杀伤时与靶细胞形成免疫突触。活化的Tc细胞在突触处局部胞吐，释放穿孔素与颗粒酶，穿孔素在靶细胞膜上形成孔洞使靶细胞溶解，颗粒酶则激活caspase级联诱导凋亡。Tc细胞不能杀死游离的病毒颗粒，激活前需要相应的病毒抗原，白细胞介素可激活Tc细胞。","src":"《第13章 免疫系统的细胞》p80；p81；MBoC 7e 印刷 p1392"},{"id":"7f08f93c","s":"c","g":"c15","n":"肥大细胞","e":"mast cell","d":"肥大细胞（mast cell）是胞质中含有不同大小嗜碱性颗粒的细胞，与嗜碱性粒细胞相似，介导超敏反应。当组织受到损伤或发生炎症、过敏反应时，肥大细胞释放大量组胺，使血管壁通透性增加，导致局部组织水肿，这属于机体的一种正常防御反应。在炎症反应中，肥大细胞释放的组胺与来自病原体的化学物质共同把中性粒细胞吸引到受攻击部位；IgE由效应B细胞产生后结合到肥大细胞表面Fc受体，引发组胺分泌，是花粉症、哮喘、荨麻疹等过敏症状的主要原因。","src":"《第13章 免疫系统的细胞》p38；p43；p59；MBoC 7e 印刷 p1375"},{"id":"45c666f7","s":"c","g":"c15","n":"肿瘤免疫逃逸","e":"","d":"肿瘤免疫逃逸指肿瘤细胞通过多种机制逃避机体免疫系统的识别和攻击，从而得以在体内生存和增殖的现象。免疫系统中存在一些抑制性信号通路即免疫检查点，可调节外周组织中免疫反应的持续性和强度，避免组织损伤，并参与维持对自身抗原的耐受。肿瘤细胞利用免疫检查点的抑制性信号通路抑制T细胞活性，是其逃避免疫杀伤的重要机制。针对免疫系统而非肿瘤本身的免疫疗法，正是干预这一环节的治疗思路。","src":"《第13章 免疫系统的细胞》p112"},{"id":"cbbaeed1","s":"c","g":"c15","n":"胸腺","e":"thymus","d":"胸腺（thymus）是胚胎时期第一个出现的免疫器官，属初级（中枢）淋巴器官，是T细胞发育和成熟的场所，其重量自出生到青春期上升，青春期后逐渐萎缩。胸腺中T细胞成熟的过程是一个选择过程：对机体免疫系统有益的T细胞被释放出去，引起有害自身免疫反应的T细胞则被除去。在胸腺皮质上皮细胞上，表达T细胞受体的胸腺细胞若能以适当亲和力结合自身肽-MHC复合物，即被信号诱导存活并继续成熟，此过程称为阳性选择。","src":"《第13章 免疫系统的细胞》p12；MBoC 7e 印刷 p1390"},{"id":"0999daab","s":"c","g":"c15","n":"脾脏","e":"","d":"脾脏（spleen）是最大的次级淋巴器官，含B细胞、T细胞、巨噬细胞、树突状细胞、自然杀伤细胞及红细胞，可以被看成一个免疫集会中心。它属次级（周围）淋巴器官，与淋巴结、黏膜相关淋巴组织、皮肤淋巴系统并列。脾脏不仅参与免疫应答，还是机体血液的免疫过滤器，红髓中的巨噬细胞对清除血液中无用的外来异物和衰老的红细胞起着重要作用。与淋巴结相似，捕获抗原的巨噬细胞及树突状细胞把抗原递呈给T、B细胞时，就会引起机体的免疫反应。","src":"《第13章 免疫系统的细胞》p15；p10"},{"id":"191a82bc","s":"c","g":"c15","n":"自然杀伤细胞","e":"natural killer cell (NK cell)","d":"自然杀伤细胞（natural killer cell，NK细胞）是固有免疫系统的细胞毒性细胞，可杀伤病毒感染细胞和某些癌细胞。与T、B细胞不同，它不需抗原刺激即可迅速发挥作用，是宿主防御的第一道防线。NK细胞监视宿主细胞表面MHCⅠ类分子的水平，选择性杀伤MHCⅠ类分子表达低下的细胞，这类细胞主要是病毒感染细胞和某些癌细胞。其杀伤方式不是溶解，而是诱导靶细胞凋亡；抑制性受体识别MHCⅠ等位基因，据此判断靶细胞是否异常。","src":"《第13章 免疫系统的细胞》p32；MBoC 7e Glossary（PDF p1466）"},{"id":"c3c1d1f5","s":"c","g":"c15","n":"补体","e":"complement","d":"补体（complement）是存在于血清、组织液和细胞膜表面的一组不耐热、经活化后具有酶活性的蛋白质，因由抗体激活并与抗体协同作用、起补充作用而得名。补体蛋白由肝脏产生，是先天免疫系统的一部分，可导致细胞溶解或崩解，并给吞噬细胞传递信号，提示有细胞需要清除。其作用包括引起微生物溶解、促进吞噬作用、产生炎症反应以吸引白细胞到感染部位。巨噬细胞也能合成和分泌补体成分，与细胞因子等一同参与非特异性免疫防御。","src":"《第13章 免疫系统的细胞》p41；p24"},{"id":"8f3ad211","s":"c","g":"c15","n":"记忆细胞","e":"memory cells","d":"记忆细胞（memory cells）是淋巴细胞受抗原刺激后，除分化为效应细胞之外形成的另一类细胞。初次应答中，大多数活化细胞成为发挥功能后通常死亡的效应细胞，另一些则成为记忆细胞；再次接触同一抗原时，记忆细胞比初始细胞更迅速、更容易、更高效地应答，增殖并产生效应细胞和更多记忆细胞。记忆T细胞迁移到淋巴结，可被二次入侵快速激活。记忆细胞群体可在动物一生中持续存在，即使没有特异性抗原，从而提供对病原体的终身保护。","src":"《第13章 免疫系统的细胞》p54；p87；MBoC 7e 印刷 p1368"},{"id":"85f21e8a","s":"c","g":"c15","n":"辅助T细胞","e":"helper T cells (Th)","d":"辅助T细胞（helper T cells，Th）是表达CD4、帮助免疫系统其他细胞的T淋巴细胞，又称CD4+T细胞。它不直接杀伤靶细胞，而是通过分泌白细胞介素等细胞因子发挥作用：刺激B细胞增殖，激活巨噬细胞和细胞毒性T细胞。外源性抗原经加工处理后由树突状细胞等抗原呈递细胞呈递给辅助T细胞；在效应器阶段，激活的Th细胞使特异的B细胞增殖并释放抗体。Th1主要支持炎症反应，Th2则主要激活B细胞的抗体应答，二者的平衡受细胞因子调节。","src":"《第13章 免疫系统的细胞》p46；p57；p105"},{"id":"4b57eb9f","s":"c","g":"c15","n":"适应性免疫","e":"adaptive immunity","d":"适应性免疫（adaptive immunity）是通过免疫应答对新的刺激产生反应的机制，与固有免疫相对：它需要抗原刺激，有延时性，具有抗原特异性与免疫记忆性，由T、B淋巴细胞介导，效应分子为细胞因子和各种抗体。固有免疫则无需抗原刺激、无延时、无抗原特异性、无免疫记忆性，由自然杀伤细胞、肥大细胞、吞噬细胞、树突状细胞以及补体、急性期蛋白等承担。固有免疫应答可激活适应性免疫应答：淋巴细胞通常只有在固有免疫系统先被激活之后才对外来抗原起反应。","src":"《第13章 免疫系统的细胞》p5；p7；p8"},{"id":"3a3921f1","s":"c","g":"c15","n":"骨髓","e":"","d":"骨髓（bone marrow）是初级（中枢）淋巴器官，也是一切免疫细胞的发源地，含造血干细胞和间质干细胞两种干细胞，前者产生白细胞、红细胞和血小板。骨髓是B细胞分化成熟的场所：哺乳动物骨髓中的前B细胞再分化成熟为B细胞，B细胞即骨髓依赖性淋巴细胞，在抗原刺激下可增殖分化为浆细胞，合成和分泌免疫球蛋白，主要执行体液免疫功能。骨髓与胸腺同属初级淋巴器官，是淋巴细胞发育成熟的起点。","src":"《第13章 免疫系统的细胞》p49；p10；p11"},{"id":"dd633c66","s":"c","g":"c14","n":"BRCA1","e":"BRCA1","d":"BRCA1是抑癌基因，其突变存在剂量效应，单个突变即可使三阴乳腺癌发病升高。BRCA1与BRCA2共同调控DNA双链断裂修复的两条途径——同源重组和非同源末端连接。二者功能失活时细胞修复双链断裂的能力受损，此时若用PARP抑制剂抑制PARP介导的单链损伤修复，未修复的单链损伤经复制将转化为双链断裂，细胞因而死亡。这种利用合成致死原理靶向失活抑癌基因的治疗，是PARP抑制剂用于BRCA1/2缺陷肿瘤的依据。","src":"《第14章 癌细胞》p82；p81；MBoC 7e 印刷 p1205","x":1},{"id":"c6402adf","s":"c","g":"c14","n":"CAR-NK","e":"CAR-NK","d":"CAR-NK即嵌合抗原受体NK细胞（chimeric antigen receptor-NK，CAR-NK），是仿造CAR-T细胞的设计，把人工合成的CAR结构通过转基因工程的方式转染NK细胞而获得的细胞。它一方面保留NK细胞原有的功能，另一方面又能把目标精准锁定在特定的抗原蛋白上。其与CAR-T的设计思路相同，都是让效应细胞获得针对特定肿瘤抗原的识别能力；而嵌合抗原受体由单链抗体片段等部分构成，是这类细胞疗法共同的分子核心。","src":"《第14章 癌细胞》p92；p89"},{"id":"cb7de1d7","s":"c","g":"c14","n":"DeGregori模型","e":"","d":"DeGregori模型是关于突变与癌症关系的假说：突变能引发癌症，但不一定能提高细胞的适应性。健康的组织生态系统促使健康细胞战胜癌变细胞；当组织生态系统发生变化，如衰老、吸烟或处于压力状态时，癌变细胞迅速适应变化后的环境，并在自然选择中传承获胜。除突变激活之外，癌症可能还需要与年龄等相关的组织变化来获取更有利的生存条件，从而在与健康细胞的竞争中获胜。这一模型把癌症看作细胞与组织生态系统共同演化的结果。","src":"《第14章 癌细胞》p43"},{"id":"ffeae363","s":"c","g":"c14","n":"EGFR","e":"EGFR","d":"EGFR（epidermal growth factor receptor）即表皮生长因子受体，又称ErbB-1或HER1，是表皮生长因子受体（HER）家族的成员之一。EGFR的突变常见于肺癌，如L858R和19号外显子缺失，是小分子靶向药物的重要作用靶点。原癌基因可通过显性突变获得功能而转变为癌基因，EGFR、HER2、B-Raf、Bcr-Abl均属此类，针对它们的抑制剂构成肿瘤靶向治疗的基础。","src":"《第14章 癌细胞》p75；p78；p25"},{"id":"ce1f1db5","s":"c","g":"c14","n":"HER2","e":"HER2","d":"HER2（human epidermal growth factor receptor 2）又称erbB2或NEU，是表皮生长因子受体（HER）家族成员之一。HER2在癌细胞中过表达，导致癌细胞不受控制地增殖，是原癌基因因过表达而转变为癌基因的典型例子。Her2蛋白在约25%的乳腺癌中高表达，它是参与乳腺上皮正常发育的受体酪氨酸激酶；名为曲妥珠单抗（商品名赫赛汀）的单克隆抗体能结合Her2并抑制其功能，已成为这类乳腺癌的标准疗法。","src":"《第14章 癌细胞》p75；MBoC 7e 印刷 p1209"},{"id":"6dff1f8d","s":"c","g":"c14","n":"Hallmarks of Cancer","e":"Hallmarks of Cancer","d":"Hallmarks of Cancer即“癌症的标志”，源自Hanahan与Weinberg发表于Cell的综述，用以归纳癌细胞区别于正常细胞的一组基本特性。按讲义所述，癌细胞的基本特点包括细胞生长分裂失去控制、失去接触抑制、自分泌生长刺激、脱分化、细胞间相互作用改变、染色体非整倍性改变、避免程序性死亡以及血管生成等。该框架后来被扩展到肿瘤干细胞，形成“癌症干性的标志”，包括肿瘤启动、自我更新、分化潜能、促进转移与治疗抵抗等特性。","src":"《第14章 癌细胞》p17；p63；MBoC 7e 印刷 p1216"},{"id":"ec749d43","s":"c","g":"c14","n":"PARP","e":"PARP","d":"PARP即聚腺苷二磷酸核糖聚合酶（poly(ADP-ribose) polymerase），是修复DNA单链损伤至关重要的酶。当PARP抑制剂选择性抑制PARP介导的单链修复时，未修复的单链损伤经过复制后将转化为DNA双链断裂。对BRCA1/2缺陷、同源重组修复不足的肿瘤细胞，这种断裂无法修复而致细胞死亡，即PARP抑制剂的合成致死原理。此外，DNA损伤积累使PARP活化，大量消耗NAD+，致糖酵解受抑、ATP下降，引发程序性细胞坏死。","src":"《第14章 癌细胞》p82；《第12章 细胞衰老与细胞凋亡》p85"},{"id":"9be0c899","s":"c","g":"c14","n":"Peto悖论","e":"Peto's Paradox","d":"Peto悖论（Peto's Paradox）指跨物种比较时，体型大小、寿命与癌症发生率之间并不存在相关性，这与细胞越多、寿命越长则患癌概率越高的预期相矛盾。按预期，细胞数量多、分裂次数多的动物更易累积致癌突变；然而大型、长寿的物种癌症发病率并不更高，如大象的细胞数远多于人，患癌率却更低，而小鼠的患癌概率反而高于人。该现象提示，寿命长、体型大的物种在演化中共同获得了更有效的肿瘤抑制机制。","src":"网络补充：kepuchina.cn《佩托悖论》；peopleapp.com"},{"id":"66522eea","s":"c","g":"c14","n":"Rb基因","e":"Rb gene","d":"Rb基因是视网膜母细胞瘤易感基因，是第一个被发现的抑癌基因。RB蛋白控制细胞周期进展，去磷酸化的RB具有抑制细胞增殖的活性，是RB的活性形式。家族性视网膜母细胞瘤患者遗传一个突变的Rb基因，其细胞只需再失活仅存的一个正常拷贝即可发生肿瘤，因此多数带遗传突变者双眼出现多个肿瘤；而非遗传性患者须在同一个细胞中先后失活两个正常拷贝，概率极低，约三万正常人才有一人单眼发生一个肿瘤。这体现了抑癌基因突变的隐性性质。","src":"《第14章 癌细胞》p27；MBoC 7e 印刷 p1183"},{"id":"f0e17a47","s":"c","g":"c14","n":"VEGF","e":"VEGF","d":"VEGF即血管内皮生长因子（vascular endothelial growth factor），是刺激血管生成的主要因子。按Folkman理论，没有血管生成时实体肿瘤单纯依靠弥散获取氧气及营养物质，生长范围只能维持在1～2 mm³；肿瘤组织生长范围超过2～3 mm³时，必须依靠血管生成提供足够的氧气和营养物质，才能维持快速生长。因此VEGF及其受体成为抗血管生成靶向治疗的靶点，与凝血酶敏感蛋白等一同用于阻止肿瘤血管生成。","src":"《第14章 癌细胞》p12；p71；MBoC 7e 印刷 p911"},{"id":"91703bc0","s":"c","g":"c14","n":"克隆演化","e":"clonal evolution","d":"克隆演化（clonal evolution）是解释肿瘤细胞群体形成的模型。癌症由体细胞突变引起，涉及若干轮突变的积累，即多击模型；大多数癌衍生于单个畸变的细胞。相对于正常细胞，癌细胞的遗传稳定性更差，每一个突变细胞都可能克隆扩增成一个亚群甚至肿瘤实体，在自然选择作用下，具有生长优势的克隆被保留并不断演化。因此肿瘤细胞群体在遗传上并不均一，这种异质性是肿瘤进展与耐药的基础，肿瘤与其转移灶的关系呈现典型的达尔文进化图景。","src":"《第14章 癌细胞》p38；p47；MBoC 7e 印刷 p1192"},{"id":"02d2bb5a","s":"c","g":"c14","n":"驱动突变","e":"driver mutations","d":"驱动突变（driver mutations）是指在肿瘤发生中被选择出来、赋予细胞生长优势因而对疾病发展起因果作用的突变。癌细胞中已鉴定出大量突变，其中多数只是乘客突变（passenger mutations）：它们因基因组不稳定而碰巧与驱动突变发生在同一个细胞中，对癌症的发生并无作用。判断驱动突变的一个标准是出现频率——作用于疾病相关基因的驱动突变会在许多患同一类型肿瘤的个体中反复出现，而不带来选择优势的乘客突变则很少被检出。","src":"MBoC 7e 印刷 p1186；《第14章 癌细胞》p49"},{"id":"44d200ef","s":"c","g":"c14","n":"免疫检查点单抗","e":"immune checkpoint antibody","d":"免疫检查点单抗是以免疫检查点分子为靶点的单克隆抗体，属癌症免疫疗法中的干预疗法。免疫系统中存在一些抑制性信号通路即免疫检查点，可调节外周组织中免疫反应的持续性和强度，避免组织损伤，并参与维持对自身抗原的耐受；肿瘤细胞利用这些抑制性通路抑制T细胞活性，是其逃避免疫杀伤的重要机制。因此用抗体阻断CTLA-4、PD-1或其配体PD-L1，可解除对T细胞的抑制、恢复抗肿瘤免疫。它与CAR-T等细胞疗法同属针对免疫系统而非肿瘤本身的治疗策略。","src":"《第13章 免疫系统的细胞》p112；《第14章 癌细胞》p71"},{"id":"9aee0502","s":"c","g":"c14","n":"原癌基因","e":"proto-oncogene","d":"原癌基因（proto-oncogene）是控制细胞生长和分裂的一类正常基因，其突变能引起正常细胞转变成癌细胞。这种突变通常是使之处于持续活化状态，因而促进细胞增殖，如src、ras、smads、myc等。按癌基因产物活性高低，癌症相关基因分为两类：功能获得性突变可驱动细胞癌变的一类为原癌基因，其突变、过度活化或过表达的产物称为癌基因；功能丧失性突变者则属抑癌基因。原癌基因还可因过表达、基因扩增等方式被激活。","src":"《第14章 癌细胞》p22；p23；MBoC 7e 印刷 p1179","x":1},{"id":"27f38acd","s":"c","g":"c14","n":"可塑性","e":"plasticity","d":"可塑性（plasticity）是肿瘤干细胞的“新兴特征标志”，指肿瘤干细胞能够在不同状态之间转换，包括从更为分化的状态逆转回到干细胞样状态。这种可塑性是癌症发展、治疗抵抗和转移的关键因素。肿瘤干细胞与成体干细胞有许多相似之处，成体干细胞与祖细胞都有转化成肿瘤干细胞的能力，终末分化细胞以及去分化的肿瘤细胞也具有这种能力；干细胞本身还能迁移到器官损伤部位并分化，参与组织再生。","src":"《第14章 癌细胞》p65；p62；《第11章 细胞分化与基因表达调控》p58"},{"id":"157f830a","s":"c","g":"c14","n":"合成致死","e":"synthetic lethality","d":"合成致死（synthetic lethality）是指两个或多个基因表达同时缺陷时导致细胞死亡，而其中仅一个基因缺陷并不致死的遗传关系。这种缺陷可由突变、表观遗传改变或某一基因的抑制剂造成。在合成致死筛选中，必须从一种不杀死细胞、但可能带来某种表型的突变出发。该原理已被用于靶向治疗：BRCA1或BRCA2缺陷的肿瘤细胞同源重组修复受损，对PARP抑制剂敏感，二者构成合成致死关系，是抑癌基因失活后仍可被精准打击的范例。","src":"《第14章 癌细胞》p81；p82"},{"id":"c5e21377","s":"c","g":"c14","n":"嵌合抗原受体T细胞免疫疗法","e":"CAR-T (chimeric antigen receptor T-cell immunotherapy)","d":"嵌合抗原受体T细胞免疫疗法（CAR-T）是把嵌合抗原受体经转基因工程导入T细胞的细胞免疫疗法。该受体由肿瘤相关抗原结合区（scFv段）、胞外铰链区、跨膜区和胞内信号区组成，使T细胞能识别特定肿瘤抗原并被激活，从而杀伤肿瘤。癌症免疫疗法针对的是免疫细胞而不是癌细胞，CAR-T与淋巴因子激活的杀伤细胞（LAK）、细胞因子激活的杀伤细胞（CIK）、CIK与树突状细胞混合疗法同属细胞疗法。","src":"《第14章 癌细胞》p87；p89"},{"id":"a7559619","s":"c","g":"c14","n":"循环肿瘤细胞","e":"circulating tumor cell (CTC)","d":"循环肿瘤细胞（circulating tumor cell，CTC）是进入血液循环的肿瘤细胞，可反映肿瘤块内细胞的分子特征。CTC在癌的转移扩散中起关键作用：癌细胞黏着性下降、获得浸润性，穿过血管壁进入血流，到达远处器官形成转移灶。分析血液样本中的CTC可作为癌症早期检测以及肿瘤进展和复发监测的重要工具。CTC技术还可用于评估肿瘤异质性和疾病进程：治疗中体内占支配地位的CTC不断变化，伴随耐药出现，耐药性CTC在治疗后逐渐增多。","src":"《第14章 癌细胞》p70；p14"},{"id":"07c95228","s":"c","g":"c14","n":"恶变质","e":"cachexia","d":"恶变质（cachexia，常译恶病质）是一种由癌症等严重消耗性疾病引发的复杂代谢综合征，以骨骼肌消耗（伴或不伴脂肪减少）为特征，表现为进行性体重下降、厌食、虚弱、贫血和水肿，严重者全身衰竭。其发生与进食不足、糖脂及蛋白质代谢异常、能量利用效能低以及机体炎症反应有关。癌性恶病质最为常见，胰腺癌、胃癌、食管癌患者尤为多见，一旦发生难以逆转，会降低生活质量、影响原发病治疗并缩短生存时间。","src":"网络补充：baike.qq.com《恶病质》；dayi.org.cn《恶病质》"},{"id":"51b44287","s":"c","g":"c14","n":"抑癌基因","e":"tumor suppressor gene","d":"抑癌基因（tumor suppressor gene）是编码抑制细胞生长、防止细胞癌变蛋白质的基因，属细胞增殖的负调控因子，可在检验点阻止细胞周期进程或促进凋亡。其突变性质是隐性的：只有两个拷贝都发生突变时细胞才会癌变；细胞若含一个正常抑癌基因和一个突变等位基因，一般是正常的。第二次突变可通过染色体错误分离或同源染色体间的重组使杂合体变为纯合体。功能丧失性突变使抑癌基因失活，从而促进细胞存活与增殖。","src":"《第14章 癌细胞》p28；MBoC 7e 印刷 p1179","x":1},{"id":"20321344","s":"c","g":"c14","n":"接触抑制","e":"contact inhibition","d":"接触抑制（contact inhibition）是正常细胞的重要特性。多数正常细胞在培养皿中长满单层后即停止增殖，增殖似乎依赖于与皿底的接触，并受与其他细胞接触的抑制，这一现象称为接触抑制。癌细胞通常无视这种限制而继续生长，在培养皿中形成不受抑制的转化细胞灶，同时贴壁性下降，失去分裂和运动的接触抑制。失去接触抑制是癌细胞最基本的特征之一，与其在不依赖外源生长信号的情况下持续增殖相适应。","src":"MBoC 7e 印刷 p1173；《第14章 癌细胞》p6"},{"id":"3e9650c7","s":"c","g":"c14","n":"接触抑制","e":"","d":"接触抑制是正常细胞单层生长时因细胞间相互接触而停止分裂和运动的特性。体外培养的正常细胞长满单层后便停止增殖，而癌细胞失去这一特性，表现为失去单层生长的特点，在培养时贴壁性下降，失去分裂和运动的接触抑制。癌细胞还能在没有促进生长的信号下、或在有抑制信号的条件下继续生长繁殖，并出现自分泌生长刺激。因此，失去接触抑制与生长分裂失控、脱分化、避免程序性死亡、血管生成等一起，被列为癌细胞的基本特点。","src":"《第14章 癌细胞》p6"},{"id":"3ba546a8","s":"c","g":"c14","n":"有氧糖酵解","e":"aerobic glycolysis","d":"有氧糖酵解（aerobic glycolysis）又称瓦伯格效应，是癌细胞典型的代谢改变：肿瘤细胞无论在低氧还是氧气充足的环境中，都倾向于通过一种低效的利用葡萄糖产生乳酸的糖酵解方式供给能量，从而促进增殖。癌细胞的基本特点包括生长分裂失去控制、失去接触抑制、自分泌生长刺激、脱分化、细胞间相互作用改变、染色体非整倍性改变、避免程序性死亡、血管生成以及代谢改变，有氧糖酵解即为代谢改变的核心内容。","src":"《第14章 癌细胞》p7；p10；网络补充：news.ustc.edu.cn《有氧糖酵解》"},{"id":"c2ada15d","s":"c","g":"c14","n":"杂合性丢失","e":"loss of heterozygosity","d":"杂合性丢失（loss of heterozygosity，LOH）指一对染色体中某一条上正常等位基因的丢失，使同源染色体上的缺陷等位基因得以在临床上显现。它可由错误的同源重组造成：修复时不以姐妹染色单体为模板，而使用来自另一亲本的同源染色体，把被修复DNA的序列改成另一同源染色体的序列。若所用的同源染色体带有有害突变，这次重组就破坏了“好”的拷贝，后果严重。LOH虽罕见，却是许多癌症形成的关键一步。","src":"MBoC 7e 印刷 p300；《第14章 癌细胞》p30"},{"id":"148488c5","s":"c","g":"c14","n":"杂合性丢失","e":"LOH (loss of heterozygosity)","d":"杂合性丢失（LOH，loss of heterozygosity）是抑癌基因失活的常见方式：突变的杂合体再失去或失活一个正常的拷贝，使一对等位基因都发生突变。造成突变纯合体的机制有两种：染色体结构缺陷导致染色体错误分离，或带有野生型与突变型的两条染色体之间发生重组。其结果是同源染色体上的缺陷等位基因得以在临床上显现。由于抑癌基因突变是隐性的，LOH往往是抑癌基因功能完全丧失、细胞开始癌变的关键第二步。","src":"《第14章 癌细胞》p30；p31"},{"id":"1b2bc5f6","s":"c","g":"c14","n":"病毒癌基因","e":"viral oncogene (v-onc)","d":"病毒癌基因（viral oncogene，v-onc）指反转录病毒基因组中带有的、可使受病毒感染的宿主细胞发生癌变的基因，大多数属于RNA肿瘤病毒基因组中的基因。与之相对，细胞癌基因（c-onc）由细胞原癌基因突变而来。研究发现，许多致癌病毒中的癌基因与正常细胞中的某些DNA序列高度同源，因而推测病毒癌基因起源于细胞的原癌基因，这就是RNA肿瘤病毒癌基因起源假说的依据。","src":"《第14章 癌细胞》p23；p24"},{"id":"685adfa6","s":"c","g":"c14","n":"癌","e":"carcinoma","d":"癌（carcinoma）是源于上皮细胞的恶性肿瘤，是癌症中最主要的类型。按来源与形态可进一步分为腺癌（源于腺上皮、呈腺样结构）和鳞癌（源于鳞状上皮）。与之并列的恶性类型还有肉瘤（源于中胚层的结缔组织或肌肉组织）、白血病（源于骨髓）和骨髓瘤（浆细胞恶变）。癌是最常见的恶性肿瘤，因为成体大多数细胞更新发生在上皮，分裂次数最多的细胞类型累积多个致癌突变的概率最高，且上皮组织最易受到理化损伤。","src":"《第14章 癌细胞》p3；MBoC 7e 印刷 p1165"},{"id":"a9cf432a","s":"c","g":"c14","n":"癌基因","e":"oncogene","d":"癌基因（oncogene）是产物能以显性方式起作用、促使细胞癌变的改变了的基因，通常是参与细胞生长或分裂调控的正常基因即原癌基因的突变形式。按来源可分为两类：细胞癌基因由细胞原癌基因突变而来；病毒癌基因存在于反转录病毒基因组中，可使受感染的宿主细胞癌变。原癌基因可因点突变而持续活化、或因基因扩增、过表达而变为癌基因；转基因小鼠研究证实，单个癌基因一般不足以把正常细胞变成癌细胞。","src":"MBoC 7e Glossary（PDF p1467）；印刷 p1191；《第14章 癌细胞》p23","x":1},{"id":"9eb619c6","s":"c","g":"c14","n":"癌症","e":"","d":"癌症是恶性肿瘤和血癌的统称。肿瘤分良性、恶性两类，恶性者按来源命名：癌源于上皮细胞，肉瘤源于中胚层的结缔组织或肌肉组织，白血病源于骨髓，骨髓瘤则是浆细胞恶变形成的一类特殊白细胞癌。癌症的发生是基因突变逐渐积累的结果，涉及一系列原癌基因与抑癌基因的致癌突变，至少需要5～6个，因而是一种典型的老年性疾病；若生殖细胞中已发生致癌突变，细胞癌变所需突变数的积累时间就会缩短，携带该突变的家族成员更易患癌症。","src":"《第14章 癌细胞》p3；p39"},{"id":"a91344ca","s":"c","g":"c14","n":"癌症免疫疗法","e":"cancer immunotherapy","d":"癌症免疫疗法是靶向免疫系统而非肿瘤本身的全新治疗方式，与传统的手术切除、化疗、放疗不同。它分为两类：干预疗法，如抗CTLA-4、抗PD-1、抗PD-L1抗体；细胞疗法，如CAR-T，以及淋巴因子激活的杀伤细胞（LAK）、细胞因子激活的杀伤细胞（CIK）和CIK与树突状细胞混合疗法。其原理是解除肿瘤对免疫的抑制、增强T细胞应答。该疗法对某些血液肿瘤极为有效，但也可能因免疫系统过度激活而产生严重副作用，肿瘤微环境的免疫抑制是其主要障碍。","src":"《第14章 癌细胞》p71；p87；MBoC 7e 印刷 p1210"},{"id":"77fe53a1","s":"c","g":"c14","n":"癌症进展","e":"progression of cancer","d":"癌症进展（progression of cancer）指癌症发展的渐进阶段，依次为增生、异生、原位肿瘤和恶性肿瘤。增生阶段细胞数目增多但形态基本正常；异生阶段细胞形态与组织结构出现异常；原位肿瘤阶段异常细胞仍局限于原发部位；恶性肿瘤阶段则发展为可浸润、转移的肿瘤。这一序列反映了致癌突变逐步积累、细胞恶性程度不断加深的过程，与癌症作为多击、多阶段疾病的观点一致，也为肿瘤的早期诊断提供了病理学依据。","src":"《第14章 癌细胞》p5"},{"id":"5859bea0","s":"c","g":"c14","n":"白血病","e":"leukemia","d":"白血病（leukemia）是源于骨髓的恶性肿瘤，属血癌，即白细胞的癌症，与癌、肉瘤同为恶性肿瘤的主要类型。按讲义对肿瘤的分类，恶性者包括源于上皮的癌、源于中胚层结缔组织或肌肉的肉瘤、源于骨髓的白血病，以及浆细胞恶变形成的骨髓瘤。白血病细胞可在体外形成克隆，但只有0.1%～1%的白血病细胞能够形成克隆，提示肿瘤细胞群体中存在功能差异，仅少数细胞具有致瘤性，这一观察成为肿瘤干细胞层级假说的重要依据。","src":"《第14章 癌细胞》p3；p56"},{"id":"e4533466","s":"c","g":"c14","n":"细胞癌基因","e":"cellular oncogene (c-onc)","d":"细胞癌基因（cellular oncogene，c-onc）是由细胞原癌基因突变而来的癌基因，与病毒癌基因（v-onc）相对。v-onc指反转录病毒基因组中带有的、可使受感染宿主细胞癌变的基因，大多数属于RNA肿瘤病毒基因组。许多致癌病毒中的癌基因与正常细胞中的某些DNA序列高度同源，据此推测病毒癌基因起源于细胞的原癌基因。c-onc在正常细胞中有对应序列，如EGFR、HER2等原癌基因过度活化即可变为癌基因。","src":"《第14章 癌细胞》p23；p25"},{"id":"722abdfc","s":"c","g":"c14","n":"肉瘤","e":"sarcoma","d":"肉瘤（sarcoma）是起源于中胚层、源于结缔组织或肌肉组织的恶性肿瘤。在肿瘤的命名体系中，良性肿瘤与恶性肿瘤各有对应名称：如腺瘤是呈腺样结构的良性上皮肿瘤，其对应的恶性类型为腺癌。恶性肿瘤按来源区分：癌源于上皮细胞且最为常见，肉瘤源于结缔组织或肌肉，白血病源于骨髓，骨髓瘤为浆细胞恶变，来源于神经系统的肿瘤则较少见。肉瘤即结缔组织的癌症，与上皮来源的癌在组织形态和生物学行为上均有差别。","src":"《第14章 癌细胞》p3；MBoC 7e Glossary（PDF p1474）；印刷 p1165"},{"id":"25e239ab","s":"c","g":"c14","n":"肿瘤干细胞","e":"tumor stem cell","d":"肿瘤干细胞是与一般肿瘤细胞相比具有高致瘤性的一群细胞。肿瘤组织并非由均一的肿瘤细胞构成，其中只有部分细胞具有致瘤性：仅0.1%～1%的白血病细胞能在体外形成克隆，肺癌、卵巢癌或成神经细胞瘤中仅1/5000～1/1000的细胞能在琼脂中形成克隆。据此提出的层级假说认为，只有少量肿瘤起始细胞能高频度启动肿瘤发生，特异性针对这类细胞治疗才能较好控制肿瘤，2001年Reya等正式提出肿瘤干细胞学说。","src":"《第14章 癌细胞》p56","x":1},{"id":"6e608b0d","s":"c","g":"c14","n":"肿瘤干细胞","e":"cancer stem cell (CSC)","d":"肿瘤干细胞（cancer stem cell，CSC）是存在于某些肿瘤组织中的一群干细胞样细胞。CSC通过某些机制不断分裂增殖，一方面自我更新，另一方面产生具有有限分裂和分化能力的肿瘤细胞，促进肿瘤形成。肿瘤起源于CSC，其具有自我更新、无限增殖及多向分化能力，对放化疗不敏感；在肿瘤中虽只占少数，却是肿瘤发生、发展与转移的主要细胞，是肿瘤复发的根源。在致癌因子诱导下，干细胞、周期中细胞和终末分化细胞都可能转化为肿瘤干细胞。","src":"《第14章 癌细胞》p58；p67"},{"id":"099b9cc2","s":"c","g":"c14","n":"肿瘤异质性","e":"tumor heterogeneity","d":"肿瘤异质性（tumor heterogeneity）可分为瘤间异质性和瘤内异质性。前者指不同个体或不同部位肿瘤之间的差异，后者指同一肿瘤内部细胞群体的差异。肿瘤细胞遗传稳定性较差，每个突变细胞都可能克隆扩增为亚群，在自然选择下形成优势克隆，因此肿瘤由遗传上不均一的细胞群体构成。肿瘤与其产生的转移灶之间的关系呈现典型的达尔文进化图景，时间尺度为数月至数年，受同样自然选择规律支配；研究肿瘤异质性可利用由成体干细胞在三维基质中培育成的类器官。","src":"MBoC 7e 印刷 p1192；《第14章 癌细胞》p70"},{"id":"c37dd4cf","s":"c","g":"c14","n":"肿瘤微环境","e":"tumor microenvironment","d":"肿瘤微环境（tumor microenvironment）是影响癌症发展的肿瘤细胞周围环境，包括基质细胞、分泌因子和细胞外基质。基质细胞有肌成纤维细胞、内皮细胞、间充质干细胞和浸润的免疫细胞等。肿瘤细胞会改造周围基质，营造既促进肿瘤生长又抑制免疫反应的微环境。肿瘤干细胞的自我更新和分化潜能使其能在新位置重建肿瘤微环境、形成新的肿瘤灶，并通过分泌因子与细胞外基质相互作用，重编程远处器官的微环境，使之更适合肿瘤细胞生长和存活。","src":"《第14章 癌细胞》p44；p64；MBoC 7e 印刷 p1210"},{"id":"be295823","s":"c","g":"c14","n":"肿瘤标志物","e":"tumor marker","d":"肿瘤标志物（tumor marker）是在恶性肿瘤的发生和增殖过程中，由肿瘤细胞基因表达而合成分泌，或由机体对肿瘤细胞反应而异常产生或升高的一类物质，可反映肿瘤的存在和生长，多存在于血液、尿液或组织中。按生化特性可分为酶类、胚胎抗原和蛋白类、激素类、糖蛋白类以及癌基因及其蛋白等。检测肿瘤标志物可用于高危人群筛查、辅助诊断、预后判断、疗效评价和复发监测，但特异性有限，通常需与影像学和病理学检查结合判断。","src":"网络补充：baike.qq.com《肿瘤标志物检测》；kepuchina.cn《肿瘤标志物》"},{"id":"5101a0e7","s":"c","g":"c14","n":"肿瘤诊断靶","e":"tumor biomarker","d":"肿瘤诊断靶即肿瘤生物标志物（tumor biomarker），是肿瘤诊断的重要环节。按讲义所列，肿瘤诊断包括影像技术、肿瘤诊断靶和癌的早期诊断三方面；其中癌的早期诊断依赖蛋白靶标检测、RNA水平的表达谱检测和遗传检测。作为诊断靶的分子应能反映肿瘤的存在、类型或进展，因而可用于早期发现与病程监测。循环肿瘤细胞分析即属此类思路：CTC反映肿瘤块内细胞的分子特征，可用于早期检测及进展、复发监测，并评估肿瘤异质性和疾病进程。","src":"《第14章 癌细胞》p69；p70"},{"id":"3a32e534","s":"c","g":"c14","n":"肿瘤转移","e":"tumor metastasis","d":"肿瘤转移（tumor metastasis）是恶性肿瘤细胞从原发部位扩散到体内其他部位的过程，是癌症危险性的关键因素。癌细胞黏着性下降，获得浸润性和扩散性，可经血液循环和淋巴系统扩散，在身体其他部位增殖形成次级肿瘤即转移灶。转移几乎必然要求破坏把细胞束缚于正常邻居和细胞外基质的黏附机制；侵入的癌细胞还需穿透血管或淋巴管壁进入循环，淋巴管较大、壁较薄，癌细胞可成小簇进入并滞留于淋巴结，形成淋巴结转移。","src":"《第14章 癌细胞》p13；p14；MBoC 7e 印刷 p1177","x":1},{"id":"badd5aa4","s":"c","g":"c14","n":"肿瘤转移","e":"metastasis","d":"转移（metastasis）指癌细胞从原发部位扩散到体内其他部位，是癌症危险性的关键因素。其过程包括：癌细胞黏着性下降、获得浸润性，破坏把细胞束缚于邻居和细胞外基质的黏附机制；随后穿透血管或淋巴管壁进入循环。淋巴管较大、壁较薄，癌细胞可成小簇进入，滞留于淋巴结而形成淋巴结转移；进入血管者多为单个细胞。最终癌细胞在远处器官定居、增殖，形成次级肿瘤即转移灶。整个过程涉及上皮-间充质转化（EMT）及其逆转（MET）以及浸润、血管内渗等步骤。","src":"《第14章 癌细胞》p14；MBoC 7e 印刷 p1177"},{"id":"eaa21fff","s":"c","g":"c14","n":"腺癌","e":"adenocarcinoma","d":"腺癌（adenocarcinoma）是源于腺上皮、呈腺样结构的恶性肿瘤。在肿瘤命名体系中，呈腺样结构的良性上皮肿瘤称为腺瘤，其对应的恶性类型即为腺癌。癌是源于上皮细胞的恶性肿瘤，为癌症中最主要的类型，另有鳞癌源于鳞状上皮。多数癌保留其来源细胞的某些特征，例如起源于皮肤角质细胞干细胞的基础细胞癌通常继续合成细胞角蛋白中间丝，而起源于色素细胞的黑色素瘤则常继续产生色素颗粒。","src":"《第14章 癌细胞》p3；MBoC 7e 印刷 p1165"},{"id":"2045268a","s":"c","g":"c14","n":"致癌物","e":"carcinogens","d":"致癌物（carcinogens）又称诱变剂（mutagen），是诱发肿瘤的环境因素，属肿瘤发生的外因。按性质分为三类：化学致癌，包括直接诱变剂、间接诱变剂和癌促进剂；物理致癌，如中子、γ射线和紫外线等辐射；生物致癌，即肿瘤病毒，包括DNA病毒和RNA病毒。多数强致癌物化学性质相对惰性，须经肝细胞色素P-450氧化酶代谢转化为反应性分子才具损伤作用，如煤焦油和烟草烟雾中的苯并芘、真菌毒素黄曲霉毒素B1。","src":"《第14章 癌细胞》p18；MBoC 7e 印刷 p1200"},{"id":"59b6c29c","s":"c","g":"c14","n":"良性肿瘤","e":"benign tumor","d":"良性肿瘤（benign tumor）是局限于原发组织、常保持正常形态和功能的肿瘤，与恶性肿瘤相对。良性者不浸润、不转移，仅在体积过大、激素分泌过多等情况下才造成病理危害。命名上与恶性肿瘤相对应，如呈腺样结构的良性上皮肿瘤称为腺瘤，其恶性对应类型为腺癌；源于上皮的恶性肿瘤称癌，源于结缔组织或肌肉的称肉瘤。在分化程度上，癌细胞低于正常细胞和良性肿瘤细胞，即发生脱分化，这也是良、恶性肿瘤之间的重要差别之一。","src":"《第14章 癌细胞》p4；p10；MBoC 7e 印刷 p1165"},{"id":"7fbddb9a","s":"c","g":"c14","n":"血管生成","e":"angiogenesis","d":"血管生成（angiogenesis）是从已有血管出芽长出新血管的过程。它是肿瘤生长必须的步骤，因为肿瘤生长需要营养和氧。按Folkman理论，无血管生成时实体肿瘤仅靠弥散获取氧气及营养物质，生长范围只能维持在1～2 mm³；超过2～3 mm³时，必须依靠血管生成提供足够的氧气和营养物质，才能维持肿瘤组织的快速生长。血管内皮生长因子（VEGF）与其受体结合可刺激血管生成，因而抗血管生成成为肿瘤靶向治疗的策略之一。","src":"《第14章 癌细胞》p12；p10；MBoC 7e Glossary（PDF p1445）"},{"id":"cc65a1f6","s":"c","g":"c14","n":"靶向治疗","e":"","d":"靶向治疗是2000年后开始在临床上使用的肿瘤治疗方式，介于传统治疗与免疫疗法之间。传统治疗包括手术切除、化疗和放疗，1940年后开始出现细胞毒性化疗药物；20世纪90年代开始研究、2000年后临床应用的靶向治疗，则针对特定的致癌蛋白或过程，如用小分子抑制剂抑制突变的EGFR，或阻止血管生成（VEGF、thrombospondin）。与主要杀伤快速分裂细胞的化疗不同，靶向药物针对肿瘤细胞特有的分子改变，选择性更高。","src":"《第14章 癌细胞》p71；p74"},{"id":"a48775d4","s":"c","g":"c14","n":"骨髓瘤","e":"myelomas","d":"骨髓瘤（myelomas）是一类特殊的白细胞癌，由浆细胞即成熟的B淋巴细胞发生恶变而形成，与白血病并列。在肿瘤分类中，源于骨髓的白血病与骨髓瘤同属血癌，而癌症正是恶性肿瘤和血癌的统称。骨髓瘤细胞在单克隆抗体制备中被广泛使用：将小鼠脾脏的B淋巴细胞与骨髓瘤细胞融合，可获杂交瘤，再经HAT培养基筛选，H为次黄嘌呤、A为氨基蝶呤、T为胸腺嘧啶，从而得到能持续分泌特定抗体的细胞系。","src":"《第14章 癌细胞》p3；《第2章 技术》p68"},{"id":"556b931e","s":"c","g":"c14","n":"鳞癌","e":"squamous cell carcinoma","d":"鳞癌（squamous cell carcinoma）是源于鳞状上皮的恶性肿瘤，与源于腺上皮的腺癌同属癌的常见类型。癌是源于上皮细胞的恶性肿瘤，为癌症中最主要的类型。上皮来源的肿瘤之所以最常见，是因为成体大多数细胞更新即增殖与死亡发生在上皮，分裂次数最多的细胞类型累积多个致癌突变的概率最高，且上皮组织最易受到促进癌症发生的物理和化学损伤。多数癌保留其来源细胞的特征，可据此判断其组织来源。","src":"《第14章 癌细胞》p3；MBoC 7e 印刷 p1165"},{"id":"09d2f4b3","s":"c","g":"c02","n":"ABC转运蛋白","e":"ABC transporter","d":"ABC转运蛋白（ABC transporter）是膜转运蛋白中的一个大家族，因每个成员在胞质侧含两个高度保守的ATP结合区而得名，可跨膜转运无机离子、氨基酸、单糖、多糖、小肽甚至蛋白质等种类繁多的分子。结合ATP使两个ATP结合区二聚化，水解ATP则使其解聚；这种胞内结构变化传递到跨膜区，使蛋白构象循环改变，把底物结合位点交替朝向膜内和膜外，从而实现跨膜运输。它是最大的膜转运蛋白家族，多药抗性蛋白即属此类。","src":"《第3章 细胞膜与表面（上）》p71；MBoC 7e 印刷 p649"},{"id":"13bf98e3","s":"c","g":"c02","n":"ATP合成酶","e":"ATP synthase","d":"ATP合成酶（ATP synthase）是线粒体内膜和叶绿体类囊体膜上大量存在的跨膜酶复合物，细菌质膜上也有，属F型泵。它由嵌入膜的F0基部、柄部和球形F1头部组成：F1由α3β3γδε五种多肽构成，具ATP合成的催化位点；F0由a、b2、c12三种多肽构成，12个c亚基围成环形结构，构成质子通道。它利用质子跨膜梯度驱动ADP与磷酸合成ATP，梯度来自氧化磷酸化或光合作用电子传递；嵴有助于其定位并提高合成效率。","src":"《第7章 细胞的能量代谢》p54；p60；《第3章 细胞膜与表面（上）》p70"},{"id":"8b12a77d","s":"c","g":"c09","n":"Akt","e":"Akt (PKB)","d":"在PI3K-Akt通路中，Akt即蛋白激酶B，是反转录病毒癌基因v-akt的编码产物，属丝氨酸/苏氨酸蛋白激酶。它除中间的激酶结构域外，N端还含一个PH结构域，能紧密结合质膜上PI-3-P的3位磷酸而锚定于质膜；PI3K被活化的受体酪氨酸激酶募集到质膜后催化生成PI-3,4,5-P3，为含PH结构域的蛋白提供锚定位点。Akt经PDK1（苏氨酸）和mTOR（丝氨酸）磷酸化后完全活化，进而活化凋亡抑制蛋白、抑制凋亡。","src":"《第9章 2021细胞通讯和信号转导》p82；《普通班作业汇总》p4"},{"id":"859be69b","s":"c","g":"c16","n":"Biacore","e":"Biacore","d":"Biacore是基于表面等离子共振（SPR）技术的生物分子相互作用分析系统，属研究蛋白质间相互作用的方法之一。其原理是把一种分子即配体偶联固定在传感芯片表面，再将含待测分子即分析物的溶液流经芯片；偏振光照射传感表面，反射光强度最低的角度即共振角随表面质量变化而改变，结合与解离过程被实时记录为传感曲线。该技术无需标记，可测定结合特异性、亲和力常数以及结合、解离动力学，广泛用于抗体表征与药物筛选。","src":"网络补充：cytivalifesciences.com.cn SPR；merc.ac.cn Biacore"},{"id":"e0a0b11b","s":"c","g":"c02","n":"CFTR","e":"CFTR","d":"CFTR即囊性纤维化跨膜传导调节蛋白（cystic fibrosis transmembrane conductance regulator）。该蛋白由编码CFTR的基因突变引起，因研究囊性纤维化而被发现。CFTR是上皮细胞质膜上的Cl⁻转运蛋白，可调节细胞外液尤其是肺内的离子浓度。与其他ABC转运蛋白不同，其ATP结合并非用于驱动跨膜主动运输。每27个白种人中就有1人携带突变基因，每2900人中便有1人两个拷贝均突变而患病。","src":"MBoC 7e 印刷 p651"},{"id":"5ea8896c","s":"c","g":"c02","n":"F型泵","e":"F-type pump","d":"F型泵（F-type pump）是由不同亚基组成、形状像涡轮机的蛋白，见于细菌质膜、线粒体内膜和叶绿体类囊体膜，通常也被称为ATP合成酶，利用质子跨膜梯度驱动ATP合成。质子梯度来源于细菌和线粒体中的氧化磷酸化，或植物叶绿体光合作用中的电子传递，也可由嗜盐菌中光驱动的质子泵形成。与它结构相似的V型ATP泵则相反，通常利用ATP水解的能量把质子泵进溶酶体、突触囊泡和植物液泡，酸化这些细胞器的内部环境。","src":"《第3章 细胞膜与表面（上）》p70","x":1},{"id":"93fc424e","s":"c","g":"c16","n":"GST","e":"GST","d":"谷胱甘肽S-转移酶（GST）是研究蛋白质相互作用时常用的一种亲和标签，其技术形式称为GST pull-down。用重组DNA技术把已知的诱饵蛋白与GST融合表达，融合蛋白借GST与固相化谷胱甘肽（GSH）珠的高亲和结合而被固定；再与细胞裂解液共孵育，凡与诱饵蛋白相互作用的蛋白即被捕获，洗涤去除非特异结合后经SDS-PAGE、Western blot或质谱鉴定。该法可在体外验证两蛋白的直接互作或筛选未知结合蛋白，但不能反映胞内真实状态。","src":"网络补充：baike.baidu.com／GST pull-down assay"},{"id":"e1e726da","s":"c","g":"c09","n":"G蛋白","e":"G protein","d":"三聚体G蛋白（heterotrimeric G protein）是质膜内侧由Gα、Gβ、Gγ三种亚基组成的GTP结合蛋白，Gα和Gβγ分别通过共价结合的脂分子锚定在质膜上。Gα具有GTPase活性，结合GTP时为活化态、结合GDP时为非活化态，起分子开关作用：GEF促使其释放GDP而开启，GAP加速GTP水解而关闭。活化的G蛋白偶联受体催化Gα换苷，活化的Gα或游离的Gβγ再调节腺苷酸环化酶、磷脂酶C或离子通道等，把信号转导入细胞。","src":"《第9章 2021细胞通讯和信号转导》p48；MBoC 7e 印刷 p907","x":1},{"id":"85672a63","s":"c","g":"c09","n":"G蛋白偶联受体","e":"GPCR","d":"G蛋白偶联受体（GPCR）是最大的细胞表面受体超家族，其共同特征是肽链七次跨膜形成特征性构象，并借助G蛋白把信号传入细胞内部。该超家族包括视紫红质、脊椎动物嗅觉受体以及酵母识别交配因子的受体，提示多细胞生物的GPCR可能由单细胞真核祖先的感觉受体演化而来。配体结合后受体活化G蛋白，进而激活或抑制腺苷酸环化酶、激活磷脂酶C产生IP3与DAG双信使，或直接开启离子通道；受体C端富含Ser/Thr，可被GRK磷酸化而脱敏。","src":"《第9章 2021细胞通讯和信号转导》p55、p63；MBoC 7e 印刷 p893"},{"id":"214dfbb3","s":"c","g":"c16","n":"HE染色","e":"HE staining","d":"HE染色（HE staining）即苏木精—伊红染色，是组织学、胚胎学与病理学中最基本、最常用的染色方法，由碱性染料苏木精与酸性染料伊红配合完成。细胞核内的染色质及胞质中富含RNA的核糖体等酸性物质与碱性染料亲和力强，被苏木精染成紫蓝色，这种特性称为嗜碱性；细胞质与细胞外基质中的蛋白质等成分与酸性染料亲和，被伊红染成粉红色，称为嗜酸性。借此可在光镜下清晰区分核与质、显示细胞与组织的微细结构，染色后经脱水、透明与封片即可长期保存观察。","src":"网络补充：zgbk.com／苏木精-伊红染色","x":1},{"id":"7939651e","s":"c","g":"c09","n":"MAPK通路","e":"MAPK pathway","d":"促分裂原活化蛋白激酶（MAPK）通路是真核细胞中高度保守的蛋白激酶级联，按MAPKKK→MAPKK→MAPK三级依次磷酸化。经典代表是Ras-Raf-MEK-ERK途径：生长因子结合受体酪氨酸激酶后，经Grb2与Sos使Ras转为GTP结合型而活化，活化Ras招募并激活Raf（MAPKKK），Raf磷酸化MEK（MAPKK），MEK再双位点磷酸化ERK；ERK既可作用于胞质底物，也可转入核内激活转录因子，从而调控增殖、分化与存活。","src":"网络补充：kepuchina.cn／ERK；yixue.com／MAPK通路"},{"id":"41005a33","s":"c","g":"c09","n":"PDK1","e":"PDK1","d":"磷脂酰肌醇依赖性蛋白激酶1（PDK1）是PI3K-PKB（Akt）通路中的关键激酶，其分子含有PH结构域，能通过与质膜上PI-3-P锚定位点结合而被招募到质膜。在存活信号作用下，PKB转位到质膜仅获得部分活化，还需PDK1使其活性位点上的关键苏氨酸残基磷酸化，并由PDK2（mTOR）使其丝氨酸磷酸化，PKB才完全活化；完全活化的PKB从质膜上解离，进入胞质基质和细胞核，磷酸化多种相应的靶蛋白，重新活化凋亡抑制蛋白，从而抑制细胞凋亡。","src":"《第9章 2021细胞通讯和信号转导》p84；MBoC 7e 印刷 p921"},{"id":"024b6b16","s":"c","g":"c09","n":"PH结构域","e":"PH domain","d":"普列克底物蛋白同源结构域（PH domain）是首先在血小板蛋白pleckstrin中鉴定的蛋白质相互作用模块，约200种人蛋白含有该结构域，其中包括Ras的鸟苷酸交换因子Sos。PH结构域主要作为蛋白—蛋白相互作用结构域发挥作用，只有一小部分能结合PI(3,4,5)P3；这些成员往往同时识别一种特定的膜结合蛋白与PIP3，从而大大提高结合的专一性。借此，PKB、PDK1等激酶可被募集到质膜的肌醇磷脂锚定位点而活化。","src":"《第9章 2021细胞通讯和信号转导》p30、p82；MBoC 7e 印刷 p921","x":1},{"id":"56bf4909","s":"c","g":"c09","n":"PI3K","e":"PI3K","d":"磷脂酰肌醇-3-激酶（PI3K）由p110催化亚基与含SH2结构域的p85调节亚基组成。p85的SH2结构域识别活化受体酪氨酸激酶及多种生长因子受体的磷酸酪氨酸残基，把酶募集到质膜，使催化亚基靠近膜内磷脂酰肌醇。PI3K既具磷脂酰肌醇激酶活性，可催化PI-4-P转为PI-3,4-P2、PI-4,5-P2转为PIP3，又具Ser/Thr激酶活性；生成的PI-3-P作为质膜锚定位点，募集并激活PKB、PDK1等信号蛋白与蛋白激酶。","src":"《第9章 2021细胞通讯和信号转导》p82、p84"},{"id":"9b22436f","s":"c","g":"c09","n":"PKA","e":"PKA","d":"cAMP依赖性蛋白激酶（PKA）是由cAMP激活的丝氨酸/苏氨酸蛋白激酶，为GPCR-cAMP通路的主要效应器。未受刺激时，锚定的磷酸二酯酶把局部cAMP维持在低水平，PKA处于无活性状态；信号使cAMP迅速升高、超过水解能力时PKA被激活。活化PKA可磷酸化糖原合酶与磷酸化酶激酶，从而抑制糖原合成、促进糖原分解；它还能进入核内磷酸化转录因子，介导对基因转录的激活。PKA磷酸化并激活邻近的磷酸二酯酶构成负反馈，使反应成为短暂局部脉冲。","src":"《第9章 2021细胞通讯和信号转导》p59、p61；MBoC 7e 印刷 p897"},{"id":"ec3b3d51","s":"c","g":"c09","n":"PKC","e":"PKC","d":"蛋白激酶C（PKC）是Ca2+依赖性的丝氨酸/苏氨酸蛋白激酶。IP3引起胞质Ca2+升高后，PKC由胞质转位到质膜的胞质面，在Ca2+、二酰甘油（DAG）与带负电的膜磷脂酰丝氨酸共同作用下被激活；活化的PKC磷酸化靶蛋白，底物因细胞类型而异。其底物广泛，既参与细胞分泌、肌肉收缩等短期生理效应，也参与细胞增殖、分化等长期生理效应，并可通过两条胞内途径激活基因转录。在线虫合子中，aPKC复合物在合子前端皮层的积聚对前后极的建立至关重要。","src":"《第9章 2021细胞通讯和信号转导》p70；《第11章 细胞分化与基因表达调控》p39；MBoC 7e 印刷 p899","x":1},{"id":"e998008d","s":"c","g":"c02","n":"P型泵","e":"P-type pump","d":"P型泵（P-type pump）是三类ATP驱动泵之一，因泵循环中发生自我磷酸化而得名。该家族包括许多负责建立和维持跨膜Na+、K+、H+和Ca2+梯度的离子泵；其代表钠钾泵又称钠钾ATP酶，利用ATP水解的能量逆电化学梯度将Na+运出细胞、将K+运进细胞。当离子浓度梯度增大到电化学梯度所含能量高于ATP水解释放的化学能时，钠钾泵可反向工作，借离子顺电化学梯度扩散的能量合成ATP，方向取决于ATP、ADP、磷酸根的浓度与离子电化学梯度。","src":"《第3章 细胞膜与表面（上）》p69；MBoC 7e 印刷 p646"},{"id":"6c158dca","s":"c","g":"c09","n":"SH2/SH3结构域","e":"SH2/SH3 domain","d":"SH2与SH3结构域（SH2/SH3 domain）是胞内信号蛋白中常见的保守模块。SH2识别活化受体酪氨酸激酶上被磷酸化的酪氨酸残基，使含SH2的蛋白被募集到质膜；SH3则结合胞内蛋白中富含脯氨酸的基序。故二者的结合多受磷酸化修饰调控，是受体活化后装配信号复合物的基础：接头蛋白Grb2即借SH2结合活化RTK的磷酸酪氨酸、借SH3与Sos结合，把受体与Ras的鸟苷酸交换因子连接。此外，多个SH3结构域间的弱相互作用还与蛋白质相变有关。","src":"《第9章 2021细胞通讯和信号转导》p76、p79","x":1},{"id":"7c7f2995","s":"c","g":"c12","n":"TOM/TIM/SAM/OXA复合体","e":"TOM/TIM/SAM/OXA complex","d":"线粒体蛋白转位酶复合体（TOM/TIM/SAM/OXA complex）介导线粒体蛋白质的跨膜转运与定位。多数线粒体蛋白由核基因编码、在胞质核糖体合成，须先经外膜转位酶TOM进入，为主要入口；带转运肽的前体随后交给内膜的TIM23复合体，在膜电位与PAM马达驱动下进入基质，转运肽由基质加工肽酶切除；多次跨膜载体蛋白经小TIM交给TIM22插入内膜；外膜β桶蛋白由SAM装配入外膜；线粒体自身基因组编码的疏水蛋白则由OXA从基质侧插入内膜。","src":"网络补充：pmc.ncbi.nlm.nih.gov／Role of membrane contact sites in protein import into mitochondria"},{"id":"aa2ef938","s":"c","g":"c16","n":"TUNEL检测","e":"TUNEL assay","d":"TUNEL检测（TUNEL assay）即末端脱氧核苷酸转移酶介导的dUTP缺口末端标记法，是原位检测凋亡细胞DNA断裂的常用方法。凋亡细胞激活内源性核酸内切酶，在核小体之间切断基因组DNA，产生大量3′-羟基末端；末端脱氧核苷酸转移酶（TdT）以这些断端为引物掺入带荧光素或生物素标记的dUTP，再用荧光显微镜或流式细胞仪检测，正常细胞几乎无DNA断裂故很少被标记。由于DNA片段化属凋亡较晚期的事件，该法灵敏度高、可原位显示单个凋亡核。","src":"网络补充：baike.baidu.com／TUNEL检测","x":1},{"id":"ff34aef5","s":"c","g":"c02","n":"V型泵","e":"V-type pump","d":"V型泵（V-type pump）是三类ATP驱动泵之一，由多种不同亚基构成的涡轮状蛋白机器。其功能是耗用ATP水解的能量把H+泵入细胞器，如溶酶体、突触囊泡以及植物和酵母的液泡（V即vacuolar），从而酸化这些细胞器的内部，为水解酶提供酸性环境并驱动依赖H+梯度的物质转运。与V型泵结构相关的是F型ATP酶，通常称为ATP合酶，它在生理条件下反向工作，即利用H+顺电化学梯度回流所释放的能量合成ATP，而不是水解ATP去泵H+。","src":"MBoC 7e 印刷 p646","x":1},{"id":"98f8d2a5","s":"c","g":"c16","n":"Western blotting","e":"Western blotting","d":"蛋白质印迹（Western blotting）又称免疫印迹，是检测特定蛋白质存在与含量的常用技术。其过程是先用SDS-聚丙烯酰胺凝胶电泳按分子质量分离蛋白质样品，再借强电流把凝胶中的蛋白质转移并固定在膜片上，然后用标记抗体溶液浸泡膜片，通过抗体与目标蛋白的特异结合显示相应条带。灵敏的方法可检测总细胞提取物或其他异质蛋白混合物中1纳克甚至更少的特定蛋白，因而适于评定细胞内某蛋白的量及其在不同条件下的变化，反映基因编码产物的表达情况。","src":"MBoC 7e 印刷 p490"},{"id":"293f0245","s":"c","g":"c09","n":"cAMP","e":"cAMP","d":"环腺苷酸（cAMP）是许多信号通路中最重要的第二信使之一。它由腺苷酸环化酶催化ATP生成，又被cAMP磷酸二酯酶迅速而持续地水解，因此胞外信号可在数秒内使cAMP浓度升高二十倍以上，这种快速升降依赖合成与降解两个方向的平衡。cAMP为水溶性，可在胞质中扩散，主要通过激活cAMP依赖性蛋白激酶（PKA）把信号传下去。磷酸二酯酶水解cAMP或cGMP，从而终结这些第二信使所传导的作用，使信号在时间上受到严格限制。","src":"《第9章 2021细胞通讯和信号转导》p39；MBoC 7e 印刷 p895"},{"id":"de9e80a0","s":"c","g":"c16","n":"knock in/out/down","e":"knock in/out/down","d":"敲入、敲除与敲减（knock in/out/down）是三类基因功能研究策略。敲除（knockout）通过同源重组或核酸酶造成的移码、缺失使目标基因永久失活，用于研究功能完全丧失后的表型；敲入（knock-in）在基因组特定位点插入外源序列，如突变序列或荧光标签，使基因在自身启动子下按生理水平表达，用于示踪蛋白或模拟突变；敲减（knockdown）多用RNA干扰降解靶mRNA，使表达部分降低而非完全消失，作用常为暂时、可逆。","src":"网络补充：ubigene.com／基因敲除细胞；ascentresearch.com／Types of Stable Cell Lines"},{"id":"cc74256b","s":"c","g":"c09","n":"mTOR","e":"mTOR","d":"雷帕霉素靶蛋白（mTOR）是PI3K相关的大分子蛋白激酶，因作为细菌毒素雷帕霉素的靶点而得名。哺乳动物细胞中的mTOR以两种功能不同的多蛋白复合体存在：mTORC1含raptor，对雷帕霉素敏感，是细胞生理的关键调节者，整合多种输入信号促进细胞生长；mTORC2含rictor，对雷帕霉素不敏感，通过激活Akt促进细胞存活，并经Rho家族GTP酶调节肌动蛋白骨架。在PKB活化中mTOR充当PDK2，其通路活化还可抑制自噬。","src":"《第9章 2021细胞通讯和信号转导》p84；MBoC 7e 印刷 p922"},{"id":"f7ed437b","s":"c","g":"c12","n":"mtDNA","e":"mtDNA","d":"线粒体DNA（mtDNA）位于线粒体基质中，与细胞核基因组相比更接近原核生物：一般呈环状，基因中基本无内含子，不同物种间差异较大——大多数高等动物线粒体基因组结构紧密，低等真核生物和高等植物则较大而松散。人线粒体基因组为16 569 bp，含37个基因，编码2种rRNA、22种tRNA和13种蛋白质，两条链各有一个转录启动子。由于线粒体与叶绿体基因组只编码少量蛋白，多数蛋白由核基因组编码，故二者被称为半自主性细胞器。","src":"《第7章细胞的能量代谢》p109；MBoC 7e 印刷 p863"},{"id":"c5b0e289","s":"c","g":"c11","n":"不对称分裂","e":"asymmetric division","d":"不对称分裂（asymmetric division）指一个母细胞分裂后产生两个命运不同子细胞的现象，其机制可以是细胞内在的，也可由胞外诱导信号在分裂后造成。内在机制的核心是命运决定子在胞质中分布不均，分裂时被不等地分配到两个子细胞；受精卵往往已具备内部图式，卵裂时把不同的命运决定子分隔到不同的卵裂球中，该机制在早期发育中十分普遍，也见于后期发育与干细胞。线虫合子前后极的形成即依赖aPKC复合物在合子前端皮层的积聚。","src":"《第11章 细胞分化与基因表达调控》p39；MBoC 7e 印刷 p1224"},{"id":"5e1c2253","s":"c","g":"c02","n":"主动运输","e":"active transport","d":"主动运输（active transport）指需要额外提供能量、逆电化学梯度把分子或离子跨膜转运的过程，由称作泵（pump）的转运蛋白完成，具有很强的方向性；与之相对，顺电化学梯度、不需另耗能量的运输称被动运输，其中需要膜蛋白帮助但不额外耗能者称协助扩散。按能量来源，细胞中有三种主动运输方式：协同转运、ATP驱动泵和光驱动泵。主动运输对代谢小分子的跨膜运输起关键作用，在一些特殊的哺乳动物细胞中，三分之二的代谢能量被消耗在跨膜运输过程上。","src":"《第3章 细胞膜与表面（上）》p59、p63；MBoC 7e 印刷 p642"},{"id":"629c1fa3","s":"c","g":"c11","n":"主导基因","e":"master gene","d":"主导基因（master gene）指在启动细胞分化的各类调节蛋白中，编码那一两种起决定作用的调控蛋白的基因。其特点是表达具有总开关的性质：有时仅主导基因的表达就有可能启动整个细胞的分化过程。经典实例来自果蝇——在发育早期把关键性调控眼发育的蛋白Ey转入将发育成腿的幼虫细胞中表达，结果诱导产生构成眼的不同类型细胞的有序三维组合，最终在腿的中部形成眼。这说明分化的方向可由少数主导基因的决定性表达所指定。","src":"《第11章 细胞分化与基因表达调控》p46"},{"id":"a3fe8be5","s":"c","g":"c09","n":"乙酰胆碱","e":"acetylcholine","d":"乙酰胆碱（acetylcholine）是重要的胞外信号分子与神经递质，同一分子对不同细胞可产生不同效应：在心脏可减弱心肌搏动，在骨骼肌可刺激收缩，在唾液腺可促进分泌，原因在于靶细胞表达不同的受体。在心肌细胞上，乙酰胆碱结合M型受体后激活Gi蛋白，其Gβγ直接开启K+通道，K+外流导致超极化，从而减缓收缩频率；在神经肌肉接头，它作用于递质门控的阳离子通道，引起去极化并触发肌肉收缩；作用于内皮细胞时则可经一氧化氮途径引起平滑肌舒张。","src":"《第9章 2021细胞通讯和信号转导》p38、p56；MBoC 7e 印刷 p671"},{"id":"f4e5cc99","s":"c","g":"c09","n":"二酰甘油","e":"DAG","d":"二酰甘油（DAG）是磷脂酶C水解4,5-二磷酸磷脂酰肌醇后生成的脂溶性第二信使，与可溶性的IP3构成双信使系统。与IP3不同，DAG不离开质膜，而是留在脂双层中扩散并发挥作用，其重要功能之一是激活蛋白激酶C：IP3引起的胞质Ca2+升高使PKC转位到质膜胞质面，在那里由Ca2+、DAG与带负电的磷脂酰丝氨酸共同激活，进而磷酸化靶蛋白的丝氨酸和苏氨酸残基。作为第二信使，DAG在细胞膜上生成、受第一信使调节，仅在细胞内部起作用。","src":"《第9章 2021细胞通讯和信号转导》p17、p63、p65；MBoC 7e 印刷 p899","x":1},{"id":"36322c1d","s":"c","g":"c12","n":"假循环电子传递链","e":"pseudocyclic electron transport chain","d":"假循环电子传递链（pseudocyclic electron transport chain）是光合电子传递的变通方式，介于非循环与循环之间：光系统Ⅱ与光系统Ⅰ都参与，水裂解而释放氧，但电子并不最终交给NADP+，而以氧为最终电子受体，形成既释放氧又消耗氧的局面，并伴随过氧化氢的生成。电子在末端短路回到氧，故不积累NADPH，但仍可借电子传递建立的质子梯度合成ATP，因而常被看作NADP+不足或需调整ATP与NADPH比例时的补充方式。","src":"《第7章细胞的能量代谢》p86、p93"},{"id":"ed1f55ea","s":"c","g":"c12","n":"光合单位","e":"photosynthetic unit","d":"光合单位（photosynthetic unit）是叶绿体类囊体膜上执行光能吸收与转换的基本功能单元，由捕光色素、原初电子供体D和原初电子受体A组成。天线复合物含大量叶绿素分子及类胡萝卜素，后者可吸收与叶绿素不同波长的光以提高效率，并防止光合膜中产生有害的氧自由基；天线色素吸收的光能以共振能量转移方式逐级传递，最终汇集到反应中心的特殊对叶绿素，使其激发后由D交出电子给A，完成电荷分离。每一光系统即由一个反应中心连同其天线复合物构成。","src":"《第7章细胞的能量代谢》p77；MBoC 7e 印刷 p852"},{"id":"c309f02d","s":"c","g":"c12","n":"光合磷酸化","e":"photophosphorylation","d":"光合磷酸化（photophosphorylation）是叶绿体中由电子传递偶联的ATP生成过程。光合作用合成有机物需要大量ATP与还原力NADPH，二者由类囊体膜上的电子传递链与光合磷酸化产生。按电子路径可分为三类：非循环型由光系统Ⅱ和光系统Ⅰ串联完成，电子呈线型传递，产物包括NADPH并释放O2；循环光合磷酸化只有光系统Ⅰ参与，经质体醌、细胞色素b6-f、质体蓝素与铁氧还蛋白回流，不产生NADPH和O2；假循环型则以氧为最终电子受体。","src":"《第7章细胞的能量代谢》p86、p93","x":1},{"id":"09d56aee","s":"c","g":"c12","n":"光系统","e":"photosystem","d":"光系统（photosystem）是类囊体膜上由吸光叶绿素与多种蛋白组成的多蛋白复合体，负责捕获日光能并转换为可利用的能量形式，由反应中心与天线两部分构成。天线色素含数百个叶绿素分子，另有捕光复合物作为辅助天线，含类胡萝卜素，可吸收叶绿素不能吸收的波长并防止氧自由基生成；天线捕获的激发能以共振能量转移方式传给反应中心的特殊对色素。反应中心是位于光合作用心脏处的跨膜蛋白与有机色素复合体，类囊体膜上有光系统Ⅰ与光系统Ⅱ两套，二者串联工作。","src":"《第7章细胞的能量代谢》p77、p90；MBoC 7e 印刷 p852"},{"id":"acfcc188","s":"c","g":"c11","n":"全能性","e":"totipotency","d":"全能性（totipotency）指细胞经分裂和分化后，在一定条件下仍具有发育成一个完整个体的潜能，是干细胞按分化能力分级（全能、亚全能、多能、单能）中的最高等级。全能性说明分化细胞仍保留个体的全部遗传信息，可由植物组织培养、动物克隆和干细胞研究予以证明；高度特化的动物细胞的全能性虽受限，但其核含保持物种遗传性所需的全套基因组DNA，以卵细胞为受体经核移植重编程后可发育成完整个体。四倍体囊胚注射是验证细胞是否具有全能性的黄金标准。","src":"《第11章 细胞分化与基因表达调控》p9、p13、p67","x":1},{"id":"bbcdcd0e","s":"c","g":"c12","n":"内共生假说","e":"endosymbiotic hypothesis","d":"内共生假说（endosymbiotic hypothesis）是解释线粒体与叶绿体起源的学说，认为它们由被原始真核细胞吞噬的细菌和蓝藻共生演化而来。支持证据包括：二者都是半自主性细胞器，蛋白质由两套遗传系统编码，多数由核基因组编码而少数由自身基因组编码；其基因组与原核生物接近，一般呈环状、基因中基本无内含子；高等植物叶绿体基因组约含120个基因、120 000个核苷酸对，与光合细菌的基因惊人相似；电镜观察表明叶绿体也以二分裂方式增殖。","src":"《第7章细胞的能量代谢》p109、p129、p132"},{"id":"2084bb58","s":"c","g":"c11","n":"内细胞群","e":"inner cell mass","d":"内细胞群（inner cell mass）是囊胚期胚泡腔内一侧聚集的一群形态不规则的细胞。它具备分化成内胚层、中胚层、外胚层三个胚层所有细胞类型的能力，但已失去发育成完整个体的能力，故其细胞属亚全能（多潜能）干细胞。用显微操作技术分离内细胞群可制备胚胎干细胞；分离所得的胚胎干细胞在适宜培养条件下可继续无限增殖，同时保持不受限制的发育潜能，其唯一限制是不能产生胎盘等胚外组织，因此被归为多潜能而非全能。","src":"《第11章 细胞分化与基因表达调控》p22；MBoC 7e 印刷 p1302"},{"id":"9e3ec568","s":"c","g":"c11","n":"再分化","e":"redifferentiation","d":"再分化（redifferentiation）指脱分化后失去原有结构与功能的细胞在适宜条件下重新分化、形成特定类型细胞或器官的过程，是细胞可塑性的一种表现形式。它常与去分化相提并论：去分化是分化细胞失去特有结构、变成未分化细胞的过程，再分化则是其后的重新分化阶段，二者连同直接转分化共同构成转分化现象的基础。在植物组织培养中，离体细胞先脱分化形成愈伤组织，愈伤组织再分化出芽和根等器官，最终形成完整植株，是细胞全能性发挥作用的结果。","src":"网络补充：kepuchina.cn／愈伤；zh.wikibooks.org／细胞生物学/细胞分化的基本概念","x":1},{"id":"aa21fd7c","s":"c","g":"c09","n":"分子开关","e":"molecular switch","d":"分子开关（molecular switch）指通过活化（开启）与失活（关闭）两种状态间的转换来控制下游靶蛋白的调控蛋白。细胞中主要有三类：G蛋白超家族开关，结合GTP为开、结合GDP为关，具内源GTPase活性可自行关闭；蛋白激酶与蛋白磷酸酶开关，借磷酸化与去磷酸化改变靶蛋白的构象与活性；钙调蛋白（CaM）与Ca2+结合或解离的开关。以Ras为例，GEF使其活化开启、GAP使其失活关闭，在信号由受体传向细胞核中起关键作用。","src":"《第9章 2021细胞通讯和信号转导》p18、p77；MBoC 7e 印刷 p880"},{"id":"af582142","s":"c","g":"c02","n":"动作电位","e":"action potential","d":"动作电位（action potential）是神经元、肌细胞等可兴奋细胞质膜上快速、短暂且能自我传播的电兴奋，是神经系统长距离信号传导的基础。其产生依赖电压门控离子通道的顺序开闭：轻微去极化使电压门控Na+通道开放，Na+内流引起突然而短暂的进一步去极化；随后延迟开放的K+通道在下降相开放，K+迅速外流，使膜电位在一两毫秒内恢复，即复极化。Na+通道从失活中恢复所需的时间称不应期，它限制神经元的重复发放频率并保证动作电位单向传导。","src":"《第3章 细胞膜与表面（上）》p83、p84；MBoC 7e 印刷 p664"},{"id":"5bd0643e","s":"c","g":"c12","n":"化学渗透假说","e":"chemical osmotic hypothesis","d":"化学渗透假说（chemical osmotic hypothesis）是解释氧化磷酸化偶联机制的学说。电子传递链各组分在线粒体内膜中不对称分布，高能电子沿链传递时释放的能量把H+从基质泵到膜间隙，形成跨内膜的H+电化学梯度即质子动力势；在该梯度驱使下，H+经ATP合成酶回到基质并合成ATP，梯度中的能量被储存到ATP的高能磷酸键。支持该假说的实验表明，质子动力势是ATP合成的动力，膜须保持完整性，电子传递与ATP合成是相关而不同的事件。","src":"《第7章细胞的能量代谢》p49、p51","x":1},{"id":"49af8355","s":"c","g":"c02","n":"协同转运","e":"cotransport","d":"协同转运（cotransport）是三种主动运输方式之一，其能量不直接来自ATP，而来自另一种溶质（通常是无机离子）顺电化学梯度移动时释放的自由能，借此把目标溶质逆其电化学梯度上坡转运。小肠上皮细胞是典型实例：肠腔和血液中Na+浓度都高于上皮细胞内，顶侧的Na+浓度梯度驱动的同向运输蛋白把营养物质主动输入细胞，建立营养物质跨膜浓度梯度，随后这些物质在基底侧顺浓度梯度被动离开细胞进入血液。细菌乳糖通透酶也借质子电化学梯度输入乳糖。","src":"《第3章 细胞膜与表面（上）》p63、p65；MBoC 7e 印刷 p642"},{"id":"c6cfe741","s":"c","g":"c11","n":"单能性","e":"unipotency","d":"单能性（unipotency）是干细胞按分化潜能分级中最低的一级，指细胞只能向一种（或一两种密切相关的）细胞类型分化，但仍保留自我更新能力，这一点使它与终末分化的细胞相区别，如上皮组织基底层的干细胞、肌肉中的成肌细胞。个体发育中细胞的分化潜能由全能逐渐变为多能、再趋于单能，是细胞分化的一般规律，干细胞也随之过渡为定向干细胞与前体细胞。需要指出的是，真正单能干细胞的判定仍有争议，部分曾被称作单能的细胞实为已定向的祖细胞。","src":"网络补充：wiki.owo.si／Cell potency；dayi.org.cn／什么是干细胞","x":1},{"id":"de8b7220","s":"c","g":"c02","n":"反向转运","e":"antiport","d":"反向转运（antiport）是偶联转运的一种形式，由反向转运蛋白（交换器）介导，使两种溶质以相反方向跨膜移动：一种溶质顺其电化学梯度进入细胞，同时驱动另一种溶质逆其电化学梯度排出。两种溶质转运的紧密偶联，使转运蛋白得以利用一种溶质（通常是无机离子）电化学梯度中储存的能量，为另一种溶质的上坡转运供能，这种策略在两个方向上都能起作用。与同向转运（symport）相对，二者同属偶联转运，区别于只转运单一溶质的单转运。","src":"MBoC 7e 印刷 p642","x":1},{"id":"42c59778","s":"c","g":"c09","n":"受体酪氨酸激酶","e":"RTK","d":"受体酪氨酸激酶（RTK）是最大的一类酶联受体，胞内段具酪氨酸激酶活性域。配体结合胞外部分后，受体二聚化并交叉磷酸化即自磷酸化，磷酸化的酪氨酸残基成为含SH2蛋白的停靠位点；SH3结构域则结合富含脯氨酸的基序。活化的RTK可经Grb2-Sos激活Ras-MAPK级联，或被含SH2的PI3K识别而启动PI3K/Akt通路。家族成员有EGF、胰岛素、PDGF、FGF、VEGF受体等，其信号受c-Cbl介导的内吞下调，下调失效会延长信号促癌。","src":"《第9章 2021细胞通讯和信号转导》p73、p76、p79；MBoC 7e 印刷 p915","x":1},{"id":"3d51aa6d","s":"c","g":"c12","n":"叶绿体","e":"chloroplast","d":"叶绿体（chloroplast）是绿色藻类与植物细胞中进行光合作用的膜性细胞器，多呈双凸或平凸透镜状，由叶绿体被膜、类囊体和基质三部分组成，含外膜、内膜、类囊体膜三种膜以及膜间隙、基质、类囊体腔三个腔。类囊体膜上分布光系统Ⅰ、光系统Ⅱ、细胞色素b6-f复合物与ATP合酶，是光能转换的场所；基质中含固定CO2的酶系。叶绿体是半自主性细胞器，多数蛋白由核基因组编码、少数由自身基因组编码，其基因与光合细菌的基因惊人相似，并以二分裂方式增殖。","src":"《第7章细胞的能量代谢》p106、p129、p132"},{"id":"c38bfa59","s":"c","g":"c02","n":"同向转运","e":"symport","d":"同向转运（symport）是偶联转运的一种形式，由同向运输蛋白介导，使两种溶质沿同一方向一起跨膜。其能量来自其中一种溶质（通常为无机离子或H+）顺电化学梯度移动所释放的自由能，用来驱动另一种溶质逆其电化学梯度转运。小肠上皮细胞顶侧Na+浓度梯度驱动的同向运输蛋白把营养物质主动输入细胞即属此类；细菌乳糖通透酶利用质子电化学梯度输入乳糖也是同向转运。与反向转运（antiport）相对，二者同属偶联转运，区别于只转运单一溶质的单转运。","src":"MBoC 7e 印刷 p642","x":1},{"id":"3d70a9c0","s":"c","g":"c12","n":"呼吸链","e":"respiratory chain","d":"呼吸链（respiratory chain）即电子传递链，位于线粒体内膜（嵴膜）上，由黄素蛋白、泛醌、铁硫蛋白、细胞色素和铜离子等电子载体组成的复合物体系。代谢物脱下的电子沿呼吸链逐级传递，氧化还原电位逐渐升高、自由能逐步降低，释放的能量用于把H+从基质泵到膜间隙，形成跨内膜的电化学质子梯度；该梯度再驱动ATP合酶合成ATP。因此呼吸链是氧化磷酸化的核心装置，在嵴膜上各复合物还可组装成超复合体；细菌质膜上有与之相似的呼吸链。","src":"《第7章细胞的能量代谢》p25、p44；MBoC 7e 印刷 p842"},{"id":"411ec811","s":"c","g":"c02","n":"外周膜蛋白","e":"peripheral protein","d":"外周膜蛋白（peripheral protein）是膜蛋白的一类，为水溶性蛋白，靠静电相互作用与氢键附着在脂双层表面，或结合于膜表面蛋白与磷脂极性头部，并不嵌入疏水核心、也不跨越脂双层。因其结合力弱，可用高盐（大于0.15 mol/L）、低盐或非生理pH（如pH 3至5或pH 8至12）的溶液破坏静电作用而把它洗脱，且不破坏膜结构、不需去垢剂；整合膜蛋白则须用去垢剂破坏膜结构才能提取。外周膜蛋白多参与信号转导与维持细胞形状。","src":"网络补充：smkx.hunnu.edu.cn／2DE-MS 中膜蛋白质组的研究进展；pearson.com／Peripheral Membrane Proteins","x":1},{"id":"92fc6dff","s":"c","g":"c11","n":"多潜能干细胞","e":"pluripotent stem cell","d":"多潜能干细胞（pluripotent stem cell）又称亚全能干细胞，指能分化成内、中、外三个胚层所有细胞类型、但已失去发育成完整个体能力的干细胞，胚胎干细胞即其代表，来自囊胚内细胞群。分离内细胞群并在体外培养可建立胚胎干细胞系；将Oct4、Sox2、c-Myc和Klf4四种转录因子导入小鼠成纤维细胞，可获得诱导多能干细胞，其在形态、基因与蛋白表达、表观遗传修饰状态及分化能力等方面均与胚胎干细胞相似。","src":"《第11章 细胞分化与基因表达调控》p22、p65"},{"id":"e7b79359","s":"c","g":"c11","n":"干细胞","e":"stem cell","d":"干细胞（stem cell）是未分化细胞，能持续不断地分裂，产生的子细胞或定向分化、或仍保持为干细胞而实现自我更新。按分化潜能可分为全能、亚全能（多能）、多能与单能干细胞；按个体发育中出现的先后可分为胚胎干细胞与成体干细胞。细胞分化可视为全能性逐渐丧失的过程：受精卵、胚胎干细胞、组织特异干细胞直至终末分化细胞。造血干细胞、神经干细胞、肠干细胞与间充质干细胞属多能干细胞，可分化为不同类型的细胞，但不能分化出足以构成完整个体的所有细胞。","src":"《第11章 细胞分化与基因表达调控》p23、p32；MBoC 7e 印刷 p1279","x":1},{"id":"21574378","s":"c","g":"c12","n":"底物水平磷酸化","e":"substrate-level phosphorylation","d":"底物水平磷酸化（substrate-level phosphorylation）是生物氧化生成ATP的三种方式之一，指底物的高能磷酸基团直接转移给ADP而生成ATP，不经电子传递链，也不依赖跨膜质子梯度。如醛氧化为羧酸时释放的能量大部分保存在ATP和NADH中。在细胞呼吸中，糖酵解在细胞质内经此方式产生4个ATP（己糖活化消耗2个），三羧酸循环在线粒体中经此产生2个ATP；它与氧化磷酸化、光合磷酸化在场所、条件与电子传递链上不同。","src":"《第7章细胞的能量代谢》p64；MBoC 7e 印刷 p82","x":1},{"id":"cad254fe","s":"c","g":"c12","n":"循环电子传递链","e":"cyclic electron transport chain","d":"循环电子传递链（cyclic electron transport chain）是仅由光系统Ⅰ参与的电子传递途径。光系统Ⅰ受光激发放出的电子经铁氧还蛋白、细胞色素b6-f、质体蓝素与质体醌等载体传递后又回到光系统Ⅰ，形成闭合回路，故不产生NADPH，也不释放O2；电子在回流过程中仍伴随H+的跨膜转移，建立质子梯度驱动ATP合成，即循环光合磷酸化。该途径有助于调节ATP与NADPH的供应平衡，在NADP+不足或需额外供ATP时尤为重要。","src":"《第7章细胞的能量代谢》p86、p93"},{"id":"585e51c8","s":"c","g":"c01","n":"支原体","e":"mycoplasma","d":"支原体（Mycoplasma）是一类有细胞结构的小型原核生物，作为寄生虫生活在哺乳动物体内，但它仍须自行合成DNA、RNA和蛋白质；生殖支原体的基因组仅有525个基因、580 070个核苷酸对，为已知最小的基因组之一。蕈状支原体是合成生物学的标志性材料：研究者先解码其完整DNA，再让酵母把购买的片段缝成合成拷贝并转入受体细胞，带人工DNA的细胞得以繁殖。2010年《科学》报道了世界首例人造单细胞生命体，该细胞可自我复制与分裂。","src":"《第1章 细胞与细胞生物学》p61、p62；MBoC 7e 印刷 p10","x":1},{"id":"3814edb8","s":"c","g":"c02","n":"易化扩散","e":"facilitated diffusion","d":"易化扩散（facilitated diffusion）也称协助扩散，是被动运输的一种：分子或离子顺电化学梯度跨膜，需要膜转运蛋白帮助，但不额外消耗能量。与简单扩散不同，它经有限数量的单转运蛋白进行，因而是特异的，速率远高于简单扩散；其动力学表现为随浓度差增大而趋近最大值Vmax，而简单扩散与通道介导的转运速率则与被转运分子的浓度差成正比。介导易化扩散的载体蛋白通过构象改变，在膜两侧交替开放结合位点，实现溶质的净转运。","src":"《第3章 细胞膜与表面（上）》p59、p62；MBoC 7e 印刷 p641"},{"id":"4142bf58","s":"c","g":"c09","n":"核受体","e":"nuclear receptor","d":"核受体（nuclear receptor）是位于胞质溶胶或核内、属配体活化转录因子的一类受体，其配体为脂溶性化学信号，如类固醇激素、甲状腺素、前列腺素、维生素A及其衍生物、维生素D及其衍生物等。配体结合后受体由胞浆转入细胞核，与DNA结合而发挥转录因子功能，故这类信号可经核受体直接调控基因转录。其活性受辅调节因子控制：共激活因子经组蛋白乙酰化松解染色质并解除共抑制因子的作用；辅抑制因子则招募复合物使核心组蛋白去乙酰化而抑制转录。","src":"《第9章 2021细胞通讯和信号转导》p92、p95；MBoC 7e 印刷 p936"},{"id":"a03d532c","s":"c","g":"c12","n":"氧化磷酸化","e":"oxidative phosphorylation","d":"氧化磷酸化（oxidative phosphorylation）是需氧生物与线粒体中最主要的ATP生成方式：底物氧化释放的电子沿电子传递链传给分子氧，过程中释放的能量用于把H+泵出，形成跨膜电化学质子梯度，再经化学渗透偶联驱动ATP合酶合成ATP，该过程在线粒体内膜即嵴上进行。与底物水平磷酸化、光合磷酸化在场所、条件与是否依赖电子传递链上均不同；肿瘤细胞即使在有氧时也常只把部分葡萄糖彻底氧化，而转向效率较低但可支持合成代谢的糖酵解。","src":"《第7章细胞的能量代谢》p3、p28；MBoC 7e 印刷 p1175","x":1},{"id":"8a904c70","s":"c","g":"c12","n":"氧化还原电位","e":"redox potential","d":"氧化还原电位（redox potential）指一个氧化还原对获得电子的亲和力，通常用该对等摩尔混合物与标准参照电极之间的电压差来量度。电位越高氧化性越强，电位越低氧化性越弱：NADH/NAD+的氧化还原电位低，O2/H2O的电位高。沿线粒体内膜的电子传递链，各组分的氧化还原电位逐渐升高、自由能逐步降低，电子因此能自发逐级传递并释放能量；由标准电位差可算出电子转移的标准自由能变化。氧化还原电位并不等同于电子本身所含的自由能。","src":"《第7章细胞的能量代谢》p29；MBoC 7e 印刷 p825","x":1},{"id":"f66db7e1","s":"c","g":"c02","n":"水通道蛋白","e":"aquaporin","d":"水通道蛋白（aquaporin）是镶嵌于质膜的通道蛋白，能极大提高细胞对水的通透性，使水以很高速度跨膜运输，同时完全阻挡离子通过。它要解决的问题与离子通道正好相反：既不能扰乱跨膜离子梯度，又要让水快速通过。其三维结构显示孔道狭窄，水分子只能排成单列依次穿过，一侧由排列成行的羰基氧引导，另一侧衬以疏水氨基酸；孔道窄到任何水合离子都无法进入，而去水合所需的能量代价极大，故离子被排除在外。","src":"MBoC 7e 印刷 p653"},{"id":"d4780f25","s":"c","g":"c02","n":"流动镶嵌模型","e":"fluid mosaic model","d":"流动镶嵌模型（fluid mosaic model）是1972年Singer和Nicolson提出的生物膜结构模型，其要点是：膜上脂质分子排成双层，构成生物膜的骨架；蛋白质分子以不同方式镶嵌或联结于脂双层上；膜的两侧结构不对称；膜脂和膜蛋白具有一定的流动性。该模型是在此前多达约50种膜结构假说的基础上提出的。后来的脂筏模型认为膜上一些特殊脂质可形成约70纳米、稍厚的动态微区，带着大量膜蛋白集中完成复杂功能，被视为对流动镶嵌模型的补充。","src":"《第3章 细胞膜与表面（上）》p30、p31","x":1},{"id":"4933aea0","s":"c","g":"c16","n":"流式细胞术","e":"flow cytometry","d":"流式细胞术（flow cytometry）是把稀释的细胞悬液排成单列、逐个流过照明光束，并测量每个细胞荧光信号的细胞分析技术。由于逐细胞检测，它可给出反映群体中各细胞某过程差异的直方图，直方图越宽表示变异越大；也可用于分析细胞DNA含量，区分未复制（1C）、已复制（2C）与正在复制（S期）的细胞群体，因而常用来检测细胞周期同步化程度。若把含单个细胞的液滴按所带荧光充电，再经高压偏转板偏转，即可实现细胞的分类分选。","src":"《第2章 技术》p62；MBoC 7e 印刷 p557","x":1},{"id":"125d41f0","s":"c","g":"c09","n":"百日咳毒素","e":"pertussis toxin","d":"百日咳毒素（pertussis toxin）是细菌产生的A-B型毒素：B亚基与宿主细胞的毒素受体结合，A亚基进入胞质发挥酶活性，借此扰乱宿主细胞过程。它催化Gi蛋白α亚基的ADP-核糖基化，结果阻止与Giα亚基结合的GDP释放，使Giα亚基被锁定在非活化状态，从而阻断了其对腺苷酸环化酶的抑制作用，导致气管上皮细胞内cAMP水平升高，促使液体、电解质和黏液分泌减少。作为研究工具，它常被用来判断某一效应是否由Gi蛋白介导。","src":"《第9章 2021细胞通讯和信号转导》p54；MBoC 7e 印刷 p1319"},{"id":"698e5487","s":"c","g":"c02","n":"磷脂","e":"phospholipid","d":"磷脂（phospholipid）是构成生物膜的主要脂类，也是膜上含量最丰富的脂质。其分子含亲水的极性头部与疏水的碳氢尾部，属双亲性分子，在水中可自发形成双分子层；疏水尾部通常为两条含14至24个碳原子的碳氢链，一般一条饱和、另一条含多个顺式双键，每个顺式双键使链产生弯折，链长与饱和程度影响分子的堆积方式，进而影响膜的流动性。磷脂可分为甘油磷脂与鞘磷脂两类，哺乳动物膜中卵磷脂与鞘磷脂合计约占整个膜脂的50%。","src":"《第3章 细胞膜与表面（上）》p10、p44；MBoC 7e 印刷 p605"},{"id":"07152d2b","s":"c","g":"c09","n":"磷脂酶C","e":"PLC","d":"磷脂酶C（PLC）是G蛋白偶联受体通路中的关键效应酶。配体结合受体后经Gq蛋白激活磷脂酶C-β（在RTK通路中则由PLC-γ），活化的酶水解质膜上的4,5-二磷酸磷脂酰肌醇，生成两个产物：可溶性的1,4,5-三磷酸肌醇（IP3）与膜内的二酰甘油（DAG），信号由此分为两支。IP3与内质网膜上的IP3受体结合，开启Ca2+通道使胞质Ca2+升高；DAG则激活PKC。精卵融合时，精子带入的PLC水解该底物产生IP3，启动胞质Ca2+波。","src":"《第9章 2021细胞通讯和信号转导》p63、p66；MBoC 7e 印刷 p898"},{"id":"f5b75eab","s":"c","g":"c09","n":"离子通道偶联受体","e":"ion channel-linked receptor","d":"离子通道偶联受体（ion channel-linked receptor）又称配体门控型离子通道，是具有离子通道功能的细胞膜受体，与G蛋白偶联受体、酶联受体并列为细胞膜受体介导信号转导的三条途径。它主要受神经递质等信号物质调节：递质与受体结合后使通道开放或关闭，改变膜对特定离子的通透性，离子沿各自浓度梯度流入或流出，从而把化学信号转换为电信号。离子流所携带的净电流若使突触后膜去极化，称兴奋性突触后电位，若引起超极化则称抑制性突触后电位。","src":"《第9章 2021细胞通讯和信号转导》p44、p45"},{"id":"b957f9f7","s":"c","g":"c09","n":"第一信使","e":"first messenger","d":"第一信使（first messenger）指细胞外的信号分子，即与受体特异性结合的配体，包括亲水分子、疏水分子和气体三类。它携带来自其他细胞或环境的信息，与靶细胞受体结合后触发胞内一系列信号事件，最终改变效应蛋白而调节细胞行为。相对于在细胞内生成并起作用的第二信使，第一信使是信号的源头；第二信使的生成受第一信使调节，多数在细胞膜上产生，可有效放大受体与信号分子结合所携带的信息，并且仅在细胞内部起作用。","src":"《第9章 2021细胞通讯和信号转导》p17；MBoC 7e 印刷 p879"},{"id":"34037e80","s":"c","g":"c09","n":"第二信使","e":"second messenger","d":"第二信使（second messenger）是细胞外信号作用于受体后在细胞内生成或释放的小分子信号物质，负责把信号在细胞内接力传递。其特点是：多数在细胞膜上生成，能有效放大受体与信号分子结合的信息，受第一信使调节，且仅在细胞内部起作用。主要成员有cAMP、cGMP、Ca2+、DAG、IP3与PIP3等；cAMP与Ca2+为水溶性，可在胞质中扩散，DAG为脂溶性，只在质膜的平面内扩散，其作用可被磷酸二酯酶等机制终止。","src":"《第9章 2021细胞通讯和信号转导》p17、p25、p39；MBoC 7e 印刷 p879"},{"id":"4db3abc3","s":"c","g":"c02","n":"简单扩散","e":"simple diffusion","d":"简单扩散（simple diffusion）是被动运输中最简单的方式：分子或离子顺电化学梯度跨膜，不需要消耗另外的能量，也不需要膜蛋白参与。其速率与被转运分子的浓度差成正比，并取决于分子的大小、脂溶性与电荷等性质，仅受膜总表面积的物理限制，因而与载体介导的转运不同，后者随浓度差增大而趋于饱和即Vmax。水虽可经简单扩散缓慢穿膜，但水的渗透仍服从自由能降低的方向，即从溶质浓度低的一侧流向溶质浓度高的一侧。","src":"《第3章 细胞膜与表面（上）》p59、p61；MBoC 7e 印刷 p641"},{"id":"604aee88","s":"c","g":"c02","n":"糖脂","e":"glycolipid","d":"糖脂（glycolipid）是含糖残基或寡糖链的脂质分子，在所有细胞膜表面都有发现，广泛存在于脂双层的外层，通常占膜外层脂质分子的5%。其不对称分布源于糖基是在高尔基体腔中添加的，当脂质被转运到细胞膜时糖基便暴露于细胞表面。糖脂的功能与其定位有关：在上皮细胞质膜中糖脂局限于暴露的顶面，可保护膜免受低pH、高浓度降解酶等严酷条件；带电荷的神经节苷脂可改变跨膜电场及膜表面离子浓度；它还参与细胞识别，如红细胞质膜上的鞘糖脂是ABO血型抗原。","src":"《第3章 细胞膜与表面（上）》p11、p27；MBoC 7e 印刷 p614"},{"id":"1f45c96c","s":"c","g":"c12","n":"线粒体","e":"mitochondrion","d":"线粒体（mitochondrion）是大小与细菌相近的膜性细胞器，由外膜、内膜、膜间隙和基质四部分组成。外膜含孔蛋白，通透性较高；内膜含80%蛋白质与20%脂类，通透性很低、具选择透性，向内褶入形成嵴以扩大面积，是电子传递链与氧化磷酸化的场所；基质中含三羧酸循环的酶系、mtDNA、RNA和核糖体。它执行氧化磷酸化，产生真核细胞的大部分ATP，同时参与凋亡与信号转导，故被称为细胞死亡信号整合器。","src":"《第7章细胞的能量代谢》p11；《第12章 细胞衰老与细胞凋亡》p61；MBoC 7e 印刷 p813","x":1},{"id":"27860f59","s":"c","g":"c11","n":"细胞决定","e":"","d":"细胞决定（cell determination）指个体发育过程中，细胞在出现可识别的分化特征之前就已确定未来发育命运、只能向特定方向分化的状态。它先于细胞分化并制约分化的方向：原肠期内、中、外三胚层形成时形态上虽无明显差异，但各器官的预定区已经确定。细胞决定可由胚胎移植实验证明，并表现出遗传稳定性，如果蝇成虫盘细胞经多次移植仍按原命运发育；其发生与卵的极性、早期胚胎细胞的不对称分裂，以及细胞所处位置的差异和细胞间相互作用有关。","src":"网络补充：zh.wikibooks.org／细胞生物学/细胞分化的基本概念"},{"id":"10b4f175","s":"c","g":"c11","n":"细胞分化","e":"cell differentiation","d":"细胞分化（cell differentiation）指多细胞生物个体发育中，一个或多个细胞在分裂增殖时，基因表达受到多种调控，从而在形态结构和生理功能上发生稳定性差异的过程，是发育的核心问题。分化的本质不是基因组序列的改变，而是不同基因群的开放与关闭，使细胞合成和积累不同的RNA与蛋白质，因此同一个体中不同类型细胞的DNA相同。分化伴随全能性逐渐丧失：受精卵、胚胎干细胞、组织特异干细胞直至终末分化细胞，这一序列也用于划分干细胞。","src":"《第11章 细胞分化与基因表达调控》p7、p32；MBoC 7e 印刷 p397","x":1},{"id":"0e5ec425","s":"c","g":"c02","n":"细胞膜","e":"cell membrane","d":"细胞膜（cell membrane）又称质膜，是细胞外围由脂质与膜蛋白通过非共价相互作用组成的疏水性薄层结构，把细胞与周围环境分隔开来，维持细胞的相对独立和胞内环境的稳定；真核细胞中细胞器的外围也有膜结构，二者统称生物膜。膜上脂质形成双分子层，是水溶性分子跨膜的屏障；膜蛋白种类很多，主要负责跨膜交换分子，维持并调节细胞与环境的物质交换、能量转换和信号传递。细胞膜具有不对称性、流动性和选择透过性，其结构模型有流动镶嵌模型与脂筏模型。","src":"《第3章 细胞膜与表面（上）》p3、p4、p30"},{"id":"a45dfac7","s":"c","g":"c09","n":"细胞通讯","e":"cell communication","d":"细胞通讯（cell communication）指细胞之间通过分泌信号分子或直接接触而相互实施调控。按距离可分为两类：短距离通讯即在一个局部范围内的信息交流，又分直接接触与非直接接触两种方式；长距离通讯则依靠内分泌激素信号以及长轴突神经元实现。信号分子与靶细胞受体结合后，经胞内信号转导引起第二信使含量升高、蛋白激酶或蛋白磷酸酶活性改变，最终改变效应蛋白的行为。植物与动物的细胞通讯机制各自独立演化，其受体与胞内信号机制存在差别。","src":"《第9章 2021细胞通讯和信号转导》p3；MBoC 7e 印刷 p940","x":1},{"id":"9b8e9844","s":"c","g":"c09","n":"肌醇三磷酸","e":"IP3","d":"1,4,5-三磷酸肌醇（IP3）是磷脂酶C水解4,5-二磷酸磷脂酰肌醇后生成的水溶性第二信使，与DAG共同构成双信使系统。IP3离开质膜、经胞质扩散到内质网，与内质网膜上的IP3受体结合；该受体是一个大的跨膜Ca2+通道，在无IP3时处于关闭状态，IP3结合引起构象改变、暴露出高亲和力的Ca2+结合位点，使Ca2+从内质网释放，胞质Ca2+浓度升高。升高的Ca2+可结合钙调蛋白等钙结合蛋白而影响其他蛋白，并常以正反馈方式引发Ca2+波。","src":"《第9章 2021细胞通讯和信号转导》p63、p65；MBoC 7e 印刷 p898"},{"id":"f68d2d74","s":"c","g":"c02","n":"胆固醇","e":"cholesterol","d":"胆固醇（cholesterol）是动物细胞质膜中含量特别多的一种脂质，具有特征性的四环甾体结构，由一个结构固定的环连接一个极性羟基和一条短的非极性碳氢链。它可固定周围磷脂分子起始部分碳氢链中少数亚甲基的运动，降低该区域脂双层中该部分的可变形性，减弱对小分子水溶性物质的通透性；它使脂质堆积更紧密，却并不降低膜脂流动性，在相变温度以上限制脂酰链末端运动、在相变温度以下则增强其运动。在脂筏中胆固醇像胶水一样，对含饱和脂肪酸链的鞘磷脂亲和力高。","src":"《第3章 细胞膜与表面（上）》p12、p32、p43；MBoC 7e 印刷 p605","x":1},{"id":"b1dd5ccb","s":"c","g":"c11","n":"胚胎干细胞","e":"ES cell","d":"胚胎干细胞（ES cell）是取自早期胚胎囊胚期内细胞群的干细胞，可在体外培养建系：人胚胎发育5至6天至囊胚期时取出内细胞团，分散后培养在经过处理、不能继续分裂的小鼠成纤维细胞滋养层上，随后传代培养。它具备分化成内胚层、中胚层、外胚层所有细胞类型的能力，但失去发育成完整个体的能力，故属多潜能（亚全能）干细胞；在适宜培养条件下可无限增殖并保持不受限制的发育潜能，其唯一限制是不能产生胎盘等胚外组织。","src":"《第11章 细胞分化与基因表达调控》p22、p60；MBoC 7e 印刷 p1302"},{"id":"7bb29288","s":"c","g":"c02","n":"脂筏","e":"lipid raft","d":"脂筏（lipid raft）是细胞膜上富含鞘脂与胆固醇的小型微区，其脂质处于有序液体状态，低温下能抵抗非离子去垢剂的抽提，故又称抗去垢剂膜。它像一个蛋白质停泊的平台，与膜的信号转导、蛋白质分选密切相关。筏中的胆固醇起胶水作用，对含饱和脂肪酸链的鞘磷脂亲和力很高；膜中的鞘磷脂主要位于外层，大部分参与形成脂筏。脂筏大小可以调节，小的独立脂筏有助于保持信号蛋白处于关闭状态，必要时聚集成大平台使信号分子与配件相遇而启动信号传递。","src":"《第3章 细胞膜与表面（上）》p31、p32；MBoC 7e 印刷 p634","x":1},{"id":"e4c1a6bd","s":"c","g":"c02","n":"脂筏模型","e":"lipid raft model","d":"脂筏模型（lipid raft model）认为膜上一些特殊的脂质能形成稍厚的微区，这种大小约70纳米的动态结构像筏子一样，带着大量膜蛋白以集中完成各种复杂功能。它是对流动镶嵌模型的补充：后者强调脂双层为骨架、蛋白质镶嵌或联结其上、膜两侧不对称且膜脂与膜蛋白具有流动性，而脂筏模型进一步指出膜在横向上也存在不均匀的微区组织。脂筏富集鞘脂、糖脂与胆固醇并招募特定蛋白，因而被认为具有信号分发与蛋白质分选的功能。","src":"《第3章 细胞膜与表面（上）》p31；《细胞生物学历年考题整理》p2","x":1},{"id":"284406cd","s":"c","g":"c02","n":"脂质双分子层","e":"lipid bilayer","d":"脂质双分子层（lipid bilayer）是磷脂分子排成的薄双片层，构成所有细胞膜的核心结构：两层脂质分子的疏水尾部相对朝内，亲水头部朝外与水接触。脂质分子的形状与双亲性使其在水溶液环境中自发形成双分子层——疏水碳氢链包埋于内部、亲水头部暴露于水，这是能量最低的排列方式，依脂质分子形状不同还可形成其他形状的聚集体。它构成生物膜的骨架，是水溶性分子跨膜的屏障；膜蛋白镶嵌或联结于其上，膜脂的流动性则赋予膜柔性。","src":"《第3章 细胞膜与表面（上）》p29；MBoC 7e 印刷 p609"},{"id":"44bed03b","s":"c","g":"c11","n":"脱分化","e":"dedifferentiation","d":"脱分化（dedifferentiation）指已分化的细胞失去其特有的结构与功能、变成未分化细胞的过程，是细胞可塑性的一种表现形式，与再分化、转分化并列。它可自然发生，也可人工诱导：高度分化的植物细胞在离体培养条件下可失去分化特性、恢复分裂能力并形成愈伤组织；动物体细胞部分去分化的例子较多，如蝾螈肢体再生时形成的胚芽细胞及各种肿瘤细胞，但体细胞通常难以完全去分化成全能性细胞。癌细胞在分化程度上低于正常细胞和良性肿瘤细胞，即表现为脱分化。","src":"《第11章 细胞分化与基因表达调控》p69；《第14章 癌细胞》p10","x":1},{"id":"bb1354cb","s":"c","g":"c09","n":"腺苷酸环化酶","e":"adenylyl cyclase (AC)","d":"腺苷酸环化酶（adenylyl cyclase, AC）是膜结合的酶，催化ATP生成环腺苷酸即cAMP，是G蛋白偶联受体信号通路的重要组分。在cAMP通路中，配体结合受体后经Gs或Gi蛋白激活或抑制腺苷酸环化酶，使cAMP在数秒内升高二十倍以上；cAMP随即被cAMP磷酸二酯酶迅速水解，从而及时终结第二信使的作用。cAMP再激活PKA，介导对代谢酶与基因转录的调节。腺苷酸环化酶是一个很大的膜蛋白，其活性受Gα亚基的直接调节。","src":"《第9章 2021细胞通讯和信号转导》p57、p58；MBoC 7e 印刷 p895"},{"id":"537a62dc","s":"c","g":"c16","n":"膜片钳技术","e":"patch clamp","d":"膜片钳（patch clamp）是可记录单个离子通道电流的电生理技术。其要点是：用尖端光洁、直径约0.5至2微米的玻璃微电极接触细胞膜而不刺入，在电极内施加适当负压，把电极尖端下的一小片膜轻轻吸入并与之形成高阻抗的紧密封接，电阻可达吉欧级，从而把该膜片与其余膜在电学上完全隔离；若膜片中只含一个或少数通道蛋白，测得的电流即为单个通道开放时离子跨膜移动的结果。据此可分析通道的电流幅值、开放概率与寿命，也可用于鉴定机械敏感通道。","src":"网络补充：function.sdu.edu.cn／膜片钳技术；tzyx.ntu.edu.cn／脑片膜片钳使用手册"},{"id":"39eb46ef","s":"c","g":"c16","n":"荧光共定位","e":"fluorescence colocalization","d":"荧光共定位（fluorescence colocalization）是在荧光显微成像基础上判断多种目标分子空间位置关系的方法，常用于蛋白质相互作用研究。做法是用发射波长不同的荧光探针分别标记待测分子，多通道成像后叠加图像，同一像素内同时出现两种信号即提示共定位。由于分辨率受衍射极限限制，共定位只表明两种蛋白处于同一亚细胞区域，不能证明直接结合，故常作为互作研究的初步判断，需与荧光共振能量转移等更近距离手段配合验证。","src":"网络补充：novel-optics.com（荧光共定位分析）；网络补充：scientialux.bio（Colocalization）"},{"id":"e02f9d2a","s":"c","g":"c02","n":"被动运输","e":"passive transport","d":"被动运输（passive transport）指分子或离子顺电化学梯度跨膜运输、不需消耗额外能量的过程，包括简单扩散和易化扩散；若顺梯度运输需膜蛋白帮助但不额外耗能，则称协助扩散（facilitated diffusion）。驱动力来自电化学梯度的自由能；加热、加压改变自由能即可改变物质流动方向，严格地说扩散是物质由自由能高处流向低处。由通道介导的跨膜运动总是被动的，核孔也允许直径9～10纳米、小于60 kD的物质被动扩散。","src":"《第3章 细胞膜与表面（上）》p59–p60；《第8章 细胞核与染色体》p11；MBoC 7e 印刷 p640"},{"id":"ba0ea12f","s":"c","g":"c11","n":"诱导多能干细胞","e":"iPSC (induced pluripotent stem cell)","d":"诱导多能干细胞（iPSC, induced pluripotent stem cell）指导入特定转录因子组合或小分子，使已分化体细胞失去特化状态、重获多能性的细胞。实验先确定14种候选重组基因，经系统排除后最终使用OCT3、SOX2、NANOG和LIN28；经典组合则为Oct4、Sox2、c-Myc与Klf4。所得细胞在形态、基因表达和分化能力上与胚胎干细胞相似，可分化为多种细胞，为疾病研究、药物筛选与再生医学提供无需胚胎的细胞来源。","src":"《第1章 细胞与细胞生物学》p56；《细胞生物学历年考题整理》p4","x":1},{"id":"169e4338","s":"c","g":"c12","n":"质体","e":"plastid","d":"质体（plastid）是植物细胞中一类由双层膜包被的细胞器，构成可相互转化的家族，包括前质体、叶绿体、有色体、白色体和黄化质体。与线粒体相似，质体由双层膜包围，并且不与连接大多数膜性细胞器彼此及与细胞外部的囊泡运输相通，因而其内部与胞质间的物质交换依赖自身的转运装置。内共生起源的推测得到现代原核生物与真核细胞器蛋白质转运机制高度相似的支持。叶绿体中的质体醌、质体蓝素等作为电子载体参与光合电子传递，把光能转化为ATP和NADPH。","src":"MBoC 7e 印刷 p688；《第7章细胞的能量代谢》p90、p92；《思维导图》p9"},{"id":"34cb45a9","s":"c","g":"c02","n":"跨膜蛋白","e":"transmembrane protein","d":"跨膜蛋白（transmembrane protein）是穿越脂双层、向胞外和胞内两侧伸展的膜蛋白，其部分质量分布在膜两侧，属整合膜蛋白。它具双亲性，疏水区穿过脂双层并与脂质疏水尾部作用，亲水区暴露于膜两侧溶液。跨膜段主要由非极性残基组成，多形成一个或多个α螺旋，使肽键间形成最多氢键；含20～30个高疏水性氨基酸的肽段即可跨膜。按跨膜次数分为单次与多次跨膜蛋白。因其嵌入脂双层，需去垢剂才能从膜上脱下；在内质网合成时即以此类疏水段插入膜中。","src":"《第3章 细胞膜与表面（上）》p21–p22；MBoC 7e 印刷 p709；MBoC 7e Glossary（PDF p1478）","x":1},{"id":"05d943a2","s":"c","g":"c02","n":"转位酶","e":"translocase (flippase)","d":"转位酶（translocase，flippase）又称磷脂转位酶，是催化磷脂在脂双层两小叶间翻转的膜蛋白。磷脂亲水头部穿过疏水区在能量上不利，自发翻转极慢，半衰期可达数天，而磷脂主要在内质网胞质侧合成，故需转位酶加速翻转以维持双层稳定。内质网的转位酶不需代谢能，可双向快速转运多数磷脂，使分布趋于对称；质膜上的氨基磷脂转位酶则水解ATP，把磷脂酰丝氨酸、磷脂酰乙醇胺向内翻，维持不对称。两小叶面积差还与膜弯曲及囊泡形成有关。","src":"网络补充：cell.com《The elusive flippases》；网络补充：baike.baidu.com（翻转酶）","x":1},{"id":"1d228eba","s":"c","g":"c11","n":"转分化","e":"transdifferentiation","d":"转分化（transdifferentiation）指一种类型的分化细胞转变成另一种类型分化细胞的现象，是更广义化生（metaplasia）的子集。它可经去分化与再分化两个过程实现，即先失去特有结构成为未分化状态再重新分化，也可直接转分化。实验上，导入Hnf1β与Foxa3等肝脏发育转录因子足以将小鼠胚胎成纤维细胞重编程为诱导性肝干细胞，后者可参与肝脏损伤修复；在小鼠心脏中强制表达相应因子，也可经心脏成纤维细胞的转分化再生丢失的心肌。","src":"《第11章 细胞分化与基因表达调控》p69–p71；MBoC 7e 印刷 p1308","x":1},{"id":"d5677b91","s":"c","g":"c02","n":"转运蛋白","e":"transporter","d":"转运蛋白（transporter）是膜上能与特定溶质结合的运输蛋白，通过可逆构象变化把溶质跨膜转运：结合位点先朝向膜一侧、再朝向另一侧，中间经溶质与两侧均不通的闭合状态。该过程类似酶与底物反应，有最大速率Vmax和亲和常数，可被竞争性或非竞争性抑制剂抑制，但不改变被运输分子。它既可顺梯度被动运输，也可偶联ATP水解等代谢能驱动主动运输；结合位点全部被占据时速率最大。ABC转运蛋白即借ATP结合与水解引起的二聚化、解聚循环转运小分子。","src":"《第3章 细胞膜与表面（上）》p56、p71；MBoC 7e 印刷 p641；MBoC 7e Glossary（PDF p1478）","x":1},{"id":"05fbbfd0","s":"c","g":"c02","n":"通道蛋白","e":"channel protein","d":"通道蛋白（channel protein）是形成跨膜亲水性孔道的膜蛋白，开放时允许特定溶质（通常为小无机离子）顺浓度梯度快速穿过脂双层，因主要运输钠、钾、钙、氯等离子，故称离子通道。与溶质结合能力很弱，速率比转运蛋白高4～8个数量级，一个开放通道每秒约通过1亿个离子；但通道不能主动运输，只能介导被动运输。开闭受门控调节，可为电压门控或配体门控。细胞还用水通道（aquaporin）提高水通透性，神经细胞借不同通道完成信号接收、传导与传递。","src":"《第3章 细胞膜与表面（上）》p56、p76；MBoC 7e 印刷 p639"},{"id":"0239e17b","s":"c","g":"c11","n":"造血干细胞","e":"hematopoietic stem cell","d":"造血干细胞（hematopoietic stem cell）是存在于骨髓中的多能成体干细胞，能逐级分化为循环系统三类血细胞：白细胞、红细胞和血小板，是各类免疫细胞的共同来源，骨髓因此被视为免疫细胞发源地。它属多能干细胞，可分化出多种细胞但不能构成完整个体。小鼠实验显示，骨髓细胞按表面抗原分选后输入受照射小鼠，能拯救受体者即含造血干细胞；此类细胞仅占骨髓约五万至十万分之一，但单个细胞注入造血缺陷宿主即可重建整个造血系统。","src":"《第13章 免疫系统的细胞》p11；《第11章 细胞分化与基因表达调控》p23–p24；MBoC 7e 印刷 p1287","x":1},{"id":"72d3801e","s":"c","g":"c16","n":"酵母人工染色体","e":"yeast artificial chromosome (YAC)","d":"酵母人工染色体（YAC，yeast artificial chromosome）是结构上模拟真正酵母染色体的线状DNA分子，带有天然染色体全部功能元件：一个DNA复制起点（自主复制序列，ARS）、一个着丝粒DNA序列（CEN）和两个端粒DNA序列（TEL）。因具备这三种元件，该线状DNA进入酵母后可像天然染色体一样自主复制、分裂时分配到子细胞并保持末端稳定，故可作为载体承载较大的外源DNA片段，是基因组研究中的人工染色体工具。","src":"《第8章 细胞核与染色体》p87","x":1},{"id":"d862b878","s":"c","g":"c16","n":"酵母双杂交","e":"yeast two-hybrid","d":"酵母双杂交（yeast two-hybrid）利用转录因子结构域可拆分重组的原理检测蛋白质互作。以GAL4为例，其DNA结合域识别报告基因上游激活序列，转录激活域启动转录，二者单独均无活性，只有空间上靠近才恢复转录因子功能。待测蛋白X与DNA结合域融合为“诱饵”，蛋白Y与激活域融合为“猎物”，若X与Y结合，两结构域靠近，启动lacZ等报告基因，通过显色或选择培养基筛出阳性克隆。该法可验证已知蛋白互作、从文库筛选互作蛋白并绘制互作网络。","src":"网络补充：genome.gov（Yeast Two-Hybrid）；网络补充：baike.baidu.com（酵母双杂合系统）"},{"id":"aceb2e38","s":"c","g":"c09","n":"酶联受体","e":"enzyme-linked receptor","d":"酶联受体（enzyme-linked receptor）是细胞膜受体的一类，为跨膜蛋白，特点是既是受体又是酶：一旦被配体激活即具有酶活性并放大信号，故又称催化受体。其胞内结构域常具某种蛋白质激酶活性，或本身无激酶活性而与另一种蛋白激酶分子相连，通过寡聚化与自磷酸化把信号向下游传递。按胞内域性质可分为受体酪氨酸激酶、酪氨酸激酶偶联受体、鸟苷酸环化酶受体和受体酪氨酸蛋白磷酸酶等，与离子通道偶联受体、G蛋白偶联受体并列为膜受体信号转导途径。","src":"《第9章 2021细胞通讯和信号转导》p43、p71–p72"},{"id":"5bda8344","s":"c","g":"c11","n":"重编程","e":"reprogramming","d":"重编程（reprogramming）指人为改变分化细胞的基因表达程序，使其回到多能状态或转变为其他细胞类型的过程。经典做法是导入Oct4、Sox2、Klf4等核心转录因子，把体细胞诱导为iPS细胞；核移植也可把人类皮肤细胞转化为能分化成各种组织的胚胎干细胞。这些因子既激活又抑制不同的靶基因，引发级联效应，在组蛋白修饰、DNA甲基化和染色质压缩等层次全局重组基因调控系统；完成后iPS细胞不再依赖外源因子，进入稳定、自我维持的表达状态。","src":"《第11章 细胞分化与基因表达调控》p79；MBoC 7e 印刷 p1305"},{"id":"53f23dd5","s":"c","g":"c09","n":"霍乱毒素","e":"cholera toxin","d":"霍乱毒素（cholera toxin）是霍乱弧菌分泌的毒性蛋白，是霍乱所特有的水样腹泻的致病因子。它由A、B两种亚基组成：B亚基与宿主细胞受体结合，把A亚基导向胞质；A亚基具酶活性，为ADP-核糖转移酶。进入细胞后，A亚基催化胞内NAD+上的ADP-核糖基共价结合到Gsα亚基，使Gsα丧失GTPase活性，被“锁定”在持续活化状态，不断激活腺苷酸环化酶，cAMP增加100倍以上，致使细胞大量Na+和水外流，产生严重腹泻而脱水。","src":"《第9章 2021细胞通讯和信号转导》p53；MBoC 7e 印刷 p1319；MBoC 7e Glossary（PDF p1449）"},{"id":"4fa5b422","s":"c","g":"c02","n":"静息电位","e":"resting potential","d":"静息电位（resting potential）指细胞未受刺激时膜内外两侧外正内负的电位差，神经与肌肉细胞内部比胞外低约50～100毫伏，典型值约-60毫伏。膜厚仅5纳米，该梯度可达每厘米十万伏特，膜蛋白处于巨大电场中。其主要成分由K+平衡机制产生，钾离子外流是形成基础，动力来自膜内外K+浓度差；Na+-K+泵每泵出3个Na+、泵入2个K+，具生电性但只作小的直接贡献。膜电位变化表现为去极化、复极化与超极化，并产生动作电位。","src":"《第3章 细胞膜与表面（上）》p82–p84；MBoC 7e 印刷 p657"},{"id":"c8f6500a","s":"c","g":"c12","n":"非循环电子传递链","e":"noncyclic electron transport chain","d":"非循环电子传递链（noncyclic electron transport chain）是光反应中电子沿载体单向传递的途径。电子由光系统Ⅱ出发：水裂解，释出电子、氢离子和氧；电子经质体醌（PQ）、细胞色素b6f复合体、质体蓝素（PC）传给光系统Ⅰ，后者受光激发经铁氧还蛋白（Fd）把电子交给NADP+还原酶，生成NADPH。该途径以水为供体、NADP+为最终受体，产物为NADPH、ATP和O2，同时把氢离子泵入类囊体腔，驱动ATP合成。","src":"网络补充：baike.baidu.com（非循环式电子传递途径）；网络补充：kepuchina.cn（光合作用）；《思维导图》p9"}]};
